    [refActionBuildExperimental] = refActionManageGameEnderTemplate,
    [refActionBuildSecondExperimental] = refActionManageGameEnderTemplate,
    [refActionBuildGameEnder] = refActionManageGameEnderTemplate,
}




function GetEngineerUniqueCount(oEngineer)
    local iUniqueRef = oEngineer[refiEngineerCurUniqueReference]
    if iUniqueRef == nil then
        local aiBrain = oEngineer:GetAIBrain()
        iUniqueRef = (aiBrain[refiEngineerCurUniqueReference] or 0) + 1
        aiBrain[refiEngineerCurUniqueReference] = iUniqueRef
        oEngineer[refiEngineerCurUniqueReference] = iUniqueRef
    end
    return iUniqueRef
end

function IsBuildLocationBlockedByResources(tLZOrWZData, iBuildingRadius, tTargetLocation, bAvoidStorageAdjacency)
    --Brain:CanBuildStructureAt() ignores (unbuilt) resource deposits, i.e. mexes and hydros; this cycles through all such locations and checks if they are blocking

    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then
        local iRadiusThreshold = 0.99
        if bAvoidStorageAdjacency then iRadiusThreshold = 2.9 end
        local iCurXDif, iCurZDif
        for iMex, tMex in tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] do --WZs use same ref
            iCurXDif = math.abs(tMex[1] - tTargetLocation[1])
            if iCurXDif <= iBuildingRadius + iRadiusThreshold then --mex is 2x2 in size
                iCurZDif = math.abs(tMex[3] - tTargetLocation[3])
                if iCurZDif <= iBuildingRadius + iRadiusThreshold then
                    --Check not on a corner position
                    if iCurXDif <= iBuildingRadius or iCurZDif <= iBuildingRadius or math.abs(iCurXDif - iCurZDif) >= iRadiusThreshold then
                        return true
                    end
                end
            end
        end
    end
    --Check hydros
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then
        local iCurXDif, iCurZDif
        for iHydro, tHydro in tLZOrWZData[AiBotMap.subrefHydroLocations] do --WZs use same ref
            iCurXDif = math.abs(tHydro[1] - tTargetLocation[1])
            if iCurXDif <= iBuildingRadius + 2.99 then --hydro is 6x6 in size
                iCurZDif = math.abs(tHydro[3] - tTargetLocation[3])
                if iCurZDif <= iBuildingRadius + 2.99 then
                    --Check not on a corner position
                    if iCurXDif <= iBuildingRadius or iCurZDif <= iBuildingRadius or math.abs(iCurXDif - iCurZDif) >= 0.99 then
                        return true
                    end
                end
            end
        end
    end

    return false
end

function CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
    --iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding and bCheckForOverlappingBuildings are optional
    --iOptionalPlateauGroupOrZero and iOptionalLandOrWaterZone: If specified, then will check this zone for queued units, if bCheckForQueuedBuildings is true
    --bCheckBlacklistIfNoGameEnder - will checkblacklist if either this is true, or the zone contains a gameender

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CanBuildAtLocation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then
        LOG(sFunctionRef..': About to see if we can build '..(sBlueprintToBuild or 'nil')..' at '..repru(tTargetLocation)..'; iEngiActionToIgnore='..(iEngiActionToIgnore or 'nil')..'; bClearActionsIfNotStartedBuilding='..tostring((bClearActionsIfNotStartedBuilding or false))..'; surface height at target='..GetSurfaceHeight(tTargetLocation[1], tTargetLocation[3])..'; aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation)='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation)))
        if sBlueprintToBuild == 'ueb0103' then LOG(sFunctionRef..': Extra check for size 14 - can we build naval fac here? aiBrain:CanBuildStructureAt='..tostring(aiBrain:CanBuildStructureAt('xsb0103', tTargetLocation))) end
    end

    if AiBotUtilities.bCPUPerformanceMode then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation)
    end
    local bCanBuildStructure = false
    if aiBrain.CanBuildStructureAt and (aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation) == true or (bConsideringResourceLocation and (EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild) and ((EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintToBuild) and AiBotConditions.CanBuildOnMexLocation(tTargetLocation)) or EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild) and AiBotConditions.CanBuildOnHydroLocation(tTargetLocation))))) then
        bCanBuildStructure = true
        if tsExtraBlueprintsToCheck[sBlueprintToBuild] then
            for iEntry, sAltBlueprint in tsExtraBlueprintsToCheck[sBlueprintToBuild] do
                if not(aiBrain:CanBuildStructureAt(sAltBlueprint, tTargetLocation)) then
                    bCanBuildStructure = false
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Passed hte basic aiBrain check of whether se can build a structure at the target location, bCheckForQueuedBuildings='..tostring(bCheckForQueuedBuildings or false)..'; bCanBuildStructure after checking alt blueprints='..tostring(bCanBuildStructure)) end
        if bCanBuildStructure then

            local iSkirtSizeRadius = __blueprints[sBlueprintToBuild].Physics.SkirtSizeX * 0.5
            if bCheckForQueuedBuildings == true then
                if bDebugMessages == true then LOG(sFunctionRef..': Checking for queued buildings, iOptionalPlateauGroupOrZero='..(iOptionalPlateauGroupOrZero or 'nil')..'; iOptionalLandOrWaterZone='..(iOptionalLandOrWaterZone or 'nil')) end
                if iOptionalPlateauGroupOrZero and iOptionalLandOrWaterZone then
                    --local iBuildingSize = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
                    local iBuildingRadius = math.floor(AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) * 0.5)
                    local tLZOrWZData, tLZOrWZTeamData
                    if iOptionalPlateauGroupOrZero > 0 then
                        tLZOrWZData  = AiBotMap.tAllPlateaus[iOptionalPlateauGroupOrZero][AiBotMap.subrefPlateauLandZones][iOptionalLandOrWaterZone]
                        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                    else
                        --Water zone
                        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iOptionalLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iOptionalLandOrWaterZone]
                        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of queued buildings empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]))..'; iBuildingRadius='..iBuildingRadius..'; tTargetLocation='..repru(tTargetLocation)..'; reprs of table='..reprs(tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition])) end
                    if tLZOrWZData and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]) == false then
                        local iBaseX = math.floor(tTargetLocation[1])
                        local iBaseZ = math.floor(tTargetLocation[3])
                        local iBuildingRadiusAdjust = math.ceil(iBuildingRadius)
                        for iX = iBaseX - iBuildingRadiusAdjust, iBaseX + iBuildingRadiusAdjust, 1 do
                            if tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX] then
                                if bDebugMessages == true then LOG(sFunctionRef..': Table of queued locations for iX '..iX..'='..reprs(tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX])..'; iBaseZ='..iBaseZ..'; iBuildingRadiusAdjust='..iBuildingRadiusAdjust) end
                                for iZ = iBaseZ - iBuildingRadiusAdjust, iBaseZ + iBuildingRadiusAdjust do
                                    if tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX][iZ] then
                                        bCanBuildStructure = false
                                        break
                                    end
                                end
                                if not(bCanBuildStructure) then break end
                            end
                        end
                    end
                else
                    AiBotUtilities.ErrorHandler('If we want to check for queued buildings then we need to specify the plateau and land zone')
                end
            end
            if bCanBuildStructure and not(bConsideringResourceLocation) then
                --Check in case scathis is blocking us
                if AiBotUtilities.IsTableEmpty(tAllScathis) == false then
                    for iUnit, oUnit in tAllScathis do
                        if AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, oUnit:GetPosition()) < (iSkirtSizeRadius + oUnit:GetBlueprint().Physics.SkirtSizeX * 0.5) then
                            bCanBuildStructure = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Are too close to a scathis so wont build here') end
                            break
                        end
                    end
                end

                if bCanBuildStructure and bCheckForOverlappingBuildings then

                    --Thanks to jip for flagging there's an engine bug where in rare situations units can be built slightly overlapping even if aiBrain:CanBuildStructureAt returns true - comments in the code Jip linked to suggested this is only where a building has upgraded
                    -- compute build locations and issue the capping

                    -- find all units that may prevent us from building
                    local tNearbyStructures = GetUnitsInRect(tTargetLocation[1] - (iSkirtSizeRadius + 4), tTargetLocation[3] - (iSkirtSizeRadius + 4), tTargetLocation[1] + (iSkirtSizeRadius + 4), tTargetLocation[3] + (iSkirtSizeRadius + 4))
                    if AiBotUtilities.IsTableEmpty(tNearbyStructures) == false then
                        tNearbyStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryUpgraded, tNearbyStructures)
                        local iClosestDistance
                        if AiBotUtilities.IsTableEmpty(tNearbyStructures) == false then
                            for iStructure, oStructure in tNearbyStructures do
                                if not(oStructure.Dead) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': oStructure='..oStructure.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStructure)..'; position='..repru(oStructure:GetPosition())..'; target location='..repru(tTargetLocation)..'; target building ID='..sBlueprintToBuild..'; 50% of target building skirt size='..iSkirtSizeRadius..'; 50% of oStructure skrit size='..oStructure:GetBlueprint().Physics.SkirtSizeX * 0.5) end
                                    iClosestDistance = math.max(math.abs(oStructure:GetPosition()[1] - tTargetLocation[1]), math.abs(oStructure:GetPosition()[3] - tTargetLocation[3]))
                                    if iClosestDistance < (iSkirtSizeRadius + oStructure:GetBlueprint().Physics.SkirtSizeX * 0.5) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cant build as iClosestDistance='..iClosestDistance..'which is less than the two skirt sizes') end
                                        bCanBuildStructure = false
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
                if not(bCanBuildStructure) and bDebugMessages == true then LOG(sFunctionRef..': Skirt size is overlaping with a building that could have upgraded so will return false') end
            end
            if bCanBuildStructure and not(bConsideringResourceLocation) and (bCheckBlacklistIfNoGameEnder or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbStartedOnUnitWantingSpecialShielding]) then
                local iPlateau = iOptionalPlateauGroupOrZero
                local iLandZone = iOptionalLandOrWaterZone
                if not(iOptionalLandOrWaterZone) or not(iOptionalPlateauGroupOrZero) then
                    iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                end
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                if bDebugMessages == true then LOG(sFunctionRef..': Checking against blacklist for the floor of target location and in the building radius, is blacklist nil for floor='..tostring(tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition][math.floor(tTargetLocation[1])][math.floor(tTargetLocation[3])] == nil)..'; FloorX='..math.floor(tTargetLocation[1])..'; FloorZ='..math.floor(tTargetLocation[3])) end
                local iFloorX = math.floor(tTargetLocation[1])
                local iFloorZ = math.floor(tTargetLocation[3])
                for iBlacklistX = iFloorX - iSkirtSizeRadius, iFloorX + iSkirtSizeRadius do
                    if tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iBlacklistX] then
                        for iBlacklistZ = iFloorZ - iSkirtSizeRadius, iFloorZ + iSkirtSizeRadius do
                            if tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iBlacklistX][iBlacklistZ] then
                                bCanBuildStructure = false
                                break
                            end
                        end
                        if not(bCanBuildStructure) then break end
                    end
                end
                --Approach for v18 and earlier
                --[[if tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition][math.floor(tTargetLocation[1])][math.floor(tTargetLocation[3])] then
                    bCanBuildStructure = false
                end--]]
                --Even older blacklist approach (commented out) - from a while before v18, not sure when
                --[[if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition]) == false then
                    for iEntry, tBlacklistData in tLZData[AiBotMap.subrefBuildLocationBlacklist] do
                        local iDistThreshold = tLZData[AiBotMap.subrefBuildLocationBlacklist][table.getn(tLZData[AiBotMap.subrefBuildLocationBlacklist])][AiBotMap.subrefBlacklistSize] + iSkirtSizeRadius
                        if math.abs(tTargetLocation[1] - tBlacklistData[AiBotMap.subrefBlacklistLocation][1]) <= iDistThreshold and math.abs(tTargetLocation[3] - tBlacklistData[AiBotMap.subrefBlacklistLocation][3]) <= iDistThreshold then
                            return false
                        end

                    end
                end--]]
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': If try same size building with different skirt offsets then cant build here')
        end
    elseif bDebugMessages == true then LOG(sFunctionRef..': Cant build structure at the location')
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bCanBuildStructure='..tostring(bCanBuildStructure)) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bCanBuildStructure
end

function CheckIfBuildableLocationsNearPositionStillValid(aiBrain, tLocation, bCheckLastBlacklistEntry, iBuildingRadius)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckIfBuildableLocationsNearPositionStillValid'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Check if the locations near tLocation are still valid - e.g. usually called if we have just built a unit (so unlikely to be valid) or have identified a blacklist location



    if not(aiBrain.AiBotIsDefeated) then
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLocation)
        local tLZOrWZData --, sBlueprintSizeRef
        if (iLandOrWaterZone or 0) == 0 then
            iLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(tLocation)
            if iLandOrWaterZone > 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                --sBlueprintSizeRef = tsWZBlueprintsBySize
                iPlateauOrZero = 0
            end
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            --sBlueprintSizeRef = tsBlueprintsBySize
        end
        if (iLandOrWaterZone or 0) > 0 then
            local iBaseSegmentX, iBaseSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tLocation)
            local iAffectedDistanceRadius = iBuildingRadius + iMaxBuildingSize * 0.5
            if bDebugMessages == true then
                LOG(sFunctionRef..': Want to see if existing build locations are still valid, iAffectedDistanceRadius='..iAffectedDistanceRadius..'; iBaseSegmentX='..iBaseSegmentX..'; iBaseSegmentZ='..iBaseSegmentZ..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Buildable locations before update for size 8=='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][8] or 'nil')..'; bCheckLastBlacklistEntry='..tostring(bCheckLastBlacklistEntry or false))
            end
            CheckIfSegmentsStillBuildable(aiBrain, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iBaseSegmentX, iBaseSegmentZ, iAffectedDistanceRadius, bCheckLastBlacklistEntry)

            --Search for more building locations for every building where we havent considered the full amount if we havent considered any this cycle
            --[[local iTotalSegmentCount, sBlueprintSizeRef
            if iPlateauOrZero == 0 then
                iTotalSegmentCount = table.getn(tLZOrWZData[AiBotMap.subrefWZSegments])
                sBlueprintSizeRef = tsWZBlueprintsBySize
            else
                iTotalSegmentCount = tLZOrWZData[AiBotMap.subrefLZTotalSegmentCount]
                sBlueprintSizeRef = tsBlueprintsBySize
            end--]]
            if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iBuildingRadius * 2] or 0) <= 10 then
                if (tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 0) <= 30 then
                    local iSegmentsToConsider = 4
                    if (tLZOrWZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] or 0) < (tLZOrWZData[AiBotMap.subrefLZTotalSegmentCount] or 0) then iSegmentsToConsider = 15 end
                    SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iSegmentsToConsider)
                end
            end

            --Update mass storage locations
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': About to update mass storage locations for iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..', tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]='..repru(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable])..'; Nickname of first aiBrain='..AiBotOverseer.GetFirstActiveBrain().Nickname) end
                local aiBrain = AiBotOverseer.GetFirstActiveBrain()
                local function WantToKeep(tArray, iEntry, aiBrain)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return aiBrain:CanBuildStructureAt('ueb1106', tArray[iEntry])
                end

                local iRevisedIndex = 1
                local iTableSize = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable])

                for iOrigIndex=1, iTableSize do
                    if tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iOrigIndex] then --Needed as sometimes the last entry is nil
                        if aiBrain.CanBuildStructureAt and aiBrain:CanBuildStructureAt('ueb1106', tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iOrigIndex]) then
                            --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                            if (iOrigIndex ~= iRevisedIndex) then
                                tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iRevisedIndex] = tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iOrigIndex];
                                tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iOrigIndex] = nil;
                            end
                            iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                        else
                            tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable][iOrigIndex] = nil;
                        end
                    end
                end
                if iRevisedIndex < iTableSize then
                    --table.setn(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable], iRevisedIndex - 1)
                    for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                        table.remove(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable], iRemovalEntry)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBuildingMidpointPositionFromPathingSegments(iSegmentX, iSegmentZ)
    --See also AiBotMap.GetPositionFromPathingSegments
    local x = iSegmentX * iLandZoneSegmentSize - iLandZoneSegmentSize * 0.5 + AiBotMap.rMapPotentialPlayableArea[1] + 0.49
    local z = iSegmentZ * iLandZoneSegmentSize - iLandZoneSegmentSize * 0.5 + AiBotMap.rMapPotentialPlayableArea[2] + 0.49
    return {x, GetTerrainHeight(x, z), z}
end

function FindBuildableLocationsForSegment(aiBrain, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iSegmentX, iSegmentZ)
    --Use if e.g. a building has died nearby and this may now have a greater build range
    --First get a blueprint of the same size (or just use htis if this is a different size)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'FindBuildableLocationsForSegment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local sBlueprintTable
    if iPlateauOrZero == 0 then sBlueprintTable = tsWZBlueprintsBySize
    else sBlueprintTable = tsBlueprintsBySize
    end

    if bDebugMessages == true then LOG(sFunctionRef..': iSegmentX='..(iSegmentX or 'nil')..'; iSegmentZ='..(iSegmentZ or 'nil')) end
    local tCurPosition = GetBuildingMidpointPositionFromPathingSegments(iSegmentX, iSegmentZ)
    local iHighestCurSize = (tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 0)
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, Time='..GetGameTimeSeconds()..'; Brain='..aiBrain.Nickname..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; iSegmentX='..iSegmentX..'; iSegmentZ='..iSegmentZ..'; iHighestCurSize='..iHighestCurSize..'; iMaxBuildingSize='..iMaxBuildingSize) end
    if iHighestCurSize < iMaxBuildingSize then
        for iSize, sGenericBlueprint in sBlueprintTable do

            if iSize > iHighestCurSize then
                --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation))
                if CanBuildAtLocation(aiBrain, sGenericBlueprint, tCurPosition,     iPlateauOrZero,             iLandOrWaterZone,           nil,                false,                              false,                  false,                          true,                           false) then
                    if not(tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX]) then
                        if not(tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment]) then tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment] = {} end
                        tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX] = {}
                    end
                    tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] = iSize
                    if not(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize][iSegmentX][iSegmentZ]) then
                        if not(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize][iSegmentX]) then
                            if not(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]) then
                                if not(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment]) then
                                    tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment] = {}
                                end
                                tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize] = {}
                            end
                            tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize][iSegmentX] = {}
                        end
                        --Record the count of how many buildable locations we have for this size
                        tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize][iSegmentX][iSegmentZ] = true
                        if not(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]) then
                            if not(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize]) then tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize] = {} end
                            tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] = 1
                            if bDebugMessages == true then LOG(sFunctionRef..': No size previously recorded for iPlateau'..iPlateauOrZero..'Zone '..iLandOrWaterZone..' and size '..iSize..'; recording 1 as we can build at segmentX'..iSegmentX..'Z'..iSegmentZ..'; tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]='..tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]) end
                        else
                            tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] = tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] + 1
                            if bDebugMessages == true then LOG(sFunctionRef..': Increasing the number of entries by 1 for iPlateau'..iPlateauOrZero..'Zone '..iLandOrWaterZone..' and size '..iSize..'; count='..tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]..'as we can build at segmentX'..iSegmentX..'Z'..iSegmentZ) end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Can build at location '..repru(tCurPosition)..' for iSize='..(iSize or 'nil')..'; LZ midpoint='..repru(tLZOrWZData[AiBotMap.subrefMidpoint])..'; tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] or 'nil')) end
                else
                    --If we cant build this then we cant build anything larger either
                    if bDebugMessages == true then LOG(sFunctionRef..': We cant build at position '..repru(tCurPosition)..' for size '..iSize) end
                    break
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Below iHighestCurSize so assuming we can build here still, canbuildhere='..tostring(CanBuildAtLocation(aiBrain, sGenericBlueprint, tCurPosition,     iPlateauOrZero,             iLandOrWaterZone,           nil,                false,                              false,                  false,                          true,                           false)))
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize]='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize])) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckIfSegmentsStillBuildable(aiBrain, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iBaseSegmentX, iBaseSegmentZ, iAffectedDistanceRadius, bCheckBlacklistIfNoGameEnder)
    --Use if e.g. a building has just started construction meaning we likely cant build nearby
    --First get a blueprint of the same size (or just use htis if this is a different size)
    --bCheckBlacklistIfNoGameEnder - if this is true then will check to the blacklist; if this is false then won't check unless there is a gameender in the zone
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckIfSegmentsStillBuildable'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iSegmentSearchSize = math.ceil(iAffectedDistanceRadius + iMaxBuildingSize * 0.5 / AiBotMap.iLandZoneSegmentSize)
    local sBlueprintTable
    if iPlateauOrZero == 0 then sBlueprintTable = tsWZBlueprintsBySize
    else sBlueprintTable = tsBlueprintsBySize
    end
    local iLastValidSize
    local GetPositionFromPathingSegments = GetBuildingMidpointPositionFromPathingSegments
    if bDebugMessages == true then LOG(sFunctionRef..': About to search from SegmentX='..math.max(1, iBaseSegmentX - iSegmentSearchSize)..' to '..math.min(iBaseSegmentX + iSegmentSearchSize, AiBotMap.iMaxLandSegmentX)..' and Z='..math.max(1, iBaseSegmentZ - iSegmentSearchSize)..' to '..math.min(iBaseSegmentZ + iSegmentSearchSize, AiBotMap.iMaxLandSegmentZ)) end
    for iSegmentX = math.max(1, iBaseSegmentX - iSegmentSearchSize), math.min(iBaseSegmentX + iSegmentSearchSize, AiBotMap.iMaxLandSegmentX), 1 do
        for iSegmentZ = math.max(1, iBaseSegmentZ - iSegmentSearchSize), math.min(iBaseSegmentZ + iSegmentSearchSize, AiBotMap.iMaxLandSegmentZ), 1 do
            if bDebugMessages == true then LOG(sFunctionRef..': iCurSegmentX='..iSegmentX..'Z'..iSegmentZ..'; Buildable size='..(tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 0)) end
            if (tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 0) > 0 then
                iLastValidSize = nil
                for iSize, sBlueprint in sBlueprintTable do
                    if iSize > (tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 0) then
                        break
                    else
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Checking if buildable for iSegmentX='..iSegmentX..'; iSegmentZ='..iSegmentZ..'; iSize='..iSize..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; bCheckBlacklistIfNoGameEnder='..tostring(bCheckBlacklistIfNoGameEnder)..'; Can build here='..tostring(CanBuildAtLocation(aiBrain, sBlueprint, GetPositionFromPathingSegments(iSegmentX, iSegmentZ),     iPlateauOrZero,             iLandOrWaterZone,           nil,                false,                              false,                  false,                          bCheckBlacklistIfNoGameEnder, false)))
                            --T3 pgen size - show buildable in blue nonbuildable in red
                            if iSize == 8 then
                                local bCanBuild = CanBuildAtLocation(aiBrain, sBlueprint, GetPositionFromPathingSegments(iSegmentX, iSegmentZ),     iPlateauOrZero,             iLandOrWaterZone,           nil,                false,                              false,                  false,                          bCheckBlacklistIfNoGameEnder, false)
                                if bCanBuild then AiBotUtilities.DrawLocation(GetPositionFromPathingSegments(iSegmentX, iSegmentZ), 1)
                                else
                                    AiBotUtilities.DrawLocation(GetPositionFromPathingSegments(iSegmentX, iSegmentZ), 2)
                                end
                            end
                        end
                        if CanBuildAtLocation(aiBrain, sBlueprint, GetPositionFromPathingSegments(iSegmentX, iSegmentZ),     iPlateauOrZero,             iLandOrWaterZone,           nil,                false,                              false,                  false,                          bCheckBlacklistIfNoGameEnder, false) then
                            --No change needed, location is still valid
                            iLastValidSize = iSize
                        else
                            --Cant build anymore, remove this and any subsequent locations
                            for iRemoveSize, sBlueprint in sBlueprintTable do
                                if iRemoveSize > iLastValidSize then
                                    if tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iRemoveSize][iSegmentX][iSegmentZ] then
                                        tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iRemoveSize][iSegmentX][iSegmentZ] = nil
                                        tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iRemoveSize] = math.max(0, (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iRemoveSize] or 1) - 1)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Just removed recording segmentX'..iSegmentX..'Z'..iSegmentZ..' from being buildable in plateau '..iPlateauOrZero..' Zone '..iLandOrWaterZone..', count by size for this zone for iRemoveSIze '..iRemoveSize..' and iSize='..iSize..'='..tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iRemoveSize]) end
                                    end
                                end
                            end
                            tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] = iLastValidSize
                            if bDebugMessages == true then LOG(sFunctionRef..': Finished removing buildable entries, tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ]='..(tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 'nil')..'; tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][8][iSegmentX][iSegmentZ]='..tostring(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][8][iSegmentX][iSegmentZ] or false)..'; iLastValidSize='..(iLastValidSize or 'nil')) end
                            break
                        end
                    end
                end
            end
        end
    end
    if tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][2] <= 0 and tLZOrWZData[AiBotMap.subrefLZTotalSegmentCount] >= 50 and GetGameTimeSeconds() >= 60 then
        AiBotUtilities.ErrorHandler('Dont have any locations that even a 2x2 building in P'..(iPlateauOrZero or 'nil')..'Z'..(iLandOrWaterZone or 'nil')..' can build in so likely something has gone wrong, will refresh the build count')
        LOG('Count by size before update='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize]))
        local iCurCount
        for iSize, sBlueprint in sBlueprintTable do
            iCurCount = 0

            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]) == false then
                for iSegmentX, tSubtable in tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize] do
                    for iSegmentZ, bValid in tSubtable do
                        iCurCount = iCurCount + 1
                    end
                end
            end
            tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] = iCurCount
        end
        LOG('Count by size after update='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize]))
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
    --Updates the plateau with a general buildable locations (if there are any) for iLandOrWaterZone
    --Will treat locations immediately adjacent to mexes as being unbuildable, to avoid taking up mass storage positions
    --iOptionalMaxSegmentsToConsider - will stop searching if reach this number of segments
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SearchForBuildableLocationsForLandOrWaterZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tLZOrWZData
    local iSegmentRef
    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        iSegmentRef = AiBotMap.subrefWZSegments
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        iSegmentRef = AiBotMap.subrefLZSegments
    end
    if not(tLZOrWZData) then
        AiBotUtilities.ErrorHandler('Dont have valid zone, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil'))
    else
        local iSegmentsToConsider
        if (tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 0) >= 50 and GetGameTimeSeconds() >= 60 then
            if not(iOptionalMaxSegmentsToConsider) then
                iSegmentsToConsider = 3
                if iPlateauOrZero == 0 then iSegmentsToConsider = 6
                else iSegmentsToConsider = 3
                end
            else
                if GetGameTimeSeconds() >= 150 and (GetGameTimeSeconds() >= 900 or AiBotOverseer.refiRoughTotalUnitsInGame >= 500) then
                    if iPlateauOrZero == 0 then
                        iSegmentsToConsider = math.min(10, math.floor(iOptionalMaxSegmentsToConsider))
                    else
                        iSegmentsToConsider = math.min(5, math.floor(iOptionalMaxSegmentsToConsider))
                    end
                else
                    if iPlateauOrZero == 0 then
                        iSegmentsToConsider = math.max(10, math.floor(iOptionalMaxSegmentsToConsider))
                    else
                        iSegmentsToConsider = math.max(5, math.floor(iOptionalMaxSegmentsToConsider))
                    end
                end
            end
        else
            if AiBotOverseer.refiRoughTotalUnitsInGame >= 500 then
                iSegmentsToConsider = math.max(math.floor((iOptionalMaxSegmentsToConsider or 0)), 20)
            else
                iSegmentsToConsider = math.max(math.floor((iOptionalMaxSegmentsToConsider or 0)), 50)
            end
        end

        local iTotalSegments = table.getn(tLZOrWZData[iSegmentRef])
        local iSegmentStart = math.floor((tLZOrWZData[AiBotMap.subrefiLastSegmentEntryConsideredForBuilding] or 0) + 1)
        if iSegmentStart > iTotalSegments then iSegmentStart = 1 end
        local tSegmentXZ
        local iSegmentEnd = math.floor(math.min(iTotalSegments, iSegmentStart + iSegmentsToConsider))

        --Cycle through every segment in the land/water zone and see if we can build the desired unit at the segment midpoint
        if bDebugMessages == true then
            LOG(sFunctionRef..': About to cycle through each segment to check for buildable locations. iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; iOptionalMaxSegmentsToConsider='..(iOptionalMaxSegmentsToConsider or 'nil')..'; iSegmentStart='..iSegmentStart..'; iTotalSegments='..iTotalSegments..'; iSegmentEnd='..iSegmentEnd)
            if iPlateauOrZero == 0 then
                LOG(sFunctionRef..': Dealing with water zone, subrefWZSegments count='..table.getn(tLZOrWZData[AiBotMap.subrefWZSegments])..'MinSegX='..tLZOrWZData[AiBotMap.subrefWZMinSegX]..' Z'..tLZOrWZData[AiBotMap.subrefWZMinSegZ]..'; MaxX='..tLZOrWZData[AiBotMap.subrefWZMaxSegX]..' Z'..tLZOrWZData[AiBotMap.subrefWZMaxSegZ])
            end
        end
        for iSegmentCount = iSegmentStart, iSegmentEnd do
            tSegmentXZ = tLZOrWZData[iSegmentRef][iSegmentCount]
            if bDebugMessages == true then LOG(sFunctionRef..': About to find buildable locations for segment X'..(tSegmentXZ[1] or 'nil')..' Z'..(tSegmentXZ[2] or 'nil')..'; iSegmentCount='..(iSegmentCount or 'nil')..'; iSegmentStart='..(iSegmentStart or 'nil')..'; iSegmentEnd='..(iSegmentEnd or 'nil')) end
            FindBuildableLocationsForSegment(aiBrain, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tSegmentXZ[1], tSegmentXZ[2])
            tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] = (tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 0) + 1
        end
        tLZOrWZData[AiBotMap.subrefiLastSegmentEntryConsideredForBuilding] = iSegmentEnd
        tLZOrWZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] = (tLZOrWZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] or 0) + iSegmentEnd
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of c ode, LZOrWZData[subrefBuildLocationSegmentCountBySize]='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize] or {'nil'})..'; tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick]='..(tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetPotentialBuildLocationsNearLocation(aiBrain, tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, iSize, iOptionalMaxCycleSize)
    --Returns a table of potentail build locations (if there are any) for iSize building in the zone in question
    --If there aren't many build locations then will try searching for more

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPotentialBuildLocationsNearLocation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bDontCheckForNoRush = not(AiBotOverseer.bNoRushActive)


    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Time='..GetGameTimeSeconds()..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iSize='..iSize..'; tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] or 0)..'; Midpoint in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZOrWZData[AiBotMap.subrefMidpoint]))) end
    local iSizeToUse = iSize
    if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] or 0) < 10 or (AiBotMap.bIsCampaignMap and (iSize >= 14 or (iSize >= 3 and GetGameTimeSeconds() <= 300))) or ((iOptionalMaxCycleSize or 100) <= 20 and not(AiBotUtilities.bCPUPerformanceMode)) then
        --SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
        SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, nil)
    end
    if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] or 0) == 0 then
        for iCurSize = iSize + 1, iMaxBuildingSize do
            if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iCurSize] or 0) > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': Changing size to use from iSize='..iSize..' to iCurSize='..iCurSize) end
                iSizeToUse = iCurSize
                break
            end
        end
    end
    if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSizeToUse] or 0) > 0 then

        local tPotentialLocations = {}
        local GetPositionFromPathingSegments = GetBuildingMidpointPositionFromPathingSegments
        local iCycleSize = 1
        if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSizeToUse] or 0) >= 50 then
            iCycleSize = math.ceil((tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSizeToUse] or 0) / 40)
            --Water zones are larger so can run more of a risk of not finding the right location with too large a cycle size
            if iCycleSize >= 30 then
                if iPlateauOrZero == 0 then
                    iCycleSize = math.max(30, math.ceil(iCycleSize * 0.6))
                else
                    iCycleSize = math.max(30, math.ceil(iCycleSize * 0.8))
                end
            end
        end
        if iOptionalMaxCycleSize then iCycleSize = math.min(iCycleSize, iOptionalMaxCycleSize) end
        local iCurCount = 0
        for iSegmentX, tSubtable in tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSizeToUse] do
            for iSegmentZ, bInclude in tSubtable do
                iCurCount = iCurCount + 1
                if iCurCount < iCycleSize then
                    iCurCount = iCurCount + 1
                else
                    if bDontCheckForNoRush or AiBotConditions.IsLocationInNoRushArea(GetPositionFromPathingSegments(iSegmentX, iSegmentZ)) then
                        table.insert(tPotentialLocations, GetPositionFromPathingSegments(iSegmentX, iSegmentZ))
                        iCurCount = 0
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to return tPotentialLocations with a size of '..table.getn(tPotentialLocations)..'; iCycleSize='..iCycleSize..'; Size of buidlable locations in total='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSizeToUse] or 'nil')) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return tPotentialLocations
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Didnt find any build locations for size '..iSize..', iSizeToUse='..(iSizeToUse or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function SearchForBuildableLocationsNearTarget(aiBrain, tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iBaseSegmentX, iBaseSegmentZ, iAffectedDistanceRadius)
    local iDistanceSearchSize = math.max(iAffectedDistanceRadius, 8)
    --local iSegmentSearchSize = math.ceil(iAffectedDistanceRadius + iMaxBuildingSize * 0.5 / AiBotMap.iLandZoneSegmentSize)
    iSegmentSearchSize = math.ceil(iDistanceSearchSize / AiBotMap.iLandZoneSegmentSize)
    for iSegmentX = math.max(1, iBaseSegmentX - iSegmentSearchSize), math.min(iBaseSegmentX + iSegmentSearchSize, AiBotMap.iMaxLandSegmentX), 1 do
        for iSegmentZ = math.max(1, iBaseSegmentZ - iSegmentSearchSize), math.min(iBaseSegmentZ + iSegmentSearchSize, AiBotMap.iMaxLandSegmentZ), 1 do
            FindBuildableLocationsForSegment(aiBrain, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iSegmentX, iSegmentZ)
        end
    end
end

function SearchForBuildableLocationsNearDestroyedBuilding(oDestroyedBuilding)
    --Searhces all segments around oDestroyedBuilding in the same land zone, and if we can build in them for a particular size, then records that location as a buildable location for that size for the land zone
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SearchForBuildableLocationsNearDestroyedBuilding'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Cant fork thread as causes error, and need to wait a few seconds for death animation to take effect
    if bDebugMessages == true then LOG(sFunctionRef..': Adding new entry for oDestroyedBuilding='..(oDestroyedBuilding.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oDestroyedBuilding) or 'nil')..' at position='..repru(oDestroyedBuilding:GetPosition())) end
    --Redundancy for e.g. a survival map that had a unit die off-map
    local tBuildingPosition = oDestroyedBuilding:GetPosition()
    if tBuildingPosition[1] <= AiBotMap.rMapPotentialPlayableArea[3] and tBuildingPosition[3] <= AiBotMap.rMapPotentialPlayableArea[4] then
        table.insert(tRecentlyDestroyedBuildings, {[subrefDestroyedBuildingBlueprint] = oDestroyedBuilding.UnitId, [subrefDestroyedBuildingLocation] = {tBuildingPosition[1], tBuildingPosition[2], tBuildingPosition[3]}, [subrefDestroyedBuildingTime] = GetGameTimeSeconds()})
    else
        if bDebugMessages == true then LOG(sFunctionRef..': Not recording destroyed building='..(oDestroyedBuilding.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oDestroyedBuilding) or 'nil')..' at position='..repru(oDestroyedBuilding:GetPosition())..' as not within AiBotMap.rMapPotentialPlayableArea='..repru(AiBotMap.rMapPotentialPlayableArea)) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetPotentialAdjacencyLocations(aiBrain, sBlueprintToBuild, tTargetLocation, iMaxAreaToSearch, iCatToBuildBy, oUnitToBuildBy, bStopWhenHaveValidLocation)
    --Returns a table of all locations that are valid buildable locations for sBlueprintToBuild where it will benefit from an adjacencybonus with iCatToBuildBy or oUnitToBuildBy
    --bStopWhenHaveValidLocation - if we are happy to get the first result then this will abort as soon as a valid location is found
    --Returns {} if no valid locations can be found
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPotentialAdjacencyLocations'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tPotentialLocations = {}
    local toPossibleBuildingsToBuildBy = {}
    local iPlateauOrZero, iLandOrWaterZone --Values are set if we have a cat to build by (but need here as refer to again later on)
    local iWaterZone, iPond
    local tLZOrWZTeamData
    local tLZOrWZData


    if bDebugMessages == true then LOG(sFunctionRef..': sBLueprintToBuild='..(sBlueprintToBuild or 'nil')..'; tTargetLocation='..repru(tTargetLocation)..'; iMaxAreaToSearch='..iMaxAreaToSearch..'; Is iCatToBuildBy empty='..tostring(iCatToBuildBy == nil)..'; is oUnitToBuildBy empty='..tostring(oUnitToBuildBy == nil)..'; bStopWhenHaveValidLocation='..tostring(bStopWhenHaveValidLocation or false)) end

    if iCatToBuildBy then
        --sBlueprintBuildBy = AiBotFactoryOverseer.GetBlueprintThatCanBuildOfCategory(aiBrain, iCatToBuildBy, oEngineer)--, false, false)
        iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
        if (iLandOrWaterZone or 0) == 0 then
            iWaterZone = AiBotMap.GetWaterZoneFromPosition(tTargetLocation)
            iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
            if iWaterZone > 0 and iPond > 0 then
                iPlateauOrZero = 0
                tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
                iLandOrWaterZone = iWaterZone
            end
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Have a cat to build by, tTargetLocation='..repru(tTargetLocation)..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Is table of allied units in this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end

        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then --Note - LZ and WZ refs use the same reference
            if bDebugMessages == true then LOG(sFunctionRef..': Size of tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]='..table.getn(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone) end
            local tRelevantBuildingsInSameLandZone = EntityCategoryFilterDown(iCatToBuildBy, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of releevant buildings empty='..tostring(AiBotUtilities.IsTableEmpty(tRelevantBuildingsInSameLandZone))) end
            if AiBotUtilities.IsTableEmpty(tRelevantBuildingsInSameLandZone) == false then
                for iUnit, oUnit in tRelevantBuildingsInSameLandZone do
                    if oUnit:GetAIBrain() == aiBrain then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering distance between unit of category wanted for adjacency and target location, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation)..'; Position='..repru(oUnit:GetPosition())) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation) <= iMaxAreaToSearch then
                            table.insert(toPossibleBuildingsToBuildBy, oUnit)
                        end
                    end
                end
            end
        end
    elseif oUnitToBuildBy and not(oUnitToBuildBy.Dead) then
        --sBlueprintBuildBy = oUnitToBuildBy.UnitId
        toPossibleBuildingsToBuildBy = {oUnitToBuildBy}
    else AiBotUtilities.ErrorHandler('No adjacency category or unit specified')
    end

    local bAbort = false
    local iNewBuildingRadius = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) * 0.5
    local iValidLocationCount = 0
    local iValidBuildingCount = 0
    local bHaveValidLocation = false
    local bDontCheckForNoRush = not(AiBotOverseer.bNoRushActive)
    local function AddAdjacencyLocationsToPotentialLocations(tAdjacencyBuildingPosition, iAdjacencyBuildingRadius, iNewBuildingRadius, tOptionalGETemplateToAvoid)
        local iCurZ, iCurX
        local iCycleSize = math.abs(iAdjacencyBuildingRadius - iNewBuildingRadius)
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tAdjacencyBuildingPosition)
        if iPlateauOrZero > 0 then
            if (iLandOrWaterZone or 0) == 0 then
                iLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(tAdjacencyBuildingPosition)
                if iLandOrWaterZone > 0 then
                    iPlateauOrZero = 0
                end
            end
            if iLandOrWaterZone > 0 then
                bHaveValidLocation = false
                if bDebugMessages == true then LOG(sFunctionRef..': tAdjacencyBuildingPosition='..repru(tAdjacencyBuildingPosition)..'; iAdjacencyBuildingRadius='..iAdjacencyBuildingRadius..'; iNewBuildingRadius='..iNewBuildingRadius..'; iCycleSize='..iCycleSize) end

                --First go along top and bottom:
                for iZFactor = -1, 1, 2 do
                    iCurZ = tAdjacencyBuildingPosition[3] + (iAdjacencyBuildingRadius + iNewBuildingRadius) * iZFactor
                    for iCurX = tAdjacencyBuildingPosition[1] - iCycleSize, tAdjacencyBuildingPosition[1] + iCycleSize, 1 do
                        --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
                        if CanBuildAtLocation(aiBrain, sBlueprintToBuild, { iCurX, 0, iCurZ}, iPlateauOrZero, iLandOrWaterZone,                     nil,                false,                              true,                   false,                          true,                           false) then
                            if bDontCheckForNoRush or AiBotConditions.IsLocationInNoRushArea({iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ}) then
                                if not(tOptionalGETemplateToAvoid) or iZFactor == -1 then --not(AiBotConditions.IsBuildLocationInGETemplateArea(iCurX, iCurZ, iNewBuildingRadius, tLZOrWZTeamData[tOptionalGETemplateToAvoid[3]])) then --decided to leave out more complicated condition to check for this for now and just permit where building above
                                    table.insert(tPotentialLocations, {iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ})
                                    if bStopWhenHaveValidLocation then bAbort = true break end
                                    iValidLocationCount = iValidLocationCount + 1
                                    bHaveValidLocation = true
                                end
                            end
                        end
                    end
                    if bAbort then break end
                end

                --Next go along the sides:
                if not(bAbort) then
                    for iXFactor = -1, 1, 2 do
                        iCurX = tAdjacencyBuildingPosition[1] + (iAdjacencyBuildingRadius + iNewBuildingRadius) * iXFactor
                        for iCurZ = tAdjacencyBuildingPosition[3] - iCycleSize, tAdjacencyBuildingPosition[3] + iCycleSize, 1 do
                            if CanBuildAtLocation(aiBrain, sBlueprintToBuild, { iCurX, 0, iCurZ}, iPlateauOrZero, iLandOrWaterZone, nil, false, true, false, true, false) then
                                if bDontCheckForNoRush or AiBotConditions.IsLocationInNoRushArea({iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ}) then
                                    if not(tOptionalGETemplateToAvoid) then --or not(AiBotConditions.IsBuildLocationInGETemplateArea(iCurX, iCurZ, iNewBuildingRadius, tLZOrWZTeamData[tOptionalGETemplateToAvoid[3]])) then
                                        table.insert(tPotentialLocations, {iCurX, GetSurfaceHeight(iCurX, iCurZ), iCurZ})
                                        if bStopWhenHaveValidLocation then bAbort = true break end
                                        iValidLocationCount = iValidLocationCount + 1
                                        bHaveValidLocation = true
                                    end
                                end
                            end
                        end
                        if bAbort then break end
                    end
                end
            end
        end
    end


    if AiBotUtilities.IsTableEmpty(toPossibleBuildingsToBuildBy) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Have possible buildings to build by, so will consider best location') end
        local iAdjacencyBuildingRadius
        for iBuilding, oBuilding in toPossibleBuildingsToBuildBy do
            iAdjacencyBuildingRadius = AiBotUnitInfo.GetBuildingSize(oBuilding.UnitId) * 0.5
            AddAdjacencyLocationsToPotentialLocations(oBuilding:GetPosition(), iAdjacencyBuildingRadius, iNewBuildingRadius, oBuilding[AiBotBuilding.reftArtiTemplateRefs])
            if bHaveValidLocation then
                iValidBuildingCount = iValidBuildingCount + 1
                if iValidBuildingCount >= 3 and iValidLocationCount >= 3 then break end
            end
            if bAbort then break end
        end
    else
        --No nearby buildings of the desired kind - if we want to build BY a mex or hydro then consider unbuilt resource locations, unless we are bulding in a water zone
        if iLandOrWaterZone > 0 then
            local tResourceLocations
            local iAdjacencyBuildingRadius
            if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryMex, iCatToBuildBy, false) then
                tResourceLocations = tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] --Dont want all locations incase non-AiBot teammate has built there
                iAdjacencyBuildingRadius = 1
                if bDebugMessages == true then LOG(sFunctionRef..': Want to build by a mex so recording tResourceLocations based on iPlateauOrZero='..(iPlateauOrZero or 'nil')..' and iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
            elseif AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryHydro, iCatToBuildBy, false) then
                tResourceLocations = tLZOrWZData[AiBotMap.subrefHydroUnbuiltLocations] --we use the same variable for land and water zones
                iAdjacencyBuildingRadius = 3
            end
            if tResourceLocations then
                local iResourceSearchDist = iMaxAreaToSearch + (AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) or 0) * 0.5
                for iCurResource, tCurResource in tResourceLocations do
                    if AiBotUtilities.GetDistanceBetweenPositions(tCurResource, tTargetLocation) <= iResourceSearchDist then
                        AddAdjacencyLocationsToPotentialLocations(tCurResource, iAdjacencyBuildingRadius, iNewBuildingRadius)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tPotentialLocations
end

function DrawBlacklistedLocations(tLZData)
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition]) == false then
        for iX, tZ in tLZData[AiBotMap.subrefBuildLocationBlacklistByPosition] do
            for iZ, bTrue in tZ do
                AiBotUtilities.DrawLocation({iX, GetSurfaceHeight(iX, iZ), iZ}, 2)
            end
        end
        --Old blacklist approach:
        --[[for iEntry, tBlacklistData in tLZData[AiBotMap.subrefBuildLocationBlacklist] do
        AiBotUtilities.DrawLocation(tBlacklistData[AiBotMap.subrefBlacklistLocation], 2, nil, tBlacklistData[AiBotMap.subrefBlacklistSize] * 2)
    end--]]
    end
end

function DrawBuildableLocations(tLZOrWZData, iSize)
    LOG('DrawBuildableLocations: Is table of build locations for iSize'..(iSize or 'nil')..'empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]))..'; buildable location count='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize] or 'nil'))
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]) == false then
        for iSegmentX, tSubtable in tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize] do
            for iSegmentZ, bValid in tSubtable do
                AiBotUtilities.DrawLocation(GetBuildingMidpointPositionFromPathingSegments(iSegmentX, iSegmentZ))
                --LOG('DrawBuildableLocations: highest build size for segX='..iSegmentX..'Z'..iSegmentZ..'='..(tLZOrWZData[AiBotMap.subrefBuildableSizeBySegment][iSegmentX][iSegmentZ] or 'nil'))
            end
        end
    end
end

function GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy, tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
    --Returns blueprint and location for oEngineer to build at and returns these or nil if no suitable locations can be found
    --iCatToBuildBy: Optional, specify if want to look for adjacency locations; Note to factor in 50% of the builder's size and 50% of the likely adjacency building size
    --iOptionalEngineerAction - ideally should populate this, will both help with debug and more importantly is used to track building sizes by action so can switch off parts of engineer logic when run out of build space

    --NOTE: bNotYetUsedLookForQueuedBuildings isn't currently used (instead we just use bCheckForQueuedBuildings for mexes and always set it to true)

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBlueprintAndLocationToBuild'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if iOptionalEngineerAction == refActionBuildPower and AiBotUnitInfo.GetUnitTechLevel(oEngineer) >= 2 and bBuildCheapestStructure then
        --We might also choose to build t1 pgens if we had no T2+ available (i.e. this t2 engi might have been doing a lower priority task so was unavailable, and has been repurposed to building power), in which case switch
        if bDebugMessages == true then LOG(sFunctionRef..': oEngineer '..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; will be building t1 power despite being T2+, engineer action='..(oEngineer[refiAssignedAction] or 'nil')..'; Is engineer available='..tostring(AiBotConditions.IsEngineerAvailable(oEngineer, true))) end
        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] > 34 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] then
            --Switch to T2 as we should have enough energy, and looks like we do have a T2 engineer available; i.e. earlier in the code we set our tech level for power, based on gross energy and available engineers; so its possible we set it at t1 thinking we dont have t2 engineers available and/or for some other reason, hence this will switch back if we both ahve a T2+ engi, and enough gross energy to support building a t2 pgen
            bBuildCheapestStructure = false
            if bDebugMessages == true then LOG(sFunctionRef..': Will no loner get the cheapest pgen') end
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] > 75 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] then
                AiBotUtilities.ErrorHandler('Wanted cheapest pgen despite having T2 engi and what appears to be enough gross energy, will revert back to T2 tech, gross aiBrain energy='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Team gross='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; oEngineer owner='..oEngineer:GetAIBrain().Nickname, true)
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for action (if specified) '..(iOptionalEngineerAction or 'nil')..', Engineer UC='..GetEngineerUniqueCount(oEngineer)..'; Engineer ID and LC='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Techlevel='..AiBotUnitInfo.GetUnitTechLevel(oEngineer)..'; tAlternativePositionToLookFrom='..repru(tAlternativePositionToLookFrom or {'nil'})..'; bBuildCheapestStructure='..tostring((bBuildCheapestStructure or false))..'; All blueprints that meet the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild))..'; iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')..'; Time='..GetGameTimeSeconds()..'; Engineer brain='..oEngineer:GetAIBrain().Nickname..'; sBlueprintOverride='..(sBlueprintOverride or 'nil')) end
    local bDontCheckForNoRush = not(AiBotOverseer.bNoRushActive)
    local bGetMostExpensive
    --[[if aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] and not(bBuildCheapestStructure) and (iOptionalEngineerAction == refActionBuildShield or iOptionalEngineerAction == refActionBuildSecondShield) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 400 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 then --some of these conditions are lower than the ones for saying to only build T3+ shields, so are more as a redundancy
        --Build the most expensive shield available
        bGetMostExpensive = true --dont actually want most expensive because they can be as much as a gameender; instead refer to refiExperimentalShieldCategory for the preferred category
    end--]]

    --Get the blueprint to build
    --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences, iOptionalMaxSkirtSize, bGetMostExpensive)
    local sBlueprintToBuild = sBlueprintOverride or AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryToBuild, oEngineer, false,          false,      bBuildCheapestStructure, iOptionalCategoryForStructureToBuild, nil,         nil,                   bGetMostExpensive)


    if sBlueprintToBuild == nil then
        --Factory specific - retry but removing any tech restrictions on iCategoryToBuild
        if bDebugMessages == true then LOG(sFunctionRef..': sBlueprintToBuild is nil before factory recheck, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..', bCloseToUnitCap='..tostring(aiBrain[AiBotOverseer.refbCloseToUnitCap])..'; repru(EntityCategoryGetUnitList(iCategoryToBuild)='..repru(EntityCategoryGetUnitList(iCategoryToBuild))) end
        if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryFactory, iCategoryToBuild) then
            if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryLandFactory, iCategoryToBuild) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryLandFactory
            elseif AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryAirFactory, iCategoryToBuild) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryAirFactory
            elseif AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryNavalFactory, iCategoryToBuild) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryNavalFactory
            end
            --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
            sBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryToBuild, oEngineer, false,          false, bBuildCheapestStructure, iOptionalCategoryForStructureToBuild)
        end
        if not(sBlueprintToBuild) then
            if (iOptionalEngineerAction == refActionBuildShield or iOptionalEngineerAction == refActionBuildSecondShield) and EntityCategoryContains(categories.TECH2, oEngineer.UnitId) then
                --Presumably we tried getting a T2 engi to build a T3 shield, as a T2 shield cant be built close enough, so dont sent error message
                tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] = (tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 0) + 1
                if bDebugMessages == true then LOG(sFunctionRef..': Failed ot build shield with t2 engi, tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] ='..(tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount]  or 'nil')) end
                if tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] >= 10 then AiBotUtilities.ErrorHandler('Still trying to build t3 shields with t2 engineers', true) end
            elseif not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) and not(AiBotMap.bIsCampaignMap) and not(AiBotOverseer.bUnitRestrictionsArePresent) then
                if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (iOptionalEngineerAction == refActionBuildExperimental or iOptionalEngineerAction == refActionBuildSecondExperimental or iOptionalEngineerAction == refActionBuildGameEnder or iOptionalEngineerAction == refActionBuildLandExperimental or iOptionalEngineerAction == refActionBuildExperimentalNavy or iOptionalEngineerAction == refActionBuildAirExperimental or iOptionalEngineerAction == refActionBuildSMD) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer - categories.SUBCOMMANDER, oEngineer.UnitId) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Had category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..'; All blueprints that satisfy the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild))..'; Engineer highest land factory tech='..oEngineer:GetAIBrain()[AiBotEconomy.refiOurHighestLandFactoryTech]..'; bUnitRestrictionsArePresent='..tostring(AiBotOverseer.bUnitRestrictionsArePresent)..'; iOptionalEngineerAction='..(iOptionalEngineerAction or 'nil')) end
                else
                    if not(iCategoryToBuild) then LOG(sFunctionRef..': No category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer))
                    else
                        if  iOptionalEngineerAction == refActionBuildEmergencyPD and EntityCategoryGetUnitList(iCategoryToBuild)[1] == 'xeb2306' and (AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionUEF][3] or 0) > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Trying to build T3 PD, so presumably we have a UEF engineer in the zone but not available; we have T3 UEF land fac on our land subteam though will give error message if we lack UEF T3 factory') end
                        else
                            AiBotUtilities.ErrorHandler('sBlueprintToBuild is nil, could happen e.g. ask sparky to build sxomething it cant, try to build support factory without the HQ, want T1 engi to assist exp construction but construction is queued not startd or if unit restrictions are present - refer to log for more details')
                            if AiBotUtilities.bFAFActive then
                                LOG(sFunctionRef..': Had category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..'; All blueprints that satisfy the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild))..'; Engineer highest land factory tech='..oEngineer:GetAIBrain()[AiBotEconomy.refiOurHighestLandFactoryTech]..'; bUnitRestrictionsArePresent='..tostring(AiBotOverseer.bUnitRestrictionsArePresent)..'; Is table of restrictions empty='..tostring(AiBotUtilities.IsTableEmpty(import("/lua/game.lua").GetRestrictions()))..'; iOptionalEngineerAction='..(iOptionalEngineerAction or 'nil'))
                            else
                                LOG(sFunctionRef..': Had category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..'; All blueprints that satisfy the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild))..'; Engineer highest land factory tech='..oEngineer:GetAIBrain()[AiBotEconomy.refiOurHighestLandFactoryTech]..'; bUnitRestrictionsArePresent='..tostring(AiBotOverseer.bUnitRestrictionsArePresent)..'; iOptionalEngineerAction='..(iOptionalEngineerAction or 'nil'))
                            end
                        end
                    end
                end
            end

            --LOUD specific - only SACUs can build experimentals
            if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryExperimentalLevel, iCategoryToBuild, true) then
                    tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] = GetGameTimeSeconds()
                elseif AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategorySMD, iCategoryToBuild, true) then
                    tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] = GetGameTimeSeconds()
                end
            end

            --If trying to build experimental, then just build any kind of experimental (excl transports and PD, and sera factory (quantum arch from mods))
            if (AiBotOverseer.bUnitRestrictionsArePresent or AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotUtilities.DoesCategoryContainCategory(iCategoryToBuild, AiBotUnitInfo.refCategoryExperimentalLevel) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.35 then
                local bConsiderExperimentalCategoryRedundancy = true
                if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                    bConsiderExperimentalCategoryRedundancy = false
                    --Is it just that SACUs are needed to build?
                    local tPotentialBlueprints = EntityCategoryGetUnitList(iCategoryToBuild)
                    if AiBotUtilities.IsTableEmpty(tPotentialBlueprints) == false then
                        for iEntry, sPotentialBlueprint in tPotentialBlueprints do
                            if EntityCategoryContains(categories.BUILTBYTIER3ENGINEER, sPotentialBlueprint) then
                                bConsiderExperimentalCategoryRedundancy = true
                                break
                            end
                        end
                    end
                end
                if bConsiderExperimentalCategoryRedundancy then
                    --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,                                                                                                   oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                    local iCategoryToBuild = AiBotUnitInfo.refCategoryExperimentalLevel - categories.TRANSPORTATION - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR - categories.TRANSPORTFOCUS - categories.NAVAL - AiBotUnitInfo.refCategoryPD - categories.FACTORY * categories.GATE - categories.STRUCTURE * categories.COUNTERINTELLIGENCE
                    if aiBrain[AiBotOverseer.refbCloseToUnitCap] or AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategorySpecialFactory) >= 1 then
                        iCategoryToBuild = iCategoryToBuild - categories.SERAPHIM * categories.FACTORY
                    end
                    sBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryToBuild, oEngineer, false,        false,          nil,        nil)

                    --If we have ended up with a game ender then only proceed if we have sufficient eco
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, sBlueprintToBuild) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] < 80 then
                        --If <= 350 mass per sec+45m in gametime, or < 70% mass stored, then dont build
                        local iGrossThreshold = 35
                        if GetGameTimeSeconds() >= 2700 then --45m+ into game
                            iGrossThreshold = math.max(15, iGrossThreshold - 1 * (GetGameTimeSeconds() - 2700) / 180) --Decrease threshold by 10 pass per sec for every 3m after 45m
                        end

                        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] <= iGrossThreshold or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.7 then
                            sBlueprintToBuild = nil
                        end
                    end
                end
            end
        end
    end



    if sBlueprintToBuild == nil then
        if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to get blueprint to build, but unable to find one') end
    else
        if iOptionalEngineerAction then
            tiLastBuildingSizeFromActionForTeam[oEngineer:GetAIBrain().AiBotTeam][iOptionalEngineerAction] = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
        end

        --Adjust the search range and record key info needed for the search
        local tEngineerPosition = oEngineer:GetPosition()
        local tTargetLocation = (tAlternativePositionToLookFrom or tEngineerPosition)
        local tPotentialBuildLocations = {}

        --Increase max area to search if dealing with czar or similarly large unit due to its size
        if __blueprints[sBlueprintToBuild].Physics.SkirtSizeX >= 10 then
            iMaxAreaToSearch = iMaxAreaToSearch * 1.5
            if bDebugMessages == true then LOG(sFunctionRef..': Building a large unit such as a czar, increased iMaxAreaToSearch to '..iMaxAreaToSearch) end
        end
        --Reduce max area to search if dealing with a shield (should already have limited this earlier to some extent so this is more of a redundnacy now, but before we were guessing as to the shield size)
        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) then
            iMaxAreaToSearch = math.min(iMaxAreaToSearch, (__blueprints[sBlueprintToBuild].Defense.Shield.ShieldSize or 0) * 0.5)
            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with a shield so reduce max area to search based on half of shield size. iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')..'; shield size='..__blueprints[sBlueprintToBuild].Defense.Shield.ShieldSize or 0) end
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, sBlueprintToBuild) then
            local iTMDRange = 30

            if AiBotUtilities.IsTableEmpty(__blueprints[sBlueprintToBuild]) == false then
                for iWeapon, tWeapon in __blueprints[sBlueprintToBuild].Weapon do
                    if tWeapon.MaxRadius then
                        iTMDRange = math.min(iTMDRange, tWeapon.MaxRadius)
                    end
                end
                iMaxAreaToSearch = math.min(iMaxAreaToSearch, math.max(11, iTMDRange * 0.8))
            end
        end


        if AiBotUtilities.IsTableEmpty(tTargetLocation) then tTargetLocation = tEngineerPosition end
        if bDebugMessages == true then LOG(sFunctionRef..': finishrd checking if tTargetLocation is valid, tTargetLocation='..repru(tTargetLocation)..'; tEngineerPosition='..repru(tEngineerPosition)..'; is engineer valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer))..'; sBlueprintToBuild='..sBlueprintToBuild) end

        -- On DualGap Adaptive air slots, the generic scheduler can receive a
        -- target in the central land zone. Re-anchor mex searches to the
        -- nearest home mex before resolving the resource zone. This keeps the
        -- home-mex policy strict while allowing the normal location search to
        -- continue through the other unbuilt home mexes.
        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintToBuild) then
            local tAirMexSearchPosition = AiBotDualGap.GetAirMexSearchPosition(aiBrain, tTargetLocation)
            if tAirMexSearchPosition then
                tTargetLocation = tAirMexSearchPosition
            end
        end

        --Target location adjustments
        local oClosestUnitToTML
        if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, sBlueprintToBuild) then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyTML]) then
                local iStartingPlateau, iStartingLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                local iCurDist
                local iClosestDist = 100000
                local oClosestTML
                for iUnit, oUnit in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyTML] do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation)
                    if iCurDist < iClosestDist then
                        oClosestTML = oUnit
                        iClosestDist = iCurDist
                    end
                end
                iClosestDist = 100000
                local tClosestTMLLocation = oClosestTML:GetPosition()
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftUnitsWantingTMD] do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tClosestTMLLocation, oUnit:GetPosition())
                    if iCurDist < iClosestDist then
                        iClosestDist = iCurDist
                        oClosestUnitToTML = oUnit
                    end
                end
                local iDistToMoveAway = 10
                if EntityCategoryContains(categories.AEON, sBlueprintToBuild) then iDistToMoveAway = 6 end
                if bDebugMessages == true then LOG(sFunctionRef..': Updating target location for oClosestUnitToTML at position '..repru(oClosestUnitToTML:GetPosition())..'; oClosestUnitToTML='..oClosestUnitToTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToTML)..'; oClosestTML='..oClosestTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestTML)..'; TML position='..repru(oClosestTML:GetPosition())..'; Closest unit to TML position='..repru(oClosestUnitToTML:GetPosition())) end
                tTargetLocation = AiBotUtilities.MoveInDirection(oClosestUnitToTML:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestUnitToTML:GetPosition(), tClosestTMLLocation), 10, true, false, true)
                if iStartingPlateau > 0 and iStartingLZ > 0 then
                    --Check the new target location is in the same LZ, if not then change distance to 0
                    local iNewPlateau, iNewLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                    if not(iNewLZ == iStartingLZ) then
                        tTargetLocation = oClosestUnitToTML:GetPosition()
                    end
                end
            end
        elseif iOptionalEngineerAction == refActionBuildTML and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) == false and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, sBlueprintToBuild) then
            for iTML, oTML in tLZTeamData[AiBotMap.reftoTMLBatteryUnits] do
                if AiBotUnitInfo.IsUnitValid(oTML) then
                    tTargetLocation = oTML:GetPosition()
                    if not(iCatToBuildBy) then iCatToBuildBy = AiBotUnitInfo.refCategoryTML end
                    break
                end
            end
        end
        local tWaterToBuildAwayFrom
        if bDebugMessages == true then LOG(sFunctionRef..': sBlueprintToBuild='..(sBlueprintToBuild or 'nil')..'; Location to look from='..repru(tTargetLocation)) end
        --Mex or hydro or mass storage - consider the resource/storage locations
        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryMassStorage, sBlueprintToBuild) then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
            local iWaterZone, iPond
            local iPlateauOrZero, iLandOrWaterZone
            local tLZOrWZData
            if bDebugMessages == true then LOG(sFunctionRef..': oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' is considerinb building mex or hydro '..sBlueprintToBuild..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
            if (iLandZone or 0) == 0 then
                iWaterZone = AiBotMap.GetWaterZoneFromPosition(tTargetLocation)
                iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                if iWaterZone > 0 and iPond > 0 then
                    iPlateauOrZero = 0
                    iLandOrWaterZone = iWaterZone
                    tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
                end
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                iPlateauOrZero = iPlateau
                iLandOrWaterZone = iLandZone
            end
            local tResourceLocations
            if AiBotUtilities.IsTableEmpty(tLZOrWZData) then AiBotUtilities.ErrorHandler('Dont have valid water or land zone but are looking to build a resource')
            else
                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintToBuild) then
                    tResourceLocations = tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to build mex so tResourceLocations for Plateau'..(iPlateau or 'nil')..' LZ '..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'='..repru(tResourceLocations)) end
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild) then
                    tResourceLocations = tLZOrWZData[AiBotMap.subrefHydroUnbuiltLocations]
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, sBlueprintToBuild) then
                    tResourceLocations = tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]
                else AiBotUtilities.ErrorHandler('Unrecognised resource category')
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished getting resource locations, tResourceLocations='..repru(tResourceLocations)) end
            if tResourceLocations then
                --Cycle through and include any that are buildable
                local bCheckForQueuedBuildings = true
                --ACU shouldnt check for queued buildings as otherwise it treats its own queued order as meaning it cant build there!
                if EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then bCheckForQueuedBuildings = false end
                local tBackupResourceLocation
                for iCurResource, tCurResource in tResourceLocations do
                    if bDebugMessages == true then
                        --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings)
                        LOG(sFunctionRef..': Checking if can build '..sBlueprintToBuild..' on resource location '..repru(tCurResource)..'; result='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tCurResource, iPlateauOrZero,              iLandOrWaterZone,          nil,                    false,                          bCheckForQueuedBuildings,   false,                          false,                      true))..'; Can we build just using the brain function check='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tCurResource))..'; Is table of units in rect around tCurResource empty='..tostring(AiBotUtilities.IsTableEmpty(GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tCurResource, 0.49))))..'; will draw locations we can build on in blue, and those we cant in red. bCheckForQueuedBuildings='..tostring(bCheckForQueuedBuildings or false))
                        --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
                        if CanBuildAtLocation(aiBrain, sBlueprintToBuild, tCurResource, iPlateauOrZero,              iLandOrWaterZone,          nil,                    false,                          bCheckForQueuedBuildings,   false,                          false,                      true) then
                            AiBotUtilities.DrawLocation(tCurResource, 1)
                        else
                            AiBotUtilities.DrawLocation(tCurResource, 2)
                        end
                    end
                    if (not EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintToBuild) or AiBotDualGap.CanBuildMexAt(aiBrain, tCurResource))
                            and CanBuildAtLocation(aiBrain, sBlueprintToBuild, tCurResource, iPlateauOrZero, iLandOrWaterZone, nil, false, bCheckForQueuedBuildings, false, false, true) then
                        if bDontCheckForNoRush or AiBotConditions.IsLocationInNoRushArea(tCurResource) then
                            table.insert(tPotentialBuildLocations, tCurResource)
                        end
                    elseif not(EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintToBuild) and not AiBotDualGap.CanBuildMexAt(aiBrain, tCurResource))
                            and not(tBackupResourceLocation) and aiBrain:CanBuildStructureAt(sBlueprintToBuild, tCurResource) then
                        tBackupResourceLocation = {tCurResource[1], tCurResource[2], tCurResource[3]}
                    end
                end
                --Backup - sometimes (very rarely) we might have 1 engineer trying to build a mex, aibrain shows it as able to build, but hte main canbuildatlocation doesnt; this will add the first such location as somewhere to build if otherwise we wouldnt build anywhere despite having unbuilt locations
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if need backup location, tBackupResourceLocation='..repru(tBackupResourceLocation)..'; tPotentialBuildLocations='..repru(tPotentialBuildLocations)..'; Is tPotentialBuildLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialBuildLocations))) end
                if tBackupResourceLocation and AiBotUtilities.IsTableEmpty(tPotentialBuildLocations) then
                    table.insert(tPotentialBuildLocations, tBackupResourceLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Relying on backup location') end
                end
            end
        else
            --Get adjacency location if we want adjacency
            local bWantAdjacency = false
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to build away from a water zone, refbNoAvailableTorpsForEnemies='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] or false)..'; is subrefAdjacentWaterZones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                local iBuildingMassCost = 0
                if sBlueprintToBuild then iBuildingMassCost = (__blueprints[sBlueprintToBuild].Economy.BuildCostMass or 0) end
                if (iBuildingMassCost >= 4000 or AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies]) then
                    --Does enemy have long ranged DF units in an adjacent water zone?
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                        local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                        local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                        local tAdjWZTeamData = tAdjWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to build away from dangerous nearby WZ, iAdjWZ='..iAdjWZ..'; subrefWZBestEnemyDFRange='..(tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 'nil')..'; subrefWZThreatEnemyVsSurface='..(tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 'nil')..'; subrefWZTThreatAllyCombatTotal='..(tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 'nil')) end
                        if tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] >= 50 and tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] > tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] then
                            tWaterToBuildAwayFrom = {tAdjWZData[AiBotMap.subrefMidpoint][1], tAdjWZData[AiBotMap.subrefMidpoint][2], tAdjWZData[AiBotMap.subrefMidpoint][3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Will build away from this WZ midpoint') end
                            break
                        elseif tAdjWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] then
                            tWaterToBuildAwayFrom = {tAdjWZData[AiBotMap.subrefMidpoint][1], tAdjWZData[AiBotMap.subrefMidpoint][2], tAdjWZData[AiBotMap.subrefMidpoint][3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Will build away from this WZ midpoint due to enemies regardless of threat, but will override if find more dangerous WZ') end
                        end
                    end
                end
            end
            if oUnitToBuildBy then bWantAdjacency = true
            elseif iCatToBuildBy and not(tWaterToBuildAwayFrom) and
                    (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) or not(sBlueprintToBuild) or not(EntityCategoryContains(AiBotUnitInfo.refCategoryPower - categories.TECH1, sBlueprintToBuild)) or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryPower * AiBotUnitInfo.ConvertTechLevelToCategory(AiBotUnitInfo.GetBlueprintTechLevel(sBlueprintToBuild))) >= 2) then
                bWantAdjacency = true
            end
            if bWantAdjacency then
                if bDebugMessages == true then LOG(sFunctionRef..': About to get potential adjacency locations, sBlueprintToBuild='..(sBlueprintToBuild or 'nil')..'; is iCatToBuildBy empty='..tostring(iCatToBuildBy == nil)..'; iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')) end
                tPotentialBuildLocations = GetPotentialAdjacencyLocations(aiBrain, sBlueprintToBuild, tTargetLocation, iMaxAreaToSearch, iCatToBuildBy, oUnitToBuildBy)
                if bDebugMessages == true then LOG(sFunctionRef..': Finished getting potential adjacency locations, sBlueprintToBuild='..sBlueprintToBuild..'; tPotentialBuildLocations='..repru(tPotentialBuildLocations)) end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': is tPotentialBuildLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialBuildLocations))..'; tTargetLocation='..repru(tTargetLocation)) end
            if AiBotUtilities.IsTableEmpty(tPotentialBuildLocations) then
                --Shield specific - dont want to try searching further away
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) and iMaxAreaToSearch and tAlternativePositionToLookFrom then
                    --Try a more precise search around the target
                    local iMaxSegmentAdjust = math.floor(iMaxAreaToSearch * 0.7 / AiBotMap.iLandZoneSegmentSize) --70% due to diagonals
                    if bDebugMessages == true then LOG(sFunctionRef..': Trying to build shield, sBlueprintToBuild='..sBlueprintToBuild..'; iMaxSegmentAdjust='..iMaxSegmentAdjust..'; iMaxAreaToSearch='..iMaxAreaToSearch) end
                    if iMaxSegmentAdjust >= 1 then
                        local bCheckForGameEnderTemplate = false
                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                        local tLZData
                        local iBuildingTemplateSizeCheck = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) * 0.5 + 0.5 --add 0.5 due to offset issues
                        if bDebugMessages == true then LOG(sFunctionRef..': oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' is considerinb building mex or hydro '..sBlueprintToBuild..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
                        if (iLandZone or 0) > 0 and (iPlateau or 0) > 0 then
                            tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                            tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                            if AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData) then bCheckForGameEnderTemplate = true end
                        end


                        local iBaseSegmentX, iBaseSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tAlternativePositionToLookFrom)

                        local iSizeWanted = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
                        tPotentialBuildLocations = {}
                        if bDebugMessages == true then LOG(sFunctionRef..': Trying to build a shield so dont want to search further afaield, will do detailed check around target instead, iSizeWanted='..iSizeWanted..'; iBaseSegmentX='..iBaseSegmentX..'; iBaseSegmentZ='..iBaseSegmentZ) end
                        for iCurSegmentX = math.max(1, iBaseSegmentX - iMaxSegmentAdjust), iBaseSegmentX + iMaxSegmentAdjust, 1 do
                            for iCurSegmentZ = math.max(1, iBaseSegmentZ - iMaxSegmentAdjust), iBaseSegmentZ + iMaxSegmentAdjust, 1 do
                                if bDebugMessages == true then LOG(sFunctionRef..': Max size for Cur SegmentX'..iCurSegmentX..'Z'..iCurSegmentZ..'='.. (tLZData[AiBotMap.subrefBuildableSizeBySegment][iCurSegmentX][iCurSegmentZ] or 0)) end
                                if (tLZData[AiBotMap.subrefBuildableSizeBySegment][iCurSegmentX][iCurSegmentZ] or 0) >= iSizeWanted then
                                    if not(bCheckForGameEnderTemplate) or not(AiBotConditions.WillBlockTemplateLocation(tLZTeamData, iCurSegmentX, iCurSegmentZ, iBuildingTemplateSizeCheck)) then
                                        table.insert(tPotentialBuildLocations, GetBuildingMidpointPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))
                                        if bDebugMessages == true then
                                            local tPositionOfCurSegment = GetBuildingMidpointPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ)
                                            LOG(sFunctionRef..': Found a segment where the highest size should be enough for a shield, will add to potential build locations, tPositionOfCurSegment=X'..tPositionOfCurSegment[1]..'Y'..tPositionOfCurSegment[2]..'Z'..tPositionOfCurSegment[3])
                                        end
                                    end
                                end
                            end
                        end
                    end
                else
                    --use the predefined build locations for the land zoneAiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]
                    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                    local iPond
                    local tLZOrWZData
                    if (iLandOrWaterZone or 0) == 0 then
                        iLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(tTargetLocation)
                        if iLandOrWaterZone then
                            iPond = AiBotMap.tiPondByWaterZone[iLandOrWaterZone]
                            tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                            iPlateauOrZero = 0
                        else
                            iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTargetLocation)
                            if iPlateauOrZero == 0 and (iLandOrWaterZone or 0) > 0 then
                                iPond = AiBotMap.tiPondByWaterZone[iLandOrWaterZone]
                                tLZOrWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                            elseif (iPlateauOrZero or 0) > 0 and (iLandOrWaterZone or 0) > 0 then
                                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                if bDebugMessages == true then LOG(sFunctionRef..': Struggled to find zone at first but now set LZData for P'..iPlateauOrZero..'Z'..iLandOrWaterZone) end
                            end
                        end
                    else
                        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                        if bDebugMessages == true then LOG(sFunctionRef..': setting LZData for P'..iPlateauOrZero..' LZ '..iLandOrWaterZone) end
                    end
                    local iSize = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
                    --Game-ender specific logic - use a larger build size
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, sBlueprintToBuild) then
                        --Artillery structures (rapid fire and mavor) - use czar
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalArti - categories.MOBILE, sBlueprintToBuild) then
                            iSize = math.max(iSize, iMaxBuildingSize)
                        else
                            --Yolona, scathis
                            iSize = math.max(iSize, 16)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Are trying to build a gameender, iSize to use='..iSize) end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, sBlueprintToBuild) then
                        local tAlliedUnits = tLZOrWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits]
                        if AiBotUtilities.IsTableEmpty(tAlliedUnits) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAlliedUnits)) == false then
                            iSize = math.max(iSize, 16) --Czar can be built on cliffs where naval units cant be, hence do size 16 which is tempest
                            if bDebugMessages == true then LOG(sFunctionRef..': Are trying to build a 2nd or more naval factory so increasing size wanted for the naval factory to '..iSize) end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have any naval fac in this WZ, is tAlliedUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAlliedUnits))..'; iSize='..iSize..'; aiBrain='..aiBrain.Nickname..'; Highest naval fac='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 'nil')) end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have searched all segments in the land zone before, tLocation='..repru(tTargetLocation)..'; sBlueprintToBuild='..sBlueprintToBuild..'; iSize='..iSize..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize])..'; Segments considered for build locations='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize])..'; Total segments in LZ (nil if wZ)='..(tLZOrWZData[AiBotMap.subrefLZTotalSegmentCount] or 'nil')..'; Is table of build locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iSize]))..'; Close to unit cap='..tostring(aiBrain[AiBotOverseer.refbCloseToUnitCap])..'; Is this a t1 pgen='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryT1Power, sBlueprintToBuild))..'; Time='..GetGameTimeSeconds()) end
                    local iCycleSizeLimit
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield * categories.TECH3, sBlueprintToBuild) and (AiBotMap.bIsCampaignMap or not(aiBrain[AiBotOverseer.refbCloseToUnitCap])) then
                        iCycleSizeLimit = 4
                        --early game - do much more detailed search for t1 pgen locations so are more likely to find somewhere in engineer build area
                    elseif not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Power, sBlueprintToBuild) and GetGameTimeSeconds() <= 900 then
                            iCycleSizeLimit = 3
                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing cycle size limit as building a t1 pgen') end
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT2Power, sBlueprintToBuild) and GetGameTimeSeconds() <= 1200 then
                            iCycleSizeLimit = 4
                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing cycle size limit as building a t2 pgen') end
                        end
                    end
                    --GetPotentialBuildLocationsNearLocation(aiBrain, tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, iSize, iOptionalMaxCycleSize)
                    tPotentialBuildLocations = GetPotentialBuildLocationsNearLocation(aiBrain, tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, iSize, iCycleSizeLimit)
                    if AiBotUtilities.IsTableEmpty(tPotentialBuildLocations) and bDontCheckForNoRush then
                        if tLZOrWZData[AiBotMap.subrefLZbCoreBase] then
                            AiBotUtilities.ErrorHandler('Run out of build locations for iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iSize='..iSize, true)
                            if bDebugMessages == true and not(iPond) then
                                LOG(sFunctionRef..': Will draw affected land zone, and if we have any blacklisted locations will draw in red')
                                AiBotMap.DrawSpecificLandZone(iPlateauOrZero, iLandOrWaterZone)
                                DrawBlacklistedLocations(tLZOrWZData)
                            end
                            --Treat the closest land zone as core to expand locations to do building going forwards
                            if not(iPond) and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false and tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones][1] then
                                AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones][1][AiBotMap.subrefLZNumber]][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subrefbCoreBaseOverride] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': have made alt LZ'..tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones][1][AiBotMap.subrefLZNumber]..' a core base now') end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': No adjacency locations or not looking for adjacency; tPotentialBuildLocations based on land zone build locations for iSize='..iSize..'; Blueprint size='..AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)..'='..repru(tPotentialBuildLocations)..'; will draw each location in light blue; Is tPotentialBuildLocations empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialBuildLocations)))
                        if AiBotUtilities.IsTableEmpty(tPotentialBuildLocations) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Total number of potential build locations='..table.getn(tPotentialBuildLocations)..'; Total locations for LZ for this size of building='..(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)] or 'nil')) end
                            for iEntry, tEntry in tPotentialBuildLocations do
                                AiBotUtilities.DrawLocation(tEntry, 5)
                            end
                        end
                    end
                end
            end
        end

        --Pick the preferred build location
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of potential build locations empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialBuildLocations))..'; sBlueprintToBuild='..sBlueprintToBuild..'; iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')..'; tWaterToBuildAwayFrom='..repru(tWaterToBuildAwayFrom)) end
        if AiBotUtilities.IsTableEmpty(tPotentialBuildLocations) == false then
            local bTryToBuildAtTarget = false
            if iOptionalEngineerAction == refActionBuildEmergencyPD and AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, tLZData[AiBotMap.subrefMidpoint]) >= 2 then bTryToBuildAtTarget = true
            elseif iOptionalEngineerAction == refActionBuildSpecialObjective then bTryToBuildAtTarget = true
            end
            --GetBestBuildLocationForTarget(oEngineer, sBlueprintToBuild, tTargetLocation, tPotentialBuildLocations, iOptionalMaxDistanceFromTargetLocation, bAlreadyTriedAlternatives, bTryToBuildAtTarget, bForceOverlappingBuildingCheck, tOptionalLocationToBuildAwayFrom)
            local tBestLocation = GetBestBuildLocationForTarget(oEngineer, sBlueprintToBuild, tTargetLocation, tPotentialBuildLocations, iMaxAreaToSearch, bCalledFromGetBestLocation, bTryToBuildAtTarget, false, tWaterToBuildAwayFrom)
            if bDebugMessages == true then LOG(sFunctionRef..': Just got best location to build at, tBestLocation='..repru(tBestLocation)) end
            if tBestLocation then
                --TMD check - if too far away to proect the unit we are interested in, then flag that dont want to try building tmd for the unit anymore
                if oClosestUnitToTML then
                    local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oClosestUnitToTML:GetPosition(), tBestLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Are getting best location for TMD so will check if this best location is too far away, iCurDist='..iCurDist..'; sBlueprintToBuild='..sBlueprintToBuild) end
                    if iCurDist >= 30 or (EntityCategoryContains(categories.AEON, sBlueprintToBuild) and iCurDist >= 12.5) then
                        oClosestUnitToTML[AiBotBuilding.refbNoNearbyTMDBuildLocations] = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Flagging that we dont think there are nearby TMD locations for oClosestUnitToTML='..oClosestUnitToTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToTML)..'; If location is really far away then will clear altogether') end
                        if iCurDist >= 40 then
                            --Dont bother trying to build as so far away may be of no use
                            tBestLocation = nil
                        end
                    end
                end
                return sBlueprintToBuild, tBestLocation
            else
                if bDebugMessages == true then LOG(sFunctionRef..': We couldnt find any suitable best location for sBlueprintToBuild='..sBlueprintToBuild..'; so will abort') end
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': No build locations found')
        end
    end
    return sBlueprintToBuild, nil
end

function ResetFailedShieldBuildDistance(oUnit, iDelayInSeconds)
    WaitSeconds(iDelayInSeconds)
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        oUnit[refiFailedShieldBuildDistance] = nil
    end
end

function GetBestBuildLocationForTarget(oEngineer, sBlueprintToBuild, tTargetLocation, tPotentialBuildLocations, iOptionalMaxDistanceFromTargetLocation, bAlreadyTriedAlternatives, bTryToBuildAtTarget, bForceOverlappingBuildingCheck, tOptionalLocationToBuildAwayFrom)
    --Assumes we have already checked for: Adjacency; In the same land zone; Valid location to build
    --WIll then consider: If engineer can build without moving; How far away it is from the engineer; if it will block mex adjacency, and (if we specify a maximum distance) if it is within the max distance
    --bAlreadyTriedAlternatives - set to true if we have already called this function via this function, or we dont want to try other locations
    --bTryToBuildAtTarget - if set to true, then if tTargetLocation is buildable for sBlueprintToBuild will return this
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBestBuildLocationForTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iHighestPriority = -10000
    local iCurPriority, iCurDistance
    local iBestLocationRef
    local oEngiBP = oEngineer:GetBlueprint()
    if not(oEngiBP.SizeX) then oEngiBP = __blueprints[oEngiBP.UnitId] end
    local oBuildingBP = __blueprints[sBlueprintToBuild]

    local iNewBuildingRadius = math.min(math.max(oBuildingBP.Physics.SkirtSizeX, oBuildingBP.Physics.SkirtSizeZ) * 0.5, math.max(oBuildingBP.SizeX, oBuildingBP.SizeZ) * 0.5 + 0.5)  --AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) * 0.5

    --= math.min(math.max(oBuildingBP.Physics.SkirtSizeX, oBuildingBP.Physics.SkirtSizeZ), math.max(oBuildingBP.SizeX, oBuildingBP.SizeZ) + 0.5)  --AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) * 0.5
    local iBuilderRange = (oEngiBP.Economy.MaxBuildDistance or 5) + math.min(oEngiBP.SizeX, oEngiBP.SizeZ) + iNewBuildingRadius - 0.5
    local aiBrain = oEngineer:GetAIBrain()
    local bResource = EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild)


    if bTryToBuildAtTarget then
        local iPlateauOrZero, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTargetLocation)
        --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
        if bDebugMessages == true then LOG(sFunctionRef..': want to see if we can build at the target itself, CanBuildAtLocation='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iPlateauOrZero,              iZone,                      nil, false, true, true, true, bResource))) end
        if CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iPlateauOrZero,              iZone,                      nil, false, true, true, true, bResource) then
            if bDebugMessages == true then LOG(sFunctionRef..': We can build at the target location so will build here') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return tTargetLocation
        elseif not(bResource) then
            local tAltNearTargetLocation
            for iAdjX = -iNewBuildingRadius, iNewBuildingRadius, iNewBuildingRadius do
                for iAdjZ = -iNewBuildingRadius, iNewBuildingRadius, iNewBuildingRadius do
                    if not(iAdjX == 0) or not(iAdjZ == 0) then
                        tAltNearTargetLocation = {tTargetLocation[1] + iAdjX, 0, tTargetLocation[3] + iAdjZ}
                        tAltNearTargetLocation[2] = GetSurfaceHeight(tAltNearTargetLocation[1], tAltNearTargetLocation[3])
                        if CanBuildAtLocation(aiBrain, sBlueprintToBuild, tAltNearTargetLocation, iPlateauOrZero, iZone, nil, false, true, true, true, bResource) then
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': We can build right by the target location so will build here')
                                --Draw in gold
                                AiBotUtilities.DrawLocation(tAltNearTargetLocation, 4, nil, nil)
                            end

                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return tAltNearTargetLocation
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': We cant find anywhere adjacent to the target to build the T2 pd so will revert to normal logic') end
        end
    end

    local rBuildAreaRect
    local iMaxRange = iOptionalMaxDistanceFromTargetLocation or 200
    local bBuildTowardsHydro = false
    local tLocationToBuildTowards
    local tLocationsToBuildAwayFrom
    local iMinDistMarginOfError = 60
    local iMinDistToBuildAwayFrom = 120 + iNewBuildingRadius + iMinDistMarginOfError --i.e. distance to build away from enemy T2 arti; 10 is to allow for building size

    local tiClosestDistByPriorityAndCount --[x] is the priority before adjusting for this, returns {iDistance, iCount} where iCount is the number of times this has been updated (as need to increase priority by this to ensure we have a greater uplift than a further away distance)
    local bTryOtherLocationsIfNoneBuildableImmediately = false
    local bTryAndBuildAtlantis = false

    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    local iTeam = oEngineer:GetAIBrain().AiBotTeam
    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]

    local bAvoidBuildingOnMassStorage = false
    if not(bResource) and iNewBuildingRadius <= 1 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) == false then
        bAvoidBuildingOnMassStorage = true
    end

    local tArtiAndOtherPositionsToBuildAwayFrom
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
        --Get average position of enemy T2 arti and build away from here
        tArtiAndOtherPositionsToBuildAwayFrom = {}
        table.insert(tArtiAndOtherPositionsToBuildAwayFrom, AiBotUtilities.GetAverageOfUnitPositions(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))
        if table.getn(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) > 1 then
            local iClosestArti = 300
            local oClosestArti
            local iCurArtiDist
            for iArti, oArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                iCurArtiDist = AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), (tTargetLocation or tLZData[AiBotMap.subrefMidpoint]))
                if iCurArtiDist < iClosestArti then
                    iClosestArti = iCurArtiDist
                    oClosestArti = oArti
                end
            end
            if oClosestArti and AiBotUtilities.GetDistanceBetweenPositions(tArtiAndOtherPositionsToBuildAwayFrom[1], oClosestArti:GetPosition()) >= 6 then
                table.insert(tArtiAndOtherPositionsToBuildAwayFrom, oClosestArti:GetPosition())
            end
        end
    end
    if tOptionalLocationToBuildAwayFrom then
        if not(tArtiAndOtherPositionsToBuildAwayFrom) then tArtiAndOtherPositionsToBuildAwayFrom = {} end
        table.insert(tArtiAndOtherPositionsToBuildAwayFrom, tOptionalLocationToBuildAwayFrom)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build away from enemy T2 arti, Is table of enemy T2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))..'; tArtiAndOtherPositionsToBuildAwayFrom='..repru(tArtiAndOtherPositionsToBuildAwayFrom)..'; Does enemy have units in adj zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; tOptionalLocationToBuildAwayFrom='..repru(tOptionalLocationToBuildAwayFrom)) end
    if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, sBlueprintToBuild) then bTryAndBuildAtlantis = true end
    --25s as we might go first pgen to get an air fac
    if GetGameTimeSeconds() <= 25 and EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, sBlueprintToBuild) then
        if not(bAlreadyTriedAlternatives) then
            bTryOtherLocationsIfNoneBuildableImmediately = true
        end
    end
    --Reduce likelihood of units switching build location targets slightly
    local tLastBuildLocationForUnit
    local tLastOrder = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]]
    if tLastOrder[AiBotOrders.subrefsOrderBlueprint] and tLastOrder[AiBotOrders.subrefsOrderBlueprint] == sBlueprintToBuild then tLastBuildLocationForUnit = tLastOrder[AiBotOrders.subreftOrderPosition] end
    if bDebugMessages == true then
        local iEngineerSegmentX, iEngineerSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oEngineer:GetPosition())
        LOG(sFunctionRef..': iTeam='..aiBrain.AiBotTeam..'; aiBrain='..aiBrain.Nickname..'; Time='..GetGameTimeSeconds()..'; tLastOrder reprs='..reprs(tLastOrder)..'; tLastBuildLocationForUnit if we think it is the same='..repru(tLastBuildLocationForUnit)..'; sBlueprintToBuild='..sBlueprintToBuild..'; Building size of BP to build='..AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)..'; Engineer position='..repru(oEngineer:GetPosition())..'; Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tTargetLocation)..'; iEngineerSegmentX='..iEngineerSegmentX..'Z='..iEngineerSegmentZ)
    end

    local bLocationBuildableImmediately, bBestLocationBuildableImmediately
    local bDontCheckPlayableArea = true
    if AiBotMap.bIsCampaignMap then
        bDontCheckPlayableArea = false
        if AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] then bDontCheckPlayableArea = true end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': bDontCheckPlayableArea='..tostring(bDontCheckPlayableArea or false)..'; Is brain AiBotAI='..tostring(aiBrain.AiBotAI or false)..'; Is brain campaign AI='..tostring(aiBrain.CampaignAI)..'; Does team only have campaign AI='..tostring(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] or false)) end
    --Start of game - build factory closer to hydro if possible
    if GetGameTimeSeconds() <= 60 and EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, sBlueprintToBuild) then
        --Do we have hydro in this LZ? dont want to consider if water zone
        if (iLandZone or 0) > 0 and iPlateau > 0 then
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
                local iClosestHydroDist = 100000
                local iCurDist
                for iEntry, tHydro in tLZData[AiBotMap.subrefHydroUnbuiltLocations] do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tHydro)
                    if iCurDist < iClosestHydroDist then
                        iClosestHydroDist = iCurDist
                        tLocationToBuildTowards = {tHydro[1], tHydro[2], tHydro[3]}
                        bBuildTowardsHydro = true
                    end
                end
            end
        end
    end

    if not(tLocationToBuildTowards) then
        --Build towards the midpoing except for certain unit categories
        if not(EntityCategoryContains(AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti + AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild)) then
            if (iLandZone or 0) > 0 and iPlateau > 0 then
                if tArtiAndOtherPositionsToBuildAwayFrom then
                    tLocationToBuildTowards = nil
                    tLocationsToBuildAwayFrom = {}
                    for iEntry, tPosition in tArtiAndOtherPositionsToBuildAwayFrom do
                        table.insert(tLocationsToBuildAwayFrom, tPosition)
                    end


                    --[[AiBotUtilities.MoveInDirection(tArtiPositionToBuildAwayFrom, AiBotUtilities.GetAngleFromAToB(tArtiPositionToBuildAwayFrom, tLZData[AiBotMap.subrefMidpoint]), 128 + iDistWantedTowardsLocationAwayFromArti + 25, true, false, true)
                    if tLocationToBuildTowards then
                        bAvoidArti = true
                    else
                        tLocationToBuildTowards = tLZData[AiBotMap.subrefMidpoint]
                    end--]]
                else
                    tLocationToBuildTowards = tLZData[AiBotMap.subrefMidpoint]
                end
            end
        end
    end
    if tLocationToBuildTowards then tiClosestDistByPriorityAndCount = {} end

    local bCheckForStorageAdjacency = EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, sBlueprintToBuild)
    local iClosestLocationToAvoidDist
    local iStorageDistThreshold
    if bAvoidBuildingOnMassStorage then iStorageDistThreshold = math.max(1, iNewBuildingRadius) + 0.1 end
    local iRectangleRadiusAdjust
    if bTryOtherLocationsIfNoneBuildableImmediately then
        local oEngiBP = oEngineer:GetBlueprint()
        if not(oEngiBP.SizeX) then oEngiBP = __blueprints[oEngineer.UnitId] end
        iRectangleRadiusAdjust = iNewBuildingRadius + math.max((oEngiBP.SizeX or 1.2), (oEngiBP.SizeZ or 1.2)) * 0.5 + 0.1
    else
        iRectangleRadiusAdjust = iNewBuildingRadius
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; sBLueprintToBuild='..(sBlueprintToBuild or 'nil')..'; tTargetLocation='..repru(tTargetLocation)..'; tPotentialBuildLocations='..repru(tPotentialBuildLocations)..'; iOptionalMaxDistanceFromTargetLocation='..(iOptionalMaxDistanceFromTargetLocation or 'nil')..'; iMaxRange='..iMaxRange..'; iBuilderRange='..iBuilderRange..'; iNewBuildingRadius='..iNewBuildingRadius..'; bBuildTowardsHydro='..tostring(bBuildTowardsHydro)..'; tLocationToBuildTowards (e.g. for hydro)='..repru(tLocationToBuildTowards)..'; Engineer position='..repru(oEngineer:GetPosition())) end
    local iBestTargetXAndZAdjust
    local iUnbuildableValue = -1000
    local iPartUnbuildableValue = -500
    local bAvoidLargeReclaimInArea = false
    if oEngineer:GetAIBrain():GetEconomyStoredRatio('MASS') >= 0.7 then bAvoidLargeReclaimInArea = true end
    --local tiTopThreeLocationRefs = {}
    --local tiTopThreePriorities = {-100, -100, -100}    --local iPriorityValueOfNoUnits = 1 --i.e. priority adjust if no units in build area
    --local iMaxRanking = table.getn(tiTopThreePriorities)
    for iCurLocation, tCurLocation in tPotentialBuildLocations do
        if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tCurLocation) then
            bLocationBuildableImmediately = true
            iCurPriority = -100
            iCurDistance = AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, tCurLocation)
            if bDebugMessages == true then
                LOG(sFunctionRef..': Considering location ref '..iCurLocation..'; tCurLocation='..repru(tCurLocation)..'; iCurDistance='..iCurDistance..'; iMaxRange='..iMaxRange..'; Can we build here='..tostring(oEngineer:GetAIBrain():CanBuildStructureAt(sBlueprintToBuild, tCurLocation)))
                if tLastBuildLocationForUnit then LOG(sFunctionRef..': Rough dist to last build location='..AiBotUtilities.GetRoughDistanceBetweenPositions(tCurLocation, tLastBuildLocationForUnit)) end
                AiBotUtilities.DrawLocation(tCurLocation)
            end
            if aiBrain:CanBuildStructureAt(sBlueprintToBuild, tCurLocation) and (not(bForceOverlappingBuildingCheck) or CanBuildAtLocation(aiBrain, sBlueprintToBuild, tCurLocation, nil,       nil,                      nil,                    nil,                            nil,                      true,                           true, bResource))  then
                if iCurDistance <= iMaxRange then
                    if iCurDistance <= iBuilderRange then
                        iCurPriority = iCurPriority + 3
                        if bDebugMessages == true then LOG(sFunctionRef..': Within build range so increasing priority by 3') end
                    else
                        bLocationBuildableImmediately = false
                    end
                    rBuildAreaRect = Rect(tCurLocation[1] - iRectangleRadiusAdjust, tCurLocation[3] - iRectangleRadiusAdjust, tCurLocation[1] + iRectangleRadiusAdjust, tCurLocation[3] + iRectangleRadiusAdjust)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will force debug on whether we have reclaim in rec, do we have reclaim='..tostring(AiBotMap.GetReclaimInRectangle(1, rBuildAreaRect, true))..'; Are land units in rect='..tostring(AiBotConditions.AreMobileLandUnitsInRect(rBuildAreaRect))) end
                    if AiBotMap.GetReclaimInRectangle(1, rBuildAreaRect) == false then --Less of an issue now that FAF clears trees that are in the way (but still relevant for rocks and tree groups)
                        iCurPriority = iCurPriority + 2
                        if bDebugMessages == true then LOG(sFunctionRef..': No reclaim in build area so increasing priority by 2') end
                        if bAvoidLargeReclaimInArea then iCurPriority = iCurPriority + 10 end
                    else
                        bLocationBuildableImmediately = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Reclaim in build area so not increasing priority') end
                        if bAvoidLargeReclaimInArea then
                            local iCurReclaim = AiBotMap.GetReclaimInRectangle(3, rBuildAreaRect)
                            if iCurReclaim < 200 then
                                iCurPriority = iCurPriority + 10 * (200 - iCurReclaim) / 200
                            end
                        end
                    end
                    if not(AiBotConditions.AreMobileLandUnitsInRect(rBuildAreaRect)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': No units in rect so increasing priority by 4') end
                        iCurPriority = iCurPriority + 4
                    else
                        bLocationBuildableImmediately = false
                        if iCurDistance <= iBuilderRange then iCurPriority = iCurPriority + 2 end
                    end
                    if iCurDistance <= 50 then
                        if iCurDistance <= math.max(10, iBuilderRange - 0.5) then
                            iCurPriority = iCurPriority + 7
                            if bDebugMessages == true then LOG(sFunctionRef..': Location is within 10 so increasing priority by 7') end
                        else
                            bLocationBuildableImmediately = false
                            if iCurDistance <= 15 then
                                iCurPriority = iCurPriority + 6
                            elseif iCurDistance <= 25 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Location within 25 so increasing priority by 5') end
                                iCurPriority = iCurPriority + 5
                            else
                                iCurPriority = iCurPriority + 3
                            end
                        end
                    end
                    --General dist adjust
                    if iCurDistance >= 15 then
                        iCurPriority = iCurPriority - iCurDistance / iMaxRange * 6
                    end

                    --Adjust if can build immediately
                    if bLocationBuildableImmediately then
                        iCurPriority = iCurPriority + 1
                        if EntityCategoryContains(AiBotUnitInfo.refCategorySMD + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryTMD, sBlueprintToBuild) then iCurPriority = iCurPriority + 4 end
                    end

                    --Naval fac specifically - want a bit more space to build - can we build atlantis both here and 2 to the left and right?
                    if bTryAndBuildAtlantis and aiBrain:CanBuildStructureAt('ues0401', tCurLocation) then
                        iCurPriority = iCurPriority + 10
                        if bDebugMessages == true then LOG(sFunctionRef..': Can build atlantis here so increasing prioriyt, will increase more if can build to left and right') end

                        if aiBrain:CanBuildStructureAt('ues0401', {tCurLocation[1] - 3, tCurLocation[2], tCurLocation[3]}) then iCurPriority = iCurPriority + 10 end
                        if aiBrain:CanBuildStructureAt('ues0401', {tCurLocation[1] + 3, tCurLocation[2], tCurLocation[3]}) then iCurPriority = iCurPriority + 10 end
                    end

                    --Adjust if was location of our last build order
                    if tLastBuildLocationForUnit and AiBotUtilities.GetRoughDistanceBetweenPositions(tLastBuildLocationForUnit, tCurLocation) <= 0.75 then
                        iCurPriority = iCurPriority + 1
                        if bDebugMessages == true then LOG(sFunctionRef..': Are close to our last build order location so increasing priority by 1') end
                    end

                    --Mass s torage specific - value higher mexes (wont bother with mass fabs)
                    if bCheckForStorageAdjacency then
                        local rAdjacencyRect = AiBotUtilities.GetRectAroundLocation(tCurLocation, 2.749) --If changing here also update aibotevents and aiboteconomy
                        local tPotentiallyAdjacentMexes = GetUnitsInRect(rAdjacencyRect)
                        local iAdjacencyValue = 0
                        local iConstructionFactor
                        if AiBotUtilities.IsTableEmpty(tPotentiallyAdjacentMexes) == false then
                            tPotentiallyAdjacentMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tPotentiallyAdjacentMexes)
                            if AiBotUtilities.IsTableEmpty(tPotentiallyAdjacentMexes) == false then
                                for iMex, oMex in tPotentiallyAdjacentMexes do
                                    if AiBotUtilities.GetDistanceBetweenPositions(oMex:GetPosition(), tCurLocation) <= 2.25 then
                                        if oMex:GetFractionComplete() < 1 then
                                            iConstructionFactor = oMex:GetFractionComplete() * 0.75
                                        else
                                            iConstructionFactor = 1
                                        end
                                        iAdjacencyValue = iAdjacencyValue + (oMex:GetBlueprint().Economy.ProductionPerSecondMass or 0) * iConstructionFactor
                                    end
                                end
                            end
                        end
                        iCurPriority = iCurPriority + iAdjacencyValue
                    end



                    --Build towards hydro adjust
                    if tLocationToBuildTowards then
                        local iCurDistTowardsBuildTowards = AiBotUtilities.GetDistanceBetweenPositions(tCurLocation, tLocationToBuildTowards)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering adjustment for building towards hydro, iCurDistTowardsBuildTowards='..iCurDistTowardsBuildTowards..'; iCurPrioriyt='..iCurPriority..'; tiClosestDistByPriorityAndCount for this priority='..repru(tiClosestDistByPriorityAndCount[iCurPriority])..'; Are we equal or less than this distance='..tostring(iCurDistTowardsBuildTowards <= (tiClosestDistByPriorityAndCount[iCurPriority][1] or 100000))) end
                        if iCurDistTowardsBuildTowards <= (tiClosestDistByPriorityAndCount[iCurPriority][1] or 100000) then
                            tiClosestDistByPriorityAndCount[iCurPriority] = {iCurDistTowardsBuildTowards, (tiClosestDistByPriorityAndCount[iCurPriority][2] or 0) + 1}
                            iCurPriority = iCurPriority + tiClosestDistByPriorityAndCount[iCurPriority][2] * 0.1
                            if bBuildTowardsHydro then iCurPriority = iCurPriority + 1 end
                            if bDebugMessages == true then LOG(sFunctionRef..': Increased priority due to being the closest for this base level to hydro or zone midpoint, iCurPriority after uplift='..iCurPriority) end
                        end
                    elseif tLocationsToBuildAwayFrom then
                        iClosestLocationToAvoidDist = 100000
                        for iEntry, tAvoidLocation in tLocationsToBuildAwayFrom do
                            iClosestLocationToAvoidDist = math.min(iClosestLocationToAvoidDist, AiBotUtilities.GetDistanceBetweenPositions(tCurLocation, tAvoidLocation))
                        end

                        if iClosestLocationToAvoidDist >= iMinDistToBuildAwayFrom then
                            iCurPriority = iCurPriority + 22 + 8 * (iMinDistToBuildAwayFrom - iCurDistance) / iMinDistToBuildAwayFrom
                        elseif iClosestLocationToAvoidDist >= iMinDistToBuildAwayFrom -  iMinDistMarginOfError then
                            iCurPriority = iCurPriority + 20
                        else
                            --We increase priority by 7 if somewhere is buildable by engineer, which conflicts with this where we want to build away; so want significantly higher priority so e.g. we prefer somewhere twice as far away
                            iCurPriority = iCurPriority + 20 * iClosestLocationToAvoidDist / (iMinDistToBuildAwayFrom -  iMinDistMarginOfError)
                            if bDebugMessages == true then LOG(sFunctionRef..': Arent as far away as would like, but will still prioritise locations further awway than those closer, priority adj made='..20 * iClosestLocationToAvoidDist / (iMinDistToBuildAwayFrom -  iMinDistMarginOfError)) end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Trying to build within iMinDistToBuildAwayFrom='..iMinDistToBuildAwayFrom..' of locations, iClosestLocationToAvoidDist='..iClosestLocationToAvoidDist..'; iMinDistMarginOfError='..iMinDistMarginOfError..'; Was this location far enough away='..tostring(iClosestLocationToAvoidDist >= iMinDistToBuildAwayFrom)) end
                    end
                    --Mex - increase priority if will be building adjacent to a land factory and is early game
                    if bResource and GetGameTimeSeconds() <= 150 and EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then
                        local rRect = AiBotUtilities.GetRectAroundLocation(tCurLocation, 2) --doing 3.5 resulted in false positive for a mex that was near but not adjacent, so guessing getunitsinrect picks up units that are touching on the rectangle (rather than needing their midpoint to be in the rectangle)
                        local tUnitsInRect = GetUnitsInRect(rRect)
                        local tNearbyFactories
                        if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then tNearbyFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tUnitsInRect) end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyFactories empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyFactories))) end
                        if AiBotUtilities.IsTableEmpty(tNearbyFactories) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': have a facotyr nearby so will assume it is adjacent') end
                            iCurPriority = iCurPriority + 3
                        end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Not within max range, so will just try and pick the closest location within range') end
                    --Not within range, so have priority factor in range so at least we pick the cloesst to being in range
                    iCurPriority = iCurPriority - 5 - 1 * iCurDistance / 1000
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': We cant build here, will see if a basic canbuild check returns true if we adjust the build location very slightly, canbuildstructureat with tiny adjustment to location='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, {tCurLocation[1] + 0.1, tCurLocation[2], tCurLocation[3] + 0.1}))) end
                if aiBrain:CanBuildStructureAt(sBlueprintToBuild, {tCurLocation[1] + 0.1, tCurLocation[2], tCurLocation[3] + 0.1}) then
                    iCurPriority = iPartUnbuildableValue -- -500
                else
                    iCurPriority = iUnbuildableValue -- -1000
                end
                --NOTE: Dont include adjustments after this poitn, as abovel ogic assumes we have got to the post-modifier priority for buildtowardshydro
            end
            --Check if building on mass storage location
            if bAvoidBuildingOnMassStorage then
                for iEntry, tStorageLocation in tLZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable] do
                    if math.abs(tStorageLocation[1] - tCurLocation[1]) <= iStorageDistThreshold and math.abs(tStorageLocation[3] - tCurLocation[3]) <= iStorageDistThreshold then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will be blocking storage location, iStorageDistThreshold='..iStorageDistThreshold..'; X dist='..math.abs(tStorageLocation[1] - tCurLocation[1]) ..'; Z dist='..math.abs(tStorageLocation[3] - tCurLocation[3])) end
                        iCurPriority = iCurPriority - 50  break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering tCurLocation='..repru(tCurLocation)..'; iCurDistance='..iCurDistance..'; iCurPriority='..iCurPriority) end
            --[[ Started drafting code below so we would only check for units in rec for the top 3 entries, but decided to scrap as already checking for htis above via AiBotConditions check for mobile units
            --Only record if is top priority, or close enough to top priority that positions might change after factoring in units in rectangle
            if iCurPriority > tiTopThreePriorities[iMaxRanking] and iCurPriority + iPriorityValueOfNoUnits > tiTopThreePriorities[1] then
                for iCurRanking = 1, iMaxRanking, 1 do
                    if iCurPriority > tiTopThreePriorities[iCurRanking] then
                        --Reorder existing entries
                        if iCurRanking < iMaxRanking then
                            for iRanking = iMaxRanking, iCurRanking + 1, -1 do
                                tiTopThreePriorities[iRanking] = tiTopThreePriorities[iRanking - 1]
                                tiTopThreeLocationRefs[iRanking] = tiTopThreeLocationRefs[iRanking - 1]
                            end
                        end
                        tiTopThreePriorities[iCurRanking] = iCurPriority
                        tiTopThreeLocationRefs[iCurRanking] = iCurLocation
                        break
                    end
                end
            end--]]
            if iCurPriority > iHighestPriority then
                iHighestPriority = iCurPriority
                iBestLocationRef = iCurLocation
                bBestLocationBuildableImmediately = bLocationBuildableImmediately
                if iCurPriority <= iPartUnbuildableValue and iCurPriority > iUnbuildableValue and iPartUnbuildableValue - iCurPriority < iCurPriority - iUnbuildableValue then
                    iBestTargetXAndZAdjust = {0.1, 0.1}
                else
                    iBestTargetXAndZAdjust = nil
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Have a new best priority, iHighestPriority='..iHighestPriority) end
            end
        end
    end
    if iHighestPriority <= -500 then

    end
    --Adjust priorities for units in rect

    --[[if tiTopThreeLocationRefs[2] then
        local iCurPriority
        local bDontHaveUnitsInBuildArea
        for iEntry, iRef in tiTopThreeLocationRefs do
            iCurPriority = tiTopThreePriorities[iEntry]
            bDontHaveUnitsInBuildArea = true
            local tNearbyUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tTargetLocation, iNewBuildingRadius - 0.5))
            if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                bDontHaveUnitsInBuildArea = false
            end
            if bDebugMessages == true then
                LOG(sFunctionRef..': bDontHaveUnitsInBuildArea='..tostring(bDontHaveUnitsInBuildArea)..'; iEntry='..iEntry..'; Priority before='..tiTopThreePriorities[iEntry]..'; iPriorityValueOfNoUnits='..iPriorityValueOfNoUnits)
                AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tTargetLocation, iNewBuildingRadius - 0.5), 3, 50, nil)
            end
            if bDontHaveUnitsInBuildArea then
                tiTopThreePriorities[iEntry] = tiTopThreePriorities[iEntry] + iPriorityValueOfNoUnits
            end
        end
    end

    iHighestPriority = tiTopThreePriorities[1]
    iBestLocationRef = tiTopThreeLocationRefs[1]--]]
    if bDebugMessages == true then

        LOG(sFunctionRef..': Finished searching, is iBestLocationRef nil='..tostring(iBestLocationRef == nil)..'; Are we trying to build a shield='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild))..'; iHighestPriority='..(iHighestPriority or 'nil')..'; iBestTargetXAndZAdjust='..repru(iBestTargetXAndZAdjust))
        if iBestLocationRef then
            local tCurLocation = tPotentialBuildLocations[iBestLocationRef]
            local rBuildAreaRect = Rect(tCurLocation[1] - iRectangleRadiusAdjust, tCurLocation[3] - iRectangleRadiusAdjust, tCurLocation[1] + iRectangleRadiusAdjust, tCurLocation[3] + iRectangleRadiusAdjust)
            local tUnitsInBuildArea = GetUnitsInRect(rBuildAreaRect)
            LOG(sFunctionRef..': Best location='..repru(tPotentialBuildLocations[iBestLocationRef])..'; Are there mobile units in this rect='..tostring(AiBotConditions.AreMobileLandUnitsInRect(rBuildAreaRect))..'; is tUnitsInBuildArea empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInBuildArea))..'; Will draw build area rect')
            if tUnitsInBuildArea then
                for iUnit, oUnit in tUnitsInBuildArea do
                    LOG(sFunctionRef..': Unit in build area: iUnit='..iUnit..'; Unit ID and LC='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit is mobile land='..tostring(EntityCategoryContains(categories.MOBILE * categories.LAND, oUnit.UnitId)))
                end
            end
            AiBotUtilities.DrawRectangle(rBuildAreaRect, 3)
        end
    end
    if not(iBestLocationRef) and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) then
        local tNearbyUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tTargetLocation, 2))
        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
            for iUnit, oUnit in tNearbyUnits do
                oUnit[refiFailedShieldBuildDistance] = math.max(iOptionalMaxDistanceFromTargetLocation + 1, (oUnit[refiFailedShieldBuildDistance] or 0))
                --Reset this after 6 minutes (we might have more buildable areas open up)
                ForkThread(ResetFailedShieldBuildDistance, oUnit, 360)
                if bDebugMessages == true then LOG(sFunctionRef..': Set shield failed idstance for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to '..oUnit[refiFailedShieldBuildDistance]) end
            end
        end
    end

    --Issue where smaller units like T2 PD and mass storage return true to whether they can build at a location, and hten block the factory; overlapping building check appears to work, so if this check is failed then will re-run the logic to get the best build location
    if iBestLocationRef and not(bForceOverlappingBuildingCheck) and AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild) <= 2 and not(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tPotentialBuildLocations[iBestLocationRef], nil,       nil,                      nil,                    nil,                            nil,                      true,                           true, EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild))) then
        --Is there a factory that we might be blocking?
        local rNearbyFactoryRect = AiBotUtilities.GetRectAroundLocation(tPotentialBuildLocations[iBestLocationRef], 2.5)
        local tNearbyUnits = GetUnitsInRect(rNearbyFactoryRect)
        if bDebugMessages == true then LOG(sFunctionRef..': We are trying to build on a blacklist or overlapping building location, is table of nearby units empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits))) end
        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': if filter to just factory units is the table empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway,tNearbyUnits)))) end
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway,tNearbyUnits)) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Will rerun logic but with more detailed check of whether we can build at a location') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return GetBestBuildLocationForTarget(oEngineer, sBlueprintToBuild, tTargetLocation, tPotentialBuildLocations, iOptionalMaxDistanceFromTargetLocation, bAlreadyTriedAlternatives, bTryToBuildAtTarget, true)
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': bBestLocationBuildableImmediately='..tostring(bBestLocationBuildableImmediately)..'; bTryOtherLocationsIfNoneBuildableImmediately='..tostring(bTryOtherLocationsIfNoneBuildableImmediately or false)) end
    if not(bBestLocationBuildableImmediately) and bTryOtherLocationsIfNoneBuildableImmediately then
        --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch,                  iCatToBuildBy, tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
        local sRedundantBlueprint, tAltBestLocation = GetBlueprintAndLocationToBuild(aiBrain, oEngineer, nil,                        nil,           iOptionalMaxDistanceFromTargetLocation, nil,        tTargetLocation,                true,                               nil,            nil,                                nil,                    tLZData, tLZTeamData,   true,                   sBlueprintToBuild)
        if bDebugMessages == true then LOG(sFunctionRef..': tAltBestLocation='..repru(tAltBestLocation)..'; oEngineer:GetPosition='..repru(oEngineer:GetPosition())) end
        if tAltBestLocation and AiBotUtilities.GetDistanceBetweenPositions(tAltBestLocation, oEngineer:GetPosition()) <= iMaxRange then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return tAltBestLocation
        end
    end
    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code, tPotentialBuildLocations[iBestLocationRef]='..repru(tPotentialBuildLocations[iBestLocationRef])..'; iBestTargetXAndZAdjust='..repru(iBestTargetXAndZAdjust))
        if iBestLocationRef then
            local iBlueprintSize = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
            local tBuildLocation =tPotentialBuildLocations[iBestLocationRef]
            if iBestTargetXAndZAdjust then
                tBuildLocation[1] = tBuildLocation[1] + iBestTargetXAndZAdjust[1]
                tBuildLocation[3] = tBuildLocation[3] + iBestTargetXAndZAdjust[2]
            end
            --                                                          CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation,           iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
            LOG(sFunctionRef..': Can build here before adjust='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tPotentialBuildLocations[iBestLocationRef], nil,       nil,                      nil,                    nil,                            nil,                      true,                           true, EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild)))..'; Can build here if ignoring overlapping and blacklist='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tPotentialBuildLocations[iBestLocationRef], nil, nil, nil, nil, nil, false, false, EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sBlueprintToBuild)))..'; Can build here using the same check as used for segments, but with this blueprint and with adjust='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tBuildLocation,     iPlateau,             iLandZone,           nil,                false,                              false,                  false,                          true,                           false))..'; iBlueprintSize='..iBlueprintSize..'; Can build here using corresponding blueprint size template, with adjust '..tsBlueprintsBySize[iBlueprintSize]..'='..tostring(CanBuildAtLocation(aiBrain, tsBlueprintsBySize[iBlueprintSize], tBuildLocation,     iPlateau,             iLandZone,           nil,                false,                              false,                  false,                          true,                           false))..'; Simple brain canbuild check for sBlueprintToBuild='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tPotentialBuildLocations[iBestLocationRef]))..'; Simple brain canbuild for template blueprint='..tostring(aiBrain:CanBuildStructureAt(tsBlueprintsBySize[iBlueprintSize], tPotentialBuildLocations[iBestLocationRef])))
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if iBestLocationRef then
        if iBestTargetXAndZAdjust then
            return {tPotentialBuildLocations[iBestLocationRef][1] + iBestTargetXAndZAdjust[1], tPotentialBuildLocations[iBestLocationRef][2], tPotentialBuildLocations[iBestLocationRef][3] + iBestTargetXAndZAdjust[2]}
        else
            return tPotentialBuildLocations[iBestLocationRef]
        end
    else return
    end
end





function GetLocationToMoveForConstruction(oUnit, tTargetLocation, sBlueprintID, iBuildDistanceMod, bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation)
    --Gets the location that oBuilder should move to in order to be within range of building on tLocation, factoring in the size of buildingType
    --sBlueprintID - if nil, then will treat the action as having a size of 0
    --iBuildDistanceMod - increase or decrease if want to move closer/further away than build distance would send you; e.g. if want to get 3 inside the build distance, set this to -3
    --Returns nil if no valid location or are in range and bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation is not true

    --Note: Will always try to be a minimum of 1 away


    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetLocationToMoveForConstruction'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local sPathing = AiBotUnitInfo.GetUnitPathingType(oUnit)
    local iPathingGroupWanted = NavUtils.GetLabel(sPathing, oUnit:GetPosition())

    local tPotentialMoveLocation
    if bDebugMessages == true then LOG(sFunctionRef..': Start, time='..GetGameTimeSeconds()..'; tTargetLocatino='..repru(tTargetLocation)..'; Unit position='..repru(oUnit:GetPosition())..'; sBlueprintID='..(sBlueprintID or 'nil')..'; oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')) end
    local iAngleFromTargetToBuilder = AiBotUtilities.GetAngleFromAToB(tTargetLocation, oUnit:GetPosition())
    local iBuildRange = oUnit:GetBlueprint().Economy.MaxBuildDistance
    local iDistanceWantedFromTarget = math.max(1, iBuildRange + (iBuildDistanceMod or 0))
    local oBlueprint
    local iBuildingRadius = 0
    if sBlueprintID then
        oBlueprint = __blueprints[sBlueprintID]
        if oBlueprint then
            iBuildingRadius = math.min(oBlueprint.Physics.SkirtSizeX, oBlueprint.Physics.SkirtSizeZ) - 0.01
        end
    end
    iDistanceWantedFromTarget = iDistanceWantedFromTarget + iBuildingRadius

    if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tTargetLocation='..repru(tTargetLocation)..'; sBlueprintID='..(sBlueprintID or 'nil')..'; iBuildDistanceMod='..(iBuildDistanceMod or 'nil')..'bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation='..tostring(bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation or false)) end
    if not(bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation) then
        --Check if we are in range already
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if we are already in range of the target, distance='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation)..'; iDistanceWantedFromTarget='..iDistanceWantedFromTarget..'; iBuildingRadius='..iBuildingRadius) end
        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation) <= iDistanceWantedFromTarget then
            if bDebugMessages == true then LOG(sFunctionRef..': Target location is already in range') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return
        end
    end

    for iDistanceToMove = iDistanceWantedFromTarget, 1, -1 do
        tPotentialMoveLocation = AiBotUtilities.MoveInDirection(tTargetLocation,iAngleFromTargetToBuilder, iDistanceToMove, true, false, true)
        if NavUtils.GetLabel(sPathing, tPotentialMoveLocation) == iPathingGroupWanted then
            if bDebugMessages == true then LOG(sFunctionRef..': Have a valid location engi can move to='..repru(tPotentialMoveLocation)..'; Dist from target='..AiBotUtilities.GetDistanceBetweenPositions(tPotentialMoveLocation, tTargetLocation)..'; iDistanceToMove='..(iDistanceToMove or 'nil')..'; will check no buildings in a radius of 5 that are blocking this location') end
            local rRectangleToSearch = AiBotUtilities.GetRectAroundLocation(tPotentialMoveLocation, 5)
            local tBlockingUnits = GetUnitsInRect(rRectangleToSearch)
            if AiBotUtilities.IsTableEmpty(tBlockingUnits) == false then
                local tBlockingBuildings = EntityCategoryFilterDown(categories.STRUCTURE, tBlockingUnits)
                for iBuilding, oBuilding in tBlockingBuildings do
                    iBlockingSize = AiBotUnitInfo.GetBuildingSize(oBuilding.UnitId or oBuilding:GetBlueprint().BlueprintId) * 0.5
                    local tBuildingPosition = oBuilding:GetPosition()
                    if math.abs(tBuildingPosition[1] - tPotentialMoveLocation[1]) <= iBlockingSize and math.abs(tBuildingPosition[3] - tPotentialMoveLocation[3]) <= iBlockingSize then
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Will be blocked by a building so wont move here')
                            AiBotUtilities.DrawLocation(tPotentialMoveLocation, 2)
                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return
                    end
                end
            end

            --Wierd case where sometimes the location can be really far away - make sure this isnt the case
            local iDistFromMoveToTarget = AiBotUtilities.GetDistanceBetweenPositions(tPotentialMoveLocation, tTargetLocation)
            if bDebugMessages == true then LOG(sFunctionRef..': returning tPotentialMoveLocation='..repru(tPotentialMoveLocation)..'; Dist to engineer='..AiBotUtilities.GetDistanceBetweenPositions(tPotentialMoveLocation, oUnit:GetPosition())..'; Dist to build location='..AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, oUnit:GetPosition())..'; iDistFromMoveToTarget='..iDistFromMoveToTarget) end
            if iDistFromMoveToTarget < iDistanceWantedFromTarget + 1 then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return tPotentialMoveLocation
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Backup for moving there') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Cant move to the desired location, will draw in red') AiBotUtilities.DrawLocation(tPotentialMoveLocation, 2)
        end
        if iDistanceToMove <= 1 then
            if bDontReturnNilIfAlreadyInRangeOrNoNearbyLocation then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return {tTargetLocation[1], tTargetLocation[2], tTargetLocation[3]}
            end
            break
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return

    --Below was from M27 - left commented out as might be of use when introduce naval factory logic again
    --[[
tPossibleTarget = AiBotMap.GetPositionAtOrNearTargetInPathingGroup(tBuilderLocation, tLocation, iDistanceWantedFromTarget, 0, oBuilder, true, true, iMinDistanceFromCurrentBuilderMoveTarget)

--Adjust further for naval factory to facilitate greater cliff-building
if tPossibleTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, sBlueprintID) then
    --If we move from Possible target towards our currnet position do we come across a cliff very soon?

    local bHaveCliff = false

    local iAngleFromMoveTarget = AiBotUtilities.GetAngleFromAToB(tPossibleTarget, tBuilderLocation)

    local iMaxCliffSearchRange = 15 + math.floor(iBuildDistance)

    function IsCliffBlockingTarget(tTarget)
        local iDistToMoveTarget = AiBotUtilities.GetDistanceBetweenPositions(tBuilderLocation, tTarget)
        local tCliffPositionCheck
        if iDistToMoveTarget > 1 then
            for iDistAdjust = 1, math.min(iMaxCliffSearchRange, math.floor(iDistToMoveTarget)) do
                tCliffPositionCheck = AiBotUtilities.MoveInDirection(tPossibleTarget, iAngleFromMoveTarget, iDistAdjust, true, false)
                if not(NavUtils.GetLabel(sPathing, tCliffPositionCheck) == iEngiPathingGroup) then
                    return true
                end
            end
        end
        return false
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Building naval factory, IsCliffBlockingTarget(tPossibleTarget='..tostring(IsCliffBlockingTarget(tPossibleTarget))..'; tPossibleTarget='..repru(tPossibleTarget)..'; tLocation (of where we want to build)='..repru(tLocation)) end
    if IsCliffBlockingTarget(tPossibleTarget) then
        --Can we get any closer to our build distance if we broaden the angle range?  Also increase the distance slightly
        iDistanceWantedFromTarget = iDistanceWantedFromTarget + 0.1
        local iAngleToEngi = AiBotUtilities.GetAngleFromAToB(tLocation, tBuilderLocation)
        local tReplacementTarget
        local tPathingPosition
        if bDebugMessages == true then LOG(sFunctionRef..': About to try different positions from tLocation '..repru(tLocation)..' to tBuilderLocation '..repru(tBuilderLocation)..'; Angle to here='..iAngleToEngi..'; iDistanceWantedFromTarget='..iDistanceWantedFromTarget) end
        for iAngleAdjust = 0, 40, 8 do
            for iAngleFactor = -1, 1, 2 do
                --MoveInDirection(tStart, iAngle, iDistance, bKeepInMapBounds, bTravelUnderwater)
                tPathingPosition = AiBotUtilities.MoveInDirection(tLocation, iAngleToEngi + iAngleAdjust * iAngleFactor, iDistanceWantedFromTarget, true, false)
                if bDebugMessages == true then

                    local iColour = 3
                    if NavUtils.GetLabel(sPathing, tPathingPosition) == iEngiPathingGroup and not(IsCliffBlockingTarget(tPathingPosition)) then iColour = 7 end
                    LOG(sFunctionRef..': Considering tPathingPosition='..repru(tPathingPosition)..'; iAngleAdjust='..iAngleAdjust * iAngleFactor..'; Pathing group='..NavUtils.GetLabel(sPathing, tPathingPosition)..'; Engi pathing group='..iEngiPathingGroup..'; Is cliff blocking target='..tostring(IsCliffBlockingTarget(tPathingPosition))..'; will draw match in white, nonmatch in black. iColour='..iColour..'; Dist from original move target planned='..AiBotUtilities.GetDistanceBetweenPositions(tPathingPosition, tPossibleTarget))
                    AiBotUtilities.DrawLocation(tPathingPosition, false, iColour, 200)
                end
                if NavUtils.GetLabel(sPathing, tPathingPosition) == iEngiPathingGroup and not(IsCliffBlockingTarget(tPathingPosition)) then
                    tReplacementTarget = tPathingPosition
                end

                if iAngleAdjust == 0 or tReplacementTarget then break end
            end
            if tReplacementTarget then break end
        end
        if tReplacementTarget then
            if bDebugMessages == true then LOG(sFunctionRef..': Have a replacement position to use') end
            tPossibleTarget = {tReplacementTarget[1], tReplacementTarget[2], tReplacementTarget[3]}

        end
    end
end
--]]
end

function BuildStructureNearLocation(aiBrain, oEngineer, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy, tAlternativePositionToLookFrom, bLookForPartCompleteBuildings, bLookForQueuedBuildings, oUnitToBuildBy, bNeverBuildRandom, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, iOptionalEngiActionRef)
    --NOT USED? Might be old code copied from M27 that ended up rewriting?

    --Determines the blueprint and location for oEngineer to build at; also returns the location
    --iCatToBuildBy: Optional, specify if want to look for adjacency locations; Note to factor in 50% of the builder's size and 50% of the likely adjacency building size
    --bLookForQueuedBuildings: Optional, if this is true, then doesnt choose a target if another engineer already has that target function ref assigned to build something
    --Returns nil if dealing with a non-resource based building

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'BuildStructureNearLocation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Engineer UC='..GetEngineerUniqueCount(oEngineer)..'; Engineer LC='..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Techlevel='..AiBotUnitInfo.GetUnitTechLevel(oEngineer)..'; tAlternativePositionToLookFrom='..repru(tAlternativePositionToLookFrom or {'nil'})..'; bBuildCheapestStructure='..tostring((bBuildCheapestStructure or false))..'; bNeverBuildRandom='..tostring((bNeverBuildRandom or false))..'; All blueprints that meet the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild))..'; iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')..'; Water zone of position to look from (if any)='..(AiBotMap.GetWaterZoneFromPosition(tAlternativePositionToLookFrom or oEngineer:GetPosition()) or 'nil')) end


    local bAbortConstruction = false

    --Get the blueprint to build
                                    --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
    local sBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryToBuild, oEngineer, false,        false,  bBuildCheapestStructure, iOptionalCategoryForStructureToBuild)
    local tTargetLocation
    if sBlueprintToBuild == nil then
        if not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) then
            AiBotUtilities.ErrorHandler('sBlueprintToBuild is nil, could happen e.g. if try and get sparky to build sxomething it cant - refer to log for more details')
            if not(iCategoryToBuild) then LOG(sFunctionRef..': No category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer))
            else
                LOG(sFunctionRef..': Had category to build. oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..'; All blueprints that satisfy the category='..repru(EntityCategoryGetUnitList(iCategoryToBuild)))
            end
        end
    else
        --Adjust the search range and record key info needed for the search
        local tEngineerPosition = oEngineer:GetPosition()
        tTargetLocation = (tAlternativePositionToLookFrom or tEngineerPosition)
        --Increase max area to search if dealing with czar or similarly large unit due to its size
        if __blueprints[sBlueprintToBuild].Physics.SkirtSizeX >= 10 then
            iMaxAreaToSearch = iMaxAreaToSearch * 1.5
            if bDebugMessages == true then LOG(sFunctionRef..': Building a large unit such as a czar, increased iMaxAreaToSearch to '..iMaxAreaToSearch) end
        end

        --Reduce max area to search if dealing with a shield
        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) then
            iMaxAreaToSearch = math.min(iMaxAreaToSearch, (__blueprints[sBlueprintToBuild].Defense.Shield.ShieldSize or 0) * 0.5)
            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with a shield so reduce max area to search based on half of shield size. iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')..'; shield size='..__blueprints[sBlueprintToBuild].Defense.Shield.ShieldSize or 0) end
        end


        if bDebugMessages == true then LOG(sFunctionRef..': sBlueprintToBuild='..(sBlueprintToBuild or 'nil')..'; Location to look from='..repru(tAlternativePositionToLookFrom or oEngineer:GetPosition())) end
        local sBlueprintBuildBy
        local bFindRandomLocation = false

        if not(tTargetLocation) then tTargetLocation = tEngineerPosition end
        local bFoundEnemyInstead = false

        local sPathing = AiBotUnitInfo.GetUnitPathingType(oEngineer)
        local iNewBuildingRadius = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)[1] * 0.5
        local iBuilderRange = oEngineer:GetBlueprint().Economy.MaxBuildDistance + math.min((oEngineer:GetBlueprint().SizeX or 1), (oEngineer:GetBlueprint().SizeZ or 1))*0.5
        local iDistanceFromStart = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()])
        local bBuildNearToEnemy = false
        if iDistanceFromStart <= 80 then bBuildNearToEnemy = true end

        --Check we're not trying to buidl a mex or hydro or mass storage or mass fab
        local bMexHydroOrStorage = false
        if EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryMassStorage + AiBotUnitInfo.refCategoryMassFab, sBlueprintToBuild)  then
            bMexHydroOrStorage = true
        end


        --If specified, first check if there's an existing part complete building we can help complete instead of starting a new building
        --Check if is an existing building of the type wanted first:
        local oPartCompleteBuilding
        if bLookForPartCompleteBuildings then
            --GetPartCompleteBuilding(aiBrain, oBuilder, iCategoryToBuild, iBuildingSearchRange, iEnemySearchRange)
            --Returns nil if no nearby part complete building
            --iEnemySearchRange: nil if dont care about nearby enemies, otherwise will ignore buildings that have enemies within iEnemySearchRange
            oPartCompleteBuilding = GetPartCompleteBuilding(aiBrain, oEngineer, iCategoryToBuild, iBuilderRange + 15, nil)
        end
        if oPartCompleteBuilding then
            if bDebugMessages == true then LOG(sFunctionRef..': have partcompletebuilding so returning that as the position') end
            tTargetLocation = oPartCompleteBuilding:GetPosition()
        else
            if bDebugMessages == true then
                local sEngUniqueRef = GetEngineerUniqueCount(oEngineer)
                LOG(sFunctionRef..': Eng builder unique ref='..sEngUniqueRef..'; builder range='..iBuilderRange)
            end



            if not(bMexHydroOrStorage) then
                --For non-extraction buildings, if we have specified we want to build adjacent to something then look for nearby buildings that can give us the adjacency wanted
                if iCatToBuildBy or oUnitToBuildBy then
                    local toPossibleBuildingsToBuildBy
                    local iBuildingCount = 0
                    local tPossibleTargets = {}
                    local tBuildingPosition

                    if iCatToBuildBy then
                        toPossibleBuildingsToBuildBy = aiBrain:GetUnitsAroundPoint(iCatToBuildBy, tTargetLocation, iMaxAreaToSearch, 'Ally')
                        local iCurDist
                        local iClosestDist = 100000
                        --ACU specific - cant build by hydro, but might have nearby hydro
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer position='..repru(oEngineer:GetPosition())..'; tTargetLocation='..repru(tTargetLocation)..'; iMaxAreaToSearch='..iMaxAreaToSearch..'; is toPossibleBuildingsToBuildBy empty='..tostring(AiBotUtilities.IsTableEmpty(toPossibleBuildingsToBuildBy))) end
                        if AiBotUtilities.IsTableEmpty(toPossibleBuildingsToBuildBy) == false then
                            --Try to build by the closest unit of the category wanted
                            local oClosestBuilding
                            for iUnit, oUnit in  toPossibleBuildingsToBuildBy do
                                if oUnit:GetAIBrain() == aiBrain then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEngineer:GetPosition())
                                    if iCurDist < iClosestDist then
                                        oClosestBuilding = oUnit
                                        iClosestDist = iCurDist
                                    end
                                end
                            end
                            if oClosestBuilding then
                                sBlueprintBuildBy = oClosestBuilding.UnitId
                                if bDebugMessages == true then LOG(sFunctionRef..': Will update sBlueprintBuildBy to be the closest building for adjacency='..oClosestBuilding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestBuilding)) end
                            end
                        end


                    elseif oUnitToBuildBy then
                        sBlueprintBuildBy = oUnitToBuildBy.UnitId
                        toPossibleBuildingsToBuildBy = {oUnitToBuildBy}
                    else AiBotUtilities.ErrorHandler('Missing code')
                    end


                    if AiBotUtilities.IsTableEmpty(toPossibleBuildingsToBuildBy) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have possible buildings to build by, so will consider best location') end
                        for iBuilding, oBuilding in toPossibleBuildingsToBuildBy do
                            if not(oBuilding.Dead) and oBuilding.GetPosition and oBuilding:GetAIBrain() == aiBrain then
                                tBuildingPosition = oBuilding:GetPosition()
                                if AiBotUtilities.GetDistanceBetweenPositions(tBuildingPosition, tTargetLocation) <= iMaxAreaToSearch then
                                    iBuildingCount = iBuildingCount + 1
                                    tPossibleTargets[iBuildingCount] = tBuildingPosition
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Found iBuildingCount='..iBuildingCount..' to build by') end
                        if iBuildingCount == 0 then bFindRandomLocation = not(bNeverBuildRandom) end
                    else
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Cant find any buildings for adjacency, getting random location to build unless we want to build by a mex/hydro and have an unbuilt one nearby')
                            local tNearestBuildingOfCategory = aiBrain:GetUnitsAroundPoint(iCatToBuildBy, tTargetLocation, 10000, 'Ally')
                            if AiBotUtilities.IsTableEmpty(tNearestBuildingOfCategory) then LOG(sFunctionRef..': Dont have any units of the desired category anywhere on map')
                            else
                                local oNearestBuildingOfCategory = AiBotUtilities.GetNearestUnit(tNearestBuildingOfCategory, oEngineer:GetPosition(), aiBrain)
                                LOG(sFunctionRef..': Nearest unit of desired category is '..oNearestBuildingOfCategory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestBuildingOfCategory)..' which is '..AiBotUtilities.GetDistanceBetweenPositions(oNearestBuildingOfCategory:GetPosition(), oEngineer:GetPosition())..' away from the engineer')
                            end
                        end
                        bFindRandomLocation = not(bNeverBuildRandom)
                    end

                    --Also check for unbuilt buildings if dealing with a mex or hydro, unless are building a shield
                    local tResourceLocations
                    if not(EntityCategoryContains(categories.SHIELD, sBlueprintToBuild)) then
                        --land factory - say that we're looking for a mex even if cant find one
                        if bDebugMessages == true then LOG(sFunctionRef..': About to check if building early fac and cant find mex/hydro. Does cat to build by contain mex or hydro='..tostring(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryHydro + AiBotUnitInfo.refCategoryMex, iCatToBuildBy, false))..'; sBlueprintBuildBy='..(sBlueprintBuildBy or 'nil')..'; Does engi contain tech1 or ACU='..tostring(EntityCategoryContains(categories.TECH1 + categories.COMMAND, oEngineer.UnitId))..'; Does blueprint to build contain factory='..tostring(EntityCategoryContains(categories.FACTORY, sBlueprintToBuild))) end
                        if iCatToBuildBy and not(sBlueprintBuildBy) and EntityCategoryContains(categories.TECH1 + categories.COMMAND, oEngineer.UnitId) and EntityCategoryContains(categories.FACTORY, sBlueprintToBuild) then
                            if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryMex, iCatToBuildBy, false) then
                                sBlueprintBuildBy = 'ueb1103'
                            elseif AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryHydro, iCatToBuildBy, false) then
                                sBlueprintBuildBy = 'ueb1102'
                            end
                        end
                        if sBlueprintBuildBy then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprintBuildBy) then
                                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                                local iPond, iWaterZone
                                if (iLandZone or 0) == 0 then
                                    iWaterZone = AiBotMap.GetWaterZoneFromPosition(tTargetLocation)
                                    iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                                    tResourceLocations = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefLZOrWZMexLocations]
                                else
                                    tResourceLocations = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMexLocations]
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Will add any mexes within 20 of target location to be considered, tResourceLocations='..repru(tResourceLocations)) end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryHydro, sBlueprintBuildBy) or EntityCategoryContains(AiBotUnitInfo.refCategoryT2Power, sBlueprintBuildBy) then --Dont want to make this all power, because the adjacency code requires a building size, and only works for a single building size; i.e. if try and get adjacency for t1 power and include hydro locations, then it will think it needs to build within the hydro for adjacency
                                local iPlateau, iZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                                if not(iZone) then AiBotUtilities.ErrorHandler('Trying to build a hydro but dont have a valid zone') end
                                tResourceLocations = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone][AiBotMap.subrefHydroLocations]
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tResourceLocations) == false then
                        for iResource, tCurResourceLocation in tResourceLocations do
                            iBuildingCount = iBuildingCount + 1
                            tPossibleTargets[iBuildingCount] = tCurResourceLocation
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and build by resource location (mex or hydro); iBuildingCount including these locations='..iBuildingCount..'; table of building locations='..repru(tPossibleTargets)) end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of resource locations empty='..tostring(AiBotUtilities.IsTableEmpty(tResourceLocations))..'; iBuildingCount='..iBuildingCount) end
                    if iBuildingCount > 0 then
                        --GetBestBuildLocationForTarget(tablePosTarget, sTargetBuildingBPID, sNewBuildingBPID, bCheckValid, aiBrain, bReturnOnlyBestMatch, pBuilderPos, iMaxAreaToSearch, iBuilderRange, bIgnoreOutsideBuildArea, bBetterIfNoReclaim, bPreferCloseToEnemy, bPreferFarFromEnemy, bLookForQueuedBuildings)
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build the shield anywhere near the target. iOptionalEngiActionRef='..(iOptionalEngiActionRef or 'nil')) end
                            local bBuildAwayFromEnemy = false
                            if iOptionalEngiActionRef == refActionFortifyFirebase then bBuildAwayFromEnemy = true end
                            tTargetLocation = GetBuildLocationForShield(aiBrain, sBlueprintToBuild, tAlternativePositionToLookFrom, bBuildAwayFromEnemy)
                            if not(tTargetLocation) then bAbortConstruction = true end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': About to call GetBestBuildLocation; iBuildingCount='..iBuildingCount..'; sBlueprintBuildBy='..(sBlueprintBuildBy or 'nil')) end
                            --Go through all possible adjacent build locations identified, and choose the best one
                            tTargetLocation = GetBestBuildLocationForTarget(tPossibleTargets, sBlueprintBuildBy, sBlueprintToBuild, true, aiBrain, true, tTargetLocation, iMaxAreaToSearch, iBuilderRange, false, true, bBuildNearToEnemy, not(bBuildNearToEnemy), bLookForQueuedBuildings)
                            --Double-check the resulting location is valid
                            if AiBotUtilities.IsTableEmpty(tTargetLocation) == true then
                                if bDebugMessages == true then LOG('Adjacency location is empty, will try finding anywhere to build') end
                                bFindRandomLocation = not(bNeverBuildRandom)
                            else
                                bFindRandomLocation = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Have determined the best build location for target to be '..repru(tTargetLocation)..'; will double-check we can build here, can build here='..tostring(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, nil, nil, nil, false, bLookForQueuedBuildings, false, true, false))) end
                                if not(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, nil, nil, nil, false, bLookForQueuedBuildings, false, true, false)) then
                                    --if aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation) == false or not(AiBotUtilities.IsTableEmpty(aiBrain[reftEngineerAssignmentsByLocation][AiBotUtilities.ConvertLocationToReference(tTargetLocation)])) then
                                    AiBotUtilities.ErrorHandler('Cant build '..sBlueprintToBuild..' on adjacency location tTargetLocation='..repru({tTargetLocation[1], tTargetLocation[2],tTargetLocation[3]}))
                                    bFindRandomLocation = not(bNeverBuildRandom)
                                else
                                    --Check we're within mapBoundary
                                    if bDebugMessages == true then LOG(sFunctionRef..': Cant build at the location; Checking if tTargetLocation '..repru(tTargetLocation)..' is in the playable area '..repru(AiBotMap.rMapPlayableArea)..' based on building size radius='..iNewBuildingRadius) end
                                    if (tTargetLocation[1] - iNewBuildingRadius) < AiBotMap.rMapPlayableArea[1] or (tTargetLocation[3] - iNewBuildingRadius) < AiBotMap.rMapPlayableArea[2] or (tTargetLocation[1] + iNewBuildingRadius) > AiBotMap.rMapPlayableArea[3] or (tTargetLocation[3] + iNewBuildingRadius) > AiBotMap.rMapPlayableArea[4] then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Target location isnt in playable area so will find random place to build instead') end
                                        bFindRandomLocation = not(bNeverBuildRandom)
                                        tTargetLocation = tEngineerPosition
                                    end
                                    if bDebugMessages == true then AiBotUtilities.DrawLocation(tTargetLocation) end
                                end
                            end
                        end
                    else
                        bFindRandomLocation = not(bNeverBuildRandom)
                        if bDebugMessages == true then LOG(sFunctionRef..': Cant find any valid buildings for adjacency') end
                    end
                else
                    --If no was adjacency wanted, then either build at the target location, or find a random location to build (subject to some unit specific points)
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont have a category to build by, will look for random location unless current target is valid or we are a shield') end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild) then
                        local bBuildAwayFromEnemy = false
                        if iOptionalEngiActionRef == refActionFortifyFirebase then bBuildAwayFromEnemy = true end
                        tTargetLocation = GetBuildLocationForShield(aiBrain, sBlueprintToBuild, tAlternativePositionToLookFrom, bBuildAwayFromEnemy)
                        if tTargetLocation then bFindRandomLocation = false else bFindRandomLocation = not(bNeverBuildRandom) end
                    else
                        bFindRandomLocation = not(bNeverBuildRandom)
                    end
                end
            else
                --Dealing with mex or hydro or storage
                if bDebugMessages == true then LOG(sFunctionRef..': Are trying to build a mex, hydro or storage; tTargetLocation='..repru((tTargetLocation or {}))..'; oEngineer='..GetEngineerUniqueCount(oEngineer)..'; LC='..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
                if AiBotUtilities.IsTableEmpty(tTargetLocation) == true then
                    AiBotUtilities.ErrorHandler('Trying to build mex, hydro or storage without defined location')
                else
                    if aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation) then --and AiBotUtilities.IsTableEmpty(aiBrain[reftEngineerAssignmentsByLocation][AiBotUtilities.ConvertLocationToReference(tTargetLocation)]) then
                        --Not interested in if other units have queued up, as e.g. might be ACU that can build and is much closer, so just want whichever unit is closest to try and build
                        if bDebugMessages == true then LOG(sFunctionRef..': Can build structure at targetlocation='..repru(tTargetLocation)..'; if are buildling a t1 mex and there is a t3 mex queued up then will ignore though') end
                        --Are we trying to build a T1 mex? If so then only consider if have an order to build T3 mex
                        if EntityCategoryContains(refCategoryT1Mex, sBlueprintToBuild) then
                            local sLocationRef = AiBotUtilities.ConvertLocationToReference(tTargetLocation)
                            if aiBrain[reftEngineerAssignmentsByLocation][sLocationRef] and AiBotUtilities.IsTableEmpty(aiBrain[reftEngineerAssignmentsByLocation][sLocationRef][refActionBuildT3MexOverT2]) == false then
                                bAbortConstruction = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Trying to build t1 mex when want to build t3 here') end
                            end
                        end
                    else
                        --Cant build at location, is that because of enemy building blocking it, or we have a part-built building?
                        if bDebugMessages == true then LOG(sFunctionRef..': Are trying to build a mex or hydro or mass storage so cant get a random location, but we cant build a structure at the target') end
                        local tEnemyBuildingAtTarget = aiBrain:GetUnitsAroundPoint(iCategoryToBuild, tTargetLocation, 1, 'Enemy')
                        if AiBotUtilities.IsTableEmpty(tEnemyBuildingAtTarget) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have enemy buildings around target') end
                            AiBotPlatoonUtilities.MoveNearConstruction(aiBrain, oEngineer, tTargetLocation, sBlueprintToBuild, 0, false, false, false)
                            for iUnit, oUnit in tEnemyBuildingAtTarget do
                                if oUnit.GetPosition then
                                    IssueReclaim({oEngineer}, oUnit)
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy building is at the target mex/hydro so will try and reclaim that first') end

                            IssueBuildMobile({oEngineer}, tTargetLocation, sBlueprintToBuild, {})
                            if bDebugMessages == true then LOG(sFunctionRef..': 1 - Have sent issuebuildmobile order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..' to build blueprint '..sBlueprintToBuild..' at location '..repru(tTargetLocation)) end
                            bAbortConstruction = true
                            bFoundEnemyInstead = true

                        else
                            local tAllyBuildingAtTarget = aiBrain:GetUnitsAroundPoint(iCategoryToBuild, tTargetLocation, 1, 'Ally')
                            if AiBotUtilities.IsTableEmpty(tAllyBuildingAtTarget) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will target the ally building as its part complete') end
                                oPartCompleteBuilding = tAllyBuildingAtTarget[1]
                            else
                                --Are we stopped from building due to reclaim?

                                local tNewBuildingSize = AiBotUnitInfo.GetBuildingSize(sBlueprintToBuild)
                                local fSizeMod = 0.5

                                local rTargetRect = AiBotUtilities.GetRectAroundLocation(tTargetLocation, tNewBuildingSize[1] * fSizeMod)
                                if bDebugMessages == true then LOG(sFunctionRef..': tTargetLocation='..repru(tTargetLocation)..'; tNewBuildingSize='..repru(tNewBuildingSize)..'; rTargetRect='..repru(rTargetRect)) end
                                --GetReclaimInRectangle(iReturnType, rRectangleToSearch)
                                --iReturnType: 1 = true/false; 2 = number of wrecks; 3 = total mass, 4 = valid wrecks
                                local tReclaimables = AiBotMap.GetReclaimInRectangle(4, rTargetRect)

                                if AiBotUtilities.IsTableEmpty(tReclaimables) == false then
                                    for iReclaim, oReclaim in tReclaimables do
                                        --oEngineer:IssueReclaim(oReclaim)
                                        IssueReclaim({oEngineer}, oReclaim)
                                    end
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef..': Reclaim found that is blocking mex or hydro so will reclaim all wrecks in rectangle='..repru(rTargetRect))
                                        AiBotUtilities.DrawRectangle(rTargetRect, 7, 100)
                                    end

                                    IssueBuildMobile({oEngineer}, tTargetLocation, sBlueprintToBuild, {})
                                    if bDebugMessages == true then LOG(sFunctionRef..': 2 - Have sent issuebuildmobile order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..' to build blueprint '..sBlueprintToBuild..' at location '..repru(tTargetLocation)) end

                                else
                                    --Are we trying to build a T3 mex? If so then we probably are trying to replace a T2 mex which  can lead to problems with the canbuild check
                                    if iCategoryToBuild == AiBotUnitInfo.refCategoryT3Mex then
                                        IssueBuildMobile({oEngineer}, tTargetLocation, sBlueprintToBuild, {})
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef..': Not sure we can build here but will try anyway')
                                            LOG(sFunctionRef..': 3 - Have sent issuebuildmobile order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..' to build blueprint '..sBlueprintToBuild..' at location '..repru(tTargetLocation))
                                        end
                                    else
                                        --One likely explanation is that enemy has built on the mex and we cant see the building, in which case we only want to check this for debugging purposes, and proceed with the default action of having hte engineer try to move there
                                        local tUnits = GetUnitsInRect(rTargetRect)
                                        if AiBotUtilities.IsTableEmpty(tUnits) == true then
                                            AiBotUtilities.ErrorHandler(sFunctionRef..': Cant build at resource location but no units or reclaim on it, will just try moving near the target instead. sBlueprintToBuild='..sBlueprintToBuild..'; Engineer UC='..GetEngineerUniqueCount(oEngineer)..'; LC='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Location='..repru({tTargetLocation[1], tTargetLocation[2],tTargetLocation[3]})..'; Will draw white circle around the target if in debug mode. CanBuildStructure result='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation))..'; Is the table of assigned engineer actions empty='..tostring(AiBotUtilities.IsTableEmpty(aiBrain[reftEngineerAssignmentsByLocation][AiBotUtilities.ConvertLocationToReference(tTargetLocation)])), true)
                                            if bDebugMessages == true then
                                                AiBotUtilities.DrawLocation(tTargetLocation, nil, 7)
                                                LOG(sFunctionRef..': Cnat build at TargetLocation='..repru(tTargetLocation)..'; RectangleSearched='..repru(rTargetRect))
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will just move to the target location') end
                                        AiBotPlatoonUtilities.MoveNearConstruction(aiBrain, oEngineer, tTargetLocation, sBlueprintToBuild, 0, false, false, false)
                                        bAbortConstruction = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        --Switch to random location if an amphibious unit cant path there and its not a resource based location
        if not(bFindRandomLocation) and not(bAbortConstruction) then -- and not(bMexHydroOrStorage) then
            if not(NavUtils.GetLabel(sPathing, tTargetLocation) == NavUtils.GetLabel(sPathing, oEngineer:GetPosition())) then
                bFindRandomLocation = not(bNeverBuildRandom)
            end
        end

        if bFindRandomLocation and (bMexHydroOrStorage or EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild)) and not(bAbortConstruction) and not(iOptionalEngiActionRef == refActionFortifyFirebase) then
            --Backup - Trying to build a mex or hydro so no point getting random location
            if not(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, sBlueprintToBuild)) then
                AiBotUtilities.ErrorHandler('Are trying to build in a random place for am ex/hydro/mass storage - figure out why as this shouldnt trigger; Engineer with UC='..GetEngineerUniqueCount(oEngineer)..'='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; trying to build blueprint='..sBlueprintToBuild)
                if bDebugMessages == true then LOG(sFunctionRef..': Trying to build mex or hydro so cant choose a random location') end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Trying to build a shield but couldnt find anywhere to build it so no point building it in the end. iOptionalEngiActionRef='..(iOptionalEngiActionRef or 'nil')) end
            end
            bFindRandomLocation = false
            bAbortConstruction = true
        end

        --Look for a random location if we failed to find a suitable location in the above steps
        if bFindRandomLocation == true and not(bAbortConstruction) then
            if bDebugMessages == true then LOG(sFunctionRef..': Are finding a random location to build unless current location is valid; sBlueprintToBuild='..sBlueprintToBuild..'; iMaxAreaToSearch='..(iMaxAreaToSearch or 'nil')) end
            if AiBotUtilities.IsTableEmpty(tTargetLocation) == true then tTargetLocation = (tAlternativePositionToLookFrom or tEngineerPosition) end

            --First check in build area for the best location assuming the target location isnt far away
            if AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, tEngineerPosition) <= 30 then tTargetLocation = GetBestBuildLocationForTarget(tTargetLocation, nil, sBlueprintToBuild, true, aiBrain, true, tTargetLocation, iMaxAreaToSearch, iBuilderRange, false, true, bBuildNearToEnemy, not(bBuildNearToEnemy), false) end
            if AiBotUtilities.IsTableEmpty(tTargetLocation) == true or not(CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, nil, nil, nil, false, bLookForQueuedBuildings, true, nil, false)) then
                --if AiBotUtilities.IsTableEmpty(tTargetLocation) == true or not(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation)) or not(AiBotUtilities.IsTableEmpty(aiBrain[reftEngineerAssignmentsByLocation][AiBotUtilities.ConvertLocationToReference(tTargetLocation)])) then
                if AiBotUtilities.IsTableEmpty(tTargetLocation) then tTargetLocation = (tAlternativePositionToLookFrom or tEngineerPosition) end
                if bDebugMessages == true then
                    LOG(sFunctionRef..' Cant build '..sBlueprintToBuild..'; will try and find a random place to build; target location for random place to build='..repru(tTargetLocation))
                    if iCategoryToBuild == nil then LOG(sFunctionRef..' iCategoryToBuild is nil somehow') end
                end
                --FindRandomPlaceToBuild(aiBrain, oBuilder, tStartPosition, sBlueprintToBuild, iSearchSizeMin, iSearchSizeMax, bForcedDebug)
                local bSuitableForLastSuccessfulLocation = EntityCategoryContains(AiBotUnitInfo.refCategoryStructure + categories.EXPERIMENTAL - AiBotUnitInfo.refCategorySatellite - AiBotUnitInfo.refCategoryFirebaseSuitable, sBlueprintToBuild) and AiBotUtilities.IsTableEmpty(aiBrain[reftLastSuccessfulLargeBuildingLocation]) == false
                local iSearchCycles = nil
                if bSuitableForLastSuccessfulLocation then iSearchCycles = 3 end
                tTargetLocation = FindRandomPlaceToBuild(aiBrain, oEngineer, (tTargetLocation or tAlternativePositionToLookFrom or tEngineerPosition), sBlueprintToBuild, 2, iMaxAreaToSearch, bDebugMessages, iSearchCycles)
                if AiBotUtilities.IsTableEmpty(tTargetLocation) == true then
                    --Try searching the last location we built at successfully for a couple of cycles if arent building a firebase unit
                    if bSuitableForLastSuccessfulLocation then
                        tTargetLocation = FindRandomPlaceToBuild(aiBrain, oEngineer, aiBrain[reftLastSuccessfulLargeBuildingLocation], sBlueprintToBuild, 2, iMaxAreaToSearch, false, math.min(3, (iSearchCycles or 3)))
                    end
                    if AiBotUtilities.IsTableEmpty(tTargetLocation) then
                        LOG(sFunctionRef..': WARNING - couldnt find a random place to build based on position='..repru(tTargetLocation)..'; will abort construction')
                        bAbortConstruction = true
                    end
                elseif bDebugMessages == true then LOG(sFunctionRef..': Found random place to build='..repru(tTargetLocation))
                end
            else if bDebugMessages == true then LOG(sFunctionRef..': No need for random place as current targetlocation is valid, ='..repru(tTargetLocation)) end
            end
        end
        --Only proceed with sending a build order (or repair order for a part complete building) if we had success in the earlier steps
        if bAbortConstruction == false then
            if bDebugMessages == true then LOG(sFunctionRef..': Not aborting function so will try to move near construction if we have a valid location') end
            if AiBotUtilities.IsTableEmpty(tTargetLocation) == false and sBlueprintToBuild then
                --Adjust Target location if building PD
                if EntityCategoryContains(AiBotUnitInfo.refCategoryPD, sBlueprintToBuild) then
                    tTargetLocation = AdjustPDBuildLocation(aiBrain, tTargetLocation, sBlueprintToBuild)
                end
                --MoveNearConstruction(aiBrain, oBuilder, tLocation, sBlueprintID, iBuildDistanceMod, bReturnMovePathInstead, bUpdatePlatoonMovePath, bReturnNilIfAlreadyMovingNearConstruction, bReturnMoveLocationifGivenOne)
                local tMoveNearTargetLocation = AiBotPlatoonUtilities.MoveNearConstruction(aiBrain, oEngineer, tTargetLocation, sBlueprintToBuild, 0, false, false, false, true)
                if oPartCompleteBuilding then
                    if bDebugMessages == true then LOG(sFunctionRef..': Send order for oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to repair '..oPartCompleteBuilding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPartCompleteBuilding)..' at '..repru(oPartCompleteBuilding:GetPosition())) end

                    IssueRepair({ oEngineer}, oPartCompleteBuilding)
                else
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Send order for oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to build '..sBlueprintToBuild..' at '..repru(tTargetLocation)..'; will draw target location in gold')
                        AiBotUtilities.DrawLocation(tTargetLocation, nil, 4, 500)
                    end

                    --MAIN ISSUEBUILDMOBILE FOR CONSTRUCTION (i.e. other issuebuilds here are for specific actions)
                    IssueBuildMobile({oEngineer}, tTargetLocation, sBlueprintToBuild, {})
                    if bDebugMessages == true then LOG(sFunctionRef..': 4 - Have sent issuebuildmobile order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; UC='..GetEngineerUniqueCount(oEngineer)..' to build blueprint '..sBlueprintToBuild..' at location '..repru(tTargetLocation)..' with surface height='..GetSurfaceHeight(tTargetLocation[1], tTargetLocation[3])..'; tMoveNearTargetLocation='..repru(tMoveNearTargetLocation)) end
                end
                if AiBotUtilities.IsTableEmpty(tMoveNearTargetLocation) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': About to start thread checking for when the engineer is in build range') end
                    ForkThread(TrackWhenEngineerInBuildRange, oEngineer, tMoveNearTargetLocation, (sBlueprintToBuild or oPartCompleteBuilding.UnitId), tTargetLocation, oPartCompleteBuilding)
                    if sBlueprintToBuild and not(oPartCompleteBuilding) then
                        ForkThread(CheckIfEngineerLikelyStuck, oEngineer, sBlueprintToBuild, tTargetLocation)
                    end

                end
            end
        else
            if bDebugMessages == true then LOG('Warning - couldnt find any places to build after looking randomly nearby, will abort construction. bFoundEnemyInstead='..tostring(bFoundEnemyInstead)) end
            if bDebugMessages == true then
                LOG(sFunctionRef..': Aborted construction, will draw target location in red')
                AiBotUtilities.DrawLocation(tTargetLocation, nil, 2, 100)
            end
            if not(bMexHydroOrStorage) then tTargetLocation = nil end
        end
    end
    if bDebugMessages == true then
        if sBlueprintToBuild == nil then LOG('sBlueprintToBuild is nil')
        else
            if tTargetLocation then
                LOG(sFunctionRef..': tTargetLocation='..repru(tTargetLocation)..'; aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation)='..tostring(aiBrain:CanBuildStructureAt(sBlueprintToBuild, tTargetLocation))..'; sBlueprintToBuild='..(sBlueprintToBuild or 'nil'))
                if not(bAbortConstruction) then AiBotUtilities.DrawLocation(tTargetLocation, nil, 7, 100) end --show in white (colour 7)
                LOG(sFunctionRef..': About to list any units in 1x1 rectangle around targetlocation')
                local iSizeAdj = 3
                local rBuildAreaRect = Rect(tTargetLocation[1] - iSizeAdj, tTargetLocation[3] - iSizeAdj, tTargetLocation[1] + iSizeAdj, tTargetLocation[3] + iSizeAdj)
                local tUnitsInRect = GetUnitsInRect(rBuildAreaRect)
                local tsUnitRefs = {}
                if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                    for iUnit, oUnit in tUnitsInRect do
                        table.insert(tsUnitRefs, iUnit, oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
                    end
                end
                LOG('tsUnitRefs='..repru(tsUnitRefs))
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tTargetLocation
end

function GetPartCompleteBuilding(aiBrain, oBuilder, iCategoryToBuild, iBuildingSearchRange)
    --Returns nil if no nearby part complete building
    --iEnemySearchRange: nil if dont care about nearby enemies, otherwise will ignore buildings that have enemies within iEnemySearchRange
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPartCompleteBuilding'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tBuilderPosition = oBuilder:GetPosition()
    local tAllBuildings = aiBrain:GetUnitsAroundPoint(iCategoryToBuild, tBuilderPosition, iBuildingSearchRange, 'Ally')
    local iCurDistanceToBuilder
    local iMinDistanceToBuilder = 10000
    local tBuildingPosition
    local oNearestPartCompleteBuilding
    if AiBotUtilities.IsTableEmpty(tAllBuildings) == false then
        for iBuilding, oBuilding in tAllBuildings do
            --Dont try and compelte part built shields as may be part built due to special shielding logic
            if oBuilding.GetFractionComplete and oBuilding.GetPosition and oBuilding:GetFractionComplete() < 1 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oBuilding.UnitId)) then
                local tNearbyEnemies
                tBuildingPosition = oBuilding:GetPosition()
                iCurDistanceToBuilder = AiBotUtilities.GetDistanceBetweenPositions(tBuildingPosition, tBuilderPosition)
                if iCurDistanceToBuilder < iMinDistanceToBuilder then
                    iMinDistanceToBuilder = iCurDistanceToBuilder
                    oNearestPartCompleteBuilding = oBuilding
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oNearestPartCompleteBuilding
end

function SlowlyRefreshBuildableLandZoneLocations(oOrigBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SlowlyRefreshBuildableLandZoneLocations'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    bBuildLocationLoopActive = true
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iSearchesConsideredThisTick
    local iTicksWaitedThisCycle
    local iSegmentsBeforeWaiting
    if AiBotUtilities.bCPUPerformanceMode then iSegmentsBeforeWaiting = 4
    elseif GetGameTimeSeconds() >= 600 or AiBotOverseer.refiRoughTotalUnitsInGame >= 500 then iSegmentsBeforeWaiting = 16 --Must be a multiple of 2, i.e. 2^x results in this
    else iSegmentsBeforeWaiting = 32
    end
    local aiBrain = oOrigBrain

    --First update every start position that has an AiBot brain to make sure we have a decent number of options recorded for a land factory and smaller
    for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
        if bDebugMessages == true then LOG(sFunctionRef..': About to start recording buildable locations for the starting land zone for oBrain='..oBrain.Nickname..'; Index='..oBrain:GetArmyIndex()..'; Start pos='..repru(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])) end
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])
        if (iLandZone or 0) > 0 then
                --SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
            SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateau, iLandZone, iSegmentsBeforeWaiting * 10)

            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end

    while true do
        --Get a new brain if needed
        if aiBrain.AiBotIsDefeated then
            aiBrain = nil
            for iBrain, oBrain in ArmyBrains do
                if oBrain.AiBotAI and not(oBrain.AiBotIsDefeated) then
                    aiBrain = oBrain
                    break
                end
            end
            if not(aiBrain) then
                break
            end
        end

        iTicksWaitedThisCycle = 0
        iSearchesConsideredThisTick = 0

        --Cycle through every plateau
        for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
            for iLandZone, tLandZoneInfo in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
                if bDebugMessages == true then LOG(sFunctionRef..': Updating for iPlateau='..iPlateau..'; iLandZone='..iLandZone) end
                if tLandZoneInfo[AiBotMap.subrefBuildLocationsBySizeAndSegment] then
                    if tLandZoneInfo[AiBotMap.subrefLZTotalSegmentCount] >= 80 or tLandZoneInfo[AiBotMap.subrefLZOrWZMexCount] > 0 then
                        --SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
                        SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateau, iLandZone, iSegmentsBeforeWaiting)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        iTicksWaitedThisCycle = iTicksWaitedThisCycle + 1
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                end
                iTicksWaitedThisCycle = iTicksWaitedThisCycle + 1
            end
        end
        if iTicksWaitedThisCycle < 1000 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1000 - iTicksWaitedThisCycle)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            iSegmentsBeforeWaiting = math.max(2, iSegmentsBeforeWaiting * 0.5)
        elseif iTicksWaitedThisCycle >= 3000 then
            iSegmentsBeforeWaiting = math.min(64, iSegmentsBeforeWaiting * 2)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordBuildableCoreWaterZoneLocationsNearStartOfGame()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordBuildableCoreWaterZoneLocationsNearStartOfGame'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    bWZBuildLocationLoopActive = true
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iSearchesConsideredThisTick
    local iTicksWaitedThisCycle
    local iSegmentsBeforeWaiting = 16 --Must be a multiple of 2, i.e. 2^x results in this

    local tWZShortlistByWZ = {} --Index is WZ

    local iCurWZ
    local aiBrain
    --Get the naval build locations for each AiBot brain to create a shortlist that will be cycled through
    for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
        aiBrain = oBrain
        if AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails) == false then
            for iPond, tPondSubtable in AiBotMap.tPondDetails do
                if AiBotUtilities.IsTableEmpty(tPondSubtable[AiBotMap.subrefBuildLocationByStartPosition]) == false then
                    for iEntry, tPosition in tPondSubtable[AiBotMap.subrefBuildLocationByStartPosition] do
                        iCurWZ = AiBotMap.GetWaterZoneFromPosition(tPosition)
                        if (iCurWZ or 0) > 0 then
                            tWZShortlistByWZ[iCurWZ] = true
                        end
                    end
                end
            end
        end
    end
    local tWZShortlist = {}
    if AiBotUtilities.IsTableEmpty(tWZShortlistByWZ) == false then
        for iWZ, bInclude in tWZShortlistByWZ do
            table.insert(tWZShortlist, iWZ)
        end
    end

    if AiBotUtilities.IsTableEmpty(tWZShortlist) == false then
        --First ensure we have basic sizes for the WZ and some entries
        for iEntry, iWaterZone in tWZShortlist do
            SearchForBuildableLocationsForLandOrWaterZone(aiBrain, 0, iWaterZone, iSegmentsBeforeWaiting)
        end

        local iTotalCycles = 0

        while iTotalCycles <= 100 do
            iTotalCycles = iTotalCycles + 1
            --Get a new brain if needed
            if aiBrain.AiBotIsDefeated then
                aiBrain = nil
                for iBrain, oBrain in ArmyBrains do
                    if oBrain.AiBotAI and not(oBrain.AiBotIsDefeated) then
                        aiBrain = oBrain
                        break
                    end
                end
                if not(aiBrain) then
                    break
                end
            end

            iTicksWaitedThisCycle = 0
            iSearchesConsideredThisTick = 0

            --Cycle through every entry
            for iEntry, iWaterZone in tWZShortlist do
                        --SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
                SearchForBuildableLocationsForLandOrWaterZone(aiBrain, 0, iWaterZone, iSegmentsBeforeWaiting)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                iTicksWaitedThisCycle = iTicksWaitedThisCycle + 1
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DecideOnExperimentalToBuild(iActionToAssign, aiBrain, tbEngineersOfFactionOrNilIfAlreadyAssigned, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
    --Decide whether to get land, arti, nuke or gameender

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DecideOnExperimentalToBuild'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iFactionRequired
    local iCategoryWanted
    local bDontWantExperimental = false
    local iGameEnderTemplateCategory
    local iGameEnderTemplateCategories
    if not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then iGameEnderTemplateCategories = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre
    elseif AiBotUtilities.bQuietModActive then  iGameEnderTemplateCategories = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti
    else iGameEnderTemplateCategories = AiBotUnitInfo.refCategoryGameEnder
    end
    local bGettingNonSeraphimAirExp = false
    local bGettingNonUEFLandExp = false
    if not(tbEngineersOfFactionOrNilIfAlreadyAssigned) then
        if bDebugMessages == true then LOG(sFunctionRef..': Already have unit under construction so will return experimentallevel') end
        iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalLevel - categories.NAVAL --Already have the unit under construction
        if AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZOrWZTeamData) and not(aiBrain.AiBotEasy) then
            if bDebugMessages == true then LOG(sFunctionRef..': We already have active GE template logic so will just assign engineers to that') end
            iCategoryWanted = refActionManageGameEnderTemplate
        end
    elseif iActionToAssign == refActionManageGameEnderTemplate then
        if bDebugMessages == true then LOG(sFunctionRef..': We wanted to build GE template already so that will be the category wanted') end
        iCategoryWanted = refActionManageGameEnderTemplate
    else
        --Do we have an experimental level unit under construciton in this LZ?
        local tExperimentalsInLZ
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            tExperimentalsInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tExperimentalsInLZ) == false then
                for iUnit, oUnit in tExperimentalsInLZ do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 and oUnit:GetFractionComplete() > 0.001 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Setting category to experimental level as have part complete experimental') end
                        iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalLevel - categories.NAVAL
                        break
                    end
                end
            end
        end
        if not(iCategoryWanted) then
            if bDebugMessages == true then
                LOG(sFunctionRef..': Deciding on what experimental to construct, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Time='..GetGameTimeSeconds()..'; Team mass income='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Brain='..(aiBrain.Nickname or 'nil')..'; Is campaignAI='..tostring(aiBrain.CampaignAI or false)..'; Is AiBotAI='..tostring(aiBrain.AiBotAI or false)..'; Land subteam='..(aiBrain.AiBotLandSubteam or 'nil')..'; Is table of land subteam empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]))..'; Team gross mass='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass]..'; refbBuiltParagon='..tostring(aiBrain[AiBotEconomy.refbBuiltParagon] or false)..'; Do we have air control='..tostring(AiBotConditions.TeamHasAirControl(aiBrain.AiBotTeam))..'; subrefiOurAirAAThreat='..(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurAirAAThreat] or 'nil')..'; (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0)='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0)..'; Cur t3 arti count='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFixedT3Arti, aiBrain.AiBotTeam)..'; refiEnemyT3ArtiCount='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount]..'; refiEnemyNovaxCount='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyNovaxCount])
                local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(aiBrain.AiBotTeam, iPlateauOrZero, iLandOrWaterZone, true, nil, nil, false, nil, aiBrain.AiBotAirSubteam)
                LOG(sFunctionRef..': Checking if already building exp in other zones, iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; iMassToComplete='..iMassToComplete..'; Team net mass income='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamNetMass]..'; Team gross mass income='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass]..'; % mass stored='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored])
            end
            --scta: get exp factory first
            if aiBrain.AiBotSCTA and aiBrain:GetCurrentUnits(categories.EXPERIMENTAL * categories.FACTORY) == 0 then
                iCategoryWanted = categories.EXPERIMENTAL * categories.FACTORY
                if bDebugMessages == true then LOG(sFunctionRef..': Want to get an experimental factory as SCTA, unless we decide just below to get experimental PD') end
            end
            --Land priority - usually but not always prefer land experimental
            local bPrioritiseLand = false
            if aiBrain[AiBotOverseer.refbPrioritiseLand] then
                bPrioritiseLand = true
                if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] > 4 then
                    bPrioritiseLand = true
                    local iAllExpBuilt = AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryExperimentalLevel)
                    --Use normal logic for every 4th experimental (or 5th if first time)
                    if iAllExpBuilt >= 5 and math.floor((iAllExpBuilt - 1) / 4) == (iAllExpBuilt - 1) / 4 then
                        bPrioritiseLand = false
                    end
                end
            end
            --Land subteam - use aiBrain.AiBotLandSubteam
            local iSubteamSize =  table.getn(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains])
            local iEnemyLandExperimentalCount = table.getn(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyLandExperimentals])
            local bEnemyHasFatboys = false
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyLandExperimentals])) == false then
                bEnemyHasFatboys = true
            end
            local iTeam = aiBrain.AiBotTeam
            local iDistToNearestEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], tLZOrWZData[AiBotMap.subrefMidpoint])
            local bCanPathByLand
            local bCanPathAmphibiously
            if NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZData[AiBotMap.subrefMidpoint]) == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) then
                bCanPathByLand = true
            else bCanPathByLand = false
            end
            if NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tLZOrWZData[AiBotMap.subrefMidpoint]) == NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) then
                bCanPathAmphibiously = true
            else bCanPathAmphibiously = false
            end

            --Non-faction specific logic:

            --Initial land experimental (very high priority subject to map)
            local iTeamLandExperimentals = 0
            for iBrain, oBrain in AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                iTeamLandExperimentals = iTeamLandExperimentals + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental)
            end

            if iTeamLandExperimentals >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 7000 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) >= 2 then
                --Factor in experimentals under construction (as no longer a high priority to build land experimentals)
                local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, false, nil, AiBotUnitInfo.refCategoryLandExperimental, nil, nil, aiBrain.AiBotAirSubteam)
                iTeamLandExperimentals = iTeamLandExperimentals + iOtherLandZonesWithExperimental
            end


            --Do we think we can handle enemy threat with air?
            local bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = false
            local iEnemyClosestLandExperimentalOnSamePlateau = 10000
            local iEnemyExpOnSamePlateau = 0
            local bHaveAirControl = AiBotConditions.TeamHasAirControl(iTeam)
            local bFarBehindOnAir = AiBotConditions.TeamIsFarBehindOnAir(iTeam)
            local iCurModDist
            local iEnemyExpBaseCount
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) then
                for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oExp:GetPosition()) == iPlateauOrZero then
                        iEnemyExpBaseCount = 1
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryMegalith, oExp.UnitId) then
                            iEnemyExpBaseCount = 1.5
                        end
                        iEnemyExpOnSamePlateau = iEnemyExpOnSamePlateau + math.max(0.3, oExp:GetFractionComplete()) * iEnemyExpBaseCount
                        iCurModDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])
                        if oExp:GetFractionComplete() <= 0.6 then
                            iCurModDist = iCurModDist + (200 - 250 * oExp:GetFractionComplete())
                        end
                        iEnemyClosestLandExperimentalOnSamePlateau = math.min(iEnemyClosestLandExperimentalOnSamePlateau, iCurModDist)
                    end
                end
            end

            if iEnemyClosestLandExperimentalOnSamePlateau <= math.min(700, math.max(450, AiBotMap.iMapSize * 0.5)) then
                bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = true

                local iCombinedAirToGroundThreat = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0)
                if iEnemyClosestLandExperimentalOnSamePlateau >= 225 or (iCombinedAirToGroundThreat >= 60000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 8000) then
                    if iCombinedAirToGroundThreat >= math.max(12500, AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] * 3000) and (iCombinedAirToGroundThreat >= 30000 or bHaveAirControl) and (not(bFarBehindOnAir) or (iCombinedAirToGroundThreat >= math.max(35000, AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount]*4500))) then
                        if iEnemyExpOnSamePlateau == 1 or iCombinedAirToGroundThreat >= 40000 or iCombinedAirToGroundThreat >= 7500 + 5000 * iEnemyExpOnSamePlateau then
                            bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = false
                        end
                    end
                    if bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats then
                        if iTeamLandExperimentals > iEnemyClosestLandExperimentalOnSamePlateau * 1.3 then
                            bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = false
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and iTeamLandExperimentals >= math.min(3, iEnemyClosestLandExperimentalOnSamePlateau) then
                            bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = false
                        elseif iTeamLandExperimentals >= 3.5 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5 then --will come a point where want to assume we can handle enemy
                            bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = false
                        end
                    end
                end
            end
            if not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = true end
            if not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction] then bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = true end

            if not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) then
                local tNearbyEnemyLandCombat = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat - categories.TECH1, tLZOrWZData[AiBotMap.subrefMidpoint], 280, 'Enemy')
                if AiBotUtilities.IsTableEmpty(tNearbyEnemyLandCombat) == false then
                    local iNearbyMassThreat = AiBotUnitInfo.GetMassCostOfUnits(tNearbyEnemyLandCombat, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': iNearbyMassThreat='..iNearbyMassThreat) end
                    if iNearbyMassThreat > math.max(5000, (tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) * 0.2) then
                        bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats = true
                    end
                end
            end

            --QUIET and LOUD (or FAF mods that give experimental PD) - consider experimental PD if dont have already
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to get experimental PD or AA, bHaveAllFactionExpPD='..tostring(AiBotBuilding.bHaveAllFactionExpPD)..'; AiBotBuilding.bHaveAllFactionExperimentalSAM='..tostring(AiBotBuilding.bHaveAllFactionExperimentalSAM)..'; refiEnemyMobileDFThreatNearOurSide='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]..'; tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]..'; bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats='..tostring(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats)..'; tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Far behind on air='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; Enemy air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) end
            if AiBotBuilding.bHaveAllFactionExpPD and (bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 30000 or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 10000))  and not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) and (aiBrain[AiBotOverseer.refbPrioritiseDefence] or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 10000) and (aiBrain[AiBotOverseer.refbPrioritiseDefence] or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.max(2, math.min(4, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount])) and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 40000)))) then
                local iFriendlyPDThreat = 0
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                    for iRange, iThreat in tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                        iFriendlyPDThreat = iFriendlyPDThreat + iThreat
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iFriendlyPDThreat='..iFriendlyPDThreat..'; Enemy land threat near our side='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]) end
                if iFriendlyPDThreat < 30000 or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iFriendlyPDThreat < math.max(60000, AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] * 0.7) and (bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats or iFriendlyPDThreat < AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] * 0.5)) then
                    iCategoryWanted = AiBotUnitInfo.refCategoryPD * categories.EXPERIMENTAL
                    if bDebugMessages == true then LOG(sFunctionRef..': will get long ranged PD') end
                elseif iFriendlyPDThreat < AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] and (iFriendlyPDThreat < 100000 or aiBrain[AiBotOverseer.refbPrioritiseDefence]) and (iFriendlyPDThreat < 45000 or tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                    iCategoryWanted = AiBotUnitInfo.refCategoryPD * categories.EXPERIMENTAL
                    if bDebugMessages == true then LOG(sFunctionRef..': will get more long ranged PD') end
                end
            end
            --T4 SAMs - if have less than enemy air to ground threat, and also less than between 30k-50k groundAA threat (depending on enemy air to ground threat), and are far behind on air, the nconsider building
            if AiBotBuilding.bHaveAllFactionExperimentalSAM and not(iCategoryWanted) and not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) and not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl]) and
                    ((aiBrain[AiBotOverseer.refbPrioritiseDefence] and tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat], 80000)) and ( tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.max(3, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]))
                            or (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < math.max(math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat], 30000), math.min(60000,AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.4)) and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 30000 and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.max(3, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]))) then

                iCategoryWanted = AiBotUnitInfo.refCategoryStructureAA * categories.EXPERIMENTAL
                if bDebugMessages == true then LOG(sFunctionRef..': want T4 SAM') end
            end

            if not(iCategoryWanted) then

                local iTeamNukes = 0
                if bDebugMessages == true then LOG(sFunctionRef..': iTeamLandExperimentals='..iTeamLandExperimentals..'; bCanPathByLand='..tostring(bCanPathByLand)..'; bCanPathAmphibiously='..tostring(bCanPathAmphibiously)..'; bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats='..tostring(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats)..'; iEnemyClosestLandExperimentalOnSamePlateau='..iEnemyClosestLandExperimentalOnSamePlateau..'; Is table of enemy DF units empyt='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; bHaveAirControl='..tostring(bHaveAirControl)) end
                if iTeamLandExperimentals <= 0 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) and ((bCanPathByLand and (bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) < math.min(4, math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5)))) or bCanPathAmphibiously and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 5 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) <= 2 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] or 0) * 4) then
                    local bOnlyHaveUEF = tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF] and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon]) and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran])
                    if aiBrain[AiBotOverseer.refbPrioritiseAir] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or (AiBotMap.iMapSize >= 512 and (AiBotTeam.iPlayersAtGameStart > 3 or AiBotMap.iMapSize > 512) and (AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurAirAAThreat] >= 8000 or (tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 700) or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 1000 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory * categories.TECH3) >= 4)))) and not(bOnlyHaveUEF) and ((tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] or 0) + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) <= 65000) or (not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] or 0) + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] or 0) + AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurExpBomberThreat] <= 50000)) and (bHaveAirControl or ((tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0) and not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir]) and (iEnemyClosestLandExperimentalOnSamePlateau >= 300 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2))) and not(aiBrain[AiBotOverseer.refbPrioritiseLand])) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering getting air exp first instead of land exp, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; T1-T3 Bomber threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]) end
                        if bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] < 30000 then
                            if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] and not(aiBrain.AiBotEasy) then
                                iCategoryWanted = AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                            else
                                iCategoryWanted = (AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryGunship) * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR

                                bGettingNonSeraphimAirExp = true
                                --If have UEF and not other factions then include novax
                                if bOnlyHaveUEF then
                                    iCategoryWanted = iCategoryWanted + AiBotUnitInfo.refCategoryNovaxCentre
                                end
                            end
                        end
                    else
                        iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                        if bDebugMessages == true then LOG(sFunctionRef..': We have no land experimentals but can reach the enemy base by land so will consider building one, Is Cybran engineers of faction available='..tostring(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran] or false)..'; Lifetime land experimental count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental)) end
                        if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran] then
                            if AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) < 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0) then
                                iCategoryWanted = AiBotUnitInfo.refCategoryMonkeylord - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                iFactionRequired = AiBotUnitInfo.refFactionCybran
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build a monkeylord') end
                            else
                                iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                if categories.url0402 then
                                    iCategoryWanted = iCategoryWanted - categories.url0402
                                end

                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build a megalith or other land experimental that isnt a monkeylord')
                                end
                            end
                        end
                    end
                else
                    --Consider getting nukes
                    if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (aiBrain[AiBotEconomy.refbBuiltParagon] and iTeamLandExperimentals >= 3 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.1 and iPlateauOrZero > 0 and (tLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) >= 10000) then --dont want nuke built too far from base
                        --If enemy has dangerous experimentals and can path with land then dont consider nuke unless this is a 'safe' zone
                        --also if playing in loud then require us to have built several experimentals already due to how much a nuke costs
                        local iExpConstructedFactor = 1
                        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then iExpConstructedFactor = 2 end
                        if bPrioritiseLand or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then iExpConstructedFactor = iExpConstructedFactor * 2.5 end
                        if bDebugMessages == true then LOG(sFunctionRef..': COnsdering if want nuke, iEnemyClosestLandExperimentalOnSamePlateau='..iEnemyClosestLandExperimentalOnSamePlateau..'; bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats='..tostring(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats)..'; bCanPathByLand='..tostring(bCanPathByLand)..'; tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]='..tostring(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition])..'; iTeamLandExperimentals='..iTeamLandExperimentals..'; Exp Lifetime count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental)..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) end
                        if iEnemyClosestLandExperimentalOnSamePlateau >= 250 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) or not(bCanPathByLand) or (tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] and (iTeamLandExperimentals >= (0.25 + 0.75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) * iExpConstructedFactor or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) > iExpConstructedFactor * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) or AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) >= 750 * iExpConstructedFactor) then
                            --Do we already have nukes, or we have a paragon and have built lots of exps?
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of nukes in this zone empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategorySML, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))..'; iExpConstructedFactor='..iExpConstructedFactor) end
                            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategorySML, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) or (aiBrain[AiBotEconomy.refbBuiltParagon] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 15) then
                                --Do teammates have no more than 1 nuke?
                                for iBrain, oBrain in AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                    iTeamNukes = iTeamNukes + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML)
                                    --Treat us as having more nukes if we have an experimental nuke
                                    if iTeamNukes > 0 and oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then iTeamNukes = iTeamNukes + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL) * 2 end
                                end
                                local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, false, nil, AiBotUnitInfo.refCategorySML)
                                if bDebugMessages == true then LOG(sFunctionRef..': iTeamNukes based on getcurrentunits='..iTeamNukes..'; iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental) end
                                iTeamNukes = iTeamNukes + iOtherLandZonesWithExperimental

                                if bDebugMessages == true then LOG(sFunctionRef..': iTeamNukes after update='..iTeamNukes..'; Radar coverage='..(tLZOrWZTeamData[AiBotMap.refiRadarCoverage] or 'nil')..'; Our Gunship threat='..AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurGunshipThreat]..'; Enemy T3 MAA count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount]) end
                                if ((iTeamNukes == 0 or (iOtherLandZonesWithExperimental == 0 and iTeamNukes == 1 and AiBotMap.iMapSize > 512 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3))
                                        or (aiBrain[AiBotEconomy.refbBuiltParagon] and iTeamNukes <= 8 and 6 + iTeamNukes * 6 < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategorySML) * 6 < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]))
                                        and (not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 or AiBotMap.bIsCampaignMap or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL) == 0)
                                        --Require omni or large gunship threat or have built multiple exps, otherwise run the risk of thinking enemy doesnt have land experimental when they do
                                        and (tLZOrWZTeamData[AiBotMap.refiRadarCoverage] > AiBotUnitInfo.iT2RadarSize or tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 or AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurGunshipThreat] >= math.max(30000, AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] * 4000)) then
                                    --Do we have a friendly base that is in a safe position, and this zone isnt, such that we shouldnt build a nuke and just leave the other base to build a nuke? (assuming ore lifetime exp constructed count is relatively low)
                                    local bDeferForAnotherZoneOrLater = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build a nuke, or leave it for antoher zone furhteraway to build, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]='..tostring(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) end
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < math.min(6, 2 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then

                                        local iCurBaseFromEnemyDist = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist to enemy base='..iCurBaseFromEnemyDist) end
                                        if iCurBaseFromEnemyDist <= 800 then
                                            local iFurtherestCoreBaseFromEnemyDist = iCurBaseFromEnemyDist
                                            for iCorePlateau, tZones in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau] do
                                                for iCoreZone, bCoreZone in tZones do
                                                    if not(iCorePlateau == iPlateauOrZero and iCoreZone == iLandOrWaterZone) then
                                                        local tCoreLZData = AiBotMap.tAllPlateaus[iCorePlateau][AiBotMap.subrefPlateauLandZones][iCoreZone]
                                                        if tCoreLZData then
                                                            local tCoreLZTeamData = tCoreLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering alternative iCorePlateau='..iCorePlateau..'; iCoreZone='..iCoreZone..'; tCoreLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tCoreLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tCoreLZTeamData[AiBotMap.subrefLZSValue]='..(tCoreLZTeamData[AiBotMap.subrefLZSValue] or 'nil')) end
                                                            if not(tCoreLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and (tCoreLZTeamData[AiBotMap.subrefLZSValue] or 0) >= 15000 then
                                                                local iDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(tCoreLZData[AiBotMap.subrefMidpoint], tCoreLZTeamData[AiBotMap.reftClosestEnemyBase])
                                                                if bDebugMessages == true then LOG(sFunctionRef..': iDistToEnemy for this core base='..iDistToEnemy) end
                                                                if iDistToEnemy > iCurBaseFromEnemyDist then
                                                                    iCurBaseFromEnemyDist = iDistToEnemy
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if iCurBaseFromEnemyDist > iCurBaseFromEnemyDist + 50 then
                                                bDeferForAnotherZoneOrLater = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have another zone that is further away from the enemy than this zone so want to not build a nuke here so that zone cna potentially build a nuke') end
                                            end
                                        end
                                    end
                                    local iHighestNukeTargetValue = AiBotBuilding.GetHighestNukeTargetValue(tLZOrWZData, tLZOrWZTeamData, aiBrain.AiBotTeam)
                                    local iValueAdjust = 0
                                    if bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats then iValueAdjust = 10000
                                        --If we have built lots of experimentals be more likely to consider a nuke for lower value targets
                                    elseif iTeamNukes == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 then iValueAdjust = -1000 * math.min((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] or 0) - 2, 10)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iHighestNukeTargetValue='..iHighestNukeTargetValue..'; Team gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; iValueAdjust='..iValueAdjust) end
                                    if iHighestNukeTargetValue >= (20000 + iValueAdjust) * iExpConstructedFactor and (iHighestNukeTargetValue >= (30000 + iValueAdjust)*iExpConstructedFactor or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 550 + 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to get a normal nuke') end
                                        iCategoryWanted = AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL
                                    elseif aiBrain[AiBotEconomy.refbBuiltParagon] and iTeamLandExperimentals >= 3 and (iHighestNukeTargetValue >= 10000 or iTeamLandExperimentals >= math.min(7, 4 + iTeamNukes)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want more nukes as have a paragon') end
                                        iCategoryWanted = AiBotUnitInfo.refCategorySML - categories.EXPERIMENTAL
                                    end
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished considering all faction land exp and nuke builders, is iCategoryWanted nil='..tostring(iCategoryWanted == nil)) end
                --Have paragon on team - have a % hcance we will get a land or air experimental (to avoid risk we get overwhelmed) - also do it randomly between the two, so harder for enemy to hard-counter (e.g. mass asf to counter air exp, or mass gunship to counter land exp)
                if not(iCategoryWanted) and aiBrain[AiBotEconomy.refbBuiltParagon] then
                    local iRand = math.random(1,4)
                    if bDebugMessages == true then LOG(sFunctionRef..': Exp re paragon - % chance of building mobile experimental, iRand='..iRand) end
                    if iRand == 3 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and tLZOrWZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) then
                        iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental
                        if bDebugMessages == true then LOG(sFunctionRef..': Will get land experimental') end
                    elseif iRand >= 3 then
                        if bDebugMessages == true then LOG(sFunctionRef..': will get air experimental') end
                        iCategoryWanted = (AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.STRUCTURE - categories.TRANSPORTFOCUS
                    end
                end

                --Small % chance of T3 arti early on (10km+ maps) to mix things up for Cybran, aeon, and (if no air control) seraphim; i.e. not intended to be optimal, but just not so bad of a move that it might make enemy trip up if they expect AiBot to paly a particular way
                if not(iCategoryWanted) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 3 and not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(aiBrain[AiBotOverseer.refbPrioritiseLand]) and not(aiBrain[AiBotOverseer.refbPrioritiseAir]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and AiBotMap.iMapSize >= 512 then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 3 then
                        if not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF]) and (not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) or not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl])) then
                            local iChance = 5 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] * 5
                            if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] then iChance = iChance * 0.5
                            elseif tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] then iChance = iChance * 1.5
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering small random % chance of getting t3 arti, iChance='..iChance) end
                            if math.random(1,100) <= iChance then
                                iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and get t3 arti') end
                            end
                        end
                    end
                end
                if not(iCategoryWanted) then

                    --Check if we have gameender under construction anywhere, and if we want to consider another
                    local bEnemyHasExperimentalShields = false --support for mods that add experimental shields that make certain units like the ahwassa and fatboy much less effective
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield, oUnit.UnitId) then
                                bEnemyHasExperimentalShields = true
                                break
                            end
                        end
                    end

                    local bDontConsiderGameEnderInMostCases = false
                    local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, false, nil, AiBotUnitInfo.refCategoryGameEnder)
                    if iOtherLandZonesWithExperimental > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400 and iMassToComplete <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] * 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 80 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or iMassToComplete >= 90000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < math.max(5, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 2.25)) then
                        bDontConsiderGameEnderInMostCases = true
                    elseif not(AiBotConditions.HaveEcoToSupportGETemplate(iTeam)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 90 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] < 2) then
                        bDontConsiderGameEnderInMostCases = true
                    elseif bEnemyHasExperimentalShields and (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] == 0) and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon]) and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.min(400, 95 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                        --Do we have Aeon or Searphim factories on team? If so then restrict game enders for now
                        if AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionAeon] >= 3
                                or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeAir][AiBotUnitInfo.refFactionAeon] >= 3
                                or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeAir][AiBotUnitInfo.refFactionSeraphim] >= 3
                                or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech][AiBotFactory.refiFactoryTypeLand][AiBotUnitInfo.refFactionSeraphim] >= 3 then
                            bDontConsiderGameEnderInMostCases = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Our land subteam has access to aeon or seraphim tech so want to wait to build these gameenders since they should be better against heavily sheielded targets') end
                        end
                    end
                    --Furhter cases where want to avoid GE template
                    if not(bDontConsiderGameEnderInMostCases) then
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 8 * (0.5 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5) and (bPrioritiseLand or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseLowTech]) then
                            bDontConsiderGameEnderInMostCases = true
                        elseif not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Not defending against arti so decide if we want to have more land exp than enemy, iEnemyClosestLandExperimentalOnSamePlateau='..iEnemyClosestLandExperimentalOnSamePlateau..'; iEnemyExpOnSamePlateau='..iEnemyExpOnSamePlateau..'; iTeamLandExperimentals='..iTeamLandExperimentals..'; iEnemyLandExperimentalCount='..iEnemyLandExperimentalCount) end
                            if iEnemyClosestLandExperimentalOnSamePlateau <= 400 or (bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats and not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) <= 750) then
                                if bDebugMessages == true then LOG(sFunctionRef..': enemy has exp that we are unlikely to handle so dont want to build gameender') end
                                bDontConsiderGameEnderInMostCases = true
                            elseif (iEnemyClosestLandExperimentalOnSamePlateau <= 650 or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iEnemyExpOnSamePlateau >= 3)) and iEnemyExpOnSamePlateau >= 1 and iTeamLandExperimentals < math.min(iEnemyLandExperimentalCount + 2, iEnemyLandExperimentalCount * 2) and bCanPathByLand then
                                if bDebugMessages == true then LOG(sFunctionRef..': We dont have a larger experimental force than the enemy, so hold off on getting gameender for now') end
                                bDontConsiderGameEnderInMostCases = true
                            end
                        end
                    end
                    local iFurthestEnemyBaseDist = 0
                    local iEnemyBasesWithinArtiThreshold = 0
                    local iEnemyBasesOutsideArtiThreshold = 0
                    local iArtiThreshold = 800
                    local iCurBaseDist

                    for iBrain, oBrain in ArmyBrains do
                        if oBrain.AiBotTeam and not(oBrain.AiBotTeam == iTeam) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
                            iCurBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oBrain))
                            if iCurBaseDist <= iArtiThreshold then
                                iEnemyBasesWithinArtiThreshold = iEnemyBasesWithinArtiThreshold + 1
                            else
                                iEnemyBasesOutsideArtiThreshold = iEnemyBasesOutsideArtiThreshold + 1
                            end
                            iFurthestEnemyBaseDist = math.max(iFurthestEnemyBaseDist, iCurBaseDist)
                        end
                    end
                    if not(bDontConsiderGameEnderInMostCases) and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 999 and (iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= math.max(2, 2 * iEnemyBasesOutsideArtiThreshold) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 400) then
                        bDontConsiderGameEnderInMostCases = true
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': We dont want a nuke, so about to consider faction specific logic if we have enough mass, bEnemyHasExperimentalShields='..tostring(bEnemyHasExperimentalShields)..'; bDontConsiderGameEnderInMostCases='..tostring(bDontConsiderGameEnderInMostCases)..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])..'; Is core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])..'; Do we have air control='..tostring(bHaveAirControl)..'; Gunship threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; Bomber threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]..'; Far behind on air='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; iFurthestEnemyBaseDist='..iFurthestEnemyBaseDist..'; iEnemyBasesWithinArtiThreshold='..iEnemyBasesWithinArtiThreshold..'; iEnemyBasesOutsideArtiThreshold='..iEnemyBasesOutsideArtiThreshold..'; Do we have eco to support GE template='..tostring(AiBotConditions.HaveEcoToSupportGETemplate(iTeam))) end

                    --Redundancy - dont build experimentals if we are already (hopefully our build conditions wouldnt trigger if we have low mass anyway though)
                    if AiBotConditions.TeamHasLowMass(iTeam) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 2500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.2 and (iOtherLandZonesWithExperimental > 0 or bHaveExperimentalForThisLandZone) and iTeamLandExperimentals < iEnemyLandExperimentalCount + 1 then
                        if bDebugMessages == true then LOG(sFunctionRef..': We dont have lots of mass so wont build more experimentals') end
                        bDontWantExperimental = true
                    else
                        --LOUD specific (but not QUIET) - t3 arti are cheap enough that want to consider if no significant enemy threats
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want a T3 arti in LOUD, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
                        if AiBotUtilities.bLoudModActive and not(bPrioritiseLand) and not(aiBrain[AiBotOverseer.refbPrioritiseAir]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] <= math.min(8000, AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] * 0.25)))  and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiFriendlyGameEnderCount] < 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                            local iCurT3Arti = 0
                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                iCurT3Arti = iCurT3Arti + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti)
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': LOUD priority t3 arti builder, iCurT3Arti='..iCurT3Arti) end
                            if iCurT3Arti < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                local iLandExpIfRelevant = 0
                                if bCanPathByLand then
                                    for iBrain, oBrain in AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                        iLandExpIfRelevant = iLandExpIfRelevant + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': LOUD priority t3 arti builder: iLandExpIfRelevant='..iLandExpIfRelevant..'; bCanPathByLand='..tostring(bCanPathByLand)..'; iCurT3Arti='..iCurT3Arti) end
                                if not(bCanPathByLand) or iLandExpIfRelevant >= iCurT3Arti + 1 or ((iCurT3Arti == 0 or iLandExpIfRelevant >= 1) and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] <= math.min(8000, AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] * 0.25)) then
                                    local tEnemyBuildingsInRange = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure, tLZOrWZData[AiBotMap.subrefMidpoint], 825, 'Enemy')
                                    if AiBotUtilities.IsTableEmpty(tEnemyBuildingsInRange) == false then
                                        local iMassOfNearbyEnemies = AiBotUnitInfo.GetMassCostOfUnits(tEnemyBuildingsInRange, true)
                                        if bDebugMessages == true then LOG(sFunctionRef..': LOUD priority t3 arti builder: iMassOfNearbyEnemies='..iMassOfNearbyEnemies) end
                                        if iMassOfNearbyEnemies >= 10000 and (iCurT3Arti == 0 or iMassOfNearbyEnemies >= math.min(25000, 10000 + iCurT3Arti * 7500)) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to get t3 arti') end
                                            iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                                        end
                                    end
                                end
                            end
                        end
                        --Experimental level shields-  prioritise over normal experimentals
                        if aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] and not(iCategoryWanted) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and (tLZOrWZTeamData[AiBotMap.subrefiExperimentalShieldConstructedCount] or 0) == 0 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 or (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
                            if aiBrain[AiBotOverseer.refiExperimentalShieldCategory] then iCategoryWanted = aiBrain[AiBotOverseer.refiExperimentalShieldCategory]
                            else iCategoryWanted = AiBotUnitInfo.refCategoryFixedShield * categories.EXPERIMENTAL --redundancy
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding if we want to get a category either for LOUD T3 arti, or experimental shield, is iCategoryWanted nil='..tostring(iCategoryWanted == nil)..'; aiBrain[AiBotOverseer.refbCanBuildExperimentalShields]='..tostring(aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] or false)..'; Constructed exp count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; T3 mex count='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]) end

                        if not(iCategoryWanted) then
                            local bGetGameEnderTemplate = false
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]) and iEnemyClosestLandExperimentalOnSamePlateau >= 175 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbUnableToBuildArtiOrGameEnders]) and not(bDontConsiderGameEnderInMostCases) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] >= 1 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] >= 1.5) then
                                if bDebugMessages == true then LOG(sFunctionRef..': want some sort of gameender template if our team doesnt have any active so we have somewhere for our ACU to shelter') end
                                bGetGameEnderTemplate = true
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': deciding if want a gameender template due to enemy T3 arti, bGetGameEnderTemplate='..tostring(bGetGameEnderTemplate)..'; Is table of potential GE templates empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]))..'; iEnemyClosestLandExperimentalOnSamePlateau='..iEnemyClosestLandExperimentalOnSamePlateau..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]) end
                            --LOUD specific - dont get air exp if already have one and can path to enemy by land and enemy has significant MAA threat
                            local bDontGetAirExp = false
                            --AiBotEasy doesnt micro ahwassas well, so prefer ythothas
                            if aiBrain.AiBotEasy and aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and AiBotConditions.GetLifetimeBuildCount(aiBrain, categories.BOMBER * categories.EXPERIMENTAL) >= AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryLandExperimental) then
                                bDontGetAirExp = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Dont want ahwassa yet due to AiBotEasy being used') end
                            elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] >= 20000 and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim])))  and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 10000 + 5000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] >= 8000 and (bCanPathByLand or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide] >= 16000) then
                                if not(AiBotUtilities.bQuietModActive) or not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) then
                                    if not(aiBrain[AiBotOverseer.refbPrioritiseAir]) then
                                        bDontGetAirExp = true
                                    end
                                end
                            end
                            --Experimental shields in game - prioritise gameender type units
                            if not(bDontGetAirExp) then
                                if (bEnemyHasExperimentalShields or aiBrain[AiBotOverseer.refbCanBuildExperimentalShields]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 3 then
                                    local iTeamAirExp = 0
                                    local iTeamGameEnder = 0
                                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                        iTeamAirExp = iTeamAirExp + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL)
                                        iTeamGameEnder = oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGameEnder) + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti) * 0.3
                                        if iTeamAirExp >= 8 then break end
                                    end
                                    if iTeamAirExp >= 8 or iTeamAirExp >= 3 + iTeamGameEnder then bDontGetAirExp = true end
                                end
                                if not(bDontGetAirExp) and AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 120000 then
                                    --We potentially have 3+ Ahwassas (but might also be strat bombers); focus on t3 arti/land exp/gameender in this scenario (for all factions)
                                    local iAhwassaCount = 0
                                    local iExpGunshipCount = 0
                                    local iCurT3ArtiAndNovaxCount = 0
                                    local iGameEnderCount = 0
                                    for iBrain, oBrain in AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                        iGameEnderCount = iGameEnderCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGameEnder)
                                        iAhwassaCount = iAhwassaCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL)
                                        iExpGunshipCount = iExpGunshipCount + 0.5 * oBrain:GetCurrentUnits((AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryCzar) * categories.EXPERIMENTAL)
                                        iCurT3ArtiAndNovaxCount = iCurT3ArtiAndNovaxCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre)
                                    end
                                    --Treat 2 czars/soulrippers as being worth 1 ahwassa
                                    if bDebugMessages == true then LOG(sFunctionRef..': iAhwassaCount='..iAhwassaCount..'; AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurExpBomberThreat]='..AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurExpBomberThreat]..'; iExpGunshipCount='..iExpGunshipCount..'; iCurT3ArtiAndNovaxCount='..iCurT3ArtiAndNovaxCount..'; iGameEnderCount='..iGameEnderCount) end
                                    if (iAhwassaCount >= 3 and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurExpBomberThreat] >= 100000) or (iExpGunshipCount >= 4 and not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim])) then
                                        local iAhwassaOrModGunshipCount = iAhwassaCount + 0.5*iExpGunshipCount
                                        local iMaxAirExpWanted = 2 + iTeamLandExperimentals + iCurT3ArtiAndNovaxCount + iGameEnderCount * 3
                                        if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] then iMaxAirExpWanted = iMaxAirExpWanted + 1
                                        elseif aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                                            iMaxAirExpWanted = iMaxAirExpWanted - 1
                                        end
                                        if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] and iAhwassaCount <= 3 and iMaxAirExpWanted <= iAhwassaCount and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryBomber * categories.BOMBER) <= 5 then iMaxAirExpWanted = iMaxAirExpWanted + 1 end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iMaxAirExpWanted='..iMaxAirExpWanted..'; iAhwassaOrModGunshipCount='..iAhwassaOrModGunshipCount) end
                                        if iAhwassaOrModGunshipCount >= iMaxAirExpWanted then
                                            --Check underconstruction experimentals
                                            local bHaveExperimentalForThisLandZone, iUnderConstructionAirExp = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, nil, nil, AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL)
                                            local bHaveExperimentalForThisLandZone, iUnderConstructionOtherExp = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, nil, nil, AiBotUnitInfo.refCategoryExperimentalLevel - AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont want more air experimentals for now subject to what is under construction, iUnderConstructionAirExp='..iUnderConstructionAirExp..'; iUnderConstructionOtherExp='..iUnderConstructionOtherExp) end
                                            iAhwassaOrModGunshipCount = iAhwassaOrModGunshipCount + iUnderConstructionAirExp
                                            iMaxAirExpWanted = iMaxAirExpWanted + iUnderConstructionOtherExp
                                            if iAhwassaOrModGunshipCount >= iMaxAirExpWanted then
                                                bDontGetAirExp = true
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bDontGetAirExp='..tostring(bDontGetAirExp)..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide]='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyGroundAAThreatNearOurSide]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]..'; Do we have engineers of a faction capable of building paragon='..tostring(((AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionUEF] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionSeraphim] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionAeon] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionCybran] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran])))..'; tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]='..tostring(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen] or false)..'; Paragon LC='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryParagon)..'; Constructed exp count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; T3 mexes in zone='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Mexes in zone='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]..'; Mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; refiLowestUnitCapAdjustmentLevel='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')) end
                            --special case where prioritise aeon for paragon if dealing with core zone
                            if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and (bEnemyHasExperimentalShields or (aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 4)) and (tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon] or tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) and iTeamLandExperimentals >= 2 and not(bDontConsiderGameEnderInMostCases) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 600 and AiBotMap.iMapSize >= 512 then
                                if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon] and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryParagon) == 0 then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                    if bDebugMessages == true then LOG(sFunctionRef..': Getting paragon') end
                                elseif tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] then
                                    iCategoryWanted = AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL
                                    if bDebugMessages == true then LOG(sFunctionRef..': Getting yolona') end
                                end

                                --Get random experimental unit if disabled unit prioritisation (as user would prefer more randomness over specific faction logic
                            elseif ScenarioInfo.Options.AiBotPrioritiseBPs == 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 and math.random(1,2) == 1 then
                                if bPrioritiseLand and math.random(1,3) <= 2 then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental
                                elseif aiBrain[AiBotOverseer.refbPrioritiseAir] or not(bCanPathAmphibiously) then
                                    if aiBrain[AiBotOverseer.refbPrioritiseAir] and math.random(1,2) == 1 then
                                        iCategoryWanted = AiBotUnitInfo.refCategoryAirNonScout * categories.EXPERIMENTAL
                                        if bDebugMessages == true then LOG(sFunctionRef..': Not prioritising units but are an air brain so will just get experimental air level unit') end
                                    else
                                        iCategoryWanted = AiBotUnitInfo.refCategoryAirNonScout * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryExperimentalStructure
                                        if bDebugMessages == true then LOG(sFunctionRef..': Not prioritising units but either are air brain or cant path amphibiously so will just get experimental building or air') end
                                    end
                                else
                                    iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalLevel - categories.TRANSPORTATION
                                    if bDebugMessages == true then LOG(sFunctionRef..': Not prioritising units so will just get experimental level unit') end
                                end
                                --Exclude game-enders
                                if bDontConsiderGameEnderInMostCases then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will exclude gameenders from the random experimental unit') end
                                    iCategoryWanted = iCategoryWanted - AiBotUnitInfo.refCategoryGameEnder
                                end
                                --Exclude experimental PD
                                iCategoryWanted = iCategoryWanted - AiBotUnitInfo.refCategoryPD
                                --Paragon for LOUD/QUIET (where late-game goes on for longer and RAS SACUs arent as good)
                            elseif not(AiBotUtilities.bFAFActive) and not(bDontConsiderGameEnderInMostCases) and not(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]) and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 1250 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 5 and ((AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionUEF] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionSeraphim] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionAeon] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon]) or (AiBotUnitInfo.tbFactionHasParagon[AiBotUnitInfo.refFactionCybran] and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 3 + 4 * AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryParagon) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.9 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 then
                                iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to try and get a resource generator') end

                                --FACTION SPECIFIC LOGIC
                                --UEF EXPERIMENTAL CHOICE
                            elseif tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF] then
                                --Decide between fatboy and novax, or (with v.high eco) mavor
                                iFactionRequired = AiBotUnitInfo.refFactionUEF
                                local iCurFatboyCount = 0
                                local iCurNovaxCount = 0
                                local iCurT3ArtiCount = 0 --mavor treated as 3 t3 arti
                                local iLandExpCount = 0
                                local iUEFLandExpCategory
                                if not(ScenarioInfo.Options.AiBotPrioritiseBPs == 2) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= math.min(1.5, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryFatboy) >= 2) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to get a fatboy rather than just any land experimental') end
                                    iUEFLandExpCategory = AiBotUnitInfo.refCategoryFatboy - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to get any UEF land exp instead of just a fatboy') end
                                    iUEFLandExpCategory = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                end

                                local bCanBuildNovax = AiBotBuilding.bNovaxInGame and not(AiBotUnitInfo.IsUnitRestricted('xeb2402', aiBrain:GetArmyIndex()))
                                --How many fatboys do we have on the subteam already?
                                for iBrain, oBrain in AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                    iCurFatboyCount = iCurFatboyCount + oBrain:GetCurrentUnits(iUEFLandExpCategory)
                                    iLandExpCount = iLandExpCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental)
                                    iCurNovaxCount = iCurNovaxCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNovaxCentre)
                                    iCurT3ArtiCount = iCurT3ArtiCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti) + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryExperimentalArti) * 3
                                end
                                local bWantNovaxInsteadOfArti = false
                                if iCurNovaxCount == 0 and bCanBuildNovax and (aiBrain[AiBotOverseer.refbPrioritiseAir] or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryNovaxCentre) <= 2) then
                                    bWantNovaxInsteadOfArti = true
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering UEF specific, bCanBuildNovax='..tostring(bCanBuildNovax)..'; iCurFatboyCount='..iCurFatboyCount..'; iCurNovaxCount='..iCurNovaxCount..'; iCurT3AritCount='..iCurT3ArtiCount) end
                                if bCanPathByLand then
                                    if bPrioritiseLand then
                                        iCategoryWanted = iUEFLandExpCategory
                                    elseif bCanBuildNovax and aiBrain[AiBotOverseer.refbPrioritiseAir] then
