                                        iCategoryWanted = iUEFLandExpCategory
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will get fatboy1') end
                                        --Game-ender for late game scenarios where enemy has their own arti and as a team we have already tried building a number of experimentals
                                    elseif not(bDontConsiderGameEnderInMostCases) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 170 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 200 and iCurT3ArtiCount <= AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] and iTeamLandExperimentals >= 2 and (not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 12000) and AiBotMap.iMapSize >= 512 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryGameEnder) == 0 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel) >= 2 * (1.5 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                                        if bWantNovaxInsteadOfArti then
                                            iCategoryWanted = AiBotUnitInfo.refCategoryNovaxCentre
