                                        else
                                            if not(bDontGetAhwassa) and (bDontConsiderGameEnderInMostCases or (iAhwassaCount < 1 + iGameEnderCount * 3 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL) <= 2 + iGameEnderCount * 3)) or (bEnemyHasExperimentalShields and iAhwassaCount >= math.max(1, 2 * iEnemyLandExperimentalCount)) then
                                                iCategoryWanted = AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want ahwassa') end
                                            else
                                                iCategoryWanted = AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL
                                                if bDebugMessages == true then LOG(sFunctionRef..': decided to get a yolona') end
                                            end
                                        end
                                    else
                                        --We arent defending against arti (or if we are we have a more urgent enemy land exp threat), and dont have lots of ahwassa and land exp, so build either exp bomber or ythotha
                                        --If have 5+ land experimentals then consider an ahwassa even if lack air control
                                        if not(bDontGetAhwassa) and (iAhwassaCount + 1) * 2 + 3 < iTeamLandExperimentals then
                                            iCategoryWanted = AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get another exp bomber') end
                                        else
                                            iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                            bGettingNonUEFLandExp = true
                                            --If have Cybran then get megalith in preference to ythotha
                                            if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran] then
                                                iFactionRequired = AiBotUnitInfo.refFactionCybran
                                                iCategoryWanted = iCategoryWanted - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                                if categories.url0402 then iCategoryWanted = iCategoryWanted - categories.url0402 end

                                                --If have Aeon then get GC in preference to Ythotha
                                            elseif tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon] then iFactionRequired = AiBotUnitInfo.refFactionAeon end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get a ythotha, unless we have Cybran/aeon engis in which case will get Cybran/aeon') end
                                        end
                                    end
                                end
                            elseif tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran] then
                                iFactionRequired = AiBotUnitInfo.refFactionCybran
                                --If cant path to enemy with amphibious (rather than land), or enemy is building t3 arti, then consider T3 arti
                                local iCurAirExperimentals = 0
                                for iBrain, oBrain in AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                    iCurAirExperimentals = iCurAirExperimentals + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar)
                                end
                                local bAirExpForThisZone, iOtherLandZonesWithAirExperimental, AiriMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, false, nil, AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar, nil, nil, aiBrain.AiBotAirSubteam)
                                iCurAirExperimentals = iCurAirExperimentals + iOtherLandZonesWithAirExperimental
                                local iUnderConstructionLandExp = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZOrWZTeamData, iTeam, AiBotUnitInfo.refCategoryLandExperimental)
                                if aiBrain[AiBotOverseer.refbPrioritiseAir] and not(bDontGetAirExp) then
                                    iCategoryWanted = (AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                    bGettingNonSeraphimAirExp = true
                                elseif bPrioritiseLand and bCanPathAmphibiously then
                                    if ScenarioInfo.Options.AiBotPrioritiseBPs == 2 then --dont want to prioritise certain units
                                        iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR --megalith has better torps
                                        bGettingNonUEFLandExp = true
                                    else
                                        iCategoryWanted = AiBotUnitInfo.refCategoryMegalith - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR --megalith has better torps
                                        bGettingNonUEFLandExp = true
                                    end
                                    --Switch to t3 arti or scathis in some cases (e.g. cant reach enemy by hover; or have lots of land+air exp; or enemy has fatboy)
                                elseif not(bCanPathAmphibiously) or
                                        ((not(bDontConsiderGameEnderInMostCases) or iDistToNearestEnemyBase <= iArtiThreshold) and iTeamLandExperimentals + iCurAirExperimentals * 1.25 >=  math.max(5, iEnemyLandExperimentalCount * 1.25)) or (not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and iTeamLandExperimentals >= 1 and ((AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])) == false) or (aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMegalith) > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])))
                                        or (not(bCanPathByLand) and not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and iDistToNearestEnemyBase >= 650 and iEnemyLandExperimentalCount == 0 and iTeamLandExperimentals + iCurAirExperimentals + iUnderConstructionLandExp > 0) then

                                    --Consider building  then
                                    --Air exp
                                    if not(bDontGetAirExp) and iCurAirExperimentals == 0 and (bHaveAirControl or (not(bFarBehindOnAir) and (iDistToNearestEnemyBase >= 900 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 2 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAllAir * categories.EXPERIMENTAL) == 0))) then
                                        bGettingNonSeraphimAirExp = true
                                        iCategoryWanted = AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                        iFactionRequired = nil
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cybr want exp air') end
                                    elseif iDistToNearestEnemyBase <= iArtiThreshold and (bDontConsiderGameEnderInMostCases or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 90 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                                        if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti) < 4 then
                                            iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                                            iFactionRequired = nil
                                            if bDebugMessages == true then LOG(sFunctionRef..': Fixed T3 arti 8 Cyb') end
                                        else
                                            iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalStructure --i.e. scathis
                                            if bDebugMessages == true then LOG(sFunctionRef..': Cybr want exp structure') end
                                        end
                                    else
                                        iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalStructure --this includes scathis
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cybr want an exp structure') end
                                    end
                                else
                                    --Consider air experimental in some rarer cases late game
                                    local bGetAirExperimentalInstead = false
                                    if not(bDontGetAirExp) and (bEnemyHasFatboys and iTeamLandExperimentals >= 1) or (iTeamLandExperimentals >= 2 and (iTeamLandExperimentals >= 5 or (iTeamLandExperimentals >= 3 and (bHaveAirControl or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000)) or (iTeamLandExperimentals <= 2 and (bHaveAirControl and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000)))) then
                                        if iCurAirExperimentals == 0 or (bEnemyHasFatboys and (iCurAirExperimentals <= math.max(1, iTeamLandExperimentals) or iCurAirExperimentals * 10000 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat])) or (iCurAirExperimentals * 2.5 < iTeamLandExperimentals and (iCurAirExperimentals + 1) * 10000 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]) then
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] <= 15 or bHaveAirControl then
                                                bGetAirExperimentalInstead = true
                                            end
                                        end
                                    end
                                    if bGetAirExperimentalInstead then
                                        bGettingNonSeraphimAirExp = true
                                        iCategoryWanted = AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cybr will get exp air') end
                                    elseif not(bCanPathByLand) then
                                        if ScenarioInfo.Options.AiBotPrioritiseBPs == 2 then --dont want to prioritise certain units
                                            iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR --megalith has better torps
                                            bGettingNonUEFLandExp = true
                                        else
                                            iCategoryWanted = AiBotUnitInfo.refCategoryMegalith - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR --megalith has better torps
                                            bGettingNonUEFLandExp = true
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Cybr will get mega') end
                                    else
                                        if iTeamLandExperimentals == 0 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) < 2 then
                                            iCategoryWanted = AiBotUnitInfo.refCategoryMonkeylord - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                            bGettingNonUEFLandExp = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Cybr will get monkey') end
                                        else
                                            --Get megalith
                                            iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR --i.e. megalith (but slightly more helpful to mods doing it this way)
                                            if categories.url0402 then iCategoryWanted = iCategoryWanted - categories.url0402 end
                                            bGettingNonUEFLandExp = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Cybr will get non monkey land exp') end
                                        end
                                    end
                                end
                            elseif tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionAeon] then
                                iFactionRequired = AiBotUnitInfo.refFactionAeon
                                local iCurAirExperimentals = 0
                                for iBrain, oBrain in AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                    iCurAirExperimentals = iCurAirExperimentals + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar)
                                end
                                local bAirExpForThisZone, iOtherLandZonesWithAirExperimental, AiriMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, false, nil, AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar, nil, nil, aiBrain.AiBotAirSubteam)
                                local iCurT3ArtiCount = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti) + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryExperimentalArti) * 3
                                local iLifetimeAirExpCount = AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL)
                                local iLifetimeGroundExpCount =  AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental)
                                local iUnderConstructionLandExp = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZOrWZTeamData, iTeam, AiBotUnitInfo.refCategoryLandExperimental)
                                local bHaveLargeBuildAreaAvailable = false
                                if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][24] or 0) > 0 then
                                    bHaveLargeBuildAreaAvailable = true
                                end
                                iCurAirExperimentals = iCurAirExperimentals + iOtherLandZonesWithAirExperimental

                                local iEnemyT3ArtiEquivalent = AiBotConditions.GetEnemyT3ArtiEquivalent(iTeam, 0.4, 3, true, nil)
                                local iFriendlyGameEnderUnderConstruction = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZOrWZTeamData, iTeam, AiBotUnitInfo.refCategoryGameEnder)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering aeon specific experimental, iCurAirExperimentals='..iCurAirExperimentals..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Land exp='..iTeamLandExperimentals..'; iFriendlyGameEnderUnderConstruction='..iFriendlyGameEnderUnderConstruction..'; iEnemyT3ArtiEquivalent='..iEnemyT3ArtiEquivalent..'; refbDefendAgainstArti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or false)..'; iEnemyLandExperimentalCount='..iEnemyLandExperimentalCount..'; Our gunship threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]..'; iOur bomber threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]..'; iLifetimeAirExpCount='..iLifetimeAirExpCount..'; iLifetimeGroundExpCount='..iLifetimeGroundExpCount..'; bHaveLargeBuildAreaAvailable='..tostring(bHaveLargeBuildAreaAvailable)..'; iUnderConstructionLandExp='..iUnderConstructionLandExp) end

                                if aiBrain[AiBotOverseer.refbPrioritiseAir] and not(bDontGetAirExp) then
                                    bGettingNonSeraphimAirExp = true
                                    iCategoryWanted = (AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                elseif bPrioritiseLand and bCanPathAmphibiously then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                    bGettingNonUEFLandExp = true
                                elseif not(bDontGetAirExp) and bHaveLargeBuildAreaAvailable and ((iLifetimeGroundExpCount >= 4 and iLifetimeAirExpCount < iLifetimeGroundExpCount / 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 4) or (not(bCanPathByLand) and iEnemyLandExperimentalCount <= iTeamLandExperimentals + iUnderConstructionLandExp)) and (bHaveAirControl or (not(bFarBehindOnAir) and AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] <= 20) or AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] <= 8) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have built lots of exp but havent tried many czars so will get some even if we lack air control') end
                                    bGettingNonSeraphimAirExp = true
                                    iCategoryWanted = AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and (iCurAirExperimentals + iTeamLandExperimentals > (iFriendlyGameEnderUnderConstruction + iCurT3ArtiCount) or iCurAirExperimentals + iTeamLandExperimentals > 0 and iEnemyT3ArtiEquivalent > 0) then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to get salvation due to high mass') end
                                    --Do we want to get t3 arti or gameender?
                                elseif not(bCanPathAmphibiously) or
                                        (not(bCanPathByLand) and iDistToNearestEnemyBase >= 650 and ((iDistToNearestEnemyBase >= 1000 and not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats)) or (iEnemyLandExperimentalCount == 0 and iTeamLandExperimentals + iCurAirExperimentals + iUnderConstructionLandExp > 0))) or
                                        ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iLifetimeGroundExpCount + iLifetimeAirExpCount >= 5) and
                                                ((not(bDontConsiderGameEnderInMostCases) or iDistToNearestEnemyBase <= iArtiThreshold) and (iTeamLandExperimentals + iCurAirExperimentals * 1.6 >= math.max(3, iEnemyLandExperimentalCount + 1) or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and iTeamLandExperimentals + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] / 15000 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0)) / 15000 >= math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5, iEnemyLandExperimentalCount)))) or
                                                (not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and (not(bDontConsiderGameEnderInMostCases) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iLifetimeGroundExpCount >= math.max(4, 2 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and (iTeamLandExperimentals >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 110 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))) then

                                    --Consider building Czar
                                    if not(bDontGetAirExp) and bHaveLargeBuildAreaAvailable and iCurAirExperimentals <= iCurT3ArtiCount and (iEnemyT3ArtiEquivalent < 1 or iCurAirExperimentals == 0) and (not(AiBotConditions.TeamIsFarBehindOnAir(iTeam)) or (iEnemyT3ArtiEquivalent == 0 and iCurAirExperimentals == 0 and iLifetimeAirExpCount <= 2) or (iCurT3ArtiCount >= 3 and iCurAirExperimentals == 0 and iLifetimeAirExpCount < iCurT3ArtiCount)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to get some Czars') end
                                        bGettingNonSeraphimAirExp = true
                                        iCategoryWanted = AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                    elseif iDistToNearestEnemyBase <= iArtiThreshold and (bDontConsiderGameEnderInMostCases or iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= 1 + 2 * iEnemyBasesOutsideArtiThreshold or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                                        if iEnemyT3ArtiEquivalent < 4 then
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 then
                                                iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want to get a salvation due to very high mass') end
                                            elseif not(bDontConsiderGameEnderInMostCases) and not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and iFurthestEnemyBaseDist > iArtiThreshold and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= math.max(90, 15 + 70 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.max(250, 30 + 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and iFriendlyGameEnderUnderConstruction == 0 then
                                                iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will get a paragon0 as enemy has a far away base even if it also has a number within range') end
                                            else iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                                                if bDebugMessages == true then LOG(sFunctionRef..': Fixed T3 arti 9 Aeon') end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy base dist is '..iDistToNearestEnemyBase..' so will get T3 arti') end
                                            end
                                        else
                                            if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.max(325, 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and iEnemyT3ArtiEquivalent <= 1.4 and iFriendlyGameEnderUnderConstruction == 0 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will get paragon1; gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; iEnemyT3ArtiEquivalent='..iEnemyT3ArtiEquivalent..'; iFriendlyGameEnderUnderConstruction='..iFriendlyGameEnderUnderConstruction) end
                                                iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                            else
                                                iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will get salvation as mass high enough that not sure we would benefit that much from a paragon') end
                                            end
                                        end
                                    else
                                        if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.max(325, 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and iEnemyT3ArtiEquivalent <= 1.4 and iFriendlyGameEnderUnderConstruction == 0 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to get paragon2; gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; iEnemyT3ArtiEquivalent='..iEnemyT3ArtiEquivalent..'; iFriendlyGameEnderUnderConstruction='..iFriendlyGameEnderUnderConstruction) end
                                            iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                        else
                                            iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                            if bDebugMessages == true then LOG(sFunctionRef..': Have enough mass that will go for a salvation') end
                                        end
                                    end
                                else
                                    --Consider air experimental in some rarer cases late game
                                    local bGetAirExperimentalInstead = false
                                    if not(bDontGetAirExp) and bHaveLargeBuildAreaAvailable and
                                            ((bEnemyHasFatboys and iTeamLandExperimentals >= 1) or
                                                    (iTeamLandExperimentals >= 2 and (iTeamLandExperimentals >= 5 or (iTeamLandExperimentals >= 3 and (bHaveAirControl or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000 or (iCurAirExperimentals == 0 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAllAir * categories.EXPERIMENTAL) == 0))) or (iTeamLandExperimentals <= 2 and (bHaveAirControl and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000))))
                                                    or (iTeamLandExperimentals >= iCurAirExperimentals * 3 and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) or bHaveAirControl) and iTeamLandExperimentals >= math.min(4, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) >= 3 + 3 * AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAllAir * categories.EXPERIMENTAL))) then

                                        if iCurAirExperimentals == 0 or (bEnemyHasFatboys and (iCurAirExperimentals <= math.max(1, iTeamLandExperimentals) or iCurAirExperimentals * 10000 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat])) or  (iCurAirExperimentals * 2.5 < iTeamLandExperimentals and (iCurAirExperimentals + 1) * 10000 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]) or (iCurAirExperimentals < iTeamLandExperimentals and bHaveAirControl) then
                                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.iEnemyT3MAAActiveCount] <= 15 or bHaveAirControl then
                                                bGetAirExperimentalInstead = true
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': We can path to enemy amphibiously so will consider whether to get air or land, bGetAirExperimentalInstead='..tostring(bGetAirExperimentalInstead or false)) end
                                    if bGetAirExperimentalInstead then
                                        bGettingNonSeraphimAirExp = true
                                        iCategoryWanted = AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                    else
                                        --Build GC or paragon or T3 arti (or Czar in some rare cases)
                                        if ((iTeamLandExperimentals >= 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 70) or (iTeamLandExperimentals >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.max(325, 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and iEnemyT3ArtiEquivalent <= 1.4 and iFriendlyGameEnderUnderConstruction == 0 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get paragon3 or T3 arti due to lots of friendly land experimentals; gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; iEnemyT3ArtiEquivalent='..iEnemyT3ArtiEquivalent..'; iFriendlyGameEnderUnderConstruction='..iFriendlyGameEnderUnderConstruction..'; iTeamLandExperimentals='..iTeamLandExperimentals) end
                                            if AiBotMap.iMapSize >= 512 and (AiBotMap.iMapSize >= 1000 or AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFixedT3Arti, iTeam) >= 4) and iFriendlyGameEnderUnderConstruction == 0 then
                                                if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 9500 then
                                                    iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Getting paragon5') end
                                                else
                                                    iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Getting paragon4') end
                                            else
                                                iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                                                if bDebugMessages == true then LOG(sFunctionRef..': Fixed T3 arti 10 Aeon') end
                                            end
                                        elseif not(bEnemyHasDangerousLandExpWeCantHandleOrNearbyThreats) and (iDistToNearestEnemyBase <= iArtiThreshold or not(bDontConsiderGameEnderInMostCases)) and (iTeamLandExperimentals >= math.max(1, aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryGameEnder)) or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental) >= 3) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                            if AiBotMap.iMapSize >= 1000 and iDistToNearestEnemyBase >= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 + 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and iFriendlyGameEnderUnderConstruction == 0 then
                                                if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 9500 then
                                                    iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Getting paragon5') end
                                                else
                                                    iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                                end
                                            else
                                                if (bDontConsiderGameEnderInMostCases or iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= 1 + 2 * iEnemyBasesOutsideArtiThreshold or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                                                    iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Fixed T3 arti 11 Aeon') end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will get paragon or exp arti') end
                                                    if not(AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 60 + 100 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                                        iCategoryWanted = AiBotUnitInfo.refCategoryParagon
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting paragon6') end
                                                    else
                                                        iCategoryWanted = AiBotUnitInfo.refCategoryExperimentalArti
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting rapid fire arti') end
                                                    end
                                                end
                                            end

                                        else
                                            --Dont reset faction requirement as GC is better than most other factions, except cybran
                                            iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                            bGettingNonUEFLandExp = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': want more land experimentals') end
                                            if tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionCybran] then
                                                iFactionRequired = AiBotUnitInfo.refFactionCybran
                                                iCategoryWanted = iCategoryWanted - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                                if categories.url0402 then iCategoryWanted = iCategoryWanted - categories.url0402 end
                                            end
                                        end
                                    end
                                end
                            else
                                --Not dealing with standard faction - basic choice between land and T3 arti/experimental structure, since unlikely to have hte logic in place for other units
                                if aiBrain[AiBotOverseer.refbPrioritiseAir] and not(bDontGetAirExp) then
                                    bGettingNonSeraphimAirExp = true
                                    iCategoryWanted = (AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.ANTIAIR
                                elseif bPrioritiseLand and bCanPathAmphibiously then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                    bGettingNonUEFLandExp = true
                                    --Switch to t3 arti or scathis in some cases (e.g. cant reach enemy by hover; or have lots of land+air exp; or enemy has fatboy)
                                elseif not(bCanPathAmphibiously) then
                                    iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalStructure
                                    local iCurExperimentalsOfType = 0
                                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                        iCurExperimentalsOfType = iCurExperimentalsOfType + oBrain:GetCurrentUnits(iCategoryWanted)
                                    end
                                    if iCurExperimentalsOfType >= 3 + iTeamNukes and (iCurExperimentalsOfType >= 6 + iTeamNukes or iFurthestEnemyBaseDist >= iArtiThreshold) then
                                        iCategoryWanted = AiBotUnitInfo.refCategorySML
                                    end
                                else
                                    --can path to enemy with land
                                    local iBaseAdjust = 0
                                    if iDistToNearestEnemyBase >= 400 then
                                        if iDistToNearestEnemyBase >= iArtiThreshold then iBaseAdjust = -2
                                        else iBaseAdjust = -1
                                        end
                                    end

                                    if iTeamLandExperimentals <= math.max(iEnemyLandExperimentalCount + 2 + iBaseAdjust, 3 + iBaseAdjust) then
                                        iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                        bGettingNonUEFLandExp = true
                                    else
                                        iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalStructure
                                        local iCurExperimentalsOfType = 0
                                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                            iCurExperimentalsOfType = iCurExperimentalsOfType + oBrain:GetCurrentUnits(iCategoryWanted)
                                        end
                                        if iCurExperimentalsOfType >= 3 and iCurExperimentalsOfType <= math.max(4, iTeamLandExperimentals * 2) then
                                            iCategoryWanted = iCategoryWanted + AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR
                                        end
                                    end
                                end
                            end
                            --Switch to GETemplate category if we have picked something else
                            if bGetGameEnderTemplate and not(AiBotUtilities.DoesCategoryContainCategory(iCategoryWanted, AiBotUnitInfo.refCategoryGameEnder)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will switch to gameender template type category, unless are seraphim and havent built any ahwassa yet and want to') end
                                if not(bDontGetAirExp) and iCategoryWanted and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionSeraphim] and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL) == 0 and AiBotUtilities.DoesCategoryContainCategory(categories.xsa0402, iCategoryWanted) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will stick with getting our first air exp after all') end
                                else
                                    iCategoryWanted = AiBotUnitInfo.refCategoryGameEnder
                                end
                            end
                        end
                    end
                end
                --Switch from gameender to T3 arti if enemy has a nearby firebase and the nearest enemy base is within 820 of us (unless we have paragon)
                if iCategoryWanted and AiBotUtilities.DoesCategoryContainCategory(iCategoryWanted, AiBotUnitInfo.refCategoryGameEnder) and (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or (tLZOrWZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) >= 1500) and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) <= 820 then
                    iCategoryWanted = AiBotUnitInfo.refCategoryFixedT3Arti
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has nearby t2 arti so will switch to t3 arti instead of gameender, Fixed T3 arti 12') end
                end
                --Exclude paragon from category wanted if the likely brain already has one
                if aiBrain[AiBotEconomy.refbBuiltParagon] or AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]) then
                    local bExcludeParagon = false
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 then
                        bExcludeParagon = true
                    elseif tLZOrWZTeamData[AiBotMap.refoNearbyExperimentalResourceGen] then
                        bExcludeParagon = true
                    else
                        local bHaveBrainWithoutParagon = false
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            if not(oBrain[AiBotEconomy.refbBuiltParagon]) then bHaveBrainWithoutParagon = true break end
                        end
                        if not(bHaveBrainWithoutParagon) then bExcludeParagon = true end
                    end
                    if bExcludeParagon then
                        if iCategoryWanted == AiBotUnitInfo.refCategoryParagon then iCategoryWanted = AiBotUnitInfo.refCategoryGameEnder end
                        iCategoryWanted = iCategoryWanted - AiBotUnitInfo.refCategoryParagon
                        if bDebugMessages == true then LOG(sFunctionRef..': Switching from paragon to gameender') end
                    end
                end
                --Replace T3 arti with gameender if we have paragon
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and iCategoryWanted == AiBotUnitInfo.refCategoryFixedT3Arti and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 150 then
                    iCategoryWanted = AiBotUnitInfo.refCategoryGameEnder - AiBotUnitInfo.refCategoryParagon
                    if bDebugMessages == true then LOG(sFunctionRef..': Switching from t3 arti to gameender excl paragon due to high mass') end
                end


                --Check if we want to switch to using a gameender template
                if iCategoryWanted and not(aiBrain[AiBotOverseer.refbCanBuildExperimentalShields]) then
                    if AiBotUtilities.DoesCategoryContainCategory(iCategoryWanted, iGameEnderTemplateCategories) then
                        --Do we have the eco to support this many shields? and have we built a decent number of experimentals if using LOUD mod

                        --DO we have a template available?
                        if AiBotConditions.HaveEcoToSupportGETemplate(aiBrain.AiBotTeam) and AiBotConditions.HaveTemplateSpaceForGameEnder(iCategoryWanted, tLZOrWZData, tLZOrWZTeamData, tbEngineersOfFactionOrNilIfAlreadyAssigned, aiBrain.AiBotTeam) and not(aiBrain.AiBotEasy) then
                            if bDebugMessages == true then
                                local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrZero, iLandOrWaterZone, true, 500, AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovax + AiBotUnitInfo.refCategoryGameEnder, nil, nil, aiBrain.AiBotAirSubteam)
                                LOG(sFunctionRef..': Considering if should get GE template since are building a unit that features in a GE template, bHaveExperimentalForThisLandZone='..tostring(bHaveExperimentalForThisLandZone)..'; iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; iMassToComplete='..iMassToComplete)
                            end
                            --If we have unit prioritisation disabled, then we may have arrived here just because we want to build any experimental level unit; in which case add a % chance of not doing GE template based on how many exp we have built
                            local bDontSwitch = false
                            if ScenarioInfo.Options.AiBotPrioritiseBPs == 2 and AiBotUtilities.DoesCategoryContainCategory(iCategoryWanted, AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryAirNonScout * categories.EXPERIMENTAL) then
                                local iCurGameEnderCount = AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryGameEnder, iTeam)
                                local iCurLandAndAirExpCount = AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryAirNonScout * categories.EXPERIMENTAL, iTeam)
                                local iThreshold
                                if iCurLandAndAirExpCount < iCurGameEnderCount then
                                    iThreshold = 90
                                elseif iCurLandAndAirExpCount >= 5 and iCurGameEnderCount == 0 then
                                    iThreshold = 10
                                else
                                    iThreshold = iCurGameEnderCount * 300 / (iCurGameEnderCount * 3 + iCurLandAndAirExpCount)
                                end
                                if iThreshold and math.random(1, 100) < iThreshold then bDontSwitch = true end
                                if bDebugMessages == true then LOG(sFunctionRef..': We just want any experimental, which might include a gameender, so reducing chance of building GE template, iThreshold='..(iThreshold or 'nil')..'; iCurLandAndAirExpCount='..iCurLandAndAirExpCount..'; iCurGameEnderCount='..iCurGameEnderCount..'; bDontSwitch='..tostring(bDontSwitch or false)) end
                            end

                            --Novax exception - dont apply GE template if we arent defending from arti and we dont have any novax yet
                            if not(bDontSwitch) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or ((not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 + 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (not(iCategoryWanted == AiBotUnitInfo.refCategoryNovaxCentre) or not(tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF]) or AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryNovaxCentre, iTeam) > 0)) then
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': We have template space for gameender so will switch to gameender template action instead of building the category; will first list out all the blueprints buildable under the orig category wanted')
                                    local tBlueprints = EntityCategoryGetUnitList(iCategoryWanted)
                                    LOG('Blueprints='..repru(tBlueprints))
                                    LOG(sFunctionRef..': Will now list out the blueprints in the gameender categories which also satisfy icategorywanted, if any')
                                    local tGEBlueprints = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre)
                                    for iBlueprint, sBlueprint in tGEBlueprints do
                                        if EntityCategoryContains(iCategoryWanted, sBlueprint) then
                                            LOG(sFunctionRef..': Blueprint in both categories='..sBlueprint..'; Name='..(__blueprints[sBlueprint].General.UnitName or 'nil'))
                                        end
                                    end
                                end

                                --Reset category to only be those that contain both categories
                                local tGEBlueprints
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] then
                                    --If have paragon then want to prioritise things like rapid fire arti over t3 arti or a second paragon
                                    tGEBlueprints = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryNovaxCentre - AiBotUnitInfo.refCategoryParagon)
                                else
                                    tGEBlueprints = EntityCategoryGetUnitList(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre)
                                end
                                local iRevisedCategory
                                if AiBotUtilities.IsTableEmpty(tGEBlueprints) == false then
                                    for iBlueprint, sBlueprint in tGEBlueprints do
                                        if EntityCategoryContains(iCategoryWanted, sBlueprint) then
                                            if not(iRevisedCategory) then iRevisedCategory = categories[sBlueprint]
                                            else iRevisedCategory = iRevisedCategory + categories[sBlueprint]
                                            end
                                        end
                                    end
                                end

                                iGameEnderTemplateCategory = iRevisedCategory or iCategoryWanted
                                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = iGameEnderTemplateCategory
                                iCategoryWanted = refActionManageGameEnderTemplate
                            elseif bDebugMessages == true then LOG(sFunctionRef..': Building our first novax so wont use ge template as enemy doesnt have any arti to defend from yet; or  bDontSwitch is true')
                            end
                        end
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= math.max(4, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 2) or AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                        --We dont want a GE template; exclude very high mass cost blueprints if we have multiple options to build from the category wanted for each faction and we have built fewer than 3 experimentals
                        local tsBlueprintsOfCategory = EntityCategoryGetUnitList(iCategoryWanted)
                        if AiBotUtilities.IsTableEmpty(tsBlueprintsOfCategory) == false then
                            local iMaxMassCostThreshold = math.max(25000 + 15000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] * 80)
                            local iMinMassCostThreshold = math.min(17000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] * 9000)
                            --Adjust thresholds if not prioritising
                            if ScenarioInfo.Options.AiBotPrioritiseBPs == 2 then
                                iMaxMassCostThreshold = iMaxMassCostThreshold * 1.5
                                iMinMassCostThreshold = iMinMassCostThreshold * 0.65
                            end
                            if iMaxMassCostThreshold < 180000 then
                                local iCurMassThreshold
                                local iCurMinMassThreshold, bHaveOptionAboveMinMassThreshold
                                local tsBlueprintsAndMassCostByFaction = {}
                                local iCurBlueprintFaction
                                local oCurBlueprint
                                if bDebugMessages == true then LOG(sFunctionRef..': iMaxMassCostThreshold='..iMaxMassCostThreshold..'; Team gross mass income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
                                for iBlueprint, sBlueprint in tsBlueprintsOfCategory do
                                    oCurBlueprint = __blueprints[sBlueprint]
                                    iCurBlueprintFaction = AiBotUnitInfo.GetFactionNumberFromBlueprint(sBlueprint)
                                    if not(tsBlueprintsAndMassCostByFaction[iCurBlueprintFaction]) then tsBlueprintsAndMassCostByFaction[iCurBlueprintFaction] = {} end
                                    table.insert(tsBlueprintsAndMassCostByFaction[iCurBlueprintFaction], { sBlueprint, (oCurBlueprint.Economy.BuildCostMass or 0) })
                                end
                                local bHaveLowCostOption, bHaveHighCostOption, bPotentialOption
                                --local sCheapestBlueprint
                                local iCheapestBlueprint = 10000000
                                local iMostExpensiveBlueprint = 0
                                for iFaction, tSubtable in tsBlueprintsAndMassCostByFaction do
                                    iCheapestBlueprint = 10000000
                                    iMostExpensiveBlueprint = 0

                                    iCurMassThreshold = iMaxMassCostThreshold
                                    iCurMinMassThreshold = iMinMassCostThreshold
                                    bHaveLowCostOption = false
                                    bHaveHighCostOption = false
                                    bHaveOptionAboveMinMassThreshold = false
                                    for iEntry, tBlueprintAndMassCost in tSubtable do
                                        bPotentialOption = false
                                        --Is this a non-naval unit, or (if in a water zone) is it a naval unit?
                                        if iPlateauOrZero == 0 then
                                            if EntityCategoryContains(categories.NAVAL, tBlueprintAndMassCost[1]) then
                                                bPotentialOption = true
                                            end
                                        else
                                            if not(EntityCategoryContains(categories.NAVAL, tBlueprintAndMassCost[1])) then
                                                bPotentialOption = true
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering blueprint='..tBlueprintAndMassCost[1]..' for iFaction='..iFaction..'; Mass cost='..tBlueprintAndMassCost[2]..'; bPotentialOption='..tostring(bPotentialOption)) end
                                        if bPotentialOption then
                                            if tBlueprintAndMassCost[2] <= iMaxMassCostThreshold then bHaveLowCostOption = true elseif tBlueprintAndMassCost[2] > iMaxMassCostThreshold then bHaveHighCostOption = true end
                                            if tBlueprintAndMassCost[2] < iCheapestBlueprint then
                                                iCheapestBlueprint = tBlueprintAndMassCost[2]
                                                --sCheapestBlueprint = tBlueprintAndMassCost[1]
                                            end
                                            if tBlueprintAndMassCost[2] > iMostExpensiveBlueprint then iMostExpensiveBlueprint = tBlueprintAndMassCost[2] end
                                            if tBlueprintAndMassCost[2] >= iMinMassCostThreshold then bHaveOptionAboveMinMassThreshold = true end
                                            if bHaveLowCostOption and bHaveHighCostOption and bHaveOptionAboveMinMassThreshold then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have both low and high cost options so aborting loop') end
                                                break
                                            end
                                        end
                                    end
                                    local bForcedLowCostOption = false
                                    if not(bHaveLowCostOption and bHaveHighCostOption) and iCheapestBlueprint then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Increasing mass threshold as couldnt find anything to build under default threshold, iMaxMassCostThreshold pre increase='..iMaxMassCostThreshold..'; iCheapestBlueprint='..iCheapestBlueprint) end
                                        iCurMassThreshold = math.max(iCheapestBlueprint * 1.2, 28000)
                                        bForcedLowCostOption = true
                                    end
                                    if not(bHaveOptionAboveMinMassThreshold) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Decreasing min mass threshold as couldnt find anything to build that cost enough') end
                                        iCurMinMassThreshold = math.min(20000, iMostExpensiveBlueprint * 0.6)
                                    end
                                    if bHaveOptionAboveMinMassThreshold and ((bHaveLowCostOption and bHaveHighCostOption) or bForcedLowCostOption) then
                                        for iEntry, tBlueprintAndMassCost in tSubtable do
                                            if tBlueprintAndMassCost[2] > iCurMassThreshold then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Removing blueprint '..tBlueprintAndMassCost[1]..' from the categories wanted as it costs too much being '..tBlueprintAndMassCost[2]..'; iFaction='..iFaction) end
                                                iCategoryWanted = iCategoryWanted - categories[tBlueprintAndMassCost[1]]
                                            elseif tBlueprintAndMassCost[2] < iCurMinMassThreshold then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Removing blueprint '..tBlueprintAndMassCost[1]..' from the categories wanted as it costs too little being '..tBlueprintAndMassCost[2]..'; iFaction='..iFaction..'; iCurMinMassThreshold='..iCurMinMassThreshold) end
                                                iCategoryWanted = iCategoryWanted - categories[tBlueprintAndMassCost[1]]
                                            end
                                        end
                                        --Exclude options that cost too little
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished main logic for choosing experimental, is iCategoryWanted nil='..tostring(iCategoryWanted == nil)..'; P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; bGettingNonSeraphimAirExp='..tostring(bGettingNonSeraphimAirExp)..'; bGettingNonUEFLandExp='..tostring(bGettingNonUEFLandExp)..'; Mass%='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Exp constructed count='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount]) end
    if not(iCategoryWanted) and not(bDontWantExperimental) then iCategoryWanted = AiBotUnitInfo.refCategoryLandExperimental - iGameEnderTemplateCategories - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR end --redundancy
    if iCategoryWanted == refActionManageGameEnderTemplate and not(tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
        --Redundancy - wouldn't expect to get here
        local iOurT3Arti = 0
        local iOurNovax = 0
        local iOurGameEnder = 0
        for iBrain, oBrain in AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            iOurT3Arti = iOurT3Arti + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti)
            iOurNovax = iOurNovax + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti)
            iOurGameEnder = iOurGameEnder + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryGameEnder)
        end
        local iDistToNearestEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
        local bCanBuildNovax = AiBotBuilding.bNovaxInGame and not(AiBotUnitInfo.IsUnitRestricted('xeb2402', aiBrain:GetArmyIndex()))
        if iDistToNearestEnemyBase >= 750 or (iOurGameEnder > 0 and iOurT3Arti == 0) then
            if bCanBuildNovax and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF] and (iOurNovax == 0 or (iOurNovax < 3 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyArtiAndExpStructure]))) then
                if bDebugMessages == true then LOG(sFunctionRef..': Switching category to novax') end
                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryNovaxCentre
            elseif iOurT3Arti < 3 then
                if bDebugMessages == true then LOG(sFunctionRef..': Switching category to T3 arti') end
                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Switching category to GameEnder') end
                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
            end
        else
            if bCanBuildNovax and tbEngineersOfFactionOrNilIfAlreadyAssigned[AiBotUnitInfo.refFactionUEF] and (iOurNovax == 0 or (iOurNovax < 3 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyArtiAndExpStructure]))) then
                if bDebugMessages == true then LOG(sFunctionRef..': Switching category to novax') end
                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryNovaxCentre
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Switching category to game ender') end
                tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
            end
        end
    elseif not(ScenarioInfo.Options.AiBotPrioritiseBPs == 2) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 then
        if bGettingNonSeraphimAirExp and not(AiBotUtilities.bLoudModActive) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will check if we have Seraphim on our team, and if so will hold off getting a general air experimental') end
            local iTeam = aiBrain.AiBotTeam
            for iBrain, oBrain in AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have seraphim on our team so want to hold off on getting an experimental from this zone') end
                    iCategoryWanted = nil
                end
            end
        elseif bGettingNonUEFLandExp then
            --Do we have UEF on team?
            local bHaveUEFOnTeam
            local iTeam = aiBrain.AiBotTeam
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF and oBrain.AiBotLandSubteam == aiBrain.AiBotLandSubteam then
                    bHaveUEFOnTeam = true
                    if bDebugMessages == true then LOG(sFunctionRef..': We have UEF on our team so want to hold off on getting an experimental from this zone unless we have built similar number of fatboys to other EXPs') end
                end
            end
            if bHaveUEFOnTeam and not(AiBotOverseer.bUnitRestrictionsArePresent) and categories.uel0401 and not(AiBotMap.bIsCampaignMap) then
                local iFatboyLC = AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryFatboy)
                local iAllLandExpLC = AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental)
                if (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or iAllLandExpLC - iFatboyLC >= 1) and (iFatboyLC <= (iAllLandExpLC - iFatboyLC) or (aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFatboy) == 0 and iFatboyLC <= 1 + (iAllLandExpLC - iFatboyLC) * 2)) then
                    iCategoryWanted = nil
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iFatboyLC='..iFatboyLC..'; iAllLandExpLC='..iAllLandExpLC..'; Is iCategoryWanted nil now='..tostring(iCategoryWanted == nil)) end
            end
        end
    end
    --Flag if we need SACUs
    if iCategoryWanted and not(iCategoryWanted == refActionManageGameEnderTemplate) then
        local tsBlueprintsOfCategory = EntityCategoryGetUnitList(iCategoryWanted)
        if tsBlueprintsOfCategory then
            local bCanBuildWithT3Engi = false
            for iBlueprint, sBlueprint in tsBlueprintsOfCategory do
                if EntityCategoryContains(categories.BUILTBYTIER3ENGINEER, sBlueprint) then
                    bCanBuildWithT3Engi = true
                    break
                end
            end
            if not(bCanBuildWithT3Engi) then tLZOrWZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] = GetGameTimeSeconds() end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, will list out all blueprints meeting iCategoryWanted. iFactionRequired='..(iFactionRequired or 'nil')..'; iCategoryWanted=nil='..tostring(iCategoryWanted == nil))
        if iCategoryWanted then
            if not(iCategoryWanted == refActionManageGameEnderTemplate) then
                local tBlueprints = EntityCategoryGetUnitList(iCategoryWanted)
                local tsBlueprintsAndName = {}
                for _, sBlueprint in tBlueprints do
                    table.insert(tsBlueprintsAndName, sBlueprint..': '..(__blueprints[sBlueprint].General.UnitName or 'nil')..', Faction='..(__blueprints[sBlueprint].General.FactionName or 'Unknown'))
                end
                LOG(sFunctionRef..': Blueprints='..repru(tsBlueprintsAndName))
            else
                LOG(' Are applying GE tempalte logic or want to hold off')
            end
        else
            LOG('Have no category')
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCategoryWanted, iFactionRequired
end

function MonitorToReissueReclaimOrder(oEngineer, oNearestReclaimableEnemy, iDistanceToReissue, iTicksToCheck)
    --Call vai fork thread, intended so e.g. when engineer is approaching an enemy to reclaim, it will start reclaiming hte moment the enemy gets within reclaim range
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorToReissueReclaimOrder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iRemainingTicksToWait = iTicksToCheck
    local iCurDist
    local iEngineerActionRequired = oEngineer[refiAssignedAction]
    local iEngineerPriorityRequired = oEngineer[refiAssignedActionPriority]
    local bGivenNewOrder = false

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to reclaim enemy '..oNearestReclaimableEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableEnemy)..'; iDistanceToReissue='..iDistanceToReissue..'; iTicksToCheck='..iTicksToCheck..'; Time='..GetGameTimeSeconds()) end
    while iRemainingTicksToWait > 0 do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        iRemainingTicksToWait = iRemainingTicksToWait - 1
        --Abort if either unit is invalid, engineer is already reclaiming, or engineer appears to have orders changed (vai cahnge in priority or action)
        if bDebugMessages == true then
            LOG(sFunctionRef..': iRemainingTicksToWait='..iRemainingTicksToWait..'; TIme='..GetGameTimeSeconds()..'; Is engi valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer))..'; Is nearest reclaimable enemy valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy))..'; Engi action='..(oEngineer[refiAssignedAction] or 'nil')..'; Engi priority='..(oEngineer[refiAssignedActionPriority] or 'nil'))
            if AiBotUnitInfo.IsUnitValid(oEngineer) and AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy) then
                LOG(sFunctionRef..': Dist from engi to nearest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oNearestReclaimableEnemy:GetPosition())..'; Engi state='..AiBotUnitInfo.GetUnitState(oEngineer))
            end
        end
        if AiBotUnitInfo.IsUnitValid(oEngineer) and AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy) and not(oEngineer:IsUnitState('Reclaiming')) and oEngineer[refiAssignedAction] == iEngineerActionRequired and oEngineer[refiAssignedActionPriority] == iEngineerPriorityRequired then
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oNearestReclaimableEnemy:GetPosition())
            if iCurDist <= iDistanceToReissue then
                if bDebugMessages == true then LOG(sFunctionRef..': Engineer is close to target so will issue a reclaim order') end
                AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaimableEnemy, false, 'ReclByT', false, true)
                bGivenNewOrder = true
                break --Dont want to risk clearing engineer every tick and never reclaiming
            elseif iCurDist <= iDistanceToReissue + 0.5 and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oNearestReclaimableEnemy.UnitId) and oEngineer:IsUnitState('Moving') and oNearestReclaimableEnemy:IsUnitState('Moving') then
                --If enemy unit is moving and we are moving, then likely will be in range by the time the reclaim order goes through - check enemy engi is moving towards us
                if bDebugMessages == true then LOG(sFunctionRef..': Almost in range of enemy engineer, so will try reclaiming very slightly sooner if angle dif from them suggests they are moving towards us, angle dif='..AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oNearestReclaimableEnemy:GetPosition(), oEngineer:GetPosition()), AiBotUnitInfo.GetUnitFacingAngle(oNearestReclaimableEnemy))) end
                if AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oNearestReclaimableEnemy:GetPosition(), oEngineer:GetPosition()), AiBotUnitInfo.GetUnitFacingAngle(oNearestReclaimableEnemy)) <= 35 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Repeating reclaim order') end
                    AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaimableEnemy, false, 'ReclByET', false, true)
                    bGivenNewOrder = true
                    break --Dont want to risk clearing engineer every tick and never reclaiming
                end
            end
        else
            break
        end

    end
    --Consider clearing orders and reissuing the reclaim command if enemy is moving in a dif angle to us
    if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oEngineer) and AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy) then LOG(sFunctionRef..': end of monitoring, but engi and target both alive, bGivenNewOrder='..tostring(bGivenNewOrder)..'; Engi state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; Special micro active='..tostring(oEngineer[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
    if not(bGivenNewOrder) and AiBotUnitInfo.IsUnitValid(oEngineer) and AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy) and not(oEngineer:IsUnitState('Reclaiming')) and not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) then
        local iOurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oEngineer)
        local iAngleToEnemy = AiBotUtilities.GetAngleFromAToB(oEngineer:GetPosition(), oNearestReclaimableEnemy:GetPosition())
        if bDebugMessages == true then LOG(sFunctionRef..': iOurFacingDirection='..iOurFacingDirection..'; iAngleToEnemy='..iAngleToEnemy) end
        if AiBotUtilities.GetAngleDifference(iAngleToEnemy, iOurFacingDirection) >= 20 then
            local iEnemyFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oNearestReclaimableEnemy)
            local iAngleDif = AiBotUtilities.GetAngleDifference(iEnemyFacingDirection, iOurFacingDirection)
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyFacingDirection='..iEnemyFacingDirection..'; iAngleDif='..iAngleDif) end
            if iAngleDif >= 20 then
                AiBotOrders.IssueTrackedClearCommands(oEngineer)
                AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaimableEnemy, false, 'ReclERefr', false)
                bGivenNewOrder = true
                if bDebugMessages == true then LOG(sFunctionRef..': Cleared and reissued reclaim order as we seem to be going in the wrong direction') end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function CheckForNearbyEnemies()  end --This is incorporated into available engineers by tech - added to make it easier to locate logic
function FilterToAvailableEngineersByTech(tEngineers, bInCoreZone, tLZData, tLZTeamData, iTeam, iPlateauOrPond, iLandZone, bIsWaterZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'FilterToAvailableEngineersByTech'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..' for iPlateauOrPond='..iPlateauOrPond..'; iLandZone='..iLandZone..'; reprs of tEngineers='..reprs(tEngineers)) end

    --Returns a table of available engineers by tech
    local toAvailableEngineersByTech = {[1]= { },[2]={},[3]={}}
    local toAssignedEngineers = {}
    local bHaveAvailableEngi = false
    local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]  --AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
    --local tNearbyEnemiesByZone = {}
    local bCheckForEnemies = false
    local toNavalEnemiesAdjacentToLand
    local bCheckIfEnemyIsActuallyEnemy = false
    if AiBotMap.bIsCampaignMap and (AiBotOverseer.tbSpecialCodeForMission[41] or (ScenarioInfo.QAICommander and AiBotUnitInfo.IsUnitValid(ScenarioInfo.QAICommander))) then
        bCheckIfEnemyIsActuallyEnemy = true
    end
    if (bIsWaterZone and (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false))
            or (not(bIsWaterZone) and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
        --table.insert(tNearbyEnemiesByZone, tLZTeamData[AiBotMap.subrefTEnemyUnits])
        bCheckForEnemies = true
        if AiBotUtilities.bCPUPerformanceMode then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) then bCheckForEnemies = false
            elseif aiBrain[AiBotUnitInfo.refbEasyBrain] and tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] == 0 and tEngineers[1].GetAIBrain and tEngineers[1]:GetAIBrain()[AiBotUnitInfo.refbEasyBrain] then
                bCheckForEnemies = false
            end
        end
    end
    if not(bIsWaterZone) and not(AiBotUtilities.bCPUPerformanceMode) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iAdjWZ, iPond
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
            local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]

            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..tSubtable[AiBotMap.subrefAWZRef]..'; subrefWZThreatEnemyVsSurface='..(tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 'nil')..'; subrefWZBestEnemyDFRange='..(tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 'nil')..'; is subrefTEnemyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) or false)) end
            if tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] > 40 and tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > 15 and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                for iEnemy, oEnemy in tAdjWZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if not(oEnemy.Dead) and oEnemy[AiBotUnitInfo.refiDFRange] > 15 then
                        if not(toNavalEnemiesAdjacentToLand) then toNavalEnemiesAdjacentToLand = {} end
                        if bDebugMessages == true then LOG(sFunctionRef..': Including naval enemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' in toNavalEnemiesAdjacentToLand') end
                        table.insert(toNavalEnemiesAdjacentToLand, oEnemy)
                    end
                end
            end
        end
    end

    if bDebugMessages == true then
        LOG(sFunctionRef..': Finished deciding if should check for enemies, bCheckForEnemies='..tostring(bCheckForEnemies)..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or false)..'; AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestCombatEnemies]) empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestCombatEnemies]))..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false))
        if bIsWaterZone then
            local tNewAttemptWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandZone]][AiBotMap.subrefPondWaterZones][iLandZone][AiBotMap.subrefWZTeamData][iTeam]
            LOG(sFunctionRef..': Is tNewAttemptWZTeamData[reftoNearestCombatEnemies] empty='..tostring(AiBotUtilities.IsTableEmpty(tNewAttemptWZTeamData[AiBotMap.reftoNearestCombatEnemies]))..'; Is tNewAttemptWZTeamData = tLZTeamData='..tostring(tNewAttemptWZTeamData == tLZTeamData))
        end
    end

    --[[if bIsWaterZone then
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefWZOtherWaterZones]) == false then
            local iAdjWZ
            for _, tWZSubtable in  tLZData[AiBotMap.subrefWZOtherWaterZones] do
                iAdjWZ = tWZSubtable[AiBotMap.subrefWZAWZRef]

                if AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false then
                    table.insert(tNearbyEnemiesByZone, AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefTEnemyUnits])
                    bCheckForEnemies = true
                end
            end
        end
    elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjacentLZ in  tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iAdjacentLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false then
                table.insert(tNearbyEnemiesByZone, AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iAdjacentLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits])
                bCheckForEnemies = true
            end
        end
    end--]]
    --if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding if should check for enemies (based on if enemy threats in this or nearby LZ), bCheckForEnemies='..tostring(bCheckForEnemies)..'; Is table of enemy units for this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; is tNearbyEnemiesByZone empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemiesByZone))..'; subrefLZThreatEnemyMobileDFTotalin this LZ='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)) end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding if should check for enemies (based on if enemy threats in this or nearby LZ), bCheckForEnemies='..tostring(bCheckForEnemies)..'; If get units aroundpoint with radius of 30 is the table of units empty='..tostring(AiBotUtilities.IsTableEmpty(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategorySubmarine, tLZData[AiBotMap.subrefMidpoint], 30, 'Enemy')))) end

    local iClosestDistUntilInRangeOfMobileEnemy = 100000
    local iClosestDistUntilInRangeOfStaticEnemy = 100000
    local iNearestReclaimableEnemy = 100000
    local iNearestReclaimableDangerousEnemy = 100000
    local oNearestReclaimableDangerousEnemy
    local iNearestEnemy = 100000
    local oNearestReclaimableEnemy
    local oNearestEnemy
    local iCurDistToEnemy
    local iCurDistUntilInRange
    local iCurUnitRange
    local bWantEngiToRun
    local bEngiIsUnavailable

    local iLZOrWZToRunTo, iPlateauOrZeroToRunTo
    local iThresholdToRunFromMobileEnemies = 35
    if bInCoreZone or (bIsWaterZone and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false) then
        iThresholdToRunFromMobileEnemies = 10
        --Zone with lots of reclaim where we have stronger combat threat than enemy - consider lower run threshold
    elseif tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 250 then
        local iFriendlyThreatRatioWanted = 1.3
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1200 then iFriendlyThreatRatioWanted = 1.1 end

        if bIsWaterZone then
            if tLZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] * iFriendlyThreatRatioWanted < tLZTeamData[AiBotMap.subrefWZThreatAlliedAntiNavy] and tLZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] * iFriendlyThreatRatioWanted < tLZTeamData[AiBotMap.subrefWZThreatAlliedSurface] then
                iThresholdToRunFromMobileEnemies = 20
            end
        else
            if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= iFriendlyThreatRatioWanted * (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) * iFriendlyThreatRatioWanted then
                iThresholdToRunFromMobileEnemies = 16
            end
        end
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 2000 and iThresholdToRunFromMobileEnemies >= 35 and ((bIsWaterZone and tLZTeamData[AiBotMap.subrefWZThreatAlliedSurface] >= 300) or (not(bIsWaterZone) and tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] >= 100)) then iThresholdToRunFromMobileEnemies = 26 end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': setting iThresholdToRunFromMobileEnemies='..(iThresholdToRunFromMobileEnemies or 'nil')..'; Our combat='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')..'; Enemy combat='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Our mobile DF='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; Signif mass reclaim='..(tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')..'; tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]='..(tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 'nil')..'; Is tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]))) end

    local iEnemyUnitSearchRange = iThresholdToRunFromMobileEnemies + math.max(10, (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0), (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0), (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0), (tLZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0), (tLZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] or 0))
    local iActualEnemySearchRange
    local iActualEnemyCategorySearch
    local iEasyEnemyCategorySearch = AiBotUnitInfo.refCategoryStructure
    local iNormalEnemyCategorySearch = AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategorySubmarine
    local bCheckLRThreats = false

    if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false and iEnemyUnitSearchRange < 100 then bCheckLRThreats = true end
    local bConsiderRunningFromEnemies = true
    if tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 then
        --Last base so make a last stand
        bConsiderRunningFromEnemies = false
    end

    local bCheckForReclaim
    if (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 20 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 8 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 300 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35)) then
        --If we lack a land factory, it's the first 12m, a land zone, and it's not a mexless zone that hasnt been dropped recently, then check for reclaim in the build range of the engineer and reclaim it if it's available
        if GetGameTimeSeconds() > 720 or bIsWaterZone or ((tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateauOrPond][iLandZone])) or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryLandFactory) > 0 or tLZData[AiBotMap.subrefLZOrWZMexCount] == (tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3]) then
            bCheckForReclaim = true
        end
    end

    if tEngineers then
        local bCheckForWallsToReclaim = false
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of wall segments empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPlayerWallSegments]))) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPlayerWallSegments]) == false then
            local iTotalWallSegments = table.getn(tLZData[AiBotMap.subrefLZPlayerWallSegments])
            if AiBotUtilities.bCPUPerformanceMode then
                if iTotalWallSegments >= 9 then bCheckForWallsToReclaim = true end
            elseif iTotalWallSegments >= 5 or (iTotalWallSegments >= 2 and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) == 0) then --sometimes walls can get spread over several land zones in a line, meaning the previous threshold of 10 doesnt pick it up; also if we have just reclaimed a wall then there might only be a few segments, but htey could restrict land units to a very narrow path
                bCheckForWallsToReclaim = true
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Size of wall segment table='..table.getn(tLZData[AiBotMap.subrefLZPlayerWallSegments])..'; bCheckForWallsToReclaim='..tostring(bCheckForWallsToReclaim or false)) end
        end

        --Use much lower threshold to run if if we have T2+ PD in this zone
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                if iRange >= 50 and iThreat > 0 then
                    iThresholdToRunFromMobileEnemies = 5
                    break
                end
            end
        end

        --Be more aggressive at trying to reclaim if enemy has low combat threat and we have multiple engineers, and be even more aggressive if any of them have a reclaim order
        local iReclaimRangeAdjust = 0
        if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 60 then
            iReclaimRangeAdjust = 2
            --If we have an engineer that has a reclaim order increase this further (so engis more likely to try and gang up together)
            for iEngi, oEngi in tEngineers do
                if oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueReclaim then
                    iReclaimRangeAdjust = 9
                    break
                end
            end
        end

        --Run from WZ midpoint as positiontorunfrom if WZ is dangerous (if land zone and no nearestenemy to run from)
        local tWZPositionToRunFrom
        if tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] and not(bIsWaterZone) then
            local iAdjWZ, iPond
            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                local tAdjWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                local tAdjWZTeamData = tAdjWZData[AiBotMap.subrefWZTeamData][iTeam]
                if (tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0) > 30 then
                    tWZPositionToRunFrom = {tAdjWZData[AiBotMap.subrefMidpoint][1], tAdjWZData[AiBotMap.subrefMidpoint][2], tAdjWZData[AiBotMap.subrefMidpoint][3]}
                    break
                end
            end
        end


        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyUnitSearchRange='..iEnemyUnitSearchRange..'; iThresholdToRunFromMobileEnemies='..iThresholdToRunFromMobileEnemies..'; bCheckLRThreats='..tostring(bCheckLRThreats)..'; bConsiderRunningFromEnemies='..tostring(bConsiderRunningFromEnemies)..'; Time='..GetGameTimeSeconds()) end
        local bIgnoreIfEnemyUnderwater = false
        local bConsiderReclaimableEnemiesInBuildRangeOnly
        local bDontCheckForHostileCivilains = not(tLZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone])
        for iEngineer, oEngineer in tEngineers do
            if not(oEngineer.Dead) then --redundancy for rare error

                if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer '..(oEngineer.UnitId or 'nil')..'; iEngineer='..iEngineer..' with unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; refiAssignedAction='..(oEngineer[refiAssignedAction] or 'nil')..'; oEngineer[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oEngineer[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; refiGameTimeToResetMicroActive='..(oEngineer[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; bCheckForEnemies='..tostring(bCheckForEnemies)..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                bWantEngiToRun = false
                bEngiIsUnavailable = false
                if not(oEngineer:IsUnitState('Attached')) and not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) and not(oEngineer:IsUnitState('Capturing')) then --even when adding a not(oEngineer.Dead) to this, in LOUD it can sometimes have an error when checking unit state; however it should only last a short while
                    if bIsWaterZone and EntityCategoryContains(categories.HOVER, oEngineer.UnitId) then bIgnoreIfEnemyUnderwater = true end
                    --First check for enemies that we want to run from/take action from
                    if bCheckForEnemies or bCheckForWallsToReclaim or toNavalEnemiesAdjacentToLand then
                        local bReclaimingDangerousEnemy = false
                        iNearestReclaimableEnemy = 10000
                        iNearestReclaimableDangerousEnemy = 10000
                        iClosestDistUntilInRangeOfMobileEnemy = 10000
                        iClosestDistUntilInRangeOfStaticEnemy = 10000
                        oNearestReclaimableDangerousEnemy = nil
                        oNearestReclaimableEnemy = nil
                        oNearestEnemy = nil
                        bConsiderReclaimableEnemiesInBuildRangeOnly = false

                        --If engi is building emergency PD or Arti or torp launcher then dont run
                        if not(oEngineer[refiAssignedAction] == refActionBuildEmergencyPD or oEngineer[refiAssignedAction] == refActionBuildSecondPD or oEngineer[refiAssignedAction] == refActionBuildEmergencyArti or oEngineer[refiAssignedAction] == refActionBuildWall or oEngineer[refiAssignedAction] == refActionBuildT1TorpLauncher or oEngineer[refiAssignedAction] == refActionBuildTorpLauncher) then
                            --Is the engineer reclaiming an engineer or combat unit, or alternatively building something whose fraction complete is almost done?
                            if oEngineer:IsUnitState('Reclaiming') then
                                local oReclaimTarget = oEngineer:GetFocusUnit()
                                if oReclaimTarget and not(oReclaimTarget.Dead) and ((oReclaimTarget[AiBotUnitInfo.refiCombatRange] or 0) > 0 or EntityCategoryContains(categories.RECLAIM, oReclaimTarget.UnitId)) then
                                    bReclaimingDangerousEnemy = true
                                end
                            end
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Engineer unit state='..AiBotUnitInfo.GetUnitState(oEngineer))
                                local oFocusUnit = oEngineer:GetFocusUnit()
                                if oFocusUnit then
                                    LOG(sFunctionRef..': Engineer focus unit='..oFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit)..'; Focus unit fraction complete='..oEngineer:GetFocusUnit():GetFractionComplete())
                                end
                            end
                            if (oEngineer:IsUnitState('Repairing') or oEngineer:IsUnitState('Building')) then
                                local oFocusUnit = oEngineer:GetFocusUnit()
                                if oFocusUnit and oFocusUnit:GetFractionComplete() >= 0.75 and oFocusUnit:GetFractionComplete() < 1 then
                                    if oFocusUnit:GetFractionComplete() >= 0.9 then
                                        bConsiderReclaimableEnemiesInBuildRangeOnly = true
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oFocusUnit.UnitId) and AiBotUnitInfo.GetUnitHealthPercent(oEngineer) >= 0.99 then
                                        bConsiderReclaimableEnemiesInBuildRangeOnly = true
                                    end
                                end
                                if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oFocusUnit) then LOG(sFunctionRef..': We are currently building '..oFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit)..'; Fraction complete='..oFocusUnit:GetFractionComplete()..'; Engi work progress='..oEngineer:GetWorkProgress()..'; bConsiderReclaimableEnemiesInBuildRangeOnly='..tostring(bConsiderReclaimableEnemiesInBuildRangeOnly)) end
                            end
                            if not(bReclaimingDangerousEnemy) and not(bConsiderReclaimableEnemiesInBuildRangeOnly) and not(oEngineer:IsUnitState('Capturing') and oEngineer:GetWorkProgress() >= 0.75) then
                                if not(oEngineer[AiBotUnitInfo.refbEasyBrain]) or (not(oEngineer:IsUnitState('Reclaiming')) and not(oEngineer:IsUnitState('Repairing')) and not(oEngineer:IsUnitState('Building'))) then
                                    if aiBrain.GetUnitsAroundPoint then
                                        if oEngineer[AiBotUnitInfo.refbEasyBrain] then
                                            iActualEnemySearchRange = math.min(10, iEnemyUnitSearchRange)
                                            iActualEnemyCategorySearch = iEasyEnemyCategorySearch
                                        else
                                            iActualEnemySearchRange = iEnemyUnitSearchRange
                                            iActualEnemyCategorySearch = iNormalEnemyCategorySearch
                                        end
                                        local tNearbyEnemiesByZone
                                        if AiBotUtilities.bCPUPerformanceMode then
                                            tNearbyEnemiesByZone = tLZTeamData[AiBotMap.subrefTEnemyUnits]
                                            iNearestEnemy = iActualEnemySearchRange
                                            iNearestReclaimableDangerousEnemy = iActualEnemySearchRange
                                            iNearestReclaimableEnemy = iActualEnemySearchRange
                                        elseif toNavalEnemiesAdjacentToLand and not(bCheckForEnemies) and not(bCheckForWallsToReclaim) then
                                            --Will update to reflect naval enemies below, so dont search
                                        elseif tLZTeamData[AiBotMap.refiRadarCoverage] >= 60 or not(bCheckForEnemies) then
                                            tNearbyEnemiesByZone = aiBrain:GetUnitsAroundPoint(iActualEnemyCategorySearch, oEngineer:GetPosition(), iActualEnemySearchRange, 'Enemy')
                                            if bDebugMessages == true then LOG(sFunctionRef..': Using getunitsaroundpoint to check for enemies, tLZTeamData[AiBotMap.refiRadarCoverage]='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                                        else
                                            --Rely on memory
                                            tNearbyEnemiesByZone = {}
                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                    table.insert(tNearbyEnemiesByZone, oUnit)
                                                end
                                            end
                                            --Include adjacent zones
                                            if bIsWaterZone then
                                                --Water zone
                                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                                                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                                                        if not(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] == iLandZone) then
                                                            table.insert( tNearbyEnemiesByZone, oUnit)
                                                        end
                                                    end
                                                end
                                            else
                                                --Land zone
                                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                        if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                                            table.insert( tNearbyEnemiesByZone, oUnit)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if toNavalEnemiesAdjacentToLand then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Updating nearby enemies to include toNavalEnemiesAdjacentToLand') end
                                            if not(tNearbyEnemiesByZone) then tNearbyEnemiesByZone = toNavalEnemiesAdjacentToLand
                                            else
                                                for iEnemy, oEnemy in toNavalEnemiesAdjacentToLand do
                                                    table.insert(tNearbyEnemiesByZone, oEnemy)
                                                end
                                            end
                                        end

                                        --for iSubtable, tSubtable in tNearbyEnemiesByZone do
                                        --if AiBotUtilities.IsTableEmpty(tSubtable) == false then
                                        --for iUnit, oUnit in tSubtable do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby enemies empty for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemiesByZone))) end
                                        if AiBotUtilities.IsTableEmpty(tNearbyEnemiesByZone) == false then
                                            for iUnit, oUnit in tNearbyEnemiesByZone do
                                                --It's not possible to reclaim an under construction building
                                                if not(oUnit.Dead) and (oUnit:GetFractionComplete() == 1 or not(oUnit:IsBeingBuilt()) or AiBotConditions.BuildingWasBeingBuiltButCanBeReclaimedNow(oUnit)) then
                                                    if (not(bCheckIfEnemyIsActuallyEnemy) or (IsEnemy(oEngineer:GetAIBrain():GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))) and not(oUnit:IsUnitState('Attached')) then
                                                        if not(bIgnoreIfEnemyUnderwater) or not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                                                            iCurUnitRange = (oUnit[AiBotUnitInfo.refiDFRange] or 0) + (oUnit[AiBotUnitInfo.refiIndirectRange] or 0)
                                                            if bIsWaterZone and not(EntityCategoryContains(categories.HOVER, oEngineer.UnitId)) then iCurUnitRange = math.max(iCurUnitRange, (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0)) end
                                                            iCurDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEngineer:GetPosition())
                                                            if iCurDistToEnemy < iNearestEnemy then
                                                                iNearestEnemy = iCurDistToEnemy
                                                                oNearestEnemy = oUnit
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurUnitRange='..iCurUnitRange..'; iCurDistToEnemy='..iCurDistToEnemy..'; Is reclaimable='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryReclaimable, oUnit.UnitId))..'; Does the unit contain the reclaim category='..tostring(EntityCategoryContains(categories.RECLAIM, oUnit.UnitId))..'; iNearestReclaimableDangerousEnemy='..iNearestReclaimableDangerousEnemy) end
                                                            if iCurDistToEnemy < iNearestReclaimableDangerousEnemy and EntityCategoryContains(AiBotUnitInfo.refCategoryReclaimable, oUnit.UnitId) then
                                                                if (oUnit[AiBotUnitInfo.refiCombatRange] > 0 or EntityCategoryContains(categories.RECLAIM, oUnit.UnitId)) and oUnit:GetFractionComplete() == 1 then
                                                                    --Dangerous enemy
                                                                    iNearestReclaimableDangerousEnemy = iCurDistToEnemy
                                                                    oNearestReclaimableDangerousEnemy = oUnit
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Updating nearest dangerous enemy to be '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                                                end
                                                                if iCurDistToEnemy < iNearestReclaimableEnemy then
                                                                    iNearestReclaimableEnemy = iCurDistToEnemy
                                                                    oNearestReclaimableEnemy = oUnit
                                                                end
                                                            end
                                                            --Ignore land scouts and similar unthreatening units
                                                            if iCurUnitRange > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                                                                iCurDistUntilInRange = iCurDistToEnemy - iCurUnitRange
                                                                if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                                                    if iCurDistUntilInRange < iClosestDistUntilInRangeOfMobileEnemy then
                                                                        if bDontCheckForHostileCivilains or not(oUnit[AiBotUnitInfo.refbHostileImmobileCivilian]) then
                                                                            iClosestDistUntilInRangeOfMobileEnemy = iCurDistUntilInRange
                                                                        end
                                                                    end
                                                                else
                                                                    if iCurDistUntilInRange < iClosestDistUntilInRangeOfStaticEnemy then
                                                                        if bDontCheckForHostileCivilains or not(oUnit[AiBotUnitInfo.refbHostileImmobileCivilian]) or (AiBotUnitInfo.CanSeeUnit(oUnit:GetAIBrain(), oEngineer) or iCurDistToEnemy - 4 <= AiBotUnitInfo.GetUnitMaxIntelOrVisualRange(oUnit, bIsWaterZone, false)) then
                                                                            iClosestDistUntilInRangeOfStaticEnemy = iCurDistUntilInRange
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Updating iClosestDistUntilInRangeOfStaticEnemy to '..iClosestDistUntilInRangeOfStaticEnemy..' for enemy '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DFRange='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; IndirectRange='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; AntiNAvy='..(oUnit[AiBotUnitInfo.refiAntiNavyRange] or 'nil')..'; iCurUnitRange='..iCurUnitRange) end
                                                                        end
                                                                    end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': iCurDistUntilInRange='..iCurDistUntilInRange) end
                                                            end
                                                        end
                                                    end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' is dead or is being built (cant reclaim under construction units), is table of g etguards empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit:GetGuards()))) end
                                                end
                                            end
                                            --end
                                        end
                                        --Consider reclaiming wall segment instead
                                        if bDebugMessages == true then LOG(sFunctionRef..': bCheckForWallsToReclaim='..tostring(bCheckForWallsToReclaim or false)..'; iNearestReclaimableEnemy='..(iNearestReclaimableEnemy or 'nil')..'; iClosestDistUntilInRangeOfStaticEnemy='..(iClosestDistUntilInRangeOfStaticEnemy or 'nil')..'; iClosestDistUntilInRangeOfMobileEnemy='..(iClosestDistUntilInRangeOfMobileEnemy or 'nil')) end
                                        if bCheckForWallsToReclaim and (iNearestReclaimableEnemy or 100) >= 10 and (iClosestDistUntilInRangeOfStaticEnemy or 100) >= 8 and (iClosestDistUntilInRangeOfMobileEnemy or 100) >= 10 then
                                            local iEngiIndex = oEngineer:GetAIBrain():GetArmyIndex()
                                            for iUnit, oUnit in tLZData[AiBotMap.subrefLZPlayerWallSegments] do
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering wall '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Dist to engi='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEngineer:GetPosition())..'; Is enemy='..tostring(IsEnemy(iEngiIndex, oUnit:GetAIBrain():GetArmyIndex()))) end
                                                if AiBotUnitInfo.IsUnitValid(oUnit) and IsEnemy(iEngiIndex, oUnit:GetAIBrain():GetArmyIndex()) then
                                                    iCurDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEngineer:GetPosition())
                                                    if iCurDistToEnemy < (iNearestReclaimableEnemy or 10000) then
                                                        iNearestReclaimableEnemy = iCurDistToEnemy
                                                        oNearestReclaimableEnemy = oUnit
                                                    end
                                                end
                                            end
                                        end
                                        local iEngiBuildDistance = oEngineer:GetBlueprint().Economy.MaxBuildDistance
                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking for nearby enemies for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; iNearestReclaimableEnemy='..iNearestReclaimableEnemy..'; iClosestDistUntilInRangeOfStaticEnemy='..iClosestDistUntilInRangeOfStaticEnemy..'; Core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; Core expansion='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; oNearestReclaimableDangerousEnemy='..(oNearestReclaimableDangerousEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableDangerousEnemy) or 'nil')..'; oNearestReclaimableEnemy='..(oNearestReclaimableEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableEnemy) or 'nil')..'; iEngiBuildDistance='..iEngiBuildDistance..'; iNearestReclaimableDangerousEnemy='..iNearestReclaimableDangerousEnemy..'; iReclaimRangeAdjust='..iReclaimRangeAdjust) end
                                        if oNearestReclaimableEnemy and (iClosestDistUntilInRangeOfMobileEnemy > 10 or iNearestReclaimableEnemy < iEngiBuildDistance + 3 or EntityCategoryContains(AiBotUnitInfo.refCategoryLightAttackBot, oNearestReclaimableEnemy.UnitId)) and (iNearestReclaimableEnemy < 20 + iReclaimRangeAdjust or
                                                (iNearestReclaimableEnemy < 40 and bCheckForWallsToReclaim and EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oNearestReclaimableEnemy) and iClosestDistUntilInRangeOfStaticEnemy >= iNearestReclaimableEnemy + 10 and (not(oNearestReclaimableDangerousEnemy) or iNearestReclaimableDangerousEnemy >= iNearestReclaimableEnemy + 20 or (iNearestReclaimableEnemy <= 30 and iNearestReclaimableDangerousEnemy >= 35 and AiBotUtilities.GetDistanceBetweenPositions(oNearestReclaimableEnemy:GetPosition(), oNearestReclaimableDangerousEnemy:GetPosition()) > 10 + iNearestReclaimableDangerousEnemy)))) --i.e. if have a wall taht is in an adjacent zone but on the border, then increase search range to reduce issues where we try travel to that zone and take the wrong path
                                                and ((iClosestDistUntilInRangeOfStaticEnemy >= 10 and iNearestReclaimableEnemy <= iEngiBuildDistance) or iNearestReclaimableEnemy <= (iEngiBuildDistance + 7 + iReclaimRangeAdjust) or (iNearestReclaimableEnemy <= iEngiBuildDistance + 14 + iReclaimRangeAdjust and (tLZTeamData[AiBotMap.subrefLZbCoreBase] or tLZTeamData[AiBotMap.subrefLZCoreExpansion])) or (bCheckForWallsToReclaim and EntityCategoryContains(AiBotUnitInfo.refCategoryWall, oNearestReclaimableEnemy) and (not(oNearestReclaimableDangerousEnemy) or iNearestReclaimableDangerousEnemy >= iNearestReclaimableEnemy + 20 + iReclaimRangeAdjust or (iNearestReclaimableEnemy <= 30 and iNearestReclaimableDangerousEnemy >= 35)))) then
                                            --Reclaim enemy
                                            --Switch the target to the nearest dangerous enemy if it is in our build range
                                            if iNearestReclaimableDangerousEnemy <= iEngiBuildDistance + 0.5 and oNearestReclaimableDangerousEnemy
                                                    and (iNearestReclaimableDangerousEnemy <= iEngiBuildDistance or iNearestReclaimableDangerousEnemy <= iEngiBuildDistance + math.min(oNearestReclaimableDangerousEnemy:GetBlueprint().Physics.SkirtSizeX, oNearestReclaimableDangerousEnemy:GetBlueprint().Physics.SkirtSizeZ) * 0.5) then

                                                oNearestReclaimableEnemy = oNearestReclaimableDangerousEnemy
                                                if bDebugMessages == true then LOG(sFunctionRef..': Switching so nearest reclaimable enemy is the nearest reclaimable dangerous enemy='..oNearestReclaimableDangerousEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableDangerousEnemy)) end
                                                --Niche case - nearby enemy engineer building PD or factory - want to stop the engineer before construction completes
                                            elseif iNearestReclaimableDangerousEnemy <= iEngiBuildDistance + 10 and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oNearestReclaimableDangerousEnemy.UnitId) and oNearestReclaimableDangerousEnemy:GetWorkProgress() >= 0.5 then
                                                local oEnemyConstructingUnit = oNearestReclaimableDangerousEnemy:GetFocusUnit()
                                                if AiBotUnitInfo.IsUnitValid(oEnemyConstructingUnit) and oEnemyConstructingUnit:GetFractionComplete() <= 0.9 and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryTorpedoLauncher, oEnemyConstructingUnit.UnitId) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy engi is building a PD or factory so will try and stop it by reclaiming it') end
                                                    oNearestReclaimableEnemy = oNearestReclaimableDangerousEnemy
                                                end
                                            end
                                            bEngiIsUnavailable = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will reclaim or capture unit, is capture target='..tostring(oNearestReclaimableEnemy[AiBotUnitInfo.refbIsCaptureTarget])..'; Is oNearestReclaimableEnemy valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestReclaimableEnemy))) end
                                            if oNearestReclaimableEnemy[AiBotUnitInfo.refbIsCaptureTarget] then
                                                TrackEngineerAction(oEngineer, refActionCaptureUnit, false, 1)
                                                --Dont capture if already capturing (redundancy)
                                                if not(oEngineer:IsUnitState('Capturing')) then
                                                    AiBotOrders.IssueTrackedCapture(oEngineer, oNearestReclaimableEnemy, false, 'CapE')
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Told engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to capture enemy unit') end
                                                end
                                            else
                                                local oEnemyBP = oNearestReclaimableEnemy:GetBlueprint()
                                                local iDistanceUntilInRange = iEngiBuildDistance + math.min(oEnemyBP.Physics.SkirtSizeX, oEnemyBP.Physics.SkirtSizeZ) * 0.5
                                                local bReclaimingNearbyCivilianWalls = false
                                                if iNearestReclaimableEnemy > iDistanceUntilInRange and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestReclaimableEnemy.UnitId) and (iPlateauOrPond == 0 or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oNearestReclaimableEnemy:GetPosition()) == iPlateauOrPond) then
                                                    --If targeting a civilian building then check if are walls nearby and if so reclaim teh walls as they may be blocking our orders
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Brain of nearest reclaimable enemy='..(oNearestReclaimableEnemy:GetAIBrain().Nickname or 'nil')..'; Is civilian='..tostring(AiBotConditions.IsCivilianBrain(oNearestReclaimableEnemy:GetAIBrain()))) end
                                                    if AiBotConditions.IsCivilianBrain(oNearestReclaimableEnemy:GetAIBrain()) then
                                                        local tMidpoint = AiBotUtilities.MoveInDirection(oEngineer:GetPosition(), AiBotUtilities.GetAngleFromAToB(oEngineer:GetPosition(), oNearestReclaimableEnemy:GetPosition()), iNearestReclaimableEnemy * 0.5)
                                                        local rRect = AiBotUtilities.GetRectAroundLocation(tMidpoint, math.min(15, iNearestReclaimableEnemy * 0.5))
                                                        local tNearbyUnits = GetUnitsInRect(rRect)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': is table of nearby units empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits))) end
                                                        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                                                            local tNearbyWalls = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryWall, tNearbyUnits)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': is table of nearby walls empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyWalls))) end
                                                            if AiBotUtilities.IsTableEmpty(tNearbyWalls) == false and table.getn(tNearbyWalls) >= 5 then
                                                                local iNearestWall = 30 --dont move to reclaim walls further away than this (more of a redundancy as doubt would have a reclaim order anyway)
                                                                local oNearestWall, iCurWallDist
                                                                for iWall, oWall in tNearbyWalls do
                                                                    if not(oWall:GetAIBrain().AiBotTeam == iTeam) then
                                                                        iCurWallDist = AiBotUtilities.GetDistanceBetweenPositions(oWall:GetPosition(), oEngineer:GetPosition())
                                                                        if iCurWallDist < iNearestWall then
                                                                            iNearestWall = iCurWallDist
                                                                            oNearestWall = oWall
                                                                        end
                                                                    end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': oNearestWall='..(oNearestWall.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestWall) or 'nil')) end
                                                                if oNearestWall then
                                                                    bReclaimingNearbyCivilianWalls = true
                                                                    AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestWall, false, 'RecCivWal')
                                                                end
                                                            end

                                                        end
                                                    end
                                                end
                                                if not(bReclaimingNearbyCivilianWalls) then
                                                    if oNearestReclaimableEnemy:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oNearestReclaimableEnemy.UnitId) and iNearestReclaimableEnemy <= iDistanceUntilInRange then
                                                        AiBotOrders.IssueTrackedCapture(oEngineer, oNearestReclaimableEnemy, false, 'CapT1Mx', false)
                                                    else
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and reclaim oNearestReclaimableEnemy='..oNearestReclaimableEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableEnemy)) end
                                                        --IssueTrackedReclaim(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, bForceReissueOfOrderSubjectToMicro)
                                                        AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaimableEnemy, false, 'RecE', false, (iNearestReclaimableEnemy < iDistanceUntilInRange and (not(oEngineer:IsUnitState('Reclaiming')) or not(oNearestReclaimableEnemy == oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]))))
                                                    end
                                                end


                                                if bDebugMessages == true then LOG(sFunctionRef..': Told engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to reclaim (or if T1 mex to capture) enemy unit '..oNearestReclaimableEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestReclaimableEnemy)..'; Is getguards empty='..tostring(AiBotUtilities.IsTableEmpty(oNearestReclaimableEnemy:GetGuards()))..'; Unit:IsBeingBuilt()='..tostring(oNearestReclaimableEnemy:IsBeingBuilt())) end
                                                --Monitor every tick for the next 9 ticks to see if enemy gets in-range

                                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to monitor reclaim distance, iDistanceUntilInRange='..iDistanceUntilInRange..'; iNearestReclaimableEnemy='..iNearestReclaimableEnemy..'; Speed of us and them='..(oEnemyBP.Physics.MaxSpeed or 0) + oEngineer:GetBlueprint().Physics.MaxSpeed) end
                                                if iNearestReclaimableEnemy > iDistanceUntilInRange and iNearestReclaimableEnemy - iDistanceUntilInRange <= (oEnemyBP.Physics.MaxSpeed or 0) + oEngineer:GetBlueprint().Physics.MaxSpeed + 0.2 then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will monitor to reissue order') end
                                                    ForkThread(MonitorToReissueReclaimOrder, oEngineer, oNearestReclaimableEnemy, iDistanceUntilInRange, 9)
                                                end
                                            end
                                        else
                                            --Enemy not close enough to reclaim, do we want to run?
                                            if bConsiderRunningFromEnemies or (iClosestDistUntilInRangeOfMobileEnemy < 10 and iNearestReclaimableEnemy > 22 and iClosestDistUntilInRangeOfMobileEnemy <= iThresholdToRunFromMobileEnemies) then
                                                --Above will have done getunitsaroundpoint; if dont have enemies that want to run from and we lack good intel in this zone, then do a more detailed check based on memory
                                                if bCheckForEnemies and iClosestDistUntilInRangeOfMobileEnemy > iThresholdToRunFromMobileEnemies and (tLZTeamData[AiBotMap.refiOmniCoverage] or 0) < 50 then
                                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Are enemy DF units close to this engineer='..tostring(AiBotConditions.CloseToEnemyUnit(oEngineer:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], iThresholdToRunFromMobileEnemies, iTeam, true))) end
                                                        if AiBotConditions.CloseToEnemyUnit(oEngineer:GetPosition(), tLZTeamData[AiBotMap.reftoNearestDFEnemies], iThresholdToRunFromMobileEnemies, iTeam, true) then
                                                            iClosestDistUntilInRangeOfMobileEnemy = iThresholdToRunFromMobileEnemies - 0.1
                                                        end
                                                    end
                                                    if bCheckLRThreats and iClosestDistUntilInRangeOfMobileEnemy > iThresholdToRunFromMobileEnemies then
                                                        --Also consider running from LR threats
                                                        local iCurDistUntilInRangeOfLREnemy
                                                        for iUnit, oUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                                                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                                                                iCurDistUntilInRangeOfLREnemy = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oEngineer:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange]
                                                                if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                                                    if iCurDistUntilInRangeOfLREnemy < iClosestDistUntilInRangeOfMobileEnemy then iClosestDistUntilInRangeOfMobileEnemy = iCurDistUntilInRangeOfLREnemy end
                                                                else
                                                                    if iCurDistUntilInRangeOfLREnemy < iClosestDistUntilInRangeOfStaticEnemy then iClosestDistUntilInRangeOfStaticEnemy = iCurDistUntilInRangeOfLREnemy end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering LR unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in range of us, iCurDistUntilInRangeOfLREnemy='..iCurDistUntilInRangeOfLREnemy) end
                                                            end
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Not close enough to reclaim enemy, and not a core LZ, iClosestDistUntilInRangeOfStaticEnemy='..iClosestDistUntilInRangeOfStaticEnemy..'; iClosestDistUntilInRangeOfMobileEnemy='..iClosestDistUntilInRangeOfMobileEnemy..'; iThresholdToRunFromMobileEnemies='..iThresholdToRunFromMobileEnemies..'; Is engi reclaiming='..tostring(oEngineer:IsUnitState('Reclaiming'))..'; oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]='..(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; is this valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]))) end
                                                if (iClosestDistUntilInRangeOfStaticEnemy < 8 or iClosestDistUntilInRangeOfMobileEnemy <= iThresholdToRunFromMobileEnemies) and (not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or iClosestDistUntilInRangeOfStaticEnemy < 4 or iClosestDistUntilInRangeOfMobileEnemy < 8) then
                                                    --Dont run if we are building a land factory and have a friendly combat threat in the zone or factory is near-complete
                                                    if tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 40 and (oEngineer:IsUnitState('Building') or oEngineer:IsUnitState('Reclaiming')) and (oEngineer:GetWorkProgress() >= 0.75 or (oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryPD, oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]))) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to risk engineer sticking around to try and complete its building') end
                                                        --Dont run if we are reclaiming and we arent actually in range of the enemy unit or are reclaiming an enemy combat unit or engineer
                                                    elseif oEngineer:IsUnitState('Reclaiming') and ((iClosestDistUntilInRangeOfMobileEnemy > 3 and iClosestDistUntilInRangeOfStaticEnemy > 1) or (oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].UnitId and not(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].Dead) and ((oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.refiCombatRange] or 0) > 0 or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].UnitId) or (oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].GetHealth and AiBotUnitInfo.GetUnitHealthPercent(oEngineer[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) <= 0.3)))) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': want to keep reclaiming instead of running') end
                                                    else
                                                        local tPositionToRunFrom
                                                        if oNearestEnemy then tPositionToRunFrom = oNearestEnemy:GetPosition()
                                                        elseif tWZPositionToRunFrom then tPositionToRunFrom = tWZPositionToRunFrom
                                                        end
                                                        if not(bIsWaterZone) then
                                                            --Core base - consider running if arent close to midpoint and are closer to enemy than the midpoint is
                                                            iLZOrWZToRunTo =  AiBotLand.GetLandZoneToRunTo(iTeam, iPlateauOrPond, iLandZone, AiBotMap.refPathingTypeHover, oEngineer:GetPosition(), tPositionToRunFrom)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': iLZOrWZToRunTo from normal logic='..iLZOrWZToRunTo..'; subrefLZbCoreBase='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; tPositionToRunFrom='..repru(tPositionToRunFrom)) end
                                                            if iLZOrWZToRunTo and tPositionToRunFrom and tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tPositionToRunFrom) - 10 > AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tPositionToRunFrom) then
                                                                --Retreat further back in core base
                                                                iLZOrWZToRunTo = iLandZone
                                                                TrackEngineerAction(oEngineer, refActionRunToLandZone, false, 1, {iPlateauOrPond, iLZOrWZToRunTo})
                                                            elseif not(iLZOrWZToRunTo == iLandZone) and iLZOrWZToRunTo then --If LZ to run to is same as cur LZ might as well use engineer normally (e.g. might have defences to build)
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will run to LZ '..iLZOrWZToRunTo..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLZOrWZToRunTo][AiBotMap.subrefMidpoint]))..'; refbConstructionStart='..tostring(oEngineer[AiBotUnitInfo.refbConstructionStart] or false)) end
                                                                if AiBotMap.bIsCampaignMap and not(oEngineer[AiBotUnitInfo.refbConstructionStart]) and not(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLZOrWZToRunTo][AiBotMap.subrefMidpoint])) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': campaign map, dont want engi that we havent constructed to retreat outside of playable area in case prevents expansion') end
                                                                else
                                                                    --Run to the LZ
                                                                    AiBotOrders.IssueTrackedMove(oEngineer, AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLZOrWZToRunTo][AiBotMap.subrefMidpoint], 8, false, 'RunTo'..iLZOrWZToRunTo)
                                                                    bEngiIsUnavailable = true
                                                                    TrackEngineerAction(oEngineer, refActionRunToLandZone, false, 1, {iPlateauOrPond, iLZOrWZToRunTo})
                                                                    tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] = math.floor(GetGameTimeSeconds())
                                                                end
                                                            end
                                                        else --Dealing with water zone:
                                                            iLZOrWZToRunTo, iPlateauOrZeroToRunTo = AiBotNavy.GetWaterZoneToRunTo(iTeam, iPlateauOrPond, iLandZone, AiBotMap.refPathingTypeHover, oEngineer:GetPosition(), tPositionToRunFrom, true)

                                                            if iPlateauOrZeroToRunTo == 0 and not(iLZOrWZToRunTo == iLandZone) then --If WZ to run to is same as cur WZ might as well use engineer normally (e.g. might have defences to build); similarly if we would run here from the WZ we want to run to
                                                                --Run to the WZ
                                                                AiBotOrders.IssueTrackedMove(oEngineer, AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iLZOrWZToRunTo][AiBotMap.subrefMidpoint], 8, false, 'NRunTo'..iLZOrWZToRunTo)
                                                                bEngiIsUnavailable = true
                                                                TrackEngineerAction(oEngineer, refActionRunToWaterZone, false, 1, nil, iLZOrWZToRunTo)
                                                                tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] = math.floor(GetGameTimeSeconds())
                                                            elseif (iPlateauOrZeroToRunTo or 0) > 0 and  iLZOrWZToRunTo then
                                                                --Run to the land zone
                                                                AiBotOrders.IssueTrackedMove(oEngineer, AiBotMap.tAllPlateaus[iPlateauOrZeroToRunTo][AiBotMap.subrefPlateauLandZones][iLZOrWZToRunTo][AiBotMap.subrefMidpoint], 8, false, 'WLRunTo'..iLZOrWZToRunTo)
                                                                bEngiIsUnavailable = true
                                                                TrackEngineerAction(oEngineer, refActionRunToLandZone, false, 1, {iPlateauOrZeroToRunTo, iLZOrWZToRunTo})
                                                                tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] = math.floor(GetGameTimeSeconds())
                                                            else
                                                                --Nowhere to run

                                                                --Previous code -have replaced with logic in the function that gets the WZ to run to
                                                                --[[if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                                                    local tClosestRallyPoint
                                                                    local iClosestRallyPointDist = 100000
                                                                    local iCurRallyPointDist
                                                                    for iEntry, tLZSubtable in tLZData[AiBotMap.subrefAdjacentLandZones] do
                                                                        local tCurRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZData, iTeam, tLZSubtable[AiBotMap.subrefWPlatAndLZNumber][1], tLZSubtable[AiBotMap.subrefWPlatAndLZNumber][2], nil)
                                                                        if tCurRallyPoint then
                                                                            iCurRallyPointDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tCurRallyPoint)
                                                                            if iCurRallyPointDist < iClosestRallyPointDist then
                                                                                tClosestRallyPoint = {tCurRallyPoint[1], tCurRallyPoint[2], tCurRallyPoint[3]}
                                                                                iClosestRallyPointDist = iCurRallyPointDist
                                                                            end
                                                                        end
                                                                    end
                                                                    if tClosestRallyPoint then
                                                                        local iPlateau, iLZToRunTo = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tClosestRallyPoint)
                                                                        AiBotOrders.IssueTrackedMove(oEngineer, (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLZToRunTo][AiBotMap.subrefMidpoint] or tClosestRallyPoint), 8, false, 'WLRunTo'..iLZOrWZToRunTo)
                                                                        bEngiIsUnavailable = true
                                                                        TrackEngineerAction(oEngineer, refActionRunToLandZone, false, 1, {iPlateau, iLZToRunTo})
                                                                        tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] = math.floor(GetGameTimeSeconds())
                                                                    end
                                                                end--]]
                                                            end
                                                        end
                                                    end
                                                else
                                                    --We arent yet close enough that we want to run so do nothing
                                                end
                                            end
                                        end
                                    end
                                end
                            else
                                if not(bReclaimingDangerousEnemy) then
                                    bConsiderReclaimableEnemiesInBuildRangeOnly = true
                                end
                            end
                        else
                            --Check we arent reclaiming dangerous enemy
                            if oEngineer:IsUnitState('Reclaiming') then
                                local oReclaimTarget = oEngineer:GetFocusUnit()
                                if oReclaimTarget and not(oReclaimTarget.Dead) and ((oReclaimTarget[AiBotUnitInfo.refiCombatRange] or 0) > 0 or EntityCategoryContains(categories.RECLAIM, oReclaimTarget.UnitId)) then
                                    bReclaimingDangerousEnemy = true
                                end
                            end
                            if not(bReclaimingDangerousEnemy) then
                                bConsiderReclaimableEnemiesInBuildRangeOnly = true
                            end
                        end
                    end
                    if bConsiderReclaimableEnemiesInBuildRangeOnly then
                        --We are doing a high priority action, so only consider reclaimable enemies that are in our build range
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer doing high priority action so will only consider enemies in build range unless close to completion, work progress='..oEngineer:GetWorkProgress()..'; Is primary builder='..tostring(oEngineer[refbPrimaryBuilder])) end
                        if not(oEngineer:GetWorkProgress() >= 0.9) and (not(oEngineer[refbPrimaryBuilder]) or oEngineer:GetWorkProgress() <= 0.6) then
                            local iEngiBuildDistance = oEngineer:GetBlueprint().Economy.MaxBuildDistance
                            if oEngineer[AiBotUnitInfo.refbEasyBrain] then
                                iActualEnemyCategorySearch = iEasyEnemyCategorySearch
                            else
                                iActualEnemyCategorySearch = iNormalEnemyCategorySearch
                            end
                            local tReclaimableEnemies = aiBrain:GetUnitsAroundPoint(iActualEnemyCategorySearch, oEngineer:GetPosition(), iEngiBuildDistance, 'Enemy')
                            local oEnemyCombatOrReclaimer
                            local oOtherEnemy
                            if AiBotUtilities.IsTableEmpty(tReclaimableEnemies) == false then
                                for iEnemy, oEnemy in tReclaimableEnemies do
                                    if (oEnemy[AiBotUnitInfo.refiCombatRange] or 0) > 0 or EntityCategoryContains(categories.RECLAIM, oEnemy.UnitId) then
                                        oEnemyCombatOrReclaimer = oEnemy
                                        break
                                    elseif not(oOtherEnemy) then oOtherEnemy = oEnemy
                                    end
                                end
                            end
                            local oReclaimTarget = oEnemyCombatOrReclaimer or oOtherEnemy
                            if oReclaimTarget then
                                TrackEngineerAction(oEngineer, refActionReclaimEnemyUnit, false, 1)
                                AiBotOrders.IssueTrackedReclaim(oEngineer, oReclaimTarget, false, 'RecPE')
                                if bDebugMessages == true then LOG(sFunctionRef..': Told engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to reclaim enemy that is in its range, enemy='..oReclaimTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oReclaimTarget)) end
                                bEngiIsUnavailable = true
                            end
                        end
                    end
                else
                    bEngiIsUnavailable = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Engi is attached, capturing, or special micro, unit status='..AiBotUnitInfo.GetUnitState(oEngineer)..'; refbSpecialMicroActive='..tostring(oEngineer[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                end



                --Finished checking for enemies; now check more generally if engineer is busy
                if bDebugMessages == true then LOG(sFunctionRef..': Is engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' unavailable='..tostring(bEngiIsUnavailable)) end
                if not(bEngiIsUnavailable) then
                    bEngiIsUnavailable = not(AiBotConditions.IsEngineerAvailable(oEngineer))

                    if bDebugMessages == true then LOG(sFunctionRef..': Entry in table='..iEngineer..'; Considering if engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' is available, result='..tostring(AiBotConditions.IsEngineerAvailable(oEngineer, true) or false)..'; Eng unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; bEngiIsUnavailable='..tostring(bEngiIsUnavailable or false)..'; oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder] ='..repru(oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder] )) end
                    if oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder] and not(oEngineer[refiAssignedAction] == refActionMoveToLandZone) and not(oEngineer[refiAssignedAction] == refActionAttackMoveToLandZone) and not(oEngineer:IsUnitState('Reclaiming')) then
                        local iTargetPlateau = oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder][1]
                        local iTargetZone = oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder][2]

                        oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder] = nil

                        local tTargetZoneData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetZone]

                        if bDebugMessages == true then
                            if not(tTargetZoneData[AiBotMap.subrefMidpoint]) then LOG(sFunctionRef..': Dont have valid midpoint data for target P='..iTargetPlateau..';Z='..iTargetZone)
                            else
                                LOG(sFunctionRef..': Considering if engi is closer to the target sone P'..iTargetPlateau..'Z'..iTargetZone..' zone it used to be traveling to than this midpoint, dist from engi to prev zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tTargetZoneData[AiBotMap.subrefMidpoint], oEngineer:GetPosition())..'; Dist from this zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tTargetZoneData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint]))
                            end
                        end
                        if tTargetZoneData and AiBotUtilities.GetDistanceBetweenPositions(tTargetZoneData[AiBotMap.subrefMidpoint], oEngineer:GetPosition()) <= AiBotUtilities.GetDistanceBetweenPositions(tTargetZoneData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint]) then

                            AiBotOrders.IssueTrackedMove(oEngineer, tTargetZoneData[AiBotMap.subrefMidpoint], 3, false, 'ResumeeMTP'..iTargetPlateau..'Z'..iTargetZone)
                            TrackEngineerAction(oEngineer, refActionMoveToLandZone, false, 1, { iTargetPlateau, iTargetZone })
                            bEngiIsUnavailable = true
                            if bDebugMessages == true then LOG(sFunctionRef..': will send engi '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to this zone, oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo]='..repru(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])) end
                        end
                    elseif bCheckForReclaim then
                        if not(bEngiIsUnavailable) then
                            if AiBotACU.ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrPond, iLandZone, tLZData, tLZTeamData, oEngineer, true, 20) then
                                bEngiIsUnavailable = true
                            end
                        elseif oEngineer:IsUnitState('Moving') and oEngineer[refiAssignedAction] == refActionMoveToLandZone then
                            --Engineer is already busy; exception if engineer is traveling to another zone where want to reissue its old order after issuing a reclaim order
                            local iTargetPlateau = oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][1]
                            local iTargetZone = oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][2]

                            if AiBotACU.ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrPond, iLandZone, tLZData, tLZTeamData, oEngineer, true, 50) then
                                if iTargetPlateau and iTargetZone then

                                    if bDebugMessages == true then LOG(sFunctionRef..': Recording plateau and LZ that engi was going to move to but has been diverted from, iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetZone='..(iTargetZone or 'nil')) end
                                    bEngiIsUnavailable = true
                                    oEngineer[refiPlateauAndZoneTravelingBeforeTempReclaimOrder] = {iTargetPlateau, iTargetZone}
                                elseif bDebugMessages == true then LOG(sFunctionRef..': engi '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; had an action to move to a land zone but didnt have a target plateau or zone recorded (maybe it ran from enemy units?), so it wont resume its orders later')
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bEngiIsUnavailable='..tostring(bEngiIsUnavailable)) end
                if bEngiIsUnavailable then
                    table.insert(toAssignedEngineers, oEngineer)
                else
                    --Clear engineer trackers as redundancy in case failed to clear previously
                    if oEngineer[refiAssignedAction] then ClearEngineerTracking(oEngineer) end

                    table.insert(toAvailableEngineersByTech[AiBotUnitInfo.GetUnitTechLevel(oEngineer)], oEngineer)
                    if bDebugMessages == true then LOG(sFunctionRef..': Just added engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to toAvailableEngineersByTech, Eng tech level='..AiBotUnitInfo.GetUnitTechLevel(oEngineer)..'; Size of table='..table.getn(toAvailableEngineersByTech[AiBotUnitInfo.GetUnitTechLevel(oEngineer)])) end
                    bHaveAvailableEngi = true
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished recording available engineers, Is tEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tEngineers))..'; bHaveAvailableEngi='..tostring(bHaveAvailableEngi)..'; Is toAssignedEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(toAssignedEngineers))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bHaveAvailableEngi then return toAvailableEngineersByTech, toAssignedEngineers
    else return nil, toAssignedEngineers
    end
end

function GetCategoryToBuildOrAssistFromAction(iActionToAssign, iMinTechLevel, aiBrain, tbEngineersOfFactionOrNilIfAlreadyAssigned, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
    --Returns the building category type based on the action; iMinTechLevel is optional; aiBrain is required if dealing with construction of experimental
    --tbEngineersOfFaction is true for each faction that we have an engineer of iMinTechLevel available for, but is nil if we don't need to worry about factions, either due to category or because the unit/building is under construciton already

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetCategoryToBuildOrAssistFromAction'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iCategoryToBuild = tiActionCategory[iActionToAssign]
    local iOptionalFactionRequired --Used for certain categories where chocie of category depended on the faction available
    if bDebugMessages == true then LOG(sFunctionRef..': Time of start='..GetGameTimeSeconds()..'; iActionToAssign='..iActionToAssign..'; iMinTechLevel='..iMinTechLevel..'; aiBrain='..aiBrain.Nickname..'; repru(tbEngineersOfFactionOrNilIfAlreadyAssigned)='..repru(tbEngineersOfFactionOrNilIfAlreadyAssigned)..'; Is tbActionsThatDontHaveCategory[iActionToAssign] nil='..tostring(tbActionsThatDontHaveCategory[iActionToAssign] == nil)..'; Is tiActionCategory[iActionToAssign] nil='..tostring(tiActionCategory[iActionToAssign] == nil)) end
    --Manual adjustments to default category
    if iActionToAssign == refActionBuildGameEnder then
        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] >= 750 then
            iCategoryToBuild = iCategoryToBuild - AiBotUnitInfo.refCategoryParagon
        elseif AiBotConditions.GetTeamLifetimeBuildCount(aiBrain.AiBotTeam, AiBotUnitInfo.refCategoryParagon) > 0 then
            local iParagonUnderConstruction = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZOrWZTeamData, aiBrain.AiBotTeam, AiBotUnitInfo.refCategoryParagon)
            if iParagonUnderConstruction > 0 then
                iCategoryToBuild = iCategoryToBuild - AiBotUnitInfo.refCategoryParagon
            end
        end
        if AiBotConditions.HaveTemplateSpaceForGameEnder(iCategoryToBuild, tLZOrWZData, tLZOrWZTeamData, tbEngineersOfFactionOrNilIfAlreadyAssigned, aiBrain.AiBotTeam) and not(aiBrain.AiBotEasy) then
            tLZOrWZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = iCategoryToBuild
            iCategoryToBuild = refActionManageGameEnderTemplate
        end
    elseif iActionToAssign == refActionBuildQuantumGateway and tLZOrWZTeamData[AiBotMap.subrefbGEShieldSACU] then
        iCategoryToBuild = AiBotUnitInfo.refCategoryQuantumGateway * categories.UEF
    end
    if not(iCategoryToBuild) and not(tbActionsThatDontHaveCategory[iActionToAssign]) then
        if iActionToAssign == refActionBuildEmergencyPD then
            if iMinTechLevel == 3 then --i.e. to allow for T3 only builders
                iCategoryToBuild = AiBotUnitInfo.refCategoryT3PD
            elseif aiBrain[AiBotOverseer.refbCloseToUnitCap] then
                if bDebugMessages == true then LOG(sFunctionRef..': Close to unit cap so will get T2PlusPD') end
                iCategoryToBuild = AiBotUnitInfo.refCategoryT2PlusPD
            else
                if iMinTechLevel == 1 then
                    iCategoryToBuild = AiBotUnitInfo.refCategoryPD - categories.TECH3 - categories.EXPERIMENTAL
                elseif aiBrain[AiBotOverseer.refbCloseToUnitCap] then
                    if bDebugMessages == true then LOG(sFunctionRef..': Close to unit cap so will build T2+ PD') end
                    iCategoryToBuild = AiBotUnitInfo.refCategoryT2PlusPD
                elseif iMinTechLevel > 1 or (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPD * categories.TECH1) > 0)) then
                    --Want to build either T2 or T2+ PD
                    if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 5 or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 then
                        iCategoryToBuild = AiBotUnitInfo.refCategoryPD - categories.TECH3 - categories.EXPERIMENTAL
                        --Just consider T2 PD, dont have good enough tech to try for t3 anyway
                    else
                        local iT2PD = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPD * categories.TECH2)
                        if ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iT2PD <= 1 and (iT2PD == 0 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 7)) or (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (iT2PD <= 5 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPD * categories.TECH3) >= iT2PD)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have many t2 pd so will get more t2 pd (not T3)') end
                            iCategoryToBuild = AiBotUnitInfo.refCategoryPD - categories.TECH3 - categories.EXPERIMENTAL
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Have some T2 PD so will consider getting T3 PD if theyre buildable') end
                            iCategoryToBuild = AiBotUnitInfo.refCategoryT2PlusPD
                            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 12 then iCategoryToBuild = iCategoryToBuild - categories.EXPERIMENTAL end
                        end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Have no T1 PD so will get T1 PD') end
                    iCategoryToBuild = AiBotUnitInfo.refCategoryPD * categories.TECH1
                end
            end
        elseif iActionToAssign == refActionFortifyFirebase then
            AiBotUtilities.ErrorHandler('Firebase logic not in place')
            --Calculate closest firebase and assume we are trying to build this
            if aiBrain[refiFirebaseBeingFortified] then
                iCategoryToBuild = aiBrain[refiFirebaseCategoryWanted][aiBrain[refiFirebaseBeingFortified]]
                if AiBotUtilities.IsTableEmpty(iCategoryToBuild, false) then AiBotUtilities.ErrorHandler('Dont have a category to build for firebase ref '..(aiBrain[refiFirebaseBeingFortified] or 'nil')..'; will just build T2 plus PD')
                    iCategoryToBuild = AiBotUnitInfo.refCategoryT2PlusPD
                end
            else
                AiBotUtilities.ErrorHandler('Dont have a firebase to be fortified so will just build T2 plus PD')
                iCategoryToBuild = AiBotUnitInfo.refCategoryT2PlusPD
            end
        elseif iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental then
            iCategoryToBuild, iOptionalFactionRequired = DecideOnExperimentalToBuild(iActionToAssign, aiBrain, tbEngineersOfFactionOrNilIfAlreadyAssigned, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
        elseif iActionToAssign == refActionBuildShield or iActionToAssign == refActionBuildSecondShield then
            --NOTE: Separately this gets changed to tech3 if need increased range
            if bDebugMessages == true then LOG(sFunctionRef..': Considering building shield, iMinTechLevel='..iMinTechLevel..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount]='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount]..'; Novax count='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyNovaxCount]..'; Enemy air to ground='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; SValue='..tLZOrWZTeamData[AiBotMap.subrefLZSValue]..'; Core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])..'; Cose to unit cap='..tostring(aiBrain[AiBotOverseer.refbCloseToUnitCap])..'; Unit cap adj level='..(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; iMinTechLevel='..iMinTechLevel..'; refiFixedShieldT2EngiFailureCount='..((tLZOrWZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 'nil'))..'; Is table of nearby t2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))..'; aiBrain[AiBotOverseer.refbCloseToUnitCap]='..tostring(aiBrain[AiBotOverseer.refbCloseToUnitCap])) end

            if AiBotMap.bIsCampaignMap or (aiBrain[AiBotOverseer.refbCloseToUnitCap] and (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 0) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield
            elseif iMinTechLevel <= 2 and ((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] <= 1 and tLZOrWZTeamData[AiBotMap.subrefLZSValue] <= 14000) or (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and (not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbDefendAgainstArti]) or (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount] == 0 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyNovaxCount] <= 2)))) and not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.TECH2
                if bDebugMessages == true then LOG(sFunctionRef..': Will build T2 shield') end
            elseif aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (not(AiBotUtilities.bQuietModActive) and not(AiBotUtilities.bLoudModActive))) and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 or (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
                iCategoryToBuild = aiBrain[AiBotOverseer.refiExperimentalShieldCategory] or AiBotUnitInfo.refCategoryFixedShield - categories.TECH2 - categories.TECH1
                if bDebugMessages == true then LOG(sFunctionRef..': Want to allow for experimental tech shields') end
            elseif iMinTechLevel >= 3 or (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbDefendAgainstArti] and (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0 or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyNovaxCount] > 2)) or aiBrain[AiBotOverseer.refbCloseToUnitCap] or (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 12000 and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 8000)) then
                iCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.TECH3
                if bDebugMessages == true then LOG(sFunctionRef..': Only want T3 shields') end
            else
                iCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.TECH2
                if bDebugMessages == true then LOG(sFunctionRef..': Will build T2 shield') end
            end
        elseif iActionToAssign == refActionBuildSpecialObjective then
            if bDebugMessages == true then LOG(sFunctionRef..': Will return nil as should have override category') end
            iCategoryToBuild = nil
        else
            AiBotUtilities.ErrorHandler('Need to add code for action='..(iActionToAssign or 'nil'))
        end
    end
    if iCategoryToBuild and not(iCategoryToBuild == refActionManageGameEnderTemplate) then
        --Power specific - only build at the minimum tech level, presume this is so if we want to build T1/T2 power while having access to T3 (due to very low power) we can; will therefore add adjustment when looking for part-build buildings to counter this
        if iActionToAssign == refActionBuildPower then
            --Only restrict the power we will build if we have no unit restrictions and/or arent in a campaign
            if not(AiBotOverseer.bUnitRestrictionsArePresent or AiBotMap.bIsCampaignMap) then
                iCategoryToBuild = iCategoryToBuild * AiBotUnitInfo.ConvertTechLevelToCategory(iMinTechLevel)
            end
        else
            if iMinTechLevel > 1 then
                if iMinTechLevel == 3 then iCategoryToBuild = iCategoryToBuild * categories.TECH3 + iCategoryToBuild*categories.EXPERIMENTAL
                else iCategoryToBuild = iCategoryToBuild - categories.TECH1
                end
            end
        end
        --Unit cap - dont build T1 if near cap, and only build experimentals if very near cap
        if aiBrain[AiBotOverseer.refbCloseToUnitCap] then
            if bDebugMessages == true then LOG(sFunctionRef..': Are close to unit cap, wont build T1 units, does category to build contain only T1 and not HQ or mex='..tostring(AiBotUtilities.DoesCategoryContainCategory(categories.TECH1, iCategoryToBuild, true))..'; Does it contain HQ or T3 or experimental='..tostring(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryAllHQFactories + categories.TECH3 + categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower * categories.TECH2, iCategoryToBuild))) end
            if AiBotUtilities.DoesCategoryContainCategory(categories.TECH1  - AiBotUnitInfo.refCategoryAirStaging - AiBotUnitInfo.refCategoryT1Mex, iCategoryToBuild, true) and not(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryAllHQFactories + categories.TECH3 + categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower * categories.TECH2, iCategoryToBuild)) and (not(tLZOrWZTeamData[AiBotMap.subrefLZFortify]) or (not(iActionToAssign == refActionBuildT1Radar) and not(iActionToAssign == refActionBuildT2Radar))) then
                iCategoryToBuild = nil
            elseif aiBrain[AiBotOverseer.refiExpectedRemainingCap] < 15 then
                if not(AiBotUtilities.DoesCategoryContainCategory(categories.TECH3 + categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower * categories.TECH2, iCategoryToBuild)) then
                    iCategoryToBuild = nil
                end
            elseif (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 1 and aiBrain:GetCurrentUnits(iCategoryToBuild) >= 100 then
                if AiBotUtilities.DoesCategoryContainCategory(categories.TECH3 + categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower * categories.TECH2, iCategoryToBuild) and aiBrain:GetCurrentUnits(iCategoryToBuild) > 150 then
                    --Do nothing
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Have lots of the target category to build so wont build any more') end
                    iCategoryToBuild = nil
                end

            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is iCategoryToBuild nil after unit cap adjustment='..tostring(iCategoryToBuild == nil)) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCategoryToBuild, iOptionalFactionRequired
end

function GetEngineersOfTechWanted(iMinTechLevelWanted, toAvailableEngineersByTech)
    local tEngineersOfTechWanted
    if iMinTechLevelWanted == 3 then
        tEngineersOfTechWanted = toAvailableEngineersByTech[3]
    else
        tEngineersOfTechWanted = {}
        if iMinTechLevelWanted == 2 then
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[2]) == false then
                for iEngi, oEngi in toAvailableEngineersByTech[2] do
                    table.insert(tEngineersOfTechWanted, oEngi)
                end
            end
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3]) == false then
                for iEngi, oEngi in toAvailableEngineersByTech[3] do
                    table.insert(tEngineersOfTechWanted, oEngi)
                end
            end
        else
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[1]) == false then
                for iEngi, oEngi in toAvailableEngineersByTech[1] do
                    table.insert(tEngineersOfTechWanted, oEngi)
                end
            end
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[2]) == false then
                for iEngi, oEngi in toAvailableEngineersByTech[2] do
                    table.insert(tEngineersOfTechWanted, oEngi)
                end
            end
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3]) == false then
                for iEngi, oEngi in toAvailableEngineersByTech[3] do
                    table.insert(tEngineersOfTechWanted, oEngi)
                end
            end
        end
    end
    return tEngineersOfTechWanted
end

function GetPartCompleteBuildingInZone(iTeam, iPlateauOrPond, iLandOrWaterZone, iCategoryWanted, bIsWaterZone, iConstructionCountToIgnore)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPartCompleteBuildingInZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iValidCount = 0
    if bDebugMessages == true then

        local tBlueprints = {}
        LOG(sFunctionRef..': Start of code at game time seconds='..GetGameTimeSeconds()..', iPlateauOrPond='..(iPlateauOrPond or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; bIsWaterZone='..tostring(bIsWaterZone or false)..'; iTeam='..iTeam..' iConstructionCountToIgnore='..(iConstructionCountToIgnore or 'nil'))
        if iCategoryWanted then tBlueprints = EntityCategoryGetUnitList(iCategoryWanted)
        else LOG(sFunctionRef..': iCategoryWanted is nil')
        end
        LOG(sFunctionRef..': will list out every blueprint of iCategoryWanted='..reprs(tBlueprints))
    end
    local tLZOrWZTeamData
    if bIsWaterZone then
        tLZOrWZTeamData = AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
    else
        tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
    end
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        if iCategoryWanted then
            local tBuildingsOfCategory = EntityCategoryFilterDown(iCategoryWanted, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of buildings of category empty='..tostring(AiBotUtilities.IsTableEmpty(tBuildingsOfCategory))) end
            if AiBotUtilities.IsTableEmpty(tBuildingsOfCategory) == false then
                for iUnit, oUnit in tBuildingsOfCategory do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fractino compelte='..oUnit:GetFractionComplete()..'; oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]='..tostring(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction] or false)) end
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 and not(oUnit[AiBotBuilding.refoGameEnderBeingShielded]) and not(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                        --If upgrading a factory then assist this unless we have high mass and dont have low power
                        if not(oUnit:IsUnitState('BeingUpgraded')) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.2 or AiBotConditions.HaveLowPower(iTeam) or (table.getn(tBuildingsOfCategory) >= 4 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 or iCategoryWanted == AiBotUnitInfo.refCategoryLandFactory)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Found a part complete building '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..', will return this') end
                            if (iConstructionCountToIgnore or 0) <= iValidCount then
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return oUnit
                            else
                                iValidCount = iValidCount + 1
                            end
                        end
                    end
                end
            end
        else
            AiBotUtilities.ErrorHandler('No category wanted specified')
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return nil
end

function RemoveBuildingFromQueuedBuildings(oEngineer, oBuilding)
    --Intended to be called when oEngineer starts building oBuilding
    if AiBotUtilities.IsTableEmpty(oEngineer[reftQueuedBuildings]) == false then
        for iEntry, tOrderDetails in oEngineer[reftQueuedBuildings] do
            if tOrderDetails[subrefBuildingID] == oBuilding.UnitId and math.abs(oBuilding:GetPosition()[1] - tOrderDetails[subrefBuildingLocation][1]) < 0.5 and math.abs(oBuilding:GetPosition()[3] - tOrderDetails[subrefBuildingLocation][3]) < 0.5 then
                local tLZOrWZTeamData, tLZOrWZData
                if tOrderDetails[subrefPlateauOrZero] == 0 then
                    tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tOrderDetails[subrefLandOrWaterZone]]][AiBotMap.subrefPondWaterZones][tOrderDetails[subrefLandOrWaterZone]]
                    tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam]
                else
                    --Dealing with land zone
                    tLZOrWZData = AiBotMap.tAllPlateaus[tOrderDetails[subrefPlateauOrZero]][AiBotMap.subrefPlateauLandZones][tOrderDetails[subrefLandOrWaterZone]]
                    tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
                end
                ChangeQueuedLocationsTracker(tOrderDetails[subrefBuildingLocation], tLZOrWZData, tOrderDetails[subrefBuildingRadius], false)
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]) == false then
                    for iLZEntry, tLZOrWZOrderDetails in tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings] do
                        if tLZOrWZOrderDetails[AiBotMap.subrefQueueRef] == tOrderDetails[subrefQueueRef] then
                            table.remove(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings], iLZEntry)
                            break
                        end
                    end
                end

                table.remove(oEngineer[reftQueuedBuildings], iEntry)
                break
            end

        end
    end
end

function RefreshPartBuiltMexList(tLZOrWZTeamData)
    local iRevisedIndex = 1
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
        local iTableSize = table.getn(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes])

        for iOrigIndex=1, iTableSize do
            if AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iOrigIndex]) and tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iOrigIndex]:GetFractionComplete() < 1 then
                --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                if (iOrigIndex ~= iRevisedIndex) then
                    tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iRevisedIndex] = tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iOrigIndex];
                    tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iOrigIndex] = nil;
                end
                iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
            else
                tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes][iOrigIndex] = nil;
            end
        end
        if iRevisedIndex < iTableSize then
            --table.setn(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes], iRevisedIndex - 1)
            for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                table.remove(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes], iRemovalEntry)
            end
        end
    end
end

function UpdatePartBuiltListForCompletedMex(oMex)
    if oMex:GetAIBrain().AiBotAI and oMex:GetFractionComplete() == 1 then
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oMex:GetPosition())
        if iLandZone > 0 then
            RefreshPartBuiltMexList(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oMex:GetAIBrain().AiBotTeam])
        end

    end
end


function RecordPartBuiltMex(oEngineer, oMex)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordPartBuiltMex'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oMex:GetPosition())
    local iWaterZone, iPond
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..': oEngineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' has just started building oMex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
    if (iLandZone or 0) == 0 then
        iWaterZone = AiBotMap.GetWaterZoneFromPosition(oMex:GetPosition())
        iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
    end
    if iLandZone > 0 or (iWaterZone > 0 and iPond > 0) then
        if oMex:GetAIBrain().AiBotAI then
            local tLZOrWZTeamData
            if iLandZone > 0 then tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oMex:GetAIBrain().AiBotTeam]
            else tLZOrWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][oMex:GetAIBrain().AiBotTeam]
            end
            if not(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes]) then tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes] = {} end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes]) then
                if not(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes]) then tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes] = {} end
                table.insert(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes], oMex)
                if bDebugMessages == true then LOG(sFunctionRef..': Added the mex to the table of part built mexes') end
            else
                local bAlreadyInTable = false
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes] do
                    if oUnit == oMex then bAlreadyInTable = true break end
                end
                if not(bAlreadyInTable) then
                    table.insert(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes], oMex)
                    if bDebugMessages == true then LOG(sFunctionRef..': Mex not already recorded so added to the table of part built mexes') end
                end
            end
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end



function ClearEngineerTracking(oEngineer)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ClearEngineerTracking'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Is paused='..tostring(oEngineer[AiBotUnitInfo.refbPaused] or false)..'; oEngineer[refbBuildingExperimental]='..tostring(oEngineer[refbBuildingExperimental] or false)..'; oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo]='..repru(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])..'; oEngineer[reftAssignedReclaimSegments]='..repru(oEngineer[reftAssignedReclaimSegments])..'; Is table of queued buildings empty='..tostring(AiBotUtilities.IsTableEmpty(oEngineer[reftQueuedBuildings]))..'; Is table of engineers assisting this empty='..tostring(AiBotUtilities.IsTableEmpty(oEngineer[AiBotUnitInfo.reftoUnitsAssistingThis]))..'; Do we have a valid unit for special shield tracking='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer[refoUnitActivelyShielding]))..'; oEngineer[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineer[AiBotBuilding.reftArtiTemplateRefs])..'; oEngineer[refbBuildingExperimental]='..tostring(oEngineer[refbBuildingExperimental] or false)..'; refiRepairProgressWhenLastChecked='..(oEngineer[refiRepairProgressWhenLastChecked] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    --Unpause unit if it was paused (redundancy)
    if oEngineer[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseMassUsage(oEngineer, false) end

    --Reset stuck count
    oEngineer[AiBotConditions.refiEngineerStuckCheckCount] = 0

    oEngineer[refbPrimaryBuilder] = false
    oEngineer[refiAssignedActionPriority] = nil
    oEngineer[refiAssignedAction] = nil
    oEngineer[refbHasSpareAction] = nil
    if oEngineer[refiRepairProgressWhenLastChecked] then oEngineer[refiRepairProgressWhenLastChecked] = nil end

    --Update experimental construction tracking:
    if oEngineer[refbBuildingExperimental] then
        --As backup, also remove any dead engineers from this table
        oEngineer[refbBuildingExperimental] = nil
        local iRevisedIndex = 1
        local tArray = AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]
        local iTableSize = table.getn(tArray)
        if bDebugMessages == true then LOG(sFunctionRef..': removing engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' from table of engis building experimentals, iTableSize='..iTableSize) end
        for iOrigIndex=1, iTableSize do
            if tArray[iOrigIndex] then
                if tArray[iOrigIndex][refbBuildingExperimental] and oEngineer ~= tArray[iOrigIndex] and AiBotUnitInfo.IsUnitValid(tArray[iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                    --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                    if (iOrigIndex ~= iRevisedIndex) then
                        tArray[iRevisedIndex] = tArray[iOrigIndex];
                        tArray[iOrigIndex] = nil;
                    end
                    iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                else
                    tArray[iOrigIndex] = nil;
                end
            end
        end

        if iRevisedIndex < iTableSize then
            --table.setn(tArray, iRevisedIndex - 1)
            for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                table.remove(tArray, iRemovalEntry)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': table size after removal='..table.getn(tArray)..'; iRevisedIndex='..iRevisedIndex..'; tArray[iTableSize]='..(tArray[iTableSize].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tArray[iTableSize]) or 'nil')) end
    end

    --Update details of engineers moving to a plateau
    if oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo] then
        local tTargetLZTeamData = AiBotMap.tAllPlateaus[oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][1]][AiBotMap.subrefPlateauLandZones][oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo][2]][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
        if tTargetLZTeamData and AiBotUtilities.IsTableEmpty(tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': removing from table of engis traveling here, size of table='..table.getn(tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere])) end
            for iUnit, oUnit in tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                if oUnit == oEngineer then
                    table.remove(tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere][iUnit])
                    break
                end
            end
        end
    end
    oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo] = nil

    --Clear reclaim assignment tracking
    if oEngineer[reftAssignedReclaimSegments] then
        if bDebugMessages == true then LOG(sFunctionRef..': Engineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; reftAssignedReclaimSegments='..repru(oEngineer[reftAssignedReclaimSegments])) end
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.tReclaimAreas[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]][AiBotMap.refReclaimSegmentMidpoint])
        if (iLandZone or 0) > 0 then
            local tEngiAssignedByReclaim = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam][AiBotMap.subrefReclaimAreaAssignmentsBySegment]
            if tEngiAssignedByReclaim and tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] then tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] = math.max(0, (tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] or 0) - 1) end
        elseif (iPlateau or 0) > 0 then
            local iWaterZone = AiBotMap.GetWaterZoneFromPosition(AiBotMap.tReclaimAreas[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]][AiBotMap.refReclaimSegmentMidpoint])
            if (iWaterZone or 0) > 0 then
                local tEngiAssignedByReclaim = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam][AiBotMap.subrefReclaimAreaAssignmentsBySegment]
                if tEngiAssignedByReclaim and tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] then tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] = math.max(0, (tEngiAssignedByReclaim[oEngineer[reftAssignedReclaimSegments][1]][oEngineer[reftAssignedReclaimSegments][2]] or 0) - 1) end
            end
        end
        oEngineer[reftAssignedReclaimSegments] = nil
    end

    --Clear any queued building orders
    if AiBotUtilities.IsTableEmpty(oEngineer[reftQueuedBuildings]) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': removing from table of queued buildings, size of table='..table.getn(oEngineer[reftQueuedBuildings])) end
        for iEntry, tOrderDetails in oEngineer[reftQueuedBuildings] do
            local tLZOrWZTeamData, tLZOrWZData
            if tOrderDetails[subrefPlateauOrZero] > 0 then
                tLZOrWZData = AiBotMap.tAllPlateaus[tOrderDetails[subrefPlateauOrZero]][AiBotMap.subrefPlateauLandZones][tOrderDetails[subrefLandOrWaterZone]]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            else
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tOrderDetails[subrefLandOrWaterZone]]][AiBotMap.subrefPondWaterZones][tOrderDetails[subrefLandOrWaterZone]]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            end
            ChangeQueuedLocationsTracker(tOrderDetails[subrefBuildingLocation], tLZOrWZData, tOrderDetails[subrefBuildingRadius], false)

            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]) == false then
                for iLZEntry, tLZOrderDetails in tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings] do
                    if tLZOrderDetails[AiBotMap.subrefQueueRef] == tOrderDetails[subrefQueueRef] then
                        table.remove(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings], iLZEntry)
                        break
                    end
                end
            end
        end
    end
    oEngineer[reftQueuedBuildings] = nil

    --Clear assisting engineers
    if AiBotUtilities.IsTableEmpty(oEngineer[AiBotUnitInfo.reftoUnitsAssistingThis]) == false then
        local tEngineersToRemove = {}
        if bDebugMessages == true then LOG(sFunctionRef..': Will clear all engineers assisting this, number of engineers assisting='..table.getn(oEngineer[AiBotUnitInfo.reftoUnitsAssistingThis])) end
        for iAssistingEngineer, oAssistingEngineer in oEngineer[AiBotUnitInfo.reftoUnitsAssistingThis] do
            if AiBotUnitInfo.IsUnitValid(oAssistingEngineer) then
                table.insert(tEngineersToRemove, oAssistingEngineer)
            end
        end
        for iAssistingEngineer, oAssistingEngineer in tEngineersToRemove do
            if not(oAssistingEngineer == oEngineer) and not(oEngineer['AiBotTempClearing']) then
                oEngineer['AiBotTempClearing'] = true
                AiBotOrders.IssueTrackedClearCommands(oAssistingEngineer)
                oEngineer['AiBotTempClearing'] = nil
            end
        end
        oEngineer[AiBotUnitInfo.reftoUnitsAssistingThis] = nil
    end

    --Clear special shield tracking
    if oEngineer[refoUnitActivelyShielding] then
        if AiBotUnitInfo.IsUnitValid(oEngineer[refoUnitActivelyShielding]) then
            if AiBotUtilities.IsTableEmpty(oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': remvogin from special shield engineers list, size of list='..table.getn(oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding])) end
                for iRecordedEngi, oRecordedEngi in oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding] do
                    if oRecordedEngi == oEngineer then
                        table.remove(oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding], iRecordedEngi)
                        break
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding]) then
            oEngineer[refoUnitActivelyShielding][reftEngineersActivelyShielding] = nil
        end
        oEngineer[refoUnitActivelyShielding] = nil

    end

    --Clear gameender tracking
    if oEngineer[AiBotBuilding.reftArtiTemplateRefs] then
        local iTemplateRef = oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]
        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oEngineer:GetPosition(), true, oEngineer:GetAIBrain().AiBotTeam)
        if bDebugMessages == true then LOG(sFunctionRef..': About to remove engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' from GE template, is table of engineers for this template empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]))..'; oEngineer[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineer[AiBotBuilding.reftArtiTemplateRefs])) end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': removing from list of engineers assigned to GE Template, size of table='..table.getn(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers])) end
            for iRecordedEngi, oRecordedEngi in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers] do
                if oRecordedEngi == oEngineer then
                    table.remove(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers], iRecordedEngi)
                    break
                end
            end
        end
        local tAltLZData = AiBotMap.tAllPlateaus[oEngineer[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oEngineer[AiBotBuilding.reftArtiTemplateRefs][2]]
        if tAltLZData and not(tAltLZData == tLZData) then
            local tAltLZTeamData = tAltLZData[AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': AltLZData based on engi recorded GE template arti ref is dif so will also check this table to remove, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]))) end
            if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': removing from list of engineers assigned to GE Template, size of table='..table.getn(tAltLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers])) end
                for iRecordedEngi, oRecordedEngi in tAltLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers] do
                    if oRecordedEngi == oEngineer then
                        table.remove(tAltLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers], iRecordedEngi)
                        break
                    end
                end
            end
        end
        oEngineer[AiBotBuilding.reftArtiTemplateRefs] = nil
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TrackQueuedBuilding(oEngineer, sBuildingID, tBuildLocation)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TrackQueuedBuilding'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time='..GetGameTimeSeconds()..'; oEngineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; sBuildingID='..(sBuildingID or 'nil')..'; tBuildLocation='..repru(tBuildLocation)..'; iCurQueueRefNumber='..iCurQueueRefNumber) end

    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tBuildLocation)

    if iPlateauOrZero > 0 then
        if (iLandOrWaterZone or 0) == 0 then
            iLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(tBuildLocation)
            iPlateauOrZero = 0
        end
        if iLandOrWaterZone > 0 then
            iCurQueueRefNumber = iCurQueueRefNumber + 1
            if not(oEngineer[reftQueuedBuildings]) then oEngineer[reftQueuedBuildings] = {} end
            if bDebugMessages == true then LOG(sFunctionRef..': About to get building size='..(AiBotUnitInfo.GetBuildingSize(sBuildingID) or 'nil')) end
            local iBuildingRadius = math.floor(AiBotUnitInfo.GetBuildingSize(sBuildingID) * 0.5)
            table.insert(oEngineer[reftQueuedBuildings], {[subrefQueueRef] = iCurQueueRefNumber, [subrefBuildingID] = sBuildingID, [subrefBuildingLocation] = tBuildLocation, [subrefBuildingRadius] = iBuildingRadius, [subrefPlateauOrZero] = iPlateauOrZero, [subrefLandOrWaterZone] = iLandOrWaterZone})
            local tLZOrWZTeamData, tLZOrWZData
            if iPlateauOrZero > 0 then
                tLZOrWZData  = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            else
                --Water zone
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            end

            if iPlateauOrZero == 0 then

                tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            else
                tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
            end
            if not(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]) then tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings] = {} end
            table.insert(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings], {[AiBotMap.subrefQueueRef] = iCurQueueRefNumber, [AiBotMap.subrefBuildingID] = sBuildingID, [AiBotMap.subrefBuildingLocation] = tBuildLocation, [AiBotMap.subrefBuildingRadius] = iBuildingRadius, [AiBotMap.subrefPrimaryBuilder] = oEngineer})
            --Record the locations as being queued
            ChangeQueuedLocationsTracker(tBuildLocation, tLZOrWZData, iBuildingRadius, true)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ChangeQueuedLocationsTracker(tBuildLocation, tLZOrWZData, iBuildingRadius, bAddToQueue)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ChangeQueuedLocationsTracker'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iBaseX = math.floor(tBuildLocation[1])
    local iBaseZ = math.floor(tBuildLocation[3])
    for iX = iBaseX - iBuildingRadius, iBaseX + iBuildingRadius, 1 do
        if bAddToQueue then
            if not(tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX]) then
                if not(tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition]) then tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition] = {} end
                tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX] = {}
            end
            for iZ = iBaseZ - iBuildingRadius, iBaseZ + iBuildingRadius do
                tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX][iZ] = true
            end
        else
            if tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX] then
                for iZ = iBaseZ - iBuildingRadius, iBaseZ + iBuildingRadius do
                    tLZOrWZData[AiBotMap.subrefQueuedLocationsByPosition][iX][iZ] = nil
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TrackEngineerAction(oEngineer, iActionToAssign, bIsPrimaryBuilder, iCurPriority, tOptionalPlatAndLandToMoveTo, vOptionalOtherVariable, bMarkAsSpare)
    --bIsPrimaryBuilder - true if engineer will be building the item in question (so false if assisting an engineer or repairing a building or assisting an upgrade or moving somewhere etc.
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TrackEngineerAction'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --Special logic (done in a genric way in case end up with more scenarios like this) - if action to assign currnetly is special shield logic and we have a different action to assign then clear engineer tracking (as we have an override that prevents it being cleared via orders)
    if oEngineer[refiAssignedAction] and not(oEngineer[refiAssignedAction] == iActionToAssign) then ClearEngineerTracking(oEngineer) end

    oEngineer[refiAssignedAction] = iActionToAssign
    oEngineer[refbPrimaryBuilder] = (bIsPrimaryBuilder or false)
    oEngineer[refiAssignedActionPriority] = iCurPriority
    oEngineer[refbHasSpareAction] = bMarkAsSpare

    --Track experimental construction
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; iActionToAssign='..iActionToAssign..'; oEngineer[refbBuildingExperimental]='..tostring(oEngineer[refbBuildingExperimental])..'; Last order blueprint='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental or iActionToAssign == refActionBuildGameEnder or iActionToAssign == refActionBuildExperimentalNavy or iActionToAssign == refActionBuildLandExperimental or iActionToAssign == refActionManageGameEnderTemplate or iActionToAssign == refActionBuildAirExperimental then
        if not(oEngineer[refbBuildingExperimental]) then --dont want engineers on GE template to keep being added to table
            table.insert(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals], oEngineer)
            oEngineer[refbBuildingExperimental] = true
            if bDebugMessages == true then
                local iDeadCount = 0
                for iUnit, oUnit in AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals] do
                    if oUnit.Dead then iDeadCount = iDeadCount + 1 end
                end
                LOG(sFunctionRef..': Adding engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to team '..oEngineer:GetAIBrain().AiBotTeam..' table of engineers building experimental, size of table='..table.getn(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals])..'; iDeadCount='..iDeadCount)
            end
        elseif bDebugMessages == true then
            LOG(sFunctionRef..': Will now check if this engineer is already recorded in the table, is table empty='..tostring(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]))
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]) == false then
                for iRecorded, oRecorded in AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals] do
                    if oRecorded == oEngineer then LOG(sFunctionRef..': engi is recorded, iRecorded entry='..iRecorded) break end
                end
            end
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': Clearing flag for engineer to be building an experimental') end
        oEngineer[refbBuildingExperimental] = nil
    end

    --Track info e.g. for units moving to other plateaus
    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oEngineer:GetPosition(), true, oEngineer)
    local tTargetLZTeamData
    if tOptionalPlatAndLandToMoveTo then
        oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo] = {tOptionalPlatAndLandToMoveTo[1], tOptionalPlatAndLandToMoveTo[2]}
        tTargetLZTeamData = AiBotMap.tAllPlateaus[tOptionalPlatAndLandToMoveTo[1]][AiBotMap.subrefPlateauLandZones][tOptionalPlatAndLandToMoveTo[2]][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
        if bDebugMessages == true then LOG(sFunctionRef..': Recorded engi as having a plateau to move to, oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo]='..repru(oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo])) end
    end
    if vOptionalOtherVariable then
        if iActionToAssign == refActionReclaimArea then
            oEngineer[reftAssignedReclaimSegments] = vOptionalOtherVariable
        elseif iActionToAssign == refActionRunToWaterZone or iActionToAssign == refActionMoveToWaterZone then
            if bDebugMessages == true then LOG(sFunctionRef..': Engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' wants to move to water zone '..vOptionalOtherVariable..'; iCurPriority='..(iCurPriority or 'nil')) end
            oEngineer[AiBotLand.reftiPlateauAndLZToMoveTo] = nil
            oEngineer[AiBotNavy.refiWZToMoveTo] = vOptionalOtherVariable
            local iPond = AiBotMap.tiPondByWaterZone[vOptionalOtherVariable]
            tTargetLZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][vOptionalOtherVariable][AiBotMap.subrefWZTeamData][oEngineer:GetAIBrain().AiBotTeam]
        else AiBotUtilities.ErrorHandler('vOptionalOtherVariable is specified but dont know what for, iActionToAssign='..iActionToAssign)
        end
    end

    --Track if we are moving to a land or water zone
    if tTargetLZTeamData then
        if not(tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) then tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere] = {} end
        table.insert(tTargetLZTeamData[AiBotMap.subrefTEngineersTravelingHere], oEngineer)
        --Reduce BP wanted by the LZ, and no longer flag it as wanting BP if this satisfies all its needs
        local iEngiTechLevel = AiBotUnitInfo.GetUnitTechLevel(oEngineer)
        for iTech = iEngiTechLevel, 1, -1 do
            if tTargetLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                tTargetLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] = tTargetLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] - oEngineer:GetBlueprint().Economy.BuildRate
                local bNoLongerWantBP = false
                if tTargetLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] <= 0 then
                    bNoLongerWantBP = true
                    for iAltTech = iTech, 1, -1 do
                        if tTargetLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iAltTech] > 0 then
                            bNoLongerWantBP = false
                            break
                        end
                    end
                end
                if bNoLongerWantBP then
                    tTargetLZTeamData[AiBotMap.subrefTbWantBP] = false
                end
                break
            end
        end
    end

    --Track potential blacklist locations for primary engineers - note that more general queued building construction tracking is done via TrackQueuedBuilding based on when an order is given to construct something
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to track engineer for blacklisted locations, Time='..GetGameTimeSeconds()..'; Engineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; bIsPrimaryBuilder='..tostring(bIsPrimaryBuilder or false)..'; oEngineer[AiBotOrders.refiOrderCount]='..(oEngineer[AiBotOrders.refiOrderCount] or 'nil')..'; Last order type='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] or 'nil')) end
    if bIsPrimaryBuilder and not(tbActionsThatDontHaveCategory[iActionToAssign]) and oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild then
        ForkThread(MonitorEngineerForBlacklistLocation, oEngineer)
    end

    --Reclaim tracking
    if oEngineer[refiSequentialReclaimCount] and not(tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueReclaim) and not(tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueAggressiveMove) then
        oEngineer[refiSequentialReclaimCount] = nil
    end

    --Unpause engineer
    if oEngineer[AiBotUnitInfo.refbPaused] then
        AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineer, false)
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' action='..(oEngineer[refiAssignedAction] or 'nil')..'; refbBuildingExperimental='..tostring((oEngineer[refbBuildingExperimental] or false))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveSameTargetAndNotStartedBuilding'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if bDebugMessages == true then
        if AiBotUnitInfo.IsUnitValid(oEngineer) then
            LOG(sFunctionRef..': time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..': Engineer is valid, refbPrimaryBuilder='..tostring(oEngineer[refbPrimaryBuilder])..'; Assigned action='..(oEngineer[refiAssignedAction] or 'nil')..'; Engineer unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; Qued buildings queue ref='..(oEngineer[reftQueuedBuildings][1][subrefQueueRef] or 'nil')..'; Last order blueprint='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Last order position='..repru(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition] or {'nil'}))
        else
            LOG(sFunctionRef..': Engineer is no longer valid')
        end
    end
    if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer[refbPrimaryBuilder] and oEngineer[refiAssignedAction] == iOrigAction and not(oEngineer:IsUnitState('Building')) and not(oEngineer:IsUnitState('Repairing')) and oEngineer[reftQueuedBuildings][1][subrefQueueRef] == iOrigQueueRef and sOrigBlueprint == oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] then --and oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition], tOrigBuildLocation) <= 1 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    end
end

function ClearBlacklistForUnitConstructed(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ClearBlacklistForUnitConstructed'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is table of blacklists empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit[reftUnitBlacklistSegmentXZ]))) end
    if AiBotUtilities.IsTableEmpty(oUnit[reftUnitBlacklistSegmentXZ]) == false then
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        if iPlateauOrZero and (iLandOrWaterZone or 0) > 0 then
            local tLZOrWZData
            if iPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            end
            for iEntry, tiSegmentXZ in oUnit[reftUnitBlacklistSegmentXZ] do
                if tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][tiSegmentXZ[1]][tiSegmentXZ[2]] then tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][tiSegmentXZ[1]][tiSegmentXZ[2]] = nil end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished clearing the blacklisted locations, iPlateau='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; repru of blacklisted locations for zone='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition])) end
        end
    end
    oUnit[reftUnitBlacklistSegmentXZ] = nil
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedBlacklistReset(tLZOrWZData, iX, iZ, iResetTimeInSeconds, oOptionalUnitToTrack)
    WaitSeconds(iResetTimeInSeconds)
    if not(oOptionalUnitToTrack) or not(AiBotUnitInfo.IsUnitValid(oOptionalUnitToTrack)) then
        tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iX][iZ] = nil
    end
end

function RecordBlacklistLocation(tLocation, iRadius, iResetTimeInSeconds, oOptionalUnitToTrack)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordBlacklistLocation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --oOptionalUnitToTrack - i.e. should have experimental units under construction specified here - if specified, means iresettimeinseconds only triggers if that unit doesnt exist, as a redundancy for if we failed to pickup the event when it died
    --iResetTimeInSeconds - per above, if  oOptionalUnitToTrack is specififed then this only triggers if hte unit no longer exists after waiting iResetTimeInSeconds

    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLocation)
    if bDebugMessages == true then LOG(sFunctionRef..': Gametimeseconds='..GetGameTimeSeconds()..'; tLocation='..repru(tLocation)..'; iRadius='..(iRadius or 'nil')..'; iResetTimeInSeconds='..(iResetTimeInSeconds or 'nil')..'; oOptionalUnitToTrack='..(oOptionalUnitToTrack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalUnitToTrack) or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
    if (iLandOrWaterZone or 0) > 0 then
        local tLZOrWZData
        if iPlateauOrZero == 0 then
            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        end
        if oOptionalUnitToTrack then
            oOptionalUnitToTrack[reftUnitBlacklistSegmentXZ] = {}
        end


        local iBaseX = math.floor(tLocation[1])
        local iBaseZ = math.floor(tLocation[3])
        local iSegmentRadius = math.floor(iRadius / AiBotMap.iLandZoneSegmentSize)
        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through every position for iSegmentRadius='..iSegmentRadius..'; iBaseX='..iBaseX..'; iBaseZ='..iBaseZ) end
        for iX = iBaseX - iSegmentRadius, iBaseX + iSegmentRadius do
            for iZ = iBaseZ - iSegmentRadius, iBaseZ + iSegmentRadius do
                if not(tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iX][iZ]) then
                    if not(tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iX]) then
                        if not(tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition]) then tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition] = {} end
                        tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iX] = {}
                    end
                    tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition][iX][iZ] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Added blacklist to location iX='..iX..'; iZ='..iZ..'; iResetTimeInSeconds='..(iResetTimeInSeconds or 'nil')) end
                    if (iResetTimeInSeconds or 0) >= 0 then
                        ForkThread(DelayedBlacklistReset, tLZOrWZData, iX, iZ, iResetTimeInSeconds, oOptionalUnitToTrack)
                    end
                    if oOptionalUnitToTrack then
                        table.insert(oOptionalUnitToTrack[reftUnitBlacklistSegmentXZ], {iX, iZ})
                        if bDebugMessages == true then LOG(sFunctionRef..': Added blacklist location for oOptionalUnitToTrack='..oOptionalUnitToTrack.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOptionalUnitToTrack)..'; X'..iX..'Z'..iZ) end
                    end
                else
                    --Already reocrded as a blacklist so wont rerecord/add a new reset to it
                end
            end
        end
        if bDebugMessages == true then
            LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Added location to the blacklist, tLocation='..repru(tLocation)..'; iRadius='..(iRadius or 0)..'; iResetTimeInSeconds='..(iResetTimeInSeconds or 'nil')..'; repru of blacklist locations='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationBlacklistByPosition])..'; will draw all blacklisted locations for this LZ')
            DrawBlacklistedLocations(tLZOrWZData)
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorEngineerForBlacklistLocation(oEngineer)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorEngineerForBlacklistLocation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    local sOrigBlueprint = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint]
    --Only consider engineers with a single queued up building
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; sOrigBlueprint='..(sOrigBlueprint or 'nil')..'; Is table of queued buildings empty='..tostring(AiBotUtilities.IsTableEmpty(oEngineer[reftQueuedBuildings]))..'; Size of queued buildings table='..table.getn(oEngineer[reftQueuedBuildings] or {})) end
    if sOrigBlueprint and AiBotUtilities.IsTableEmpty(oEngineer[reftQueuedBuildings]) == false and table.getn(oEngineer[reftQueuedBuildings]) == 1 then
        --Ignore for mexes and hydrocarbons
        if not(EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro, sOrigBlueprint)) then
            local iOrigQueueRef = oEngineer[reftQueuedBuildings][1][subrefQueueRef]
            local sTrackerRef = 'AiBotQ'..iOrigQueueRef
            if not(oEngineer[sTrackerRef]) then
                oEngineer[sTrackerRef] = true
                local tOrigBuildLocation = {oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition][1], oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition][2], oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition][3]}
                local bCloseToTarget = false
                local iOrigAction = oEngineer[refiAssignedAction]
                local iWaitCount = 0
                local iOrigTime = GetGameTimeSeconds()

                --[[function HaveSameTargetAndNotStartedBuilding()
                if bDebugMessages == true then
                    if AiBotUnitInfo.IsUnitValid(oEngineer) then
                    --]]
                --LOG('HaveSameTargetAndNotStartedBuilding: time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..': Engineer is valid, refbPrimaryBuilder='..tostring(oEngineer[refbPrimaryBuilder])..'; Assigned action='..(oEngineer[refiAssignedAction] or 'nil')..'; Engineer unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; Qued buildings queue ref='..(oEngineer[reftQueuedBuildings][1][subrefQueueRef] or 'nil')..'; Last order blueprint='..(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Last order position='..repru(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition] or {'nil'}))
                --[[else
                LOG('HaveSameTargetAndNotStartedBuilding: Engineer is no longer valid')
            end
        end--]]
                --if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer[refbPrimaryBuilder] and oEngineer[refiAssignedAction] == iOrigAction and not(oEngineer:IsUnitState('Building')) and not(oEngineer:IsUnitState('Repairing')) and oEngineer[reftQueuedBuildings][1][subrefQueueRef] == iOrigQueueRef and sOrigBlueprint == oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] and oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition], tOrigBuildLocation) <= 1 then
                --[[return true
        else
            return false
        end
    end--]]
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(10)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                if bDebugMessages == true then LOG(sFunctionRef..': time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..': Finished first wait, HaveSameTargetAndNotStartedBuilding='..tostring(HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation))..'; iOrigQueueRef='..repru(iOrigQueueRef or 'nil')..'; tOrigBuildLocation='..repru(tOrigBuildLocation)..'; iOrigAction='..repru(iOrigAction or 'nil')) end

                while HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation) and not(bCloseToTarget) do
                    if bDebugMessages == true then LOG(sFunctionRef..': time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..': bCloseToTarget='..tostring(bCloseToTarget)..'; Dist between engineer pos and orig build location='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tOrigBuildLocation)) end
                    if AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tOrigBuildLocation) <= 12 then bCloseToTarget = true break
                    else
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitSeconds(10)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        iWaitCount = iWaitCount + 1
                        if iWaitCount >= 20 then break end
                    end
                end
                if bCloseToTarget then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(45)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished another wait and are close to target, time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; HaveSameTargetAndNotStartedBuilding()='..tostring(HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation))) end
                    if HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation) then
                        --If there are no mobile units then wait another 30s
                        local bAddToBlacklist = true
                        local iRadius = AiBotUnitInfo.GetBuildingSize(sOrigBlueprint) * 0.5
                        local rNearbyRect = AiBotUtilities.GetRectAroundLocation(tOrigBuildLocation, iRadius)
                        local tUnitsInRect = GetUnitsInRect(rNearbyRect)
                        if AiBotUtilities.IsTableEmpty(tUnitsInRect) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.MOBILE * categories.LAND, tUnitsInRect)) then
                            bAddToBlacklist = false
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitSeconds(30)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                            if HaveSameTargetAndNotStartedBuilding(oEngineer, iOrigAction, iOrigQueueRef, sOrigBlueprint, tOrigBuildLocation) then
                                bAddToBlacklist = true
                            end
                        end
                        if bAddToBlacklist then

                            --Add location to blacklist
                            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tOrigBuildLocation)
                            if bDebugMessages == true then LOG(sFunctionRef..': time='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..': Want to add to blacklist, iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; sOrigBlueprint='..sOrigBlueprint) end
                            if iPlateau and iLandZone then
                                RecordBlacklistLocation(tOrigBuildLocation, 1, 480) --i.e. reset after 8 minutes

                                --Prev approach below:
                                --table.insert(tLZData[AiBotMap.subrefBuildLocationBlacklist], {[AiBotMap.subrefBlacklistLocation] = tOrigBuildLocation, [AiBotMap.subrefBlacklistSize] = iRadius, [AiBotMap.subrefBlacklistType] = AiBotMap.BlacklistTimeout})

                                --Update existing build locations to remove if they are near here
                                CheckIfBuildableLocationsNearPositionStillValid(oEngineer:GetAIBrain(), tOrigBuildLocation, true, AiBotUnitInfo.GetBuildingSize(sOrigBlueprint) * 0.5)

                                --Clear this engineer and any assisting engineers (assisting engineers are cleared via ClearEngineerTracking)
                                AiBotOrders.IssueTrackedClearCommands(oEngineer)
                            end
                        end
                    end
                end
            end
            oEngineer[sTrackerRef] = nil
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetEngineerToReclaimNearbyArea(oEngineer, iPriorityOverride, tLZOrWZTeamData, iPlateauOrPond, iLandOrWaterZone, bWantEnergyNotMass, bOnlyConsiderReclaimInRangeOfEngineer, iMinIndividualValueOverride, bIsWaterZone, bOptionalReturnTrueIfGivenOrder)
    --Gets engineer to find the nearest unassigned reclaim segment in the land zone that has mass/energy, to move to the middle of it, and reclaim it
    --Factors in how much mass is in the segment and how many engineers have been assigned already and adjusts the chosen segment accordingly
    --bOnlyConsiderReclaimInRangeOfEngineer - if this is true then will use oEngineer position instead of the midpoint of the reclaim segment that want to target
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetEngineerToReclaimNearbyArea'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --The dedicated DualGap air/eco opening reserves T2/T3 engineers for
    --power, air tech and production. Reclaim is exclusively a T1 job.
    local oEngineerBrain = AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetAIBrain()
    local bDualGapAirEcoRole = oEngineerBrain and (oEngineerBrain.AiBotDualGapRole == 'top_air'
            or oEngineerBrain.AiBotDualGapRole == 'bottom_air'
            or oEngineerBrain.AiBotDualGapRole == 'eco')
    if bDualGapAirEcoRole and not(EntityCategoryContains(categories.TECH1, oEngineer.UnitId)) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    end



    local bGivenOrder = false
    local iCurPriority = (iPriorityOverride or oEngineer[refiAssignedActionPriority] or 1)
    local tLZOrWZData
    if bIsWaterZone then tLZOrWZData = AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
    else tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
    end

    local iTotalMassAtStartOfCodeInZone = tLZOrWZData[AiBotMap.subrefTotalMassReclaim] --used to give error message if 0 and we couldnt find reclaim
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; iPlateauOrPond='..iPlateauOrPond..'; iLandOrWaterZone='..iLandOrWaterZone..'; bWantEnergyNotMass='..tostring(bWantEnergyNotMass or false)..'; bOnlyConsiderReclaimInRangeOfEngineer='..tostring(bOnlyConsiderReclaimInRangeOfEngineer or false)..'; iMinIndividualValueOverride='..(iMinIndividualValueOverride or 'nil')..'; bIsWaterZone='..tostring(bIsWaterZone or false)..'; Total mass in zone='..tLZOrWZData[AiBotMap.subrefTotalMassReclaim]..'; Total significant mass='..tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; tLZOrWZData[AiBotMap.subrefHighestIndividualReclaim]='..(tLZOrWZData[AiBotMap.subrefHighestIndividualReclaim] or 'nil')..'; iTotalMassAtStartOfCodeInZone='..(iTotalMassAtStartOfCodeInZone or 'nil')) end
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefReclaimSegments]) == false then
        local iClosestSegmentDist = 100000
        local tiClosestSegmentXZ
        local iCurModDist
        local sTotalReclaimValueRef
        local iReclaimValuePerEngi
        local oNearestReclaim
        local iNearestReclaim = 10000
        local iNearestReclaimWithAnyValue = 10000
        local oNearestAnyValueReclaim
        local iEngiPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oEngineer:GetPosition())

        local iMinSignifSegmentValue = 0
        local bDontCheckSignificantValue = true
        local bIncludeIfNoSignificantMass = true
        local bReduceModDistIfSignificantMass = false
        if not(bWantEnergyNotMass) then
            if not(bOnlyConsiderReclaimInRangeOfEngineer) then
                if iMinSignifSegmentValue >= AiBotMap.iSignificantMassThreshold then bIncludeIfNoSignificantMass = false end
                if tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 500 then
                    iMinSignifSegmentValue = AiBotMap.iSignificantMassThreshold --10 (as of v43)
                    bDontCheckSignificantValue = false
                elseif tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] > 0 then
                    bReduceModDistIfSignificantMass = true
                end
            end
        end

        local iMinReclaimIndividualValue = (iMinIndividualValueOverride or AiBotMap.iLowestMassThreshold)


        if bWantEnergyNotMass then
            sTotalReclaimValueRef = AiBotMap.subrefLZTotalEnergyReclaim
            iReclaimValuePerEngi = 300
        else
            sTotalReclaimValueRef = AiBotMap.subrefTotalMassReclaim
            iReclaimValuePerEngi = 200
        end

        local oEngBP = oEngineer:GetBlueprint()
        if not(oEngBP.SizeX) then oEngBP = __blueprints[oEngBP.UnitId] end
        --if oEngBP.Economy.MaxBuildDistance >= 10 then iSegmentSearchSize = math.max(1, math.ceil((oEngBP.Economy.MaxBuildDistance + 2) / math.min(AiBotMap.iReclaimSegmentSizeX, AiBotMap.iReclaimSegmentSizeZ))) end
        --local iMoveSpeed = oEngBP.Physics.MaxSpeed
        local iMaxDistanceToEngineer = oEngBP.Economy.MaxBuildDistance + math.min(oEngBP.SizeX, oEngBP.SizeZ) * 0.5 - 0.1
        local bCheckTerrain = false
        if iMaxDistanceToEngineer < math.min(AiBotMap.iReclaimSegmentSizeX, AiBotMap.iReclaimSegmentSizeZ) then bCheckTerrain = true end
        local sReclaimTableRef
        if bWantEnergyNotMass then sReclaimTableRef = AiBotMap.refSegmentReclaimTotalEnergy
        else sReclaimTableRef = AiBotMap.refReclaimHighestIndividualMassReclaim --AiBotMap.refReclaimTotalMass
        end

        local bDontConsiderPlayableArea = not(AiBotMap.bIsCampaignMap)
        local bDontConsiderNoRush = not(AiBotOverseer.bNoRushActive)
        local tiSegmentsToConsiderByCountAndDist = {}
        local tiSegmentCountToSegmentXZ = {}

        if not(bOnlyConsiderReclaimInRangeOfEngineer) then
            for iSegmentCount, tSegmentXZ in tLZOrWZData[AiBotMap.subrefReclaimSegments] do
                if bDebugMessages == true then LOG(sFunctionRef..': Reclaim in segment X='..tSegmentXZ[1]..'Z'..tSegmentXZ[2]..'='..(AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][sReclaimTableRef] or 'nil')..' using sReclaimTableRef='..sReclaimTableRef..'; iMinReclaimIndividualValue='..iMinReclaimIndividualValue..'; bDontCheckSignificantValue='..tostring(bDontCheckSignificantValue or false)..'; iMinSignifSegmentValue='..(iMinSignifSegmentValue or 'nil')..'; Total signif mass='..(AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass] or 'nil')) end
                if AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][sReclaimTableRef] >= iMinReclaimIndividualValue and (bIncludeIfNoSignificantMass or AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass] > 0) and (bDontCheckSignificantValue or AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass] >= iMinSignifSegmentValue) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering reclaim location at position '..repru(AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2]))..'; plyaable area='..repru(AiBotMap.rMapPlayableArea)..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2])))..'; bDontConsiderPlayableArea='..tostring(bDontConsiderPlayableArea)..'; Mass reclaim in segment='..(AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalMass] or 'nil')..'; Signif mass in segment='..(AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass] or 'nil')) end
                    if bDontConsiderPlayableArea or AiBotConditions.IsLocationInPlayableArea(AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2])) then
                        if bDontConsiderNoRush or AiBotConditions.IsLocationInNoRushArea(AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2])) then
                            iCurModDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), AiBotMap.GetReclaimLocationFromSegment(tSegmentXZ[1], tSegmentXZ[2]))
                            if iCurModDist > iMaxDistanceToEngineer then
                                if tLZOrWZTeamData[AiBotMap.subrefReclaimAreaAssignmentsBySegment][tSegmentXZ[1]] and tLZOrWZTeamData[AiBotMap.subrefReclaimAreaAssignmentsBySegment][tSegmentXZ[1]][tSegmentXZ[2]] and tLZOrWZData[sTotalReclaimValueRef] < (iReclaimValuePerEngi * tLZOrWZTeamData[AiBotMap.subrefReclaimAreaAssignmentsBySegment][tSegmentXZ[1]][tSegmentXZ[2]]) then
                                    iCurModDist = iCurModDist + 60 * tLZOrWZTeamData[AiBotMap.subrefReclaimAreaAssignmentsBySegment][tSegmentXZ[1]][tSegmentXZ[2]] * iReclaimValuePerEngi / math.max(5, tLZOrWZData[sTotalReclaimValueRef]) --Low priority area
                                end
                            end
                            if bReduceModDistIfSignificantMass then
                                if AiBotMap.tReclaimAreas[tSegmentXZ[1]][tSegmentXZ[2]][AiBotMap.refReclaimTotalSignificantMass] > 0 then
                                    iCurModDist = iCurModDist * 0.5
                                else iCurModDist = iCurModDist + 12
                                end --Prioritise locations with significant reclaim over those without
                            end
                            tiSegmentCountToSegmentXZ[iSegmentCount] = {tSegmentXZ[1], tSegmentXZ[2]}
                            tiSegmentsToConsiderByCountAndDist[iSegmentCount] = iCurModDist
                            if iCurModDist < iClosestSegmentDist then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a new closest dist='..iCurModDist..'; SegmentXZ='..repru(tSegmentXZ)) end
                                iClosestSegmentDist = iCurModDist
                                tiClosestSegmentXZ = {tSegmentXZ[1], tSegmentXZ[2]}
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': tiClosestSegmentXZ='..repru(tiClosestSegmentXZ)..'; bOnlyConsiderReclaimInRangeOfEngineer='..tostring(bOnlyConsiderReclaimInRangeOfEngineer or false)) end
        function TryToGetReclaimForSegmentOrAroundEngineer(tiSegmentTargetToUseUnlessConsideringReclaimInRangeOfEngineer, bDontConsiderAnyValueYetOverride, bAbortAsSoonAsFoundPossibleReclaim, bForceUsAnyValueReclaim)
            if tiSegmentTargetToUseUnlessConsideringReclaimInRangeOfEngineer then tiClosestSegmentXZ = tiSegmentTargetToUseUnlessConsideringReclaimInRangeOfEngineer end
            if tiClosestSegmentXZ or bOnlyConsiderReclaimInRangeOfEngineer or (bForceUsAnyValueReclaim and oNearestAnyValueReclaim) then
                local tNearbyReclaim
                local tTargetPos
                local iCurDistToTargetPos
                local bConsiderBelowMinValueIfCantFindAny = true
                local iCurMinToUse = 0

                if bForceUsAnyValueReclaim then
                    tNearbyReclaim = {oNearestAnyValueReclaim}
                    tTargetPos = oEngineer:GetPosition()
                else
                    --Get reclaim in the segment

                    if bOnlyConsiderReclaimInRangeOfEngineer then
                        tTargetPos = oEngineer:GetPosition()
                    else tTargetPos = AiBotMap.GetReclaimLocationFromSegment(tiClosestSegmentXZ[1], tiClosestSegmentXZ[2])
                    end

                    if bDebugMessages == true then
                        if bOnlyConsiderReclaimInRangeOfEngineer then LOG(sFunctionRef..': Only considering reclaim around the engineer position rather than the wider land zone')
                        else
                            LOG(sFunctionRef..': Considering all reclaim in the land zone, Eng build distance='..oEngBP.Economy.MaxBuildDistance..'; SizeX='..oEngBP.SizeX..'; Eng SizeZ='..oEngBP.SizeZ..'; tiClosestSegmentXZ='..repru(tiClosestSegmentXZ)..'; Mass/energy reclaim in this segment (depending on which we are searching for)='..AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][sReclaimTableRef]..'; searching for energy not mass='..tostring(bWantEnergyNotMass))
                        end
                    end

                    --GetReclaimInRectangle(iReturnType, rRectangleToSearch)
                    --    --iReturnType: 1 = true/false; 2 = number of wrecks; 3 = total mass, 4 = valid wrecks
                    local rReclaimRectangle
                    if bOnlyConsiderReclaimInRangeOfEngineer then
                        if bDebugMessages == true then LOG(sFunctionRef..': Only considering reclaim in range of negineer so will consider arond tTargetPos='..repru(tTargetPos)..'; using a radius of '..math.max(AiBotMap.iReclaimSegmentSizeX * 0.5, iMaxDistanceToEngineer, AiBotMap.iReclaimSegmentSizeZ * 0.5)..'; Playable area='..repru(AiBotMap.rMapPlayableArea)) end
                        rReclaimRectangle = AiBotUtilities.GetRectAroundLocation(tTargetPos, math.max(AiBotMap.iReclaimSegmentSizeX * 0.5, iMaxDistanceToEngineer, AiBotMap.iReclaimSegmentSizeZ * 0.5))
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider the reclaim segment using iMaxDistanceToEngineer='..(iMaxDistanceToEngineer or 'nil')..'; Reclaim segment midpoint='..repru(AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][AiBotMap.refReclaimSegmentMidpoint])..'; Playable area='..repru(AiBotMap.rMapPlayableArea)) end
                        rReclaimRectangle = AiBotMap.GetReclaimSegmentRectangle(tiClosestSegmentXZ[1], tiClosestSegmentXZ[2], iMaxDistanceToEngineer)
                    end
                    tNearbyReclaim = AiBotMap.GetReclaimInRectangle(4, rReclaimRectangle)
                    if bDebugMessages == true then
                        local iTargetPosPlateau, iTargetPosLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetPos)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering for iPlateauOrPond='..(iPlateauOrPond or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Engineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; iMaxDistanceToEngineer='..(iMaxDistanceToEngineer or 'nil')..'; oEngBP.Economy.MaxBuildDistance='..(oEngBP.Economy.MaxBuildDistance or 'nil')..'; tiClosestSegmentXZ='..repru(tiClosestSegmentXZ)..'; Is tNearbyReclaim empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyReclaim))..'; Total mass recorded against this reclaim segment='..(AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][AiBotMap.refReclaimTotalMass] or 'nil')..'; tTargetPos='..repru(tTargetPos)..'; Eng pos='..repru(oEngineer:GetPosition())..'; Target Plateau and LZ='..(iTargetPosPlateau or 'nil')..'-'..(iTargetPosLZ or 0)..'; Reclaim segment='..repru(tiClosestSegmentXZ)..'; rReclaimRectangle='..repru(rReclaimRectangle)..'; AiBotMap.iReclaimSegmentSizeX='..(AiBotMap.iReclaimSegmentSizeX or 'nil')..'; iMaxDistanceToEngineer='..(iMaxDistanceToEngineer or 'nil')) end
                        AiBotUtilities.DrawRectangle(rReclaimRectangle, 2, 20)
                    end


                    if bOnlyConsiderReclaimInRangeOfEngineer or EntityCategoryContains(categories.COMMAND, oEngineer.UnitId)  then
                        bConsiderBelowMinValueIfCantFindAny = false
                    else
                        if bDontConsiderAnyValueYetOverride then bConsiderBelowMinValueIfCantFindAny = false end
                        if iMinIndividualValueOverride and not(bWantEnergyNotMass) and (tLZOrWZData[AiBotMap.subrefHighestIndividualReclaim] or 0) < iMinIndividualValueOverride then AiBotUtilities.ErrorHandler('Are trying to send reclaim order with min threshold below the amount in the zone so the engineer will likely end up wasting time on lower value reclaim', true, true) end
                    end

                    if not(bConsiderBelowMinValueIfCantFindAny) then iCurMinToUse = iMinReclaimIndividualValue end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyReclaim empty='..tostring(tNearbyReclaim)..'; bConsiderBelowMinValueIfCantFindAny='..tostring(bConsiderBelowMinValueIfCantFindAny)..'; iCurMinToUse='..iCurMinToUse) end
                end
                if AiBotUtilities.IsTableEmpty(tNearbyReclaim) == false then
                    local iReclaimRadius

                    local iEngiTerrainLabel = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oEngineer:GetPosition())


                    for iReclaim, oReclaim in tNearbyReclaim do
                        --is this valid reclaim within our build area?
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': iReclaim='..iReclaim..'; oReclaim.MaxMassReclaim='..(oReclaim.MaxMassReclaim or 0))
                            if oReclaim.MaxMassReclaim >= 100 or (bWantEnergyNotMass and oReclaim.MaxEnergyReclaim >= 100) then
                                LOG('Large reclaim, repr of all values='..reprs(oReclaim))
                                if oReclaim.GetBlueprint then
                                    LOG('oReclaim has a blueprint='..reprs(oReclaim:GetBlueprint()))
                                else LOG('oReclaim doesnt have .GetBlueprint')
                                end
                            end
                        end

                        if oReclaim.CachePosition and not(oReclaim:BeenDestroyed()) and ((not(bWantEnergyNotMass) and ((bConsiderBelowMinValueIfCantFindAny and not(oNearestReclaim)) or (not(bWantEnergyNotMass) and oReclaim.MaxMassReclaim >= iCurMinToUse) or (bWantEnergyNotMass and oReclaim.MaxEnergyReclaim >= iCurMinToUse))))  then
                            if bDontConsiderNoRush or AiBotConditions.IsLocationInNoRushArea(oReclaim.CachePosition) then
                                iReclaimRadius = math.min((oReclaim:GetBlueprint().SizeX or 0.5), (oReclaim:GetBlueprint().SizeZ or 0.5))*0.5
                                iCurDistToTargetPos = math.max(0, AiBotUtilities.GetDistanceBetweenPositions(tTargetPos, oReclaim.CachePosition) - iReclaimRadius)
                                --Can we path to it?
                                if iCurDistToTargetPos < iNearestReclaim and (oReclaim.MaxMassReclaim > 150 or AiBotUtilities.IsTableEmpty(oReclaim[reftUnitsReclaimingUs]) or oReclaim[reftUnitsReclaimingUs][1] == oEngineer) and (not(bCheckTerrain) or (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oReclaim.CachePosition) == iEngiTerrainLabel or (iCurDistToTargetPos <= 12 and AiBotUtilities.GetDistanceBetweenPositions(oReclaim.CachePosition, oEngineer:GetPosition()) <= iReclaimRadius + iMaxDistanceToEngineer))) then
                                    iNearestReclaim = iCurDistToTargetPos
                                    oNearestReclaim = oReclaim
                                    if bConsiderBelowMinValueIfCantFindAny then
                                        if bWantEnergyNotMass then
                                            iCurMinToUse = math.min(iMinReclaimIndividualValue, oReclaim.MaxEnergyReclaim)
                                        else
                                            iCurMinToUse = math.min(iMinReclaimIndividualValue, oReclaim.MaxMassReclaim)
                                        end
                                    end
                                end
                                --Backup e.g. if looking for energy reclaim but only have mass available
                                if not(oNearestReclaim) then
                                    if iCurDistToTargetPos < iNearestReclaimWithAnyValue and (oReclaim.MaxMassReclaim or 0) + (oReclaim.MaxEnergyReclaim or 0) > 0 then
                                        if (not(oNearestAnyValueReclaim) or (oNearestAnyValueReclaim[AiBotMap.refbUnreachableReclaim] and not(oReclaim[AiBotMap.refbUnreachableReclaim]))) or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oReclaim.CachePosition) == iEngiPlateau or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oReclaim.CachePosition) == iPlateauOrPond then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Recording reclaim as a backup for now so we have at least something to reclaim') end
                                            oNearestAnyValueReclaim = oReclaim
                                            iNearestReclaimWithAnyValue = iCurDistToTargetPos
                                            if bAbortAsSoonAsFoundPossibleReclaim and not(oNearestAnyValueReclaim[AiBotMap.refbUnreachableReclaim]) then break end
                                            if bConsiderBelowMinValueIfCantFindAny then
                                                if bWantEnergyNotMass then
                                                    iCurMinToUse = math.min(iMinReclaimIndividualValue, oReclaim.MaxEnergyReclaim)
                                                else
                                                    iCurMinToUse = math.min(iMinReclaimIndividualValue, oReclaim.MaxMassReclaim)
                                                end
                                            end
                                            break
                                        end
                                    end
                                elseif bDebugMessages == true then
                                    LOG(sFunctionRef..': Have got oNearestReclaim, reprs='..reprs(oNearestReclaim))
                                end
                            end
                        end
                        if AiBotUtilities.bCPUPerformanceMode and oNearestReclaim then break end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished cycling through reclaim, is oNearestReclaim nil='..tostring(oNearestReclaim == nil)..'; bCheckTerrain='..tostring(bCheckTerrain or false)) end
                    if not(oNearestReclaim) and ((bConsiderBelowMinValueIfCantFindAny and not(bDontConsiderAnyValueYetOverride)) or (bOnlyConsiderReclaimInRangeOfEngineer and oNearestAnyValueReclaim and not(bWantEnergyNotMass) and oNearestAnyValueReclaim.MaxMassReclaim >= iMinReclaimIndividualValue))  then
                        oNearestReclaim = oNearestAnyValueReclaim
                        --Check this is in the same zone
                        if oNearestReclaim and bCheckTerrain then
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if nearest any value reclaim is in the same plateau, Hover label of cacheposition='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oNearestReclaim.CachePosition) or 'ni')..'; iEngiPlateau='..(iEngiPlateau or 'nil')..'; iPlateauOrPond='..(iPlateauOrPond or 'nil')) end
                            if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oNearestReclaim.CachePosition) == iEngiPlateau or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oNearestReclaim.CachePosition) == iPlateauOrPond) then
                                local iDistToReclaim = AiBotUtilities.GetDistanceBetweenPositions(oNearestReclaim.CachePosition, oEngineer:GetPosition())
                                local iRangeToWreck = iMaxDistanceToEngineer + math.min((oNearestReclaim:GetBlueprint().SizeX or 0.5), (oNearestReclaim:GetBlueprint().SizeZ or 0.5))*0.5
                                if bDebugMessages == true then LOG(sFunctionRef..': iDistToReclaim='..iDistToReclaim..'; iRangeToWreck='..iRangeToWreck) end
                                if iDistToReclaim > iRangeToWreck then
                                    local iBaseAngle = AiBotUtilities.GetAngleFromAToB(oNearestReclaim.CachePosition, oEngineer:GetPosition())
                                    local bNoValidPotentialLocation = true
                                    for iAngleAdjust = 0, 315, 45 do
                                        local tPotentialLocationToMove = AiBotUtilities.MoveInDirection(oNearestReclaim.CachePosition, iBaseAngle + iAngleAdjust, iRangeToWreck, true, false, AiBotMap.bIsCampaignMap)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Ignoring reclaim as we cant path to it, unless the engineer can path somewhere that is within build range of here, tPotentialLocationToMove='..repru(tPotentialLocationToMove)..'; Hover label of this='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialLocationToMove) or 'nil')..'; iPlateauOrPond='..iPlateauOrPond..'; iDistToReclaim='..iDistToReclaim..'; iMaxDistanceToEngineer='..iMaxDistanceToEngineer..'; Angle from engi to reclaim='..AiBotUtilities.GetAngleFromAToB(oEngineer:GetPosition(), oNearestReclaim.CachePosition)) end
                                        if AiBotUtilities.IsTableEmpty(tPotentialLocationToMove) == false and (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialLocationToMove) == iEngiPlateau or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialLocationToMove) == iPlateauOrPond) then
                                            bNoValidPotentialLocation = false
                                            break
                                        end
                                    end
                                    if bNoValidPotentialLocation then
                                        --Could we path to the midpoint of the reclaim segmetn from engi plateau, and (if so) can we then reach the reclaim position from this midpoint?
                                        local bCantPathToSegmentMidpoint = true
                                        if tiClosestSegmentXZ then
                                            local tClosestSegmentMidpoint = AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][AiBotMap.refReclaimSegmentMidpoint]
                                            if tClosestSegmentMidpoint then
                                                local iClosestSegmentPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tClosestSegmentMidpoint)
                                                if bDebugMessages == true then LOG(sFunctionRef..': iClosestSegmentPlateau='..(iClosestSegmentPlateau or 'nil')..'; Dist from reclaim to segment midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tClosestSegmentMidpoint, oNearestReclaim.CachePosition)..'; iRangeToWreck='..iRangeToWreck) end
                                                if iClosestSegmentPlateau and iClosestSegmentPlateau == iEngiPlateau and AiBotUtilities.GetDistanceBetweenPositions(tClosestSegmentMidpoint, oNearestReclaim.CachePosition) <= iRangeToWreck then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': We can path here after all, probably, so will retain') end
                                                    bCantPathToSegmentMidpoint = false
                                                end
                                            end
                                        end
                                        if bCantPathToSegmentMidpoint then
                                            --Mark against the reclaim it is of no value
                                            oNearestAnyValueReclaim[AiBotMap.refbUnreachableReclaim] = true
                                            --Want to consider reassigning this reclaim segment if the only reclaim in it is in a different plateau
                                            oNearestReclaim = nil
                                            if tiClosestSegmentXZ then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Reclaim segments for this zone before reassignment='..reprs(tLZOrWZData[AiBotMap.subrefReclaimSegments])..'; Size of this='..table.getn(tLZOrWZData[AiBotMap.subrefReclaimSegments])..'; tiClosestSegmentXZ[1]='..(tiClosestSegmentXZ[1] or 'nil')..'; tiClosestSegmentXZ[2]='..(tiClosestSegmentXZ[2] or 'nil')) end
                                                AiBotMap.ReassignReclaimSegment(tiClosestSegmentXZ[1], tiClosestSegmentXZ[2], tLZOrWZData)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Reclaim segments for this zone after reassignment='..reprs(tLZOrWZData[AiBotMap.subrefReclaimSegments])..'; Size of this='..table.getn(tLZOrWZData[AiBotMap.subrefReclaimSegments])) end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if oNearestReclaim then
                        if oEngineer:IsUnitState('Capturing') then AiBotUtilities.ErrorHandler('Are aborting an engineer that was capturing and telling it to reclaim instead', true, true) end
                        bGivenOrder = true
                        if oEngineer[AiBotUnitInfo.refbEasyBrain] then
                            AiBotOrders.IssueTrackedAggressiveMove(oEngineer, oNearestReclaim:GetPosition(), 3, false, 'ReclLZeSeg', false)
                        else
                            AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaim, false, 'ReclLZSeg')
                            if bWantEnergyNotMass then
                                oEngineer[refiLastReclaimTargetValue] = oNearestReclaim.MaxEnergyReclaim
                            else
                                oEngineer[refiLastReclaimTargetValue] = oNearestReclaim.MaxMassReclaim
                            end
                        end
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Will send order to get reclaim at position '..repru(oNearestReclaim.CachePosition)..'; will draw a box around here; oNearestReclaim ID='..(oNearestReclaim.UnitId or 'nil')..'; mass value='..(oNearestReclaim.MaxMassReclaim or 'nil')..'; Dist to engi='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oNearestReclaim.CachePosition)..'; Engi cur position='..repru(oEngineer:GetPosition()))
                            if AiBotUtilities.IsTableEmpty(oNearestReclaim.CachePosition) == false then AiBotUtilities.DrawLocation(oNearestReclaim.CachePosition) end
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have any reclaim of sufficient value; iMinReclaimIndividualValue='..iMinReclaimIndividualValue) end
                    end

                else
                    if bDebugMessages == true then LOG(sFunctionRef..' No reclaim in nearby segments, will update the reclaim in this segment if engi isnt range restricted') end
                    if not(bOnlyConsiderReclaimInRangeOfEngineer) and tiClosestSegmentXZ then
                        if bDebugMessages == true then LOG(sFunctionRef..': Total mass pre update='..AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][AiBotMap.refReclaimTotalMass]) end
                        AiBotMap.UpdateReclaimDataNearSegments(tiClosestSegmentXZ[1], tiClosestSegmentXZ[2], 0)
                        if bDebugMessages == true then LOG(sFunctionRef..': Total mass post update='..AiBotMap.tReclaimAreas[tiClosestSegmentXZ[1]][tiClosestSegmentXZ[2]][AiBotMap.refReclaimTotalMass]) end
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': No segments in land zone with sufficient reclaim') end
            end
        end

        if bOnlyConsiderReclaimInRangeOfEngineer then
            TryToGetReclaimForSegmentOrAroundEngineer()
        else
            for iSegmentCount, iModDist in AiBotUtilities.SortTableByValue(tiSegmentsToConsiderByCountAndDist, false) do
                if bDebugMessages == true then LOG(sFunctionRef..': Cycling through segments by dist to engineer, iSegmentCount='..iSegmentCount..'; X='..tiSegmentCountToSegmentXZ[iSegmentCount][1]..'Z='..tiSegmentCountToSegmentXZ[iSegmentCount][2]..'; iModDist='..iModDist) end
                TryToGetReclaimForSegmentOrAroundEngineer(tiSegmentCountToSegmentXZ[iSegmentCount], true)
                if bGivenOrder then break end
            end
            if not(bGivenOrder) then
                --Ignore value restriction
                if oNearestAnyValueReclaim then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will just get the nearest any value reclaim to reclaim') end
                    TryToGetReclaimForSegmentOrAroundEngineer(nil, false, true, true)
                end
                if not(bGivenOrder) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will now try cycling through ignoring low value restriction and stop the moment we find a pathable wreck') end
                    for iSegmentCount, iModDist in AiBotUtilities.SortTableByValue(tiSegmentsToConsiderByCountAndDist, false) do
                        TryToGetReclaimForSegmentOrAroundEngineer(tiSegmentCountToSegmentXZ[iSegmentCount], false, true)
                        if bGivenOrder then break end
                    end
                end
            end
        end

        if bGivenOrder and not(EntityCategoryContains(categories.COMMAND, oEngineer.UnitId)) then
            TrackEngineerAction(oEngineer, refActionReclaimArea, false, iCurPriority, nil, tiClosestSegmentXZ)
        elseif not(bGivenOrder) and not(bOnlyConsiderReclaimInRangeOfEngineer) then
            --Flag that this zone has failed to find anything for engineers to reclaim, so we limit BP to assign to 5
            tLZOrWZData[AiBotMap.subrefiTimeFailedToGetReclaim] = GetGameTimeSeconds()

            if bDebugMessages == true then LOG(sFunctionRef..': Recording that we failed to get reclaim in this zone, is oNearestReclaim nil='..tostring(oNearestReclaim == nil)..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
            --If there is a valid reclaim nearby (it just is too low value) then also give order to reclaim this
            if oNearestReclaim and not(oEngineer:IsUnitState('Capturing')) then
                if oEngineer[AiBotUnitInfo.refbEasyBrain] then
                    AiBotOrders.IssueTrackedAggressiveMove(oEngineer, oNearestReclaim:GetPosition(), 3, false, 'ReclBLZeSeg', false)
                else
                    AiBotOrders.IssueTrackedReclaim(oEngineer, oNearestReclaim, false, 'ReclBLZSeg')
                end
                bGivenOrder = true
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Time since last zone refresh='..GetGameTimeSeconds() - (tLZOrWZData[AiBotMap.subrefLastReclaimRefresh] or 0)..'; LZ total recalim='..(tLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 0)..'; tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]='..(tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end
                if not(bWantEnergyNotMass) and not(bOnlyConsiderReclaimInRangeOfEngineer) then
                    if iTotalMassAtStartOfCodeInZone == 0 then AiBotUtilities.ErrorHandler('We tried getting an engi to reclaim mass in a zone when there is no mass, P'..iPlateauOrPond..'Z'..iLandOrWaterZone..';WZ='..tostring(bIsWaterZone or false), true)
                    else
                        if GetGameTimeSeconds() - (tLZOrWZData[AiBotMap.subrefLastComprehensiveReclaimRefresh] or 0) >= 3 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will refresh reclaim data in this zone P'..iPlateauOrPond..'Z'..iLandOrWaterZone..', including any underlying segments, mass before refresh='..tLZOrWZData[AiBotMap.subrefTotalMassReclaim]) end
                            AiBotMap.RefreshLandOrWaterZoneReclaimValue(iPlateauOrPond, iLandOrWaterZone, bIsWaterZone, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Total mass after refresh of reclaim='..tLZOrWZData[AiBotMap.subrefTotalMassReclaim]) end
                        elseif GetGameTimeSeconds() - (tLZOrWZData[AiBotMap.subrefLastComprehensiveReclaimRefresh] or 0) < 1 then
                            if (tLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 0) < iTotalMassAtStartOfCodeInZone then --or (iTotalSignificantMassAtStartOfCodeInZone > (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) and iMinReclaimIndividualValue > (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Couldnt find anything to reclaim but we have refreshed the zone in the last second, mass value post refresh is below 1, tLZOrWZData[AiBotMap.subrefTotalMassReclaim]='..(tLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 'nil')..'; iTotalMassAtStartOfCodeInZone='..iTotalMassAtStartOfCodeInZone) end
                            elseif iMinIndividualValueOverride and iMinIndividualValueOverride > AiBotMap.iLowestMassThreshold and EntityCategoryContains(categories.COMMAND, oEngineer.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': ACU was trying to get high value reclaim if there was any, since there isnt ACU should just proceed to other orders') end
                            else
                                AiBotUtilities.ErrorHandler('Couldnt find anything to reclaim but we have refreshed the zone in the last second, mass value post refresh was less than pre refresh, see log for more info', true)
                                LOG(sFunctionRef..': Post warning message: iPlateauOrPond='..iPlateauOrPond..'; iLandOrWaterZone='..iLandOrWaterZone..'; iMinIndividualValueOverride='..(iMinIndividualValueOverride or 'nil')..'; subrefHighestIndividualReclaim='..(tLZOrWZData[AiBotMap.subrefHighestIndividualReclaim] or 'nil'))
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bGivenOrder and bOptionalReturnTrueIfGivenOrder then return true end
end

function FilterEngineersOfTechAndEngiCountForFaction(iOptionalFactionRequired, tEngineersOfTechWanted, bOkWithNoEngisIfDontHaveFactionRequired)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'FilterEngineersOfTechAndEngiCountForFaction'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tEngineersOfFactionAndTechWanted
    tEngineersOfFactionAndTechWanted = {}
    local iRevisedEngiCount = 0
    for iTechEngi, oTechEngi in tEngineersOfTechWanted do
        if AiBotUnitInfo.GetUnitFaction(oTechEngi) == iOptionalFactionRequired then
            table.insert(tEngineersOfFactionAndTechWanted, oTechEngi)
            iRevisedEngiCount = iRevisedEngiCount + 1
            if bDebugMessages == true then LOG(sFunctionRef..': oTechEngi='..oTechEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTechEngi)..' is the right faction so including in revised list, iRevisedEngiCount='..iRevisedEngiCount) end
        end
    end
    if iRevisedEngiCount == 0 and not(bOkWithNoEngisIfDontHaveFactionRequired) then AiBotUtilities.ErrorHandler('After filtering to a faction we have no available engineers - this shouldnt be possible') end
    --Now replace original table os we dont have to update below references (do by returning these values now since have moved this logic to a function)
    if bDebugMessages == true then LOG(sFunctionRef..': Finished updating list, iRevisedEngiCount='..iRevisedEngiCount..'; Last engi in list='..(tEngineersOfTechWanted[iEngiCount].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount]) or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tEngineersOfFactionAndTechWanted, iRevisedEngiCount

end

function ActiveShieldMonitor(oUnitToProtect, tLZTeamData, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ActiveShieldMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if not(oUnitToProtect[refbActiveUnitShieldingThread]) then
        oUnitToProtect[refbActiveUnitShieldingThread] = true
        local iShieldCategoryToBuild
        local iOptionalFactionRequired
        local iEngineerFactionRequired = AiBotUnitInfo.refCategoryEngineer
        local iTimeOfLastBlockingBuildingCheck
        local iPreviousAction
        local refiShieldActionConstruct = 1
        local refiShieldActionAssist = 2

        if oUnitToProtect[AiBotBuilding.refoNearbyFactoryOfFaction] then
            iOptionalFactionRequired = AiBotUnitInfo.GetUnitFaction(oUnitToProtect[AiBotBuilding.refoNearbyFactoryOfFaction])
        end
        if not(iOptionalFactionRequired) then iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield
        else
            if iOptionalFactionRequired == AiBotUnitInfo.refFactionSeraphim then
                --Does enemy have mavor? if so then want T3 shields not T2
                local bEnemyHasMavorOrCloseToUnitCap = false
                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 0 then
                    bEnemyHasMavorOrCloseToUnitCap = true
                elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                    for iArti, oArti in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalArti * categories.UEF, oArti.UnitId) then
                            bEnemyHasMavorOrCloseToUnitCap = true
                        end
                    end
                end
                if bEnemyHasMavorOrCloseToUnitCap then
                    iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.SERAPHIM
                else
                    --If go for T2 shielding then will be quicker to build and cheaper, and still cover the unit provided the shield can absorb a single shot
                    iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.TECH2 * categories.SERAPHIM
                end
                iEngineerFactionRequired = iEngineerFactionRequired * categories.SERAPHIM  - categories.EXPERIMENTAL
            elseif iOptionalFactionRequired == AiBotUnitInfo.refFactionAeon then
                iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.AEON - categories.EXPERIMENTAL
                iEngineerFactionRequired = iEngineerFactionRequired * categories.AEON
            elseif iOptionalFactionRequired == AiBotUnitInfo.refFactionUEF then
                iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.UEF  - categories.EXPERIMENTAL
                iEngineerFactionRequired = iEngineerFactionRequired * categories.UEF
            else
                iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield
            end
        end
        local sLikelyShieldBlueprint = AiBotFactory.GetMostExpensiveBlueprintOfCategory(iShieldCategoryToBuild)
        local iBlueprintBuildTime = (__blueprints[sLikelyShieldBlueprint].Economy.BuildTime or 1250)

        local aiBrain = oUnitToProtect:GetAIBrain()
        local iTotalAvailableLocations = 0
        for iEntry, tLocation in oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield] do
            iTotalAvailableLocations = iTotalAvailableLocations + 1
            if bDebugMessages == true then
                LOG(sFunctionRef..': Will draw tLocation in reftLocationsForPriorityShield')
                AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tLocation, AiBotUnitInfo.GetBuildingSize(sLikelyShieldBlueprint) * 0.5), 4, 200)
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop to protect the unit if it is still valid, is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnitToProtect))..'; Unit to protect='..(oUnitToProtect.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToProtect) or 'nil')) end
        while AiBotUnitInfo.IsUnitValid(oUnitToProtect) and not(oUnitToProtect[AiBotBuilding.reftArtiTemplateRefs]) do
            if bDebugMessages == true then LOG(sFunctionRef..': Loop start at time '..GetGameTimeSeconds()..'; Is table of engineers actively shielding empty='..tostring(AiBotUtilities.IsTableEmpty(oUnitToProtect[reftEngineersActivelyShielding]))..'; oUnitToProtect='..oUnitToProtect.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToProtect)..'; Assigned plateau and LZ='..repru(oUnitToProtect[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam])..'; reftArtiTemplateRefs='..repru(oUnitToProtect[AiBotBuilding.reftArtiTemplateRefs])) end
            if AiBotUtilities.IsTableEmpty(oUnitToProtect[reftEngineersActivelyShielding]) == false then
                --Decide what to do with the engineers - first see how many shields we have, and if any are compelted:
                local iConstructedShields = 0
                local iActiveShields = 0
                local iPartConstructedShields = 0
                local oNearestCompletionShield
                local iHighestPartCompleteShield = -0.01 --So a 0% complete building gets included
                local iLowestPartCompleteShield = 1.01
                local oLowestCompletionShield
                local oLastCompletedShield
                local iCurShield, iMaxShield
                local oLowestConstructedShieldHealth
                local oHighestConstructedShieldHealth
                local iLowestConstructedShieldHealth = 100000
                local iHighestConstructedShieldHealthPercent = 0
                if bDebugMessages == true then LOG(sFunctionRef..': oUnitToProtect='..oUnitToProtect.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToProtect)..'; Is table of special assigned shields empty='..tostring(AiBotUtilities.IsTableEmpty(oUnitToProtect[AiBotBuilding.reftoSpecialAssignedShields]))) end
                if AiBotUtilities.IsTableEmpty(oUnitToProtect[AiBotBuilding.reftoSpecialAssignedShields]) == false then
                    local tiEntriesToRemove = {}
                    for iShield, oShield in oUnitToProtect[AiBotBuilding.reftoSpecialAssignedShields] do
                        if AiBotUnitInfo.IsUnitValid(oShield) then
                            if not(oShield[refbDontIncludeAsPartCompleteBuildingForConstruction]) or GetGameTimeSeconds() - (oShield[refiLastClearedForReclaim] or 0) >= 10 then
                                oShield[refbDontIncludeAsPartCompleteBuildingForConstruction] = true
                                oShield[refiLastClearedForReclaim] = GetGameTimeSeconds()

                                --Clear any assisting or building engineers who dont have the special shield action (to avoid a unit that is constructing a shield using this)
                                local tGuardingEngineers = oShield:GetGuards()
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of guarding engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tGuardingEngineers))) end
                                if AiBotUtilities.IsTableEmpty(tGuardingEngineers) == false then
                                    for iGuard, oGuard in tGuardingEngineers do
                                        if not(oGuard[refiAssignedAction] == refActionSpecialShieldDefence) and not(oGuard[refiAssignedAction] == refActionManageGameEnderTemplate) then
                                            AiBotOrders.IssueTrackedClearCommands(oGuard)
                                        end
                                    end
                                end
                                --Also check every engineer in this zone
                                local tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
                                    for iPotentialEngineer, oPotentialEngineer in tEngineersInZone do
                                        if AiBotUnitInfo.IsUnitValid(oPotentialEngineer) then
                                            if oPotentialEngineer[refiAssignedAction] == refActionBuildShield or oPotentialEngineer[refiAssignedAction] == refActionBuildSecondShield or oPotentialEngineer[refiAssignedAction] == refActionAssistShield then
                                                if bDebugMessages == true then LOG(sFunctionRef..': have engineer with action '..oPotentialEngineer[refiAssignedAction]..'; Engineer='..oPotentialEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPotentialEngineer)..'; Focus unit='..(oPotentialEngineer:GetFocusUnit().UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPotentialEngineer:GetFocusUnit()) or 'nil')) end
                                                if oPotentialEngineer:GetFocusUnit()[refbDontIncludeAsPartCompleteBuildingForConstruction] or oPotentialEngineer:GetFocusUnit()[refiAssignedAction] == refActionSpecialShieldDefence then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will clear engineer orders') end
                                                    AiBotOrders.IssueTrackedClearCommands(oPotentialEngineer)
                                                end
                                            end
                                        end
                                    end
                                end
                                --Check shield isnt on a priority list to assist
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false then
                                    for iCurShieldEntry = table.getn(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]), 1, -1 do
                                        if tLZTeamData[AiBotMap.reftPriorityShieldsToAssist][iCurShieldEntry][refbDontIncludeAsPartCompleteBuildingForConstruction] then
                                            table.remove(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist], iCurShieldEntry)
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering assigned shield oShield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Fraction complete='..oShield:GetFractionComplete()) end
                            if oShield:GetFractionComplete() == 1 then
                                iConstructedShields = iConstructedShields + 1
                                oLastCompletedShield = oShield
                                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': COnsidering shield health of constructed shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iCurShield='..iCurShield..'; iMaxShield='..iMaxShield..'; iLowestConstructedShieldHealth='..iLowestConstructedShieldHealth..'; oUnit.MyShield:GetHealth()='..(oShield.MyShield:GetHealth() or 'nil')..'; Shield ratio='..(oShield:GetShieldRatio(false) or 0)..'; IsUp='..tostring(oShield.MyShield:IsUp())..'; IsOn='..tostring(oShield.MyShield:IsOn())..'; Depleted by damage='..tostring(oShield.DepletedByDamage or false)) end
                                if iCurShield > 0 then iActiveShields = iActiveShields + 1 end
                                if iCurShield < iLowestConstructedShieldHealth then
                                    oLowestConstructedShieldHealth = oShield
                                    iLowestConstructedShieldHealth = iCurShield
                                end
                                if (iCurShield / iMaxShield) > iHighestConstructedShieldHealthPercent then
                                    iHighestConstructedShieldHealthPercent = (iCurShield / iMaxShield)
                                    oHighestConstructedShieldHealth = oShield
                                end
                            else
                                iPartConstructedShields = iPartConstructedShields + 1
                                if oShield:GetFractionComplete() > iHighestPartCompleteShield then
                                    iHighestPartCompleteShield = oShield:GetFractionComplete()
                                    oNearestCompletionShield = oShield
                                end
                                if oShield:GetFractionComplete() < iLowestPartCompleteShield then
                                    iLowestPartCompleteShield = oShield:GetFractionComplete()
                                    oLowestCompletionShield = oShield
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a part constructed shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' with fraction compelte '..oShield:GetFractionComplete()..'; oNearestCompletionShield='..(oNearestCompletionShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield) or 'nil')) end
                            end
                        else
                            tiEntriesToRemove[iShield] = true
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tiEntriesToRemove) == false then
                        for iEntry, bRemove in tiEntriesToRemove do
                            oUnitToProtect[AiBotBuilding.reftoSpecialAssignedShields][iEntry] = nil
                        end
                    end
                end

                function ConstructNewShield()
                    local bProceededWithConstruction = false
                    --Need to construct a new shield (need to be wanting to do this for at least a tick due to delay in constructionstarting triggering due to forked thread)
                    local tPositionToBuild
                    local tAltPositionToBuild
                    local iActionGiven
                    if bDebugMessages == true then LOG(sFunctionRef..': ConstructNewShield: repru of locations for priority shield='..repru(oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield])..'; sLikelyShieldBlueprint='..(sLikelyShieldBlueprint or 'nil')..'; iPreviousAction='..(iPreviousAction or 'nil')..'; oLowestConstructedShieldHealth='..(oLowestConstructedShieldHealth.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oLowestConstructedShieldHealth) or 'nil')..'; ') end

                    for iEntry, tLocation in oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield] do
                        --basic check whether we can build (we should already be able to)
                        if bDebugMessages == true then LOG(sFunctionRef..': Can we build sLikelyShieldBlueprint '..sLikelyShieldBlueprint..' at tLocation '..repru(tLocation)..'='..tostring(aiBrain:CanBuildStructureAt(sLikelyShieldBlueprint, tLocation))) end
                        if aiBrain:CanBuildStructureAt(sLikelyShieldBlueprint, tLocation) then
                            if tPositionToBuild then
                                tAltPositionToBuild = tLocation
                                break
                            else
                                tPositionToBuild = tLocation
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': tPositionToBuild='..repru(tPositionToBuild)) end
                    if tPositionToBuild then
                        local toEngineersOfWrongFaction = {}
                        local oFirstEngineerOfRightFaction
                        local iEngineerBuildOrderCount = 0
                        for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Does this contain the required faction='..tostring(EntityCategoryContains(iEngineerFactionRequired, oEngineer.UnitId))) end
                            if EntityCategoryContains(iEngineerFactionRequired, oEngineer.UnitId) then
                                iEngineerBuildOrderCount = iEngineerBuildOrderCount + 1
                                --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                                local sBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineer, false,  false,          false,          nil,                                false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Checking what shields engineer '..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..' can build; iOptionalFactionRequired='..(iOptionalFactionRequired or 'nil')..'; Will try and build unit '..sBlueprintToBuild..' at position '..repru(tPositionToBuild)) end
                                --Have the 4th engineer try to build in the alt location, so if the main location is blocked we may still get construction started
                                if iEngineerBuildOrderCount == 4 and tAltPositionToBuild then
                                    AiBotOrders.IssueTrackedBuild(oEngineer, tAltPositionToBuild, sBlueprintToBuild, false, 'SpAEBS')
                                else
                                    AiBotOrders.IssueTrackedBuild(oEngineer, tPositionToBuild, sBlueprintToBuild, false, 'SpEBS')
                                end
                                iActionGiven = refiShieldActionConstruct
                                bProceededWithConstruction = true

                                if not(oFirstEngineerOfRightFaction) then oFirstEngineerOfRightFaction = oEngineer end
                            else
                                table.insert(toEngineersOfWrongFaction, oEngineer)
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished telling engineers of right faction to build, Is table of engineers of wrong faction empty='..tostring(AiBotUtilities.IsTableEmpty(toEngineersOfWrongFaction))..'; bProceededWithConstruction='..tostring(bProceededWithConstruction)..'; Is oFirstEngineerOfRightFaction nil='..tostring(oFirstEngineerOfRightFaction == nil)) end
                        if AiBotUtilities.IsTableEmpty(toEngineersOfWrongFaction) == false then
                            if not(oFirstEngineerOfRightFaction) then
                                local bBuildAnyShield = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Do we want to build a shield with wrong faction? Engineers of wrong faction='..table.getn(toEngineersOfWrongFaction)..'; iActiveShields='..iActiveShields..'; oUnitToProtect:GetFractionComplete()='..oUnitToProtect:GetFractionComplete()..'; iHighestConstructedShieldHealthPercent='..iHighestConstructedShieldHealthPercent..'; iConstructedShields='..iConstructedShields) end
                                if (table.getn(toEngineersOfWrongFaction) >= 5 or (iActiveShields == 0 and oUnitToProtect:GetFractionComplete() >= 0.2) or (iHighestConstructedShieldHealthPercent <= 0.5 and iConstructedShields >= 2)) then
                                    if iConstructedShields + iPartConstructedShields <= 1 then bBuildAnyShield = true
                                    elseif iConstructedShields >= 2 and iHighestConstructedShieldHealthPercent <= 0.8 then
                                        bBuildAnyShield = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bBuildAnyShield='..tostring(bBuildAnyShield)) end
                                    if bBuildAnyShield then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have so many engineers of the wrong faction that will just try and get them to build a shield') end
                                        for iEngineer, oEngineer in toEngineersOfWrongFaction do
                                            --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,                                   oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                                            local sBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryFixedShield * categories.TECH3, oEngineer, false,       false,          false,      nil,                                 false)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking what shields engineer '..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..' can build as backup as dont have right faction; iOptionalFactionRequired='..(iOptionalFactionRequired or 'nil')..'; Will try and build unit '..(sBlueprintToBuild or 'nil')..' at position '..repru(tPositionToBuild)) end
                                            if sBlueprintToBuild then
                                                AiBotOrders.IssueTrackedBuild(oEngineer, tPositionToBuild, sBlueprintToBuild, false, 'SBkEBS')
                                                iActionGiven = refiShieldActionConstruct
                                            end
                                        end
                                        bProceededWithConstruction = true
                                    end
                                end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Will get engineers to assist the one doing the construction') end
                                for iEngineer, oEngineer in toEngineersOfWrongFaction do
                                    --if not(oEngineer == oFirstEngineerOfRightFaction) then
                                    AiBotOrders.IssueTrackedGuard(oEngineer, oFirstEngineerOfRightFaction, false, 'SpEGE', false)
                                    --end
                                    iActionGiven = refiShieldActionConstruct
                                end
                            end
                        end
                    else
                        AiBotUtilities.ErrorHandler('We are unable to build at a predefined shield location, will check for small blocking AiBot buildings and destroy them', true)
                        --Only search for units that are actually built on the shield location - so e.g. this wont cover if a factory is built where part of the factory covers the shield location
                        local iSearchRadius = AiBotUnitInfo.GetBuildingSize(sLikelyShieldBlueprint) * 0.5 - 0.49 --even at -0.75 will get units that arent in the build area being included
                        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield]='..repru(oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield])..'; iSearchRadius='..iSearchRadius..'; iTimeOfLastBlockingBuildingCheck='..(iTimeOfLastBlockingBuildingCheck or 'nil')) end
                        if GetGameTimeSeconds() - (iTimeOfLastBlockingBuildingCheck or -100) >= 5 then
                            iTimeOfLastBlockingBuildingCheck = GetGameTimeSeconds()
                            for iEntry, tLocation in oUnitToProtect[AiBotBuilding.reftLocationsForPriorityShield] do
                                local rShieldAreaRect = AiBotUtilities.GetRectAroundLocation(tLocation, iSearchRadius)
                                local tUnitsNearby = GetUnitsInRect(rShieldAreaRect)
                                if AiBotUtilities.IsTableEmpty(tUnitsNearby) == false then
                                    local tBuildingsNearby = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryFixedShield - AiBotUnitInfo.refCategoryMex - AiBotUnitInfo.refCategoryHydro, tUnitsNearby)
                                    if AiBotUtilities.IsTableEmpty(tBuildingsNearby) == false then
                                        --Do we have a shield near her?
                                        local bNearbyShield = false
                                        local tShieldsNearby = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tUnitsNearby)
                                        if AiBotUtilities.IsTableEmpty(tShieldsNearby) == false then
                                            --Redundancy - check if have any shields near here and both dont do the kill logic if we do, and also assign such shields to the game ender
                                            for iShield, oShield in tShieldsNearby do
                                                if oShield:GetAIBrain().AiBotAI and oShield:GetAIBrain().AiBotTeam == iTeam then
                                                    if AiBotUtilities.GetRoughDistanceBetweenPositions(oShield:GetPosition(), tLocation) <= 4 then
                                                        bNearbyShield = true
                                                        if oShield['OnConstructionStarted'] then
                                                            --We for some reason havent assigned this shield against the game ender so will now
                                                            local oFirstEngineer
                                                            for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                                                                oFirstEngineer = oEngineer
                                                                break
                                                            end
                                                            ForkThread(AssignShieldToGameEnder, oShield, oFirstEngineer)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if not(bNearbyShield) then
                                            for iBuilding, oBuilding in tBuildingsNearby do
                                                if oBuilding:GetAIBrain().AiBotAI and oBuilding:GetAIBrain().AiBotTeam == aiBrain.AiBotTeam then
                                                    if AiBotUnitInfo.GetUnitMassCost(oBuilding[AiBotUnitInfo.refiUnitMassCost]) * oBuilding:GetFractionComplete() <= 5000 then
                                                        --Check the building position and size means it is actually a blocking building
                                                        if oBuilding:GetPosition()[1] >= rShieldAreaRect[1] and oBuilding:GetPosition()[1] <= rShieldAreaRect[3] and oBuilding:GetPosition()[3] >= rShieldAreaRect[2] and oBuilding:GetPosition()[3] <= rShieldAreaRect[2] and (not(oBuilding[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will destroy blocking building='..oBuilding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBuilding)..'; Building position='..repru(oBuilding:GetPosition())..'; will draw rectangle that this is within')
                                                                AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tLocation, iSearchRadius))
                                                            end
                                                            AiBotOrders.IssueTrackedKillUnit(oBuilding)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if iActionGiven then
                        iPreviousAction =  iActionGiven
                    end
                    return bProceededWithConstruction
                end

                function AssistShield(oShield)
                    --Assist this (if bPauseEngineers is true then will make sure every engineer is paused so they dont actually complete it)
                    if oShield:GetFractionComplete() < 1 then
                        if bDebugMessages == true then LOG(sFunctionRef..': AssistShield: Will repair shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' with fraction complete '..oShield:GetFractionComplete()) end
                        for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                            --Issue where engineers are given repair order but do nothing - will try adding small delay in case issue is being given same order every tick
                            if GetGameTimeSeconds() - (oEngineer[refiTimeOfLastShieldRepairOrder] or -10) < 1 and oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget] == oShield then
                                if bDebugMessages == true then LOG(sFunctionRef..': It has been less than 1s since we last gave order to repair') end
                            else
                                oEngineer[refiTimeOfLastShieldRepairOrder] = GetGameTimeSeconds()
                                if bDebugMessages == true then LOG(sFunctionRef..': Engineer unit state='..AiBotUnitInfo.GetUnitState(oEngineer)..'; Is state repairing='..tostring(oEngineer:IsUnitState('Repairing'))..'; Engineer work progress='..(oEngineer:GetWorkProgress() or 'nil')) end
                                AiBotOrders.IssueTrackedRepair(oEngineer, oShield, false, 'SpecShR', false)
                            end
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': AssistShield: Will assist shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' with fraction complete '..oShield:GetFractionComplete()) end
                        for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Giving guard order to oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer))
                                local oFocusUnit = oEngineer:GetFocusUnit()
                                if oFocusUnit then
                                    LOG(sFunctionRef..': Engineer cur focus unit='..oFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit))
                                end
                            end
                            AiBotOrders.IssueTrackedGuard(oEngineer, oShield, false, 'SpecShG', false)
                        end
                    end
                    iPreviousAction =  refiShieldActionAssist
                end

                if bDebugMessages == true then LOG(sFunctionRef..': Deciding what to do, iConstructedShields='..iConstructedShields..'; iPartConstructedShields='..iPartConstructedShields..'; iHighestPartCompleteShield='..iHighestPartCompleteShield..'; iActiveShields='..iActiveShields..'; iTotalAvailableLocations='..iTotalAvailableLocations) end
                if iConstructedShields == 0 then
                    --Want to build a shield - complete the closest to completion if we have any
                    if oNearestCompletionShield then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to construct a shield, will assist the one nearest completion='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)..' fraction complete='..oNearestCompletionShield:GetFractionComplete()) end
                        AssistShield(oNearestCompletionShield)
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to construct a shield, none under construction so will build a new one') end
                        ConstructNewShield()
                    end
                else
                    --We already have 1 constructed shield, want to make sure we have another shield that is closest to completion next
                    --% wanted - if are assigning 500 build power to this, and the shortest BT shield is 1250, then in theory we could end up building the shield in 0.4s, i.e. each tick would be 4%.  In reality this seems unlikely though
                    local iPercentCompleteWanted
                    local iTotalBuildPowerAvailable = 0
                    for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                        iTotalBuildPowerAvailable = iTotalBuildPowerAvailable + (oEngineer:GetBlueprint().Economy.BuildRate or 0)
                    end
                    if aiBrain.AiBotAI then
                        iTotalBuildPowerAvailable = iTotalBuildPowerAvailable * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainBuildMultiplier]
                    end
                    --Treat build power as being 50% more than it actually is to give a bit more leeway
                    iPercentCompleteWanted = math.min(0.99, math.max(0.8, 1 - iTotalBuildPowerAvailable * 2.5 / (iBlueprintBuildTime * 10) - 0.002))
                    if iPartConstructedShields > 0 and iHighestPartCompleteShield < iPercentCompleteWanted then
                        --Want to assist existing part complete shield
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to assist existing part complete shield as it isnt near complete yet, iPercentCompleteWanted='..iPercentCompleteWanted..'; oNearestCompletionShield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)..'; Fraction complete='..oNearestCompletionShield:GetFractionComplete()) end
                        AssistShield(oNearestCompletionShield)
                    else
                        --We have at least 1 constructed shield, and at least 1 shield whose % complete is at the level wanted; Therefore we want a 3rd shield that is near-complete constructed
                        if iPartConstructedShields + iConstructedShields < iTotalAvailableLocations and ConstructNewShield() then
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to build a new shiled as we have more available locations than we have shields built or started building') end
                        else
                            --Get the lowest complete shield to assist if it needs it
                            if iPartConstructedShields > 0 and (iLowestPartCompleteShield < iPercentCompleteWanted or iActiveShields == 0) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to assist the lowest complete shield as it isnt nearly done, oLowestCompletionShield='..oLowestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLowestCompletionShield)..'; Fraction complete='..oLowestCompletionShield:GetFractionComplete()) end
                                AssistShield(oLowestCompletionShield)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if weant to ctrlK a shield, iPartConstructedShields='..iPartConstructedShields..'; iConstructedShields='..iConstructedShields) end
                                if iPartConstructedShields == 0 and iConstructedShields >= 2 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to ctrlK a shield so can rebuild') end
                                    if oLowestConstructedShieldHealth and (not(oLowestConstructedShieldHealth[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will ctrlK shield '..oLowestConstructedShieldHealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLowestConstructedShieldHealth)) end
                                        AiBotOrders.IssueTrackedKillUnit(oLowestConstructedShieldHealth)
                                        --Clear assisting engineers in case they are assisting a part-complete shield that we want to stop
                                        if iPreviousAction == refiShieldActionAssist then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Previous action was to assist shield so will clear all engineerse that have a previous action being to assist a shield so they dont finish a part complete shield') end
                                            for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                                                AiBotOrders.IssueTrackedClearCommands(oEngineer)
                                            end
                                        end
                                    else
                                        local bAssistUnitToProtectInstead = false
                                        if oUnitToProtect:GetFractionComplete() < 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                                            local iCurHealth, iMaxHealth = AiBotUnitInfo. GetCurrentAndMaximumShield(oLastCompletedShield, true)
                                            if iCurHealth > iMaxHealth * 0.9 then
                                                bAssistUnitToProtectInstead = true
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unable to find shield to kill so will default to assisting last compelted shield, bAssistUnitToProtectInstead='..bAssistUnitToProtectInstead) end
                                        if bAssistUnitToProtectInstead then
                                            AssistShield(oUnitToProtect)
                                        else
                                            AssistShield(oLastCompletedShield)
                                        end
                                    end
                                else
                                    --We have 1 complete shield, and all other shield locations have near-complete shields, so dont want to do anything else - have the engineers assist the completed shield, unless it has >80% shield health and the unit to protect isnt completed yet
                                    local bAssistUnitToProtectInstead = false
                                    if oUnitToProtect:GetFractionComplete() < 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                                        local iCurHealth, iMaxHealth = AiBotUnitInfo. GetCurrentAndMaximumShield(oLastCompletedShield, true)
                                        if iCurHealth > iMaxHealth * 0.9 then
                                            bAssistUnitToProtectInstead = true
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nothing to do so will assist a complete shield unless want to assist underconstruction gameender, oLastCompletedShield='..oLastCompletedShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oLastCompletedShield)..'; bAssistUnitToProtectInstead='..tostring(bAssistUnitToProtectInstead)) end
                                    if bAssistUnitToProtectInstead then
                                        AssistShield(oUnitToProtect)
                                    else
                                        AssistShield(oLastCompletedShield)
                                    end
                                end
                            end
                        end
                    end
                end

                --Decide whether to ctrlK shield so can start building another
                if iConstructedShields >= math.max(iTotalAvailableLocations, 2) or (iConstructedShields > 1 and iConstructedShields + iPartConstructedShields >= iTotalAvailableLocations and iActiveShields < iConstructedShields) and (not(oLowestConstructedShieldHealth[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and not(oLowestConstructedShieldHealth[AiBotUnitInfo.refbEasyBrain]) then
                    --CtrlK a completed shield with the lowest shield value
                    if bDebugMessages == true then LOG(sFunctionRef..': iConstructedShields='..iConstructedShields..'; iTotalAvailableLocations='..iTotalAvailableLocations..'; iConstructedShields='..iConstructedShields..'; iPartConstructedShields='..iPartConstructedShields..'; iActiveShields='..iActiveShields..'; iLowestConstructedShieldHealth='..(iLowestConstructedShieldHealth or 'nil')) end
                    AiBotOrders.IssueTrackedKillUnit(oLowestConstructedShieldHealth)
                end

                --Make sure engineers show the action they have been assigned (as will have had orders cleared from above) - changed so will no longer clear in AiBotOrders
                --[[local bFirstEngineer = true
                for iEngineer, oEngineer in oUnitToProtect[reftEngineersActivelyShielding] do
                    if not(oEngineer[refiAssignedAction] == refActionSpecialShieldDefence) then
                        TrackEngineerAction(oEngineer, refActionSpecialShieldDefence, bFirstEngineer, iPriorityToUse)
                        if bFirstEngineer then bFirstEngineer = false end
                    end
                end--]]


            else
                if bDebugMessages == true then LOG(sFunctionRef..': Engineers no longer actively shielding, will end the loop at time '..GetGameTimeSeconds()) end
                oUnitToProtect[refbActiveUnitShieldingThread] = false
                break
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if AiBotUtilities.IsTableEmpty(oUnitToProtect[reftEngineersActivelyShielding]) == false then
            local tEngisToClear = {}
            for iEngi, oEngi in oUnitToProtect[reftEngineersActivelyShielding] do
                if AiBotUnitInfo.IsUnitValid(oEngi) then
                    table.insert(tEngisToClear, oEngi)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is tEngisToClear empty='..tostring(tEngisToClear)) end
            if AiBotUtilities.IsTableEmpty(tEngisToClear) == false then
                for iEngi, oEngi in tEngisToClear do
                    AiBotOrders.IssueTrackedClearCommands(oEngi)
                    ClearEngineerTracking(oEngi)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code at time '..GetGameTimeSeconds()..'; Is game ender valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnitToProtect) or false)..'; ActiveShieldMonitoe='..tostring(oUnitToProtect[refbActiveUnitShieldingThread] or false)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignEngineerToShieldDefenceDuty(oEngineer, tLZTeamData)
    --Get the highest value unit to defend (for now will only support 1 unit for shield defence duty)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignEngineerToShieldDefenceDuty'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oUnitToProtect
    local iHighestMassValue = 0
    local iCurMassValue
    local iUnitToProtectEntry
    for iGameEnder, oGameEnder in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
        if AiBotUnitInfo.IsUnitValid(oGameEnder) then
            iCurMassValue = oGameEnder[AiBotUnitInfo.refiUnitMassCost] * oGameEnder:GetFractionComplete()
            if iCurMassValue > iHighestMassValue then
                iHighestMassValue = iCurMassValue
                oUnitToProtect = oGameEnder
                iUnitToProtectEntry = iGameEnder
            end
        end
    end
    if oUnitToProtect and oUnitToProtect[AiBotBuilding.reftArtiTemplateRefs] then
        oUnitToProtect = nil
        table.remove(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection], iUnitToProtectEntry)
        if bDebugMessages == true then LOG(sFunctionRef..': Have a gameender flagged as wanting special shielding, will cancel as it is part of a GE template') end
    end
    if not(oUnitToProtect) then
        --Clear engineer actions as we dont have something for them to do after all
        ClearEngineerTracking(oEngineer)
    else
        if not(oUnitToProtect[reftEngineersActivelyShielding]) then oUnitToProtect[reftEngineersActivelyShielding] = {} end
        table.insert(oUnitToProtect[reftEngineersActivelyShielding], oEngineer)
        oEngineer[refoUnitActivelyShielding] = oUnitToProtect
        if not(oUnitToProtect[refbActiveUnitShieldingThread]) then
            ForkThread(ActiveShieldMonitor, oUnitToProtect, tLZTeamData, oEngineer:GetAIBrain().AiBotTeam)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTableRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, bWantToChangeDueToNovax, bWantToChangeDueToBuildingMultipleGameEnder)
    local sFunctionRef = 'GETemplateReassessGameEnderCategory'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, P'..iPlateau..'L'..iLandZone..'; Is oFirstUEF valid='..tostring(AiBotUnitInfo.IsUnitValid(oFirstUEF))..'; Does GETemplate contain novax='..tostring(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryNovaxCentre, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]))..'; is refoNearbyExperimentalResourceGen empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]))..'; subrefbGEShieldSACU='..tostring(tLZTeamData[AiBotMap.subrefbGEShieldSACU] or false)..'; Time='..GetGameTimeSeconds()) end
    local bDontConsiderGameEnderDueToExistingConstruction = false
    if not(tLZTeamData[AiBotMap.subrefbGEShieldSACU]) then
        if bWantToChangeDueToBuildingMultipleGameEnder then
            bDontConsiderGameEnderDueToExistingConstruction = true
            if bDebugMessages == true then LOG(sFunctionRef..':called this due to building multiple gameenders, so wont try and get another') end
        elseif not(tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) or not(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory])) then
            --GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, bOptionalReturnMassToCompleteOtherZoneUnderConstruction, iOptionalSearchRange, iOptionalCategoryFilter, bOptionalClearEngineersInOtherZonesWithoutConstruction, iOptionalTableRefToIgnoreForThisZone)
            local iMassToCompleteGameEnders = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true,                   nil,                    AiBotUnitInfo.refCategoryGameEnder, false,                                        iTableRef)
            if bDebugMessages == true then LOG(sFunctionRef..': iMassToCompleteGameEnders='..(iMassToCompleteGameEnders or 'nil')..'; Time='..GetGameTimeSeconds()) end
            if iMassToCompleteGameEnders > 30000 and iMassToCompleteGameEnders < math.min(80000, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] * 0.5) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.min(900, 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 175000 then
                bDontConsiderGameEnderDueToExistingConstruction = true
            end
        end
    end

    if tLZTeamData[AiBotMap.subrefbGEShieldSACU] and (AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false or table.getn(tTableRef[AiBotMap.subrefGEArtiLocations]) <= 1) then
        if bDebugMessages == true then LOG(sFunctionRef..': Doing an expensive shield SACU shielding strategy and we already have a GE arti or only space for one, so want a gameender') end
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
    elseif tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] and not(EntityCategoryContains(categories.SUBCOMMANDER, oFirstEngineer.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) > 800 then
        if bDebugMessages == true then LOG(sFunctionRef..': Want SACUs for land zone and enemy base is too far for t3 arti so will ignore normal logic and just consider building game-enders and novax') end
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryNovaxCentre
    elseif not(oFirstUEF) and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryNovaxCentre, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) and not(AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryFixedT3Arti, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory])) then
        --Switch from novax to T3 arti (or gameender if enemy base is very far away)
        if bDebugMessages == true then LOG(sFunctionRef..': we dont have a UEF engi but our category includes novax, will include T3 arti if enemy base is close, otherwise will include gameender') end
        local iFurthestEnemyBaseDist = 0
        local iClosestEnemyBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])
        local iEnemyBasesWithinArtiThreshold = 0
        local iEnemyBasesOutsideArtiThreshold = 0
        local iArtiThreshold = 775 --Want a bit of leeway due to risk we build T3 arti at the rear of the land zone and it ends up out of range
        local iCurBaseDist

        for iBrain, oBrain in ArmyBrains do
            if oBrain.AiBotTeam and not(oBrain.AiBotTeam == iTeam) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
                iCurBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oBrain))
                if iCurBaseDist <= iArtiThreshold then
                    iEnemyBasesWithinArtiThreshold = iEnemyBasesWithinArtiThreshold + 1
                else
                    iEnemyBasesOutsideArtiThreshold = iEnemyBasesOutsideArtiThreshold + 1
                end
                iFurthestEnemyBaseDist = math.max(iFurthestEnemyBaseDist, iCurBaseDist)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemyBaseDist='..iClosestEnemyBaseDist..'; iEnemyBasesWithinArtiThreshold='..iEnemyBasesWithinArtiThreshold..'; iEnemyBasesOutsideArtiThreshold='..iEnemyBasesOutsideArtiThreshold..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
        if iClosestEnemyBaseDist <= iArtiThreshold and (iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= 1 + 2 * iEnemyBasesOutsideArtiThreshold or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 125000 then
            if bDebugMessages == true then LOG(sFunctionRef..': Including T3 arti and novax as options to build') end
            tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre
        else
            tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryNovaxCentre
            if bDebugMessages == true then LOG(sFunctionRef..': Including gameender and novax as options to build') end
        end
    elseif not(oFirstSeraphim) and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategorySML, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
        --Switch from yolona to gameender
        if bDebugMessages == true then LOG(sFunctionRef..': will expand from building SML to building any gameender as we lack a seraphim engi') end
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
    elseif not(oFirstAeon) and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryParagon, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will expand from building paragon to building any gameender') end
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
    else
        --Set to T3 arti or gameender (include novax if we have no existing arti)
        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) then
            if bDebugMessages == true then LOG(sFunctionRef..': No existing arti units so will cover t3 arti gameender and novax, bDontConsiderGameEnderDueToExistingConstruction='..tostring(bDontConsiderGameEnderDueToExistingConstruction or false)) end
            local iArtiThreshold = 800
            if bDontConsiderGameEnderDueToExistingConstruction and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) <= iArtiThreshold and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 125000 then
                tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre
            else
                tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryNovaxCentre
            end
        else
            --If we have a novax built, then get T3 arti if enemy base is close (unless have high mass income and enemy has t3 arti/similar, in which case look to get gameender)
            if bDebugMessages == true then LOG(sFunctionRef..': We already have an arti type unit so will build t3 arti if enemy close, or t3 arti and gameender otherwise') end
            local iFurthestEnemyBaseDist = 0
            local iClosestEnemyBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])
            local iEnemyBasesWithinArtiThreshold = 0
            local iEnemyBasesOutsideArtiThreshold = 0
            local iArtiThreshold = 800
            local iCurBaseDist

            for iBrain, oBrain in ArmyBrains do
                if oBrain.AiBotTeam and not(oBrain.AiBotTeam == iTeam) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
                    iCurBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oBrain))
                    if iCurBaseDist <= iArtiThreshold then
                        iEnemyBasesWithinArtiThreshold = iEnemyBasesWithinArtiThreshold + 1
                    else
                        iEnemyBasesOutsideArtiThreshold = iEnemyBasesOutsideArtiThreshold + 1
                    end
                    iFurthestEnemyBaseDist = math.max(iFurthestEnemyBaseDist, iCurBaseDist)
                end
            end



            if bDebugMessages == true then LOG(sFunctionRef..': bWantToChangeDueToNovax='..tostring(bWantToChangeDueToNovax or false)..'; iClosestEnemyBaseDist='..iClosestEnemyBaseDist..'; iFurthestEnemyBaseDist='..iFurthestEnemyBaseDist..'; iEnemyBasesWithinArtiThreshold='..iEnemyBasesWithinArtiThreshold..'; iEnemyBasesOutsideArtiThreshold='..iEnemyBasesOutsideArtiThreshold..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; bDontConsiderGameEnderDueToExistingConstruction='..tostring(bDontConsiderGameEnderDueToExistingConstruction)) end
            if bWantToChangeDueToNovax and (bDontConsiderGameEnderDueToExistingConstruction or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 125000)) then
                --We dont have the eco for a gameender, so want novax or T3 arti
                local bWantTorps = false
                local tiAirSubteams = {}
                local iT3ArtiCount = 0
                local iNovaxCount = 0
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    tiAirSubteams[oBrain.AiBotAirSubteam] = true
                    if not(oBrain:IsDefeated()) then
                        iNovaxCount = iNovaxCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNovaxCentre)
                        iT3ArtiCount = iT3ArtiCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFixedT3Arti)
                    end
                end
                for iAirSubteam, bInclude in tiAirSubteams do
                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] then bWantTorps = true break end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': We lack eco for game endero s, goet novax only if we want torps or we have as many T3 arti as novaxes, bWantTorps='..tostring(bWantTorps)) end
                if bWantTorps or (iNovaxCount <= iT3ArtiCount and (iFurthestEnemyBaseDist >= iArtiThreshold or iNovaxCount >= 5 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]))) then
                    tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryNovaxCentre
                    if bDebugMessages == true then LOG(sFunctionRef..': will get another novax') end
                elseif iClosestEnemyBaseDist <= iArtiThreshold and (iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= 1 + 2 * iEnemyBasesOutsideArtiThreshold) then
                    tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti
                    if bDebugMessages == true then LOG(sFunctionRef..': We are calling this function due to a novax, and have decided to switch to just building T3 arti') end
                else
                    if iFurthestEnemyBaseDist >= iArtiThreshold and (not(bDontConsiderGameEnderDueToExistingConstruction) or iEnemyBasesWithinArtiThreshold == 0) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 + 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Almost have enough eco for a gameender so will get it') end
                        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Will get novax or T3 arti as cant decide') end
                        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]..'; subrefiTeamMassStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; iFurthestEnemyBaseDist='..iFurthestEnemyBaseDist..'; iArtiThreshold='..iArtiThreshold..'; iEnemyBasesWithinArtiThreshold='..iEnemyBasesWithinArtiThreshold..'; iEnemyBasesOutsideArtiThreshold='..iEnemyBasesOutsideArtiThreshold..'; Does GE Template category include gameender='..tostring((tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] and (AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]))))) end
                if AiBotMap.iMapSize >= 500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 200 and not(bDontConsiderGameEnderDueToExistingConstruction) and (oFirstUEF or oFirstSeraphim or oFirstAeon) and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] <= 2 then
                    tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
                    if bDebugMessages == true then LOG(sFunctionRef..': Have high mass income so will get gameender for second arti') end
                elseif tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] and (AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) or (iClosestEnemyBaseDist <= iArtiThreshold and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 125000 and (iFurthestEnemyBaseDist <= iArtiThreshold or iEnemyBasesWithinArtiThreshold >= 1 + 2 * iEnemyBasesOutsideArtiThreshold or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))) then
                    tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryGameEnder
                    if bDebugMessages == true then LOG(sFunctionRef..': Will include T3 arti along with gameender category') end
                else
                    tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryGameEnder
                    if bDebugMessages == true then LOG(sFunctionRef..': will get gameender category only') end
                end
            end
        end
    end

    --Exclude paragon if we have high mass or nearby one (QUIET/LOUD)
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= math.min(800, math.max(350, 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]))
            or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]) == false and (AiBotUtilities.bQuietModActive or AiBotUtilities.bLOUDModActive))
    then
        if bDebugMessages == true then LOG(sFunctionRef..': Want to exclude paragon as we have lots of mass') end
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] - AiBotUnitInfo.refCategoryParagon
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] then
            --Exclude t3 arti if we are able to build a game-ender
            local aiBrain = oFirstEngineer:GetAIBrain()
            local iPotentialCategory = tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] - AiBotUnitInfo.refCategoryFixedT3Arti
            local sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iPotentialCategory, oFirstEngineer,      nil,            nil,        nil,            nil,                                nil,                    10)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering excluding t3 arti if we have paragon, sArtiToBuild if we exclude='..(sArtiToBuild or 'nil')) end
            if sArtiToBuild then
                tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = iPotentialCategory
                if bDebugMessages == true then LOG(sFunctionRef..': Will exclude t3 arti from refiLastGameEnderTemplateCategory to build') end
            end
        end
    end


    --Check - can our first engineer build units of the desired category? If not then change the category to be an experimental level unit as we might have unit restrictions preventing this
    if not(tLZTeamData[AiBotMap.subrefbGEShieldSACU]) and oFirstEngineer then
        local aiBrain = oFirstEngineer:GetAIBrain()

        --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences, iOptionalMaxSkirtSize)
        local sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstEngineer,      nil,            nil,        nil,            nil,                                nil,                    10)
        if bDebugMessages == true then LOG(sFunctionRef..': oFirstEngineer='..oFirstEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstEngineer)..'; sArtiToBuild='..(sArtiToBuild or 'nil')) end
        if not(sArtiToBuild) then
            --LOUD prevents T3 engis building experimentals
            if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.SUBCOMMANDER, tTableRef[AiBotMap.subrefGEEngineers])) then
                if bDebugMessages == true then LOG(sFunctionRef..': We have no SACUs assigned to this template so will flag we want some unless we already have lots in the zone') end
                --Flag we want SACUs unless we already have lots in this zone
                local tSACUsInZone
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    tSACUsInZone = EntityCategoryFilterDown(categories.SUBCOMMANDER, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tSACUsInZone) or table.getn(tSACUsInZone) <= 6 then
                        tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] = GetGameTimeSeconds()
                        if bDebugMessages == true then LOG(sFunctionRef..': Flagging we want SACUs for this zone') end
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Resorting to building any experimental since we dont seem able to build normal ones, and flagging that we are unable to build arti or gameenders') end
                tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = AiBotUnitInfo.refCategoryExperimentalLevel - categories.NAVAL - categories.SERAPHIM * categories.FACTORY - categories.FACTORY * categories.GATE - categories.TRANSPORTATION  - categories.DEFENSE * categories.STRUCTURE * categories.DIRECTFIRE - categories.STRUCTURE * categories.ANTIAIR - categories.TRANSPORTFOCUS - categories.STRUCTURE * categories.COUNTERINTELLIGENCE
                AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbUnableToBuildArtiOrGameEnders] = true
            end
        end
    end

    --exclude experimental resource generator if we already have one in this template (LOUD doesnt allow them to be built close by each other, and for FAF if we have a paragon then we dont want a second)
    if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoNearbyExperimentalResourceGen]) or (AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.MASSFABRICATION * categories.EXPERIMENTAL, tTableRef[AiBotMap.subrefGEArtiUnits])) == false) then
        tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] = tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory] - categories.MASSFABRICATION * categories.EXPERIMENTAL
    end
    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code, will list out blueprints that meet the desired GE template category')
        local tBlueprints = EntityCategoryGetUnitList(tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory])
        local tsBlueprintsAndName = {}
        for _, sBlueprint in tBlueprints do
            table.insert(tsBlueprintsAndName, sBlueprint..': '..(__blueprints[sBlueprint].General.UnitName or 'nil')..', Faction='..(__blueprints[sBlueprint].General.FactionName or 'Unknown'))
        end
        LOG(sFunctionRef..': Blueprints='..repru(tsBlueprintsAndName))

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GETemplateStartBuildingArtiOrGameEnder(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, tTableRef, iTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer)
    --Decide on the arti blueprint we want to try and build; priority to use:
    --Aeon (Paragon and T3 arti) > Seraphim (Yolona) > UEF (Mavor) > Cybran (Scathis)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GETemplateStartBuildingArtiOrGameEnder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bTriedBuildingSomething = false

    if bDebugMessages == true then LOG(sFunctionRef..': Start of logic for building arti at zone '..iLandZone..', is tAvailableEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; Arti locations='..repru(tTableRef[AiBotMap.subrefGEArtiLocations])..'; Template size='..tTableRef[AiBotMap.subrefGESize]..'; oFirstAeon='..(oFirstAeon.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstAeon) or 'nil')..'; oFirstSeraphim='..(oFirstSeraphim.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstSeraphim) or 'nil')..'; oFirstUEF='..(oFirstUEF.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstUEF) or 'nil')) end
    local sArtiToBuild
    local aiBrain
    local oEngineerToBuild
    local bUsingSACU = false

    if oFirstAeon then
        aiBrain = oFirstAeon:GetAIBrain()
        oEngineerToBuild = oFirstAeon
        --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,                                    oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences, iOptionalMaxSkirtSize)
        sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstAeon,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
        --Paragon override if we are trying to build paragon or t3 arti
        if (aiBrain[AiBotEconomy.refbBuiltParagon] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 150)) and (sArtiToBuild == 'xab1401' or sArtiToBuild == 'uab2302') then
            GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTableRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, false)
            sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstAeon,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
        end
        if bDebugMessages == true and sArtiToBuild then LOG(sFunctionRef..': Aeon sArtiToBuild='..sArtiToBuild..'; Can we build this in the last arti location='..tostring(aiBrain:CanBuildStructureAt(sArtiToBuild, tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))..'; Could we build T3 arti in this location='..tostring(aiBrain:CanBuildStructureAt('uab2302', tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))) end
    end
    if not(sArtiToBuild) then
        if oFirstSeraphim then
            aiBrain = oFirstSeraphim:GetAIBrain()
            sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstSeraphim,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
            oEngineerToBuild = oFirstSeraphim
            if bDebugMessages == true and sArtiToBuild then LOG(sFunctionRef..': Seraphim sArtiToBuild='..sArtiToBuild..'; Can we build this in the last arti location='..tostring(aiBrain:CanBuildStructureAt(sArtiToBuild, tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))..'; Could we build T3 arti in this location='..tostring(aiBrain:CanBuildStructureAt('uab2302', tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))) end
        end
        if not(sArtiToBuild) then
            if oFirstUEF then
                aiBrain = oFirstUEF:GetAIBrain()
                sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstUEF,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                oEngineerToBuild = oFirstUEF
                if bDebugMessages == true and sArtiToBuild then LOG(sFunctionRef..': UEF sArtiToBuild='..sArtiToBuild..'; Can we build this in the last arti location='..tostring(aiBrain:CanBuildStructureAt(sArtiToBuild, tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))..'; Could we build T3 arti in this location='..tostring(aiBrain:CanBuildStructureAt('uab2302', tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))) end
            end
            if not(sArtiToBuild) then
                if oFirstCybran then
                    aiBrain = oFirstCybran:GetAIBrain()
                    sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstCybran,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                    oEngineerToBuild = oFirstCybran
                    if bDebugMessages == true and sArtiToBuild then LOG(sFunctionRef..': Cybran sArtiToBuild='..sArtiToBuild..'; Can we build this in the last arti location='..tostring(aiBrain:CanBuildStructureAt(sArtiToBuild, tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))..'; Could we build T3 arti in this location='..tostring(aiBrain:CanBuildStructureAt('uab2302', tTableRef[AiBotMap.subrefGEArtiLocations][table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])]))) end
                end
                if not(sArtiToBuild) then
                    if oFirstEngineer then
                        --If this is LOUD and we have SACUs then have the first of these try to build the blueprint
                        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                            local tSACUs = EntityCategoryFilterDown(categories.SUBCOMMANDER, tAvailableEngineers)
                            if AiBotUtilities.IsTableEmpty(tSACUs) == false then
                                oEngineerToBuild = tSACUs[1]
                                sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oEngineerToBuild,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                                --Expand to include t3 arti (incase we didnt alreayd) if not found anything to build; one reason why nothing found to build could be limited build area
                                if not(sArtiToBuild) and aiBrain then
                                    sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovax, oEngineerToBuild,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                                end
                                if sArtiToBuild then
                                    oFirstEngineer = tSACUs[1]
                                    bUsingSACU = true
                                end
                            end
                        end
                        if not(bUsingSACU) then
                            aiBrain = oFirstEngineer:GetAIBrain()
                            sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oFirstEngineer,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                            oEngineerToBuild = oFirstEngineer
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting oEngineerToBuild to be equal to oFirstEngineer='..(oFirstEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstEngineer) or 'nil')..'; sArtiToBuild='..(sArtiToBuild or 'nil')) end
                            --Expand to include t3 arti (incase we didnt alreayd) if not found anything to build; one reason why nothing found to build could be limited build area
                            if not(sArtiToBuild) and aiBrain then
                                if bDebugMessages == true then LOG(sFunctionRef..': Cant build the desired category, will reassess, and if still cant build then will just get gameender+t3 arti') end
                                GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTableRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, false)
                                sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], oEngineerToBuild,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                                if bDebugMessages == true then LOG(sFunctionRef..': sArtiToBuild after reassessment='..(sArtiToBuild or 'nil')) end
                                if not(sArtiToBuild) then
                                    sArtiToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovax, oEngineerToBuild,    nil,        nil,        nil,            nil,                                nil,                    tTableRef[AiBotMap.subrefiMaxArtiSkirtSize])
                                    if bDebugMessages == true then LOG(sFunctionRef..': sArtiToBuild after trying all gameenders and t3 arti='..(sArtiToBuild or 'nil')) end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if bDebugMessages == true then
        LOG(sFunctionRef..': sArtiToBuild before considering engi last order='..(sArtiToBuild or 'nil')..'; oEngineerToBuild='..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')..'; iCyclesWaitingForEngineer='..(tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] or 'nil')..'; Is table of available engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; bUsingSACU='..tostring(bUsingSACU or false)..'; is oEngineerToBuild valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineerToBuild))..'; Time='..GetGameTimeSeconds())
        if sArtiToBuild then
            local tBlueprints = EntityCategoryGetUnitList(tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory])
            LOG(sFunctionRef..': All blueprints that meet GE template category:')
            for iEntry, sBlueprint in tBlueprints do
                LOG('Blueprint '..sBlueprint..': '..(__blueprints[sBlueprint].General.UnitName or 'nil'))
            end
        end
    end
    if sArtiToBuild and AiBotUnitInfo.IsUnitValid(oEngineerToBuild) then
        local sLastBlueprint = oEngineerToBuild[AiBotOrders.reftiLastOrders][oEngineerToBuild[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil'
        if sLastBlueprint and not(sLastBlueprint == sArtiToBuild) and EntityCategoryContains(tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory], sLastBlueprint) then
            sArtiToBuild = sLastBlueprint
            if bDebugMessages == true then LOG(sFunctionRef..': engi last blueprint was different, but also met the category, sLastBlueprint='..sLastBlueprint..'; so will change what to build to this') end
        end

        tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] = 0
        --Is either of the arti locations available? If not then need to reclaim any buildings there (assuming we dont have a T3 arti there)
        local iBuildingSize = AiBotUnitInfo.GetBuildingSize(sArtiToBuild)
        local tLocationToBuild
        for iEntry, tBuildLocation in tTableRef[AiBotMap.subrefGEArtiLocations] do
            if aiBrain:CanBuildStructureAt(sArtiToBuild, tBuildLocation) then
                tLocationToBuild = {tBuildLocation[1], tBuildLocation[2],tBuildLocation[3]}
                break
            end
        end
        if not(tLocationToBuild) then
            --Look to reclaim buildings that are blocking us, unless they are very high value buildings
            local iLowestValueBlockingBuildings = 150000 --basic threshold to prevent reclaiming really high value buildings
            local tLowestValueBlockingBuildings, iCurValueBlockingBuildings, iLowestValueRef
            local bHavePotentiallyValidLocation = false
            local tUnitsToConsiderReclaiming, iXDif, iZDif
            local iArtiRadius = AiBotUnitInfo.GetBuildingSize(sArtiToBuild) * 0.5
            local iThresholdDistDif = iArtiRadius + 3 - 0.8 --i.e. a shield is radius 6; so this gives a 0.8 leeway to hopefully cover off rounding
            for iEntry, tBuildLocation in tTableRef[AiBotMap.subrefGEArtiLocations] do
                local tBlockingUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tBuildLocation, iBuildingSize * 0.5 - 0.3)) --tried with -0.7 but wouldnt pickup on SAM that was just inside the shield build area
                if not(tBlockingUnits) then
                    AiBotUtilities.ErrorHandler('Tempalte location cant be built on but has no units in it', true)
                    if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry]) then
                        if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount] = {} end
                        tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = 0
                    end
                    tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] + 1
                else
                    local tBlockingUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryWall + categories.EXPERIMENTAL, tBlockingUnits)
                    if AiBotUtilities.IsTableEmpty(tBlockingUnits) then
                        AiBotUtilities.ErrorHandler('Template location cant be built on but has no buildings in it', true)
                        if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry]) then
                            if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount] = {} end
                            tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = 0
                        end
                        tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] + 1
                    else
                        tUnitsToConsiderReclaiming = {}
                        local oBlockingExperimentalToAssist
                        for iUnit, oUnit in tBlockingUnits do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering potentially blocking unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to arti position='..AiBotUtilities.GetDistanceBetweenPositions(tBuildLocation, oUnit:GetPosition())..'; Fraction complete='..oUnit:GetFractionComplete()..'; oUnit[AiBotBuilding.reftArtiTemplateRefs]='..repru(oUnit[AiBotBuilding.reftArtiTemplateRefs])) end
                                if oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                                    --Do nothing; abort if the unit is more than .5 within the margin
                                    local bAbort = true
                                    local iUnitRadius = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) * 0.5

                                    iXDif = oUnit:GetPosition()[1] - tBuildLocation[1]
                                    if iXDif < 0 then iXDif = iXDif - iUnitRadius
                                    else iXDif = iXDif + iUnitRadius end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Blocking unit XDif='..iXDif..'; iThresholdDistDif='..iThresholdDistDif..'; tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry]='..(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] or 'nil')) end
                                    if math.abs(iXDif) >= iThresholdDistDif then
                                        bAbort = false
                                    else
                                        iZDif = oUnit:GetPosition()[3] - tBuildLocation[3]
                                        if iZDif < 0 then iZDif = iZDif - iUnitRadius
                                        else iZDif = iZDif + iUnitRadius end

                                        if bDebugMessages == true then LOG(sFunctionRef..': Blocking unit ZDif='..iZDif..'; Unit Xposition='..oUnit:GetPosition()[1]..'; tBuildLocationX='..tBuildLocation[1]..'; Unit Z position='..oUnit:GetPosition()[3]..'; tBuildLocationZ='..tBuildLocation[3]..'; iUnitRadius='..iUnitRadius..'; iArtiRadius='..iArtiRadius) end
                                        if math.abs(iZDif) >= iThresholdDistDif then
                                            --Assume unit isnt actually a true blocking unit and ignore
                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit might not actually be blocking so will continue search') end
                                            bAbort = false
                                            --Smaller artiref buildings - more likely they arent actually blocking if X is dif
                                        elseif iUnitRadius <= 3 and iXDif >= iArtiRadius + iUnitRadius and (tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] or 0) <= 60 and (iUnitRadius == 1 or (tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] or 0) <= 30) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Probably dont have a blocking building with this so will look for other buildings') end
                                            bAbort = false
                                        end
                                    end

                                    if bAbort then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Blocking building is part of arti template so want to abort and not reclaim anything') end
                                        tUnitsToConsiderReclaiming = nil
                                        break
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Were going to abort but as the dist is far enough away will treat this unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as not blocking') end
                                    end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) and (oUnit:GetFractionComplete() >= 0.05 or oUnit:GetHealth() >= 500 or AiBotUtilities.GetDistanceBetweenPositions(tBuildLocation, oUnit:GetPosition()) <= 1.5) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have an experimental level unit that might be blocking, if it is close then will record') end
                                    if EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, oUnit.UnitId) and oUnit:GetFractionComplete() < 1 then
                                        --Just assist the experimental so it gets completed
                                        oBlockingExperimentalToAssist = oUnit
                                    elseif AiBotUtilities.GetDistanceBetweenPositions(tBuildLocation, oUnit:GetPosition()) <= 3 then
                                        oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTableRef}
                                        if oUnit:GetFractionComplete() < 1 then tTableRef[AiBotMap.subrefbFailedToGetArtiLocation] = false end
                                        local bAdd = true
                                        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false then
                                            for iRecorded, oRecorded in tTableRef[AiBotMap.subrefGEArtiUnits] do
                                                if oRecorded == oUnit then bAdd = false break end
                                            end
                                        end
                                        if bAdd then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding blocking arti unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of arti units for P'..iPlateau..'Z'..iLandZone..'T'..iTableRef) end
                                            table.insert(tTableRef[AiBotMap.subrefGEArtiUnits], oUnit)
                                        end
                                    end
                                    tUnitsToConsiderReclaiming = nil
                                    break

                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding blocking unit to table of units to consider reclaiming') end
                                    table.insert(tUnitsToConsiderReclaiming, oUnit)
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to consider reclaiming empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToConsiderReclaiming))) end
                        if AiBotUtilities.IsTableEmpty(tUnitsToConsiderReclaiming) == false then
                            iCurValueBlockingBuildings = AiBotUnitInfo.GetMassCostOfUnits(tUnitsToConsiderReclaiming)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurValueBlockingBuildings='..iCurValueBlockingBuildings..'; iLowestValueBlockingBuildings='..iLowestValueBlockingBuildings) end
                            if iCurValueBlockingBuildings < iLowestValueBlockingBuildings then
                                iLowestValueBlockingBuildings = iCurValueBlockingBuildings
                                tLowestValueBlockingBuildings = tUnitsToConsiderReclaiming
                                iLowestValueRef = iEntry
                                bHavePotentiallyValidLocation = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Have potentially valid location, and will record this build location') end
                            end
                        elseif oBlockingExperimentalToAssist then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have a friendly experimental unit blocking the build location so will try and assist it to complete it and make some space, oBlockingExperimentalToAssist='..oBlockingExperimentalToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBlockingExperimentalToAssist)..'; Fraction complete='..oBlockingExperimentalToAssist:GetFractionComplete()) end
                            GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTableRef, oBlockingExperimentalToAssist, nil)
                        else
                            if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry]) then
                                if not(tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount] = {} end
                                tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = 0
                            end
                            tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEArtiBlockedFailureCount][iEntry] + 1
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering blocking buildings, bHavePotentiallyValidLocation='..tostring(bHavePotentiallyValidLocation or false)) end
            if bHavePotentiallyValidLocation then
                tTableRef[AiBotMap.subrefbFailedToGetArtiLocation] = false
                --Get all engineers to reclaim the units here
                local iCtrlKdUnits = 0
                local oUnitToReclaim
                for iUnit, oUnit in tLowestValueBlockingBuildings do
                    if oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() == 1 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryVolatile + categories.COMMAND, oUnit.UnitId)) then
                        --CtrlK instead of reclaiming
                        AiBotOrders.IssueTrackedKillUnit(oUnit)
                        iCtrlKdUnits = iCtrlKdUnits + 1
                    elseif not(oUnitToReclaim) then oUnitToReclaim = oUnit
                    end
                end

                if oUnitToReclaim then
                    CheckAndClearEngineersConstructingTargetUnit(oUnitToReclaim, tLZTeamData, iPlateau, iLandZone)
                    for iEngineer, oEngineer in tAvailableEngineers do
                        if oEngineer[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineer, false, nil, iTeam) end
                        AiBotOrders.IssueTrackedReclaim(oEngineer, oUnitToReclaim, false, 'GERecl', false)
                    end
                    tAvailableEngineers = nil
                    tAvailableT3EngineersByFaction = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Want engineers to reclaim blocking unit '..oUnitToReclaim.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToReclaim)) end
                elseif bDebugMessages == true then LOG(sFunctionRef..': No unit to eclaim, ctrlKcount='..iCtrlKdUnits)
                end
            else
                --Dont have a valid location, so need to come up with some redundancy logic, e.g. clear engis and flag that we mustn't try and use this location again, unless we already have an arti unit
                --e.g. have a flag on the index; and then when creating an index first check we dont already have an index; and then update the function for considering if we have available locations
                tTableRef[AiBotMap.subrefbFailedToGetArtiLocation] = true
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': oEngineerToBuild='..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')..'; Is table of tAvailableEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))) end
            --We have a location to build - get 1 engineer to build (the others can build a shield)
            for iEngineer, oEngineer in tAvailableEngineers do
                if oEngineer == oEngineerToBuild then
                    table.remove(tAvailableEngineers, iEngineer)
                    if bDebugMessages == true then LOG(sFunctionRef..': Removing engineer from table of engineers by faction if it isnt empty, faction='..(AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId) or 'nil')..'; Engineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Is tAvailableT3EngineersByFaction empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction))..'; Is tAvailableT3EngineersByFaction for faction empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction[AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)]))) end
                    if not(bUsingSACU) then
                        table.remove(tAvailableT3EngineersByFaction[AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)], 1)
                    else
                        for iUnit, oUnit in tAvailableT3EngineersByFaction[AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)] do
                            if oUnit == oEngineer then
                                table.remove(tAvailableT3EngineersByFaction[AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)], iUnit)
                                break
                            end
                        end
                    end
                    break
                end
            end

            local tMoveLocation = GetLocationToMoveForConstruction(oEngineerToBuild, tLocationToBuild, sArtiToBuild, 0, false)

            --Dont move+build if too far away, incase is terrain that means our move position ends up causing us to go in a different direction
            if tMoveLocation and (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) <= 10 and AiBotUtilities.GetDistanceBetweenPositions(tLocationToBuild, oEngineerToBuild:GetPosition()) <= 10 + (oEngineerToBuild:GetBlueprint().Economy.MaxBuildDistance or 5) then
                if bDebugMessages == true then LOG(sFunctionRef..': GE Telling engineer '..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')..' to move to '..repru(tMoveLocation)..' and then build '..sArtiToBuild..' at location '..repru(tLocationToBuild)..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTableRef='..iTableRef..'; refbSpecialMicroActive='..tostring(oEngineerToBuild[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; refiMoveAndBuildStuckCount='..(oEngineerToBuild[AiBotOrders.refiMoveAndBuildStuckCount] or 'nil')) end
                AiBotOrders.IssueTrackedMoveAndBuild(oEngineerToBuild, tLocationToBuild, sArtiToBuild, tMoveLocation, 1, false, 'GEMBArtT'..iTableRef)
                bTriedBuildingSomething = true
                if AiBotUtilities.GetDistanceBetweenPositions(oEngineerToBuild:GetPosition(), tMoveLocation) <= 2 then oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] = (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) + 1 end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': GE Telling engineer '..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')..' to build '..sArtiToBuild..' at build location '..repru(tLocationToBuild)..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTableRef='..iTableRef..'; refbSpecialMicroActive='..tostring(oEngineerToBuild[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; refiMoveAndBuildStuckCount='..(oEngineerToBuild[AiBotOrders.refiMoveAndBuildStuckCount] or 'nil')) end
                ConsiderResettingGEEngineerJustBeforeGivingNewOrder(oEngineerToBuild, tLocationToBuild, sArtiToBuild)
                AiBotOrders.IssueTrackedBuild(oEngineerToBuild, tLocationToBuild, sArtiToBuild, false, 'GEBArt')
                bTriedBuildingSomething = true
                tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] = ( tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] or 0) + 1
                if tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] >= 60 and math.round(tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] / 10) * 10 == tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] then
                    --Reassess what to build every 10s as we have spent more than a minute trying to build something
                    GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTableRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, false)
                end
            end
            if oEngineerToBuild[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineerToBuild, false, nil, iTeam) end
            oEngineerToBuild[refbPrimaryBuilder] = true
            if not(oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][3] == iTableRef) or not( oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                if bDebugMessages == true then LOG(sFunctionRef..': will send the oEngineerToBuild to be recorded as part of the GE template, iTeam='..iTeam..'; P'..iPlateau..'Z'..iLandZone..'T'..iTableRef..' time='..GetGameTimeSeconds()) end
                RecordEngineerAsPartofGameEnderTemplate(oEngineerToBuild, iPlateau, iLandZone, iTableRef, nil, false)
                --oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTableRef}
            end --Redundancy


            --Check for blocking experimentals under construction and assist these if we already have a number of shields
            if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEShieldUnits]) == false then
                local bHaveUnderConstructionShields = false
                local iConstructedShieldCount = 0
                for iShield, oShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                    if AiBotUnitInfo.IsUnitValid(oShield) then
                        if oShield:GetFractionComplete() < 1 then
                            bHaveUnderConstructionShields = true
                        else
                            iConstructedShieldCount = iConstructedShieldCount + 1
                        end
                    end
                end
                local oBlockingExperimentalToAssist
                if not(bHaveUnderConstructionShields) and iConstructedShieldCount >= 4 then
                    local tBlockingUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tLocationToBuild, iBuildingSize * 0.5 - 0.3)) --tried with -0.7 but wouldnt pickup on SAM that was just inside the shield build area
                    if AiBotUtilities.IsTableEmpty(tBlockingUnits) == false then
                        local tBlockingMobileExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel, tBlockingUnits)
                        if AiBotUtilities.IsTableEmpty(tBlockingMobileExperimentals) == false then
                            for iBlockingExp, oBlockingExp in tBlockingMobileExperimentals do
                                if oBlockingExp:GetFractionComplete() < 1 then
                                    oBlockingExperimentalToAssist = oBlockingExp
                                    break
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': oBlockingExperimentalToAssist='..(oBlockingExperimentalToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBlockingExperimentalToAssist) or 'nil')) end
                if oBlockingExperimentalToAssist then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a blocking experimental we will assist to free up build area, oBlockingExperimentalToAssist='..oBlockingExperimentalToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBlockingExperimentalToAssist)..'; fraction complete='..oBlockingExperimentalToAssist:GetFractionComplete()) end
                    GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTableRef, oBlockingExperimentalToAssist, nil)
                end
            end
        end
    else
        tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] = (tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] or 0) + 1
        if tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] >= 15 and oFirstEngineer then
            --Reevaluate what gameender or T3 arti unit we want
            if bDebugMessages == true then LOG(sFunctionRef..': Have been waiting '..tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer]..' cycles for an engineer so will reassess the GE category') end
            GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTableRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer)

            tTableRef[AiBotMap.subrefiCyclesWaitingForEngineer] = 0
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bTriedBuildingSomething
end

function GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTableRef, oUnit, iOptionalMax)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GETemplateAssistUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bClearAllEngineers = false --returns true if we have flagged to clear all available engineers (as a redundancy since setting the table to nil doesnt seem to work)

    local iCurEntry = 0
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, assisting oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with fraction complete='..oUnit:GetFractionComplete()..'; iOptionalMax='..(iOptionalMax or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if oUnit:GetFractionComplete() < 1 then
        if iOptionalMax then
            --Check if any existing engineers are building the unit, and if so then have the first one of them as the first engineer (so we keep building with the unit that started construction)
            --local tiEngineersToRemove = {}
            --local tiEngineerByFactionToRemove = {}
            for iEngineer, oEngineer in tAvailableEngineers do
                if oEngineer:GetFocusUnit() == oUnit then
                    AiBotOrders.IssueTrackedRepair(oEngineer, oUnit, false, 'GEFRepT'..iTableRef, false)
                    iCurEntry = iCurEntry + 1
                    if iCurEntry == 1 then oEngineer[refbPrimaryBuilder] = true else oEngineer[refbPrimaryBuilder] = false end
                    if not(oEngineer[AiBotBuilding.reftArtiTemplateRefs][3] == iTableRef) or not( oEngineer[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                        RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTableRef, nil, false)
                        --oEngineer[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTableRef}
                    end
                    --table.insert(tiEngineersToRemove, iEngineer)
                    if bDebugMessages == true then LOG(sFunctionRef..': First engi given order to repair='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; removing from table of available engineers, P'..iPlateau..'L'..iLandZone..'T'..iTableRef..' Time='..GetGameTimeSeconds()) end
                    table.remove(tAvailableEngineers, iEngineer)
                    local iFactionRef = AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)
                    if AiBotUtilities.IsTableEmpty( tAvailableT3EngineersByFaction[iFactionRef]) == false then
                        for iFactionEngi, oFactionEngi in tAvailableT3EngineersByFaction[iFactionRef] do
                            if oFactionEngi == oEngineer then
                                --if not(tiEngineerByFactionToRemove[iFactionRef]) then tiEngineerByFactionToRemove[iFactionRef] = {} end
                                --table.insert(tiEngineerByFactionToRemove[iFactionRef], iFactionEngi)
                                table.remove(tAvailableT3EngineersByFaction[iFactionRef], iFactionEngi)
                                break
                            end
                        end
                    end
                    break
                end
            end
        end
        if not(iOptionalMax) or iCurEntry < iOptionalMax then
            for iEngineer, oEngineer in tAvailableEngineers do
                AiBotOrders.IssueTrackedRepair(oEngineer, oUnit, false, 'GERepT'..iTableRef, false)
                if not(oEngineer[AiBotBuilding.reftArtiTemplateRefs][3] == iTableRef) or not( oEngineer[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                    --oEngineer[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTableRef}
                    RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTableRef, nil, false)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Just given repair order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; iCurEntry='..iCurEntry..'; iOptioanlMax='..(iOptionalMax or 'nil')..'; P'..iPlateau..'L'..iLandZone..'T'..iTableRef..' Time='..GetGameTimeSeconds()) end
                if iOptionalMax then
                    iCurEntry = iCurEntry + 1
                    if iCurEntry == 1 then oEngineer[refbPrimaryBuilder] = true else oEngineer[refbPrimaryBuilder] = false end
                    if iCurEntry >= iOptionalMax then break end
                end
            end
        end
    else
        for iEngineer, oEngineer in tAvailableEngineers do
            AiBotOrders.IssueTrackedGuard(oEngineer, oUnit, false, 'GEAssT'..iTableRef, false)
            if bDebugMessages == true then LOG(sFunctionRef..': Just given guard order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; iCurEntry='..iCurEntry..'; iOptioanlMax='..(iOptionalMax or 'nil')..'; P'..iPlateau..'L'..iLandZone..'T'..iTableRef..' Time='..GetGameTimeSeconds()) end
            if iOptionalMax then
                iCurEntry = iCurEntry + 1
                if iCurEntry == 1 then oEngineer[refbPrimaryBuilder] = true else oEngineer[refbPrimaryBuilder] = false end
                if iCurEntry >= iOptionalMax then break end
            end
        end
    end
    if iOptionalMax then
        for iCurEngi = iCurEntry, 1, -1 do
            local oEngineer = tAvailableEngineers[iCurEngi]
            local iFactionRef = AiBotUnitInfo.GetFactionNumberFromBlueprint(oEngineer.UnitId)
            if AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction[iFactionRef]) == false then
                for iFactionEngi, oFactionEngi in tAvailableT3EngineersByFaction[iFactionRef] do
                    if oFactionEngi == oEngineer then
                        table.remove(tAvailableT3EngineersByFaction[iFactionRef], iFactionEngi)
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Just removed engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' from table of available engineers, P'..iPlateau..'L'..iLandZone..'T'..iTableRef..' at time='..GetGameTimeSeconds()) end
            table.remove(tAvailableEngineers, iCurEngi)
        end
    else
        tAvailableEngineers = nil
        tAvailableT3EngineersByFaction = nil
        bClearAllEngineers = true
        if bDebugMessages == true then LOG('Setting all available engineers to nil, P='..iPlateau..'L'..iLandZone..' TR='..iTableRef..'; Time='..GetGameTimeSeconds()..'; bClearAllEngineers='..tostring(bClearAllEngineers or false)) end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, bClearAllEngineers='..tostring(bClearAllEngineers or false)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bClearAllEngineers
end

function ConsiderResettingGEEngineerJustBeforeGivingNewOrder(oEngineerToBuild, tLocationToBuild, sBPToBuild)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderResettingGEEngineerJustBeforeGivingNewOrder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to reset refiGETemplateTimeTryingToBuild to 0 for engineer '..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)) end
    oEngineerToBuild[refiGETemplateTimeTryingToBuild] = (oEngineerToBuild[refiGETemplateTimeTryingToBuild] or 0) + 1
    if oEngineerToBuild[refiGETemplateTimeTryingToBuild] >= 15 and (not(oEngineerToBuild[AiBotUnitInfo.refbSpecialMicroActive]) or oEngineerToBuild[refiGETemplateTimeTryingToBuild] >= 50) then
        AiBotOrders.IssueTrackedClearCommands(oEngineerToBuild)
        oEngineerToBuild[refiGETemplateTimeTryingToBuild] = 0
        if bDebugMessages == true then LOG(sFunctionRef..': Cleared orders for the engineer, special micro post clearing='..tostring(oEngineerToBuild[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
    elseif oEngineerToBuild[refiGETemplateTimeTryingToBuild] >= 4 and (AiBotOrders.bDontConsiderCombinedArmy or oEngineerToBuild.AiBotActive) then
        --Check for blocking mobile units where we are trying to build that are owend by a different AiBotAI so we can transfer ownership over
        local rBuildArea = AiBotUtilities.GetRectAroundLocation(tLocationToBuild, AiBotUnitInfo.GetBuildingSize(sBPToBuild) * 0.5)
        local tBlockingUnits = GetUnitsInRect(rBuildArea)
        if bDebugMessages == true then LOG(sFunctionRef..': Checking for units in blocking area, will draw, is table of blocking units empty='..tostring(AiBotUtilities.IsTableEmpty(tBlockingUnits))) AiBotUtilities.DrawRectangle(rBuildArea) end
        if AiBotUtilities.IsTableEmpty(tBlockingUnits) == false then
            local tMobileLandUnitsInRect = EntityCategoryFilterDown(categories.MOBILE * categories.LAND,tBlockingUnits)
            if AiBotUtilities.IsTableEmpty(tMobileLandUnitsInRect) == false then
                local oBrainWanted = oEngineerToBuild:GetAIBrain()
                local tUnitsToTransfer = {}
                for iUnit, oUnit in tMobileLandUnitsInRect do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering blocking mobile unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit brain='..oUnit:GetAIBrain().Nickname..'; Brain wanted='..oBrainWanted.Nickname) end
                    if not(oUnit:GetAIBrain() == oBrainWanted) and oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() == 1 and not(oUnit:IsUnitState('Attached')) and (AiBotOrders.bDontConsiderCombinedArmy or oUnit.AiBotActive) then
                        table.insert(tUnitsToTransfer, oUnit)
                    end
                end
                if AiBotUtilities.IsTableEmpty(tUnitsToTransfer) == false then
                    AiBotTeam.TransferUnitsToPlayer(tUnitsToTransfer, oBrainWanted:GetArmyIndex(), false)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GETemplateStartBuildingShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, iMaxShieldsToTryAndBuild, iOptionalMaxEngiPerAction, bOnlyGetT3)
    --Decide on the arti blueprint we want to try and build; priority to use:
    --Aeon (Paragon and T3 arti) > Seraphim (Yolona) > UEF (Mavor) > Cybran (Scathis)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GETemplateStartBuildingShield'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bTriedBuildingSomething = false

    local sShieldToBuild = nil
    local aiBrain
    local oEngineerToBuild
    local iShieldCategoryToBuild
    if bOnlyGetT3 then
        iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.TECH3 * categories.SIZE12 --e.g. for mods that add experimental shields we are unlikely to want more than 2 exp shields
    else
        iShieldCategoryToBuild = AiBotUnitInfo.refCategoryFixedShield * categories.SIZE12
    end

    local iFactionRef
    if oFirstSeraphim then
        aiBrain = oFirstSeraphim:GetAIBrain()
        iFactionRef = AiBotUnitInfo.refFactionSeraphim
        oEngineerToBuild = tAvailableT3EngineersByFaction[iFactionRef][1]
        if oEngineerToBuild then
            sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild,nil,nil,nil,nil,nil,6)
        end

    end
    if not(sShieldToBuild) then
        if oFirstUEF then
            aiBrain = oFirstUEF:GetAIBrain()
            iFactionRef = AiBotUnitInfo.refFactionUEF
            oEngineerToBuild = tAvailableT3EngineersByFaction[iFactionRef][1]
            if oEngineerToBuild then
                sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild,nil,nil,nil,nil,nil,6)
            end
        end
        if not(sShieldToBuild) then
            if oFirstAeon then
                aiBrain = oFirstAeon:GetAIBrain()
                iFactionRef = AiBotUnitInfo.refFactionAeon
                oEngineerToBuild = tAvailableT3EngineersByFaction[iFactionRef][1]
                if oEngineerToBuild then
                    sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild,nil,nil,nil,nil,nil,6)
                end
            end
            if not(sShieldToBuild) then
                if oFirstCybran then
                    aiBrain = oFirstCybran:GetAIBrain()
                    iFactionRef = AiBotUnitInfo.refFactionCybran
                    oEngineerToBuild = tAvailableT3EngineersByFaction[iFactionRef][1]
                    if oEngineerToBuild then
                        sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild,nil,nil,nil,nil,nil,6)
                    end
                end
                if not(sShieldToBuild) then
                    if oFirstEngineer then
                        aiBrain = oFirstEngineer:GetAIBrain()
                        oEngineerToBuild = oFirstEngineer
                        if oEngineerToBuild then
                            sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild,nil,nil,nil,nil,nil,6)
                            --A large shield is better than no shield?
                            if not(sShieldToBuild) then sShieldToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iShieldCategoryToBuild, oEngineerToBuild) end
                        end
                    end
                end
            end
        end
    end
    local tEngisOfDesiredFaction = tAvailableT3EngineersByFaction[iFactionRef]
    if bDebugMessages == true then LOG(sFunctionRef..': dealing with iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; sShieldToBuild='..(sShieldToBuild or 'nil')..'; oEngineerToBuild='..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')) end
    if sShieldToBuild and oEngineerToBuild then
        local sLastBlueprint = oEngineerToBuild[AiBotOrders.reftiLastOrders][oEngineerToBuild[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil'
        if sLastBlueprint and not(sLastBlueprint == sShieldToBuild) and EntityCategoryContains(iShieldCategoryToBuild, sLastBlueprint) then
            sShieldToBuild = sLastBlueprint
            if bDebugMessages == true then LOG(sFunctionRef..': engi last blueprint was different, but also met the desired shield category, sLastBlueprint='..sLastBlueprint..'; so will change what to build to this') end
        end


        --Scenarios where we have 2 arti locations but our shield radius is too small - dont want to build on the 7th shield location, but instead want to build on the arti location
        local bUseArtiInsteadOfLastShieldLocation = false
        local tbShieldEntriesNotToConsider = {}

        if __blueprints[sShieldToBuild].Defense.Shield.ShieldSize <= 37 and table.getn(tTableRef[AiBotMap.subrefGEArtiLocations]) >= 2 and not(oFirstUEF) and not(oFirstSeraphim) then
            --Only want to build aeon/cybran shields in the 'middle' locations (where they cover both game-enders and all other shields), outer shields will need to be UEF/Seraphim
            tbShieldEntriesNotToConsider = {[1]=true,[2]=true,[5]=true,[6]=true,[8]=true}
            --Flag we want UEF and sera engineers
            if not(tLZTeamData[AiBotMap.subreftbBPByFactionWanted]) then tLZTeamData[AiBotMap.subreftbBPByFactionWanted] = {} end
            if not(oFirstUEF) then
                tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionUEF] = true
                if bDebugMessages == true then LOG(sFunctionRef..': Flagging that we want UEF engineers for zone '..iLandZone) end
            end
            if not(oFirstSeraphim) then
                tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionSeraphim] = true
                if bDebugMessages == true then LOG(sFunctionRef..': Flagging that we want Seraphim engineers for zone '..iLandZone) end
            end

            --Look for a factory to build the engineers that we want
            if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false then
                for iArti, oArti in tTableRef[AiBotMap.subrefGEArtiUnits] do
                    if not(AiBotUnitInfo.IsUnitValid(oArti[AiBotBuilding.refoNearbyFactoryOfFaction])) then
                        AiBotBuilding.RecordNearbyFactoryForShieldEngineers(oArti, { [AiBotUnitInfo.refFactionUEF] = true, [AiBotUnitInfo.refFactionSeraphim] = true })
                    end
                    break
                end
            end

            --Build in arti location if we lack UEF and Seraphim factories
            if oEngineerToBuild then
                local iLandSubteam = oEngineerToBuild:GetAIBrain().AiBotLandSubteam
                local tFactoriesByTech = AiBotTeam.tLandSubteamData[iLandSubteam][AiBotTeam.subrefFactoriesByTypeFactionAndTech]
                if (tFactoriesByTech[AiBotUnitInfo.refFactionUEF][1] or 0) == 0 and (tFactoriesByTech[AiBotUnitInfo.refFactionUEF][2] or 0) == 0 and  (tFactoriesByTech[AiBotUnitInfo.refFactionUEF][3] or 0) == 0
                        and (tFactoriesByTech[AiBotUnitInfo.refFactionSeraphim][1] or 0) == 0 and (tFactoriesByTech[AiBotUnitInfo.refFactionSeraphim][2] or 0) == 0 and  (tFactoriesByTech[AiBotUnitInfo.refFactionSeraphim][3] or 0) == 0 then
                    bUseArtiInsteadOfLastShieldLocation = true
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Our shield size is below 37 and we have 2+ arti locations in this zone, so will consider 1 less hsield entry and flag we want UEF or seraphim engineers for this zone, tbShieldEntriesNotToConsider='..repru(tbShieldEntriesNotToConsider)) end
        end

        --Are any of the shield locations available? If not then need to reclaim blocking buildings
        local iBuildingSize = AiBotUnitInfo.GetBuildingSize(sShieldToBuild)
        local tLocationsToBuild = {}
        local iLocationsToBuild = 0
        if not(iMaxShieldsToTryAndBuild) then iMaxShieldsToTryAndBuild = 1 end
        for iEntry, tBuildLocation in tTableRef[AiBotMap.subrefGEShieldLocations] do
            if not(tbShieldEntriesNotToConsider[iEntry]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering shield location '..repru(tBuildLocation)..'; can we build a shield here='..tostring(aiBrain:CanBuildStructureAt(sShieldToBuild, tBuildLocation))) end
                if aiBrain:CanBuildStructureAt(sShieldToBuild, tBuildLocation) then
                    table.insert(tLocationsToBuild, {tBuildLocation[1], tBuildLocation[2],tBuildLocation[3]})
                    iLocationsToBuild = iLocationsToBuild + 1
                    if iLocationsToBuild >= iMaxShieldsToTryAndBuild then
                        break
                    end
                else
                    if bDebugMessages == true then  AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tBuildLocation, 3), 2) end
                end
            end
        end
        if bUseArtiInsteadOfLastShieldLocation and AiBotUtilities.IsTableEmpty(tLocationsToBuild) then
            --Consider the second arti location
            if aiBrain:CanBuildStructureAt(sShieldToBuild, tTableRef[AiBotMap.subrefGEArtiLocations][2]) then
                table.insert(tLocationsToBuild, {tTableRef[AiBotMap.subrefGEArtiLocations][2][1], tTableRef[AiBotMap.subrefGEArtiLocations][2][2],tTableRef[AiBotMap.subrefGEArtiLocations][2][3]})
                iLocationsToBuild = iLocationsToBuild + 1
            end
        end

        local tFirstLocationBuiltAt

        if AiBotUtilities.IsTableEmpty(tLocationsToBuild) == false then
            --First assign the first engineer

            for iEngineer, oEngineer in tAvailableEngineers do
                if oEngineer == oEngineerToBuild then
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to build the shield') end
                    table.remove(tAvailableEngineers, iEngineer)
                    break
                end
            end
            if AiBotUtilities.IsTableEmpty(tEngisOfDesiredFaction) == false then
                for iEngineer, oEngineer in tEngisOfDesiredFaction do
                    if oEngineer == oEngineerToBuild then
                        table.remove(tEngisOfDesiredFaction, iEngineer)
                        break
                    end
                end
            end
            local tMoveLocation = GetLocationToMoveForConstruction(oEngineerToBuild, tLocationsToBuild[1], sShieldToBuild, 0, false)
            if tMoveLocation and (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) <= 10 then
                if bDebugMessages == true then LOG(sFunctionRef..': GE S Telling engineer '..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..' to move to '..repru(tMoveLocation)..' and then build '..sShieldToBuild..' at location '..repru(tLocationsToBuild[1])) end
                AiBotOrders.IssueTrackedMoveAndBuild(oEngineerToBuild, tLocationsToBuild[1], sShieldToBuild, tMoveLocation, 1, false, 'GEMBShT'..iTemplateRef)
                if AiBotUtilities.GetDistanceBetweenPositions(oEngineerToBuild:GetPosition(), tMoveLocation) <= 2 then oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] = (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) + 1 end
                bTriedBuildingSomething = true
            else
                if bDebugMessages == true then LOG(sFunctionRef..': GE S Telling engineer '..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..' to build '..sShieldToBuild..' at build location '..repru(tLocationsToBuild[1])..'; oEngineerToBuild[refiGETemplateTimeTryingToBuild]='..(oEngineerToBuild[refiGETemplateTimeTryingToBuild] or 'nil')) end

                AiBotOrders.IssueTrackedBuild(oEngineerToBuild, tLocationsToBuild[1], sShieldToBuild, false, 'GEBArt')
                bTriedBuildingSomething = true

            end
            if oEngineerToBuild[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineerToBuild, false) end
            oEngineerToBuild[refbPrimaryBuilder] = true
            tFirstLocationBuiltAt = {tLocationsToBuild[1][1], tLocationsToBuild[1][2], tLocationsToBuild[1][3]}
            if bDebugMessages == true then LOG(sFunctionRef..': Just sent build order for oEngineerToBuild='..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..'; oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs])..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTemplateRef='..iTemplateRef..'; if dif will update engineer') end
            if not(oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][3] == iTemplateRef) or not( oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                if bDebugMessages == true then LOG(sFunctionRef..': Updated engineer zone and template ref') end
                --oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                RecordEngineerAsPartofGameEnderTemplate(oEngineerToBuild, iPlateau, iLandZone, iTemplateRef, nil, false)
            end --Redundancy
            table.remove(tLocationsToBuild, 1)

            --Now try and build at the other locations if have any
            local iMaxCount = iMaxShieldsToTryAndBuild + 1
            local iCurLoopCount = 0
            if AiBotUtilities.IsTableEmpty(tEngisOfDesiredFaction) == false and AiBotUtilities.IsTableEmpty(tLocationsToBuild) == false then
                local iLastEngi = table.getn(tEngisOfDesiredFaction)
                local iLastLocation = table.getn(tLocationsToBuild)
                while AiBotUtilities.IsTableEmpty(tEngisOfDesiredFaction) == false and AiBotUtilities.IsTableEmpty(tLocationsToBuild) == false do
                    iCurLoopCount = iCurLoopCount + 1
                    if iCurLoopCount > iMaxCount then AiBotUtilities.ErrorHandler('Infinite loop protection') break end
                    tMoveLocation = GetLocationToMoveForConstruction(tEngisOfDesiredFaction[iLastEngi], tLocationsToBuild[iLastLocation], sShieldToBuild, 0, false)
                    if tMoveLocation and (tEngisOfDesiredFaction[iLastEngi][AiBotConditions.refiEngineerStuckCheckCount] or 0) <= 10 then
                        if bDebugMessages == true then LOG(sFunctionRef..': GE Extra Telling engineer '..tEngisOfDesiredFaction[iLastEngi].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngisOfDesiredFaction[iLastEngi])..' to move to '..repru(tMoveLocation)..' and then build '..sShieldToBuild..' at location '..repru(tLocationsToBuild[iLastLocation])) end
                        AiBotOrders.IssueTrackedMoveAndBuild(tEngisOfDesiredFaction[iLastEngi], tLocationsToBuild[iLastLocation], sShieldToBuild, tMoveLocation, 1, false, 'GEMEBShT'..iTemplateRef)
                        if AiBotUtilities.GetDistanceBetweenPositions(tEngisOfDesiredFaction[iLastEngi]:GetPosition(), tMoveLocation) <= 2 then tEngisOfDesiredFaction[iLastEngi][AiBotConditions.refiEngineerStuckCheckCount] = (tEngisOfDesiredFaction[iLastEngi][AiBotConditions.refiEngineerStuckCheckCount] or 0) + 1 end
                        bTriedBuildingSomething = true
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': GE Extra Telling engineer '..tEngisOfDesiredFaction[iLastEngi].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngisOfDesiredFaction[iLastEngi])..' to build '..sShieldToBuild..' at build location '..repru(tLocationsToBuild[iLastLocation])) end
                        ConsiderResettingGEEngineerJustBeforeGivingNewOrder(oEngineerToBuild, tLocationsToBuild[iLastLocation], sShieldToBuild)
                        AiBotOrders.IssueTrackedBuild(tEngisOfDesiredFaction[iLastEngi], tLocationsToBuild[iLastLocation], sShieldToBuild, false, 'GEEBSh'..iTemplateRef)
                        bTriedBuildingSomething = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Just sent a build order for oEngineerToBuild='..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..'; oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs]='..repru(oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs])..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTemplateRef='..iTemplateRef..'; if dif will update engineer') end
                    if not(tEngisOfDesiredFaction[iLastEngi][AiBotBuilding.reftArtiTemplateRefs][3] == iTemplateRef) or not( tEngisOfDesiredFaction[iLastEngi][AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Just updated the recorded arti template ref for the engineer building a shield, tEngisOfDesiredFaction[iLastEngi]='..tEngisOfDesiredFaction[iLastEngi].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngisOfDesiredFaction[iLastEngi])) end
                        --tEngisOfDesiredFaction[iLastEngi][AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                        RecordEngineerAsPartofGameEnderTemplate(tEngisOfDesiredFaction[iLastEngi], iPlateau, iLandZone, iTemplateRef, nil, false)
                    end --Redundancy
                    for iEngineer, oEngineer in tAvailableEngineers do
                        if oEngineer == tEngisOfDesiredFaction[iLastEngi] then
                            table.remove(tAvailableEngineers, iEngineer)
                            break
                        end
                    end
                    table.remove(tEngisOfDesiredFaction, iLastEngi)
                    iLastEngi = iLastEngi - 1
                    table.remove(tLocationsToBuild, iLastLocation)
                    iLastLocation = iLastLocation - 1
                end
            end

        end
        if bDebugMessages == true then LOG(sFunctionRef..': Will consider reclaiming blocking units if still have avaialble engis, Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; iLocationsToBuild='..iLocationsToBuild..'; iMaxShieldsToTryAndBuild='..iMaxShieldsToTryAndBuild..'; bUseArtiInsteadOfLastShieldLocation='..tostring(bUseArtiInsteadOfLastShieldLocation or false)) end
        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and iLocationsToBuild < iMaxShieldsToTryAndBuild and (iLocationsToBuild == 0 or not(bUseArtiInsteadOfLastShieldLocation)) then
            --Look to reclaim buildings that are blocking us with remaining engineers, unless they are very high value buildings
            AiBotProfiler.FunctionProfiler(sFunctionRef..'ReclaimBlockers', AiBotProfiler.refProfilerStart)
            local iLowestValueBlockingBuildings = 150000 --basic threshold to prevent reclaiming really high value buildings
            local tLowestValueBlockingBuildings, iCurValueBlockingBuildings, iLowestValueRef
            local bHavePotentiallyValidLocation = false
            local tUnitsToConsiderReclaiming
            local iXDif, iZDif

            function ConsiderUnitsToReclaim(tBuildLocation, iEntry)
                local tBlockingUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tBuildLocation, iBuildingSize * 0.5 - 0.3))
                if not(tBlockingUnits) then
                    AiBotUtilities.ErrorHandler('Tempalte location cant be built on but has no units in it', true)
                    if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry]) then
                        if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount] = {} end
                        tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = 0
                    end
                    tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] + 1
                else
                    local tBlockingUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryWall, tBlockingUnits)
                    if AiBotUtilities.IsTableEmpty(tBlockingUnits) then
                        AiBotUtilities.ErrorHandler('Template location cant be built on but has no buildings in it', true)
                        if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry]) then
                            if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount] = {} end
                            tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = 0
                        end
                        tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] + 1
                    else
                        tUnitsToConsiderReclaiming = {}
                        for iUnit, oUnit in tBlockingUnits do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Location '..repru(tBuildLocation)..' has a blocking unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' with radius='..AiBotUnitInfo.GetBuildingSize(oUnit.UnitId)*0.5..'; Is unit oUnit[AiBotBuilding.reftArtiTemplateRefs] nil='..tostring(oUnit[AiBotBuilding.reftArtiTemplateRefs]==nil)) end
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) then
                                    --Do nothing
                                    tUnitsToConsiderReclaiming = nil
                                    break
                                elseif oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                                    --Do nothing; abort if the unit is more than .5 within the margin
                                    local bAbort = true
                                    local iUnitRadius = AiBotUnitInfo.GetBuildingSize(oUnit.UnitId) * 0.5

                                    iXDif = oUnit:GetPosition()[1] - tBuildLocation[1]
                                    if iXDif < 0 then iXDif = iXDif - iUnitRadius
                                    else iXDif = iXDif + iUnitRadius end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Blocking unit XDif='..iXDif) end
                                    if math.abs(iXDif) >= 5.25 then
                                        bAbort = false
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit might not actually be blocking so will continue search') end
                                    else
                                        iZDif = oUnit:GetPosition()[3] - tBuildLocation[3]
                                        if iZDif < 0 then iZDif = iZDif - iUnitRadius
                                        else iZDif = iZDif + iUnitRadius end

                                        if bDebugMessages == true then LOG(sFunctionRef..': Blocking unit ZDif='..iZDif) end
                                        if math.abs(iZDif) >= 5.25 then
                                            --Assume unit isnt actually a true blocking unit and ignore
                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit might not actually be blocking so will continue search') end
                                            bAbort = false
                                        end
                                    end

                                    if bAbort then
                                        tUnitsToConsiderReclaiming = nil
                                        break
                                    end
                                else
                                    local bShieldToAdd = false
                                    --e.g. has another engineer unrelated to template logic gone and built in our template, but managed to build in the right place?
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield - categories.TECH2, oUnit.UnitId) then
                                        iXDif = math.abs(oUnit:GetPosition()[1] - tBuildLocation[1])
                                        if iXDif <= 0.5 or (iXDif >= 2.5 and iXDif <= 3.5) then
                                            iZDif = math.abs(oUnit:GetPosition()[3] - tBuildLocation[3])
                                            if iZDif <= 0.5 or (iZDif >= 2.5 and iZDif <= 3.5) then
                                                bShieldToAdd = true
                                            end
                                        end
                                    end
                                    if bShieldToAdd then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dealing with a fixed hsield that is in the right location to form part of our logic so will add, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'P'..iPlateau..'L'..iLandZone..'T'..iTemplateRef) end
                                        oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                                        --Check not already in the table (redundancy)
                                        local bAlreadyRecorded = false
                                        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEShieldUnits]) == false then
                                            for iRecordedShield, oRecordedShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                                                if oRecordedShield == oUnit then
                                                    bAlreadyRecorded = true
                                                    break
                                                end
                                            end
                                        end
                                        if not(bAlreadyRecorded) then
                                            table.insert(tTableRef[AiBotMap.subrefGEShieldUnits], oUnit)
                                        end

                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of units to reclaim') end
                                        table.insert(tUnitsToConsiderReclaiming, oUnit)
                                    end
                                end
                                end
                        end
                        if AiBotUtilities.IsTableEmpty(tUnitsToConsiderReclaiming) == false then
                            iCurValueBlockingBuildings = AiBotUnitInfo.GetMassCostOfUnits(tUnitsToConsiderReclaiming)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurValueBlockingBuildings='..iCurValueBlockingBuildings..'; iLowestValueBlockingBuildings='..iLowestValueBlockingBuildings) end
                            if iCurValueBlockingBuildings < iLowestValueBlockingBuildings then
                                iLowestValueBlockingBuildings = iCurValueBlockingBuildings
                                tLowestValueBlockingBuildings = tUnitsToConsiderReclaiming
                                bHavePotentiallyValidLocation = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a potentially valid location for shields so will reclaim if it remains the lowest value of blocking units') end
                            end
                        else
                            if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry]) then
                                if not(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount] = {} end
                                if bDebugMessages == true then LOG(sFunctionRef..': tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount]='..repru(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount])..'; iEntry='..iEntry..'; Is tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount] nil='..tostring(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount] == nil)) end
                                tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = 0
                            end
                            tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] + 1
                        end
                    end
                end
            end

            for iEntry, tBuildLocation in tTableRef[AiBotMap.subrefGEShieldLocations] do
                if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to consider tBuildLocation='..repru(tBuildLocation)..'; iEntry='..iEntry..'; tbShieldEntriesNotToConsider[iEntry]='..tostring(tbShieldEntriesNotToConsider[iEntry] or false)..'; (tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] or 0)='..(tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] or 0)) end
                if not(tbShieldEntriesNotToConsider[iEntry]) then
                    if (tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][iEntry] or 0) <= 5 then
                        ConsiderUnitsToReclaim(tBuildLocation, iEntry)
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef..'ReclaimBlockers', AiBotProfiler.refProfilerEnd)
            if not(bHavePotentiallyValidLocation) and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiLocations][2]) == false then ConsiderUnitsToReclaim(tTableRef[AiBotMap.subrefGEArtiLocations][2], 2) end
            if bHavePotentiallyValidLocation then
                --Get all engineers to reclaim the units here
                local oUnitToReclaim
                local iCtrlKdUnits = 0
                for iUnit, oUnit in tLowestValueBlockingBuildings do
                    if oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() == 1 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryVolatile + categories.COMMAND, oUnit.UnitId)) then
                        --CtrlK instead of reclaiming
                        AiBotOrders.IssueTrackedKillUnit(oUnit)
                        iCtrlKdUnits = iCtrlKdUnits + 1
                    elseif not(oUnitToReclaim) then oUnitToReclaim = oUnit
                    end
                end
                local iEngisGivenReclaimOrder = 0
                if oUnitToReclaim then


                    CheckAndClearEngineersConstructingTargetUnit(oUnitToReclaim, tLZTeamData, iPlateau, iLandZone)
                    for iEngineer, oEngineer in tAvailableEngineers do
                        if bDebugMessages == true then LOG(sFunctionRef..': Giving order to engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to reclaim the blocking unit') end
                        if oEngineer[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineer, false) end
                        AiBotOrders.IssueTrackedReclaim(oEngineer, oUnitToReclaim, false, 'GESRecl', false)
                        iEngisGivenReclaimOrder = iEngisGivenReclaimOrder + 1
                        if iOptionalMaxEngiPerAction and iEngisGivenReclaimOrder >= iOptionalMaxEngiPerAction then break end
                        bTriedBuildingSomething = true
                    end
                    if iOptionalMaxEngiPerAction then
                        for iRemoveCount = 1, iEngisGivenReclaimOrder do
                            local oEngiToRemove = tAvailableEngineers[1]
                            if AiBotUtilities.IsTableEmpty(tEngisOfDesiredFaction) == false then
                                for iFactionEngi, oFactionEngi in tEngisOfDesiredFaction do
                                    if oFactionEngi == oEngiToRemove then
                                        table.remove(tEngisOfDesiredFaction, iFactionEngi)
                                        break
                                    end
                                end
                            end
                            table.remove(tAvailableEngineers, 1)
                        end
                    else
                        tAvailableEngineers = nil
                        tEngisOfDesiredFaction = nil
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Want to create space for shield by reclaiming unit '..(oUnitToReclaim.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToReclaim) or 'nil')..'; bTriedBuildingSomething='..tostring(bTriedBuildingSomething)..'; iEngisGivenReclaimOrder='..iEngisGivenReclaimOrder..'; Is tAvailableEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; iCtrlKdUnits='..iCtrlKdUnits) end
            end
        else
            if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                local iEngisGivenOrder = 1
                if not(iOptionalMaxEngiPerAction) or iEngisGivenOrder < iOptionalMaxEngiPerAction then
                    --Get every other engineer to assist this engineer
                    local iRemainingEngisGivenGuard = 0
                    for iEngineer, oEngineer in tAvailableEngineers do
                        if oEngineer:CanBuild(sShieldToBuild) then
                            AiBotOrders.IssueTrackedBuild(oEngineer, tFirstLocationBuiltAt, sShieldToBuild, false, 'GEXtraBS'..iTemplateRef)
                            if bDebugMessages == true then LOG(sFunctionRef..': Just sent a build order for negineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to build shield '..sShieldToBuild..'; iLandZone='..iLandZone..'; iTemplateRef='..iTemplateRef) end
                            if not(oEngineer[AiBotBuilding.reftArtiTemplateRefs][3] == iTemplateRef) or not( oEngineer[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Just updated the recorded arti template ref for the backup engineer building a shield, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
                                --oEngineer[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                                RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTemplateRef, nil, false)
                            end --Redundancy
                            bTriedBuildingSomething = true
                        else
                            AiBotOrders.IssueTrackedGuard(oEngineer, oEngineerToBuild, false, 'GESAss', false)
                        end
                        iRemainingEngisGivenGuard = iRemainingEngisGivenGuard + 1
                        if iOptionalMaxEngiPerAction and iRemainingEngisGivenGuard + iEngisGivenOrder >= iOptionalMaxEngiPerAction then break end
                    end

                    if iOptionalMaxEngiPerAction then
                        for iRemoveCount = 1, iRemainingEngisGivenGuard do
                            local oEngiToRemove = tAvailableEngineers[1]
                            if AiBotUtilities.IsTableEmpty(tEngisOfDesiredFaction) == false then
                                for iFactionEngi, oFactionEngi in tEngisOfDesiredFaction do
                                    if oFactionEngi == oEngiToRemove then
                                        table.remove(tEngisOfDesiredFaction, iFactionEngi)
                                        break
                                    end
                                end
                            end

                            table.remove(tAvailableEngineers, 1)
                        end
                    else
                        tAvailableEngineers = nil
                        tEngisOfDesiredFaction = nil
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bTriedBuildingSomething
end

function GETemplateConsiderDefences(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, iTeam, iOptionalMaxEngiPerAction)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GETemplateConsiderDefences'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bTriedBuildingSomething = false

    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to get defences such as SMD, iLandZone='..iLandZone..'; iTemplateRef='..iTemplateRef..'; Do we have active shield monitor='..tostring(tTableRef[AiBotMap.subrefGEbActiveShieldMonitor])) end

    if tTableRef[AiBotMap.subrefGEbActiveShieldMonitor] or (not(AiBotBuilding.bShieldsCanDischarge) and tTableRef[AiBotMap.subrefGEShieldUnits] and table.getn(tTableRef[AiBotMap.subrefGEShieldUnits]) >= 5) then
        function BuildDefensiveUnit(iCategoryWanted, tPotentialBuildLocations, bOptionalRemoveInvalidPotentialBuildLocations)
            local oEngineerToBuild
            for iFaction, tEngineers in tAvailableT3EngineersByFaction do
                for iEngineer, oEngineer in tEngineers do
                    oEngineerToBuild = oEngineer
                    break
                end
                if oEngineerToBuild then
                    break
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build defensive unit, oEngineerToBuild='..(oEngineerToBuild.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild) or 'nil')) end
            if oEngineerToBuild then
                local aiBrain = oEngineerToBuild:GetAIBrain()
                local sBPToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryWanted, oEngineerToBuild)

                local sLastBlueprint = oEngineerToBuild[AiBotOrders.reftiLastOrders][oEngineerToBuild[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil'
                if sLastBlueprint and not(sLastBlueprint == sBPToBuild) and EntityCategoryContains(iCategoryWanted, sLastBlueprint) then
                    sBPToBuild = sLastBlueprint
                    if bDebugMessages == true then LOG(sFunctionRef..': engi last blueprint was different, but also met the category, sLastBlueprint='..sLastBlueprint..'; so will change what to build to this') end
                end

                local tBuildLocation
                for iPotentialLocation, tPotentialLocation in tPotentialBuildLocations do
                    tBuildLocation = {tPotentialLocation[1], tPotentialLocation[2], tPotentialLocation[3]}
                    if bDebugMessages == true then LOG(sFunctionRef..': can we build blueprint at the location='..tostring(aiBrain:CanBuildStructureAt(sBPToBuild, tBuildLocation))..'; Engineer='..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..'; sBPToBuild='..sBPToBuild..'; tBuildLocation='..repru(tBuildLocation)) end
                    if not(aiBrain:CanBuildStructureAt(sBPToBuild, tBuildLocation)) then
                        tBuildLocation = {tBuildLocation[1] + 0.5, 0, tBuildLocation[3] + 0.5}
                        tBuildLocation[2] = GetSurfaceHeight(tBuildLocation[1], tBuildLocation[3])
                        if bDebugMessages == true then LOG(sFunctionRef..': can we build at adjusted tBuildLocation='..repru(tBuildLocation)..'='..tostring(aiBrain:CanBuildStructureAt(sBPToBuild, tBuildLocation))) end
                    end
                    if aiBrain:CanBuildStructureAt(sBPToBuild, tBuildLocation) then
                        --First assign the first engineer
                        for iEngineer, oEngineer in tAvailableEngineers do
                            if oEngineer == oEngineerToBuild then
                                if bDebugMessages == true then LOG(sFunctionRef..': Setting engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to build the SMD') end
                                table.remove(tAvailableEngineers, iEngineer)
                                break
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction) == false then
                            local bRemovedFromEngiByFaction = false
                            for iFaction, tEngisOfDesiredFaction in tAvailableT3EngineersByFaction do
                                for iEngineer, oEngineer in tEngisOfDesiredFaction do
                                    if oEngineer == oEngineerToBuild then
                                        table.remove(tEngisOfDesiredFaction, iEngineer)
                                        bRemovedFromEngiByFaction = true
                                        break
                                    end
                                end
                                if bRemovedFromEngiByFaction then break end
                            end
                        end

                        local tMoveLocation = GetLocationToMoveForConstruction(oEngineerToBuild, tBuildLocation, sBPToBuild, 0, false)
                        if tMoveLocation and (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) <= 10 then
                            if bDebugMessages == true then LOG(sFunctionRef..': GE SMD or def Telling engineer '..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..' to move to '..repru(tMoveLocation)..' and then build '..sBPToBuild..' at location '..repru(tBuildLocation)..'; Dist from engi to build location='..AiBotUtilities.GetDistanceBetweenPositions(oEngineerToBuild:GetPosition(), tMoveLocation)..'; Engi state='..AiBotUnitInfo.GetUnitState(oEngineerToBuild)) end
                            AiBotOrders.IssueTrackedMoveAndBuild(oEngineerToBuild, tBuildLocation, sBPToBuild, tMoveLocation, 1, false, 'GESMDMB')
                            bTriedBuildingSomething = true
                            if AiBotUtilities.GetDistanceBetweenPositions(oEngineerToBuild:GetPosition(), tMoveLocation) <= 2 then oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] = (oEngineerToBuild[AiBotConditions.refiEngineerStuckCheckCount] or 0) + 1 end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': GE SMD or defence Telling engineer '..oEngineerToBuild.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToBuild)..' to build '..sBPToBuild..' at build location '..repru(tBuildLocation)..'; oEngineerToBuild[refiGETemplateTimeTryingToBuild]='..(oEngineerToBuild[refiGETemplateTimeTryingToBuild] or 'nil')) end
                            ConsiderResettingGEEngineerJustBeforeGivingNewOrder(oEngineerToBuild, tBuildLocation, sBPToBuild)
                            AiBotOrders.IssueTrackedBuild(oEngineerToBuild, tBuildLocation, sBPToBuild, false, 'GESMDB')
                            bTriedBuildingSomething = true
                        end
                        if oEngineerToBuild[AiBotUnitInfo.refbPaused] then AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oEngineerToBuild, false, nil, iTeam) end
                        oEngineerToBuild[refbPrimaryBuilder] = true
                        if not(oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][3] == iTemplateRef) or not( oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs][2] == iLandZone) then
                            --oEngineerToBuild[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                            RecordEngineerAsPartofGameEnderTemplate(oEngineerToBuild, iPlateau, iLandZone, iTemplateRef, nil, false)
                        end --Redundancy
                        break
                    end
                end
                if not(bTriedBuildingSomething) then
                    local iLowestValueBlockingBuildings = 150000 --basic threshold to prevent reclaiming really high value buildings
                    local tLowestValueBlockingBuildings, iCurValueBlockingBuildings, iLowestValueRef
                    local bHavePotentiallyValidLocation = false
                    local tUnitsToConsiderReclaiming
                    local iXDif, iZDif
                    local iBuildingSize = AiBotUnitInfo.GetBuildingSize(sBPToBuild)

                    function ConsiderUnitsToReclaim(tSearchLocation, iEntry)
                        local tBlockingUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tSearchLocation, iBuildingSize * 0.5 - 0.3))
                        if not(tBlockingUnits) then
                            AiBotUtilities.ErrorHandler('Tempalte location cant be built on but has no units in it', true)
                            if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry]) then
                                if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount] = {} end
                                tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = 0
                            end
                            tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] + 1
                        else
                            local tBlockingUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryWall, tBlockingUnits)
                            if AiBotUtilities.IsTableEmpty(tBlockingUnits) then
                                AiBotUtilities.ErrorHandler('Template location cant be built on but has no buildings in it', true)
                                if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry]) then
                                    if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount] = {} end
                                    tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = 0
                                end
                                tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] + 1
                            else
                                tUnitsToConsiderReclaiming = {}
                                for iUnit, oUnit in tBlockingUnits do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Location '..repru(tSearchLocation)..' has a blocking unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at position '..repru(oUnit:GetPosition())..' with radius='..AiBotUnitInfo.GetBuildingSize(oUnit.UnitId)*0.5..'; Is unit oUnit[AiBotBuilding.reftArtiTemplateRefs] nil='..tostring(oUnit[AiBotBuilding.reftArtiTemplateRefs]==nil)) end
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) then
                                            --Do nothing
                                            tUnitsToConsiderReclaiming = nil
                                            break
                                        elseif oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                                            --Do nothing
                                            tUnitsToConsiderReclaiming = nil
                                            break
                                        else
                                            local bUnitToAdd = false
                                            --e.g. has another engineer unrelated to template logic gone and built in our template, but managed to build in the right place?
                                            if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                                                iXDif = math.abs(oUnit:GetPosition()[1] - tSearchLocation[1])
                                                if iXDif <= 0.5 or (iXDif >= 2.5 and iXDif <= 3.5) then
                                                    iZDif = math.abs(oUnit:GetPosition()[3] - tSearchLocation[3])
                                                    if iZDif <= 0.5 or (iZDif >= 2.5 and iZDif <= 3.5) then
                                                        bUnitToAdd = true
                                                    end
                                                end
                                            end
                                            if bUnitToAdd then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Dealing with a fixed hsield that is in the right location to form part of our logic so will add, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; P'..iPlateau..'L'..iLandZone..'T'..iTemplateRef) end
                                                oUnit[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                                                tUnitsToConsiderReclaiming = nil
                                                --Check not already in the table (redundancy)
                                                local bAlreadyRecorded = false
                                                if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEShieldUnits]) == false then
                                                    for iRecordedShield, oRecordedShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                                                        if oRecordedShield == oUnit then
                                                            bAlreadyRecorded = true
                                                            break
                                                        end
                                                    end
                                                end
                                                if not(bAlreadyRecorded) then
                                                    table.insert(tTableRef[AiBotMap.subrefGEShieldUnits], oUnit)
                                                end
                                                break
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will add to table of units to reclaim') end
                                                table.insert(tUnitsToConsiderReclaiming, oUnit)
                                            end
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tUnitsToConsiderReclaiming) == false then
                                    iCurValueBlockingBuildings = AiBotUnitInfo.GetMassCostOfUnits(tUnitsToConsiderReclaiming)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iCurValueBlockingBuildings='..iCurValueBlockingBuildings..'; iLowestValueBlockingBuildings='..iLowestValueBlockingBuildings) end
                                    if iCurValueBlockingBuildings < iLowestValueBlockingBuildings then
                                        iLowestValueBlockingBuildings = iCurValueBlockingBuildings
                                        tLowestValueBlockingBuildings = tUnitsToConsiderReclaiming
                                        bHavePotentiallyValidLocation = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have a potentially valid location for shields so will reclaim if it remains the lowest value of blocking units') end
                                    end
                                else
                                    if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry]) then
                                        if not(tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount]) then tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount] = {} end
                                        tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = 0
                                    end
                                    tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] = tTableRef[AiBotMap.subrefGEDefenceBlockedFailureCount][iEntry] + 1
                                end
                            end
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': bTriedBuildingSomething was false so will go through every potential build location to see if there are blocking units to reclaim') end

                    for iPotentialLocation, tBuildLocation in tPotentialBuildLocations do
                        if bDebugMessages == true then AiBotUtilities.DrawRectangle(AiBotUtilities.GetRectAroundLocation(tBuildLocation, 1.5), 2, 200) end
                        --Look to reclaim buildings that are blocking us with remaining engineers, unless they are very high value buildings


                        if (tTableRef[AiBotMap.subrefGEShieldBlockedFailureCount][1] or 0) < 5 then
                            ConsiderUnitsToReclaim(tBuildLocation, iPotentialLocation)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bHavePotentiallyValidLocation='..tostring(bHavePotentiallyValidLocation or false)..'; Is tLowestValueBlockingBuildings empty='..tostring(AiBotUtilities.IsTableEmpty(tLowestValueBlockingBuildings))) end
                        if bHavePotentiallyValidLocation then
                            --Get all engineers to reclaim the units here
                            local iCtrlKdUnits = 0
                            local oUnitToReclaim
                            for iUnit, oUnit in tLowestValueBlockingBuildings do
                                if oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() == 1 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryVolatile + categories.COMMAND, oUnit.UnitId)) then
                                    --CtrlK instead of reclaiming
                                    AiBotOrders.IssueTrackedKillUnit(oUnit)
                                    iCtrlKdUnits = iCtrlKdUnits + 1
                                elseif not(oUnitToReclaim) then oUnitToReclaim = oUnit
                                end
                            end

                            if oUnitToReclaim then
                                local iEngisGivenReclaimOrder = 0
                                CheckAndClearEngineersConstructingTargetUnit(oUnitToReclaim, tLZTeamData, iPlateau, iLandZone)
                                for iEngineer, oEngineer in tAvailableEngineers do
                                    AiBotOrders.IssueTrackedReclaim(oEngineer, oUnitToReclaim, false, 'GESMDRecl', false)
                                    iEngisGivenReclaimOrder = iEngisGivenReclaimOrder + 1
                                    if iOptionalMaxEngiPerAction and iEngisGivenReclaimOrder >= iOptionalMaxEngiPerAction then break end
                                end
                                if iOptionalMaxEngiPerAction then
                                    for iRemoveCount = 1, iEngisGivenReclaimOrder do
                                        local oEngiToRemove = tAvailableEngineers[1]
                                        if AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction) == false then
                                            local bRemovedFromEngiByFaction = false
                                            for iFaction, tFactionEngineers in tAvailableT3EngineersByFaction do
                                                for iFactionEngi, oFactionEngi in tFactionEngineers do
                                                    if oFactionEngi == oEngiToRemove then
                                                        table.remove(tAvailableT3EngineersByFaction, iFactionEngi)
                                                        bRemovedFromEngiByFaction = true
                                                        break
                                                    end
                                                end
                                                if bRemovedFromEngiByFaction then break end
                                            end
                                        end
                                        table.remove(tAvailableEngineers, 1)
                                    end
                                else
                                    tAvailableEngineers = nil
                                    tAvailableT3EngineersByFaction = nil
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to create space for SMD or other defensive unit by reclaiming unit '..oUnitToReclaim.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToReclaim)) end
                                break
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': CtrlKdUnitCount='..iCtrlKdUnits) end
                                if bOptionalRemoveInvalidPotentialBuildLocations then
                                    table.remove(tPotentialBuildLocations, iPotentialLocation)
                                    break
                                end
                            end
                        elseif bOptionalRemoveInvalidPotentialBuildLocations then
                            table.remove(tPotentialBuildLocations, iPotentialLocation)
                            break
                        end
                    end
                end
            end
        end
        --Consider getting SMD if we dont have one and enemy has nukes, and we have an SMD location for this table
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want SMD for template '..iTemplateRef..'; in P'..iPlateau..'Z'..iLandZone..'; Is table of enemy nukes empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]))..'; Do we have a valid SMD unit in this template already='..tostring(AiBotUnitInfo.IsUnitValid(tTableRef[AiBotMap.subrefGESMDUnit]))..'; Is table of available t3 engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction))..'; Is SMD location for this template empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGESMDLocation]))) end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false and not(AiBotUnitInfo.IsUnitValid(tTableRef[AiBotMap.subrefGESMDUnit])) and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGESMDLocation]) == false and AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategorySML - categories.BATTLESHIP, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers])) == false then
            --Enemy has nuke (non sera battleship version) and we lack SMD for this template, so get SMD unless we have another template in this zone that has SMD
            local bHaveOtherTemplateWithSMD = false
            for iTemplate, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                if AiBotUnitInfo.IsUnitValid(tTableRef[AiBotMap.subrefGESMDUnit]) then
                    bHaveOtherTemplateWithSMD = true
                    break
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bHaveOtherTemplateWithSMD='..tostring(bHaveOtherTemplateWithSMD)) end
            if not(bHaveOtherTemplateWithSMD) then
                --Wnat to build SMD
                BuildDefensiveUnit(AiBotUnitInfo.refCategorySMD, {tTableRef[AiBotMap.subrefGESMDLocation]})
            end
        end


        --Consider getting SAMs
        if not(bTriedBuildingSomething) and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEAvailableDefenceLocations]) == false then
            local iSAMsWanted = math.max(1, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] / 8000)
            if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 then
                if AiBotConditions.TeamHasAirControl(iTeam) then iSAMsWanted = math.max(1, iSAMsWanted * 0.5) end
            else
                iSAMsWanted = iSAMsWanted + 2
            end
            --Cap sams wanted based on defence locations if trying to build more than 3
            local iTotalDefenceLocations = table.getn(tTableRef[AiBotMap.subrefGEAvailableDefenceLocations])
            if iSAMsWanted > 3 then iSAMsWanted = math.min(iSAMsWanted, math.max(3, iTotalDefenceLocations - 2)) end

            local iCurSAMs = 0
            local iCurPD = 0
            local iCurT2Arti = 0
            if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEDefenceUnits]) == false then
                for iDefenceUnit, oDefenceUnit in tTableRef[AiBotMap.subrefGEDefenceUnits] do
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oDefenceUnit.UnitId) then
                        iCurSAMs = iCurSAMs + 1
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oDefenceUnit.UnitId) then
                        iCurPD = iCurPD + 1
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oDefenceUnit.UnitId) then
                        iCurT2Arti = iCurT2Arti + 1
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': iCurSAMs='..iCurSAMs..'; iSAMsWanted='..iSAMsWanted..'; iCurPD='..iCurPD..'; iCurT2Arti='..iCurT2Arti..'; iTotalDefenceLocations='..iTotalDefenceLocations) end

            if iCurSAMs < iSAMsWanted then
                BuildDefensiveUnit(AiBotUnitInfo.refCategoryGroundAA * categories.SIZE4 * categories.TECH3, tTableRef[AiBotMap.subrefGEAvailableDefenceLocations], true)
            end
            if not(bTriedBuildingSomething) then
                --T2 arti builder
                if ((AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false or (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) >= 10000) and iCurT2Arti < 4) or (iCurT2Arti < (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) / 1000) or (iCurT2Arti == 0 and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] > 50) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want T2 arti, unless no space') end
                    if iCurSAMs > 0 or iCurT2Arti < iTotalDefenceLocations - 2 then
                        BuildDefensiveUnit(AiBotUnitInfo.refCategoryFixedT2Arti * categories.SIZE4, tTableRef[AiBotMap.subrefGEAvailableDefenceLocations], true)
                    end
                end
                if not(bTriedBuildingSomething) then
                    --PD builder
                    if iCurPD < 4 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false or (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 and (iCurPD == 0 or iCurPD < tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] / 500))) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasTeleport] or (AiBotUnitInfo.GetMassCostOfUnits(tTableRef[AiBotMap.subrefGEArtiUnits]) >= 150000 and tTableRef[AiBotMap.subrefGEArtiUnits][1].GetFractionComplete and tTableRef[AiBotMap.subrefGEArtiUnits][1]:GetFractionComplete() >= 0.8 and iCurPD < 2) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want PD unless no space') end
                        if iCurSAMs > 0 or iCurPD < iTotalDefenceLocations - 2 then
                            --Ravager size category invalid (although for FAF have drafted a PR to fix it 2025-11)
                            BuildDefensiveUnit(AiBotUnitInfo.refCategoryPD * categories.SIZE4 + categories.xeb2306, tTableRef[AiBotMap.subrefGEAvailableDefenceLocations], true)
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bTriedBuildingSomething='..tostring(bTriedBuildingSomething)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bTriedBuildingSomething
end

function GETemplateMoveEngineersUnderShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef)
    if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and tTableRef[AiBotMap.subrefGEArtiLocations][1] and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEShieldUnits]) == false then
        local tMidpoint = tTableRef[AiBotMap.subrefGEMidpoint]
        local iMaxDistWanted = AiBotUtilities.GetDistanceBetweenPositions(tTableRef[AiBotMap.subrefGEArtiLocations][1], tMidpoint)
        local bNearHighHealthShield
        local tCurEngiPosition
        for iCurEngineer = table.getn(tAvailableEngineers), 1, -1 do
            tCurEngiPosition = tAvailableEngineers[iCurEngineer]:GetPosition()
            if AiBotUtilities.GetDistanceBetweenPositions(tCurEngiPosition, tMidpoint) > iMaxDistWanted then
                --Check incase we are already under a fixed shield that is part of the GE template
                bNearHighHealthShield = false
                for iShield, oShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                    if AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tCurEngiPosition) <= 16 and oShield:GetFractionComplete() == 1 and oShield.MyShield.GetHealth and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oShield) >= 0.8 then
                        bNearHighHealthShield = true
                        break
                    end
                end
                if not(bNearHighHealthShield) then
                    AiBotOrders.IssueTrackedMove(tAvailableEngineers[iCurEngineer], tMidpoint, 2, false, 'GEConsol', false)
                    table.remove(tAvailableEngineers, iCurEngineer)
                end
            end
        end
    end
end

function DelayedGEManagerCheck(tLZData, tLZTeamData, iTemplateRef, iPlateau, iLandZone, iTeam)
    --Call via fork thread; currently used when engineer added but no active monitor
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedGEManagerCheck'


    WaitTicks(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tTableRef = tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef]
    if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTemplateRef='..iTemplateRef..'; subrefGEbActiveMonitor='..tostring(tTableRef[AiBotMap.subrefGEbActiveMonitor] or false)..'; is subrefGEEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))..'; Time='..GetGameTimeSeconds()) end
    if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEbActiveMonitor]) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        GameEnderTemplateManager(tLZData, tLZTeamData, iTemplateRef, iPlateau, iLandZone, iTeam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GameEnderTemplateManager(tLZData, tLZTeamData, iTemplateRef, iPlateau, iLandZone, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GameEnderTemplateManager'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tTableRef = tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef]
    local bCallAgainAfterDelay

    function RemoveEngineerFromGETemplate(oEngineer)
        if tLZTeamData[AiBotMap.subrefbGEShieldSACU] and EntityCategoryContains(categories.UEF * categories.SUBCOMMANDER, oEngineer.UnitId) then
            --Dont remove - shield SACU
            bCallAgainAfterDelay = true
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to remove UEF SACU from GE template as it is using shield SACUs') end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Will clear engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' from this template for P'..iPlateau..'Z'..iLandZone..'R'..iTemplateRef) end
            if not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) then
                AiBotOrders.IssueTrackedClearCommands(oEngineer)
            end
            --Make sure RAS SACUs have their assigned template cleared
            if oEngineer[AiBotBuilding.reftArtiTemplateRefs] and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oEngineer.UnitId)) then
                oEngineer[AiBotBuilding.reftArtiTemplateRefs] = nil
            else
                ClearEngineerTracking(oEngineer)
                --redundancy
                if bDebugMessages == true then LOG(sFunctionRef..': Finished clearing engineer, reftArtiTemplateRefs before redundancy='..reprs(oEngineer[AiBotBuilding.reftArtiTemplateRefs])) end
                if oEngineer[AiBotBuilding.reftArtiTemplateRefs] then oEngineer[AiBotBuilding.reftArtiTemplateRefs] = nil end
            end
        end
    end

    if not(tTableRef[AiBotMap.subrefGEbActiveMonitor]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Setting GE active monitor to true for iTemplateRef='..(iTemplateRef or 'nil')..'; P'..iPlateau..'Z'..iLandZone..' Team '..iTeam..'; Is tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]))..'; Arti locations='..repru(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations])..'; Is table of engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))..'; Is table empty for engis using alt ref='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]))) end
        tTableRef[AiBotMap.subrefGEbActiveMonitor] = true
        AiBotOverseer.refiCurGETemplateGlobalCount = AiBotOverseer.refiCurGETemplateGlobalCount + 1

        local iCurTick = (GetGameTimeSeconds() - math.floor(GetGameTimeSeconds())) * 10
        local iTicksToWait = AiBotOverseer.refiCurGETemplateGlobalCount - iCurTick - 1
        if iTicksToWait < 0 then iTicksToWait = iTicksToWait + 10 end
        while iTicksToWait >= 10 do
            iTicksToWait = iTicksToWait - 10
        end
        if AiBotOverseer.refiCurGETemplateGlobalCount == 1 then iTicksToWait = math.min(iTicksToWait, 4) end
        if bDebugMessages == true then LOG(sFunctionRef..': Count='..AiBotOverseer.refiCurGETemplateGlobalCount..'; iTicksToWait='..iTicksToWait..'; iCurTick='..iCurTick..'; Time='..GetGameTimeSeconds()) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(iTicksToWait)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        local iShieldLocations = table.getn(tTableRef[AiBotMap.subrefGEShieldLocations])
        local iArtiLocations = table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
        tTableRef[AiBotMap.subrefGEbDontNeedEngineers] = false



        local oFirstUEF, oFirstAeon, oFirstCybran, oFirstSeraphim, oFirstEngineer, bClearAllEngineers
        local bHaveAlreadyTriedSwitchingCategoryForNovax = false
        local bTriedBuildingSomething = false
        local bGaveBuildOrder = false
        local bDisbandForPowerStall = false

        local bUsingSACUShieldTemplate = false
        local oGatewayForShieldSACUs
        --Dont do shield SACUs on a 5km map or non-FAF or poor eco
        if AiBotUtilities.bFAFActive and AiBotBuilding.bShieldsCanDischarge and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 90 and AiBotMap.iMapSize >= 500 then
            --Do we have UEF T3 engineers, SACUs, or any tech factory or gateway in this zone?
            bUsingSACUShieldTemplate = not(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown((AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryQuantumGateway + AiBotUnitInfo.refCategoryEngineer * categories.TECH3 + categories.SUBCOMMANDER) * categories.UEF, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))
            if bUsingSACUShieldTemplate then
                --Set this flag for the zone
                tLZTeamData[AiBotMap.subrefbGEShieldSACU] = true
            end
        end
        local tArtiMidpoint
        if table.getn(tTableRef[AiBotMap.subrefGEArtiLocations]) == 1 then
            tArtiMidpoint = tTableRef[AiBotMap.subrefGEArtiLocations][1]
        else
            tArtiMidpoint = {}
            for iArtiLocation, tArtiLocation in tTableRef[AiBotMap.subrefGEArtiLocations] do
                tArtiMidpoint[1] = (tArtiMidpoint[1] or 0) + tArtiLocation[1]
                tArtiMidpoint[3] = (tArtiMidpoint[3] or 0) + tArtiLocation[3]
            end
            tArtiMidpoint[1] = tArtiMidpoint[1] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
            tArtiMidpoint[3] = tArtiMidpoint[3] / table.getn(tTableRef[AiBotMap.subrefGEArtiLocations])
        end


        if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting for P'..iPlateau..'Z'..iLandZone..'; iTableRef='..iTemplateRef..'; tTableRef[AiBotMap.subrefGEbDontNeedEngineers]='..tostring(tTableRef[AiBotMap.subrefGEbDontNeedEngineers] or false)..'; is tableo f engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))..'; Time='..GetGameTimeSeconds()) end

        while not(tTableRef[AiBotMap.subrefGEbDontNeedEngineers]) do
            --Decide whether to continue with loop - abort if have no engineers and no arti and no shields
            local bStillValid = false
            if AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEEngineers]) then bStillValid = true end
            if AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEArtiUnits]) then bStillValid = true end
            if AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEShieldUnits]) then bStillValid = true end
            if bDebugMessages == true then LOG(sFunctionRef..': Starting new loop at time='..GetGameTimeSeconds()..' for P'..iPlateau..'Z'..iLandZone..'TableRef'..iTemplateRef..'; bStillValid='..tostring(bStillValid or false)..'; Time of last AiBot death='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAiBotPlayerDefeat] or 'nil')..'; Is this table flagged as no longer wanting engis='..tostring(tTableRef[AiBotMap.subrefGEbDontNeedEngineers])) end
            if bStillValid then
                --Decide what to do with engineers, if we have any
                bDisbandForPowerStall = false
                local tAvailableEngineers = {}
                local tAvailableT3EngineersByFaction = {}
                local tLowCompletionShieldsToAssist = {}
                oFirstUEF = nil
                oFirstAeon = nil
                oFirstCybran = nil
                oFirstSeraphim = nil
                oFirstEngineer = nil

                if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]) == false then
                    for iEngineer, oEngineer in tTableRef[AiBotMap.subrefGEEngineers] do
                        if not(oEngineer:IsUnitState('Upgrading')) and (not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) or not(bUsingSACUShieldTemplate) or not(EntityCategoryContains(categories.UEF * categories.SUBCOMMANDER, oEngineer.UnitId))) then
                            if bDebugMessages == true then LOG(sFunctionRef..': About to add engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to table of available engineers') end
                            table.insert(tAvailableEngineers, oEngineer)
                            if EntityCategoryContains(categories.ENGINEER * categories.TECH3 + categories.SUBCOMMANDER, oEngineer.UnitId) then
                                if not(oFirstUEF) and EntityCategoryContains(categories.UEF * categories.TECH3, oEngineer.UnitId) then oFirstUEF = oEngineer end
                                if not(oFirstAeon) and EntityCategoryContains(categories.AEON * categories.TECH3, oEngineer.UnitId) then oFirstAeon = oEngineer end
                                if not(oFirstCybran) and EntityCategoryContains(categories.CYBRAN * categories.TECH3, oEngineer.UnitId) then oFirstCybran = oEngineer end
                                if not(oFirstSeraphim) and EntityCategoryContains(categories.SERAPHIM * categories.TECH3, oEngineer.UnitId) then oFirstSeraphim = oEngineer end
                                if not(oFirstEngineer) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer * categories.TECH3 + categories.SUBCOMMANDER * categories.TECH3, oEngineer.UnitId) then oFirstEngineer = oEngineer end
                                if not(oEngineer[AiBotBuilding.reftArtiTemplateRefs]) then
                                    --oEngineer[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
                                    RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTemplateRef, nil, false)
                                end --redundancy
                            end
                        end
                    end

                    tAvailableT3EngineersByFaction = {}
                    if oFirstAeon then tAvailableT3EngineersByFaction[AiBotUnitInfo.refFactionAeon] = EntityCategoryFilterDown(categories.AEON * categories.TECH3, tAvailableEngineers) end
                    if oFirstUEF then tAvailableT3EngineersByFaction[AiBotUnitInfo.refFactionUEF] = EntityCategoryFilterDown(categories.UEF * categories.TECH3, tAvailableEngineers) end
                    if oFirstCybran then tAvailableT3EngineersByFaction[AiBotUnitInfo.refFactionCybran] = EntityCategoryFilterDown(categories.CYBRAN * categories.TECH3, tAvailableEngineers) end
                    if oFirstSeraphim then tAvailableT3EngineersByFaction[AiBotUnitInfo.refFactionSeraphim] = EntityCategoryFilterDown(categories.SERAPHIM * categories.TECH3, tAvailableEngineers) end
                    if not(oFirstAeon) and not(oFirstUEF) and not(oFirstCybran) and not(oFirstSeraphim) then tAvailableT3EngineersByFaction[AiBotUnitInfo.refFactionUnrecognised] = EntityCategoryFilterDown(categories.TECH3, tAvailableEngineers) end
                    if AiBotUnitInfo.IsUnitValid(oFirstEngineer) or iTeam then --We might have T1-2 engineers that dont qualify as a first available negi but could still do some stuff
                        if not(iTeam) then iTeam = oFirstEngineer:GetAIBrain().AiBotTeam end --mostly a redundancy since should always have a team from the function calling this

                        local iCompletedArti = 0
                        local iUnderConstructionArti = 0
                        local iCompletedShields = 0
                        local iCompletedAiBotEasyShields = 0
                        local iUnderConstructionShields = 0
                        local oNearestCompletionShield, oNearestCompletionArti
                        local iHighestCompletionShield = -0.1
                        local iHighestCompletionArti = -0.1
                        local iExpShieldCount = 0
                        local iArtiMassInvestment = 0
                        bTriedBuildingSomething = false

                        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false then
                            for iArti, oArti in tTableRef[AiBotMap.subrefGEArtiUnits] do
                                if oArti:GetFractionComplete() == 1 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': We have completed oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; at position '..repru(oArti:GetPosition())..'; Arti locations in template='..repru(tTableRef[AiBotMap.subrefGEArtiLocations])) end
                                    iCompletedArti = iCompletedArti  + 1
                                    iArtiMassInvestment = iArtiMassInvestment + (oArti[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oArti))
                                else
                                    iUnderConstructionArti = iUnderConstructionArti + 1
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; Fraction complete='..oArti:GetFractionComplete()..'; iHighestCompletionArti='..iHighestCompletionArti) end
                                    if oArti:GetFractionComplete() > iHighestCompletionArti then
                                        iHighestCompletionArti = oArti:GetFractionComplete()
                                        oNearestCompletionArti = oArti
                                    end
                                    iArtiMassInvestment = iArtiMassInvestment + (oArti[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oArti)) * oArti:GetFractionComplete()
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEShieldUnits]) == false then
                            for iShield, oShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering shield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Fraction complete='..oShield:GetFractionComplete()..'; Shield arti ref='..repru(oShield[AiBotBuilding.reftArtiTemplateRefs])) end
                                if oShield:GetFractionComplete() == 1 then
                                    iCompletedShields = iCompletedShields  + 1
                                    if oShield[AiBotUnitInfo.refbEasyBrain] then
                                        iCompletedAiBotEasyShields = iCompletedAiBotEasyShields + 1
                                    end
                                else
                                    iUnderConstructionShields = iUnderConstructionShields + 1
                                    if oShield:GetFractionComplete() > iHighestCompletionShield then
                                        iHighestCompletionShield = oShield:GetFractionComplete()
                                        oNearestCompletionShield = oShield
                                    end
                                    if oShield:GetFractionComplete() < 0.07 then
                                        table.insert(tLowCompletionShieldsToAssist, oShield)
                                    end
                                end
                                if EntityCategoryContains(categories.EXPERIMENTAL, oShield.UnitId) then iExpShieldCount = iExpShieldCount+ 1 end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Finished checking how many shields and arti we have in iPlateau='..iPlateau..'; Zone='..iLandZone..'; Template ref='..iTemplateRef..', iCompletedShields='..iCompletedShields..'; iUnderConstructionShields='..iUnderConstructionShields..'; iCompletedArti='..iCompletedArti..'; iUnderConstructionArti='..iUnderConstructionArti..'; Number of engis='..table.getn(tAvailableEngineers)..'; tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart]='..(tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] or 'nil')..'; tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild]='..tostring(tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild] or false)..'; Is table of engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))) end

                        --Check shields for cycling once we have a certain number
                        if iCompletedShields >= 3 and (iCompletedAiBotEasyShields == 0 or iCompletedShields - iCompletedAiBotEasyShields >= 2) then
                            if bDebugMessages == true then LOG(sFunctionRef..': we have at least 3 shields so will check if we are shield cycling, tTableRef[AiBotMap.subrefGEbActiveShieldMonitor]='..tostring(tTableRef[AiBotMap.subrefGEbActiveShieldMonitor] or false)) end
                            ForkThread(AiBotBuilding.MonitorShieldsForCycling, tTableRef, iTeam, iLandZone, iTemplateRef, tLZTeamData)
                        end

                        if tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild] and AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                            tTableRef[AiBotMap.subrefbForceRefreshOfArtiToBuild] = false
                            local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true,                                                      nil,            AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, false, iTemplateRef)
                            GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTemplateRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, iMassToComplete >= 80000)
                        end

                        --If we dont have a T3 arti even started construction, then build one with the closest engineer able to build the desired category
                        if iCompletedArti == 0 and iUnderConstructionArti == 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build an arti or gameender, is table of available engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; oFirstEngineer='..(oFirstEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstEngineer) or 'nil')..'; Is tAvailableT3EngineersByFaction empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction))) end
                            --GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, bOptionalReturnMassToCompleteOtherZoneUnderConstruction, iOptionalSearchRange, iOptionalCategoryFilter,                 bOptionalClearEngineersInOtherZonesWithoutConstruction, iOptionalTableRefToIgnoreForThisZone)
                            local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true,                                                      nil,            AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, false, iTemplateRef)
                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to build another gameender unit from this template, iTeam='..(iTeam or 'nil')..'; iOtherLandZonesWithExperimental='..(iOtherLandZonesWithExperimental or 'nil')..'; iMassToComplete='..(iMassToComplete or 'nil')..'; Stored mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 'nil')..'; Gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Av mass%='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; P'..iPlateau..'Z'..iLandZone..'T'..iTemplateRef..' Time='..GetGameTimeSeconds()) end
                            if (iOtherLandZonesWithExperimental or 0) > 0 and (iMassToComplete or 0) >= math.max(100000, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 0) * 2) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 200*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotConditions.TeamHasLowMass(iTeam)) and AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) <= 800 and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
                                --NOTE: IF CHANGING ABOVE THEN CHANGE THE SAME PLACE LATER IN CODE
                                if bDebugMessages == true then LOG(sFunctionRef..': Will reassess first category to build as dont want another gameender') end
                                --If current category contains game-enders then reassess
                                GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTemplateRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, true)
                            end
                            bGaveBuildOrder = GETemplateStartBuildingArtiOrGameEnder(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer)
                            if bGaveBuildOrder then bTriedBuildingSomething = true end
                            if AiBotUnitInfo.IsUnitValid(oFirstEngineer) and AiBotTeam.tTeamData[oFirstEngineer:GetAIBrain().AiBotTeam][AiBotTeam.refbUnableToBuildArtiOrGameEnders] then
                                tTableRef[AiBotMap.subrefGEbDontNeedEngineers] = true
                                break
                            end
                        end

                        if iUnderConstructionArti > 0 then tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] = 0 end

                        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                            local iOrigAvailableEngis = table.getn(tAvailableEngineers)
                            local bExcludeExpShields
                            if iExpShieldCount > 0 then
                                if iExpShieldCount >= 2 or (iExpShieldCount >= 1 and iShieldLocations - iCompletedShields - iUnderConstructionShields >= 5) then bExcludeExpShields = true
                                else
                                    --We have 1 exp shield - dont get a second if we dont have a gameender
                                    bExcludeExpShields = true
                                    if iUnderConstructionArti + iCompletedArti > 0 then
                                        for iArti, oArti in tTableRef[AiBotMap.subrefGEArtiUnits] do
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oArti.UnitId) then
                                                bExcludeExpShields = false
                                                break
                                            end
                                        end

                                    end
                                end
                            end
                            --If have lots of engineers then spread out since the biggest delay may be starting construction of a shield
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to start  building more shields, iCompletedShields='..iCompletedShields..'; iUnderConstructionShields='..iUnderConstructionShields..'; iArtiMassInvestment='..iArtiMassInvestment..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])..'; FAF condition='..tostring((AiBotUtilities.bFAFActive and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iArtiMassInvestment >= 100000 or (iCompletedShields + iUnderConstructionShields < 4 and (iCompletedShields+iUnderConstructionShields < 3 or iCompletedArti >= 1)) or (iCompletedArti >= 1 and (iCompletedArti >= 2 or iArtiMassInvestment >= 50000)))))) end
                            if (iUnderConstructionShields == 0 and (iCompletedShields == 0 or iCompletedShields < math.min(6, iHighestCompletionArti * 8))) or (iOrigAvailableEngis >= 5 and iUnderConstructionShields > 0 and iCompletedShields + iUnderConstructionShields < iShieldLocations and iUnderConstructionShields < 4) then
                                if (AiBotUtilities.bFAFActive and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iArtiMassInvestment >= 100000 or (iCompletedShields + iUnderConstructionShields < 4 and (iCompletedShields+iUnderConstructionShields < 3 or iCompletedArti >= 1)) or (iCompletedArti >= 1 and (iCompletedArti >= 2 or iArtiMassInvestment >= 50000))))
                                        --Non-FAF - be far less likely to get lots of shielding
                                        or iCompletedShields + iUnderConstructionShields < math.max(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]) then

                                    if not(bUsingSACUShieldTemplate) or (iUnderConstructionShields == 0 and (iCompletedShields == 0 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (iCompletedShields < 3 or ((tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] or 0) <= 0.5 and iCompletedShields < 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] * 3))))) then
                                        --Start building so have at least 4 shields built at once (want to do ahead of assisting shields, since faction used for this is important) - have 1 engi building each shield
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try assigning 1 engi each to building a shield since iOrigAvailableEngis='..iOrigAvailableEngis) end

                                        --GETemplateStartBuildingShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, iMaxShieldsToTryAndBuild,                                                                                  iOptionalMaxEngiPerAction, bOnlyGetT3)
                                        bGaveBuildOrder = GETemplateStartBuildingShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, math.min(4 - iUnderConstructionShields, iShieldLocations - iCompletedShields - iUnderConstructionShields), 1,                           bExcludeExpShields)
                                        if bGaveBuildOrder then bTriedBuildingSomething = true end
                                    end
                                end

                            end
                            if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Still have available engineers for zone '..iLandZone..'; will have 1 engi assisting the gameender and then have the rest building shields or helping tocompletion unless we want to assist a shield as ah igher priority. iOrigAvailableEngi'..iOrigAvailableEngis..'; Is tLowCompletionShieldsToAssist empty='..tostring(AiBotUtilities.IsTableEmpty(tLowCompletionShieldsToAssist))..'; iUnderConstructionShields='..iUnderConstructionShields..'; iCompletedShields='..iCompletedShields..'; iHighestCompletionArti='..iHighestCompletionArti..'; is oNearestCompletionShield valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestCompletionShield))) end
                                if iHighestCompletionArti > 0.03 and (iUnderConstructionShields == 1 or iUnderConstructionShields <= 2 and iHighestCompletionShield <= 0.03) and oNearestCompletionShield and (iCompletedShields == 0 or iCompletedShields < math.min(6, iHighestCompletionArti * 8)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': will get one engi to assist nearest completion shield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)) end
                                    bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionShield, 1)
                                    if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                end
                                if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                    --Have 1 engi assisting the arti if it is under construction so it doesnt die from low health
                                    if iUnderConstructionArti > 0 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have an under construction arti so will try and assist it, oNearestCompletionArti='..(oNearestCompletionArti.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionArti) or 'nil')) end
                                        bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionArti, 1)
                                        if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                    end

                                    --next have 1 engi assisting each low health under construction shield
                                    if iOrigAvailableEngis >= 5 and AiBotUtilities.IsTableEmpty(tLowCompletionShieldsToAssist) == false and AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                        for iShield, oShield in tLowCompletionShieldsToAssist do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get 1 engineer to assist the low construction shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)) end
                                            bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oShield, 1)
                                            if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                            if AiBotUtilities.IsTableEmpty(tLowCompletionShieldsToAssist) then break end --redundancy, but hopefully shouldnt happen
                                        end
                                    end

                                    --If still have available engineers, then focus on getting more shielding if either we lack 3 completed shields, or enemy has T3 arti
                                    if bDebugMessages == true then LOG(sFunctionRef..': Do we still ahve available engineers? is table empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; tTableRef[AiBotMap.subrefbHaveTooSmallShields]='..tostring(tTableRef[AiBotMap.subrefbHaveTooSmallShields] or false)) end
                                    if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                        --If are powerstalling then disband engineers and dont proceed with construction
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                                            bDisbandForPowerStall = true
                                            --Remove the last available engineer
                                            local oEngiToRemove = tAvailableEngineers[table.getn(tAvailableEngineers)]
                                            ClearEngineerTracking(oEngiToRemove)
                                            AiBotOrders.IssueTrackedClearCommands(oEngiToRemove)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Are powerstalling so have removed the last available engineer, just c leared oEngiToRemove='..oEngiToRemove.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngiToRemove)..' from P'..iPlateau..'L'..iLandZone..'T'..iTemplateRef..' at time='..GetGameTimeSeconds()) end
                                        elseif oNearestCompletionShield then
                                            local iLimitOnEngisToAssistShield
                                            if iCompletedShields >= 3 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) then iLimitOnEngisToAssistShield = 1 end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will assist nearest completion shield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)..'; iLimitOnEngisToAssistShield='..(iLimitOnEngisToAssistShield or 'nil')) end
                                            bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionShield, iLimitOnEngisToAssistShield)
                                            if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                        elseif iCompletedShields + iUnderConstructionShields < iShieldLocations and (not(bUsingSACUShieldTemplate) or (iArtiMassInvestment >= 150000 and iUnderConstructionArti == 0) or ((tTableRef[AiBotMap.subrefiHighestShieldACUHealthPercent] or 0) <= 0.5 and iCompletedShields < 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] * 3)) and
                                                ((AiBotUtilities.bFAFActive and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iArtiMassInvestment >= 100000 or (iCompletedShields + iUnderConstructionShields < 4 and (iCompletedShields+iUnderConstructionShields < 3 or iCompletedArti >= 1)) or (iCompletedArti >= 1 and (iCompletedArti >= 2 or iArtiMassInvestment >= 50000))))
                                                        or iCompletedShields + iUnderConstructionShields < math.max(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount])) then
                                            if (iHighestCompletionArti >= 0.1 * iCompletedShields or iCompletedShields < 4 or not(AiBotConditions.HaveLowPower(iTeam)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100 + 250 * iCompletedShields) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': We can build more shields so we will, iCompletedShields='..iCompletedShields..'; iUnderConstructionShields='..iUnderConstructionShields..'; iArtiMassInvestment='..iArtiMassInvestment..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])..'; FAF condition='..tostring((AiBotUtilities.bFAFActive and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or iArtiMassInvestment >= 100000 or (iCompletedShields + iUnderConstructionShields < 4 and (iCompletedShields+iUnderConstructionShields < 3 or iCompletedArti >= 1)) or (iCompletedArti >= 1 and (iCompletedArti >= 2 or iArtiMassInvestment >= 50000)))))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount]) end
                                                bGaveBuildOrder = GETemplateStartBuildingShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, math.min(4, iShieldLocations - iCompletedShields), nil, bExcludeExpShields)
                                                if bGaveBuildOrder then bTriedBuildingSomething = true end
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to build more shields unless we have better power')
                                                    bDisbandForPowerStall = true
                                                end
                                            end
                                        elseif tTableRef[AiBotMap.subrefbHaveTooSmallShields] and iCompletedShields >= iShieldLocations and (oFirstSeraphim or oFirstUEF) then
                                            local tUEFAndSeraEngis = EntityCategoryFilterDown((categories.UEF + categories.SERAPHIM) * categories.TECH3, tAvailableEngineers)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider destroying a shield to rebuild with a larger one if we have UEF or Sera engineers, is tUEFAndSeraEngis empty='..tostring(AiBotUtilities.IsTableEmpty(tUEFAndSeraEngis))) end
                                            if AiBotUtilities.IsTableEmpty(tUEFAndSeraEngis) == false then
                                                --Destroy one of the small shields
                                                for iShield, oShield in tTableRef[AiBotMap.subrefGEShieldUnits] do
                                                    if oShield[AiBotBuilding.refbProtectingAllArtiAndShieldLocations] == false then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..' that is not protecting all arti and shield locations so will ctrlk it so can rebuild with larger shield') end
                                                        AiBotOrders.IssueTrackedKillUnit(oShield)
                                                        tTableRef[AiBotMap.subrefbHaveTooSmallShields] = nil
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and not(bDisbandForPowerStall) then
                                            --Move engineers to be under shields if enemy has t3 arti (unless are SACU and already under fixed shield coverage)
                                            if iCompletedShields + iUnderConstructionShields - 1 >= iShieldLocations and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (iUnderConstructionArti > 0 or iCompletedArti >= iArtiLocations) then
                                                GETemplateMoveEngineersUnderShield(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, nil, nil, bExcludeExpShields)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will try sending any far away engineers towards midpoint where they should be safer, is tAvailableEngineers empty after this='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))) end
                                            end
                                            if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                                --Consider building SMD if enemy has nukes
                                                local oDefenceToAssist

                                                if AiBotUnitInfo.IsUnitValid(tTableRef[AiBotMap.subrefGESMDUnit]) then
                                                    if tTableRef[AiBotMap.subrefGESMDUnit]:GetFractionComplete() < 1 then
                                                        oDefenceToAssist = tTableRef[AiBotMap.subrefGESMDUnit]
                                                    end
                                                end
                                                if not(oDefenceToAssist) and AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subrefGEDefenceUnits]) then
                                                    for iDefence, oDefence in tTableRef[AiBotMap.subrefGEDefenceUnits] do
                                                        if oDefence:GetFractionComplete() < 1 then
                                                            oDefenceToAssist = oDefence
                                                            break
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': oDefenceToAssist='..(oDefenceToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oDefenceToAssist) or 'nil')) end
                                                if oDefenceToAssist then
                                                    bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oDefenceToAssist)
                                                    if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                                else
                                                    --Assign up to 4 engis to build defences
                                                    bGaveBuildOrder = GETemplateConsiderDefences(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZTeamData, iPlateau, iLandZone, tTableRef, iTemplateRef, iTeam, 4)
                                                    if bGaveBuildOrder then bTriedBuildingSomething = true end
                                                end
                                                if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                                    --We have all our shields constructed (or dont want to devote them all to shields due to enemy not having arti yet); redundancy - check if we have under construction arti
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Still have engineers available, oNearestCompletionArti='..(oNearestCompletionArti.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionArti) or 'nil')..'; bTriedBuildingSomething='..tostring(bTriedBuildingSomething)) end
                                                    local toShieldSACUsToKeepHome
                                                    --Assist gateway if we have one and want shield SACUs
                                                    if bUsingSACUShieldTemplate then
                                                        local oSACUOrGatewayToAssist
                                                        local iFullyUpgradedSACUs = 0
                                                        local bWantMoreSACUs = true
                                                        --First check for shield SACU to assist
                                                        if AiBotConditions.IsTableOfUnitsStillValid(tTableRef[AiBotMap.subreftoGEShieldSACUs]) then
                                                            local oFirstUpgradingSACU
                                                            local oFirstUnupgradedSACU
                                                            local oFirstCompletelyUnupgradedSACU
                                                            local iSACUsWanted = AiBotConditions.GetShieldSACUsWantedForGETemplate(iTeam)
                                                            for iSACU, oSACU in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                                                                if oSACU:IsUnitState('Upgrading') then
                                                                    oFirstUpgradingSACU = oSACU
                                                                    break
                                                                    --Only get a non-upgrading SACU
                                                                elseif (oSACU[AiBotACU.refiUpgradeCount] or 0) >= 3 then
                                                                    iFullyUpgradedSACUs = iFullyUpgradedSACUs + 1
                                                                elseif not(oFirstUnupgradedSACU) and (oSACU[AiBotACU.refiUpgradeCount] or 0) < 3 and not(oSACU[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotUtilities.GetDistanceBetweenPositions(oSACU:GetPosition(), tArtiMidpoint) <= 10 then
                                                                    oFirstUnupgradedSACU = oSACU
                                                                    if (oSACU[AiBotACU.refiUpgradeCount] or 0) then oFirstCompletelyUnupgradedSACU = oFirstUnupgradedSACU end
                                                                elseif not(oFirstCompletelyUnupgradedSACU) and (oSACU[AiBotACU.refiUpgradeCount] or 0) then oFirstCompletelyUnupgradedSACU = oSACU
                                                                end
                                                            end
                                                            if oFirstUpgradingSACU then
                                                                oSACUOrGatewayToAssist = oFirstUpgradingSACU
                                                            elseif oFirstUnupgradedSACU then
                                                                --Do we want more shield SACUs?
                                                                if bDebugMessages == true then LOG(sFunctionRef..': iFullyUpgradedSACUs='..iFullyUpgradedSACUs..'; iSACUsWanted Number wanted='..iSACUsWanted) end
                                                                if iFullyUpgradedSACUs < iSACUsWanted then
                                                                    oSACUOrGatewayToAssist = oFirstUnupgradedSACU
                                                                    local sUpgradeWanted = AiBotACU.GetUpgradeForSACU(oFirstUnupgradedSACU, false, true, true)
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted='..(sUpgradeWanted or 'nil')) end
                                                                    if sUpgradeWanted then
                                                                        AiBotOrders.IssueTrackedEnhancement(oFirstUnupgradedSACU, sUpgradeWanted, false, 'GEShUgr1')
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting the upgrade for oFirstUnupgradedSACU='..oFirstUnupgradedSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnupgradedSACU)) end
                                                                        for iEngi, oEngi in tAvailableEngineers do
                                                                            if oEngi == oFirstUnupgradedSACU then table.remove(tAvailableEngineers, iEngi) break end
                                                                        end
                                                                    end
                                                                elseif oFirstCompletelyUnupgradedSACU then
                                                                    local sUpgradeWanted = AiBotACU.GetUpgradeForSACU(oFirstCompletelyUnupgradedSACU, false, true, false)
                                                                    if sUpgradeWanted then
                                                                        AiBotOrders.IssueTrackedEnhancement(oFirstCompletelyUnupgradedSACU, sUpgradeWanted, false, 'GEShUgr2')
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting the upgrade for oFirstUnupgradedSACU with shield no longer prioritised='..oFirstUnupgradedSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnupgradedSACU)) end
                                                                        for iEngi, oEngi in tAvailableEngineers do
                                                                            if oEngi == oFirstUnupgradedSACU then table.remove(tAvailableEngineers, iEngi) break end
                                                                        end
                                                                    end
                                                                else
                                                                    local sUpgradeWanted = AiBotACU.GetUpgradeForSACU(oFirstUnupgradedSACU, false, true, true)
                                                                    if sUpgradeWanted and (oFirstUnupgradedSACU:GetBlueprint().Enhancements[sUpgradeWanted].ProductionPerSecondMass or 0) > 0 then
                                                                        AiBotOrders.IssueTrackedEnhancement(oFirstUnupgradedSACU, sUpgradeWanted, false, 'GEShUgr3')
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Getting the RAS upgrade for oFirstUnupgradedSACU='..oFirstUnupgradedSACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstUnupgradedSACU)) end
                                                                        for iEngi, oEngi in tAvailableEngineers do
                                                                            if oEngi == oFirstUnupgradedSACU then table.remove(tAvailableEngineers, iEngi) break end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if table.getn(tTableRef[AiBotMap.subreftoGEShieldSACUs]) >= iSACUsWanted then bWantMoreSACUs = false end
                                                        end
                                                        if not(oSACUOrGatewayToAssist) and bWantMoreSACUs then
                                                            if not(AiBotUnitInfo.IsUnitValid(oGatewayForShieldSACUs)) then
                                                                --Search for if there is a valid one
                                                                local tGatewaysInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway * categories.UEF, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                                if AiBotUtilities.IsTableEmpty(tGatewaysInLZ) == false then
                                                                    local iCurDist
                                                                    local iClosestGateway = 10000
                                                                    for iGateway, oGateway in tGatewaysInLZ do
                                                                        if AiBotUnitInfo.IsUnitValid(oGateway) then
                                                                            --Assist the closest to us
                                                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oGateway:GetPosition(), tTableRef[AiBotMap.subrefGEMidpoint])
                                                                            if iCurDist < iClosestGateway then
                                                                                iClosestGateway = iCurDist
                                                                                oGatewayForShieldSACUs = oGateway
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if AiBotUnitInfo.IsUnitValid(oGatewayForShieldSACUs) then
                                                                --Do we want more shield SACUs?
                                                                if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subreftoGEShieldSACUs]) or AiBotConditions.GetShieldSACUsWantedForGETemplate(iTeam) < table.getn(tTableRef[AiBotMap.subreftoGEShieldSACUs]) then
                                                                    oSACUOrGatewayToAssist = oGatewayForShieldSACUs
                                                                end
                                                            end
                                                        end
                                                        if AiBotUnitInfo.IsUnitValid(oSACUOrGatewayToAssist) then
                                                            --If gateway is far away then temporarily remove shield SACUs and then re-add as available engineers
                                                            if (iFullyUpgradedSACUs > 0 or AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subreftoGEShieldSACUs]) == false) and not(oSACUOrGatewayToAssist[AiBotBuilding.reftArtiTemplateRefs]) and AiBotUtilities.GetDistanceBetweenPositions(oSACUOrGatewayToAssist:GetPosition(), tTableRef[AiBotMap.subrefGEMidpoint]) >= 15 then
                                                                toShieldSACUsToKeepHome = {}
                                                                for iSACU, oSACU in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                                                                    if (oSACU[AiBotACU.refiUpgradeCount] or 0) >= 3 and oSACU.MyShield.GetMaxHealth then
                                                                        for iEngi, oEngi in tAvailableEngineers do
                                                                            if oEngi == oSACU then
                                                                                table.insert(toShieldSACUsToKeepHome, oSACU)
                                                                                table.remove(tAvailableEngineers, iEngi)
                                                                                break
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oSACUOrGatewayToAssist, nil)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Setting all available engineers to assist the oSACUOrGatewayToAssist='..oSACUOrGatewayToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSACUOrGatewayToAssist)) end
                                                            if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                                            if toShieldSACUsToKeepHome then
                                                                if not(tAvailableEngineers) or not(tAvailableT3EngineersByFaction) then
                                                                    tAvailableEngineers = toShieldSACUsToKeepHome
                                                                    tAvailableT3EngineersByFaction = {[AiBotUnitInfo.refFactionUEF] = toShieldSACUsToKeepHome}
                                                                else
                                                                    for iSACU, oSACU in toShieldSACUsToKeepHome do
                                                                        table.insert(tAvailableEngineers, oSACU)
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and oNearestCompletionArti then
                                                        --If overflowing mass, then get rapid fabricator upgrade on any SACUs, and assist the first upgrading SACU
                                                        --Only consider getting the upgrades if we have the main arti under construction, or we risk the SACU blocking build locations
                                                        local oSACUUpgradeToAssist
                                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and tTableRef[AiBotMap.subrefGEbSACUAssigned] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                                                            local oPotentialSACUToGetUpgrade
                                                            for iEngi, oEngi in tAvailableEngineers do
                                                                if EntityCategoryContains(categories.SUBCOMMANDER, oEngi.UnitId) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oSACU, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Unit state='..AiBotUnitInfo.GetUnitState(oEngi)..'; Dist to oNearestCompletionArti='..AiBotUtilities.GetDistanceBetweenPositions(oEngi:GetPosition(), oNearestCompletionArti:GetPosition())..'; oEngi[AiBotACU.refbTriedAndFailedToGetBuildRateUpgrade]='..tostring(oEngi[AiBotACU.refbTriedAndFailedToGetBuildRateUpgrade] or false)) end
                                                                    if oEngi:IsUnitState('Upgrading') then
                                                                        if AiBotUtilities.GetDistanceBetweenPositions(oEngi:GetPosition(), oNearestCompletionArti:GetPosition()) <= 25 then
                                                                            oSACUUpgradeToAssist = oEngi
                                                                            table.remove(tAvailableEngineers, iEngi)
                                                                            break
                                                                        end
                                                                    elseif not(oPotentialSACUToGetUpgrade) and not(oEngi[AiBotACU.refbTriedAndFailedToGetBuildRateUpgrade]) then
                                                                        local sUpgradeWanted = AiBotACU.GetUpgradeForSACU(oEngi, true, true)
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted='..(sUpgradeWanted or 'nil')) end
                                                                        if sUpgradeWanted and AiBotUtilities.GetDistanceBetweenPositions(oEngi:GetPosition(), oNearestCompletionArti:GetPosition()) <= 25 then
                                                                            oPotentialSACUToGetUpgrade = oEngi
                                                                            AiBotOrders.IssueTrackedEnhancement(oPotentialSACUToGetUpgrade, sUpgradeWanted, false, 'GETemUgr')
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Setting oPotentialSACUToGetUpgrade as this SACU') end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if oPotentialSACUToGetUpgrade then
                                                                --oSACUUpgradeToAssist = oPotentialSACUToGetUpgrade -dont set this yet, as want to be sure that the unit state is upgrading
                                                                for iEngi, oEngi in tAvailableEngineers do
                                                                    if oEngi == oSACUUpgradeToAssist then table.remove(tAvailableEngineers, iEngi) break end
                                                                end
                                                            end
                                                        end

                                                        --Assist this
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will assist the arti until completion unless we have oSACUUpgradeToAssist, oNearestCompletionArti='..oNearestCompletionArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionArti)..'; oSACUUpgradeToAssist='..(oSACUUpgradeToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSACUUpgradeToAssist) or 'nil')) end

                                                        local iMaxEngineers
                                                        --Limit engineers to just 1 if we are low on mass and have another active template which is further along, and this one still has quite a while to go
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to limit engis due to low mass, iHighestCompletionArti='..iHighestCompletionArti..'; Team has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Mass%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]) end
                                                        if iHighestCompletionArti < 0.6 and AiBotConditions.TeamHasLowMass(iTeam) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.025 then
                                                            local oNearestCompletionOtherArti
                                                            local iNearestCompletionOtherArti = iHighestCompletionArti --no point considering arti further from completion than this zone
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of other active templates empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]))) end
                                                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]) == false then
                                                                for iEntry, tOtherTableRef in AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates] do
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': is other table of arti units empty='..tostring(AiBotUtilities.IsTableEmpty(tOtherTableRef[AiBotMap.subrefGEArtiUnits]))) end
                                                                    if not(tOtherTableRef == tTableRef) and AiBotUtilities.IsTableEmpty(tOtherTableRef[AiBotMap.subrefGEArtiUnits]) == false then
                                                                        for iOtherArti, oOtherArti in tOtherTableRef[AiBotMap.subrefGEArtiUnits] do
                                                                            if bDebugMessages == true then if AiBotUnitInfo.IsUnitValid(oOtherArti) then LOG(sFunctionRef..': considering oOtherArti='..oOtherArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOtherArti)..'; Fraction complete='..oOtherArti:GetFractionComplete()) end end
                                                                            if AiBotUnitInfo.IsUnitValid(oOtherArti) and oOtherArti:GetFractionComplete() < 1 and oOtherArti:GetFractionComplete() > iNearestCompletionOtherArti then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': want to assist this other arti in priority to this template arti') end
                                                                                iNearestCompletionOtherArti = oOtherArti:GetFractionComplete()
                                                                                oNearestCompletionOtherArti = oOtherArti
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if want to save mass for other GE template, oNearestCompletionOtherArti='..(oNearestCompletionOtherArti.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionOtherArti) or 'nil')..'; iNearestCompletionOtherArti='..(iNearestCompletionOtherArti or 'nil')..'; iHighestCompletionArti='..iHighestCompletionArti) end
                                                            if oNearestCompletionOtherArti and not(oNearestCompletionOtherArti == oNearestCompletionArti) then
                                                                iMaxEngineers = 1
                                                            end

                                                        end
                                                        --GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTableRef, oUnit, iOptionalMax)
                                                        bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oSACUUpgradeToAssist or oNearestCompletionArti, iMaxEngineers)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Finished telling availalbe engineeres to assist the SACU or Arti, iMaxEngineers='..(iMaxEngineers or 'nil')..'; bClearAllEngineers='..tostring(bClearAllEngineers)) end
                                                        if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                                        --We have shielding and game-ender, do we have space for a second game-ender type unit (or T3 arti)?
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have available engineers and no arti to build or assist so want to start building a second (if its possible), iCompletedArti='..iCompletedArti..'; iArtiLocations='..iArtiLocations..'; bTriedBuildingSomething='..tostring(bTriedBuildingSomething)) end
                                                        if iCompletedArti < iArtiLocations and (iCompletedArti >= 1 or not(bTriedBuildingSomething)) and not(oNearestCompletionArti) then
                                                            --First check we have the mass to support                                                                                                        --GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, bOptionalReturnMassToCompleteOtherZoneUnderConstruction, iOptionalSearchRange, iOptionalCategoryFilter)
                                                            local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true,                                                      nil,            AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, false, iTemplateRef)

                                                            local bAvoidGameEnder = false
                                                            if (iOtherLandZonesWithExperimental or 0) > 0 and (iMassToComplete or 0) >= math.max(100000, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 0) * 2) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 200*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotConditions.TeamHasLowMass(iTeam)) and AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) <= 800 and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryGameEnder, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then bAvoidGameEnder = true end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to build another gameender unit from this template, iTeam='..(iTeam or 'nil')..'; iOtherLandZonesWithExperimental='..(iOtherLandZonesWithExperimental or 'nil')..'; iMassToComplete='..(iMassToComplete or 'nil')..'; Stored mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 'nil')..'; Gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Av mass%='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; bAvoidGameEnder='..tostring(bAvoidGameEnder)..'; P'..iPlateau..'Z'..iLandZone..'T'..iTemplateRef..' Time='..GetGameTimeSeconds()) end
                                                            if bAvoidGameEnder then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will reassess category to build as looks like we are building another gameender or similar in mass so dont want to start on another gameender') end
                                                                GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTemplateRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, false, true)
                                                            elseif (iOtherLandZonesWithExperimental or 0) == 0 or (iMassToComplete or 0) <= math.max(10000, 5000 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 0)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 800 or (iMassToComplete < 40000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and not(AiBotConditions.TeamHasLowMass(iTeam)))
                                                                    or (iMassToComplete <= 20000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 5000 and iOtherLandZonesWithExperimental <= 1) then

                                                                --Further check to avoid queuing up another unit if we are likely building a gameender
                                                                if iMassToComplete < math.max(50000, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] * 2) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 300 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3) or (iMassToComplete < 100000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 150) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.02 or (oFirstEngineer and oFirstEngineer:GetAIBrain()[AiBotEconomy.refbBuiltParagon])))  then
                                                                    --NOTE: IF CHANGING ABOVE THEN CHANGE THE SAME PLACE EARLIER IN CODE
                                                                    --Change the category to build if we have UEF and built a novax, or if we have high mass income on our team and we could be building a paragon
                                                                    if not(bHaveAlreadyTriedSwitchingCategoryForNovax) and oFirstUEF and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEArtiUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNovaxCentre, tTableRef[AiBotMap.subrefGEArtiUnits])) == false and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryNovaxCentre, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': We have a UEF engineer and havent yet reassessed GE category so will consider reassessing it') end
                                                                        GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTemplateRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, true, bAvoidGameEnder)
                                                                        bHaveAlreadyTriedSwitchingCategoryForNovax = true
                                                                    elseif oFirstAeon and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 600 and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryParagon, tLZTeamData[AiBotMap.refiLastGameEnderTemplateCategory]) then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': We have an Aeon engineer and high enough gross mass that we dont want paragon and the category to build contains a paragon, so will reassess') end
                                                                        GETemplateReassessGameEnderCategory(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, iTemplateRef, tTableRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer, true, bAvoidGameEnder)
                                                                    end
                                                                    GETemplateStartBuildingArtiOrGameEnder(tAvailableEngineers, tAvailableT3EngineersByFaction, tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, tTableRef, iTemplateRef, oFirstAeon, oFirstSeraphim, oFirstUEF, oFirstCybran, oFirstEngineer)
                                                                else
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': We are either trying to build a gameender or multiple T3 arti and arent close to overflowing mass, iMassToComplete='..iMassToComplete..'; iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..';  P'..iPlateau..'L'..iLandZone..'T'..iTemplateRef..' at time='..GetGameTimeSeconds()) end
                                                                end
                                                            elseif bDebugMessages == true then LOG(sFunctionRef..': Want to hold off getting another arti or equivalent for now')
                                                            end
                                                        end
                                                        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                                                            --If we have a shield part complete then assist it
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if anything we can assist, tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart]='..(tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] or 'nil')) end
                                                            if oNearestCompletionShield then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - assist shield as have got all the arti we can, nearest completion shield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)) end
                                                                bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionShield)
                                                                if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                                            elseif not(oNearestCompletionArti) and not(oDefenceToAssist) and not(oNearestCompletionShield) then
                                                                if not(bTriedBuildingSomething) or ((tTableRef[AiBotMap.subrefiCyclesWaitingForConstructionToStart] or 0) >= 30 and iCompletedArti >= iArtiLocations and iCompletedShields >= iShieldLocations) then
                                                                    --Check we have all the completed arti - we may just have decided to wait until we have more mass
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': If completed all arti and shields then flag we dont need engineers any more, iCompletedArti='..iCompletedArti..'; iArtiLocations='..iArtiLocations..'; iCompletedShields='..iCompletedShields) end
                                                                    if iCompletedArti >= iArtiLocations and iCompletedShields >= math.min(7,iShieldLocations) then
                                                                        --We have built all possible shields and arti/gameenders, so have no more use for engineers for this logic
                                                                        tTableRef[AiBotMap.subrefGEbDontNeedEngineers] = true
                                                                        local iAvailableEngiCount = table.getn(tAvailableEngineers)
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': we no longer want engineers; if we have lots still available then will disband some of them, size of tAvailableEngineers iAvailableEngiCount='..iAvailableEngiCount) end
                                                                        if iAvailableEngiCount >= 5 then
                                                                            for iCurEngiToRemove = iAvailableEngiCount, 6, -1 do
                                                                                local oEngiToRemove = tAvailableEngineers[iCurEngiToRemove]
                                                                                RemoveEngineerFromGETemplate(oEngiToRemove)
                                                                                table.remove(tAvailableEngineers)
                                                                                if AiBotUtilities.IsTableEmpty(tAvailableT3EngineersByFaction) == false then
                                                                                    for iFaction, tEngineersOfFaction in tAvailableT3EngineersByFaction do
                                                                                        for iFactionEngi, oFactionEngi in tEngineersOfFaction do
                                                                                            if oFactionEngi == oEngiToRemove then
                                                                                                table.remove(tAvailableT3EngineersByFaction[iFaction], iFactionEngi)
                                                                                                break
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bDisbandForPowerStall then
                                            local oEngiToRemove
                                            --Only remove if we have at least 2 engineers
                                            if tAvailableEngineers[2] then
                                                --Find the first non-SACU engineer (LOUD compatibility)
                                                for iEngi, oEngi in tAvailableEngineers do
                                                    if not(EntityCategoryContains(categories.SUBCOMMANDER, oEngi.UnitId)) then
                                                        oEngiToRemove = oEngi
                                                        break
                                                    end
                                                end
                                                if not(oEngiToRemove) then oEngiToRemove = tAvailableEngineers[1] end
                                                ClearEngineerTracking(oEngiToRemove)
                                            end
                                        end
                                        --Assist under construction arti if not stalling mass
                                        --[[if bDebugMessages == true then LOG(sFunctionRef..': Will assist any under construction arti or shield if not stalling mass or energy and still have engineers available. Is team stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) end
                                        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
                                            bClearAllEngineers = false
                                            if iUnderConstructionShields > 0 and (iCompletedShields < 5 or not(oNearestCompletionArti)) and oNearestCompletionShield then
                                                --Assist shield
                                                if bDebugMessages == true then LOG(sFunctionRef..': will get remaining engis to assist nearest completion shield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)) end
                                                bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionShield)
                                            elseif iUnderConstructionArti > 0 and oNearestCompletionArti then
                                                --Assist arti
                                                if bDebugMessages == true then LOG(sFunctionRef..': will get remaining engis to assist nearest completion arti='..oNearestCompletionArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionArti)) end
                                                bClearAllEngineers = GETemplateAssistUnit(tAvailableEngineers, tAvailableT3EngineersByFaction, iPlateau, iLandZone, iTemplateRef, oNearestCompletionArti)
                                                if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                            end
                                            if bClearAllEngineers then tAvailableEngineers = nil tAvailableT3EngineersByFaction = nil end
                                        end--]]
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to flag we no longer need engineers, iCompletedArti='..iCompletedArti..'; iArtiLocations='..iArtiLocations..'; bTriedBuildingSomething='..tostring(bTriedBuildingSomething)..'; is tAvailableEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableEngineers))..'; iCompletedShields='..iCompletedShields..'; iShieldLocations='..iShieldLocations..'; iUnderConstructionArti='..iUnderConstructionArti..'; iUnderConstructionShields='..iUnderConstructionShields..'; bDisbandForPowerStall='..tostring(bDisbandForPowerStall or false)..'; tTableRef[AiBotMap.subrefGEbDontNeedEngineers] before considering='..tostring(tTableRef[AiBotMap.subrefGEbDontNeedEngineers])) end
                        if AiBotUtilities.IsTableEmpty(tAvailableEngineers) == false then
                            if iCompletedArti >= iArtiLocations and not(bTriedBuildingSomething) and iCompletedShields >= iShieldLocations and iUnderConstructionArti == 0 and iUnderConstructionShields == 0 and not(bDisbandForPowerStall) then
                                tTableRef[AiBotMap.subrefGEbDontNeedEngineers] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': iCompletedArti='..iCompletedArti..'; iArtiLocations='..iArtiLocations..' so will abort the loop, iUnderConstructionArti='..iUnderConstructionArti..'; iUnderConstructionShields='..iUnderConstructionShields) end
                                break
                            else
                                --Consider having engineers other than the first assist something else nearby if dont have low mass
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering orders for idle engineers, TeamHasLowMass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; HaveLowPower='..tostring(AiBotConditions.HaveLowPower(iTeam))..'; Size of tAvailableEngineers='..table.getn(tAvailableEngineers)) end
                                if not(AiBotConditions.TeamHasLowMass(iTeam)) and not(AiBotConditions.HaveLowPower(iTeam)) and table.getn(tAvailableEngineers) >= 3 then

                                    local tUnitsToAssist, iClosestDist, iCurDist, oClosestUnitToAssist
                                    for iEngi, oEngi in tAvailableEngineers do
                                        if not(tUnitsToAssist) then
                                            if iEngi > 1 then break end --we didnt find something to assist before
                                            local tPotentialUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryExperimentalLevel, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                            if AiBotUtilities.IsTableEmpty(tPotentialUnits) == false then
                                                for iUnit, oUnit in tPotentialUnits do
                                                    if not(oUnit.Dead) then
                                                        if oUnit:GetFractionComplete() < 1 then
                                                            if not(tUnitsToAssist) then tUnitsToAssist = {} end
                                                            table.insert(tUnitsToAssist, oUnit)
                                                        elseif oUnit.GetWorkProgress and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) and oUnit:GetWorkProgress() > 0 then
                                                            if not(tUnitsToAssist) then tUnitsToAssist = {} end
                                                            table.insert(tUnitsToAssist, oUnit)
                                                        end
                                                    end
                                                end
                                            end
                                        else
                                            iClosestDist = 40 --dont want to get too far away; means a dist of this + 60 for experimentals
                                            oClosestUnitToAssist = nil
                                            for iUnitToAssist, oUnitToAssist in tUnitsToAssist do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnitToAssist:GetPosition(), oEngi:GetPosition())
                                                if (oUnitToAssist.refiUnitMassCost or AiBotUnitInfo.GetUnitMassCost(oUnitToAssist)) >= 6000 then
                                                    iCurDist = iCurDist - 60 --want to prioritise nearby experimentals and high valeu buildings over other units; land t3 hq is 5.2k mass
                                                end
                                                if iCurDist < iClosestDist then
                                                    oClosestUnitToAssist = oUnitToAssist
                                                    iClosestDist = iCurDist
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; oClosestUnitToAssist='..(oClosestUnitToAssist or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToAssist) or 'nil')) end
                                            if oClosestUnitToAssist then
                                                if bDebugMessages == true then LOG(sFunctionRef..': oClosestUnitToAssist fraction complete='..oClosestUnitToAssist:GetFractionComplete()) end
                                                if oClosestUnitToAssist:GetFractionComplete() < 1 then
                                                    AiBotOrders.IssueTrackedRepair(oEngi, oClosestUnitToAssist, false, 'GETIdlAssP'..iPlateau..'Z'..iLandZone..'T'..iTemplateRef, false)
                                                else
                                                    AiBotOrders.IssueTrackedGuard(oEngi, oClosestUnitToAssist, false, 'GETIdlAGrP'..iPlateau..'Z'..iLandZone..'T'..iTemplateRef, false)
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': We dont have a first engineer')
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont have engineers') end
                end

                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            else
                --No valid units so should abort the loop
                if bDebugMessages == true then LOG(sFunctionRef..': have no valid units so will abort, P='..iPlateau..'Z='..iLandZone..'T='..iTemplateRef) end
                break
            end
        end
        
        --END OF LOOP (i.e. have exited from loop):
        if bDebugMessages == true then LOG(sFunctionRef..': Aborting loop at time='..GetGameTimeSeconds()..', is table of engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))..'; tTableRef[AiBotMap.subrefGEbDontNeedEngineers]='..tostring(tTableRef[AiBotMap.subrefGEbDontNeedEngineers])..'; P'..iPlateau..'Z'..iLandZone..'T'..iTemplateRef..'; Time='..GetGameTimeSeconds()) end
        if tTableRef[AiBotMap.subrefGEbDontNeedEngineers] and AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]) == false then
            for iEngineer, oEngineer in tTableRef[AiBotMap.subrefGEEngineers] do
                if bDebugMessages == true then LOG(sFunctionRef..': We dont want any more engineers for this template ref, iTemplateRef='..iTemplateRef..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Clearing flag for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Time='..GetGameTimeSeconds()) end
                RemoveEngineerFromGETemplate(oEngineer)
            end
        end
        tTableRef[AiBotMap.subrefGEbActiveMonitor] = false
    end


    if not(tTableRef[AiBotMap.subrefGEbActiveMonitor]) then --v77 - had issues with the main loop being called repeatedly and engineers not being given orders, suspect this was the cause, but this was added due to issues with engineers staying stuck on GE duty, so might need to consider further if run into issues again
        --Redundancy - clear engineers
        if bDebugMessages == true then LOG(sFunctionRef..': Extra check, is table of engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))) end
        if AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]) == false then
            for iEngineer, oEngineer in tTableRef[AiBotMap.subrefGEEngineers] do
                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy for clearing engineers for this template ref, iTemplateRef='..iTemplateRef..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Clearing flag for engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Time='..GetGameTimeSeconds()) end
                if AiBotUnitInfo.IsUnitValid(oEngineer) then
                    RemoveEngineerFromGETemplate(oEngineer)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for template '..iTemplateRef..' at time='..GetGameTimeSeconds()..'; tTableRef[AiBotMap.subrefGEbActiveMonitor]='..tostring(tTableRef[AiBotMap.subrefGEbActiveMonitor] or false)..'; bCallAgainAfterDelay='..tostring(bCallAgainAfterDelay or false)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bCallAgainAfterDelay then
        WaitSeconds(20)
        ForkThread(GameEnderTemplateManager, tLZData, tLZTeamData, iTemplateRef, iPlateau, iLandZone, iTeam)
    end
end

function DelayedAddEngiToTemplateRef(tLZTeamData, iTemplateRef, oEngineer, iTicksToDelay)
    WaitTicks(iTicksToDelay)
    if AiBotUnitInfo.IsUnitValid(oEngineer) then
        if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]) then tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers] = {} end
        table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers], oEngineer)
        if EntityCategoryContains(categories.SUBCOMMANDER, oEngineer.UnitId) then
            tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEbSACUAssigned] = true
        end
    end
end


function RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTemplateRef, tOptionalLZTeamData, bAddedToNewTemplate)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordEngineerAsPartofGameEnderTemplate'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iCurPriority = (oEngineer[refiAssignedActionPriority] or 1)
    local tLZTeamData = tOptionalLZTeamData
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oEngineer='..(oEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineer) or 'nil')..'; is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer))) end
    if not(tOptionalLZTeamData) then tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam] end

    --If engineer already has a GE template assigned, then remove it from that table
    if AiBotUtilities.IsTableEmpty(oEngineer[AiBotBuilding.reftArtiTemplateRefs]) == false then
        local tCurTemplateRef = AiBotMap.tAllPlateaus[oEngineer[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oEngineer[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.reftActiveGameEnderTemplates][oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]]
        if AiBotUtilities.IsTableEmpty(tCurTemplateRef[AiBotMap.subrefGEEngineers]) == false then
            for iRecordedEngi, oRecordedEngi in tCurTemplateRef[AiBotMap.subrefGEEngineers] do
                if oRecordedEngi == oEngineer then
                    if bDebugMessages == true then LOG(sFunctionRef..': removing oRecordedEngi='..oRecordedEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedEngi)..' from table P'..oEngineer[AiBotBuilding.reftArtiTemplateRefs][1]..'L'..oEngineer[AiBotBuilding.reftArtiTemplateRefs][2]..'T'..oEngineer[AiBotBuilding.reftArtiTemplateRefs][3]) end
                    break
                end
            end
        end
    end


    --Clear engineer orders to avoid it carrying on an order it previously had and that unit being treated as a GE template unit
    if not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) or not(EntityCategoryContains(AiBotUnitInfo.refCategoryRASSACU, oEngineer.UnitId)) then
        if bDebugMessages == true then LOG(sFunctionRef..': Cleaing engineer orders so it is available for orders for the GE template, oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
        AiBotOrders.IssueTrackedClearCommands(oEngineer)
    end
    --Clear engineer current tracking incase it's assigned to another GE template table
    ClearEngineerTracking(oEngineer)

    ForkThread(DelayedAddEngiToTemplateRef, tLZTeamData, iTemplateRef, oEngineer, 1) --Not sure actually need this delayed - had what seemed an infinite loop, but this didnt actually fix the infinite loop and there was a separate issue where this function was being called every time an engineer was given an assist order; could look at moving this back to an immediate action in the future

    if bDebugMessages == true then LOG(sFunctionRef..': Done forked thread to add engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to table of engineers for iTempalteRef='..iTemplateRef..'; bAddedToNewTemplate='..tostring(bAddedToNewTemplate)..'; Is table of engineers empty for template ref='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]))) end
    oEngineer[AiBotBuilding.reftArtiTemplateRefs] = {iPlateau, iLandZone, iTemplateRef}
    if bAddedToNewTemplate then
        --Set priority to 1 so it is hopefully less likely to be overwritten
        oEngineer[refbPrimaryBuilder] = true
        oEngineer[refiAssignedActionPriority] = 1
        local tTableRef = tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef]
        --Record engineer as being part of shield SACUs if it is a UEF shield SACU and we have flagged we want to use shieldSACU logic
        if EntityCategoryContains(categories.UEF * categories.SUBCOMMANDER, oEngineer.UnitId) and tLZTeamData[AiBotMap.subrefbGEShieldSACU] and not(oEngineer[AiBotUnitInfo.refbEasyBrain]) then
            local bRecordedAlready = false
            if not(tTableRef[AiBotMap.subreftoGEShieldSACUs]) then tTableRef[AiBotMap.subreftoGEShieldSACUs] = {}
            else
                for iSACU, oSACU in tTableRef[AiBotMap.subreftoGEShieldSACUs] do
                    if oSACU == oEngineer then bRecordedAlready = true break end
                end
            end
            if not(bRecordedAlready) then
                table.insert(tTableRef[AiBotMap.subreftoGEShieldSACUs], oEngineer)
                if not(tTableRef[AiBotMap.subrefbActiveShieldSACUCycling]) then
                    local iRecordedSACUs = table.getn(tTableRef[AiBotMap.subreftoGEShieldSACUs])
                    if iRecordedSACUs >= 2 then
                        ForkThread(AiBotBuilding.MonitorSACUShieldsForCycling, tTableRef, oEngineer:GetAIBrain().AiBotTeam, iLandZone, iTemplateRef)
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': subrefGEbActiveMonitor for template='..tostring(tTableRef[AiBotMap.subrefGEbActiveMonitor] or false)..'; is subrefGEEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(tTableRef[AiBotMap.subrefGEEngineers]))) end
        if not(tTableRef[AiBotMap.subrefGEbActiveMonitor]) then
            ForkThread(DelayedGEManagerCheck,AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone], tLZTeamData, iTemplateRef, iPlateau, iLandZone, oEngineer:GetAIBrain().AiBotTeam)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': About to track engineer action') end
    TrackEngineerAction(oEngineer, refActionManageGameEnderTemplate, oEngineer[refbPrimaryBuilder], iCurPriority, nil, nil, false)
    if bDebugMessages == true then LOG(sFunctionRef..': End of code at time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignEngineerToGameEnderTemplate(oEngineer, tLZData, tLZTeamData, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignEngineerToGameEnderTemplate'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Will find a gameender tempalte for oEngineer to join, or create a new one if there's no active one
    if bDebugMessages == true then LOG(sFunctionRef..': About to assign engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' to gameendertemplate for iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Engi team='..oEngineer:GetAIBrain().AiBotTeam) end
    local iTemplateRef
    local bAddedToNewTemplate = false
    --Work out the template ref that we will be assisting, or create a new one if we have none
    --Do we have an active gameendertemplate
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then
        for iEntry, tSubtable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iTemplateRef='..iEntry..'; Does it no longer need engis='..tostring(tSubtable[AiBotMap.subrefGEbDontNeedEngineers])..'; Has it failed ot get an arti location='..tostring(tSubtable[AiBotMap.subrefbFailedToGetArtiLocation])..'; Is table of arti units empty='..tostring(AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEArtiUnits]))) end
            if not(tSubtable[AiBotMap.subrefGEbDontNeedEngineers]) then
                if tSubtable[AiBotMap.subrefbFailedToGetArtiLocation] then
                    --Do we have any under construction units in this template?
                    local bHaveUnderConstruction = false
                    if AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEArtiUnits]) == false then
                        for iUnit, oUnit in tSubtable[AiBotMap.subrefGEArtiUnits] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 then
                                bHaveUnderConstruction = true
                                break
                            end
                        end
                    end
                    if not(bHaveUnderConstruction) and AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEShieldUnits]) == false then
                        for iUnit, oUnit in tSubtable[AiBotMap.subrefGEShieldUnits] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 then
                                bHaveUnderConstruction = true
                                break
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': We failed to get arti location to build on for this template ref; bHaveUnderConstruction='..tostring(bHaveUnderConstruction)) end
                    if bHaveUnderConstruction then
                        --Reset the flag for being unable to build
                        tSubtable[AiBotMap.subrefbFailedToGetArtiLocation] = false
                        iTemplateRef = iEntry
                        break
                    end
                else
                    iTemplateRef = iEntry
                    break
                end


            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': iTemplateRef after checking active templates='..(iTemplateRef or 'nil')) end
    if not(iTemplateRef) then
        bAddedToNewTemplate = true
        function AddBaseTableToLZTeamData(tBaseTable)
            local bProceed = true
            local tNewMidpoint = GetBuildingMidpointPositionFromPathingSegments(tBaseTable[AiBotMap.subrefiSegX], tBaseTable[AiBotMap.subrefiSegZ])
            if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) then
                tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] = {}
            else
                --Check we havent already recorded and have flagged it as not needing engineers
                for iExistingTable, tExistingTable in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                    if tExistingTable[AiBotMap.subrefGEMidpoint][1] == tNewMidpoint[1] and tExistingTable[AiBotMap.subrefGEMidpoint][3] == tNewMidpoint[3] then
                        bProceed = false
                        if not(tExistingTable[AiBotMap.subrefGEbDontNeedEngineers]) or not(tExistingTable[AiBotMap.subrefbFailedToGetArtiLocation]) then
                            iTemplateRef = iExistingTable
                        else
                            --We thought we had a valid location but turns out we dont; check if this is the location of a base template, and if so then clear that base template so we dont repeat this issue
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment]) == false then
                                if tBaseTable[AiBotMap.subrefiSegX] == tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment][AiBotMap.subrefiSegX] and tBaseTable[AiBotMap.subrefiSegZ] == tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment][AiBotMap.subrefiSegZ] then
                                    AiBotUtilities.ErrorHandler('Have recorded a failed attempt to build at a backup location so will clear the backup location', true)
                                    tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment] = nil
                                end
                            end

                        end
                        break
                    end
                end
            end
            if bProceed then
                --Work out if we have sera or UEF T3 engis in this zone
                local tSeraAndUEFT3Engis = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer * categories.UEF * categories.TECH3 + AiBotUnitInfo.refCategoryEngineer * categories.SERAPHIM * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local bHaveLargeShields = not(AiBotUtilities.IsTableEmpty(tSeraAndUEFT3Engis))
                local tArtiLocations, tShieldLocations, tDefensiveLocations
                local iMaxArtiSize
                if bHaveLargeShields then
                    tArtiLocations = tBaseTable[AiBotMap.subreftLargeArtiLocations]
                    tShieldLocations = tBaseTable[AiBotMap.subreftLargeShieldLocations]
                    tDefensiveLocations = tBaseTable[AiBotMap.subreftLargeShieldDefenceLocations]
                    iMaxArtiSize = tBaseTable[AiBotMap.subrefiLargeArtiMaxSize]
                else
                    tArtiLocations = tBaseTable[AiBotMap.subreftSmallArtiLocations]
                    tShieldLocations = tBaseTable[AiBotMap.subreftSmallShieldLocations]
                    tDefensiveLocations = tBaseTable[AiBotMap.subreftSmallShieldDefenceLocations]
                    iMaxArtiSize = tBaseTable[AiBotMap.subrefiSmallArtiMaxSize]
                end


                table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates], {
                    [AiBotMap.subrefGEMidpoint] = {tNewMidpoint[1], tNewMidpoint[2], tNewMidpoint[3]},
                    [AiBotMap.subrefGESize] = tBaseTable[AiBotMap.subrefiSize],
                    [AiBotMap.subrefGEArtiLocations] = {},
                    [AiBotMap.subrefGEShieldLocations] = {},
                    [AiBotMap.subrefGEArtiUnits] = {},
                    [AiBotMap.subrefGEShieldUnits] = {},
                    [AiBotMap.subrefGEEngineers] = {},
                    [AiBotMap.subrefGEbActiveMonitor] = false,
                    [AiBotMap.subrefGEbDontNeedEngineers] = false,
                    [AiBotMap.subrefbFailedToGetArtiLocation] = false,
                    [AiBotMap.subrefGEbActiveShieldMonitor] = false,
                    [AiBotMap.subrefiCyclesWaitingForEngineer] = 0,
                    [AiBotMap.subrefiCyclesWaitingForConstructionToStart] = 0,
                    [AiBotMap.subrefiMaxArtiSkirtSize] = iMaxArtiSize
                })
                iTemplateRef = table.getn(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates])
                local iSurfaceHeight
                for _, tLocation in tArtiLocations do
                    iSurfaceHeight = tLocation[2]
                    if iSurfaceHeight == 0 then iSurfaceHeight = GetSurfaceHeight(tLocation[1], tLocation[3]) end
                    table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations], {tLocation[1], iSurfaceHeight, tLocation[3]})
                end
                for _, tLocation in tShieldLocations do
                    iSurfaceHeight = tLocation[2]
                    if iSurfaceHeight == 0 then iSurfaceHeight = GetSurfaceHeight(tLocation[1], tLocation[3]) end
                    table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEShieldLocations], {tLocation[1], iSurfaceHeight, tLocation[3]})
                end
                --Add SMD to the last shield location, if we can build there, and if we have access to UEF or Seraphim shielding (since Cybran and Aeon shields are too small to cover SMD)
                if bHaveLargeShields then
                    local tLastShield = tShieldLocations[table.getn(tShieldLocations)]
                    local tPotentialSMDLocation = {tLastShield[1] + 4.5, 0, tLastShield[3] - 1.5}
                    tPotentialSMDLocation[2] = GetSurfaceHeight(tPotentialSMDLocation[1], tPotentialSMDLocation[3])
                    if oEngineer:GetAIBrain():CanBuildStructureAt('ueb4302', tPotentialSMDLocation) then
                        tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGESMDLocation] = {tPotentialSMDLocation[1], tPotentialSMDLocation[2], tPotentialSMDLocation[3]}
                    end
                end
                if tDefensiveLocations then
                    tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEAvailableDefenceLocations] = {}
                    for _, tLocation in tDefensiveLocations do
                        iSurfaceHeight = tLocation[2]
                        if iSurfaceHeight == 0 then iSurfaceHeight = GetSurfaceHeight(tLocation[1], tLocation[3]) end
                        table.insert(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEAvailableDefenceLocations], {tLocation[1], iSurfaceHeight, tLocation[3]})
                    end
                end



                if bDebugMessages == true then
                    local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tNewMidpoint)
                    LOG(sFunctionRef..': Have just added a new active gameendertemplate table to iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Size of gameendertemplates table='..table.getn(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates])..'; Arti locations='..repru(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations])..'; Largest build location pre blacklist for the midpoint segments='..(tLZTeamData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSegmentX][iSegmentZ] or 'nil')..'; tPotentialSMDLocation='..repru(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGESMDLocation])..'; bHaveLargeShields='..tostring(bHaveLargeShields or false)..'; Shield locations='..repru(tShieldLocations)..'; Template size='..tBaseTable[AiBotMap.subrefiSize]..'; Midpoint='..repru(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEMidpoint])..'; Playable area='..repru(AiBotMap.rMapPlayableArea)..'; will draw midpoint')
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEMidpoint]) == false then
                        AiBotUtilities.DrawLocation(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEMidpoint])
                    end
                end


                --Set a blacklist for this location
                RecordBlacklistLocation(tNewMidpoint, tBaseTable[AiBotMap.subrefiSize] + 1, 600)
                --Update buildable areas around here
                CheckIfBuildableLocationsNearPositionStillValid(oEngineer:GetAIBrain(), tNewMidpoint, true, tBaseTable[AiBotMap.subrefiSize])
                table.insert(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.tPotentiallyActiveGETemplates], tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef])
                if bDebugMessages == true then
                    local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tNewMidpoint)
                    LOG(sFunctionRef..': Post blacklist and checking buildable locations, largest build location for the midpoint segments='..(tLZTeamData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSegmentX][iSegmentZ] or 'nil')..'; is tPotentiallyActiveGETemplates empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.tPotentiallyActiveGETemplates])))
                end
            end
        end

        --See if we have somewhere in this zone we can build a template without needing to reclaim any buildings
        local tiSizesToConsider = {26,24,22} --If changing, then update similar in AiBotEngineer AssignEngineerToGameEnderTemplate
        local iPreferredSegX, iPreferredSegZ, iPreferredSize, sCurBP, iCurRadius
        local iCurDistToEnemyBase
        local iFurtherstDistToEnemyBase = 0

        --First check if we currently have any locations in the zone still available, in which case we dont need to reclaim anything and can just use this (picking hte largest size locaiton, that is furthest from the enemy base)
        local iPlayableSizeRadius
        for _, iCurSize in tiSizesToConsider do
            iPlayableSizeRadius = iCurSize * 0.5 + 0.5
            if bDebugMessages == true then LOG(sFunctionRef..': Is table for size '..iCurSize..' empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iCurSize]))) end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iCurSize]) == false then
                sCurBP = tsBlueprintsBySize[iCurSize]
                iCurRadius = iCurSize * 0.5
                for iSegX, tSubtable in tLZData[AiBotMap.subrefBuildLocationsBySizeAndSegment][iCurSize] do
                    for iSegZ, bValid in tSubtable do
                        local tCurMidpoint = GetBuildingMidpointPositionFromPathingSegments(iSegX, iSegZ)
                        iCurDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tCurMidpoint, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                        if iCurDistToEnemyBase > iFurtherstDistToEnemyBase then
                            --Check we can actually build here, taking into account resource deposits
                            if not(IsBuildLocationBlockedByResources(tLZData, iCurRadius, GetBuildingMidpointPositionFromPathingSegments(iSegX, iSegZ), true)) then
                                --Check we are in the payable area
                                if tCurMidpoint[1] - iPlayableSizeRadius >= AiBotMap.rMapPlayableArea[1] and  tCurMidpoint[3] - iPlayableSizeRadius >= AiBotMap.rMapPlayableArea[2] and tCurMidpoint[1] + iPlayableSizeRadius <= AiBotMap.rMapPlayableArea[3] and tCurMidpoint[3] + iPlayableSizeRadius <= AiBotMap.rMapPlayableArea[4] then
                                    iFurtherstDistToEnemyBase = iCurDistToEnemyBase
                                    iPreferredSize = iCurSize
                                    iPreferredSegX = iSegX
                                    iPreferredSegZ = iSegZ
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': had thought we had a valid build location but it is outside the playable area, tCurMidpoint='..repru(tCurMidpoint)..'; rMapPlayableArea='..repru(AiBotMap.rMapPlayableArea)..'; iCurSize='..iCurSize) end
                                end
                            elseif bDebugMessages == true then LOG(sFunctionRef..': Segment X'..iSegX..'Z'..iSegZ..' is blocked by resources so will ignore')
                            end
                        end
                    end
                end
            end
            if iPreferredSize then break end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iPreferredSize after checking if have large enough locatino to build with no relcaiming='..(iPreferredSize or 'nil')) end
        if iPreferredSize then
            --Add this location to the LZTeamData - need to work out where each building will go
            local tMidpoint = GetBuildingMidpointPositionFromPathingSegments(iPreferredSegX, iPreferredSegZ)
            local tBaseTable = AiBotMap.AddGameEnderTemplateInfoToTable(tMidpoint, iPreferredSize)
            AddBaseTableToLZTeamData(tBaseTable)

        else
            --We dont have anywhere we can build based on current buildable locations; see if we recorded a valid location at the start of the game that we can use instead
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment]) == false then
                --Add this location to the LZTeamData
                AddBaseTableToLZTeamData(tLZData[AiBotMap.subrefGameEnderTemplateBackupLocationSizeAndSegment])
                if bDebugMessages == true then LOG(sFunctionRef..': Have just added the backup location to the gameender active table, iTemplateRef='..(iTemplateRef or 'nil')) end
            end

        end
    end

    if iTemplateRef then

        local bAddEngineer = true
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers]) == false then
            for iRecordedEngineer, oRecordedEngineer in tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEEngineers] do
                if oRecordedEngineer == oEngineer then bAddEngineer = false break end
            end
        end
        if bAddEngineer then
            RecordEngineerAsPartofGameEnderTemplate(oEngineer, iPlateau, iLandZone, iTemplateRef, tLZTeamData, true)
        end
        if bDebugMessages == true then
            LOG(sFunctionRef..': Will start a manager for this zone if we dont already have one, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; arti locations='..repru(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations])..'; iTemplateRef='..(iTemplateRef or 'nil')..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Brain owner='..oEngineer:GetAIBrain().Nickname..'; tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEbActiveMonitor]='..tostring(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEbActiveMonitor] or false))
            if iTemplateRef and not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations][1])) then
                AiBotUtilities.DrawLocation(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEArtiLocations][1])
            end
        end
        if not(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates][iTemplateRef][AiBotMap.subrefGEbActiveMonitor]) then
            local iTeam
            if AiBotUnitInfo.IsUnitValid(oEngineer) then iTeam = oEngineer:GetAIBrain().AiBotTeam end
            ForkThread(GameEnderTemplateManager, tLZData, tLZTeamData, iTemplateRef, iPlateau, iLandZone, iTeam)
        end
    else
        AiBotUtilities.ErrorHandler('Couldnt find a gameender template for engineer to assist so will clear its orders')
        if not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) then
            AiBotOrders.IssueTrackedClearCommands(oEngineer)
        end
        ClearEngineerTracking(oEngineer)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderEmergencyPDReassignment(oEngiGivenPDOrder, tLZData, tLZMidpoint, iPlateau, iLandZone, tLZTeamData)
    --If an engineer is given a build order for emergency PD, this should also be called via a fork thread; want to add to table of units in the zone for emergency PD so can monitor
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderEmergencyPDReassignment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oEngiGivenPDOrder='..(oEngiGivenPDOrder.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngiGivenPDOrder) or 'nil')) end
    if AiBotUnitInfo.IsUnitValid(oEngiGivenPDOrder) then
        --Add to table if not already there
        local bAlreadyRecorded = false
        if not(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]) then
            tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers] = {}
        else
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]) == false then
                for iEngi, oEngi in tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers] do
                    if oEngi == oEngiGivenPDOrder then bAlreadyRecorded = true break end
                end
            end
        end
        if not(bAlreadyRecorded) then table.insert(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers], oEngiGivenPDOrder) end
        if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic]='..tostring(tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic] or false)..'; Is table of emergency PD engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]))) end
        if not(tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic]) then
            tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic] = true
            local aiBrain = oEngiGivenPDOrder:GetAIBrain()
            local iTimeStartedMonitoring = GetGameTimeSeconds()

            local iClosestEngiToTarget, iCurDist
            local iTableSize
            local bT2PlusConstructionStarted
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(3)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, is table of emergency PD engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]))..'; refiTimeLastCompletedPD='..((tLZTeamData[AiBotMap.refiTimeLastCompletedPD] or 'nil'))) end
            while AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]) == false do
                --Update the table of engineers, removing any who no longer have an emergency PD order, or are dead
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(2)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                if iTimeStartedMonitoring < (tLZTeamData[AiBotMap.refiTimeLastCompletedPD] or 0) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have finished constructing a PD while we have been waiting so aborting logic') end
                    break
                end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]) == false then
                    iClosestEngiToTarget = 10000
                    local tbEngisToRemove = {}
                    iTableSize = table.getn(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers])
                    if bDebugMessages == true then LOG(sFunctionRef..': About to loop through every engineer and check if it should be removed from emergency PD engineers, iTableSize='..iTableSize..'; Time='..GetGameTimeSeconds()) end
                    for iCurEngi = iTableSize, 1, -1 do
                        local oEngi = tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iCurEngi]
                        if not(AiBotUnitInfo.IsUnitValid(oEngi)) or not(oEngi[refiAssignedAction] == refActionBuildEmergencyPD or oEngi[refiAssignedAction] == refActionBuildSecondPD) or AiBotUtilities.IsTableEmpty(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]) then
                            tbEngisToRemove[iCurEngi] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': engineer '..(oEngi.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngi) or 'nil')..' is either invalid, doesnt have an action to build emergency PD, or its last order doesnt have an order position, oEngi[refiAssignedAction]='..(oEngi[refiAssignedAction] or 'nil')..'; Last order position='..repru(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])) end
                        else
                            --Are we building? if so then remove all engis building at the same location
                            if oEngi:IsUnitState('Building') or oEngi:IsUnitState('Repairing') then
                                if bDebugMessages == true then LOG(sFunctionRef..': Engineer is building or repairing, oEngi='..(oEngi.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngi) or 'nil')) end
                                tbEngisToRemove[iCurEngi] = true
                                --Remove all other units trying to build at the same location
                                local oUnitTarget = oEngi:GetFocusUnit()
                                if oUnitTarget then
                                    if bDebugMessages == true then LOG(sFunctionRef..': oUnitTarget='..(oUnitTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitTarget) or 'nil')..'; Tech level='..AiBotUnitInfo.GetUnitTechLevel(oUnitTarget)) end
                                    if AiBotUnitInfo.GetUnitTechLevel(oUnitTarget) >= 2 then bT2PlusConstructionStarted = true end
                                    for iSecondEngi = iTableSize, 1, -1 do
                                        if not(tbEngisToRemove[iSecondEngi]) then
                                            if bT2PlusConstructionStarted then
                                                tbEngisToRemove[iSecondEngi] = true
                                            else
                                                local oSecondEngi = tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iSecondEngi]
                                                if not(AiBotUnitInfo.IsUnitValid(oSecondEngi)) or not(oSecondEngi[refiAssignedAction] == refActionBuildEmergencyPD or oSecondEngi[refiAssignedAction] == refActionBuildSecondPD) then
                                                    tbEngisToRemove[iSecondEngi] = true
                                                else
                                                    --Is second engi trying to build at same location?
                                                    local tLastOrder = oSecondEngi[AiBotOrders.reftiLastOrders][oSecondEngi[AiBotOrders.refiOrderCount]]
                                                    if tLastOrder[AiBotOrders.subrefsOrderBlueprint] and tLastOrder[AiBotOrders.subrefsOrderBlueprint] == oUnitTarget.UnitId and AiBotUtilities.GetDistanceBetweenPositions(oUnitTarget:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= 1.4 then
                                                        tbEngisToRemove[iSecondEngi] = true
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            elseif bDebugMessages == true then LOG(sFunctionRef..': Engi state isnt building or repairing, Engi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi))
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tbEngisToRemove) == false then
                        for iCurEngi = iTableSize, 1, -1 do
                            if tbEngisToRemove[iCurEngi] then
                                if bDebugMessages == true then LOG(sFunctionRef..': Removing engineer '..(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iCurEngi].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iCurEngi]) or 'nil')..' from table of engis building emergency PD, engi last order blueprint='..(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iCurEngi][AiBotOrders.reftiLastOrders][tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers][iCurEngi][AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')) end
                                table.remove(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers], iCurEngi)
                            end
                        end
                    end

                    --If we still have engis, then determine the closest to the target, if it is far away the reassess the build location
                    if bDebugMessages == true then LOG(sFunctionRef..': Do we still have engineers building emergency PD? is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]))) end
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers]) == false then
                        local tClosestTarget, oClosestEngi
                        for iEngi, oEngi in tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers] do
                            if AiBotUnitInfo.IsUnitValid(oEngi) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEngi:GetPosition(), oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])
                                if iCurDist < iClosestEngiToTarget then
                                    iClosestEngiToTarget = iCurDist
                                    local tEngiTarget = oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]
                                    tClosestTarget = {tEngiTarget[1], tEngiTarget[2], tEngiTarget[3]}
                                    oClosestEngi = oEngi
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iClosestEngiToTarget='..iClosestEngiToTarget..'; Time='..GetGameTimeSeconds()) end
                        local bGotNewOrderOrLocation = false
                        function ReassessPDBuildLocation()
                            local sBlueprint, tAltPDLocation = GetBlueprintAndLocationToBuild(aiBrain, oClosestEngi, refActionBuildEmergencyPD, AiBotUnitInfo.refCategoryPD, oClosestEngi:GetBlueprint().Economy.MaxBuildDistance, nil, oClosestEngi:GetPosition(), false, nil, nil, false, tLZData, tLZTeamData, true, oClosestEngi[AiBotOrders.reftiLastOrders][oClosestEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint])
                            if bDebugMessages == true then LOG(sFunctionRef..': tAltPDLocation='..repru(tAltPDLocation)..'; tClosestTarget='..repru(tClosestTarget)..'; Dist between them='..AiBotUtilities.GetDistanceBetweenPositions(tClosestTarget, (tAltPDLocation or {0,0,0}))) end
                            if AiBotUtilities.IsTableEmpty(tAltPDLocation) == false and sBlueprint == oClosestEngi[AiBotOrders.reftiLastOrders][oClosestEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] then
                                --Reassign all engineers with the same target
                                if bDebugMessages == true then LOG(sFunctionRef..': Will reassign all engineers with the same target, tClosestTarget='..repru(tClosestTarget)) end
                                local toEngineersToReassign = {}
                                for iEngi, oEngi in tLZTeamData[AiBotMap.subreftoEmergencyPDEngineers] do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if engineer shoudl be reassigned due to being close to the closeset enti to target build location, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Dist to order position='..AiBotUtilities.GetDistanceBetweenPositions(tClosestTarget, oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])..'; Order position='..repru(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(tClosestTarget, oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]) <= 1.5 then
                                        AiBotOrders.IssueTrackedBuild(oEngi, tAltPDLocation, sBlueprint, false, 'RedoEmPD')
                                        TrackEngineerAction(oEngi, refActionBuildEmergencyPD, true, 1, nil, nil, false)
                                    end
                                end
                                bGotNewOrderOrLocation = true
                            end
                        end
                        if oClosestEngi and iClosestEngiToTarget <= 10 then
                            --If the desired build location has mobile units in it, then get a new build location
                            local rRect = AiBotUtilities.GetRectAroundLocation(tClosestTarget, 1)
                            local tUnitsAtTarget = GetUnitsInRect(rRect)
                            if bDebugMessages == true then LOG(sFunctionRef..': Are there units around the target? is table empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsAtTarget))) end
                            if AiBotUtilities.IsTableEmpty(tUnitsAtTarget) == false then
                                local tPDInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tUnitsAtTarget)
                                local oPartCompletePD
                                --local iClosestCompletion = 0
                                if AiBotUtilities.IsTableEmpty(tPDInRect) == false then
                                    for iCurPD, oCurPD in tPDInRect do
                                        if oCurPD:GetFractionComplete() < 1 then
                                            --if oPartCompletePD:GetFractionComplete() > iClosestCompletion then
                                            oPartCompletePD = oCurPD
                                            break
                                            --iClosestCompletion = oPartCompletePD:GetFractionComplete()
                                            --end
                                        end
                                    end
                                end
                                if oPartCompletePD then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have part complete PD under construction so wont change engineer orders') end
                                    bGotNewOrderOrLocation = true
                                else
                                    local bHaveMobileUnits = false
                                    for iUnitInRect, oUnitInRect in tUnitsAtTarget do
                                        if EntityCategoryContains(categories.MOBILE, oUnitInRect.UnitId) then
                                            bHaveMobileUnits = true
                                            break
                                        end
                                    end
                                    if bHaveMobileUnits then
                                        ReassessPDBuildLocation()
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have any mobile units in the target rectangle so will proceed with current orders') end
                                    end
                                end
                            end
                        end
                        if not(bGotNewOrderOrLocation) and iClosestEngiToTarget >= 10 and iClosestEngiToTarget <= 75 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false or tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] > 0) then
                            --Are there enemies close to the target, and we are moderately far away? in which case also reassess
                            local oEngiToConsider
                            if AiBotUnitInfo.IsUnitValid(oEngiGivenPDOrder) then oEngiToConsider = oEngiGivenPDOrder
                            else oEngiToConsider = oClosestEngi
                            end

                            local iTeam = oEngiToConsider:GetAIBrain().AiBotTeam
                            local bCloseToEnemy = AiBotConditions.CloseToEnemyUnit(tClosestTarget, tLZTeamData[AiBotMap.reftoNearestDFEnemies], 10, iTeam, true, nil, nil, oEngiToConsider, nil, false)
                            --(Left in code re seeing if close to PD in case decide want to use this, but would need to re-review as prev it referred to oEngiGivenPDOrder, and have now changed to oEngiToConsider)
                            --local bCloseToPD = false
                            --if bCloseToEnemy and oEngiToConsider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] and EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oEngiToConsider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck].UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oEngiToConsider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition(), tClosestTarget) <= oEngiToConsider[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck][AiBotUnitInfo.refiDFRange] then
                            --bCloseToPD = true
                            --else
                            if not(bCloseToEnemy) and tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] > 0 then
                                --Are we close to indirectfire
                                local tEnemyIndirect = EntityCategoryFilterDown(categories.INDIRECTFIRE * categories.MOBILE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tEnemyIndirect) == false then
                                    for iEnemy, oEnemy in tEnemyIndirect do
                                        if not(oEnemy.Dead) and (oEnemy[AiBotUnitInfo.refiIndirectRange] or 0) > 5 and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tClosestTarget) <= (oEnemy[AiBotUnitInfo.refiIndirectRange] or 0) + 10 then
                                            bCloseToEnemy = true
                                            break
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bCloseToEnemy='..tostring(bCloseToEnemy)) end
                            if bCloseToEnemy then
                                --Want to reassess build location
                                ReassessPDBuildLocation()
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': end of loop, refiTimeLastCompletedPD='..(tLZTeamData[AiBotMap.refiTimeLastCompletedPD] or 'nil')) end
            end
            if not(bT2PlusConstructionStarted) then
                tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic] = false
            else
                --v223 - not sure why we were only clearing flag if we started construction, so decided to clear the flag either way after 3s (which should avoid infinite loop type scenarios)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(3)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                tLZTeamData[AiBotMap.refbIgnoreEmergencyPDReassignmentLogic] = false
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

local function ClearDualGapT3PowerAdjacency(aiBrain, oAirHQ, sPowerBlueprint)
    if not(AiBotUnitInfo.IsUnitValid(oAirHQ)) or not(sPowerBlueprint)
            or (aiBrain.AiBotDualGapPowerClearRetryAt or 0) > GetGameTimeSeconds() then return end
    local tAirPosition = oAirHQ:GetPosition()
    local iAirRadius = AiBotUnitInfo.GetBuildingSize(oAirHQ.UnitId) * 0.5
    local iPowerRadius = AiBotUnitInfo.GetBuildingSize(sPowerBlueprint) * 0.5
    local iOffset = iAirRadius + iPowerRadius
    local tCandidateLocations = {
        {tAirPosition[1], GetSurfaceHeight(tAirPosition[1], tAirPosition[3] - iOffset), tAirPosition[3] - iOffset},
        {tAirPosition[1], GetSurfaceHeight(tAirPosition[1], tAirPosition[3] + iOffset), tAirPosition[3] + iOffset},
        {tAirPosition[1] - iOffset, GetSurfaceHeight(tAirPosition[1] - iOffset, tAirPosition[3]), tAirPosition[3]},
        {tAirPosition[1] + iOffset, GetSurfaceHeight(tAirPosition[1] + iOffset, tAirPosition[3]), tAirPosition[3]},
    }
    local tBestBlockers
    for _, tCandidate in tCandidateLocations do
        local tNearbyStructures = aiBrain:GetUnitsAroundPoint(categories.STRUCTURE, tCandidate, iPowerRadius + 1, 'Ally') or {}
        local tBlockers = {}
        local bProtectedStructurePresent = false
        for _, oStructure in tNearbyStructures do
            if AiBotUnitInfo.IsUnitValid(oStructure) and oStructure:GetAIBrain() == aiBrain and not(oStructure == oAirHQ) then
                if EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryHydro
                        + AiBotUnitInfo.refCategoryMassStorage + categories.TECH3, oStructure.UnitId) then
                    bProtectedStructurePresent = true
                    break
                elseif EntityCategoryContains(categories.STRUCTURE * (categories.TECH1 + categories.TECH2), oStructure.UnitId) then
                    table.insert(tBlockers, oStructure)
                end
            end
        end
        if not(bProtectedStructurePresent) and table.getn(tBlockers) > 0
                and (not(tBestBlockers) or table.getn(tBlockers) < table.getn(tBestBlockers)) then
            tBestBlockers = tBlockers
        end
    end
    if not(tBestBlockers) then return end

    local tT1Engineers = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer * categories.TECH1, false) or {}
    local oClearingEngineer
    for _, oEngineer in tT1Engineers do
        if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetFractionComplete() == 1
                and not(oEngineer:IsUnitState('Attached')) then
            oClearingEngineer = oEngineer
            break
        end
    end
    if not(oClearingEngineer) then return end
    for iBlocker, oBlocker in tBestBlockers do
        AiBotOrders.IssueTrackedReclaim(oClearingEngineer, oBlocker, iBlocker > 1, 'DGClearT3Power', true, true)
    end
    aiBrain.AiBotDualGapPowerClearRetryAt = GetGameTimeSeconds() + 20
    LOG('AiBot Dual Gap clearing T3 power adjacency: army='..aiBrain:GetArmyIndex()
            ..'; blockers='..table.getn(tBestBlockers)..'; engineer='..oClearingEngineer.UnitId
            ..'; time='..GetGameTimeSeconds())
end

function ConsiderActionToAssign(iActionToAssign, iMinTechWanted, iTotalBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iCurPriority, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrPond, iLandOrWaterZone, toAvailableEngineersByTech, toAssignedEngineers, bIsWaterZone, iSpecificFactionRequiredOverride, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    --vOptionalVariable can be a table, nil or a value; used to pass info specific to the action if it needs it
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderActionToAssign'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local policyBrain = ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
    local bDualGapAirEcoRole = policyBrain and (policyBrain.AiBotDualGapRole == 'top_air'
            or policyBrain.AiBotDualGapRole == 'bottom_air'
            or policyBrain.AiBotDualGapRole == 'eco')
    local bDualGapT3MexRush = bDualGapAirEcoRole
            and (policyBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3) < 8
                or AiBotEconomy.HasUncappedDualGapT3Mex(policyBrain))
    if bDualGapT3MexRush and (iActionToAssign == refActionBuildExperimental
            or iActionToAssign == refActionBuildSecondExperimental
            or iActionToAssign == refActionBuildExperimentalNavy
            or iActionToAssign == refActionBuildLandExperimental
            or iActionToAssign == refActionBuildAirExperimental
            or iActionToAssign == refActionBuildGameEnder
            or iActionToAssign == refActionManageGameEnderTemplate) then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end
    if bDualGapAirEcoRole
            and (iActionToAssign == refActionBuildMassStorage or iActionToAssign == refActionBuildSecondMassStorage)
            and policyBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * (categories.TECH2 + categories.TECH3)) < 8 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    -- This is the common path for all engineer build requests. Apply the
    -- Dual Gap role gate here so land/air/navy factory requests from every
    -- local HaveActionToAssign wrapper follow the same policy.
    local dualGapFactoryType
    if iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildSecondLandFactory then
        dualGapFactoryType = 'land'
    elseif iActionToAssign == refActionBuildAirFactory or iActionToAssign == refActionBuildSecondAirFactory then
        dualGapFactoryType = 'air'
    elseif iActionToAssign == refActionBuildNavalFactory then
        dualGapFactoryType = 'navy'
    end
    if dualGapFactoryType then
        if policyBrain and not AiBotDualGap.CanBuildFactory(policyBrain, dualGapFactoryType) then
            if bDebugMessages then
                LOG(sFunctionRef..': Dual Gap blocked '..dualGapFactoryType..' factory for role='..tostring(policyBrain.AiBotDualGapRole)..'; phase='..tostring(policyBrain.AiBotDualGapRolePhase)..'; time='..tostring(GetGameTimeSeconds()))
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return
        end
    end

    -- Manual boom mode deliberately trades production capacity for economy.
    -- Keep one land factory per controlled brain; toggling boom off immediately
    -- restores the normal factory construction logic.
    if AiBotOverseer.IsTeamBoomMode(iTeam) and (iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildSecondLandFactory) and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory, iTeam) >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end



    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(bBPIsInAdditionToExisting) and tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueBuild then iTotalBuildPowerWanted = iTotalBuildPowerWanted * 0.8 end

    --Dont try getting any mroe BP for htis action if have run out of buildable locations
    local iExpectedBuildingSize = tiLastBuildingSizeFromActionForTeam[iTeam][iActionToAssign]
    if bDebugMessages == true then
        if iExpectedBuildingSize then
            LOG(sFunctionRef..': iExpectedBuildingSize='..(iExpectedBuildingSize or 'nil')..';  tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iSize]='..( tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iExpectedBuildingSize] or 'nil')..'; iMinTechWanted='..(iMinTechWanted or 'nil')..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iActionToAssign='..iActionToAssign..'; iCurPriority='..iCurPriority)
        else
            LOG(sFunctionRef..': iExpectedBuildingSize is nil; as confirmation, iExpectedBuildingSize='..(iExpectedBuildingSize or 'nil')..'; iMinTechWanted='..(iMinTechWanted or 'nil')..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iActionToAssign='..iActionToAssign..'; iCurPriority='..iCurPriority)
        end
    end
    local iPlateauOrZero
    if bIsWaterZone then iPlateauOrZero = 0 else iPlateauOrZero = iPlateauOrPond end

    if iExpectedBuildingSize and (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iExpectedBuildingSize] or 0) == 0 then
        if not(iActionToAssign == refActionBuildMex) and not(iActionToAssign == refActionBuildHydro) then
            --If this isn't a recognised size then try the next size up
            local bChangedSize = false
            if bIsWaterZone and not(tsWZBlueprintsBySize[iExpectedBuildingSize]) and iExpectedBuildingSize < iMaxBuildingSize then
                for iAltBuildingSize = iExpectedBuildingSize + 1, iMaxBuildingSize, 1 do
                    if tsWZBlueprintsBySize[iAltBuildingSize] then
                        bChangedSize = true
                        iExpectedBuildingSize = iAltBuildingSize
                        break
                    end
                end
            elseif not(bIsWaterZone) and not(tsBlueprintsBySize[iExpectedBuildingSize]) and iExpectedBuildingSize < iMaxBuildingSize then
                for iAltBuildingSize = iExpectedBuildingSize + 1, iMaxBuildingSize, 1 do
                    if tsBlueprintsBySize[iAltBuildingSize] then
                        bChangedSize = true
                        iExpectedBuildingSize = iAltBuildingSize
                        break
                    end
                end
            end
            if bChangedSize and (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iExpectedBuildingSize] or 0) > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': We changed the expected building size and found some that work') end
            else
                if (tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 0) < 30 then
                    local iSegmentsToConsider = 5
                    if (tLZOrWZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] or 0) < (tLZOrWZData[AiBotMap.subrefLZTotalSegmentCount] or 0) then iSegmentsToConsider = 20 end

                    --SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iOptionalMaxSegmentsToConsider)
                    SearchForBuildableLocationsForLandOrWaterZone(AiBotTeam.GetFirstActiveAiBotBrain(iTeam), iPlateauOrZero, iLandOrWaterZone, iSegmentsToConsider)
                end
                if (tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize][iExpectedBuildingSize] or 0) == 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Setting build power to 0 as no buildable locations, unless we have a category of the desired type under construction, tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick]='..(tLZOrWZData[AiBotMap.subrefSegmentsConsideredThisTick] or 'nil')..'; repru of tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize] for all sizes='..repru(tLZOrWZData[AiBotMap.subrefBuildLocationSegmentCountBySize])) end
                    local iCategoryToCheck = tiActionCategory[iActionToAssign]
                    if not(iCategoryToCheck) and not(tbIgnoreEngineerAssistance[iActionToAssign]) and tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueBuild then
                        if iActionToAssign == refActionBuildExperimental then iCategoryToCheck = AiBotUnitInfo.refCategoryExperimentalLevel
                        elseif iActionToAssign == refActionBuildShield then iCategoryToCheck = AiBotUnitInfo.refCategoryFixedShield
                        elseif iActionToAssign == refActionBuildEmergencyPD then iCategoryToCheck = AiBotUnitInfo.refCategoryPD
                        else iCategoryToCheck = GetCategoryToBuildOrAssistFromAction(iActionToAssign, iMinTechWanted, ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]], nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
                        end
                    end
                    if iCategoryToCheck == refActionManageGameEnderTemplate then iCategoryToCheck = AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryFixedShield end --put in as was getting error, suspect because no build space for experimental level template
                    if not(iCategoryToCheck) or tbIgnoreEngineerAssistance[iActionToAssign] or not(GetPartCompleteBuildingInZone(iTeam, iPlateauOrPond, iLandOrWaterZone, iCategoryToCheck, bIsWaterZone, nil)) then
                        iTotalBuildPowerWanted = 0
                        if bDebugMessages == true then LOG(sFunctionRef..': We either have no expected category or we are ignoring engi assistnac,e or no building of category underconstruction, so clearing BP wanted') end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': we have an under construction unit of the desired category so wont clear the BP wanted') end
                    end
                end
            end
        end
    end

    if iTotalBuildPowerWanted < 0 then AiBotUtilities.ErrorHandler('Have negative BP wanted for iActionToAssign='..iActionToAssign)
    elseif iTotalBuildPowerWanted > 0 then
        --Reduce BP for high modifiers where we have at least 50% mass stored and dont have spare engineers
        if iTotalBuildPowerWanted > 15 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] >= 1.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35 and tLZOrWZTeamData[AiBotMap.subrefTbWantBP] and (tLZOrWZTeamData[AiBotMap.subrefSpareBPByTech][1] == 0 and tLZOrWZTeamData[AiBotMap.subrefSpareBPByTech][2] == 0 and tLZOrWZTeamData[AiBotMap.subrefSpareBPByTech][3] == 0) then
            --Only half BP for building the first power if we have lots of power already
            if iTotalBuildPowerWanted > 2 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] then
                if not(iActionToAssign == refActionLoadOntoTransport) and (not(iActionToAssign == refActionBuildPower) or (iMinTechWanted == 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] * 500)) then
                    iTotalBuildPowerWanted = iTotalBuildPowerWanted * math.max(1 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier], 0.35)
                    if bDebugMessages == true then LOG(sFunctionRef..': Significantly build power wanted to reflect our build rate') end
                end
            end
        end

        --Reclaim specific - limit BP to 5 if we have recenlty failed to find something to reclaim
        if (iActionToAssign == refActionReclaimArea or iActionToAssign == refActionReclaimTrees) and tLZOrWZData[AiBotMap.subrefiTimeFailedToGetReclaim] and GetGameTimeSeconds() - tLZOrWZData[AiBotMap.subrefiTimeFailedToGetReclaim] <= 3 then
            if bDebugMessages == true then LOG(sFunctionRef..': Time since last failed to get reclaim for this zone='..GetGameTimeSeconds() - tLZOrWZData[AiBotMap.subrefiTimeFailedToGetReclaim]..'; BP wanted before limitation='..iTotalBuildPowerWanted..'; will cap at 5') end
            iTotalBuildPowerWanted = math.min(5, iTotalBuildPowerWanted)
        end


        --Experimental specific - Dont want to build if we have other engineers in a different zone building an experimental and we dont have the eco to support multiple ones - instead rely on separate engi transfer and mass transfer logic to get the experimental built
        if (iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental or iActionToAssign == refActionBuildGameEnder or iActionToAssign == refActionBuildExperimentalNavy or iActionToAssign == refActionBuildLandExperimental or iActionToAssign == refActionBuildAirExperimental) then
            if bDebugMessages == true then LOG(sFunctionRef..': About to remove BP wanted for experimental construction if we already have one under construction nearby that has recently started, or are about to start construction, and we cant support multiple at once, and dont have one in this zone') end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 400 then
                --Do we have negative mass income, or have less than 70% mass stored? Also only consider for land experimentals (not navy) for now:
                if not(bIsWaterZone) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.7) then
                    --NOTE: If changing above thresholds then make sure the AiBotEvents OnConstructionStarted is stricter
                    local iSearchRange = math.max(150, 400 - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass])
                    local iSearchCategory = nil --means will search for everything
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 140 then
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 280 then
                            iSearchCategory = AiBotUnitInfo.refCategoryGameEnder
                        else
                            iSearchCategory = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti
                        end
                    end
                    local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateauOrPond, iLandOrWaterZone, true, iSearchRange, iSearchCategory)
                    if iMassToComplete >= math.max(15000, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] * 1.25) and not(bHaveExperimentalForThisLandZone) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 900 then
                        --Estimate how long it will take to complete if we manage to spend 40% of gross mass on existing experimentals
                        if (iMassToComplete - AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.4 > 40 then
                            iTotalBuildPowerWanted = 0
                            if bDebugMessages == true then LOG(sFunctionRef..': iMassToComplete='..iMassToComplete..'; Mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; will set BPWanted to 0') end
                        end
                    end
                end
            end
        end
        --Reduce the build power wanted by the existing build power assigned to that action for the LZ, unless bBPIsInAdditionToExisting is true or bMarkAsSpare is true
        local bAlreadyHaveTechLevelWanted = false
        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false and iTotalBuildPowerWanted > 0 and not(bMarkAsSpare) then
            local iSubstituteAction = tiActionSubstitute[iActionToAssign]
            for iEngi, oEngi in toAssignedEngineers do
                if not(oEngi[AiBotUnitInfo.refbSpecialMicroActive]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..': Considering if oEngi '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..' already has iActionToAssign '..iActionToAssign..'; oEngi[refiAssignedAction]='..(oEngi[refiAssignedAction] or 'nil')..'; Priority of engis action='..(oEngi[refiAssignedActionPriority] or 'nil')..'; iCurPrioriyt='..iCurPriority..'; Engi tech level='..AiBotUnitInfo.GetUnitTechLevel(oEngi)..'; iMinTechWanted='..iMinTechWanted..'; Engi work progress='..oEngi:GetWorkProgress()..'; oEngi subrefsOrderBlueprint='..(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')) end
                    if oEngi[refiAssignedAction] == iActionToAssign or (iSubstituteAction and oEngi[refiAssignedAction] == iSubstituteAction) then
                        if not(bAlreadyHaveTechLevelWanted) and AiBotUnitInfo.GetUnitTechLevel(oEngi) >= iMinTechWanted then
                            --Only flag as having min tech level wanted if we will be able to make use of this engineer per the later code
                            if not(tbIgnoreEngineerAssistance[iActionToAssign]) and oEngi[AiBotOrders.reftiLastOrders] and oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild then
                                --Engi should be either started construction, or have a blueprint of the desired tech level
                                if iMinTechWanted <= 1 or oEngi:GetWorkProgress() > 0 or (oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] and AiBotUnitInfo.GetBlueprintTechLevel(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint]) >= iMinTechWanted) then
                                    bAlreadyHaveTechLevelWanted = true
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Reducing total Build power wanted by '..oEngi:GetBlueprint().Economy.BuildRate..' unless bBPIsInAdditionToExisting is true; bBPIsInAdditionToExisting='..tostring(bBPIsInAdditionToExisting or false)) end
                        if not(bBPIsInAdditionToExisting) then
                            iTotalBuildPowerWanted = iTotalBuildPowerWanted - oEngi:GetBlueprint().Economy.BuildRate
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to check if want to lower tech level wanted, bAlreadyHaveTechLevelWanted='..tostring(bAlreadyHaveTechLevelWanted)..'; iMinTechWanted='..iMinTechWanted..'; Is campaign map='..tostring(AiBotMap.bIsCampaignMap)..'; iActionToAssign='..iActionToAssign) end
        if bAlreadyHaveTechLevelWanted and not(bDontUseLowerTechEngineersToAssist) then iMinTechWanted = 1
            --Campaign - might have T3 air fac but not be able to build T3 engineers
        elseif iMinTechWanted > 1 and (AiBotMap.bIsCampaignMap or AiBotOverseer.bUnitRestrictionsArePresent) and (iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildAirFactory or iActionToAssign == refActionBuildPower or iActionToAssign == refActionBuildSecondLandFactory or iActionToAssign == refActionBuildSecondAirFactory) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            --Check we have engineers of the relevant tech level to be able to build the factory
            local iEngiCategoryWanted
            if iMinTechWanted >= 3 then iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer * categories.TECH3
            else iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer - categories.TECH1
            end
            local tExistingEngineersOfCategory = EntityCategoryFilterDown(iEngiCategoryWanted, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is tExistingEngineersOfCategory empty='..tostring(AiBotUtilities.IsTableEmpty(tExistingEngineersOfCategory))) end
            if AiBotUtilities.IsTableEmpty(tExistingEngineersOfCategory) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will lower min tech level wanted to build a factory due to being a campaign or having unit restrictions') end
                iMinTechWanted = iMinTechWanted - 1
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iActionToAssign='..iActionToAssign..'; iTeam='..iTeam..'; iPlateauOrPond='..iPlateauOrPond..'; iLandOrWaterZone='..iLandOrWaterZone..'; Have just updated BP wanted for existing engineers with the same action, iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; Is toAvailableEngineersByTech empty='..tostring(AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech))..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted) end


        --Do we have an engineer of the tech level wanted? First assign any available engineers of the right tech level to the action
        --If we dont have any engineers of the right tech level available, then see if we have an engineer with a lower priority action
        local tEngineersOfTechWanted
        if toAvailableEngineersByTech and iTotalBuildPowerWanted > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Will get engis of tech wnated from available engineers by tech') end
            tEngineersOfTechWanted = GetEngineersOfTechWanted(iMinTechWanted, toAvailableEngineersByTech)
        end
        if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech) and iTotalBuildPowerWanted > 0 and AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
            local bConsiderRetreatingEngineers = false
            if (iActionToAssign == refActionBuildEmergencyPD or iActionToAssign == refActionBuildSecondPD) and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (tLZOrWZTeamData[AiBotMap.subrefLZCoreExpansion] and (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < (tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0))) then
                bConsiderRetreatingEngineers = true
            end
            --Do we have already assigned engineers with a lower priority that we could use?
            local iEngiCategoryWanted
            if iMinTechWanted <= 1 then iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer
            elseif iMinTechWanted == 2 then iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer * categories.TECH2 + AiBotUnitInfo.refCategoryEngineer * categories.TECH3
            else iEngiCategoryWanted = AiBotUnitInfo.refCategoryEngineer * categories.TECH3
            end
            local toAssignedEngisOfTechLevel = EntityCategoryFilterDown(iEngiCategoryWanted, toAssignedEngineers)
            if AiBotUtilities.IsTableEmpty(toAssignedEngisOfTechLevel) == false then
                tEngineersOfTechWanted = {}
                local iHighestPriorityEngi = iCurPriority
                local oHighestPriorityEngi
                for iEngi, oEngi in toAssignedEngisOfTechLevel do
                    if not(oEngi[refbPrimaryBuilder]) and not(oEngi[refiAssignedAction] == iActionToAssign) and oEngi[refiAssignedActionPriority] > iHighestPriorityEngi and not(oEngi:IsUnitState('Reclaiming')) and not(oEngi:IsUnitState('Attached')) and not(oEngi:IsUnitState('Capturing')) then
                        --Exception for engineers assisting a shield
                        if not(oEngi[refiAssignedAction] == refActionAssistShield) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] <= 2) then
                            iHighestPriorityEngi = oEngi[refiAssignedActionPriority]
                            oHighestPriorityEngi = oEngi
                        end
                    elseif bConsiderRetreatingEngineers and not(oHighestPriorityEngi) and oEngi[refiAssignedActionPriority] < iHighestPriorityEngi and oEngi[refiAssignedAction] == refActionRunToLandZone and not(oEngi:IsUnitState('Reclaiming')) and not(oEngi:IsUnitState('Attached')) and not(oEngi:IsUnitState('Capturing')) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will make use of engi running away to build emergency PD') end
                        oHighestPriorityEngi = oEngi
                    end
                end
                if oHighestPriorityEngi then
                    table.insert(tEngineersOfTechWanted, oHighestPriorityEngi)
                    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iMinTechWanted='..iMinTechWanted..'; oHighestPriorityEngi='..oHighestPriorityEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oHighestPriorityEngi)..'; oHighestPriorityEngi action='..(oHighestPriorityEngi[refiAssignedAction] or 'nil')..' with a priority '..(oHighestPriorityEngi[refiAssignedActionPriority] or 'nil')..'; Is primary='..tostring(oHighestPriorityEngi[refbPrimaryBuilder] or false)..'; table size='..table.getn(tEngineersOfTechWanted)) end
                end
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Is tEngineersOfTechWanted empty='..tostring(AiBotUtilities.IsTableEmpty(tEngineersOfTechWanted))) end
        if AiBotUtilities.IsTableEmpty(tEngineersOfTechWanted) == false and iTotalBuildPowerWanted > 0 then

            local sOrderRef = 'A'..iActionToAssign..'Pr'..iCurPriority --For debugging - if show unit names then will include this
            local iMaxSearchRange = 180 --Must be bigger than the largest land zone or else units wont be able to build, so can lead to engineers entering a land zone to build and then moving away to a different land zone
            local iEngiCount = table.getn(tEngineersOfTechWanted)
            local iCurEngiTechLevel
            local iCurEngiBuildPower
            local aiBrain = tEngineersOfTechWanted[1]:GetAIBrain()
            local iMinCategoryTechLevel = iMinTechWanted
            --Override tech level if we lack the relevant factory HQ
            if iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildSecondLandFactory then
                iMinCategoryTechLevel = math.max(1, math.min(iMinTechWanted, (aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] or 1)))
            elseif iActionToAssign == refActionBuildAirFactory or iActionToAssign == refActionBuildSecondAirFactory then
                iMinCategoryTechLevel = math.max(1, math.min(iMinTechWanted, (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] or 1)))
            elseif iActionToAssign == refActionBuildNavalFactory then
                iMinCategoryTechLevel = math.max(1, math.min(iMinTechWanted, (aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] or 1)))
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iMinCategoryTechLevel after adjusting for highest HQ='..iMinCategoryTechLevel..'; iMinTechWanted='..iMinTechWanted) end
            --Check faction available
            local tbEngineersOfFaction
            if tbActionsWithFactionSpecificLogic[iActionToAssign] and not(bAlreadyHaveTechLevelWanted) then
                tbEngineersOfFaction = {}
                for iUnit, oUnit in tEngineersOfTechWanted do
                    tbEngineersOfFaction[AiBotUnitInfo.GetUnitFaction(oUnit)] = true
                end
            end

            local iCategoryWanted, iOptionalFactionRequired = GetCategoryToBuildOrAssistFromAction(iActionToAssign, iMinCategoryTechLevel, aiBrain, tbEngineersOfFaction, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
            --Land and air facs - optional variable can be used to specify max tech level to use
            if vOptionalVariable and iCategoryWanted and (iActionToAssign == refActionBuildAirFactory or iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildSecondLandFactory or iActionToAssign == refActionBuildSecondLandFactory) and vOptionalVariable >= iMinCategoryTechLevel and (vOptionalVariable == 1 or vOptionalVariable == 2) then
                iCategoryWanted = iCategoryWanted * AiBotUnitInfo.ConvertTechLevelToCategory(vOptionalVariable)
            elseif vOptionalVariable and iActionToAssign == refActionBuildSpecialObjective then
                iCategoryWanted = vOptionalVariable[AiBotMap.subrefiObjCategoryToBuild]
            end
            if iSpecificFactionRequiredOverride and not(iOptionalFactionRequired) then iOptionalFactionRequired = iSpecificFactionRequiredOverride end

            function UpdateBPTracking()
                iCurEngiTechLevel = AiBotUnitInfo.GetUnitTechLevel(tEngineersOfTechWanted[iEngiCount])
                iCurEngiBuildPower = tEngineersOfTechWanted[iEngiCount]:GetBlueprint().Economy.BuildRate
                iTotalBuildPowerWanted = iTotalBuildPowerWanted - iCurEngiBuildPower
                if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[iCurEngiTechLevel]) == false then --If we are reassigning an engineer this wont have a value
                    for iEngi, oEngi in toAvailableEngineersByTech[iCurEngiTechLevel] do
                        if oEngi == tEngineersOfTechWanted[iEngiCount] then
                            table.insert(toAssignedEngineers, tEngineersOfTechWanted[iEngiCount])
                            table.remove(toAvailableEngineersByTech[iCurEngiTechLevel], iEngi)
                            break
                        end
                    end
                end

                tEngineersOfTechWanted[iEngiCount] = nil
                iEngiCount = iEngiCount - 1
            end

            if bDebugMessages == true then LOG(sFunctionRef..': iActionToAssign='..iActionToAssign..'; iEngiCount='..iEngiCount..'; Is category watned nil='..tostring(iCategoryWanted == nil)..'; iMinCategoryTechLevel='..(iMinCategoryTechLevel or 'nil')) end

            --Special logic for converting an action to a different one:
            if iCategoryWanted == refActionManageGameEnderTemplate then
                --UEF special case - do we want quantum gateway first so we have SACUs to support?
                iActionToAssign = refActionManageGameEnderTemplate
                iCategoryWanted = nil
            end


            if iCategoryWanted then
                --Do we have a part complete unit of this category already under construction in this land zone?
                --Building a factory - change whether to search for assistance based on mass stored %; for mass storage instead base the check on how many locations we have as we may be trying to build a second storage
                local iConstructionCountToIgnore = (tiIgnoreUnderConstructionThreshold[iActionToAssign] or 0)
                --local bShouldIgnoreUnderConstruction = tbIgnoreUnderConstructionActions[iActionToAssign]
                if iActionToAssign == refActionBuildLandFactory or iActionToAssign == refActionBuildAirFactory then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 15 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then iConstructionCountToIgnore = 1 end
                elseif iActionToAssign == refActionBuildMassStorage and table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) >= 5 then iConstructionCountToIgnore = 1
                elseif iConstructionCountToIgnore > 0 and iActionToAssign == refActionBuildSecondExperimental then
                    if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL, iCategoryWanted) then
                        iConstructionCountToIgnore = 0
                    end
                end

                local oBuildingToAssist
                if iConstructionCountToIgnore < 100 and not(iActionToAssign == refActionAssistNavalFactory) then --Dont want naval fac to assist an upgrading fac, but instead get the highest tech one
                    --We adjust power to only consider the min tech levle not higher ones (presumably so we can build t1/t2 power when we have access to t3, if we need more power to build t3); therefore need to take this into account here
                    local iUnderConstructionCategory
                    if iActionToAssign == refActionBuildPower then
                        iUnderConstructionCategory = AiBotUnitInfo.refCategoryPower - AiBotUnitInfo.refCategoryHydro
                    else iUnderConstructionCategory = iCategoryWanted
                    end
                    oBuildingToAssist = GetPartCompleteBuildingInZone(iTeam, iPlateauOrPond, iLandOrWaterZone, iUnderConstructionCategory, bIsWaterZone, iConstructionCountToIgnore)
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking to see if we have a unit of the desired category. oBuildingToAssist='..(oBuildingToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBuildingToAssist) or 'nil')..'; bIsWaterZone='..tostring(bIsWaterZone)) end
                end

                if oBuildingToAssist then

                    local tPositionToMoveNearFirst
                    local iDistanceToMoveNear
                    if oBuildingToAssist[AiBotBuilding.reftArtiTemplateRefs] and (oBuildingToAssist[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oBuildingToAssist)) >= 35000 and oBuildingToAssist:GetFractionComplete() < 0.9 and (1-oBuildingToAssist:GetFractionComplete()) * oBuildingToAssist[AiBotUnitInfo.refiUnitMassCost] >= 10000 and oBuildingToAssist[AiBotBuilding.reftArtiTemplateRefs][2] == iLandOrWaterZone then
                        local tTemplateRef = tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates][oBuildingToAssist[AiBotBuilding.reftArtiTemplateRefs][3]]
                        if tTemplateRef and tTemplateRef[AiBotMap.subrefGEMidpoint] then
                            iDistanceToMoveNear = AiBotUtilities.GetDistanceBetweenPositions(oBuildingToAssist:GetPosition(), tTemplateRef[AiBotMap.subrefGEMidpoint])
                            --Check we appear to have enough shields built
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.9 and AiBotUtilities.IsTableEmpty(tTemplateRef[AiBotMap.subrefGEShieldUnits]) == false and table.getn(tTemplateRef[AiBotMap.subrefGEShieldUnits]) >= table.getn(tTemplateRef[AiBotMap.subrefGEShieldLocations]) - 1 then
                                tPositionToMoveNearFirst = tTemplateRef[AiBotMap.subrefGEMidpoint]
                            end
                        end
                    end

                    --Assist the building under construction that has the category we want
                    while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                        if bDebugMessages == true then LOG(sFunctionRef..': Assigning engineer for repair action '..iActionToAssign..'; iEngiCount='..iEngiCount..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; tPositionToMoveNearFirst='..repru(tPositionToMoveNearFirst)..'; oBuildingToAssist[AiBotBuilding.reftArtiTemplateRefs]='..repru(oBuildingToAssist[AiBotBuilding.reftArtiTemplateRefs])..'; iDistanceToMoveNear='..(iDistanceToMoveNear or 'nil')..'; oBuildingToAssist='..oBuildingToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBuildingToAssist)..' with mass cost='..oBuildingToAssist[AiBotUnitInfo.refiUnitMassCost]) end
                        if tPositionToMoveNearFirst and AiBotUtilities.GetDistanceBetweenPositions(tEngineersOfTechWanted[iEngiCount]:GetPosition(), tPositionToMoveNearFirst) > iDistanceToMoveNear then
                            AiBotOrders.IssueTrackedMove(tEngineersOfTechWanted[iEngiCount], tPositionToMoveNearFirst, 2, false, 'Rep1Cons', false)
                        else
                            AiBotOrders.IssueTrackedRepair(tEngineersOfTechWanted[iEngiCount], oBuildingToAssist, false, sOrderRef)
                            if iDistanceToMoveNear then tEngineersOfTechWanted[iEngiCount][refiRepairProgressWhenLastChecked] = oBuildingToAssist:GetFractionComplete() end
                        end
                        TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, not(bAlreadyHaveTechLevelWanted), iCurPriority, nil, nil, bMarkAsSpare)
                        UpdateBPTracking()
                    end
                else
                    --Dont have any buildings of the type wanted under construction; do we have an engineer already assigned to the same action? If so then assist it
                    local oEngineerToAssist
                    if not(tbIgnoreEngineerAssistance[iActionToAssign]) and AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then

                        for iEngi, oEngi in toAssignedEngineers do
                            if oEngi[refiAssignedAction] == iActionToAssign then
                                --Only assist if engi last order was to build
                                if bDebugMessages == true then
                                    if oEngi[AiBotOrders.reftiLastOrders] then
                                        LOG(sFunctionRef..': Considering if oEngi '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..' can be assisted to build this; tablegetn of last orders='..oEngi[AiBotOrders.refiOrderCount]..'; reprs of last orders='..reprs(oEngi[AiBotOrders.reftiLastOrders])..'; refiOrderCount='..oEngi[AiBotOrders.refiOrderCount]..'; Is the last order to build something='..tostring(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild)..'; Last blueprint='..(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil'))
                                    else
                                        LOG(sFunctionRef..': Considering if oEngi '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..' can be assisted to build this; Engi last orders is nil, reprs='..reprs(oEngi[AiBotOrders.reftiLastOrders]))
                                    end
                                end
                                if oEngi[AiBotOrders.reftiLastOrders] and oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild and ((iMinTechWanted or 0) <= 1 or oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] and AiBotUnitInfo.GetBlueprintTechLevel(oEngi[AiBotOrders.reftiLastOrders][oEngi[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint]) >= iMinTechWanted) then
                                    --if Engineer cur target is flagged to not  be assisted, then dont assist this engineer
                                    if not(oEngi:GetFocusUnit()[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We can assist the engineer') end
                                        oEngineerToAssist = oEngi
                                        break
                                    end
                                end
                            end
                        end
                    end
                    if not(oEngineerToAssist) then
                        --Has a building been queued for this land zone even if we havent found an engineer to assist? (e.g. rare cases where engineer queues order then briefly drops out of the land zone list of engineers)
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings]) == false and iConstructionCountToIgnore == 0 and not(tbIgnoreEngineerAssistance[iActionToAssign]) then
                            for iEntry, tQueuedDetails in tLZOrWZTeamData[AiBotMap.subrefQueuedBuildings] do
                                if EntityCategoryContains(iCategoryWanted, tQueuedDetails[AiBotMap.subrefBuildingID]) and AiBotUnitInfo.IsUnitValid(tQueuedDetails[AiBotMap.subrefPrimaryBuilder]) and not(tQueuedDetails[AiBotMap.subrefPrimaryBuilder]:GetFocusUnit()[refbDontIncludeAsPartCompleteBuildingForConstruction]) and not(tQueuedDetails[AiBotMap.subrefPrimaryBuilder][refiAssignedAction] == refActionSpecialShieldDefence) then
                                    oEngineerToAssist = tQueuedDetails[AiBotMap.subrefPrimaryBuilder]
                                    if bDebugMessages == true then LOG(sFunctionRef..': An engineer has already queued to build unit '..tQueuedDetails[AiBotMap.subrefBuildingID]..' so will set this engineer as the primary builder, oEngineerToAssist='..(oEngineerToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEngineerToAssist) or 'nil')) end
                                    break
                                end
                            end
                        end
                    end
                    if oEngineerToAssist then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will assign engineers to build, we have oEngineerToAssist, iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount..'; tLastOrder[AiBotOrders.subrefsOrderBlueprint] of engineer to assist='..(oEngineerToAssist[AiBotOrders.reftiLastOrders][oEngineerToAssist[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] or 'nil')) end
                        local tLastOrder = oEngineerToAssist[AiBotOrders.reftiLastOrders][oEngineerToAssist[AiBotOrders.refiOrderCount]]
                        local sBlueprintToBuild = tLastOrder[AiBotOrders.subrefsOrderBlueprint]
                        local tOrderPosition = tLastOrder[AiBotOrders.subreftOrderPosition]
                        local oBaseBrain = oEngineerToAssist:GetAIBrain()
                        local bTransferOwnership
                        local oEngiToTransfer
                        local bEngiIsBuilding
                        if sBlueprintToBuild and tOrderPosition and EntityCategoryContains(iCategoryWanted, sBlueprintToBuild)
                                --Also check that blueprinttobuild is the desired tech level, e.g. for cases where a t2 engi builds a t1 pd, and then we try and build another t1 pd despite now wanting t2
                                and AiBotUnitInfo.GetBlueprintTechLevel(sBlueprintToBuild) >= iMinTechWanted then
                            while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                bTransferOwnership = false
                                if tEngineersOfTechWanted[iEngiCount]:CanBuild(sBlueprintToBuild) then
                                    --Can build
                                    AiBotOrders.IssueTrackedBuild(tEngineersOfTechWanted[iEngiCount], tOrderPosition, sBlueprintToBuild, false, sOrderRef..'B')
                                    if iActionToAssign == refActionBuildEmergencyPD then
                                        if bDebugMessages == true then LOG(sFunctionRef..': asstance changed to building - about to start forked thread for emergency PD reassignment for engi '..(tEngineersOfTechWanted[iEngiCount].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount]) or 'nil')) end
                                        ForkThread(ConsiderEmergencyPDReassignment, tEngineersOfTechWanted[iEngiCount], tLZOrWZData, tLZOrWZData[AiBotMap.subrefMidpoint], iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData)
                                    end
                                else
                                    --If we belong to a different aiBrain then transfer ownership to avoid the risk we block the build location
                                    if not(tEngineersOfTechWanted[iEngiCount]:GetAIBrain() == oBaseBrain) and not(bEngiIsBuilding) then
                                        if bEngiIsBuilding == nil then
                                            local oFocusUnit = oEngineerToAssist:GetFocusUnit()
                                            bEngiIsBuilding = AiBotUnitInfo.IsUnitValid(oFocusUnit)
                                        end
                                        if not(bEngiIsBuilding) then
                                            oEngiToTransfer = tEngineersOfTechWanted[iEngiCount]
                                            bTransferOwnership = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to transfer ownerhsip of engineer so owners are aligned') end
                                        end
                                    end
                                    --Assist the engineer for lower tech enginers
                                    if not(bTransferOwnership) then
                                        AiBotOrders.IssueTrackedGuard(tEngineersOfTechWanted[iEngiCount], oEngineerToAssist, false, sOrderRef..'A')
                                    end
                                end
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                UpdateBPTracking()
                                if bTransferOwnership then AiBotTeam.TransferUnitsToPlayer({ oEngiToTransfer }, oBaseBrain:GetArmyIndex(), false) end
                            end

                        else
                            --Assist the engineer for all engineers
                            while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                if bDebugMessages == true then LOG(sFunctionRef..': Assigning engineer for assist engineer action '..iActionToAssign..'; iEngiCount='..iEngiCount..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted) end
                                AiBotOrders.IssueTrackedGuard(tEngineersOfTechWanted[iEngiCount], oEngineerToAssist, false, sOrderRef..'A')
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                UpdateBPTracking()
                            end
                        end
                    else

                        if tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueGuard then
                            --Want to assist something, and are just looking for a single predefined category (so dont need the  later on custom logic)
                            local oUnitToAssist
                            if vOptionalVariable and AiBotUnitInfo.IsUnitValid(vOptionalVariable) then oUnitToAssist = vOptionalVariable
                            else
                                local oBackupUnit
                                local tUnitsOfCategoryInLZ = EntityCategoryFilterDown(tiActionCategory[iActionToAssign], tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tUnitsOfCategoryInLZ) == false then
                                    --Shield assistance - special logic
                                    if iActionToAssign == refActionAssistShield then
                                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist]) then --redundancy
                                            AiBotUtilities.ErrorHandler('Dont have a priority shield to assist somehow')
                                        else
                                            --Get the shield with the least assistance
                                            local iLowestBPAssisting = 100000
                                            local iCurBPAssisting
                                            for iShield, oShield in tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist] do
                                                iCurBPAssisting = 0
                                                if AiBotUtilities.IsTableEmpty(oShield[AiBotUnitInfo.reftoUnitsAssistingThis]) == false then
                                                    for iAssisting, oAssisting in oShield[AiBotUnitInfo.reftoUnitsAssistingThis] do
                                                        iCurBPAssisting = iCurBPAssisting + (oAssisting:GetBlueprint().Economy.BuildRate or 0)
                                                    end
                                                end
                                                if iCurBPAssisting < iLowestBPAssisting then
                                                    iLowestBPAssisting = iCurBPAssisting
                                                    oUnitToAssist = oShield
                                                    if iLowestBPAssisting == 0 then break end
                                                end
                                            end
                                        end
                                        --T2+ naval fac - assist the factory with the highest progress
                                    elseif iActionToAssign == refActionAssistNavalFactory then
                                        local iHighestTechLevel = 0
                                        local iCurTechLevel, iCurDistToFriendlyBase, iClosestDistToFriendlyBase
                                        if AiBotUtilities.IsTableEmpty(tUnitsOfCategoryInLZ) == false then
                                            for iHQ, oHQ in tUnitsOfCategoryInLZ do
                                                iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oHQ)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering assisting oHQ='..oHQ.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oHQ)..'; iCurTechLevel='..iCurTechLevel..'; Fraction complete='..oHQ:GetFractionComplete()..'; Dist to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oHQ:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])..'; iHighestTechLevel='..iHighestTechLevel) end
                                                if iCurTechLevel > iHighestTechLevel then
                                                    oUnitToAssist = oHQ
                                                    iHighestTechLevel = iCurTechLevel
                                                    iClosestDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oHQ:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                    if oHQ:GetFractionComplete() < 1 then iClosestDistToFriendlyBase = iClosestDistToFriendlyBase + 80 end --Prioritise constructed naval facs over ones upgrading to be the same tech
                                                elseif iCurTechLevel == iHighestTechLevel then
                                                    iCurDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oHQ:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                    if oHQ:GetFractionComplete() < 1 then iCurDistToFriendlyBase = iCurDistToFriendlyBase + 80 end
                                                    if iCurDistToFriendlyBase < iClosestDistToFriendlyBase then
                                                        iClosestDistToFriendlyBase = iCurDistToFriendlyBase
                                                        oUnitToAssist = oHQ
                                                    end
                                                end
                                            end
                                        end
                                        if oUnitToAssist then
                                            tLZOrWZTeamData[AiBotMap.refoLastNavalFacAssisted] = oUnitToAssist
                                            tLZOrWZTeamData[AiBotMap.refiHighestNavalFacAssistBP] = math.max(iTotalBuildPowerWanted, (tLZOrWZTeamData[AiBotMap.refiHighestNavalFacAssistBP] or 0))
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': oUnitToAssist='..(oUnitToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist) or 'nil')..'; is oUnitToAssist valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnitToAssist))..'; iCurPriority='..iCurPriority) end
                                    elseif iActionToAssign == refActionAssistSMD or iActionToAssign == refActionAssistNuke then
                                        --Get the one with the most progress in the zone
                                        if AiBotUtilities.IsTableEmpty(tUnitsOfCategoryInLZ) == false then
                                            local iBestProgress = -1
                                            for iUnit, oUnit in tUnitsOfCategoryInLZ do
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; WorkProgress='..oUnit:GetWorkProgress()) end
                                                if oUnit:GetWorkProgress() > iBestProgress then
                                                    oUnitToAssist = oUnit
                                                    iBestProgress = oUnit:GetWorkProgress()
                                                end
                                            end
                                        end
                                    else
                                        for iUnit, oUnit in tUnitsOfCategoryInLZ do
                                            if oUnit:GetWorkProgress() > 0 then
                                                oUnitToAssist = oUnit
                                            else
                                                oBackupUnit = oUnitToAssist
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to assist unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with work progress '..oUnit:GetWorkProgress()) end
                                        end
                                        if not(oUnitToAssist) then oUnitToAssist = oBackupUnit end
                                    end
                                end
                            end
                            if AiBotUnitInfo.IsUnitValid(oUnitToAssist) then
                                while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                    if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to assist unit '..oUnitToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist)) end
                                    AiBotOrders.IssueTrackedGuard(tEngineersOfTechWanted[iEngiCount], oUnitToAssist, false, sOrderRef)
                                    TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                    UpdateBPTracking()
                                end
                            else
                                --Dont have anything to assist
                                if bDebugMessages == true then LOG(sFunctionRef..': Cant assist the desired category so will stop trying to assist it and reduce build power required') end
                                iTotalBuildPowerWanted = 0
                            end

                        else
                            --No building under construciton, and no existing engineer to assist - assign engineers to build instead

                            --Do we need a specific faction? If so then filter available engineers to just these
                            if iOptionalFactionRequired then tEngineersOfTechWanted, iEngiCount = FilterEngineersOfTechAndEngiCountForFaction(iOptionalFactionRequired, tEngineersOfTechWanted) end

                            if iEngiCount > 0 then
                                --Building power - if we get to T3, have at least 750 gross energy per tick, and have an action to build second power, then change building power normally so it builds separately to building second power
                                if iActionToAssign == refActionBuildThirdPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                    tiIgnoreUnderConstructionThreshold[refActionBuildPower] = 1
                                end
                                local oFirstEngineer = tEngineersOfTechWanted[iEngiCount]
                                local sBlueprint, tBuildLocation
                                local iAdjacencyCategory

                                --Early game - build cheapest option of a unit (e.g. useful for mods that might add expensive hydros or experimental units)
                                local bGetCheapest = false
                                if GetGameTimeSeconds() <= 900 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 10 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 300 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 15 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and not(iActionToAssign == refActionBuildLandFactory) and not(iActionToAssign == refActionBuildAirFactory) and not(iActionToAssign == refActionBuildExperimental) and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiTimeLastNearUnitCap]) then
                                    bGetCheapest = true
                                    --Exception for power once have decent amount of energy
                                    if (iActionToAssign == refActionBuildPower or iActionToAssign == refActionBuildSecondPower) and iMinTechWanted > 1 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] > 65 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Wont get cheapest pgen as we have enough power to support highest tech level') end
                                        bGetCheapest = false
                                    end
                                end

                                if bDebugMessages == true then LOG(sFunctionRef..': About to get the blueprint and build location, oFirstEngineer='..oFirstEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstEngineer)) end
                                if iActionToAssign == refActionBuildShield or iActionToAssign == refActionBuildSecondShield then
                                    GetMaxShieldSearchRangeForEngineer(oFirstEngineer, iCategoryWanted)
                                    --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy,                         tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, tiActionAdjacentCategory[iActionToAssign], vOptionalVariable:GetPosition(), false,                              nil,                nil,                                false,                  tLZOrWZData, tLZOrWZTeamData)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished getting blueprint and build location for shield, sBlueprint='..(sBlueprint or 'nil')..'; tBuildLocation='..repru(tBuildLocation)..'; vOptionalVariable='..(vOptionalVariable.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(vOptionalVariable) or 'nil')..'; iMaxSearchRange='..iMaxSearchRange..'; vOptionalVariable position='..repru(vOptionalVariable:GetPosition())) end
                                    if AiBotUtilities.IsTableEmpty(tBuildLocation) and vOptionalVariable.UnitId then
                                        vOptionalVariable[refiFailedShieldConstructionCount] = (vOptionalVariable[refiFailedShieldConstructionCount] or 0) + 1
                                        if vOptionalVariable[refiFailedShieldConstructionCount] >= 5 then
                                            --Lower value by 1 in 3 minutes
                                            AiBotUtilities.DelayChangeVariable(vOptionalVariable, refiFailedShieldConstructionCount, -1, 180, nil, nil, nil, nil, true)
                                        end
                                    end
                                elseif vOptionalVariable and (iActionToAssign == refActionBuildEmergencyPD or iActionToAssign == refActionBuildSecondPD or iActionToAssign == refActionBuildEmergencyArti or iActionToAssign == refActionBuildT1TorpLauncher or iActionToAssign == refActionBuildTorpLauncher) then
                                    --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy,                tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, tiActionAdjacentCategory[iActionToAssign], vOptionalVariable,       false,                              nil,             nil,                                   bGetCheapest,                   tLZOrWZData, tLZOrWZTeamData)
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef..': Have just tried to get location for PD or torp launcher, vOptionalVariable='..repru(vOptionalVariable)..'; sBlueprint='..(sBlueprint or 'nil')..'; tBuildLocation='..repru(tBuildLocation))
                                        if AiBotUtilities.IsTableEmpty(tBuildLocation) == false then
                                            AiBotUtilities.DrawLocation(tBuildLocation)
                                        end
                                    end
                                elseif vOptionalVariable and (iActionToAssign == refActionBuildTMD or iActionToAssign == refActionBuildSecondTMD or iActionToAssign == refActionBuildThirdTMD) then
                                    --Build near the unit we want to protect (get blueprint will also factor in maxsearchrange based on the TMD range)
                                    if vOptionalVariable.UnitId then
                                        --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy,                tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                        sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, tiActionAdjacentCategory[iActionToAssign], vOptionalVariable:GetPosition(), false,                      nil,                nil,                                bGetCheapest, tLZOrWZData, tLZOrWZTeamData)
                                    elseif AiBotUtilities.IsTableEmpty(vOptionalVariable) == false then
                                        sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, tiActionAdjacentCategory[iActionToAssign], vOptionalVariable,               false,                      nil,                nil,                                bGetCheapest, tLZOrWZData, tLZOrWZTeamData)
                                    else
                                        AiBotUtilities.ErrorHandler('Trying to build TMD without a unit or location')
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Building TMD, sBlueprint='..sBlueprint..'; tBuildLocation='..repru(tBuildLocation)) end
                                elseif iActionToAssign == refActionBuildAirStaging and (bGetCheapest or not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiTimeLastNearUnitCap])) then
                                    --Mod support for mods that introduce t3 air staging which is very expensive - want to avoid unless close to unit cap
                                    --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild,                                         iMaxAreaToSearch, iCatToBuildBy, tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted - categories.TECH3 - categories.EXPERIMENTAL, iMaxSearchRange, iAdjacencyCategory, nil,                           false,                          nil,                nil,                                bGetCheapest,           tLZOrWZData,  tLZOrWZTeamData)
                                elseif vOptionalVariable and iActionToAssign == refActionBuildSpecialObjective then
                                    local iMaxSearchArea = vOptionalVariable[AiBotMap.subrefiObjLocationSize] --ok with this being nil
                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchArea, nil, vOptionalVariable[AiBotMap.subreftObjLocation], nil, nil, nil, bGetCheapest, tLZOrWZData, tLZOrWZTeamData, nil, nil)
                                elseif iActionToAssign == refActionBuildPower and iMinTechWanted == 3
                                        and (aiBrain.AiBotDualGapRole == 'top_air'
                                            or aiBrain.AiBotDualGapRole == 'bottom_air'
                                            or aiBrain.AiBotDualGapRole == 'eco') then
                                    --The first T3 generator is part of the air grid. Anchor
                                    --its location directly to our own highest-tech air HQ.
                                    local oAirHQ
                                    local iHighestAirTech = 0
                                    local tOwnAirFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory, false) or {}
                                    for _, oAirFactory in tOwnAirFactories do
                                        if AiBotUnitInfo.IsUnitValid(oAirFactory) and oAirFactory:GetFractionComplete() == 1 then
                                            local iAirTech = AiBotUnitInfo.GetUnitTechLevel(oAirFactory)
                                            if iAirTech > iHighestAirTech then
                                                iHighestAirTech = iAirTech
                                                oAirHQ = oAirFactory
                                            end
                                        end
                                    end
                                    if oAirHQ then
                                        sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(
                                                aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted,
                                                20, AiBotUnitInfo.refCategoryAirFactory, oAirHQ:GetPosition(),
                                                false, oAirHQ, nil, false, tLZOrWZData, tLZOrWZTeamData)
                                        if tBuildLocation and AiBotUtilities.GetDistanceBetweenPositions(
                                                tBuildLocation, oAirHQ:GetPosition()) > 14 then
                                            --GetBlueprintAndLocationToBuild normally falls back to a
                                            --random base cell when adjacency is blocked. For this build
                                            --that fallback is forbidden; retry the air-grid slot instead.
                                            tBuildLocation = nil
                                        end
                                        if not(tBuildLocation) then
                                            ClearDualGapT3PowerAdjacency(aiBrain, oAirHQ, sBlueprint)
                                        end
                                        LOG('AiBot Dual Gap T3 power anchored to air HQ: army='..aiBrain:GetArmyIndex()
                                                ..'; factory='..oAirHQ.UnitId..'; location='..repru(tBuildLocation)
                                                ..'; time='..GetGameTimeSeconds())
                                    else
                                        sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, tiActionAdjacentCategory[iActionToAssign], nil, false, nil, nil, bGetCheapest, tLZOrWZData, tLZOrWZTeamData)
                                    end
                                else
                                    iAdjacencyCategory = tiActionAdjacentCategory[iActionToAssign]
                                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iActionToAssign == refActionBuildPower and iMinTechWanted <= 2 then
                                        tiActionAdjacentCategory[iActionToAssign] = tiActionAdjacentCategory[iActionToAssign] + AiBotUnitInfo.refCategoryLandFactory
                                        if iMinTechWanted == 1 and AiBotBuilding.iLowestMassStorageTechAvailable > 2 then tiActionAdjacentCategory[iActionToAssign] = tiActionAdjacentCategory[iActionToAssign] + AiBotUnitInfo.refCategoryMex end
                                    end
                                    if not(iAdjacencyCategory) and (iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental) then
                                        if AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti * categories.STRUCTURE + AiBotUnitInfo.refCategorySML, iCategoryWanted) then
                                            iAdjacencyCategory = AiBotUnitInfo.refCategoryT3Power
                                        end
                                    end
                                    --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy, tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, iAdjacencyCategory, nil,                                false,                          nil,                nil,                                bGetCheapest, tLZOrWZData, tLZOrWZTeamData)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Just got blueprint and location to build for oFirstEngineer='..oFirstEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFirstEngineer)..'; iActionTOAssign='..iActionToAssign..'; sBlueprint='..(sBlueprint or 'nil')..'; tBuildLocation='..repru(tBuildLocation)..'; Is tiActionAdjacentCategory[iActionToAssign] nil='..tostring(tiActionAdjacentCategory[iActionToAssign] == nil)) end
                                if AiBotUtilities.IsTableEmpty(tBuildLocation) then
                                    if not(iActionToAssign == refActionBuildShield or iActionToAssign == refActionBuildSecondShield) then
                                        if sBlueprint and (GetGameTimeSeconds() <= 300 or GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastShowedBuildLocationFailure] or -300) >= 300) then
                                            --Couldnt find a build locaiton, but might be valid particularly later in the game or on small island maps, so only show as a warning message every 5m
                                            if not(AiBotUnitInfo.IsUnitRestricted(sBlueprint, AiBotTeam.GetFirstActiveAiBotBrain(iTeam))) then
                                                local bShowError = true
                                                if AiBotMap.bIsCampaignMap and EntityCategoryContains(AiBotUnitInfo.refCategoryMex, sBlueprint) then
                                                    --Is the first unbuilt mex location outside the playable area?
                                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations][1]) == false and not(AiBotConditions.IsLocationInPlayableArea(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations][1])) then
                                                        --Mex is outside playable area so dont show error, and dont flag location as needing engis for mexes
                                                        tLZOrWZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = false
                                                        bShowError = false
                                                    end
                                                end
                                                if bShowError then
                                                    AiBotUtilities.ErrorHandler('Unable to find build location, iActionToAssign='..(iActionToAssign or 'nil')..'; P'..(iPlateauOrPond or 'nil')..'Z'..(iLandOrWaterZone or 'nil')..'; sBlueprint='..(sBlueprint or 'nil'), true)
                                                    --Note - campaign maps where building mex - reason may be that all the mex locations remaining are outside of the playable area
                                                    tLZOrWZTeamData[AiBotMap.refiTimeLastShowedBuildLocationFailure] = GetGameTimeSeconds()
                                                    SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, nil)
                                                end
                                            end
                                        end
                                    end
                                elseif sBlueprint then
                                    local tMoveLocation
                                    while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Assigning engineer for building action '..iActionToAssign..'; iEngiCount='..iEngiCount..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; tiActionOrder[iActionToAssign]='..(tiActionOrder[iActionToAssign] or 'nil')..'; sBlueprint='..sBlueprint..'; tBuildLocation='..repru(tBuildLocation)..'; Eng cur state='..AiBotUnitInfo.GetUnitState(tEngineersOfTechWanted[iEngiCount])) end
                                        --Is our order to build or assist?
                                        if tiActionOrder[iActionToAssign] then
                                            if tiActionOrder[iActionToAssign] == AiBotOrders.refiOrderIssueBuild then
                                                tMoveLocation = GetLocationToMoveForConstruction(tEngineersOfTechWanted[iEngiCount], tBuildLocation, sBlueprint, 0, false)
                                                if tMoveLocation and (AiBotUtilities.GetDistanceBetweenPositions(tEngineersOfTechWanted[iEngiCount]:GetPosition(), tBuildLocation) >= 5 + (tEngineersOfTechWanted[iEngiCount]:GetBlueprint().EconomyMaxBuildDistance or 5)) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Telling engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to move to '..repru(tMoveLocation)..' and then build '..sBlueprint..' at location '..repru(tBuildLocation)) end
                                                    AiBotOrders.IssueTrackedMoveAndBuild(tEngineersOfTechWanted[iEngiCount], tBuildLocation, sBlueprint, tMoveLocation, 1, false, sOrderRef)
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Telling engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to build '..sBlueprint..' at build location '..repru(tBuildLocation)) end
                                                    AiBotOrders.IssueTrackedBuild(tEngineersOfTechWanted[iEngiCount], tBuildLocation, sBlueprint, false, sOrderRef)
                                                end
                                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, true, iCurPriority, nil, nil, bMarkAsSpare)
                                                --Special logic for emergency PD where want to reassess periodically
                                                if iActionToAssign == refActionBuildEmergencyPD then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to start forked thread for emergency PD reassignment for engi '..(tEngineersOfTechWanted[iEngiCount].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount]) or 'nil')) end
                                                    ForkThread(ConsiderEmergencyPDReassignment, tEngineersOfTechWanted[iEngiCount], tLZOrWZData, tLZOrWZData[AiBotMap.subrefMidpoint], iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData)
                                                end
                                                UpdateBPTracking()

                                                --Check for blocking selens if this is the primary engineer
                                                if bDebugMessages == true then LOG(sFunctionRef..': refiAssignedLurkerCount='..(tLZOrWZTeamData[AiBotMap.refiAssignedLurkerCount] or 'nil')..'; tEngineersOfTechWanted[iEngiCount][refbPrimaryBuilder]='..tostring(tEngineersOfTechWanted[iEngiCount][refbPrimaryBuilder] or false)) end
                                                if (tLZOrWZTeamData[AiBotMap.refiAssignedLurkerCount] or 0) > 0 then --Originally tried just for primarybuilder but was returning  false for all the engineers in question
                                                    --Check for blocking selens and move them out of the way
                                                    local iBuildingSize = AiBotUnitInfo.GetBuildingSize(sBlueprint)
                                                    local rBuildRect = AiBotUtilities.GetRectAroundLocation(tBuildLocation, iBuildingSize * 0.5 + 1)
                                                    local tUnitsInRect = GetUnitsInRect(rBuildRect)
                                                    if bDebugMessages == true then
                                                        LOG(sFunctionRef..': Is tUnitsInRect empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect))..'; sBlueprint='..sBlueprint..'; iBuildingSize='..iBuildingSize)
                                                        --AiBotUtilities.DrawRectangle(rBuildRect)
                                                    end
                                                    if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
                                                        local tSelens = EntityCategoryFilterDown(categories.xsl0101, tUnitsInRect)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': is tSelens empty='..tostring(AiBotUtilities.IsTableEmpty(tSelens))) end
                                                        if AiBotUtilities.IsTableEmpty(tSelens) == false then
                                                            for iSelen, oSelen in tSelens do
                                                                if not(oSelen[AiBotUnitInfo.refbSpecialMicroActive]) then
                                                                    local tMoveLocation = AiBotUtilities.MoveInDirection(oSelen:GetPosition(), AiBotUtilities.GetAngleFromAToB(tBuildLocation, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]), math.max(iBuildingSize + 3, 10), true, false, AiBotMap.bIsCampaignMap)
                                                                    if not(tMoveLocation) or not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tMoveLocation) == (tLZOrWZData[AiBotMap.subrefLZIslandRef] or 0)) then tMoveLocation = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]} end
                                                                    --Move away for 8s
                                                                    AiBotOrders.IssueTrackedMove(oSelen, tMoveLocation, 2, false, 'SelBlckB', true)
                                                                    AiBotMicro.TrackTemporaryUnitMicro(oSelen, 8)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end


                                                --Mex specific - build a separate unit
                                                if iActionToAssign == refActionBuildMex and iTotalBuildPowerWanted > 0 and iEngiCount > 0 then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Were building a mex at tBuildLocation='..repru(tBuildLocation)..'; however have already assigned an engineer and have more to assign, so will build at a different mex now') end
                                                    --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerAction, iCategoryToBuild, iMaxAreaToSearch, iCatToBuildBy, tAlternativePositionToLookFrom, bNotYetUsedLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData, bCalledFromGetBestLocation, sBlueprintOverride)
                                                    sBlueprint, tBuildLocation = GetBlueprintAndLocationToBuild(aiBrain, oFirstEngineer, iActionToAssign, iCategoryWanted, iMaxSearchRange, iAdjacencyCategory, nil,                                false,                          nil,             nil,                                   false,                  tLZOrWZData,    tLZOrWZTeamData)
                                                    if AiBotUtilities.IsTableEmpty(tBuildLocation) then break end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': New mex build location='..repru(tBuildLocation)) end
                                                end
                                            else
                                                AiBotUtilities.ErrorHandler('Need to add code for actions that dont involve building, ActionToAssign='..iActionToAssign..'; order ref='..(tiActionOrder[iActionToAssign] or 'nil'))
                                            end
                                        else
                                            AiBotUtilities.ErrorHandler('Missing action order type for iActionToAssign '..iActionToAssign)
                                        end
                                    end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Cant build the desired category so will stop trying to build it and reduce build power required') end
                                    iTotalBuildPowerWanted = 0
                                end
                            else
                                iTotalBuildPowerWanted = 0
                                if iOptionalFactionRequired then
                                    if not(tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted]) then tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted] = {} end
                                    tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted][iOptionalFactionRequired] = true
                                end
                            end
                        end
                    end
                end
            else --Dont have a category to search for
                --Order specific logic
                if iActionToAssign == refActionMoveToLandZone or iActionToAssign == refActionAttackMoveToLandZone then
                    local iTargetLZ
                    local iPlateauToMoveTo
                    if bIsWaterZone then
                        iTargetLZ = vOptionalVariable[2]
                        iPlateauToMoveTo = vOptionalVariable[1]
                    else
                        iTargetLZ = vOptionalVariable
                        iPlateauToMoveTo = iPlateauOrPond
                    end
                    local tTargetLZ = AiBotMap.tAllPlateaus[iPlateauToMoveTo][AiBotMap.subrefPlateauLandZones][iTargetLZ]

                    sOrderRef = sOrderRef..'TLZ='..iTargetLZ
                    if AiBotUtilities.IsTableEmpty(tTargetLZ) then
                        AiBotUtilities.ErrorHandler('Invalid LZ  for moving to, iPlateauOrPOND='..iPlateauOrPond..'; iPlateauToMoveTo='..(iPlateauToMoveTo or 'nil')..'; will do reprs of iTargetLZ in log')
                        LOG(sFunctionRef..': Invalid LZ for moving to, iPlateauOrPond='..(iPlateauOrPond or 'nil')..'; iTargetLZ='..reprs(iTargetLZ)..'; vOptionalVariable='..reprs(vOptionalVariable))
                    elseif not(AiBotUnitInfo.bDontConsiderCombinedArmy) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbContainsPureAiBotAndSharedAiBot] and tTargetLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbSharedHumanBase] then
                        iTotalBuildPowerWanted = 0
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont want engis to travel here as it is primarily a human base') end
                    else
                        --Check if we have engis moving from the target zone to this zone, in which case abort
                        local toEngisTravelingHereFromTarget = {}
                        local iTravelingPlateau, iTravelingZone
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                            for iTravelingEngi, oTravelingEngi in tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                                if not(oTravelingEngi.Dead) and oTravelingEngi[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] == iTargetLZ and not(oTravelingEngi:IsUnitState('Attached')) then
                                    table.insert(toEngisTravelingHereFromTarget, oTravelingEngi)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(toEngisTravelingHereFromTarget) == false then
                            iTotalBuildPowerWanted = 0
                            for iTravelingEngi, oTravelingEngi in toEngisTravelingHereFromTarget do
                                AiBotOrders.IssueTrackedClearCommands(oTravelingEngi)
                            end
                            tTargetLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP] = false
                        end
                        local tMoveLocation = tTargetLZ[AiBotMap.subrefMidpoint]
                        while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to move to iPlateauOrPond '..iPlateauOrPond..'; iTargetLZ='..iTargetLZ)
                            end
                            if iActionToAssign == refActionAttackMoveToLandZone then
                                AiBotOrders.IssueTrackedAggressiveMove(tEngineersOfTechWanted[iEngiCount], tMoveLocation, 5, false, sOrderRef)
                            else
                                AiBotOrders.IssueTrackedMove(tEngineersOfTechWanted[iEngiCount], tMoveLocation, 5, false, sOrderRef)
                            end
                            TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, {iPlateauToMoveTo, iTargetLZ}, nil, bMarkAsSpare)
                            UpdateBPTracking()
                        end
                    end
                elseif iActionToAssign == refActionMoveToWaterZone then
                    local iTargetWZ = vOptionalVariable
                    local iPond = AiBotMap.tiPondByWaterZone[iTargetWZ]
                    local tTargetWZ = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iTargetWZ]
                    sOrderRef = sOrderRef..'TWZ='..iTargetWZ
                    if AiBotUtilities.IsTableEmpty(tTargetWZ) then
                        AiBotUtilities.ErrorHandler('Invalid WZ  for moving to, iPlateauOrPond='..iPlateauOrPond..'; will do reprs of iTargetWZ in log')
                        LOG(sFunctionRef..': iTargetWZ='..reprs(iTargetWZ))
                    else
                        --Check if we have engis moving from the target zone to this zone, in which case abort
                        local toEngisTravelingHereFromTarget = {}
                        local iTravelingPlateau, iTravelingZone
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                            for iTravelingEngi, oTravelingEngi in tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                                if not(oTravelingEngi.Dead) and oTravelingEngi[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] == iTargetWZ and not(oTravelingEngi:IsUnitState('Attached')) then
                                    table.insert(toEngisTravelingHereFromTarget, oTravelingEngi)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(toEngisTravelingHereFromTarget) == false then
                            iTotalBuildPowerWanted = 0
                            for iTravelingEngi, oTravelingEngi in toEngisTravelingHereFromTarget do
                                AiBotOrders.IssueTrackedClearCommands(oTravelingEngi)
                            end
                            tTargetWZ[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefTbWantBP] = false
                        end
                        local tMoveLocation = tTargetWZ[AiBotMap.subrefMidpoint]
                        while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to move to iPlateauOrPond '..iPlateauOrPond..'; iTargetWZ='..iTargetWZ..'; iPond='..iPond)
                            end
                            AiBotOrders.IssueTrackedMove(tEngineersOfTechWanted[iEngiCount], tMoveLocation, 5, false, sOrderRef)
                            TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, iTargetWZ, bMarkAsSpare)
                            UpdateBPTracking()
                        end
                    end
                elseif iActionToAssign == refActionAssistUpgrade then
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) then
                        AiBotUtilities.ErrorHandler('Trying to assist upgrade but there are none for this LZ')
                    else
                        local oBestProgress
                        local iMexProgressAdjust --If we are stalling mass and want to assist an upgrade then prioritise mex upgrades over factory upgrades
                        local iLandFacProgressAdjust
                        if tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iLandFacProgressAdjust = -0.6 end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 5 then iMexProgressAdjust = 0.75
                        elseif tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.2 then
                            iMexProgressAdjust = 0.5
                        end
                        if vOptionalVariable and AiBotUnitInfo.IsUnitValid(vOptionalVariable) then
                            oBestProgress = vOptionalVariable
                        else
                            local iBestProgress = -0.4 --so we wont assist a t3 land fac upgrade in the air slot initially even if no other upgrades
                            local iCurProgress
                            for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit.GetWorkProgress then
                                    iCurProgress = (oUnit:GetWorkProgress() or 0)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iCurProgress='..iCurProgress..' for upgrading unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iMexProgressAdust='..iMexProgressAdjust) end
                                    if iMexProgressAdjust and EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then iCurProgress = iCurProgress + iMexProgressAdjust
                                    elseif iLandFacProgressAdjust and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory - categories.TECH1, oUnit.UnitId) then iCurProgress = iCurProgress + iLandFacProgressAdjust
                                    end
                                    if iCurProgress > iBestProgress then
                                        iBestProgress = iCurProgress
                                        oBestProgress = oUnit
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is oBestProgress valid='..tostring(AiBotUnitInfo.IsUnitValid(oBestProgress))..'; Best progress ID='..(oBestProgress.UnitId or 'nil')..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount) end
                        if oBestProgress then
                            while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to assist unit '..oBestProgress.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestProgress)) end
                                AiBotOrders.IssueTrackedGuard(tEngineersOfTechWanted[iEngiCount], oBestProgress, false, sOrderRef)
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                UpdateBPTracking()
                            end
                        end
                    end
                elseif iActionToAssign == refActionReclaimArea then
                    local bWantEnergyNotMass = vOptionalVariable[1]
                    local bGivenOrder = false
                    while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                        if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to reclaim nearby, iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount) end
                        --GetEngineerToReclaimNearbyArea(oEngineer,                       iPriorityOverride,   tLZOrWZTeamData, iPlateauOrPondOrPond, iLandOrWaterZone, bWantEnergyNotMass, bOnlyConsiderReclaimInRangeOfEngineer, iMinIndividualValueOverride, bIsWaterZone, bOptionalReturnTrueIfGivenOrder)
                        bGivenOrder = GetEngineerToReclaimNearbyArea(tEngineersOfTechWanted[iEngiCount], iCurPriority, tLZOrWZTeamData, iPlateauOrPond,           iLandOrWaterZone,      bWantEnergyNotMass, false,                               vOptionalVariable[2],        bIsWaterZone,  true)
                        if not(bGivenOrder) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Failed to give a valid reclaim order so aborting') end
                            iTotalBuildPowerWanted = 0 break
                        end
                        UpdateBPTracking()
                        if tLZOrWZTeamData[AiBotMap.subrefTotalMassReclaim] <= 0.1 then break end
                    end
                elseif iActionToAssign == refActionReclaimFriendlyUnit or iActionToAssign == refActionReclaimEnemyUnit then
                    --Search for nearest unit in LZ units to be reclaimed
                    local iNearestUnitDist = 10000
                    local oNearestUnit
                    local iCurDist

                    local tUnitsToReclaim
                    if vOptionalVariable then
                        if AiBotUtilities.IsTableEmpty(tUnitsToReclaim, true) then
                            tUnitsToReclaim = {vOptionalVariable}
                        else
                            tUnitsToReclaim = vOptionalVariable
                        end
                    else
                        tUnitsToReclaim = tLZOrWZTeamData[AiBotMap.subreftoUnitsToReclaim]
                    end

                    if AiBotUtilities.IsTableEmpty(tUnitsToReclaim) then
                        AiBotUtilities.ErrorHandler('Want to reclaim a unit but no units in LZ to reclaim')
                    else
                        while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                            if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to move to iPlateauOrPond '..iPlateauOrPond) end


                            local bAreDeadUnits = false
                            for iUnit, oUnit in tUnitsToReclaim do
                                if AiBotUnitInfo.IsUnitValid(oUnit) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tEngineersOfTechWanted[iEngiCount]:GetPosition(), oUnit:GetPosition())
                                    if iCurDist < iNearestUnitDist then
                                        iNearestUnitDist = iCurDist
                                        oNearestUnit = oUnit
                                    end
                                else
                                    --Have dead units in the list of units to reclaim, so need to update the table
                                    if not(bAreDeadUnits) then
                                        bAreDeadUnits = true
                                        ForkThread(AiBotEconomy.RefreshUnitsToReclaim, iTeam, iPlateauOrPond, iLandOrWaterZone)
                                    end
                                end
                            end

                            if oNearestUnit then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to reclaim oNearestUnit='..oNearestUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestUnit)) end
                                AiBotOrders.IssueTrackedReclaim(tEngineersOfTechWanted[iEngiCount], oNearestUnit, false, 'RecObs')
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                UpdateBPTracking()
                            else
                                break
                            end
                        end
                    end
                elseif iActionToAssign == refActionLoadOntoTransport then
                    if iTotalBuildPowerWanted > 0 and iEngiCount > 0 then
                        --Load onto first transport in LZ needing engis (max 1 engi per transport)]
                        for iTransport, oTransport in tLZOrWZTeamData[AiBotMap.reftoTransportsWaitingForUnits] do
                            if (oTransport[AiBotAir.refiEngisWanted] or 0) > 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Trying to load engi into transport, iEngiCount='..iEngiCount..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; oTransport='..oTransport.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTransport)..'; Engineer='..(tEngineersOfTechWanted[iEngiCount].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount]) or 'nil')..'; Transport engis wanted='..oTransport[AiBotAir.refiEngisWanted]..'; Transport cargo capacity='..AiBotAir.GetTransportEngiCargoAndRemainingCapacity(oTransport, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech])) end
                                AiBotOrders.IssueTrackedTransportLoad(tEngineersOfTechWanted[iEngiCount], oTransport, false, sOrderRef, false)
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority) --(not using bmarkasspare as dont want to change orders for an engiener loading into transport)
                                UpdateBPTracking()
                                if bDebugMessages == true then LOG(sFunctionRef..': Post sending order to load onto transport, iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount) end
                                if iEngiCount <= 0 or iTotalBuildPowerWanted <= 0 then
                                    break
                                end
                            end
                        end
                    end
                elseif iActionToAssign == refActionCaptureUnit then
                    local oUnitToCapture = vOptionalVariable
                    if bDebugMessages == true then LOG(sFunctionRef..': oUnitToCapture='..oUnitToCapture.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToCapture)..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount) end
                    while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                        if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to capture unit '..oUnitToCapture.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToCapture)..'; iEngiCount='..iEngiCount..' unless it is already capturing, is unit state capturing='..tostring(tEngineersOfTechWanted[iEngiCount]:IsUnitState('Capturing'))..'; Unit state='..AiBotUnitInfo.GetUnitState(tEngineersOfTechWanted[iEngiCount])) end
                        if not(tEngineersOfTechWanted[iEngiCount]:IsUnitState('Capturing')) then
                            AiBotOrders.IssueTrackedCapture(tEngineersOfTechWanted[iEngiCount], oUnitToCapture, false, 'Cap', false)
                        end
                        TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority) --(not using bmarkasspare since are capturing and dont want to abort part way through)
                        if bDebugMessages == true then LOG(sFunctionRef..': Recorded capture target after update='..(tEngineersOfTechWanted[iEngiCount][AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount][AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) or 'nil')) end
                        UpdateBPTracking()
                    end
                elseif iActionToAssign == refActionRepairUnit or iActionToAssign == refActionRepairAllyUnit then
                    local oUnitToRepair = vOptionalVariable
                    local bFirstEngi = true
                    --Exception - assisting a GE template unit that will require a lot more mass to complete and isnt almost done - in this scenario consider moving below the GE template (unless we are overflowing mass)
                    local tPositionToMoveNearFirst
                    local iDistanceToMoveNear
                    if oUnitToRepair[AiBotBuilding.reftArtiTemplateRefs] and (oUnitToRepair[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnitToRepair)) >= 35000 and oUnitToRepair:GetFractionComplete() < 0.9 and (1-oUnitToRepair:GetFractionComplete()) * oUnitToRepair[AiBotUnitInfo.refiUnitMassCost] >= 10000 and oUnitToRepair[AiBotBuilding.reftArtiTemplateRefs][2] == iLandOrWaterZone then
                        local tTemplateRef = tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates][oUnitToRepair[AiBotBuilding.reftArtiTemplateRefs][3]]
                        if tTemplateRef and tTemplateRef[AiBotMap.subrefGEMidpoint] then
                            --Check we appear to have enough shields built
                            iDistanceToMoveNear = AiBotUtilities.GetDistanceBetweenPositions(oUnitToRepair:GetPosition(), tTemplateRef[AiBotMap.subrefGEMidpoint])
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.9 and AiBotUtilities.IsTableEmpty(tTemplateRef[AiBotMap.subrefGEShieldUnits]) == false and table.getn(tTemplateRef[AiBotMap.subrefGEShieldUnits]) >= table.getn(tTemplateRef[AiBotMap.subrefGEShieldLocations]) - 1 then
                                tPositionToMoveNearFirst = tTemplateRef[AiBotMap.subrefGEMidpoint]
                            end
                        end
                    end
                    while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                        if bDebugMessages == true then LOG(sFunctionRef..': About to tell engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to repair nearby unit '..oUnitToRepair.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToRepair)..', iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; iEngiCount='..iEngiCount..'; tPositionToMoveNearFirst='..repru(tPositionToMoveNearFirst)..';  oUnitToRepair[AiBotBuilding.reftArtiTemplateRefs]='..repru( oUnitToRepair[AiBotBuilding.reftArtiTemplateRefs])..'; iDistanceToMoveNear='..(iDistanceToMoveNear or 'nil')..'; Distance between engineer and tPositionToMoveNear if nonblank='..AiBotUtilities.GetDistanceBetweenPositions(tEngineersOfTechWanted[iEngiCount]:GetPosition(), (tPositionToMoveNearFirst or {0,0,0}))) end
                        if tPositionToMoveNearFirst and AiBotUtilities.GetDistanceBetweenPositions(tEngineersOfTechWanted[iEngiCount]:GetPosition(), tPositionToMoveNearFirst) > iDistanceToMoveNear then
                            AiBotOrders.IssueTrackedMove(tEngineersOfTechWanted[iEngiCount], tPositionToMoveNearFirst, 2, false, 'RepCons', false)
                        else
                            AiBotOrders.IssueTrackedRepair(tEngineersOfTechWanted[iEngiCount], oUnitToRepair, false, 'RepA'..iActionToAssign..'Pr'..iCurPriority, false)
                            if iDistanceToMoveNear then tEngineersOfTechWanted[iEngiCount][refiRepairProgressWhenLastChecked] = oUnitToRepair:GetFractionComplete() end
                        end
                        TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                        if bFirstEngi and iTotalBuildPowerWanted > 30 and iActionToAssign == refActionRepairAllyUnit then
                            --Send message to teammate that are helping them
                            if AiBotOrders.bDontConsiderCombinedArmy or tEngineersOfTechWanted[iEngiCount].AiBotActive then
                                AiBotChat.SendMessage(aiBrain, 'HelpAllyBuild'..oUnitToRepair:GetAIBrain():GetArmyIndex(), oUnitToRepair:GetAIBrain().Nickname..' I\'m sending some engineers to help you with that '..LOC((oUnitToRepair:GetBlueprint().Description or 'unit')), 3, 3600, true, true)
                            end
                        end
                        UpdateBPTracking()
                        bFirstEngi = false
                    end
                elseif iActionToAssign == refActionSpecialShieldDefence then
                    --Get list of units in zone that want defence and get the best faction they think is available
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of units for special shield protection empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]))) end
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) then
                        AiBotUtilities.ErrorHandler('Are trying to do special shield protection but have no units wanting it')
                    else
                        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
                            if oUnit[AiBotBuilding.refoNearbyFactoryOfFaction] then
                                iOptionalFactionRequired = AiBotUnitInfo.GetUnitFaction(oUnit)
                                break
                            end
                        end
                        if iOptionalFactionRequired then tEngineersOfTechWanted, iEngiCount = FilterEngineersOfTechAndEngiCountForFaction(iOptionalFactionRequired, tEngineersOfTechWanted, true) end
                        if iEngiCount > 0 then
                            while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                AssignEngineerToShieldDefenceDuty(tEngineersOfTechWanted[iEngiCount], tLZOrWZTeamData)
                                if bDebugMessages == true then LOG(sFunctionRef..': Have just assigned engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to do special shield protection logic, will now update tracking of that engineer') end
                                --TRACKING NOTE - this will get cleared so the ActiveShieldMonitor will then impute backup values - i.e. changes made to below are unlikely to have an effect
                                TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                UpdateBPTracking()
                            end
                        else
                            iTotalBuildPowerWanted = 0
                            if iOptionalFactionRequired then
                                --Flag that we need engineers of the desired faction
                                if not(tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted]) then tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted] = {} end
                                tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted][iOptionalFactionRequired] = true
                            end
                        end
                    end
                elseif iActionToAssign == refActionManageGameEnderTemplate then
                    if iEngiCount > 0 then
                        while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                            AssignEngineerToGameEnderTemplate(tEngineersOfTechWanted[iEngiCount], tLZOrWZData, tLZOrWZTeamData, iPlateauOrPond, iLandOrWaterZone)
                            if bDebugMessages == true then LOG(sFunctionRef..': Have just assigned engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to do special game ender or t3 arti construction, iTeam='..iTeam) end
                            --TRACKING NOTE - this will get cleared so the ActiveShieldMonitor will then impute backup values - i.e. changes made to below are unlikely to have an effect
                            TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                            UpdateBPTracking()
                        end
                    end
                elseif iActionToAssign == refActionGiveEngineerToTeammate then
                    if iEngiCount > 0 then
                        --Check the brain still exists
                        if tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi] and not(tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi].AiBotIsDefeated) and not(tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi]:IsDefeated()) then
                            local iFailedLoopCount = 0
                            while iTotalBuildPowerWanted > 0 and iEngiCount > 0 do
                                if bDebugMessages == true then LOG(sFunctionRef..': About to gift engineer '..tEngineersOfTechWanted[iEngiCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEngineersOfTechWanted[iEngiCount])..' to brain '..tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi].Nickname) end
                                --Check the engineer isnt owned by the same brain
                                local oEngiBrain = tEngineersOfTechWanted[iEngiCount]:GetAIBrain()
                                if not(oEngiBrain == tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi]) then
                                    ForkThread(AiBotTeam.TransferUnitsToPlayer, { tEngineersOfTechWanted[iEngiCount] }, tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi]:GetArmyIndex(), false)
                                    AiBotChat.SendMessage(oEngiBrain, 'EngiXfer', 'I\'ve just given you an engineer '..tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi].Nickname..', maybe you could give me one of yours in exchange?', 5, 5, true, false, nil, nil, nil)
                                    --TRACKING NOTE - our engineer unit will be killed from being transferred, this is primarily so iEngiCount gets updated/avid infinite loop
                                    TrackEngineerAction(tEngineersOfTechWanted[iEngiCount], iActionToAssign, false, iCurPriority, nil, nil, bMarkAsSpare)
                                    UpdateBPTracking()
                                else
                                    if iEngiCount <= 1 then break end
                                    iFailedLoopCount = iFailedLoopCount + 1
                                    if iFailedLoopCount >= 5 then break end --redundancy
                                end
                            end
                        end
                        tLZOrWZTeamData[AiBotMap.subrefoBrainWantingEngi] = nil
                    end
                else
                    if not(aiBrain[AiBotOverseer.refbCloseToUnitCap]) then
                        --Exception for experimentals, as sometimes we hold off building anything because we want a different faction on the team to build
                        if not(iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental) then
                            local bMightBeWaitingForFriendlySeraExp = false
                            if (iActionToAssign == refActionBuildExperimental or iActionToAssign == refActionBuildSecondExperimental) and not(tbEngineersOfFaction[AiBotUnitInfo.refFactionSeraphim]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then bMightBeWaitingForFriendlySeraExp = true break end
                                end
                            end
                            if not(bMightBeWaitingForFriendlySeraExp) then
                                AiBotUtilities.ErrorHandler('Unrecognised order, need to add logic, iActionToAssign='..(iActionToAssign or 'nil'))
                            end
                        end
                    end
                    iTotalBuildPowerWanted = 0
                end
            end
        end

        --If we still have build power we want to assign, record in the land zone
        if bDebugMessages == true then LOG(sFunctionRef..': About to update BP wanted for iPlateauOrPond'..iPlateauOrPond..'; iLandOrWaterZone='..iLandOrWaterZone..'; iTeam='..iTeam..'; iTotalBuildPowerWanted='..iTotalBuildPowerWanted..'; tLZBuildPowerByTechWanted before update='..repru(tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])) end
        if iTotalBuildPowerWanted > 0 and not(bDontIncreaseLZBPWanted) then
            local iAdditionalBuildPowerWanted
            if not(tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][iActionToAssign]) then
                iAdditionalBuildPowerWanted = iTotalBuildPowerWanted
            else
                if bBPIsInAdditionToExisting then
                    iAdditionalBuildPowerWanted = iTotalBuildPowerWanted
                    iTotalBuildPowerWanted = tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][iActionToAssign] + iTotalBuildPowerWanted
                else
                    iAdditionalBuildPowerWanted = math.max(0, iTotalBuildPowerWanted - tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][iActionToAssign])
                end
            end
            if iAdditionalBuildPowerWanted > 0 then
                tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][iActionToAssign] = iTotalBuildPowerWanted
                tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iMinTechWanted] = (tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iMinTechWanted] or 0) + iTotalBuildPowerWanted
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    for iTech = 3, 1, -1 do
        if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[iTech]) == false then
            return iTech
        end
    end
    return 0
end

function UpdateSpareEngineerNumber(tLZOrWZTeamData, toAvailableEngineersByTech)
    --Intended to be called after running all engineer builder logic for the LZ
    tLZOrWZTeamData[AiBotMap.subrefSpareBPByTech] = {[1]=0, [2]=0,[3]=0}
    local iTotalBP
    for iTech = 1, 3, 1 do
        if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[iTech]) == false then
            iTotalBP = 0
            for iUnit, oUnit in toAvailableEngineersByTech[iTech] do
                iTotalBP = iTotalBP + oUnit:GetBlueprint().Economy.BuildRate
                if AiBotConfig.AiBotShowUnitNames then AiBotOrders.UpdateUnitNameForOrder(oUnit, 'Idle') end
            end
            tLZOrWZTeamData[AiBotMap.subrefSpareBPByTech][iTech] = iTotalBP
            if not(tLZOrWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech]) then tLZOrWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech] = {} end
            tLZOrWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech][iTech] = GetGameTimeSeconds()
        end
    end
end

function GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, bCoreZone, bHaveLowMass, bWantMorePower, bOptionalAvailableT3Engineers)
    --Returns BP to assign, and whether it should be assigned to assist the SMD (returns true) rather than building a new SMD
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPToAssignToSMD'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iBPWanted = 0
    local bAssistSMD = false
    local oUnshieldedSMD
    local oUnderConstructionShield
    --Does this LZ have enough value?
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want SMD for iPlateau '..iPlateau..'; iLandZone '..iLandZone..'; LZ building vlaue='..(tLZTeamData[AiBotMap.subrefLZSValue] or 'nil')..'; AiBotMap.bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap)..'; Is ScenarioInfo.CzarEngineer nil='..tostring(ScenarioInfo.CzarEngineer == nil)..'; ScenarioInfo.M1P1.Active='..tostring(ScenarioInfo.M1P1.Active or false)..'; ScenarioInfo.Czar is nil='..tostring(ScenarioInfo.Czar == nil)..'; ScenarioInfo.CzarFullyBuilt='..tostring(ScenarioInfo.CzarFullyBuilt or false)..'; ScenarioInfo.ControlCenter is nil='..tostring(ScenarioInfo.ControlCenter == nil)..'; Are we a cybran brain? army index='..ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetFactionIndex()..'; refbDefendAgainstArti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or false)) end
    local bObjectiveCategory = (tLZTeamData[AiBotMap.reftObjectiveLocation] and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategorySMD, tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjCategoryToBuild]))
    local bObjectiveWantMoreSMD = false
    if bObjectiveCategory then bObjectiveWantMoreSMD = AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation]) end
    if tLZTeamData[AiBotMap.subrefLZSValue] >= 11000 or bObjectiveCategory or (tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] <= 360) then
        --Special case for Cybran M6 - early on want to risk not getting SMD so can improve eco to deal with czar
        if AiBotMap.bIsCampaignMap and ScenarioInfo.ControlCenter and (ScenarioInfo.CzarEngineer or ScenarioInfo.Czar or (GetGameTimeSeconds() <= 250 and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].GetFactionIndex and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetFactionIndex() == AiBotUnitInfo.refFactionCybran)) and not(ScenarioInfo.CzarFullyBuilt) and GetGameTimeSeconds() <= 1200 and (ScenarioInfo.M1P1.Active or GetGameTimeSeconds() <= 250) then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to hold off on getting SMD for now as want to save up to fight the czar') end
        else
            local tSMD = EntityCategoryFilterDown(AiBotUnitInfo.refCategorySMD, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local iSMDsWeHave = 0
            local iSMDsWithNoMissiles = 0
            local iUnderConstructionSMD = 0
            local iHighestCompletionUnshieldedSMD = 0.1 --No point shielding SMD below this as we risk it decaying before shield is complete
            local bHaveShieldCoverage
            if AiBotUtilities.IsTableEmpty(tSMD) == false then
                for iSMDNumber, oSMD in tSMD do
                    --Check we've completed construction
                    if AiBotUnitInfo.IsUnitValid(oSMD) then
                        if bDebugMessages == true then LOG(sFunctionRef .. ': Have an SMD '..oSMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSMD)..', will check if its completed construction; fraction complete='..oSMD:GetFractionComplete()..'; Ammo count='..oSMD:GetTacticalSiloAmmoCount()..'; oSMD[AiBotBuilding.refbMissileRecentlyBuilt]='..tostring(oSMD[AiBotBuilding.refbMissileRecentlyBuilt] or false)..'; Does SMD have an empty table of shields covering it='..tostring(AiBotUtilities.IsTableEmpty(oSMD[AiBotBuilding.reftoShieldsProvidingCoverage]))..'; Does SMD want shield coverage='..tostring(oSMD[AiBotBuilding.refbUnitWantsShielding] or false)..'; oSMD[refiFailedShieldConstructionCount]='..(oSMD[refiFailedShieldConstructionCount] or 'nil')..'; iHighestCompletionUnshieldedSMD='..iHighestCompletionUnshieldedSMD) end
                        --Consider if we want to focus on shielding for this SMD instead
                        if oSMD[AiBotBuilding.refbUnitWantsShielding] and AiBotUtilities.IsTableEmpty(oSMD[AiBotBuilding.reftoShieldsProvidingCoverage]) and (oSMD[refiFailedShieldConstructionCount] or 0) <= 2 and oSMD:GetFractionComplete() > iHighestCompletionUnshieldedSMD then
                            iHighestCompletionUnshieldedSMD = oSMD:GetFractionComplete()
                            oUnshieldedSMD = oSMD
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting oSMD as one that we want to shield') end
                        elseif oSMD:GetFractionComplete() > iHighestCompletionUnshieldedSMD and AiBotConditions.IsTableOfUnitsStillValid(oSMD[AiBotBuilding.reftoShieldsProvidingCoverage]) then
                            bHaveShieldCoverage = false
                            for iShield, oShield in oSMD[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                if oShield:GetFractionComplete() == 1 then
                                    bHaveShieldCoverage = true
                                    break
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bHaveShieldCoverage='..tostring(bHaveShieldCoverage or false)) end
                            if not(bHaveShieldCoverage) then
                                local iClosestShieldCompletion = 0
                                iHighestCompletionUnshieldedSMD = oSMD:GetFractionComplete()
                                for iShield, oShield in oSMD[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                    if oShield:GetFractionComplete() > iClosestShieldCompletion and not(oShield[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                                        iClosestShieldCompletion = oShield:GetFractionComplete()
                                        oUnderConstructionShield = oShield
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': want to assist part complete shield, oUnderConstructionShield='..(oUnderConstructionShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnderConstructionShield) or 'nil')) end
                            end
                        end
                        if oSMD:GetFractionComplete() == 1 then
                            iSMDsWeHave = iSMDsWeHave + 1
                            if oSMD.GetTacticalSiloAmmoCount and oSMD:GetTacticalSiloAmmoCount() < 1 and not (oSMD[AiBotBuilding.refbMissileRecentlyBuilt]) then
                                iSMDsWithNoMissiles = iSMDsWithNoMissiles + 1
                                if bDebugMessages == true then LOG(sFunctionRef..': SMD has no missile, iSMDsWithNoMissiles='..iSMDsWithNoMissiles) end
                            end
                        else
                            iUnderConstructionSMD = iUnderConstructionSMD + 1
                        end
                    end
                end
            end

            local iEnemyNukes = 0 --Cant use table.getn
            local iEnemyBattleshipNukes = 0
            local iEnemyNormalNukes = 0
            local bEnemyNukeNotConstructed = true
            local iHighestEnemyNormalNukeBuildRate = 1
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) then
                for iNuke, oNuke in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers] do
                    if EntityCategoryContains(categories.BATTLESHIP, oNuke.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Battleship progress='..oNuke:GetWorkProgress()..'; GetNukeSiloAmmoCount='..oNuke:GetNukeSiloAmmoCount()) end
                        if oNuke:GetNukeSiloAmmoCount() > 0 then
                            iEnemyNormalNukes = iEnemyNormalNukes + 1
                        elseif oNuke:GetFractionComplete() >= 1 then
                            iEnemyBattleshipNukes = iEnemyBattleshipNukes + 1
                        end
                    elseif EntityCategoryContains(categories.EXPERIMENTAL, oNuke.UnitId) then
                        iEnemyNormalNukes = iEnemyNormalNukes + 8
                    else
                        iEnemyNormalNukes = iEnemyNormalNukes + 1
                        iHighestEnemyNormalNukeBuildRate = math.max(iHighestEnemyNormalNukeBuildRate, (oNuke:GetAIBrain()[AiBotEconomy.refiBrainBuildRateMultiplier] or 1))
                    end
                    if oNuke.GetFractionComplete and oNuke:GetFractionComplete() >= 0.95 then
                        bEnemyNukeNotConstructed = false
                    end
                end
            elseif bDebugMessages == true then
                LOG(sFunctionRef .. ': No SML detected but will build SMD anyway as a precaution as we have a good economy')
            end
            if iEnemyBattleshipNukes > 0 and iEnemyNormalNukes == 0 and (bHaveLowMass or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 600 or AiBotMap.bIsCampaignMap or tLZTeamData[AiBotMap.subrefMexCountByTech][3] < 4))) then
                iEnemyNukes = 0
            elseif iEnemyNormalNukes > 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false then
                iEnemyNukes = math.max(iEnemyNormalNukes, iEnemyBattleshipNukes * 0.2, 1) --Redundancy - if table isnt empty enemy must have at least one, and will assume they have 1 if we are building as a precaution
            else
                iEnemyNukes = math.max(iEnemyNormalNukes, iEnemyBattleshipNukes * 0.2)
            end
            if oUnshieldedSMD and iHighestCompletionUnshieldedSMD < 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) then
                --dont want to shield SMD as a priority if we arent worried about arti/novax
                if bDebugMessages == true then LOG(sFunctionRef..': enemy lacks T3 arti or novax so want to prioritise building SMD overt building shield for it') end
                oUnshieldedSMD = nil
                oUnderConstructionShield = nil
            end
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': iSMDsWeHave=' .. iSMDsWeHave .. '; iEnemyNukes=' .. iEnemyNukes..'; iEnemyNormalNukes='..iEnemyNormalNukes..'; iEnemyBattleshipNukes='..iEnemyBattleshipNukes..'; bEnemyNukeNotConstructed='..tostring(bEnemyNukeNotConstructed))
                if iEnemyNukes > 1 then
                    LOG(sFunctionRef .. ': Will now list out each nuke unit ID')
                    for iNuke, oNuke in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers] do
                        LOG(sFunctionRef .. ': iNuke=' .. iNuke .. '; oNuke=' .. oNuke.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oNuke))
                    end
                end
            end
            local iSMDWanted = math.min(iEnemyNukes, math.max(1, math.floor((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) / 5)))
            if bHaveLowMass then
                iSMDWanted = math.min( iEnemyNukes * 2 / 3, iSMDWanted)
                if iEnemyNukes <= 5 then iSMDWanted = math.min(iSMDWanted, 3) end
            end
            --Cap amount of SMD, in turn depending on enemy nuke size
            if not(bObjectiveCategory) then
                if iEnemyNukes >= 5 and tLZTeamData[AiBotMap.subrefLZSValue] >= 12000 * iEnemyNukes then iSMDWanted = math.min(8, iSMDWanted)
                else iSMDWanted = math.min(4, iSMDWanted)
                end
            end

            if iEnemyNukes == 0 then
                --Dont get SMD if enemy has no nukes but has nearby T2 arti
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                    iSMDWanted = 0
                    --Dont get pre-emptive SMD if in LOUD (where they cost a lot more) unless we have built a lot of high level units first or the game has been going on ages
                elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and GetGameTimeSeconds() <= 4500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= math.min(4, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 1.5) and (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (bHaveLowMass or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, (AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.TECH3) < 50 * math.max(1, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.5)) then
                    iSMDWanted = 0
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to be slower to get preemptive SMD in LOUD/QUIET due to how much nukes cost') end
                end
            end

            if iSMDWanted <= 0 and (bObjectiveWantMoreSMD or (tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] <= 360)) then iSMDWanted = 1 end
            if iSMDsWeHave >= iSMDWanted and iHighestEnemyNormalNukeBuildRate > 1.2 and ((iSMDsWeHave == 1 and iSMDsWithNoMissiles == 0) or (iSMDsWeHave > 1 and iSMDsWithNoMissiles < iSMDsWeHave)) and iEnemyNormalNukes > 0 and iSMDsWeHave < iEnemyNormalNukes * iHighestEnemyNormalNukeBuildRate then iSMDWanted = iSMDWanted + math.min(2, math.max(1, iEnemyNormalNukes * iHighestEnemyNormalNukeBuildRate)) end
        if bDebugMessages == true then LOG(sFunctionRef..': iSMDsWeHave='..iSMDsWeHave..'; iSMDWanted='..iSMDWanted..'; iSMDsWithNoMissiles='..iSMDsWithNoMissiles) end
        if iSMDsWeHave < iSMDWanted or (iSMDsWithNoMissiles > 0 and (bObjectiveCategory or iEnemyNormalNukes > 0) and iSMDWanted <= 1) then
        if bHaveLowMass or iSMDsWeHave > 0 then iBPWanted = 150
        elseif bWantMorePower then iBPWanted = 225
        else iBPWanted = 300 end
        if not(bCoreZone) and not(bObjectiveCategory) then iBPWanted = iBPWanted * 0.5 end
        end
            if iSMDsWithNoMissiles > 0 and (iSMDsWeHave >= iSMDWanted or iSMDsWeHave == iSMDsWithNoMissiles) and iUnderConstructionSMD ==0 and (bObjectiveCategory or iEnemyNormalNukes > 0) then
        if bDebugMessages == true then LOG(sFunctionRef..': Want to assist SMD') end
        --If have under construction SMD then finish it off
        bAssistSMD = true
        iBPWanted = math.max(150, iBPWanted * 3)
        --first smd and enemy has nuke constructed - prioritise even more
        if iSMDsWithNoMissiles == iSMDsWeHave and iEnemyNormalNukes > 0 and not(bEnemyNukeNotConstructed) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > 500 then
            iBPWanted = iBPWanted + 120
            end
            end
        end
    end
    --Flag if we want a T3 engi drop (for plateaus that dont have access to T3)
    if iBPWanted > 0 and not(bAssistSMD) and not(bCoreZone) and not(bOptionalAvailableT3Engineers) and not(iPlateau == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) then
        --Do we want T3 engineers? check dont already have t3 traveling here from another zone
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.TECH3, tLZTeamData[AiBotMap.subrefTEngineersTravelingHere])) then
            --Check we lack T3 in this zone
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
                bOptionalAvailableT3Engineers = false
            else
                bOptionalAvailableT3Engineers = not(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory * categories.TECH3 + AiBotUnitInfo.refCategoryEngineer * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))
            end

            if bDebugMessages == true then LOG(sFunctionRef..': bOptionalAvailableT3Engineers='..tostring(bOptionalAvailableT3Engineers)..'; P'..iPlateau..'Z'..iLandZone) end
            if not(bOptionalAvailableT3Engineers) then
                AiBotAir.RecordPlateauForHighTechEngineerDrop(iPlateau, iLandZone, iTeam, 3)
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iBPWanted='..(iBPWanted or 'nil')..'; bAssistSMD='..tostring(bAssistSMD)..'; oUnderConstructionShield='..(oUnderConstructionShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnderConstructionShield) or 'nil')..'; Plateau of nearest friendly base='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted, bAssistSMD, oUnshieldedSMD, oUnderConstructionShield
end

function GetBPToAssignToMassStorage(iPlateauOrZero, iLandOrWaterZone, iTeam, tLZOrWZData, tLZOrWZTeamData, bCoreZone, bHaveLowMass, bWantMorePower)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPToAssignToMassStorage'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iBPWanted = 0
    --Are all mexes in the LZ at T2+ or do we have any T3 mexes in the LZ?
    if bDebugMessages == true then LOG(sFunctionRef..': iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; T2+T3 mex count='..(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] or 0) + (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] or 0)..'; T1 mex count='..(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] or 'nil')..'; Is table of mass storage locations to build empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]))..'; Size of mex table='..table.getn((tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] or {}))..'; Zone mex count='..(tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')) end
    if AiBotBuilding.iLowestMassStorageTechAvailable <= 2 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        --Do we have empty locations for mass storage?
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) == false then
            --Only try building mass storage if we have t2/t3 mex that needs the storage, if we also have t1/no mexes for some of the mass points in the zone (in case enemies are attacking and have killed them, to avoid us then tryign to rebuild mass storage around a t1 mex)
            local bHaveT2PlusMexWantingStorage = false
            local iT1AndT0MexCount = tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] - (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3])
            if iT1AndT0MexCount == 0 or (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and not(tLZOrWZTeamData[AiBotMap.subrefbLZWantsDFSupport])) then
                bHaveT2PlusMexWantingStorage = true
            else
                local iAvailableLocationCount = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable])
                if (ScenarioInfo.Options.AiBotTeammate == 1 or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and iAvailableLocationCount > 4 * iT1AndT0MexCount then
                    bHaveT2PlusMexWantingStorage = true
                else
                    local aiBrain = ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
                    local bDontCheckOwnership
                    if ScenarioInfo.Options.AiBotTeammate == 1 then bDontCheckOwnership = true else bDontCheckOwnership = false end
                    for _, tStorageLocation in tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable] do
                        if CanBuildAtLocation(aiBrain, 'ueb1106', tStorageLocation, iPlateauOrZero, iLandOrWaterZone, nil, false, false, false, false, false) then
                            local tNearbyUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(tStorageLocation, 4))
                            if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                                for iNearbyUnit, oNearbyUnit in tNearbyUnits do
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex - categories.TECH1, oNearbyUnit.UnitId) and oNearbyUnit:GetFractionComplete() >= 0.9 and (bDontCheckOwnership or (oNearbyUnit:GetAIBrain().AiBotAI and (AiBotOrders.bDontConsiderCombinedArmy or oNearbyUnit.AiBotActive))) then
                                        bHaveT2PlusMexWantingStorage = true
                                        break
                                    end
                                end
                                if bHaveT2PlusMexWantingStorage then break end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iAvailableLocationCount based on table.getn='..table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable])..'; iT1AndT0MexCount='..iT1AndT0MexCount..'; bHaveT2PlusMexWantingStorage='..tostring(bHaveT2PlusMexWantingStorage or false)) end
            if bHaveT2PlusMexWantingStorage then
                --Do we have really low power?
                if bDebugMessages == true then LOG(sFunctionRef..': Av energy%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
                if not(bWantMorePower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 0) then

                    iBPWanted = 10
                    if not (bHaveLowMass) or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= 5 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4 and tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) then
                        iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                        if not (bWantMorePower) then
                            iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2
                        end
                    else
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] > 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 then
                            iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 0.5
                        end
                    end
                elseif tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 50 then
                    iBPWanted = 5
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if have really low power, bWantMorePower='..tostring(bWantMorePower)..'; % E stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; iBPWanted='..iBPWanted) end
            end
        end
    end
    if iBPWanted > 0 and AiBotOverseer.bNoRushActive then
        --are any storage locations inside norush?
        local bCanBuild = false
        for iEntry, tLocation in tLZOrWZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable] do
            if AiBotConditions.IsLocationInNoRushArea(tLocation) then
                bCanBuild = true
                break
            end
        end
        if not(bCanBuild) then iBPWanted = 0 end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted
end

function GetBPToAssignToAssistUpgrade(tLZTeamData, iTeam, bCoreZone, bHaveLowMass, bHaveLowPower, bWantMorePower)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPToAssignToAssistUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iBPWanted = 0

    if bDebugMessages == true then LOG(sFunctionRef..': Considering if any active upgrades we want to assist; Is table of upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; ='..tostring(bWantMorePower)..'; Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and (not(bHaveLowPower) or (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 7))) then
        if not(bWantMorePower) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > 0.8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 2) then
            if bCoreZone then iBPWanted = 5 end
            if not(bHaveLowPower) then
                if not (bHaveLowMass) then
                    iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2
                    if not (bWantMorePower) then
                        iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2
                    end
                else
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] > 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 then
                        iBPWanted = iBPWanted + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                    end
                end
            end
            if not(bCoreZone) and iBPWanted > 5 then iBPWanted = math.min(25, iBPWanted * 0.5) end
        end
        --Increase assistance if we have lots of upgrades
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.95 and not(bHaveLowPower) then
            if table.getn(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) >= 3 then iBPWanted = iBPWanted * 2
            elseif table.getn(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == 2 then iBPWanted = iBPWanted * 1.25
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef .. ': iBPWanted=' .. iBPWanted) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted
end

function GetBPForShieldAssistance(tLZTeamData, iTeam)
    --Assist shields to defend against arti
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPForShieldAssistance'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iBPWanted = 0
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for game time='..GetGameTimeSeconds()..'; Are we defending against arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 2) then
        AiBotBuilding.RecordPriorityShields(iTeam, tLZTeamData)
        if bDebugMessages == true then LOG(sFunctionRef..': Is the table of priority shields empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]))) end
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false then
            local iEnemyT3ArtiValue = 0
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre, oUnit.UnitId) then
                            if oUnit:GetFractionComplete() >= 0.5 then
                                iEnemyT3ArtiValue = iEnemyT3ArtiValue + 0.5
                            else
                                iEnemyT3ArtiValue = iEnemyT3ArtiValue + 0.25
                            end

                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then
                            if oUnit:GetFractionComplete() >= 0.75 then
                                iEnemyT3ArtiValue = iEnemyT3ArtiValue + 1
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then iEnemyT3ArtiValue = iEnemyT3ArtiValue + 1 end
                            else
                                if oUnit:GetFractionComplete() >= 0.25 then
                                    iEnemyT3ArtiValue = iEnemyT3ArtiValue + 0.5
                                else
                                    iEnemyT3ArtiValue = iEnemyT3ArtiValue + 0.25
                                end
                            end
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites]) == false then
                local iNovaxCount = 0
                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites] do
                    iNovaxCount = iNovaxCount + 1
                end
                iEnemyT3ArtiValue = math.max(iEnemyT3ArtiValue, iNovaxCount * 0.5)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is the table of enemy arti empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]))..'; iEnemyT3ArtiValue='..iEnemyT3ArtiValue..'; number of priority shields for thie LZ='..table.getn(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist])) end
            local iShieldsWantingAssistance = 0
            local iShieldsRecentlyDamaged = 0
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.5 and iEnemyT3ArtiValue >= 2 then
                iShieldsWantingAssistance = table.getn(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist])
            else
                local iCurShield, iMaxShield

                for iShield, oShield in tLZTeamData[AiBotMap.reftPriorityShieldsToAssist] do
                    if AiBotUnitInfo.IsUnitValid(oShield) then
                        iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                        if iCurShield > 0 and not(oShield[AiBotUnitInfo.refbPaused]) then
                            if EntityCategoryContains(categories.TECH2, oShield.UnitId) then
                                if iCurShield < iMaxShield * 0.7 then
                                    iShieldsRecentlyDamaged = iShieldsRecentlyDamaged + 0.5
                                end
                            elseif iCurShield < iMaxShield then
                                if iCurShield < iMaxShield * 0.8 then
                                    iShieldsRecentlyDamaged = iShieldsRecentlyDamaged + 1
                                else
                                    iShieldsRecentlyDamaged = iShieldsRecentlyDamaged + 0.75
                                end
                            else
                                --How long since shield took damage?
                                if oShield[AiBotUnitInfo.refiTimeLastDamaged] and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeLastDamaged] or -100) <= 30 then --If changing also consider changing RecordPriorityShields
                                    if oShield[AiBotUnitInfo.refiTimeLastDamaged] and GetGameTimeSeconds() - (oShield[AiBotUnitInfo.refiTimeLastDamaged] or -100) <= 20 then
                                        iShieldsRecentlyDamaged = iShieldsRecentlyDamaged + 0.6
                                    else
                                        iShieldsRecentlyDamaged = iShieldsRecentlyDamaged + 0.3
                                    end
                                end
                            end
                        end
                    end
                end
                if iShieldsRecentlyDamaged > 0 then
                    local iTotalShields = table.getn(tLZTeamData[AiBotMap.reftPriorityShieldsToAssist])
                    if iTotalShields < iShieldsRecentlyDamaged then
                        iShieldsWantingAssistance = iShieldsRecentlyDamaged + (iTotalShields - iShieldsRecentlyDamaged) * 0.5
                    else
                        iShieldsWantingAssistance = iShieldsRecentlyDamaged
                    end
                end
                if tLZTeamData[AiBotMap.subrefLZbCoreBase] then iShieldsWantingAssistance = math.max(iShieldsWantingAssistance, 0.4) end

            end
            --Reduce BP for shield assistance if we have lots of mass - i.e. in late game scenario better to spend mass than to assist a full health shield
            iBPWanted = iShieldsWantingAssistance * math.max(120, math.min(780, (360 * iEnemyT3ArtiValue)))
            --Cap BP wanted to equiv of 33 engineers (22 if we have active gameender template in the zone)
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftActiveGameEnderTemplates]) then
                iBPWanted = math.min(iBPWanted, 990)
            else
                iBPWanted = math.min(iBPWanted, 660)
            end

        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iBPWanted='..iBPWanted) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted
end

function GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, bCoreZone, bHaveLowMass, bWantMorePower, bConsideringSecondShield, iLandZoneRef, iPlateau)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPMinTechAndUnitForFixedShields'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iBPWanted = 0
    local iTechLevelWanted = 2
    local oUnitToShield
    local iHighestMassValue = 0
    local iHighMassThreshold = 15000
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; P'..iPlateau..'Z'..iLandZoneRef..'; Is table of units wanting fixed shields empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield]))..'; bConsideringSecondShield='..tostring(bConsideringSecondShield or false)) end
    if AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield]) then
        --Early in a campaign (less than 20m in) - dont get shield if dont have good mass, unless on Aeon mission 5 where need to build shields to defend civilians
        local bGetShield = true
        if AiBotMap.bIsCampaignMap then
            if bHaveLowMass and GetGameTimeSeconds() <= 1200 and not(ScenarioInfo.Ariel and ScenarioInfo.UEF and ScenarioInfo.Colonies) then --First 20m
                --Does enemy have a >=60% complete arti, and game is at least 10m old?
                if GetGameTimeSeconds() >= 600 then
                    if AiBotConditions.GetEnemyT3ArtiEquivalent(iTeam, 1, 0, false, 0.6) > 0 then
                        bGetShield = true
                    else
                        bGetShield = false
                    end
                else
                    bGetShield = false
                end
            end
        else
            --Not a campaign map - dont get a shield if we have a low lifetime experimental count on our team and low mass
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                if (bHaveLowMass and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 20) then
                    bGetShield = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Have low mass so not getting shield') end
                elseif AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel) < (1 + 0.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                    bGetShield = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Havent built experimental yet so wont get shield') end
                    --LOUD - shields have a high E cost so dont build generally until we have very high energy
                elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotConditions.HaveLowPower(iTeam)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': LOUD/QUIET active so want to be less likely to get shielding') end
                    bGetShield = false
                end
                --Exception for core base if enemy has air exp and it is a bomber, and this zone has T3AA wanting shielding
                if bDebugMessages == true then LOG(sFunctionRef..': Considering exception for airexp, bGetShield='..tostring(bGetShield)..'; bCoreZone='..tostring(bCoreZone)..'; Is table of enemy air exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]))..'; Is table of units wanting shield include structureAA='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructureAA, tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield])))) end
                if not(bGetShield) and bCoreZone and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructureAA, tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield])) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Were going to hold off on shielding but we have AA wanting shielding and enemy has air exp') end
                    bGetShield = true
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bGetShield='..tostring(bGetShield)) end
        if bGetShield then

            --Shield the highest value unit in this LZ that wants a shield, factoring in failed shield attempts
            if bConsideringSecondShield then iHighestMassValue = iHighMassThreshold end --will only try shielding if we have very high value target (e.g. t3 arti or experimental) that is unshielded
            local iCurMass
            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            local iLowestShieldAttempt = 10 --dont want to keep trying to shield if have failed lots of times (the count gets reset over time)
            local iSegmentsToConsider = 4
            if tLZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] < tLZData[AiBotMap.subrefLZTotalSegmentCount] then iSegmentsToConsider = 15 end

            for iUnit, oUnit in tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield] do
                --Increase likelihood the build location we want is available
                if not(AiBotUtilities.bCPUPerformanceMode) or (oUnit[refiFailedShieldConstructionCount] or 0) > 0 then SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateau, iLandZoneRef, 15) end
                if (oUnit[refiFailedShieldConstructionCount] or 0) <= iLowestShieldAttempt then
                    iCurMass = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                    if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; iCurMass='..reprs(iCurMass)..'; iHighestMassValue='..reprs(iHighestMassValue)..'; (oUnit[refiFailedShieldConstructionCount]='..reprs(oUnit[refiFailedShieldConstructionCount])..'; iLowestShieldAttempt='..reprs(iLowestShieldAttempt)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Build cost mass via blueprint='..(__blueprints[oUnit.UnitId].Economy.BuildCostMass or 'nil'))
                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                            for iRecorded, oRecorded in oUnit[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                LOG(sFunctionRef..': oRecorded shield covering this='..oRecorded.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecorded)..'; is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oRecorded)))
                            end
                        else
                            LOG(sFunctionRef..': No shields are recorded as providing coverage')
                        end
                    end
                    if iCurMass and (iCurMass > iHighestMassValue or (oUnit[refiFailedShieldConstructionCount] or 0) < iLowestShieldAttempt) then
                        --Check we are likely to be able ot build a shield nearby
                        if (oUnit[refiFailedShieldBuildDistance] or 0) <= 17 then --Cybran ED4 has a readius of 17
                            if oUnit:GetFractionComplete() >= 0.35 or not(EntityCategoryContains(AiBotUnitInfo.refCategoryT2Mex, oUnit.UnitId)) or not(bHaveLowMass) then
                                --Redundancy - check we dont already ahve 2+ shields covering this for lower mass units
                                if iCurMass > 30000 or AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) or table.getn(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) <= 1 then
                                    iHighestMassValue = iCurMass
                                    oUnitToShield = oUnit
                                    iLowestShieldAttempt = (oUnit[refiFailedShieldConstructionCount] or 0)
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..'; iCurMass='..(iCurMass or 'nil')..'; Fraction complete='..oUnit:GetFractionComplete()..'; iHighestMassValue='..(iHighestMassValue or 'nil')..'; Failed shield build distance='..(oUnit[refiFailedShieldBuildDistance] or 0)..'; iLowestShieldAttempt='..iLowestShieldAttempt..'; (oUnit[refiFailedShieldConstructionCount] or 0)='..(oUnit[refiFailedShieldConstructionCount] or 0)..'; Is table of shields already providing coverage empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]))..'; Shield construction count condition='..tostring((oUnit[refiFailedShieldConstructionCount] or 0) <= iLowestShieldAttempt)) end
            end
            if oUnitToShield then
                if (not(EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnitToShield.UnitId)) or (EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex, oUnitToShield.UnitId) and not(bHaveLowMass) and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))) and (iHighestMassValue >= iHighMassThreshold or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 2)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 12000) then
                    iTechLevelWanted = 3
                    --Think have logic elsewhere which will make a T3 shield be built if nowhere for T2 shield that will cover it
                end
                iBPWanted = 210
                if bCoreZone or iHighestMassValue >= 25000 then iBPWanted = iBPWanted + 60 end
                if bWantMorePower then iBPWanted = iBPWanted * 0.75 end
                if bHaveLowMass then iBPWanted = iBPWanted * 0.75 end
                if tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 2 then
                    iBPWanted = iBPWanted * 1.5
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Have a unit to shield, bCoreZone='..tostring(bCoreZone or false)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or false)..'; bWantMorePower='..tostring(bWantMorePower)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; iBPWanted='..iBPWanted) end
            end
        end
    end

    --Second shield - dont get shield if dont ahve a first shield
    if iBPWanted > 0 and bConsideringSecondShield then
        local tExistingShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local bHaveCompletedShield = false
        if AiBotUtilities.IsTableEmpty(tExistingShields) == false then
            for iShield, oShield in tExistingShields do
                if oShield:GetFractionComplete() then
                    bHaveCompletedShield = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering second shield, bHaveCompletedShield in zone='..tostring(bHaveCompletedShield)) end
        if not(bHaveCompletedShield) then
            iBPWanted = 0
        end
    end

    if iBPWanted > 0 and iTechLevelWanted < 3 then
        if bDebugMessages == true then LOG(sFunctionRef..': oUnitToShield[refiFailedShieldBuildDistance] ='..(oUnitToShield[refiFailedShieldBuildDistance] or 'nil')..'; tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount]='..(tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 'nil')) end
        if oUnitToShield and (oUnitToShield[refiFailedShieldBuildDistance] or 0) > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryT2Mex, oUnitToShield.UnitId)) then
            iTechLevelWanted = 3
        elseif (tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 0) >= 5 then
            iTechLevelWanted = 3
        elseif (oUnitToShield[refiFailedShieldConstructionCount] or 0) >= 3 then
            iTechLevelWanted = 3
            if bDebugMessages == true then LOG(sFunctionRef..': Have struggled to shield unit so will try with T3 shield') end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': oUnitToShield='..(oUnitToShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToShield) or 'nil')..'; iBPWanted='..iBPWanted..'; iTechLevelWanted='..iTechLevelWanted..'; iHighestMassValue='..iHighestMassValue) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted, iTechLevelWanted, oUnitToShield
end

function GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, bOptionalReturnMassToCompleteOtherZoneUnderConstruction, iOptionalSearchRange, iOptionalCategoryFilter, bOptionalClearEngineersInOtherZonesWithoutConstruction, iOptionalTableRefToIgnoreForThisZone, iOptionalAirSubteam)
    --returns two variables, the first is true/false if iLandZone has a queued experimental to build; the second is the number of other land zones for iTeam that have queued experimentals to build
    --Optional variables are all for if bOptionalReturnMassToCompleteOtherZoneUnderConstruction is true, except for iOptionalCategoryFilter
    --bOptionalReturnMassToCompleteOtherZoneUnderConstruction will return the amount of mass needed to complete all under construction experimentals in other zones; if iOptionalTableRefToIgnoreForThisZone is specified then will include this zone unless it is a table ref equal to the specified one
    --iOptionalSearchRange Will only include those within iOptionalSearchRange; if 0 then will only include exp in this zone
    --iOptionalCategoryFilter - if specified, then will only count engineers who are building or are queued to build a unit meeting this category (will include everything if nil)
    --bOptionalClearEngineersInOtherZonesWithoutConstruction - if this is true, then will clear any engineers building an experimental in a dif zone to the one specified if it is only queued up for all those units and none have started construction
    --iOptionalTableRefToIgnoreForThisZone - if specified, then will only ignore engineers assigned to this table ref for the zone
    --iOptionalAirSubteam - if this is specified, only consider experimentals with this air subteam

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetExperimentalsBeingBuiltInThisAndOtherLandZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bHaveExperimentalForThisLandZone = false
    local iOtherLandZonesWithExperimental = 0
    local iMassToComplete
    if bOptionalReturnMassToCompleteOtherZoneUnderConstruction then iMassToComplete = 0 end

    if bDebugMessages == true then LOG(sFunctionRef..': Is table of engis building exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]))..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTeam='..iTeam..'; iOptionalTableRefToIgnoreForThisZone='..(iOptionalTableRefToIgnoreForThisZone or 'nil')..' bOptionalReturnMassToCompleteOtherZoneUnderConstruction='..tostring(bOptionalReturnMassToCompleteOtherZoneUnderConstruction or false)..'; iOptionalSearchRange='..(iOptionalSearchRange or 'nil')..'; is iOptionalCategoryFilter nil='..tostring(iOptionalCategoryFilter == nil)..'; Time='..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]) == false then
        local tiPlateauAndLZBuildingExperimental = {}
        local toUnderConstructionExperimentalsInOtherZonesByUnitRef = {}
        local tbOptionalPlateauAndZoneStartedConstruction
        local toOptionalQueuedEngineersByPlateauAndZone
        local iCurPlateau, iCurLZ
        local bIncludeCurEntry
        local sCurBPBeingBuilt
        for iEngi, oEngi in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals] do
            if AiBotUnitInfo.IsUnitValid(oEngi) and oEngi[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] and (not(iOptionalAirSubteam) or iOptionalAirSubteam == oEngi:GetAIBrain().AiBotAirSubteam) then
                iCurPlateau = oEngi[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                iCurLZ = oEngi[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                bIncludeCurEntry = nil
                if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLZ='..(iCurLZ or 'nil')..'; Engi last order blueprint='..(oEngi[AiBotOrders.reftiLastOrders][(oEngi[AiBotOrders.refiOrderCount] or 1)][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Engi last order reprs='..reprs(oEngi[AiBotOrders.reftiLastOrders])..'; is primary engineer='..tostring(oEngi[refbPrimaryBuilder] or false)..'; Engi assigned action='..(oEngi[refiAssignedAction] or 'nil'))
                    local oEngiOrderTarget = oEngi[AiBotOrders.reftiLastOrders][(oEngi[AiBotOrders.refiOrderCount] or 1)][AiBotOrders.subrefoOrderUnitTarget]
                    if AiBotUnitInfo.IsUnitValid(oEngiOrderTarget) then
                        LOG(sFunctionRef..': oEngiOrderTarget='..oEngiOrderTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngiOrderTarget)..'; Fraction complete='..oEngiOrderTarget:GetFractionComplete()..'; Do we either have no category filter or this unit contains the required category='..tostring(not(iOptionalCategoryFilter) or EntityCategoryContains(iOptionalCategoryFilter, oEngiOrderTarget.UnitId)))
                        local oOrderTargetFocus = oEngiOrderTarget:GetFocusUnit()
                        if AiBotUnitInfo.IsUnitValid(oOrderTargetFocus) then
                            LOG(sFunctionRef..': oOrderTargetFocus='..oOrderTargetFocus.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTargetFocus)..'; fraction complete='..oOrderTargetFocus:GetFractionComplete())
                        end
                    end
                end
                if bOptionalReturnMassToCompleteOtherZoneUnderConstruction then --Check if want to include this
                    if not(iCurLZ == iLandZone and iPlateau == iCurPlateau and (iOptionalTableRefToIgnoreForThisZone == nil or iOptionalTableRefToIgnoreForThisZone == oEngi[AiBotBuilding.reftArtiTemplateRefs][3] == iOptionalTableRefToIgnoreForThisZone)) then
                        local oCurExperimental = oEngi:GetFocusUnit() or oEngi[AiBotOrders.reftiLastOrders][(oEngi[AiBotOrders.refiOrderCount] or 1)][AiBotOrders.subrefoOrderUnitTarget]
                        --if bDebugMessages == true then LOG(sFunctionRef..': Is oCurExperimental valid='..tostring(AiBotUnitInfo.IsUnitValid(oCurExperimental))) end
                        if AiBotUnitInfo.IsUnitValid(oCurExperimental) and oCurExperimental:GetFractionComplete() < 1 then
                            if not(iOptionalCategoryFilter) or EntityCategoryContains(iOptionalCategoryFilter, oCurExperimental.UnitId) then
                                if not(toUnderConstructionExperimentalsInOtherZonesByUnitRef[oCurExperimental.EntityId]) then
                                    bIncludeCurEntry = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Recording oCurExperimental as being under construction, oCurExperimental='..oCurExperimental.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurExperimental)) end
                                    toUnderConstructionExperimentalsInOtherZonesByUnitRef[oCurExperimental.EntityId] = oCurExperimental
                                end
                            end
                        end
                    end
                else
                    if not(iOptionalCategoryFilter) then
                        bIncludeCurEntry = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have an optional category filter o will include this zone as building an experimental') end
                    else
                        sCurBPBeingBuilt = oEngi[AiBotOrders.reftiLastOrders][(oEngi[AiBotOrders.refiOrderCount] or 1)][AiBotOrders.subrefsOrderBlueprint]
                        if bDebugMessages == true then LOG(sFunctionRef..': sCurBPBeingBuilt='..(sCurBPBeingBuilt or 'nil')) end
                        if sCurBPBeingBuilt and EntityCategoryContains(iOptionalCategoryFilter, sCurBPBeingBuilt) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Are queued up to be building a unit of the specified category so will include this zone as building an experimental') end
                            bIncludeCurEntry = true
                        else
                            local oCurExperimental = oEngi:GetFocusUnit()
                            if oCurExperimental and oCurExperimental:GetFractionComplete() < 1 and EntityCategoryContains(iOptionalCategoryFilter, oCurExperimental.UnitId) then
                                bIncludeCurEntry = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Engi is actively building the experimental' ..oCurExperimental.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurExperimental)) end
                            end
                        end
                    end
                end
                if bIncludeCurEntry then
                    if not(tiPlateauAndLZBuildingExperimental[iCurPlateau]) then tiPlateauAndLZBuildingExperimental[iCurPlateau] = {} end
                    tiPlateauAndLZBuildingExperimental[iCurPlateau][iCurLZ] = (tiPlateauAndLZBuildingExperimental[iCurPlateau][iCurLZ] or 0) + 1
                    if bOptionalClearEngineersInOtherZonesWithoutConstruction and not(tbOptionalPlateauAndZoneStartedConstruction[iCurPlateau][iCurLZ]) then
                        local oCurExperimental = oEngi:GetFocusUnit()
                        if oCurExperimental and oCurExperimental:GetFractionComplete() < 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oCurExperimental) then
                            if not(tbOptionalPlateauAndZoneStartedConstruction) then tbOptionalPlateauAndZoneStartedConstruction = {} end
                            if not(tbOptionalPlateauAndZoneStartedConstruction[iCurPlateau]) then tbOptionalPlateauAndZoneStartedConstruction[iCurPlateau] = {} end
                            tbOptionalPlateauAndZoneStartedConstruction[iCurPlateau][iCurLZ] = true
                        else
                            --Add engi to toOptionalQueuedEngineersByPlateauAndZone
                            if not(toOptionalQueuedEngineersByPlateauAndZone) then toOptionalQueuedEngineersByPlateauAndZone = {} end
                            if not(toOptionalQueuedEngineersByPlateauAndZone[iCurPlateau]) then toOptionalQueuedEngineersByPlateauAndZone[iCurPlateau] = {} end
                            if not(toOptionalQueuedEngineersByPlateauAndZone[iCurPlateau][iCurLZ]) then toOptionalQueuedEngineersByPlateauAndZone[iCurPlateau][iCurLZ] = {} end
                            table.insert(toOptionalQueuedEngineersByPlateauAndZone[iCurPlateau][iCurLZ], oEngi)
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is tiPlateauAndLZBuildingExperimental empty='..tostring(AiBotUtilities.IsTableEmpty(tiPlateauAndLZBuildingExperimental))..'; reprs='..reprs(tiPlateauAndLZBuildingExperimental)) end
        if AiBotUtilities.IsTableEmpty(tiPlateauAndLZBuildingExperimental) == false then
            local tBaseLZDataIfRelevant
            if iOptionalSearchRange then tBaseLZDataIfRelevant = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
            end
            if tBaseLZDataIfRelevant then
                for iAssignedPlateau, tEngineersByLZ in tiPlateauAndLZBuildingExperimental do
                    for iAssignedLZ, iEngineersAssigned in tEngineersByLZ do
                        if iPlateau == iAssignedPlateau and iLandZone == iAssignedLZ then
                            bHaveExperimentalForThisLandZone = true
                        else
                            if not(iOptionalSearchRange) then
                                iOtherLandZonesWithExperimental = iOtherLandZonesWithExperimental + 1
                            elseif iOptionalSearchRange > 0 then

                                local tExpLZData = AiBotMap.tAllPlateaus[iAssignedPlateau][AiBotMap.subrefPlateauLandZones][iAssignedLZ]
                                if tExpLZData[AiBotMap.subrefMidpoint] and AiBotUtilities.GetDistanceBetweenPositions(tExpLZData[AiBotMap.subrefMidpoint], tBaseLZDataIfRelevant[AiBotMap.subrefMidpoint]) <= iOptionalSearchRange then
                                    iOtherLandZonesWithExperimental = iOtherLandZonesWithExperimental + 1
                                end
                            end
                        end
                    end
                end
            end
        end
        if bOptionalReturnMassToCompleteOtherZoneUnderConstruction and AiBotUtilities.IsTableEmpty(toUnderConstructionExperimentalsInOtherZonesByUnitRef) == false then
            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
            if tLZData then
                for iUnit, oUnit in toUnderConstructionExperimentalsInOtherZonesByUnitRef do
                    if not(iOptionalSearchRange) or ((iOptionalSearchRange > 0 or (iOptionalTableRefToIgnoreForThisZone and not(iOptionalTableRefToIgnoreForThisZone == oUnit[AiBotBuilding.reftArtiTemplateRefs][3]))) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= iOptionalSearchRange) then
                        iMassToComplete = iMassToComplete + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * (1 - oUnit:GetFractionComplete())
                    end
                end
            end
        end
        if bOptionalClearEngineersInOtherZonesWithoutConstruction and AiBotUtilities.IsTableEmpty(tiPlateauAndLZBuildingExperimental) == false then
            for iRecordedPlateau, tRecordedZones in tiPlateauAndLZBuildingExperimental do
                for iRecordedLZ, iRecordedUnits in tRecordedZones do
                    if iRecordedUnits > 0 and not(tbOptionalPlateauAndZoneStartedConstruction[iRecordedPlateau][iRecordedLZ]) and not(iRecordedPlateau == iPlateau and iRecordedLZ == iLandZone) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..iRecordedPlateau..'Z'..iRecordedLZ..'; iRecordedUnits='..iRecordedUnits..'; tbOptionalPlateauAndZoneStartedConstruction='..repru(tbOptionalPlateauAndZoneStartedConstruction)..'; will clear all engineers in this zone; is toOptionalQueuedEngineersByPlateauAndZone empty='..tostring(AiBotUtilities.IsTableEmpty(toOptionalQueuedEngineersByPlateauAndZone[iRecordedPlateau][iRecordedLZ]))) end
                        if AiBotUtilities.IsTableEmpty(toOptionalQueuedEngineersByPlateauAndZone[iRecordedPlateau][iRecordedLZ]) == false then
                            for iRecordedEngi, oRecordedEngi in toOptionalQueuedEngineersByPlateauAndZone[iRecordedPlateau][iRecordedLZ] do
                                if AiBotUtilities.IsTableEmpty(oRecordedEngi[AiBotBuilding.reftArtiTemplateRefs]) then --redundancy
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will clear oRecordedEngi='..oRecordedEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedEngi)..'; Unit state='..AiBotUnitInfo.GetUnitState(oRecordedEngi)) end
                                    AiBotOrders.IssueTrackedClearCommands(oRecordedEngi)
                                end
                            end
                        end
                    end
                end
            end

        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; iMassToComplete='..(iMassToComplete or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete
end

function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPByTechWantedForAlternativeLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tiBPWantedByTech
    local tAltLZ = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
    if not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tAltLZ[AiBotMap.subrefMidpoint]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] then
        local tAltLZTeamData = tAltLZ[AiBotMap.subrefLZTeamData][iTeam]
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Does iAdjLZ '..iAdjLZ..' for plateau '..iPlateau..' want BP='..tostring(tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP])..'; bIslandPathing='..tostring(bIslandPathing or false)..'; base tLZData[AiBotMap.subrefLZIslandRef]='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; iAdjLZ tAltLZ[AiBotMap.subrefLZIslandRef]='..(tAltLZ[AiBotMap.subrefLZIslandRef] or 'nil')..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tAltLZ[AiBotMap.subrefMexUnbuiltLocations]))..'; bRequireUnbuiltMexes='..tostring(bRequireUnbuiltMexes or false)) end
        if (not(bRequireUnbuiltMexes) or (AiBotUtilities.IsTableEmpty(tAltLZ[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase]) or AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryEngineer, tAltLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))))
        and (not(bCheckIfEngisRecentlyRun) or not(tAltLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or
            (AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false and (GetGameTimeSeconds() - (tAltLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] or 0) >= 30 or (tAltLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 100 and tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 40 and GetGameTimeSeconds() - (tAltLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] or 0) >= 15)))
         or (AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == true  and (GetGameTimeSeconds() - (tAltLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] or 0) >= 20 or (tAltLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 100 and tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 40 and GetGameTimeSeconds() - (tAltLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] or 0) >= 10)))) then
            local iTotalBPWanted = 0
            --Do we need unbuilt mexes?


            --Does the LZ want BP?
            if tAltLZTeamData[AiBotMap.subrefTbWantBP] or bIslandPathing then
                --Do we have engis of the right tech level to give to the LZ? (ignore this check if we are trying to move engineers to an island for which the closest LZ doesnt want engineers
                local bHaveSufficientTech = false
                if tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP] then
                    for iTech = 1, iHighestTechEngiAvailable, 1 do
                        if (tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech] or 0) > 0 then
                            bHaveSufficientTech = true
                            break
                        end
                    end
                end

                if bHaveSufficientTech or (bIslandPathing and not(tLZData[AiBotMap.subrefLZIslandRef] == tAltLZ[AiBotMap.subrefLZIslandRef])) then
                    --Would we path through any dangerous LZs?
                    if AiBotLand.IsLandZonePathSafe(iPlateau, tLZData, iTeam, iPathingRef, bIslandPathing) then
                        tiBPWantedByTech = {[1]=0,[2]=0,[3]=0}
                        if not(bIslandPathing) or bHaveSufficientTech then
                            for iTech = 1, iHighestTechEngiAvailable, 1 do
                                if (tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech] or 0) > 0 then
                                    tiBPWantedByTech[iTech] = tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech]
                                    iTotalBPWanted = iTotalBPWanted + tiBPWantedByTech[iTech]
                                end
                            end
                        else
                            for iEntry, iIslandLZ in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][tAltLZ[AiBotMap.subrefLZIslandRef]] do
                                local tIslandLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIslandLZ]
                                if tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP] and AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEngineersTravelingHere]) then
                                    for iTech = 1, iHighestTechEngiAvailable, 1 do
                                        if (tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech] or 0) > 0 then
                                            tiBPWantedByTech[iTech] = tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][iTech]
                                            iTotalBPWanted = iTotalBPWanted + tiBPWantedByTech[iTech]
                                            if iTotalBPWanted >= math.min(25, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tIslandLZData[AiBotMap.subrefLZIslandRef]] * 5) then
                                                break
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if iIslandLZ '..iIslandLZ..' wants BP='..tostring(tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP])..'; Island mex count='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tIslandLZData[AiBotMap.subrefLZIslandRef]]..'; LZ mex count='..tIslandLZData[AiBotMap.subrefLZOrWZMexCount]..'; iTotalBPWanted after considering this islandLZ='..iTotalBPWanted) end
                            end
                        end
                    end
                end
            end



            --Override - for core land zones dont want any BP from a non-adjacent zone in certain cases
            if bIslandPathing or (not(bNearbyZone) and tiBPWantedByTech and tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase]) then

                local iBPToAssign

                if bIslandPathing then
                    iBPToAssign = math.min(iTotalBPWanted, 25, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tAltLZ[AiBotMap.subrefLZIslandRef]] * 5)
                else
                    if AiBotUtilities.IsTableEmpty(tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEngineersTravelingHere]) then
                        iBPToAssign = math.max(5, iTotalBPWanted - 3 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]])
                    else
                        iBPToAssign = math.max(0, iTotalBPWanted - 3 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]])
                    end
                end
                if iBPToAssign < iTotalBPWanted then
                    local iBPToIgnore = iTotalBPWanted - iBPToAssign
                    local iCurBPToIgnore
                    local iRevisedBPWanted = 0
                    for iTech, iBuildPowerWanted in tiBPWantedByTech do
                        iCurBPToIgnore = math.min(iBuildPowerWanted, iBPToIgnore)
                        tiBPWantedByTech[iTech] = tiBPWantedByTech[iTech] - iCurBPToIgnore
                        iBPToIgnore = iBPToIgnore - iCurBPToIgnore
                        iRevisedBPWanted = iRevisedBPWanted + tiBPWantedByTech[iTech]
                    end
                    if iRevisedBPWanted == 0 then
                        tiBPWantedByTech = nil
                        if bDebugMessages == true then LOG(sFunctionRef..': Have reduced BP wanted by tech for iAdjZone='..iAdjLZ..'; iTotalBPWanted='..iTotalBPWanted..'; iRevisedBPWanted='..iRevisedBPWanted) end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iAdjLZ='..iAdjLZ..'; tiBPWantedByTech='..repru(tiBPWantedByTech)) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tiBPWantedByTech
end

function GetEngisWantedForTransports(tLZTeamData, bIncludeAttachedEngineers)
    local iTransports = table.getn(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits])
    local iEngisWanted = 0
    local iMinTechLevelWanted
    for iEntry = iTransports, 1, -1 do
        if not(AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry])) then
            table.remove(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits], iEntry)
        elseif (tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry][AiBotAir.refiEngisWanted] or 0) <= 0 then
            if (tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry][AiBotAir.refiCombatUnitsWanted] or 0) <= 0 then
                table.remove(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits], iEntry)
            end
        else
            iEngisWanted = iEngisWanted + tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry][AiBotAir.refiEngisWanted]
            if tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry][AiBotAir.refiTransMinEngiTechLevel] then iMinTechLevelWanted = math.max((iMinTechLevelWanted or 1), tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry][AiBotAir.refiTransMinEngiTechLevel]) end
            if bIncludeAttachedEngineers then
                local iEngisHave, iEngiRemainingCapacity = AiBotAir.GetTransportEngiCargoAndRemainingCapacity(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][iEntry], (iMinTechLevelWanted or 1))
                if iEngiRemainingCapacity > 0 and iEngisHave > 0 then iEngisWanted = iEngisWanted + iEngisHave end
            end
        end
    end
    return iEngisWanted
end

function GetZoneAndFactionForPriorityEngineerTravel(tBaseLZTeamData, iTeam, iBaseLandZone, iBasePlateau)
    local iZoneWantingEngineer, iFactionWanted
    for iFactory, oFactory in tBaseLZTeamData[AiBotMap.reftFactoriesWantedForEngineers] do
        if AiBotUtilities.IsTableEmpty(oFactory[AiBotBuilding.reftoUnitsWantingFactoryEngineers]) == false then
            --Do we already have at least 3 engineers of this factory's faction in the zone that the gameender is in?
            local iFactionRef = AiBotUnitInfo.GetUnitFaction(oFactory)
            for iUnit, oUnit in oFactory[AiBotBuilding.reftoUnitsWantingFactoryEngineers] do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    local iGameEnderPlateau, iGameEnderZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                    local tLZTeamData = AiBotMap.tAllPlateaus[iGameEnderPlateau][AiBotMap.subrefPlateauLandZones][iGameEnderZone][AiBotMap.subrefLZTeamData][iTeam]
                    if tLZTeamData[AiBotMap.subreftbBPByFactionWanted][iFactionRef] then
                        if  iBasePlateau == iGameEnderPlateau and not(iGameEnderZone == iBaseLandZone) then
                            --How many T3 engineers of this faction do we have traveling to this zone already?
                            local iEngiCatWanted = AiBotUnitInfo.refCategoryEngineer * categories.TECH3
                            if iFactionRef == AiBotUnitInfo.refFactionUEF then iEngiCatWanted = iEngiCatWanted * categories.UEF
                            elseif iFactionRef == AiBotUnitInfo.refFactionAeon then iEngiCatWanted = iEngiCatWanted * categories.AEON
                            elseif iFactionRef == AiBotUnitInfo.refFactionCybran then iEngiCatWanted = iEngiCatWanted * categories.CYBRAN
                            elseif iFactionRef == AiBotUnitInfo.refFactionSeraphim then iEngiCatWanted = iEngiCatWanted * categories.SERAPHIM
                            end
                            local iEngisAlreadyTraveling = 0
                            --Want at least 3 enginers traveling of the desired tech level
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                                for iEngi, oEngi in  tLZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                                    if AiBotUnitInfo.IsUnitValid(oEngi) and EntityCategoryContains(iEngiCatWanted, oEngi.UnitId) then
                                        iEngisAlreadyTraveling = iEngisAlreadyTraveling + 1
                                    end
                                end
                            end
                            if iEngisAlreadyTraveling < 3 then
                                iZoneWantingEngineer = iGameEnderZone
                                iFactionWanted = iFactionRef
                                break
                            end
                        end
                    end
                end
            end
        end
        if iZoneWantingEngineer then break end
    end
    return iZoneWantingEngineer, iFactionWanted
end

function GetPDThreatAboveRangeThresholdAlongPath(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, iRangeThreshold, tTarget)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPDThreatAboveRangeThresholdAlongPath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, for iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTeam='..iTeam..'; iRangeThreshold='..iRangeThreshold..'; tTarget='..repru(tTarget)..'; Dist from target to LZ mid='..AiBotUtilities.GetDistanceBetweenPositions(tTarget, tLZData[AiBotMap.subrefMidpoint])) end
    local iCurPDThreat = 0
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
            if iRange >= iRangeThreshold then
                iCurPDThreat = iCurPDThreat + iThreat
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPDThreat for just this zone='..iCurPDThreat) end
    local iTargetPlateauOrZero, iTargetLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tTarget)
    if bDebugMessages == true then LOG(sFunctionRef..': iTargetLandZone='..(iTargetLandZone or 'nil')..'; iTargetPlateauOrZero='..(iTargetPlateauOrZero or 'nil')) end
    if iTargetLandZone > 0 and iTargetPlateauOrZero == iPlateau and not(iTargetLandZone == iLandZone) then
        --ACU is in a different land zone
        if bDebugMessages == true then LOG(sFunctionRef..': Table of land zone path from start to target='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath])) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath]) == false then
            for iEntry, iAdjLZ in  tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]][AiBotMap.subrefLZPath] do
                if not(iAdjLZ == iLandZone) then
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                        for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                            if iRange >= iRangeThreshold then
                                iCurPDThreat = iCurPDThreat + iThreat
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPDThreat after factoring in adjacent zones='..iCurPDThreat) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCurPDThreat
end

function GetClosestMobileTMLIfWantMoreTMD(iTeam, tLZTeamData)
    --Assumes we have already confirmed there are enemy mobile tml on the enemy team
    --Dont bother trying to get TMD if enemy has units in this zone
    --NOTE: After drafting this decided to use a different approach to tracking mobile TML
    AiBotUtilities.ErrorHandler('Obsolete never tested code')
    local oMobileTMLToDefendAgainst
    if (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) == 0 and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then

        local iZoneTMDCount = 0
        local tZoneTMD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTMD, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tZoneTMD) == false then
            for iUnit, oUnit in tZoneTMD do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then iZoneTMDCount = iZoneTMDCount + 1 end
            end
        end
        if iZoneTMDCount < 4 or (iZoneTMDCount < 16 and tLZTeamData[AiBotMap.subrefLZSValue] > iZoneTMDCount * 800) then
            --Get the closest enemy TML to midpoint
            local iCurDist
            local iClosestDist = 100000
            local oClosestUnit
            local tMidpoint = tLZTeamData[AiBotMap.subrefMidpoint]
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileTML] do
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tMidpoint, oUnit:GetPosition()) - math.max((oUnit[AiBotUnitInfo.refiManualRange] or 0), (oUnit[AiBotUnitInfo.refiIndirectRange] or 0))
                if iCurDist < iClosestDist then
                    iClosestDist = iCurDist
                    oClosestUnit = oUnit
                end
            end
            if iClosestDist <= 50 then
                oMobileTMLToDefendAgainst = oClosestUnit
            end

        end
    end
    return oMobileTMLToDefendAgainst
end

function GetCaptureBPWanted(oUnitToCapture, bHaveLowPower, iTeam, bIsCoreBase)
    local iTargetBuildTime = (oUnitToCapture:GetBlueprint().Economy.BuildTime or 1)
    local iBPWanted = math.min(5 + 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iTargetBuildTime * 0.25)

    local iTimeToCapture = iTargetBuildTime / iBPWanted
    if iTimeToCapture >= 10 and not(bHaveLowPower) then
        iBPWanted = math.min(40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iTargetBuildTime / 10)
    end
    iBPWanted = math.max(5, iBPWanted)
    return iBPWanted
end

function AssignBuildExperimentalOrT3NavyAction(fnHaveActionToAssign, iPlateau, iLandOrWaterZone, iTeam, tLZOrWZData, tLZOrWZTeamData, bIsWaterZone, iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignBuildExperimentalOrT3NavyAction'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    

    --Check if a teammate has units nearby that we might want to assist instead
    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code, iPlateau='..(iPlateau or 'nil')..'; iLandOrWaterZone='..iLandOrWaterZone..'; iTeam='..iTeam..'; iActionToAssign='..(iActionToAssign or 'nil')..'; iMinTechLevelWanted='..(iMinTechLevelWanted or 'nil')..'; iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..'; Is table of T3 navy and exp empty for our team (i.e. for nonAiBot units)='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy]))..'; Is table of enemy air exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]))..'; Team airaa threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]..'; Enemy air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Have low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Do we have exp under construction in this zone='..tostring(GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandOrWaterZone, false, 0, nil, false) or false)..'; Do we have air control='..tostring(AiBotConditions.TeamHasAirControl(iTeam))..'; Time since last E stall='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0) ..'; E when stalled='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled]..'; Cur gross E='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy])
        local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandOrWaterZone, true, 500, AiBotUnitInfo.refCategoryExperimentalLevel, nil, nil, nil)
        LOG(sFunctionRef..': bHaveExperimentalForThisLandZone='..tostring(bHaveExperimentalForThisLandZone)..'; iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; iMassToComplete='..iMassToComplete..'; Team mass stored actual='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Team mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored])
    end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy]) == false then
        --Update the table
        local tUnits = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoNonAiBotConstructingExpAndT3Navy]
        local iCurDist, iCurPlateau
        local iClosestDist = 250 --Dont want to assist construction further away than this
        local oNonAiBotUnitToAssistInstead
        local iCategoryToSearch
        if iActionToAssign == refActionAssistNavalFactory then
            iCategoryToSearch = categories.NAVAL + AiBotUnitInfo.refCategoryExperimentalLevel * categories.MOBILE - categories.TECH1 - categories.TECH2
            if AiBotMap.iMapSize >= 1000 then iClosestDist = 225
            else iClosestDist = 175 --Tried with 125 but was a bit too short
            end

        elseif iActionToAssign == refActionBuildGameEnder then
            iCategoryToSearch = AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti
        else
            iCategoryToSearch = AiBotUnitInfo.refCategoryExperimentalLevel
        end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refbBuiltParagon]) then
            iClosestDist = 60
        end

        for iCurEntry = table.getn(tUnits), 1, -1 do
            local oUnit = tUnits[iCurEntry]
            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() <= 0.9 and (oUnit:GetFractionComplete() <= 0.75 or EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId)) then --No point assisting a near-complete unit as it will likely be done by the time we get there
                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Has desired category='..tostring(EntityCategoryContains(iCategoryToSearch, oUnit.UnitId))..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])..'; Expected plateau='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 'nil')..'; iPlateau='..(iPlateau or 'nil')) end
                if EntityCategoryContains(iCategoryToSearch, oUnit.UnitId) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])
                    if iCurDist < iClosestDist then
                        iCurPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
                        if iCurPlateau == iPlateau then
                            if not(ScenarioInfo.Options.AiBotTeammate == 1) and not(oUnit:GetAIBrain().AiBotAI) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Aborting logic to help engineers as we have disabled teammate experimental assistance for players') end
                                break
                            end
                            iClosestDist = iCurDist
                            oNonAiBotUnitToAssistInstead = oUnit
                        elseif bDebugMessages == true then LOG(sFunctionRef..': iCurPlateau='..(iCurPlateau or 'nil')..'; dif to plateau for engis so wont proceed')
                        end
                    end
                end
            else
                table.remove(tUnits, iCurEntry)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oNonAiBotUnitToAssistInstead='..(oNonAiBotUnitToAssistInstead.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNonAiBotUnitToAssistInstead) or 'nil')..'; iClosestDist='..iClosestDist) end
        if oNonAiBotUnitToAssistInstead then
            --How much BP have we already assigned (from all zones) to repair/assist this unit?
            local iTotalBPAssigned = 0
            if AiBotConditions.IsTableOfUnitsStillValid(oNonAiBotUnitToAssistInstead[AiBotOrders.toUnitsOrderedToRepairThis]) then
                for iEngi, oEngi in oNonAiBotUnitToAssistInstead[AiBotOrders.toUnitsOrderedToRepairThis] do
                    iTotalBPAssigned = iTotalBPAssigned + (oEngi:GetBlueprint().Economy.BuildRate or 0)
                end
            end
            local iBPForNonAiBotUnit = (iBuildPowerWanted or 5)
            if not(bBPIsInAdditionToExisting) then
                iBPForNonAiBotUnit = math.max(0, iBPForNonAiBotUnit - iTotalBPAssigned * 0.75) --0.75 since some engineers may be from other zones
            end

            if iBPForNonAiBotUnit > 0 then
                --Need to set as in addition to current, or else we risk e.g. assigning 90 BP initially, then a later builder wants to assign 100, and will try assigning 100 - 90*0.75 from here, but then the main logic would reduce that by any BP for engineers coming from this zone so double-counting
                fnHaveActionToAssign(refActionRepairAllyUnit,  1, (iBuildPowerWanted or 5), oNonAiBotUnitToAssistInstead, bDontIncreaseLZBPWanted, true, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
            end
            --Also have BP for normal experimental if have quite high mass
            if iBPForNonAiBotUnit < (iBuildPowerWanted or 5) * 0.25 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.5 then
                iBuildPowerWanted = 0
            end
        elseif tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 1 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) then
            if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(3, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.75 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 25000 then
                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to get an experimental just yet, instead want to get more eco') end
                iBuildPowerWanted = 0
            end
        end
    end
    --Abort if we have multiple experimentals under construction or 1 very expensive experimental
    if (iBuildPowerWanted or 5) > 0 then
        local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandOrWaterZone, true, 500, AiBotUnitInfo.refCategoryExperimentalLevel, nil, nil, nil)
        if bDebugMessages == true then LOG(sFunctionRef..': Deciding if should overwrite decision to build another experimental, bHaveExperimentalForThisLandZone='..tostring(bHaveExperimentalForThisLandZone)..'; iOtherLandZonesWithExperimental='..iOtherLandZonesWithExperimental..'; iMassToComplete='..iMassToComplete..'; subrefiTeamAverageMassPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; subrefiTeamMassStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Time since last E stall='..(GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0))..'; Base condition='..tostring(not(bHaveExperimentalForThisLandZone) and iOtherLandZonesWithExperimental > 0 and iMassToComplete >= 20000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 0 or iMassToComplete >= 40000))..'; mass based condition Pt1='..tostring((iOtherLandZonesWithExperimental > 0.1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] * 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 2 * iMassToComplete))..'; Pt2='..tostring((iOtherLandZonesWithExperimental > 1 or (iMassToComplete >= 100000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] <= 20)))) end
        if not(bHaveExperimentalForThisLandZone) and iOtherLandZonesWithExperimental > 0 and iMassToComplete >= 20000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] < 0 or iMassToComplete >= 40000) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 900 and
                ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] and GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] <= 20) or
                        (iOtherLandZonesWithExperimental > 0.1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] * 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 2 * iMassToComplete and (iOtherLandZonesWithExperimental > 1 or (iMassToComplete >= 100000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] <= 20)))) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will delay getting experimental due to having significant mass to complete other experimentals, iActionToAssign='..iActionToAssign..'; iLandOrWaterZone='..iLandOrWaterZone) end
            iBuildPowerWanted = 0
        end
    end

    if (iBuildPowerWanted or 5) > 0 then
        --if we have upgrading t2 factory in zone and havnet built any exps yet then assist this instead
        local bAssistingUpgradingFactory = false
        local oActiveT2UpgradeToAssist
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
            local iHighestCompletion = -1
            for iUpgrade, oUpgrade in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering active upgrade, oUpgrade='..oUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrade)..'; Fraction complete='..oUpgrade:GetFractionComplete()..'; Unit last subrefsOrderBlueprint='..(oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; oUpgrade.Dead='..tostring(oUpgrade.Dead or false)..'; Is this a factory='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUpgrade.UnitId) or false)) end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory * categories.TECH2, oUpgrade.UnitId) and not(oUpgrade.Dead) then
                    if oUpgrade:GetWorkProgress() > iHighestCompletion and (iHighestCompletion <= 0 or (oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]) and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint].UnitId)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will assist t2 factory, oUpgrade='..oUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrade)) end
                        oActiveT2UpgradeToAssist = oUpgrade
                        iHighestCompletion = oUpgrade:GetFractionComplete()
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oActiveT2UpgradeToAssist='..(oActiveT2UpgradeToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oActiveT2UpgradeToAssist) or 'nil')..'; Is subreftoActiveUpgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))) end
        if oActiveT2UpgradeToAssist then
            HaveActionToAssign(refActionAssistUpgrade, 1, iBuildPowerWanted, oActiveT2UpgradeToAssist)
            bAssistingUpgradingFactory = true
        end
        if not(bAssistingUpgradingFactory) then
            --Build more land facs if not constructed any experimentals and are dealing with land zone, or if are Aeon or Seraphim, haven't built many sniperbots (or lots of t3 land), and enemy lacks fatboy or megalith
            local aiBrain = ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]

            if not(aiBrain) then
                if not(bIsWaterZone) then AiBotUtilities.ErrorHandler('Dont have a closest brain index for land zone in P'..iPlateau..'Z'..iLandOrWaterZone..'; will use brain of first unit') end
                if AiBotUnitInfo.IsUnitValid(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits][1]) then
                    aiBrain = tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits][1]:GetAIBrain()
                end
                if not(aiBrain) then
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
                        aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                    else
                        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                aiBrain = oUnit:GetAIBrain()
                                break
                            end
                        end
                        if not(aiBrain) then aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam) end
                    end
                end
            end
            local bAreSeraOrAeon = false
            local bPrioritiseSniperBots = false

            if aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon or aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then bAreSeraOrAeon = true end
            if bAreSeraOrAeon then bPrioritiseSniperBots = AiBotConditions.PrioritiseSniperBots(tLZOrWZData, iTeam, tLZOrWZTeamData, iPlateau, iLandOrWaterZone) end
            if bDebugMessages == true then LOG(sFunctionRef..': Exp constructed count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Island ref='..(tLZOrWZData[AiBotMap.subrefLZIslandRef] or 0)..'; Is table of enemy land exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))..'; time last near unit cap='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 'nil')..'; T3 mex in zone='..(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] or 'nil')..'; Mex count in zone='..(tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')..'; Number of land and indirect T3 built in game='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3)..'; Air to ground threat='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] or 0)..'; Want more factories='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandOrWaterZone, true))..'; Enemy base island ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) or 'nil')..'; Our island ref='..(tLZOrWZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Cur naval facs='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryNavalFactory, iTeam)..'; Cur land and air facs='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, iTeam)..'; bAreSeraOrAeon='..tostring(bAreSeraOrAeon or false)..'; bPrioritiseSniperBots='..tostring(bPrioritiseSniperBots)..'; Do we want more factories='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandOrWaterZone, true))..'; Do we want air fac='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData))..'; Number of T3 air facs in zone='..AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory)..'; Time='..GetGameTimeSeconds()) end

            --Assist experimental factory (SCTA)
            if aiBrain.AiBotSCTA and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.3 or AiBotConditions.HaveLowPower(iTeam)) then
                local tExperimentalFactories = EntityCategoryFilterDown(categories.EXPERIMENTAL * categories.FACTORY * categories.STRUCTURE, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tExperimentalFactories) == false then
                    local oFactoryToAssist
                    local iBestWorkProgress = -1
                    local iCurWorkProgress
                    for iFactory, oFactory in tExperimentalFactories do
                        iCurWorkProgress = oFactory:GetWorkProgress()
                        if iCurWorkProgress > iBestWorkProgress then
                            oFactoryToAssist = oFactory
                            iBestWorkProgress = iCurWorkProgress
                        end
                    end
                    if oFactoryToAssist then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will just assist existing experimental factory') end
                        fnHaveActionToAssign(refActionAssistLandFactory, 1, iBuildPowerWanted, oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return
                    end
                end
                --(oUnit[AiBotFactory.refsLastBlueprintBuilt] and EntityCategoryContains(categories.FACTORY * categories.STRUCTURE, oUnit.UnitId) and EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit[AiBotFactory.refsLastBlueprintBuilt]))) then
            end

            --Tech and turtle (or at -2 unit cap) - always get experimental instead of more factories
            if aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= -1 then
                if bDebugMessages == true then LOG(sFunctionRef..': Want high tech, refbPrioritiseHighTech='..tostring(aiBrain[AiBotOverseer.refbPrioritiseHighTech] or false)..'; refbPrioritiseDefence='..tostring(aiBrain[AiBotOverseer.refbPrioritiseDefence] or false)..'; refiLowestUnitCapAdjustmentLevel='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; so will proceed with assigning iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..' to building an experimental or power type action, iMinTechLevelWanted='..(iMinTechLevelWanted or 'nil')) end
                if not(bIsWaterZone) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                    --do nothing
                    if bDebugMessages == true then LOG(sFunctionRef..': Tech is stalling power so wont build T3 navy or experimental and instead will build more power') end
                    fnHaveActionToAssign(refActionBuildSecondPower,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                else
                    if bIsWaterZone then
                        fnHaveActionToAssign((iActionToAssign or refActionBuildExperimentalNavy),  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    else
                        fnHaveActionToAssign((iActionToAssign or refActionBuildExperimental),  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    end
                end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return
            end

            function GetFactoryToAssist(iCategoryToSearch)
                local oFactoryToAssist
                local tFactoriesInZone = EntityCategoryFilterDown(iCategoryToSearch, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local iHighestTechLevel = 0
                local iCurTechLevel, iCurDistToFriendlyBase, iClosestDistToFriendlyBase
                if AiBotUtilities.IsTableEmpty(tFactoriesInZone) == false then
                    for iHQ, oHQ in tFactoriesInZone do
                        if not(oHQ[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oHQ[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                            iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oHQ)
                            if iCurTechLevel > iHighestTechLevel then
                                oFactoryToAssist = oHQ
                                iHighestTechLevel = iCurTechLevel
                                iClosestDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oHQ:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                            elseif iCurTechLevel == iHighestTechLevel then
                                iCurDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oHQ:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                if iCurDistToFriendlyBase < iClosestDistToFriendlyBase then
                                    iClosestDistToFriendlyBase = iCurDistToFriendlyBase
                                    oFactoryToAssist = oHQ
                                end
                            end
                        end
                    end
                end
                return oFactoryToAssist
            end

            local iLifetimeCountVar --If havent built enough t3 land combat then will get more
            local iLifetimeCountCategory = (AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber) * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3
            if aiBrain[AiBotOverseer.refbPrioritiseLowTech] then
                if AiBotUtilities.bLoudModActive then
                    iLifetimeCountVar = 40
                elseif AiBotUtilities.bQuietModActive then
                    iLifetimeCountVar = 35
                else
                    iLifetimeCountVar = 30
                end
            elseif AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                if AiBotUtilities.bLoudModActive then iLifetimeCountVar = 16 else iLifetimeCountVar = 8 end
            end
            if bIsWaterZone then
                if aiBrain[AiBotOverseer.refbPrioritiseNavy] then
                    iLifetimeCountVar = 5
                else
                    iLifetimeCountVar = 10
                end
                iLifetimeCountCategory = AiBotUnitInfo.refCategoryAllNavy * (categories.TECH3 + categories.EXPERIMENTAL)
            else
                if aiBrain[AiBotOverseer.refbPrioritiseAir] then
                    iLifetimeCountCategory = AiBotUnitInfo.refCategoryAirNonScout * categories.TECH3
                    if AiBotConditions.TeamHasLowMass(iTeam) then
                        iLifetimeCountVar = math.max((iLifetimeCountVar or 30), 50)
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4 or AiBotConditions.HaveLowPower(iTeam) then
                        iLifetimeCountVar = math.max((iLifetimeCountVar or 15), 40)
                    else
                        iLifetimeCountVar = math.max((iLifetimeCountVar or 15), 30)
                    end
                elseif aiBrain[AiBotOverseer.refbPrioritiseLand] then
                    iLifetimeCountCategory = AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3
                elseif aiBrain[AiBotOverseer.refbPrioritiseNavy] and aiBrain:GetEconomyStoredRatio('MASS') <= 0.5 then
                    iLifetimeCountVar = math.max((iLifetimeCountVar or 50), 50)
                    iLifetimeCountCategory = iLifetimeCountCategory + AiBotUnitInfo.refCategoryAllNavy * (categories.TECH3 + categories.EXPERIMENTAL)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Island air/naval check, refbCanPathToEnemyBaseWithLand='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])..'; refiOurHighestAirFactoryTech='..aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; refiOurHighestNavalFactoryTech='..aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]..'; mass % stored='..aiBrain:GetEconomyStoredRatio('MASS')..'; is subreftoActiveUpgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))) end
                if not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and (((aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 or aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] >= 3) and (aiBrain:GetEconomyStoredRatio('MASS') <= 0.7 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])))) or (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirHQ + AiBotUnitInfo.refCategoryNavalHQ, tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades])) == false)) then
                    iLifetimeCountVar = math.max((iLifetimeCountVar or 40), 40)
                    iLifetimeCountCategory = iLifetimeCountCategory + AiBotUnitInfo.refCategoryAllNavy * (categories.TECH3 + categories.EXPERIMENTAL)
                end
            end

            local bInAirSlotOrAirPlayerWithoutAirControl = false --True if we want to get t3 air in most cases for asfs
            if (tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] or aiBrain[AiBotOverseer.refbPrioritiseAir]) and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 and not(aiBrain[AiBotOverseer.refbPrioritiseLand]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurAirAAThreat] <= 40000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 2 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or 0) >= 10 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) <= 6 then
                bInAirSlotOrAirPlayerWithoutAirControl = true
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Experimental construction override check, iLifetimeCountVar='..(iLifetimeCountVar or 'nil')..'; Exp constructed count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Lifetime iLifetimeCountCategory count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, iLifetimeCountCategory)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; bPrioritiseSniperBots='..tostring(bPrioritiseSniperBots or false)..'; Team has low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))..'; Primary aiBrain='..aiBrain.Nickname..'; aiBrain[AiBotOverseer.refbPrioritiseAir]='..tostring(aiBrain[AiBotOverseer.refbPrioritiseAir] or false)..'; bInAirSlotOrAirPlayerWithoutAirControl='..tostring(bInAirSlotOrAirPlayerWithoutAirControl)) end

            if not(bIsWaterZone) then
                if ((iLifetimeCountVar and aiBrain[AiBotOverseer.refbPrioritiseLowTech]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + 1) and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] > 1)) and
                        (((bPrioritiseSniperBots and AiBotConditions.TeamHasLowMass(iTeam)) or (bAreSeraOrAeon or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 1) and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryExperimentalLevel) <= 1 and GetGameTimeSeconds() <= 1800 and (tLZOrWZData[AiBotMap.subrefLZIslandRef] or 0) > 0 and (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) or (bAreSeraOrAeon and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMegalith + AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])))) and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap]) and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(4, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) or GetGameTimeSeconds() <= 1080 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or bAreSeraOrAeon) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] or 0) <= 15000 + 7500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ((bAreSeraOrAeon and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3) <= 10 + 8 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (not (bAreSeraOrAeon) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryIndirectT3) <= 6 + 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandOrWaterZone, true) and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZOrWZData[AiBotMap.subrefLZIslandRef] and ((bAreSeraOrAeon and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, iTeam) <= 6 + 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (not (bAreSeraOrAeon) and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, iTeam) <= 6 + 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryNavalFactory * categories.TECH3, iTeam) <= math.max(0, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] - 2))
                                or (iLifetimeCountVar and ((aiBrain[AiBotOverseer.refbPrioritiseLowTech] and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, iLifetimeCountCategory) < iLifetimeCountVar + iLifetimeCountVar * (math.min(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]))
                                or (not(aiBrain[AiBotOverseer.refbPrioritiseLowTech]) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, iLifetimeCountCategory) < iLifetimeCountVar + iLifetimeCountVar * (math.min(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) + math.min(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount])) and (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) or table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) <= 2))))) then

                    --Increase build power a bit in case we already ahve engineers assigned to build a factory
                    if iBuildPowerWanted <= 150 then
                        iBuildPowerWanted = math.min(math.min((iBuildPowerWanted or 5), 30) + (iBuildPowerWanted or 5), 150)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': We havent built any exp and want to get more T3 first, do we want air fac instead of land='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData))..'; Cur land factory count='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory, iTeam)..'; Dist to nearest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])..'; refiTimeLastHadNothingToBuildForAirFactory='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] or 0)..'; refiEnemyAirToGroundThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) end

                    if bInAirSlotOrAirPlayerWithoutAirControl or (not(aiBrain[AiBotOverseer.refbPrioritiseLand]) and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory]) or GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] >= 10) and (AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData) or aiBrain[AiBotOverseer.refbPrioritiseAir])) then -- and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandFactory, iTeam) >= 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) >= 400 then
                        --If have low mass then just assist an air fac
                        local oFactoryToAssist = GetFactoryToAssist(AiBotUnitInfo.refCategoryAirHQ)
                        if oFactoryToAssist and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 500 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.02) and AiBotConditions.TeamHasLowMass(iTeam))) then
                            fnHaveActionToAssign(refActionAssistAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will just assist air fac due to low mass') end
                        else
                            --If not low mass but low power then build power
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (not(AiBotConditions.TeamHasLowMass(iTeam)) and AiBotConditions.HaveLowPower(iTeam)) then
                                fnHaveActionToAssign(refActionBuildPower,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                if bDebugMessages == true then LOG(sFunctionRef..': We want more air facs instead of exp, but have low power so will get more power first') end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to extend t3 stage so will build t3 air fac instead of experimental, iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..'; Time='..GetGameTimeSeconds()) end
                                fnHaveActionToAssign(refActionBuildAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.03 then
                                    if oFactoryToAssist and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.1 then
                                        fnHaveActionToAssign(refActionAssistAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    else
                                        fnHaveActionToAssign(refActionBuildSecondAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    end
                                end
                            end
                        end
                    elseif aiBrain[AiBotOverseer.refbPrioritiseNavy] and AiBotConditions.TeamHasLowMass(iTeam) and not(bIsWaterZone) then
                        if bDebugMessages == true then LOG(sFunctionRef..': No action as low mass and want to prioritise navy') end
                    elseif (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForLandFactory] or -100)) >= 10 then
                        --Do we have a land factory HQ?
                        local oFactoryToAssist = GetFactoryToAssist(AiBotUnitInfo.refCategoryLandHQ)

                        if oFactoryToAssist and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 500 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.03) and AiBotConditions.TeamHasLowMass(iTeam))) then
                            fnHaveActionToAssign(refActionAssistLandFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will just assist land fac due to low mass') end
                        else
                            --Do we only want a land fac because we have low power? Then consider gteting more power instead
                            if aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build more power so can get air facs if we think air is better than land') end
                                fnHaveActionToAssign(refActionBuildPower,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                            else
                                fnHaveActionToAssign(refActionBuildLandFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.03 then
                                    if oFactoryToAssist and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.1 then
                                        fnHaveActionToAssign(refActionAssistLandFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    elseif (GetGameTimeSeconds() >= 300 or GetGameTimeSeconds() >= 300 / aiBrain[AiBotEconomy.refiBrainResourceMultiplier]) and (aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 3 or (not(aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and not(aiBrain[AiBotOverseer.refbPrioritiseDefence]))) then
                                        fnHaveActionToAssign(refActionBuildSecondLandFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5) * 0.5, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to extend t3 stage so will build t3 land fac instead of experimental, iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..'; Time='..GetGameTimeSeconds()) end
                            end
                        end
                    end
                    --Assist air fac if we lack air control, have <100 asf equivalent, enemy has an experimental air unit or retorer deathball, and we dont have lots of mass; if we are building an experimental in this zone and arent stalling mass then wont trigger
                elseif bInAirSlotOrAirPlayerWithoutAirControl or
                        ((not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory]) or GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForAirFactory] >= 10) and
                                ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] > 1)) and not(aiBrain[AiBotOverseer.refbPrioritiseLand]) and (not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) or aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0) and (((AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) == false or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 25000) and not(AiBotConditions.TeamHasAirControl(iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] < math.min(40000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) and (AiBotConditions.TeamHasLowMass(iTeam) or (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 0) <= 30 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4))
                                --Additional condition - Either are stalling mass/no mass stored, or we aren't building an experimental in this zone
                                and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.01 or not(GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandOrWaterZone, false, 0, nil, false, nil, aiBrain.AiBotAirSubteam))))
                                --Alt - assist air fac if its the first 20m of Cybran M6 and czar not yet built
                                or (AiBotMap.bIsCampaignMap and ScenarioInfo.ControlCenter and (ScenarioInfo.CzarEngineer or ScenarioInfo.Czar or (GetGameTimeSeconds() <= 250 and ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].GetFactionIndex and ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetFactionIndex() == AiBotUnitInfo.refFactionCybran)) and not(ScenarioInfo.CzarFullyBuilt) and GetGameTimeSeconds() <= 1200 and (ScenarioInfo.M1P1.Active or GetGameTimeSeconds() <= 250))
                                --Further alt - 20km+, first 40m, we dont have a large airaa threat and want more air facs, and we have access to T3 air, and havent built many experimentals
                                or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 2 and not(ArmyBrains[tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotOverseer.refbCloseToUnitCap]) and GetGameTimeSeconds() <= 2400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and AiBotMap.iMapSize >= 1000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] < 20000 and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandOrWaterZone, true) and AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData) and AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory) <= 5 and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryAirFactory, iTeam) <= 4 + 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))))

                then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to prioritise building asfs as we lack air control, have low mass, and enemy has experimental air or we are air player') end
                    local oFactoryToAssist = GetFactoryToAssist(AiBotUnitInfo.refCategoryAirHQ)

                    if oFactoryToAssist then
                        fnHaveActionToAssign(refActionAssistAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    else
                        fnHaveActionToAssign(refActionBuildAirFactory,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    end
                elseif (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0) <= 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled] * 1.25)) then
                    --do nothing
                    if bDebugMessages == true then LOG(sFunctionRef..': Are stalling power so wont build T3 navy or experimental and instead will build more power') end
                    fnHaveActionToAssign(refActionBuildSecondPower,  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    --Assist underconstruction experimentals if in water zone
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Will proceed with assigning for land zone iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..' to building an experimental type action, iMinTechLevelWanted='..(iMinTechLevelWanted or 'nil')) end
                    fnHaveActionToAssign((iActionToAssign or refActionBuildExperimental),  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                end
            elseif bIsWaterZone then
                local bHaveUnderConstructionExperimental = false
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied units for this WZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tFriendlyExp = EntityCategoryFilterDown(categories.EXPERIMENTAL, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if bDebugMessages == true then LOG(sFunctionRef..': is tFriendlyExp empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyExp))) end
                    if AiBotUtilities.IsTableEmpty(tFriendlyExp) == false then
                        for iExp, oExp in tFriendlyExp do
                            if bDebugMessages == true then LOG(sFunctionRef..': Exp fraction complete='..oExp:GetFractionComplete()..'; oExp='..oExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExp)) end
                            if oExp:GetFractionComplete() < 1 then
                                bHaveUnderConstructionExperimental = true
                                break
                            end
                        end
                    end
                end
                if bHaveUnderConstructionExperimental then
                    fnHaveActionToAssign(refActionBuildExperimentalNavy, (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), nil, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have an under construction experimental in water zone so will assist it') end
                else
                    if not(iActionToAssign == refActionAssistNavalFactory) and iLifetimeCountVar and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, iLifetimeCountCategory) < iLifetimeCountVar then
                        local oFactoryToAssist
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then oFactoryToAssist = GetFactoryToAssist(AiBotUnitInfo.refCategoryNavalFactory) end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will either assist existing naval fac, or build a new one, oFactoryToAssist='..(oFactoryToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryToAssist) or 'nil')) end
                        if tLZOrWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] and GetGameTimeSeconds() - tLZOrWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] <= 60 and (not(oFactoryToAssist) or not(oFactoryToAssist:GetWorkProgress()>0) or (GetGameTimeSeconds() - tLZOrWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] <= 20 and not(AiBotUnitInfo.IsUnitRestricted('ues0103', tLZOrWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex])))) then
                            fnHaveActionToAssign((iActionToAssign or refActionBuildExperimentalNavy),  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                        elseif oFactoryToAssist then
                            fnHaveActionToAssign(refActionAssistNavalFactory, (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), oFactoryToAssist, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will build a naval fac') end
                            fnHaveActionToAssign(refActionBuildNavalFactory, (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Will proceed with assigning for water zone iBuildPowerWanted='..(iBuildPowerWanted or 'nil')..' to building an experimental type action, iMinTechLevelWanted='..(iMinTechLevelWanted or 'nil')) end
                        fnHaveActionToAssign((iActionToAssign or refActionBuildExperimentalNavy),  (iMinTechLevelWanted or 3), (iBuildPowerWanted or 5), vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderCoreBaseLandZoneEngineerAssignment(tLZTeamData, iTeam, iPlateau, iLandZone, tEngineers)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderCoreBaseLandZoneEngineerAssignment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --For land zones in the core base
    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]

    local toAvailableEngineersByTech, toAssignedEngineers = FilterToAvailableEngineersByTech(tEngineers, true, tLZData, tLZTeamData, iTeam, iPlateau, iLandZone)
    local bDontCheckPlayableArea = false
    if AiBotMap.bIsCampaignMap then
        bDontCheckPlayableArea = true
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] then bDontCheckPlayableArea = false end
    end

    tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] = {[1]=0,[2]=0,[3]=0}
    if bDebugMessages == true then LOG(sFunctionRef..': Have just reset BPByTech to 0 for Plateau'..iPlateau..'; LZ='..iLandZone..'; repru='..repru(tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])) end
    --local iCurCondition = 0
    local iCurPriority = 0
    local iHighestTechEngiAvailable
    local bHaveLowMass = AiBotConditions.TeamHasLowMass(iTeam)
    local bHaveLowPower = AiBotConditions.HaveLowPower(iTeam)
    local bWantMorePower = AiBotConditions.WantMorePower(iTeam)
    local bWantMoreFactories = AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone)
    local iBPWanted
    local iActiveMexUpgrades = AiBotConditions.GetActiveMexUpgrades(tLZTeamData)
    local iNearbyEnemyAirToGroundThreat = tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
    local iHighestTechInZone = AiBotConditions.GetHighestTechInZone(iTeam, tLZTeamData) --Highest completed factory HQ or engineer in the zone (or 1 if none)
    local iFactoriesInLZ = 0
    local tFactoriesInLZ
    local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
    local bSaveMassForMML, bWantT3LandForRavagers = AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tLZData, tLZTeamData, iPlateau, iTeam, bHaveLowMass)
    local bPrioritiseProduction = AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction]
    local bDualGapAirHomeOnly = aiBrain.AiBotDualGapRole == 'top_air'
            or aiBrain.AiBotDualGapRole == 'bottom_air'
            or aiBrain.AiBotDualGapRole == 'eco'

    if not(AiBotUnitInfo.bDontConsiderCombinedArmy) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbContainsPureAiBotAndSharedAiBot] and tLZTeamData[AiBotMap.subrefLZSValue] > 30 then
        local tMexesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tMexesInZone) == false then
            local iHumanMexCount = 0
            for iMex, oMex in tMexesInZone do
                if not(oMex.AiBotActive) then iHumanMexCount = iHumanMexCount + 1 end
            end
            if iHumanMexCount >= tLZData[AiBotMap.subrefLZOrWZMexCount] -1 and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or iHumanMexCount == tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                tLZTeamData[AiBotMap.subrefLZbSharedHumanBase] = true
                if bDebugMessages == true then LOG(sFunctionRef..': Considering shared army whether teammate has built here, iHumanMexCount='..iHumanMexCount..'; will flag that this zone should be treated as a human zone') end
            else
                tLZTeamData[AiBotMap.subrefLZbSharedHumanBase] = true
            end
        end
    end

    --For now only do land zone not water zone given water zone includes torp bombers
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            iNearbyEnemyAirToGroundThreat = iNearbyEnemyAirToGroundThreat + tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
        end
    end

    function HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
        --Done as subfunction for convenience so can just note the key values for the action in question and add on the others that wont change
        --vOptionalVariable can be used for action specific information to save having to recalculate the same thing - could be a table, nil, or a value
        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (bHaveLowMass or bHaveLowPower) then iBuildPowerWanted = iBuildPowerWanted * 0.8 end
        ConsiderActionToAssign(iActionToAssign, math.max(1, iMinTechLevelWanted), iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iCurPriority, tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, toAvailableEngineersByTech, toAssignedEngineers, false, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    end
    if bDualGapAirHomeOnly and GetGameTimeSeconds() >= (aiBrain.AiBotDualGapT2PowerRushTime or 330)
            and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH2) == 0 then
        HaveActionToAssign(refActionBuildPower, 2, 10)
    end
    if bDebugMessages == true then
        LOG(sFunctionRef..': About to consider what actions we want to give engineers for iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; iTeam='..(iTeam or 'nil')..'; bHaveLowMass='..tostring(bHaveLowMass or false)..'; Team gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; Lowest mass % stored='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 'nil')..'; Team mass stored='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] or 'nil')..'; Team net mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] or 'nil')..'; Team gross mass='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil'))
        LOG(sFunctionRef..': Repeat of log but without the nil backups to help identify errors, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTeam='..iTeam..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Lowest mass % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Team mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Team net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass])
    end
    local iMinTechLevelForPower = 1

    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then
        local iPowerMod = 1 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] - 1) * 0.8 --can start on better pgen slightly sooner in teamgame
        --If we have high build rate and resource rate, then want to get more T1 pgens; otherwise factor shoudl be lower
        if aiBrain[AiBotEconomy.refiBrainResourceMultiplier] > 1 then
            if (aiBrain[AiBotEconomy.refiBrainResourceMultiplier] - 1) * 0.6 <= (aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] - 1) then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 then
                    iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.9)
                else iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.7)
                end
            else
                --We dont have a build rate boost, so should only ahve a very slight increase in the t1 pgens to build before getting T2/T3
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and (aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] > 1 or aiBrain:GetEconomyStoredRatio('ENERGY') < 0.7) then
                    iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.4)
                else
                    iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.2)
                end
            end
        end
        --[[refiBrainBuildRateMultiplier
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 then
            iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.9)
        else iPowerMod = iPowerMod + (((aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1) - 1) * 0.7)
        end--]]
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then iPowerMod = iPowerMod + 1 end

        if bDebugMessages == true then LOG(sFunctionRef..': iPowerMod='..iPowerMod..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]='..(tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex] or 'nil')..'; Brain='..(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].Nickname or 'nil')..'; Resource mod='..(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiBrainResourceMultiplier] or 'nil')..'; iHighestTechInZone='..iHighestTechInZone..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; bHaveLowMass='..tostring(bHaveLowMass)) end
        --NOTE: iPowerMod already factores in player count
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 23 * iPowerMod then --iPowermod already factors in player count
            if bDebugMessages == true then LOG(sFunctionRef..': We have so little base energy that want a few more T1 pgens before trying to get a higher tech') end
            iMinTechLevelForPower = 1
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 110 * iPowerMod then
            iMinTechLevelForPower = math.min(2, iHighestTechInZone)
            if bDebugMessages == true then LOG(sFunctionRef..': We have enough gross energy that we can get T2 pgens (or wait for a t2 engi to be available), iHighestTechInZone='..iHighestTechInZone) end
        else
            if bHaveLowPower and not(bHaveLowMass) then
                iMinTechLevelForPower = iHighestTechInZone
                if bDebugMessages == true then LOG(sFunctionRef..': Will set to highest tech in zone rather than on team') end
            else
                iMinTechLevelForPower = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]
                if bDebugMessages == true then LOG(sFunctionRef..': Will base tech level for power on teach highest tech') end
            end
        end
        if iMinTechLevelForPower > 1 and bHaveLowPower and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == iMinTechLevelForPower then
            --Do we have at least 1 available engi of the desired tech level in this zone? if not, then lower power requirements by 1 tier
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[iMinTechLevelForPower]) then
                iMinTechLevelForPower = iMinTechLevelForPower - 1
                if bDebugMessages == true then LOG(sFunctionRef..': We have low power and significant mass so no longer want to wait for a higher tech engi to become available but instad want to just get some power built, Lowering power tech required by 1 tier') end
            end
        end

    end
    if bDebugMessages == true then LOG(sFunctionRef..': iMinTechLevelForPower='..iMinTechLevelForPower..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
    --Active gameender template - want to always have 1 engi on duty as highest priority to avoid having orders cancelled
    iCurPriority = iCurPriority + 1
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData) then
        HaveActionToAssign(refActionManageGameEnderTemplate, 3, 25)
    end
    --Higher priority than low power - if we need to rush T3 AA due to enemy having T3 air and us not having good enoguh AA force
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Very high GroundAA builder to defend against strat or enemy air exp for LZ'..iLandZone..', tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Friendly factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Enemy air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Enemy air exp count='..table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals])..'; Time since last stalled E='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0)..'; OurAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]) end
    if (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 3000 or (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) == false and (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 8000 or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 20000 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 5000)) and (not(bHaveLowPower) or GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0) >= 11) and not(AiBotMap.bIsCampaignMap) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] <= 14000))  and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 then
        --Get AirAA threat for the likely subteam in here
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] do
                if oUnit:GetAIBrain().AiBotAI then
                    aiBrain = oUnit:GetAIBrain()
                    break
                end
            end
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) or (AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurAirAAThreat] <= 1200 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3) == 0) then
                --Do we have any T3 AA here already?
                local tExistingAirAA = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructureAA * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local iExistingT3AA = 0
                local iShieldedT3AA = 0
                local bEnemyAirExpThreat = not(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]))
                local bEnemyExpBomberThreat = false
                if bEnemyAirExpThreat then bEnemyExpBomberThreat = not(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryBomber, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]))) end

                if AiBotUtilities.IsTableEmpty(tExistingAirAA) == false then
                    for iUnit, oUnit in tExistingAirAA do
                        if oUnit:GetFractionComplete() >= 1 then
                            iExistingT3AA = iExistingT3AA + 1
                            if not(bEnemyAirExpThreat) then
                                break
                            end
                            if AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                                iShieldedT3AA = iShieldedT3AA + 1
                            elseif bEnemyExpBomberThreat and not(oUnit[AiBotBuilding.refbUnitWantsShielding]) then
                                AiBotBuilding.CheckIfUnitWantsFixedShield(oUnit, false, 1)
                                if bDebugMessages == true then LOG(sFunctionRef..': CHecked if T3AA oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' wants some shielding, Does unit want shielding now='..tostring(oUnit[AiBotBuilding.refbUnitWantsShielding] or false)) end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iExistingT3AA='..iExistingT3AA..'; iShieldedT3AA='..iShieldedT3AA..'; bEnemyExpBomberThreat='..tostring(bEnemyExpBomberThreat)..'; Enemy AirExp threat='..AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals], true, false, false, true, false, false)..'; Our groundAA='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
                if iExistingT3AA == 0 or (bEnemyAirExpThreat and AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals], true, false, false, true, false, false) > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy total air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; bSaveMassForMML='..tostring(bSaveMassForMML)) end
                    if not(bSaveMassForMML) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 2 then
                        iBPWanted = 30
                        if not(bHaveLowPower) then iBPWanted = 90
                        elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) == false and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 6000 then
                            iBPWanted = 50
                        end
                        --Get shielding for AA if dont have any
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to shield AA instead, bEnemyExpBomberThreat='..tostring(bEnemyExpBomberThreat)..'; iExistingT3AA='..iExistingT3AA..'; iShieldedT3AA='..iShieldedT3AA..'; Stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
                        local bBuildingShieldInstead = false
                        if bEnemyExpBomberThreat and iExistingT3AA >= 4 and iShieldedT3AA < math.min(4, iExistingT3AA * 0.5) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 225*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                            local iShieldBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
                            if bDebugMessages == true then LOG(sFunctionRef..': iShieldBPWanted='..(iShieldBPWanted or nil)..'; iTechLevelWanted='..(iTechLevelWanted or 'nil')..'; oUnitToShield='..(oUnitToShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToShield) or 'nil')) end
                            if iShieldBPWanted > 0 and oUnitToShield then
                                if iTechLevelWanted == 2 and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetFactionIndex() == AiBotUnitInfo.refFactionCybran then iTechLevelWanted = 3 end
                                bBuildingShieldInstead = true
                                HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to get shielding, oUnitToShield='..oUnitToShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToShield)) end
                            end
                        end
                        if not(bBuildingShieldInstead) then
                            HaveActionToAssign(refActionBuildAA, 3, iBPWanted)
                            if bDebugMessages == true then LOG(sFunctionRef..': T3 AA builder - iBPWanted='..iBPWanted) end
                        end
                    end
                end
            end
        end
    end

    --Anti-teleport PD builder
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) == false then
        --Are any teleport targets within 90 of this zone midpoint? If so then build emergency PD, and base the PD location on the teleport location (but move a bit towards this zone's midpoint from the actual teleport location)
        local iClosestTeleportDist = 90
        local iCurTeleportDist
        local tClosestTeleport
        for iEntry, tTeleportData in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails] do
            iCurTeleportDist = AiBotUtilities.GetDistanceBetweenPositions(tTeleportData[AiBotTeam.subreftTeleportTarget], tLZData[AiBotMap.subrefMidpoint])
            if iCurTeleportDist < iClosestTeleportDist then
                iClosestTeleportDist = iCurTeleportDist
                tClosestTeleport = {tTeleportData[AiBotTeam.subreftTeleportTarget][1], tTeleportData[AiBotTeam.subreftTeleportTarget][2], tTeleportData[AiBotTeam.subreftTeleportTarget][3]}
            end
        end
        if tClosestTeleport then
            iBPWanted = 60
            HaveActionToAssign(refActionBuildEmergencyPD, 1, iBPWanted, AiBotUtilities.MoveInDirection(tClosestTeleport, AiBotUtilities.GetAngleFromAToB(tClosestTeleport, tLZData[AiBotMap.subrefMidpoint]), 10, true))
            iCurPriority = iCurPriority + 1
            HaveActionToAssign(refActionBuildSecondPD, 1, iBPWanted, AiBotUtilities.MoveInDirection(tClosestTeleport, AiBotUtilities.GetAngleFromAToB(tClosestTeleport, tLZData[AiBotMap.subrefMidpoint]), 6, true))
        end
    end

    --Early game transport wanting engineer (takes priority over factory if we have at least 2 in this zone)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Is table of transports waiting for engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]))) end
    if not bDualGapAirHomeOnly and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
        --Check the table is still valid
        local iEngisWantedForTransports, iMinTechLevel = GetEngisWantedForTransports(tLZTeamData, true)

        if bDebugMessages == true then LOG(sFunctionRef..': iEngisWantedForTransports after refresh='..iEngisWantedForTransports) end
        if iEngisWantedForTransports > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': want engineers to load onto transport if early game, will first check if we have at least 2 factories in this zone and if the transport has a lifetime count of 1 and we only have 1 transport, size of transport table='..table.getn(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits])..'; Time='..GetGameTimeSeconds()) end
            if table.getn(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == 1 and GetGameTimeSeconds() <= 900 then
                local bFirstTransport = true
                if (AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits][1] or 1)) > 1 then bFirstTransport = false end
                if bDebugMessages == true then LOG(sFunctionRef..': bFirstTransport='..tostring(bFirstTransport)) end
                if bFirstTransport then
                    if not(tFactoriesInLZ) or iFactoriesInLZ == 0 then
                        iFactoriesInLZ = 0
                        tFactoriesInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    end
                    if AiBotUtilities.IsTableEmpty(tFactoriesInLZ) == false then
                        for iFactory, oFactory in tFactoriesInLZ do
                            if oFactory:GetFractionComplete() == 1 then
                                iFactoriesInLZ = iFactoriesInLZ + 1
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iFactoriesInLZ='..iFactoriesInLZ) end
                    if iFactoriesInLZ >= 2 then
                        --iActionToAssign,      iMinTechLevelWanted, i  BuildPowerWanted,                                                                       vOptionalVariable,  bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting
                        --BP wanted - engineers already attached shouldn't be treated as available, however want BP wanted to be total not additional to avoid multiple unattached engineers being given the same order
                        if bDebugMessages == true then LOG(sFunctionRef..': Will seek engineers for transport, iCurpriority='..iCurPriority) end
                        HaveActionToAssign(refActionLoadOntoTransport, (iMinTechLevel or 1), iEngisWantedForTransports * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], nil, false,false) --Max 5 BP to make sure we only try loading 1 engi at a time
                    end
                end
            end
        end
    end

    --TMD if we have recently lost a building to enemy TML - have 1 engineer assigned as top priority (will assign more later on)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': highest priority TMD builder, is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))..'; Enemy air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; Enemy combat total='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Time since subrefiTimeOfLastBuildingDeathToTML='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] or 0)) end
    if tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] <= 90 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] < tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] then
        local oUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone)
        if bDebugMessages == true then LOG(sFunctionRef..': Is oUnitWantingTMD valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnitWantingTMD))) end
        if oUnitWantingTMD then
            iBPWanted = tiBPByTech[2]
            if not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 2 >= 2 then iBPWanted = tiBPByTech[2] * 2 end
            if bSaveMassForMML then
                iBPWanted = iBPWanted * 0.5
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build TMD as top priority, iBPWanted='..iBPWanted..'; Unit wanting TMD='..oUnitWantingTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitWantingTMD)) end
            HaveActionToAssign(refActionBuildTMD, 2, iBPWanted, oUnitWantingTMD)
        end
    end

    --First T2 PD emergency builder if we have no T2 PD and nearby enemy threat (unless are on a t1 land spam map)
    --Approaching enemy guncom - prioritise upgrades if dont have T2, if do have T2 then get T2 PD; also get T2 PD if enemies are in this LZ and we have T2 tech
    iCurPriority = iCurPriority + 1
    local oNearestEnemy
    local iApproachingACUThreat, oNearestEnemyACU = AiBotConditions.GetThreatOfApproachingEnemyACUsAndNearestACU(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam)
    local tNearestEnemyACU
    if oNearestEnemyACU then tNearestEnemyACU = oNearestEnemyACU:GetPosition() end
    local iCurPDThreat

    if bDebugMessages == true then LOG(sFunctionRef..': Checking if emergency PD is needed, iApproachingACUThreat='..iApproachingACUThreat..'; Brain factory='..aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel]..'; Zone wants T1 spam='..tostring(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam))..'; Team gross energy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or 'nil')..'; PD builder: Part 1='..tostring(not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25)..'; Part 2='..tostring((aiBrain[AiBotOverseer.refbPrioritiseDefence] and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and (not(bHaveLowPower) or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 75)))..'; Part 3='..tostring((tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2))..'; Part 4='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4)))..'; Part 5='..tostring((tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false))..'; Part 6='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 120 or (not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0)))..'; subrefiTeamGrossEnergy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
    if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25 and (((iApproachingACUThreat > 0 or
            (aiBrain[AiBotOverseer.refbPrioritiseDefence] and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and (not(bHaveLowPower) or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 75))
            or (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2))
            and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4)))
            or (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and (tLZTeamData[AiBotMap.subrefbLZWantsDFSupport] or (not(bHaveLowPower) and not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))))
            and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 120 or (not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0)) then
        --We have T2 (or only need T1 due to enemy not having gun), so want to build PD
        local iRangeThreshold = 35 --Range of Aeon guncom
        iCurPDThreat = 0
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                if iRange >= iRangeThreshold then
                    iCurPDThreat = iCurPDThreat + iThreat
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': We have T2 or better, iCurPDThreat='..iCurPDThreat..'; iAppraochingACUThreat='..iApproachingACUThreat..'; iRangeThreshold='..iRangeThreshold..'; tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]='..repru(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange])..'; iLandZone='..iLandZone) end
        if iCurPDThreat <= math.max(470, iApproachingACUThreat * 0.5) or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iCurPDThreat <= 2500 and iCurPDThreat <= 1000 + 100 * tLZTeamData[AiBotMap.subrefMexCountByTech][2] + 300 * tLZTeamData[AiBotMap.subrefMexCountByTech][3]) then
            --Dont get T2 PD if we need mass for MML as the ACU is a T2 engi ACU with no gun, unless we have minimal threat in this zone
            if not(bSaveMassForMML) or (aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 or (iApproachingACUThreat  > tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryMML) >= 5) then
                iBPWanted = 39 --3 t2 engis
                if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 80 end
                local tTargetBuildLocation
                if tNearestEnemyACU then
                    tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(tNearestEnemyACU, tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, 2)
                else
                    local tEnemiesToConsider = {}
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                table.insert(tEnemiesToConsider, oUnit)
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tEnemiesToConsider) == false then
                        if not(oNearestEnemy) then oNearestEnemy = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.reftoNearestDFEnemies], tLZData[AiBotMap.subrefMidpoint], true, AiBotMap.refPathingTypeLand) end
                        if oNearestEnemy then --factors in if can path to enemy by land
                            if bDebugMessages == true then LOG(sFunctionRef..': oNearestEnemy='..(oNearestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy) or 'nil')..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                            tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(oNearestEnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, 2)
                        end
                    end
                    if not(oNearestEnemy) then
                        --Turtle personality when we have 4+ T2 mexes or a t3 mex, and no T2+ PD, then see if any enemies adjacent to an adjacent zone
                        local bDontGetPD = true
                        if aiBrain[AiBotOverseer.refbPrioritiseDefence] and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= math.min(5, tLZData[AiBotMap.subrefLZOrWZMexCount])) and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                            if iCurPDThreat <= 600 then
                                --Just get some PD
                                bDontGetPD = false
                            elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    if tAdjLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                        bDontGetPD = false
                                        break
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': refbPrioritiseDefence='..tostring(bDontGetPD or false)) end
                        if bDontGetPD then
                            iBPWanted = 0
                        elseif AiBotUtilities.IsTableEmpty(tTargetBuildLocation) then
                            --Build towards enemy base
                            tTargetBuildLocation = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), 25, true, false, AiBotMap.bIsCampaignMap)
                        end
                    end
                end
                if iBPWanted > 0 and tTargetBuildLocation then
                    --Reduce BP wanted if there is nearby T2 arti (as we probably want to get more T2 arti instead)
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then iBPWanted = iBPWanted * 0.5 end
                    --Reduce BP wanted if we are only at T2, and lack many T2 engis in the zone, and want more power, and location is far away
                    if bDebugMessages == true then LOG(sFunctionRef..': Reducing BP if we havent built many t2 engineers and PD location is far away, highest friendly tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Dist to target build location='..AiBotUtilities.GetDistanceBetweenPositions(tTargetBuildLocation, tLZData[AiBotMap.subrefMidpoint])..'; iT2PlusEngisInZone='..AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)..'; T2 LC='..AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)..'; bWantMorePower='..tostring(bWantMorePower)..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]) end
                    if bWantMorePower and iBPWanted > 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 then
                        local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tTargetBuildLocation, tLZData[AiBotMap.subrefMidpoint])
                        if iDistToTarget > 40 then
                            local iT2PlusEngisInZone = AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)
                            if bDebugMessages == true then LOG(sFunctionRef..': iT2PlusEngisInZone='..iT2PlusEngisInZone..'; T1 LC of engis='..AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)) end
                            if iT2PlusEngisInZone <= 4 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer - categories.TECH1) <= 8 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Reducing BP wanted, enemy combat in zone='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; iBPWanted before reduction='..iBPWanted) end
                                if (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < 10 and iDistToTarget >= 70 then
                                    iBPWanted = math.min(iBPWanted, 25)
                                else
                                    iBPWanted = math.max(math.min(iBPWanted, 25), iBPWanted * 0.47)
                                end
                            elseif iT2PlusEngisInZone <= 5 and iDistToTarget >= 50 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 500 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Halving BP wanted') end
                                iBPWanted = iBPWanted * 0.5
                            end
                        end
                    end
                    HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted, tTargetBuildLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will build emergency T2 PD, iBPWanted='..iBPWanted..'; Dist from midpoint to tTargetBuildLocation='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tTargetBuildLocation)) end
                end
            end
        end
        --T1 PD if approaching enemy ACUs that lack gun
    elseif iApproachingACUThreat > 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25 and oNearestEnemyACU and tNearestEnemyACU and oNearestEnemyACU[AiBotUnitInfo.refiDFRange] < 26
            and ((oNearestEnemyACU[AiBotACU.refiUpgradeCount] or 0) == 0 or not(bSaveMassForMML) or (aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 or (iApproachingACUThreat  > tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryMML) >= 5))
    then
        local iDistFromACUToBase = AiBotUtilities.GetDistanceBetweenPositions(oNearestEnemyACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
        if bDebugMessages == true then LOG(sFunctionRef..': Considering just getting t1 PD, iDistFromACUToBase='..iDistFromACUToBase) end
        if iDistFromACUToBase <= 175 and (iApproachingACUThreat > 1500 or iDistFromACUToBase <= 150) and (iDistFromACUToBase <= 90 or AiBotMap.iMapSize > 500) then
            iCurPDThreat = 0
            local iRangeThreshold = 26
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                    if iRange >= iRangeThreshold then
                        iCurPDThreat = iCurPDThreat + iThreat
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iCurPDThreat='..iCurPDThreat) end
            if iCurPDThreat < iApproachingACUThreat * 0.75 and (iCurPDThreat == 0 or (iDistFromACUToBase <= 125 and (iDistFromACUToBase <= 100 or oNearestEnemyACU[AiBotACU.refiUpgradeCount] == 0))) then
                iBPWanted = 15
                local tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(tNearestEnemyACU, tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, 1)
                HaveActionToAssign(refActionBuildEmergencyPD, 1, iBPWanted, tTargetBuildLocation)
                if bDebugMessages == true then LOG(sFunctionRef..': Will get emergency T1 PD, iBPWanted='..iBPWanted..'; tNearestEnemyACU='..repru(tNearestEnemyACU)..'; tTargetBuildLocation='..repru(tTargetBuildLocation)) end
            end
        end
    end

    --PD if enemy has teleport
    iCurPriority = iCurPriority + 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasTeleport] and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 then
        if not(iCurPDThreat) then
            iCurPDThreat = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                local iRangeThreshold
                if aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 then iRangeThreshold = 30 else iRangeThreshold = 20 end
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                    if iRange >= iRangeThreshold then
                        iCurPDThreat = iCurPDThreat + iThreat
                    end
                end
            end
        end
        if iCurPDThreat <= 10000 then
            local iPDThreatWanted = 10000
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyLongRangeUnits]) == false then iPDThreatWanted = iPDThreatWanted * 0.7 end
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then iPDThreatWanted = iPDThreatWanted * 0.7 end
            if (bHaveLowPower or (bHaveLowMass and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) then
                iPDThreatWanted = iPDThreatWanted * 0.7
            end
            if iCurPDThreat < iPDThreatWanted then
                iBPWanted = 30 + 120 * (iPDThreatWanted - iCurPDThreat)/iPDThreatWanted
                HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted, tLZData[AiBotMap.subrefMidpoint])
            end
        end
    end


    --Start of game or low power - build hydro if one nearby, otherwise build pgen
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Low power at start of game builder, iCurPriority='..iCurPriority..'; Z='..iLandZone..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Is table of hydro locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroLocations]))..'; Is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroUnbuiltLocations]))..'; bHaveLowPower='..tostring(bHaveLowPower)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bWantMorePower='..tostring(bWantMorePower)..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 200 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] then
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroLocations]) == false then
            --Norush check
            if bDebugMessages == true then LOG(sFunctionRef..': CHecking if hydro prevented by norush, AiBotOverseer.bNoRushActive='..tostring(AiBotOverseer.bNoRushActive or false)..'; AiBotConditions.NoRushPreventingHydroOrMex(tLZData)='..tostring(AiBotConditions.NoRushPreventingHydroOrMex(tLZData) or false)) end
            if AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tLZData) then
                if bDebugMessages == true then LOG(sFunctionRef..': Norush is preventing b uilding a hydro at core zone so will just build a pgen, iLandZone='..iLandZone) end
                HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, 10)
            else

                if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..':  Will try and build a hydro, unless we have no unbuilt locations and have no part complete hydro in which case will build power') end
                local bCanBuildOrAssistHydro = false
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
                    bCanBuildOrAssistHydro = true
                else
                    local tHydroInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tHydroInZone) == false then
                        for iUnit, oUnit in tHydroInZone do
                            if oUnit:GetFractionComplete() < 1 then bCanBuildOrAssistHydro = true break end
                        end
                    end
                end
                --Issue on some maps if lots of hydro locations spread out
                if bDebugMessages == true then LOG(sFunctionRef..': bCanBuildOrAssistHydro='..tostring(bCanBuildOrAssistHydro)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Hydros in zone='..table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefHydroLocations])..'; Higheest friendly factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Get power instead of hydro='..tostring(AiBotConditions.GetPowerInsteadOfHydroEvenIfHydroAvailable(iTeam, tLZData, tLZTeamData, iPlateau, iLandZone, bHaveLowMass, bHaveLowPower))) end
                if bCanBuildOrAssistHydro and not(AiBotConditions.GetPowerInsteadOfHydroEvenIfHydroAvailable(iTeam, tLZData, tLZTeamData, iPlateau, iLandZone, bHaveLowMass, bHaveLowPower)) then
                    iBPWanted = 10
                    if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                        iBPWanted = 5
                        if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(4, (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 8*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]] and not(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotIsDefeated) and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetCurrentUnits(AiBotUnitInfo.refCategoryPower) < 3 then
                            HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, 5)
                        else
                            HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
                        end
                    else
                        HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
                    end

                else
                    HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, 5)
                end
            end
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..': Will try and build PGens') end
            HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, 5)
        end
    else
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroUnbuiltLocations]) == false and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 20 >=  AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or (bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 0.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (bWantMorePower and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 16 and aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.3 and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] < 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.01)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Have at least 10 energy income on the team, cHecking if hydro prevented by norush, AiBotOverseer.bNoRushActive='..tostring(AiBotOverseer.bNoRushActive or false)..'; AiBotConditions.NoRushPreventingHydroOrMex(tLZData)='..tostring(AiBotConditions.NoRushPreventingHydroOrMex(tLZData) or false)..'; Want power instad of hydro='..tostring(AiBotConditions.GetPowerInsteadOfHydroEvenIfHydroAvailable(iTeam, tLZData, tLZTeamData, iPlateau, iLandZone, bHaveLowMass, bHaveLowPower))) end
            if (AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tLZData)) or AiBotConditions.GetPowerInsteadOfHydroEvenIfHydroAvailable(iTeam, tLZData, tLZTeamData, iPlateau, iLandZone, bHaveLowMass, bHaveLowPower) then
                if bDebugMessages == true then LOG(sFunctionRef..': Norush is preventing b uilding a hydro so will just build a pgen, iLandZone='..iLandZone) end

                HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, 10)
            else
                if bDebugMessages == true then LOG(sFunctionRef..': WIll try to build hydro') end
                iBPWanted = 10
                if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(4, (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)) then iBPWanted = 5 end
                HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
            end
            --Make sure we have 1 power of the cur tech level provided dont have low mass
        elseif (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 0.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= math.max(0.2, 0.15 + 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]))) and (bHaveLowPower and ((not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 30 or GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -100) <= 10)) or (not(bHaveLowMass) and bWantMorePower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < (30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] + 160 * math.max(0, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] - 2))) * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]) then
            --Exception if recently built power and have nearby enemies (so can e.g. do things like PD)
            if iNearbyEnemyAirToGroundThreat == 0 and (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 3 then
                iBPWanted = 4 * tiBPByTech[iMinTechLevelForPower]
                if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                    iBPWanted = 3 * tiBPByTech[iMinTechLevelForPower]
                else
                    iBPWanted = 4 * tiBPByTech[iMinTechLevelForPower]
                end
            else
                if (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.03) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.25 then
                    iBPWanted = tiBPByTech[iMinTechLevelForPower]
                else
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.02 then
                        iBPWanted = 3 * tiBPByTech[iMinTechLevelForPower]
                    else
                        iBPWanted = 2 * tiBPByTech[iMinTechLevelForPower]
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Start of game Want more power, iBPWanted='..iBPWanted..'; Nearby enemy air to ground threat='..iNearbyEnemyAirToGroundThreat..'; Enemy combat total='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Enemies in this or adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Mass%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
            HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, iBPWanted)

        end
    end

    --Mass storage if we have none (e.g. for snadbox games where lose ACU)
    iCurPriority = iCurPriority + 1
    if AiBotBuilding.iLowestMassStorageTechAvailable <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 0.1 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        --Build mass storage for this team - e.g. if in sandbox and lost ACU
        HaveActionToAssign(refActionBuildMassStorage, AiBotBuilding.iLowestMassStorageTechAvailable, 5)
    end


    --Being bombed or have large air force in our core base - need AA if dont have any fixed AA (see a bit later on for high priority AA builder when under air attack if already have 1 fixed AA)
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 or iNearbyEnemyAirToGroundThreat >= 500 or tLZTeamData[AiBotMap.refiEnemyAirAAThreat] >= 500 then
        --If overall enemy air threat is low and we are on a nont2 mex map then want to rly on MAA
        if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] >= 200 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] == 0 then
            --Do we already have fixed AA in this LZ?
            local iAACategory = AiBotUnitInfo.refCategoryStructureAA
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iAACategory = iAACategory * categories.TECH3 end
            local tExistingFixedAA = EntityCategoryFilterDown(iAACategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local bHaveFixedAA = false
            if AiBotUtilities.IsTableEmpty(tExistingFixedAA) == false then
                for iUnit, oUnit in tExistingFixedAA do
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have fixed AA, considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                    if oUnit:GetFractionComplete() then bHaveFixedAA = true break end
                end
            end
            if not(bHaveFixedAA) then
                iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 or iNearbyEnemyAirToGroundThreat >= 500 then iBPWanted = iBPWanted * 2 end
                if not(bHaveLowPower) then
                    if not(bHaveLowMass) then iBPWanted = iBPWanted * 4
                    else iBPWanted = iBPWanted * 2
                    end
                end
                HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': AA builder if no fixed AA: iBPWanted='..iBPWanted..'; iNearbyEnemyAirToGroundThreat='..iNearbyEnemyAirToGroundThreat..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; subrefiAlliedGroundAAThreat='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
            end
        end
    end

    -- DualGap: keep a small reclaim crew active while there is safe reclaim in
    -- the core zone. This is deliberately independent of stored mass so that
    -- reclaim remains part of the opening timing instead of stopping after the
    -- first few wrecks have funded the economy.
    if aiBrain.AiBotDualGapReclaimAlways
            and aiBrain:GetEconomyStoredRatio('MASS') < 0.8
            and (tLZData[AiBotMap.subrefTotalMassReclaim] or 0) >= 50
            and not tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]
            and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) <= 0 then
        iCurPriority = iCurPriority + 1
        local iReclaimEngineerCount = aiBrain.AiBotDualGapReclaimEngineerCount or 2
        local iReclaimBPWanted = iReclaimEngineerCount * (tiBPByTech[1] or 5)
        if (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 1000 then
            iReclaimBPWanted = math.max(iReclaimBPWanted, 10)
        end
        HaveActionToAssign(refActionReclaimArea, 1, iReclaimBPWanted, { false, nil })
        if not aiBrain.AiBotDualGapReclaimPolicyLogTime or GetGameTimeSeconds() - aiBrain.AiBotDualGapReclaimPolicyLogTime >= 30 then
            aiBrain.AiBotDualGapReclaimPolicyLogTime = GetGameTimeSeconds()
            LOG('AiBot Dual Gap reclaim policy: army='..tostring(aiBrain:GetArmyIndex())..'; role='..tostring(aiBrain.AiBotDualGapRole)..'; zone=P'..tostring(iPlateau)..'Z'..tostring(iLandZone)..'; mass='..tostring(tLZData[AiBotMap.subrefTotalMassReclaim] or 0)..'; reclaim engineers='..tostring(iReclaimEngineerCount)..'; time='..tostring(GetGameTimeSeconds()))
        end
    end

    --Low mass and significant relcaim with no enemies - assign 1 engineer as very high priority (so we can fund other high priority actions)
    iCurPriority = iCurPriority + 1
    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.15 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 and AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam))) and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1000 then
        if bDebugMessages == true then LOG(sFunctionRef..': High priority mass reclaim, iCurPriority='..iCurPriority..'; Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; Signif mass='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; subrefHighestIndividualReclaim='..tLZData[AiBotMap.subrefHighestIndividualReclaim]) end
        iBPWanted = 5
        if not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
            iBPWanted = 10
            if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                iBPWanted = math.max(15, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]])
            end
            if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3000 then
                iBPWanted = iBPWanted * 1.5
                if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.075 then
                    iBPWanted = iBPWanted * 1.5
                end
            end
        end

        --Have 1 engi search for high value wrecks
        if tLZData[AiBotMap.subrefHighestIndividualReclaim] >= 50 then
            HaveActionToAssign(refActionReclaimArea, 1, 5, { false, 50 })
            iBPWanted = iBPWanted + 5
        end
        --Then have 1-2 engis search for reclaim generally
        iCurPriority = iCurPriority + 1
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 100 then --Incase refreshed value from above and have much less
            if bDebugMessages == true then LOG(sFunctionRef..': High priority engis for reclaim, iCurPriority='..iCurPriority..'; iBPWanted='..iBPWanted) end
            HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
        end


    else
        iCurPriority = iCurPriority + 1
    end

    --Have 1 engi start on an experimental if we have all T3 mexes and very high mass % stored, and no nearby LR threats
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 or (not(bWantT3LandForRavagers) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2)) then
        if bDebugMessages == true then LOG(sFunctionRef..': Very high priority exp builder so we can get the build location ready') end
        AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 3, 5)
        --HaveActionToAssign(refActionBuildExperimental, 3, 5)
    end


    --Protect game-ender or similar high avlue target (very high priority on assumption if we have built such a unit we shouldnt have to worry about lack of resources for this
    iCurPriority = iCurPriority + 1
    if not(bPrioritiseProduction) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false then
        --Double check the units still need special shield protection
        local bContinue = true
        for iUnit, oUnit in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
            if oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                table.remove(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection], iUnit)
                bContinue = false
                break
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to assign units to active shield protection, will list out each unit for this zone that wants active protection')
            for iUnit, oUnit in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
                LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Mass cost='..oUnit[AiBotUnitInfo.refiUnitMassCost])
            end
        end
        if bContinue then
            --Check not an easy AI
            --if not(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotEasy) then --have instead disabled the 'ctrlk existing shield to build new shield' logic if AiBotEasy is enabled

            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                iBPWanted = math.max(100, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] * 300 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] * 75)
            else
                iBPWanted = 100
            end


            if bDebugMessages == true then LOG(sFunctionRef..': Special shield defence action iBPWanted='..iBPWanted) end

            --Only use T3 engineers (even if we already have t3 engineers assigned) as want to make sure we can quickly get good concentrated build power
            --function HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist)
            HaveActionToAssign(refActionSpecialShieldDefence, 3, iBPWanted,         nil,                nil,                    nil,                        nil,                            true)
            --end
        end
    end


    --Have 1 engi go to adjacent water zone early game to get naval fac (higher even than unclaimed mex) once we have built 4+ engis (10 in campaign early game)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Early game naval fac for naval map: refbCanPathToEnemyBaseWithLand='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] or false)..'; is subrefAdjacentWaterZones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))..'; refiOurHighestNavalFactoryTech='..(aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] or 'nil')..'; subrefiHighestFriendlyFactoryTech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')) end
    if (not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) or aiBrain[AiBotOverseer.refbPrioritiseNavy]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false and aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 and GetGameTimeSeconds() <= 420 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 1 then
        local iEngiLC = AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer)
        if bDebugMessages == true then LOG(sFunctionRef..': iEngiLC='..iEngiLC) end
        if iEngiLC >= 4 and (not(AiBotMap.bIsCampaignMap) or iEngiLC >= 10 or GetGameTimeSeconds() >= 600) then
            local iCurWZ, iCurPond, bHaveAdjWZWithCoreBase
            local iHighestValuePondValue = 0
            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
                iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
                local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                if tWZTeamData[AiBotMap.subrefWZbCoreBase] then
                    bHaveAdjWZWithCoreBase = true
                end
                iHighestValuePondValue = math.max(iHighestValuePondValue, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWZ]])
            end
            if iHighestValuePondValue > 8 then
                for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                    iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
                    iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
                    local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
                    local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent WZ iCurWZ='..iCurWZ..'; subrefWZbCoreBase='..tostring( tWZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; refiPriorityPondValues='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWZ]] or 'nil')) end
                    if tWZTeamData[AiBotMap.subrefWZbCoreBase] or (not(bHaveAdjWZWithCoreBase) and iHighestValuePondValue >= 30 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWZ]] or 0) >= iHighestValuePondValue and AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) >= 0.3 * AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) then
                        local iEngineersTravelingHere
                        local iEngineersPresentHere
                        local iMaxEngineersWanted
                        if bDebugMessages == true then LOG(sFunctionRef..': does zone want bp='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP])..'; subrefbEnemiesInThisOrAdjacentWZ='..tostring(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])..'; enemy air to ground='..(tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; aiBrain='..aiBrain.Nickname..'; subrefWZFactoryDestroyedCount='..(tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] or 'nil')..'; refbPrioritiseNavy='..tostring(aiBrain[AiBotOverseer.refbPrioritiseNavy] or false)..'; first condition='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP] and (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0)..'; Navy and destroyed condition='..tostring((aiBrain[AiBotOverseer.refbPrioritiseNavy] and (tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] or 0) == 0))) end
                        --If are AiBotNavy then will ignore enemies, as might be civlian or ACU or in adj WZ that is far away and since we are meant to be prioritising navy want to be more aggressive
                        if tWZTeamData[AiBotMap.subrefTbWantBP] and (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and
                                (not(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) or
                                        (aiBrain[AiBotOverseer.refbPrioritiseNavy] and (tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] or 0) == 0))  then
                            iEngineersTravelingHere = 0
                            iEngineersPresentHere = 0
                            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                                iEngineersTravelingHere = table.getn(tWZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                            end
                            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                local tEngineersInAdjZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tEngineersInAdjZone) == false then
                                    iEngineersPresentHere = table.getn(tEngineersInAdjZone)
                                end
                            end
                            iMaxEngineersWanted = 1
                            if iEngiLC >= 8 and not(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) then
                                iMaxEngineersWanted = 2
                            end

                            iBPWanted = iMaxEngineersWanted * 5
                            HaveActionToAssign(refActionMoveToWaterZone, 1, iBPWanted, iCurWZ, true)

                            if bDebugMessages == true then LOG(sFunctionRef..': High priority naval map initial factory engineer for adjacent WZ Tried to send engineers to iCurWZ '..iCurWZ..'; iBPWanted='..iBPWanted) end
                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                            break
                        end
                    end
                end
            end
        end
    end

    --Unclaimed mex in the zone
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef..': Considering if unbuilt or part build mexes in t his LZ, is subrefMexUnbuiltLocations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]))..'; Is subreftoPartBuiltMexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]))..'; Mex by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; subrefLZOrWZMexCount='..tLZData[AiBotMap.subrefLZOrWZMexCount])
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]) == false then
            LOG(sFunctionRef..': Size of unbuilt locations table='..table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]))

        end
    end
    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]) == false and not(AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tLZData, true)) then
        iBPWanted = math.max(5, table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]) * 2.5)
        if bHaveLowPower and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.1) and iBPWanted > 5 then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
                if tLZData[AiBotMap.subrefLZOrWZMexCount] >= 6 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] >= 2 then
                    iBPWanted = 5
                else
                    iBPWanted = 10
                end
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.1 and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80 then
                iBPWanted = 10
            elseif iBPWanted > 20 and iBPWanted >= tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2 then
                iBPWanted = 20
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': High priority mex builder, Have a total of '..table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations])..' unbuilt mex locations in this zone, iBPWanted='..iBPWanted..'; Highest friendly tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
        HaveActionToAssign(refActionBuildMex, 1, iBPWanted)
        if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionBuildMex] or 0) > 0 then
            tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    tAdjLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true
                end
            end
        end
    elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
        --Do we have no engineers assigned to building a mex?
        local bHaveEngisBuilding = false
        if bDebugMessages == true then LOG(sFunctionRef..': Have part built mexes, is toAssignedEngineers empty='..tostring(AiBotUtilities.IsTableEmpty(toAssignedEngineers))) end
        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
            for iEngi, oEngi in toAssignedEngineers do
                if oEngi[refiAssignedAction] == refActionBuildMex then
                    bHaveEngisBuilding = true
                    break
                end
            end
        end
        if not(bHaveEngisBuilding) then
            --Refresh list of mexes
            RefreshPartBuiltMexList(tLZTeamData)
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to assign 5 BP to complete a part built mex') end
                HaveActionToAssign(refActionCompletePartBuiltMex, 1, 5)
            end
        end
    end

    --Adjacent zones wanting mexes that dont already have 1 engineer traveling for every 2 unbuilt mexes, or 5k reclaim
    iCurPriority = iCurPriority + 1
    --(ANY CHANGES TO BELOW - CONSIDER REPLICATING FOR BOTH CORE AND NONCORE BUILDERS) Adjacent LZ that wants engineers (only chekc if we have available engineers)
    --(as of v24 decided to go with differences for the minior LZ (which uses a simplified appraoch) vs core base highest priority for adj LZs
    local tiAdjacentLandZonesWantingEngineersThatAlreadyHaveSome = {}
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have available engineers to send to another LZ. GetHighestTechEngiAvailable='..GetHighestTechEngiAvailable(toAvailableEngineersByTech)) end
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    local iNearbyZonesWantingEngineers = 0
    local iPrevEngisAvailable
    local tLZWantingBPConsidered = {}
    local tbZonesConsideredForPriorityEngi = {}
    local iAdjLZ
    local tiSafeAdjacentZones = {}
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
        local iEngineersTravelingHere
        local iEngineersPresentHere
        local iMaxEngineersWanted
        for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
            if tPathingDetails[AiBotMap.subrefLZTravelDist] <= tLZData[AiBotMap.subrefLZFurthestAdjacentLandZoneTravelDist] then
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                tbZonesConsideredForPriorityEngi[iAdjLZ] = true
                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Dangerous enemies here='..tostring(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Enemy air to ground threat='..(tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)) end
                --Record safe zones for later builder
                if not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then table.insert(tiSafeAdjacentZones, iAdjLZ) end
                if tAdjLZTeamData[AiBotMap.subrefTbWantBP] and (not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) or (tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 6000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) > (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3)) and (tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then
                    iEngineersTravelingHere = 0
                    iEngineersPresentHere = 0
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                        iEngineersTravelingHere = table.getn(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                    end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tEngineersInAdjZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tEngineersInAdjZone) == false then
                            iEngineersPresentHere = table.getn(tEngineersInAdjZone)
                        end
                    end
                    iMaxEngineersWanted = 1
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iMaxEngineersWanted = 2 end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                        iMaxEngineersWanted = math.max(iMaxEngineersWanted, math.ceil(table.gent(tAdjLZTeamData[AiBotMap.subrefMexUnbuiltLocations]) * 0.5))
                    end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
                        iMaxEngineersWanted = iMaxEngineersWanted + 1
                    end
                    --Experimental wreck - try to reclaim as a high priority
                    if tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 6000 and not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4) then
                        iMaxEngineersWanted = iMaxEngineersWanted + 1
                        if tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and bHaveLowMass then iMaxEngineersWanted = iMaxEngineersWanted + 1 end
                    end
                    if iEngineersTravelingHere + iEngineersPresentHere >= iMaxEngineersWanted then
                        tiAdjacentLandZonesWantingEngineersThatAlreadyHaveSome[iPathingRef] = iAdjLZ
                    else
                        tLZWantingBPConsidered[iAdjLZ] = true
                        --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                        local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, true,            false,          true,                   true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                        if tiBPByTechWanted then
                            for iTech = 1, iHighestTechEngiAvailable, 1 do
                                if tiBPByTechWanted[iTech] > 0 then
                                    iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                    iBPWanted = iNearbyZonesWantingEngineers * 5 + tiBPByTechWanted[iTech]
                                    HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, iAdjLZ, true)
                                    if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionMoveToLandZone] or 0) > 0 then tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true end
                                    if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                        iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                    end

                                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Want iBPWanted='..iBPWanted..' to go to iAdjLZ='..iAdjLZ..'; iNearbyZonesWantingEngineers='..iNearbyZonesWantingEngineers..'; iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
                                    if iHighestTechEngiAvailable == 0 then break end
                                end
                            end
                        end
                        if iHighestTechEngiAvailable == 0 then break end
                    end
                end
            else
                break --Table shoudl be sorted closest first so if we are too far away now the later entries should be ignored
            end
        end
    end

    iCurPriority = iCurPriority + 1
    --If have adjacent waterzone that has unbuilt mexes and has no engineers (incl traveling engineers) then also send engineer here
    if bDebugMessages == true then LOG(sFunctionRef..': High priority Considering if we have adjacent WZ that wants engineer for unbuilt mexes or core WZ, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iCurWZ, iCurPond
        local iBPAlreadyAssigned = 0
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
            iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
            local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': iCurWZ='..iCurWZ..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; subrefWZbCoreBase='..tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; brain Gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; Brain gross E='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Highest air fac='..aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; Highest land fac='..aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; Highest naval fac='..aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]..'; refiPriorityPondValues='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWZ]] or 0)) end
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false or (tWZTeamData[AiBotMap.subrefWZbCoreBase] and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iCurWZ]] or 0) > 15 or aiBrain[AiBotOverseer.refbPrioritiseNavy] or not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])) and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.5 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 20 and (aiBrain[AiBotOverseer.refbPrioritiseNavy] or (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 0) and (aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 or tWZTeamData[AiBotMap.subrefWZbCoreBase]))) then
                local iEngineersTravelingHere
                local iEngineersPresentHere
                local iMaxEngineersWanted
                if bDebugMessages == true then LOG(sFunctionRef..': does zone want bp='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP])..'; subrefbEnemiesInThisOrAdjacentWZ='..tostring(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ])..'; enemy air to ground='..(tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)) end
                if tWZTeamData[AiBotMap.subrefTbWantBP] and not(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > 0) then
                    iEngineersTravelingHere = 0
                    iEngineersPresentHere = 0
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                        iEngineersTravelingHere = table.getn(tWZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                    end
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tEngineersInAdjZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tEngineersInAdjZone) == false then
                            iEngineersPresentHere = table.getn(tEngineersInAdjZone)
                        end
                    end
                    iMaxEngineersWanted = 1
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                        iMaxEngineersWanted = math.max(iMaxEngineersWanted, math.ceil(table.gent(tWZTeamData[AiBotMap.subrefMexUnbuiltLocations]) * 0.5))
                    end
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
                        iMaxEngineersWanted = iMaxEngineersWanted + 1
                    end
                    if iMaxEngineersWanted == 1 and tWZTeamData[AiBotMap.subrefWZbCoreBase] and not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.8 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 25 and aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 then iMaxEngineersWanted = 2 end
                    iBPWanted = iMaxEngineersWanted * 5
                    HaveActionToAssign(refActionMoveToWaterZone, 1, iBPWanted + iBPAlreadyAssigned, iCurWZ, true)
                    iBPAlreadyAssigned = iBPAlreadyAssigned + iBPWanted
                    if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionMoveToWaterZone] or 0) > 0 then tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true end
                    if bDebugMessages == true then LOG(sFunctionRef..': Tried to send engineers to iCurWZ '..iCurWZ..'; iBPWanted='..iBPWanted..'; iBPAlreadyAssigned='..iBPAlreadyAssigned) end
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    if iHighestTechEngiAvailable == 0 or iBPAlreadyAssigned >= iBPWanted * 3 then break end
                end
            end
        end
    end

    --Gateway for shieldSACU gameender
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefbGEShieldSACU] then
        local tCompletedGateway = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway * categories.UEF, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local iCompletedGateway = 0
        if AiBotUtilities.IsTableEmpty(tCompletedGateway) == false then
            for iGateway, oGateway in tCompletedGateway do
                if oGateway:GetFractionComplete() == 1 then iCompletedGateway = iCompletedGateway + 1 end
            end
        end
        if iCompletedGateway < 1 then
            if not(AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData)) then iBPWanted = 60
            elseif bHaveLowPower then iBPWanted = 150
            elseif bHaveLowMass then iBPWanted = 210
            else iBPWanted = 300
            end
            --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
            HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted,                  nil,                nil,                    nil,                        AiBotUnitInfo.refFactionUEF)
        end
    end

    --Very High priority factory if we have fewer than 4 (or if lwoer thre number of mexes in the LZ or small map and signif mass stored) and is a smaller map - takes priority over mex expansion; also build more than 4 if dont have low mass and outtech enemy; also if enemy only at T1 and small map then keep building
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want v.high priority factory builder, iCurPriority='..iCurPriority..'; mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; bWantMoreFactories='..tostring(bWantMoreFactories)..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Want air instead of land fac='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))..'; GameTime='..GetGameTimeSeconds()) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 11 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 100 and bWantMoreFactories and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1 and (GetGameTimeSeconds() >= 200 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotMap.iMapSize <= 256) then

        if iFactoriesInLZ == 0 or not(tFactoriesInLZ) then
            tFactoriesInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tFactoriesInLZ) == false then
                for iFactory, oFactory in tFactoriesInLZ do
                    if oFactory:GetFractionComplete() == 1 then iFactoriesInLZ = iFactoriesInLZ + 1 end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iFactoriesInLZ='..iFactoriesInLZ..'; LZ mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
        local iFactoryAdjust = 0
        if AiBotMap.iMapSize <= 256 then
            iFactoryAdjust = math.min(3,AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 100)
        end
        if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 and AiBotMap.iMapSize <= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] > math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]) then
            --We outtech enemy and have decent mass and power, so want more factories to make use of our advantage, if enemy base is relatively near
            if AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 550 and NavUtils.GetTerrainLabel(tLZTeamData[AiBotMap.reftClosestEnemyBase]) == NavUtils.GetTerrainLabel(tLZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                iFactoryAdjust = iFactoryAdjust + 2
            end
        end

        if iFactoryAdjust <= 3 and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] <= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] <= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 300 and AiBotMap.iMapSize < 1000 and (AiBotMap.iMapSize <= 256 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 800) and not(bHaveLowPower) and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotMap.refbCanPathToEnemyBaseWithLand] then
            iFactoryAdjust = 4
        end

        --Increase factories wanted if have lots of mexes upgrading
        if not(bHaveLowMass) and not(bHaveLowPower) and (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
            iFactoryAdjust = iFactoryAdjust + 1
        end

        if iFactoriesInLZ < iFactoryAdjust + math.max(2 , math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount] + 1, 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
            iBPWanted = 5
            if not(bHaveLowMass) then iBPWanted = iBPWanted * 2.5 end
            if not(bHaveLowPower) then iBPWanted = iBPWanted * 2.5 end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and GetGameTimeSeconds() <= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] < 4 then
                iBPWanted = math.min(15, iBPWanted)
                if bHaveLowMass or bHaveLowPower or GetGameTimeSeconds() <= 300 then iBPWanted = math.min(10, iBPWanted) end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build factory, iBPWanted='..iBPWanted..'; iFactoriesInLZ='..(iFactoriesInLZ or 'nil')) end
            local bWantAirNotLand
            if iFactoriesInLZ == 0 then
                bWantAirNotLand = false
                if bDebugMessages == true then LOG(sFunctionRef..': No factoreis in LZ so will get land fac') end
            else bWantAirNotLand = AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)
            end
            local iFactoryAction
            if bWantAirNotLand then
                if bDebugMessages == true then LOG(sFunctionRef..': want to get air fac instead of land factory') end
                iFactoryAction = refActionBuildAirFactory
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Want to build land factory not air factory1') end
                iFactoryAction = refActionBuildLandFactory
            end
            if bHaveLowPower and bWantAirNotLand then iBPWanted = iBPWanted * 0.5 end

            --Change factory action if we already have a particular type under construction - not sure why added this, but it causes some issues e.g. with building air/land fac when we dont want to
            --[[local tFactoriesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tFactoriesInZone) == false then
                for iUnit, oUnit in tFactoriesInZone do
                    if oUnit:GetFractionComplete() < 1 then
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnit.UnitId) then iFactoryAction = refActionBuildAirFactory
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then iFactoryAction = refActionBuildLandFactory
                        end
                    end
                end
            end--]]
            if iFactoriesInLZ > 1 and bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                iBPWanted = 0
            end
            if iBPWanted > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering building factory (or gateway); iFactoryAction= land fac='..tostring(iFactoryAction == refActionBuildLandFactory)) end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] >= 2.0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ArmyBrains[AiBotMap.reftiClosestFriendlyAiBotBrainIndex][AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 then
                    --Get quantum gateway instead if we dont already have one (but ignore building anything if we dont have much mass)
                    if (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2 then
                        local tCompletedGateway = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        local iCompletedGateway = 0
                        if AiBotUtilities.IsTableEmpty(tCompletedGateway) == false then
                            for iGateway, oGateway in tCompletedGateway do
                                if oGateway:GetFractionComplete() == 1 then iCompletedGateway = iCompletedGateway + 1 end
                            end
                        end
                        if iCompletedGateway < 2 and (iCompletedGateway == 0 or (not(bHaveLowMass) and not(bHaveLowPower))) then
                            HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                        else
                            HaveActionToAssign(iFactoryAction, 1, iBPWanted)
                        end
                    end
                else
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] >= 1.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6) then
                        iBPWanted = iBPWanted * 0.5
                        HaveActionToAssign(iFactoryAction, 1, iBPWanted)
                        if ((iFactoryAction == refActionBuildLandFactory or (not(bHaveLowPower) and iFactoriesInLZ <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.98)) and not(aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseDefence])) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3) then
                            local iSecondAction = refActionBuildSecondLandFactory
                            if iFactoryAction == refActionBuildAirFactory then iSecondAction = refActionBuildSecondAirFactory end
                            HaveActionToAssign(iSecondAction, 1, iBPWanted)
                        end
                    else
                        HaveActionToAssign(iFactoryAction, 1, iBPWanted)
                    end
                end
            end
        end
    end

    --Fortify zone - make sure we have at least 2 land facs to help defend
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefLZFortify] then
        if iFactoriesInLZ == 0 or not(tFactoriesInLZ) then
            tFactoriesInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tFactoriesInLZ) == false then
                for iFactory, oFactory in tFactoriesInLZ do
                    if oFactory:GetFractionComplete() == 1 then iFactoriesInLZ = iFactoriesInLZ + 1 end
                end
            end
        end
        if iFactoriesInLZ < 2 and (iFactoriesInLZ == 0 or not(bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
            if not(aiBrain[AiBotOverseer.refbPrioritiseAir]) or not(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)) then
                HaveActionToAssign(refActionBuildLandFactory, 1, iBPWanted)
            else
                HaveActionToAssign(refActionBuildAirFactory, 1, iBPWanted)
            end
        end
    end

    --Build quantum gateway if using a mod (e.g. LOUD) that requires SACUs to build experimentals, or if we have lots of T3 mexes with high resource mod
    iCurPriority = iCurPriority + 1
    if (aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 1.5 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] <= (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(aiBrain:GetArmyIndex() == AiBotUnitInfo.refFactionSeraphim)) or ((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD]) and GetGameTimeSeconds() - math.max((tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] or 0), tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForSMD] or 0) <= 30 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount]))) then
        --Require at least 1 t3 pgen in the zone before starting on quantum gateway unless have very high gross energy
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have enough gross E to warrant building a quantum gateway, or if we should get more power first, bWantMorePower='..tostring(bWantMorePower)..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; No. of t3 pgens constructed in zone='..AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryT3Power)) end
        if not(bWantMorePower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryT3Power) > 0 then
            --If have lots of mexes that coudl be upgraded to T3 then hold off if low on mass
            if (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2 then
                iBPWanted = 90
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 300 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then iBPWanted = 30 + 60 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]  / (300 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
                if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 180 end
                if tLZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount]) then iBPWanted = iBPWanted * 0.25 end
                if bPrioritiseProduction then iBPWanted = iBPWanted * 0.5 end
                local oExistingGateway
                local iClosestCompletion = 0
                local iClosestDist = 10000
                local iCurDist
                local tExistingGateway = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                --If we have part complete gateway then assist this, otherwise assist completed gateway
                for iGateway, oGateway in tExistingGateway do
                    if oGateway:GetFractionComplete() < 1 then
                        if oGateway:GetFractionComplete() > iClosestCompletion then
                            iClosestCompletion = oGateway:GetFractionComplete()
                            oExistingGateway = oGateway
                        end
                    elseif iClosestCompletion == 0 then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oGateway:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oExistingGateway = oGateway
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Building quantum gateway as a high priority so we can get experimentals, oExistingGateway='..(oExistingGateway.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oExistingGateway) or 'nil')) end
                if not(oExistingGateway) then
                    if AiBotUtilities.bFAFActive and aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 1.5 then --we are building the gateway for the eco not for buildilng experimentals
                        ConsiderBuildingMassFabOrGateway(iTeam, iLandZone, tLZTeamData, HaveActionToAssign, bWantMorePower, 1.5, false)
                    else
                        HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                    end
                else
                    --Do we have any SACUs that are upgrading? if so then assist them ahead of the gateway
                    local tSACUInZone = EntityCategoryFilterDown(categories.SUBCOMMANDER, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    local oSACUToAssist
                    if AiBotUtilities.IsTableEmpty(tSACUInZone) == false then
                        for iSACU, oSACU in tSACUInZone do
                            if oSACU:IsUnitState('Upgrading') then
                                oSACUToAssist = oSACU
                                break
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oSACUToAssist='..(oSACUToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSACUToAssist) or 'nil')..'; oExistingGateway='..oExistingGateway.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExistingGateway)) end
                    if oSACUToAssist then
                        HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, oSACUToAssist)
                    else
                        HaveActionToAssign(refActionAssistQuantumGateway, 1, iBPWanted, oExistingGateway)
                    end
                end
            end
        end
    end

    --At least 1 T3 engineers assigned to gameender template if one is active; also assign an extra engineer if we require an engineer of a particular faction and have that engineer available
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering very high priority for active gameender template engineers, iCurPriority='..iCurPriority..'; do we have active gameender template='..tostring(AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData))) end
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData) and (not(bPrioritiseProduction) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) then
        HaveActionToAssign(refActionManageGameEnderTemplate, 3, 30)
        if bDebugMessages == true then LOG(sFunctionRef..': Hihest priority We have an active gameender template so will assign engis to this, do we want UEF engis='..tostring(tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionUEF] or false)..'; do we want sera engineers='..tostring(tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionSeraphim] or false)) end
        if tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionUEF] or tLZTeamData[AiBotMap.subreftbBPByFactionWanted][AiBotUnitInfo.refFactionSeraphim] then
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of available T3 engineers empty='..tostring(AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3]))) end
            if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3]) == false then
                local tUEFAndSeraphimEngineers = EntityCategoryFilterDown(categories.UEF + categories.SERAPHIM, toAvailableEngineersByTech[3])
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of UEF and sera engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tUEFAndSeraphimEngineers))) end
                if AiBotUtilities.IsTableEmpty(tUEFAndSeraphimEngineers) == false then
                    --We have UEF/Sera T3 engineers, and this zone is flagged as wanting engineers of that faction, so assign an additional engineer

                    local iFactionWanted
                    if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.SERAPHIM, tUEFAndSeraphimEngineers)) == false then iFactionWanted = AiBotUnitInfo.refFactionSeraphim else iFactionWanted = AiBotUnitInfo.refFactionUEF end
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to assign faction specific engineer as a very high prioriyt for zone '..iLandZone..'; iFactionWanted='..(iFactionWanted or 'nil')) end
                    HaveActionToAssign(refActionManageGameEnderTemplate, 3, 30, nil, false, true, iFactionWanted)
                end
            end
        end
    end


    --Need SMD as enemy has nuke launcher (or teammate has requested SMD)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; About to consider if want SMD, is table of enemy nukes empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false or (tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] <= 360) then
        local bAssistSMD = false
        local oSMDToShield, oUnderConstructionShield
        iBPWanted, bAssistSMD, oSMDToShield, oUnderConstructionShield = GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, true, bHaveLowMass, bWantMorePower)
        if bDebugMessages == true then LOG(sFunctionRef..': iBPWanted for SMD='..(iBPWanted or 'nil')..'; bAssistSMD='..tostring(bAssistSMD or false)..'; oSMDToShield='..(oSMDToShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSMDToShield) or 'nil')) end
        if iBPWanted > 0 then
            if oUnderConstructionShield then
                if bDebugMessages == true then LOG(sFunctionRef..': Have under construction shield we want to complete to cover SMD') end
                if bAssistSMD then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                        HaveActionToAssign(refActionRepairUnit, 1, iBPWanted * 0.5, oUnderConstructionShield)
                        HaveActionToAssign(refActionAssistSMD, 1, iBPWanted * 0.5)
                    else
                        HaveActionToAssign(refActionRepairUnit, 1, iBPWanted * 0.3, oUnderConstructionShield)
                        HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                    end
                else
                    HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oUnderConstructionShield)
                end
                iCurPriority = iCurPriority + 3
            elseif oSMDToShield then
                iCurPriority = iCurPriority + 1
                if bDebugMessages == true then LOG(sFunctionRef..': Need to shield the SMD first') end
                local iTechLevelWanted = 2
                if (oSMDToShield[refiFailedShieldConstructionCount] or 0) > 0 or (tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 0) >= 5 then iTechLevelWanted = 3 end
                if bAssistSMD then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                        HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted * 0.5, oSMDToShield)
                        HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                    else
                        HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted * 0.1, oSMDToShield)
                        HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                    end
                else
                    HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oSMDToShield)
                end
                iCurPriority = iCurPriority + 2
            elseif bAssistSMD then
                iCurPriority = iCurPriority + 2
                if bDebugMessages == true then LOG(sFunctionRef..': Will assist existing SMD') end
                HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                iCurPriority = iCurPriority + 1
            else
                iCurPriority = iCurPriority + 3
                if bDebugMessages == true then LOG(sFunctionRef..': Want to build SMD, iCurPrioriyt='..iCurPriority) end
                HaveActionToAssign(refActionBuildSMD, 3, iBPWanted)
            end
        else
            iCurPriority = iCurPriority + 3
        end
    else
        iCurPriority = iCurPriority + 3
    end

    --Shielding due to enemy novax
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Priority novax defence, time since detected novax nearby='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] or 0)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
    if tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 15 and (not(bHaveLowPower) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
        local iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
        if iBPWanted > 0 then
            iBPWanted = math.min(iBPWanted, 40)
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end

            HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
            if bDebugMessages == true then LOG(sFunctionRef..': Anti novax priority shield builder, iBPWanted='..iBPWanted..'; will also consider getting second shield') end
            iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, true, iLandZone, iPlateau)
            if iBPWanted > 0 and oUnitToShield then
                iBPWanted = iBPWanted * 0.5
                HaveActionToAssign(refActionBuildSecondShield, iTechLevelWanted, iBPWanted, oUnitToShield)
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to assign any BP to antinovax priority shield builder') end
        end
    end

    --Assist damaged shields in zone (as e.g. Cybran t2(2) shield cant last long against a novax)
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 15 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
        --Check for damaged shields that can assist
        local tFriendlyShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFriendlyShields) == false then
            local oShieldToAssist, iCurShield, iMaxShield
            local iLowestShieldHealth = 16000 --i.e. if have a near full health t3 shield or better dont want to worry about emergency assistance
            local iShieldHealthPercent
            for iShield, oShield in tFriendlyShields do
                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, false)
                if iCurShield < iMaxShield and iCurShield > 0 and iCurShield < iLowestShieldHealth then
                    iLowestShieldHealth = iCurShield
                    oShieldToAssist = oShield
                    iShieldHealthPercent = iCurShield / iMaxShield
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oShieldToAssist='..(oShieldToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShieldToAssist) or 'nil')..'; iLowestShieldHealth='..iLowestShieldHealth) end
            if oShieldToAssist then
                iBPWanted = 100
                if iCurShield <= 10000 and iShieldHealthPercent <= 0.6 then
                    iBPWanted = iBPWanted + 60 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount]
                    if iCurShield <= 5000 then iBPWanted = iBPWanted + 60 end
                end
                HaveActionToAssign(refActionAssistShield, 1, iBPWanted, oShieldToAssist)
            end
        end
    end

    --Transports waiting for engineers
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Is table of transports waiting for engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]))) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
        --Check the table is still valid
        local iEngisWantedForTransports, iMinTechLevel = GetEngisWantedForTransports(tLZTeamData, true)
        if bDebugMessages == true then LOG(sFunctionRef..': iEngisWantedForTransports after refresh='..iEngisWantedForTransports) end
        if iEngisWantedForTransports > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': want engineers to load onto transport') end
            --iActionToAssign,      iMinTechLevelWanted, i  BuildPowerWanted,                                                                       vOptionalVariable,  bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting
            --BP wanted - engineers already attached shouldn't be treated as available, however want BP wanted to be total not additional to avoid multiple unattached engineers being given the same order
            HaveActionToAssign(refActionLoadOntoTransport, (1 or iMinTechLevel), iEngisWantedForTransports * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], nil, false,false) --Max 5 BP to make sure we only try loading 1 engi at a time
        end
    end

    --Zones wanting specific faction engineers (e.g. for shielding game ender)
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers]) == false then
        local iZoneWantingEngineersOfFaction, iFactionWanted = GetZoneAndFactionForPriorityEngineerTravel(tLZTeamData, iTeam, iLandZone, iPlateau)
        if iZoneWantingEngineersOfFaction and iFactionWanted then
            HaveActionToAssign(refActionMoveToLandZone, 3, 90, iZoneWantingEngineersOfFaction, true, false, iFactionWanted)
        end
    end

    --Energy storage if we have none and at least 1 T2+ mex
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Considering building energy storage, Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; Have low power='..tostring(bHaveLowPower)..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]..'; Enemy unit with highest health='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyHighestMobileLandHealth]) end
    if AiBotBuilding.iLowestEnergyStorageTechAvailable <= 2 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or (not(AiBotEconomy.bT3MexCanBeUpgraded) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(2, tLZData[AiBotMap.subrefLZOrWZMexCount]))) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] <= 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 75) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 35 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]
            and (GetGameTimeSeconds() >= 360 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3 or (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2) or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10)
    then
        --Is the number of storage in this LZ <= lowest storage count?
        local toStorageInThisLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local iStorageInThisLZ = 0
        if AiBotUtilities.IsTableEmpty(toStorageInThisLZ) == false then
            for iUnit, oUnit in toStorageInThisLZ do
                if oUnit:GetFractionComplete() == 1 then iStorageInThisLZ = iStorageInThisLZ + 1 end
            end
        else
            iStorageInThisLZ = 0
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iStorageInThisLZ='..iStorageInThisLZ) end
        if iStorageInThisLZ <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then --are ok with gifting storage to a teammate
            if not(bSaveMassForMML) or (iStorageInThisLZ == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to get storage, Is tEngineers[1] valid='..tostring(AiBotUnitInfo.IsUnitValid(tEngineers[1]))) end
                iBPWanted = 5
                if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 20 end
                HaveActionToAssign(refActionBuildEnergyStorage, AiBotBuilding.iLowestEnergyStorageTechAvailable, iBPWanted)
            end
        end
    end

    --Units needing air staging
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': About to check if we need air staging for core zone, Time='..GetGameTimeSeconds()..'; Time of last shortage='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] or 'nil')..'; subrefbTeamIsStallingEnergy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; T2+T3 mec count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3] + tLZTeamData[AiBotMap.subrefMexCountByTech][2]..'; subrefiTeamGrossEnergy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; subrefiTeamGrossMass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] or 0) <= 1.1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 60*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (GetGameTimeSeconds() >= 300 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 40*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
        --Limit of 3 air staging in a LZ
        local tExistingAirStaging = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirStaging, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local iExistingAirStaging = 0
        local oExistingAiBotBrain
        local iAirStagingInThisZoneUnderConstruction = 0
        if AiBotUtilities.IsTableEmpty(tExistingAirStaging) == false then
            for iStaging, oStaging in tExistingAirStaging do
                if oStaging:GetAIBrain().AiBotAI then
                    if oStaging:GetFractionComplete() == 1 then
                        oExistingAiBotBrain = oStaging:GetAIBrain()
                        iExistingAirStaging = iExistingAirStaging + 1
                    else
                        iAirStagingInThisZoneUnderConstruction = iAirStagingInThisZoneUnderConstruction + 1
                    end
                end
            end
        end
        local iUnderConstructionInOtherZonesWithLowResources = 0
        if bDebugMessages == true then LOG(sFunctionRef..': iAirStagingInThisZoneUnderConstruction='..iAirStagingInThisZoneUnderConstruction..'; Active brain count='.. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Highest air fac tech='.. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]) end
        if iAirStagingInThisZoneUnderConstruction == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and (bHaveLowMass or bHaveLowPower or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3) then
            --How many under construction air staging do we have
            iUnderConstructionInOtherZonesWithLowResources = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZTeamData, iTeam, AiBotUnitInfo.refCategoryAirStaging)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iExistingAirStaging='..iExistingAirStaging..'; bHaveLowMass='..tostring(bHaveLowMass)..'; iAirStagingInThisZoneUnderConstruction='..iAirStagingInThisZoneUnderConstruction..'; iUnderConstructionInOtherZonesWithLowResources='..iUnderConstructionInOtherZonesWithLowResources..'; bPrioritiseProduction='..tostring(bPrioritiseProduction)) end
        if iUnderConstructionInOtherZonesWithLowResources == 0 and (iExistingAirStaging == 0 or (iExistingAirStaging == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] > 1) or (iExistingAirStaging < 3 and not(bHaveLowMass)) or (iExistingAirStaging < 8 and oExistingAiBotBrain and oExistingAiBotBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAllNonExpAir) >= 50 * iExistingAirStaging)) and (iExistingAirStaging == 0 or (not(bPrioritiseProduction) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= (40 + 20 * iExistingAirStaging) *AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then

            iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
            if not(bHaveLowMass) then iBPWanted = iBPWanted * 2 end
            HaveActionToAssign(refActionBuildAirStaging, AiBotBuilding.iLowestAirStagingTechAvailable, iBPWanted, nil, false)
            if bDebugMessages == true then LOG(sFunctionRef..': Have flagged we want air staging with iBPWanted='..iBPWanted) end
        end
    end


    --Teammate asked for engi (core zone)
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefoBrainWantingEngi] then
        UpdateSpareEngineerNumber(tLZTeamData, toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            HaveActionToAssign(refActionGiveEngineerToTeammate, 1, 5)
        end
    end

    --High value reclaim in further away zone if an enemy experimental has died recently (so likely to be a high value wreck to get)
    iCurPriority = iCurPriority + 1
    if (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35) and AiBotUtilities.IsTableEmpty(tiSafeAdjacentZones) == false then

        for iEntry, iSafeLZ in tiSafeAdjacentZones do
            local tSafeLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iSafeLZ]
            if AiBotUtilities.IsTableEmpty(tSafeLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                    if tPathingDetails[AiBotMap.subrefLZTravelDist] <= tLZData[AiBotMap.subrefLZFurthestAdjacentLandZoneTravelDist] then
                        local iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                        if not(tbZonesConsideredForPriorityEngi[iAdjLZ]) then
                            tbZonesConsideredForPriorityEngi[iAdjLZ] = true
                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                            local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Dangerous enemies here='..tostring(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Enemy air to ground threat='..(tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Want bp='..tostring(tAdjLZTeamData[AiBotMap.subrefTbWantBP])..'; Signif mass reclaim='..(tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end
                            if tAdjLZTeamData[AiBotMap.subrefTbWantBP] and tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 6000 and (not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) > (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3)) and (tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then
                                local iEngineersTravelingHere = 0
                                local iEngineersPresentHere = 0
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                                    iEngineersTravelingHere = table.getn(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                                end
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                    local tEngineersInAdjZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(tEngineersInAdjZone) == false then
                                        iEngineersPresentHere = table.getn(tEngineersInAdjZone)
                                    end
                                end
                                local iMaxEngineersWanted = 1
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and bHaveLowMass then
                                    iMaxEngineersWanted = iMaxEngineersWanted + 1
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iEngineersTravelingHere='..iEngineersTravelingHere..'; iEngineersPresentHere='..iEngineersPresentHere..'; iMaxEngineersWanted='..iMaxEngineersWanted) end
                                if iEngineersTravelingHere + iEngineersPresentHere >= iMaxEngineersWanted and (iEngineersTravelingHere > 0 or iEngineersTravelingHere + iEngineersPresentHere >= iMaxEngineersWanted * 2) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Already have enough engineers traveling here') end
                                else
                                    tLZWantingBPConsidered[iAdjLZ] = true
                                    --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                                    local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, true,        false,          true,                   true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                                    if tiBPByTechWanted then
                                        for iTech = 1, iHighestTechEngiAvailable, 1 do
                                            if tiBPByTechWanted[iTech] > 0 then
                                                iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                                --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                                HaveActionToAssign(refActionMoveToLandZone, iTech, tiBPByTechWanted[iTech], iAdjLZ,                 true,                   true)
                                                if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionMoveToLandZone] or 0) > 0 then tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true end
                                                if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                                    iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                                end

                                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                                if bDebugMessages == true then LOG(sFunctionRef..': High reclaim adjacent to adjacent zone - Assigned additional BP to go to iAdjLZ='..iAdjLZ..'; iNearbyZonesWantingEngineers='..iNearbyZonesWantingEngineers..'; iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; will abort loop now as only want to trigger this once per cycle') end
                                                break
                                            end
                                        end
                                    end
                                    if iHighestTechEngiAvailable == 0 then break end
                                end
                            end
                        end
                    end
                end
            end
        end
        local iEngineersTravelingHere
        local iEngineersPresentHere
        local iMaxEngineersWanted
        for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
            if bDebugMessages == true then LOG(sFunctionRef..': High reclaim for non adjacent land zones, considering zone with travel dist='..tPathingDetails[AiBotMap.subrefLZTravelDist]..'; iAdjLZ='..tPathingDetails[AiBotMap.subrefLZNumber]) end
            if tPathingDetails[AiBotMap.subrefLZTravelDist] >= 300 then break end
            if tPathingDetails[AiBotMap.subrefLZTravelDist] > tLZData[AiBotMap.subrefLZFurthestAdjacentLandZoneTravelDist] then --we have considered adjacent zones in the above logic
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Dangerous enemies here='..tostring(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Enemy air to ground threat='..(tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Want bp='..tostring(tAdjLZTeamData[AiBotMap.subrefTbWantBP])..'; Signif mass reclaim='..(tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end
                if tAdjLZTeamData[AiBotMap.subrefTbWantBP] and tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 6000 and (not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) > (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3)) and (tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then
                    iEngineersTravelingHere = 0
                    iEngineersPresentHere = 0
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                        iEngineersTravelingHere = table.getn(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                    end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tEngineersInAdjZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tEngineersInAdjZone) == false then
                            iEngineersPresentHere = table.getn(tEngineersInAdjZone)
                        end
                    end
                    iMaxEngineersWanted = 1
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and bHaveLowMass then
                        iMaxEngineersWanted = iMaxEngineersWanted + 1
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iEngineersTravelingHere='..iEngineersTravelingHere..'; iEngineersPresentHere='..iEngineersPresentHere..'; iMaxEngineersWanted='..iMaxEngineersWanted) end
                    if iEngineersTravelingHere + iEngineersPresentHere >= iMaxEngineersWanted and (iEngineersTravelingHere > 0 or iEngineersTravelingHere + iEngineersPresentHere >= iMaxEngineersWanted * 2) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Already have enough engineers traveling here') end
                    else
                        tLZWantingBPConsidered[iAdjLZ] = true
                        --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                        local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, true, false, true, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                        if tiBPByTechWanted then
                            for iTech = 1, iHighestTechEngiAvailable, 1 do
                                if tiBPByTechWanted[iTech] > 0 then
                                    iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                    --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    HaveActionToAssign(refActionMoveToLandZone, iTech, tiBPByTechWanted[iTech], iAdjLZ,                 true,                   true)
                                    if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionMoveToLandZone] or 0) > 0 then tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true end
                                    if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                        iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                    end

                                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Assigned additional BP to go to iAdjLZ='..iAdjLZ..'; iNearbyZonesWantingEngineers='..iNearbyZonesWantingEngineers..'; iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; will abort loop now as only want to trigger this once per cycle') end
                                    break
                                end
                            end
                        end
                        if iHighestTechEngiAvailable == 0 then break end
                    end
                end
            end
        end
    end

    --More power if lowish power and high mass (to try and avoid overflow due to lack of power), but dont increase BP wanted, and only do for T2+ power (not t1 power)
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5) then
        --Are in danger of overflowing - assist either power (if we have low power) or factory (if we dont have low power)
        local iCategoryWanted
        local oBuildingToAssist
        local iClosestToCompletion = -1

        iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]] * (3 + math.max(0, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] - 0.4) * 10))


        if bWantMorePower and (bHaveLowPower or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.05 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.99)) then
            iCategoryWanted = AiBotUnitInfo.refCategoryPower
        else
            iCategoryWanted = AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory
            --LOUD specific - get quantum gateways if at T3 since they use up 15 mass/s by a t3 engineer, vs 2 mass/s for an air fac, if evenflow is enabled
            if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
                --Do we have at least 2 gateways in this zone?
                local tFriendlyGateways = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local iGateways = 0
                if AiBotUtilities.IsTableEmpty(tFriendlyGateways) == false then
                    for iGateway, oGateway in tFriendlyGateways do
                        if oGateway:GetFractionComplete() < 1 then
                            oBuildingToAssist = oGateway
                            break
                        else
                            iGateways = iGateways + 1
                        end
                    end
                end
                if iGateways < 2 or (iGateways < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0) then
                    HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                    iCategoryWanted = nil
                end
            end
        end
        --Increase build power from what have assigned every cycle, as a separate action
        if iCategoryWanted and not(oBuildingToAssist) then
            local tFriendlyBuildings = EntityCategoryFilterDown(iCategoryWanted, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tFriendlyBuildings) == false then
                for iBuilding, oBuilding in  tFriendlyBuildings do
                    if oBuilding:GetFractionComplete() < 1 and oBuilding:GetFractionComplete() > iClosestToCompletion then
                        oBuildingToAssist = oBuilding
                        iClosestToCompletion = oBuilding:GetFractionComplete()
                    end
                end
            end
            if oBuildingToAssist then
                --Old code when wanted to just assign 1 engi each cycle:
                --HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oBuildingToAssist, true, true, nil, false, false)
                --Revised will try out variable no. of engineers (with no increase), instead of increasing by 1 each cycle, to avoid too many engineers assigned to this task; note also that assigning too many engis here can prevent the second power builder from triggering later on (due to no available engis)
                if EntityCategoryContains(categories.TECH1, oBuildingToAssist.UnitId) then iBPWanted = math.min(iBPWanted, 15)
                elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftObjectiveLocation]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryEngineer * categories.TECH3) <= 15 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Reducing iBPWanted so we have enough BP for later campaign objective category') end
                    iBPWanted = math.min(iBPWanted * 0.5, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]] * 3)
                end
                --If have priority unit to build for campaign category and this is early game then reduce BP to assign here

                HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oBuildingToAssist, true, false, nil, false, false)
                if bDebugMessages == true then LOG(sFunctionRef..': Will start increasing the build power to assign to building power or factory by repairing the closest pgen or factory to completion as we have lots of mass stored and want more power, oBuildingToAssist='..oBuildingToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBuildingToAssist)..'; Fraction complete='..oBuildingToAssist:GetFractionComplete()..'; iBPWanted='..iBPWanted..'; iCurPriority='..iCurPriority) end
            end
        end
    end

    --Priority TML to defend against enemy fatboy
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.refbGetTMLBattery] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) == false and table.getn(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) < 8 then
        iBPWanted = GetBPToAssignToBuildingTML(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, bHaveLowMass)
        if bDebugMessages == true then LOG(sFunctionRef..': High priority TML builder, iBPWanted='..iBPWanted) end
        if iBPWanted > 0 then
            HaveActionToAssign(refActionBuildTML, 2, iBPWanted)
        end
    end

    --Power stalling and either gross power significantly lower than gross mass, or we are completely stalling E
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Stalling power high priority power builder, subrefbTeamIsStallingEnergy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; bHaveLowPower='..tostring(bHaveLowPower)..'; subrefiTeamAverageEnergyPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; subrefiTeamAverageMassPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]) end
    if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.8 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 13 >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]))) then
        iBPWanted = math.min(300, aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 10)
        HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, iBPWanted)
        if bDebugMessages == true then LOG(sFunctionRef..': Will try and get more power, iMinTechLevelForPower='..iMinTechLevelForPower..'; iBPWanted='..iBPWanted) end
    end

    --1st experimental - Enemy has land experimental and we dont have one of our own yet (and havent completed one before), unless enemy has a fatboy (in which case we want to focus more on getting t2 arti)
    iCurPriority = iCurPriority + 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 1 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 or (not(bWantT3LandForRavagers) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2)) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] or 0) < 12000 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryLandExperimental, iTeam) == 0)) and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])) == false then
        local iEnemyHighestPercentComplete = 0
        local iClosestExperimental = 100000
        for iExperimental, oExperimental in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
            if AiBotUnitInfo.IsUnitValid(oExperimental) and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryAllAir, oExperimental.UnitId) then
                iEnemyHighestPercentComplete = math.max(iEnemyHighestPercentComplete, oExperimental:GetFractionComplete())
                iClosestExperimental = math.min(iClosestExperimental, AiBotUtilities.GetDistanceBetweenPositions(oExperimental:GetPosition(), tLZData[AiBotMap.subrefMidpoint]))
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyHighestPercentComplete='..iEnemyHighestPercentComplete..'; iClosestExperimental='..iClosestExperimental..'; Can path with land='..tostring(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotMap.refbCanPathToEnemyBaseWithLand])..'; Can path with amphibious='..tostring(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotMap.refbCanPathToEnemyBaseWithAmphibious])) end
        if iEnemyHighestPercentComplete > 0 and iClosestExperimental <= 750 and (ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotMap.refbCanPathToEnemyBaseWithLand] or (iClosestExperimental <= 650 and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotMap.refbCanPathToEnemyBaseWithAmphibious])) then
            --[[local iAliveExperimentals = 0
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                local tFriendlyExperimentals = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandExperimental, false, false)
                if AiBotUtilities.IsTableEmpty(tFriendlyExperimentals) == false then
                    for iExperimental, oExperimental in tFriendlyExperimentals do
                        if oExperimental:GetFractionComplete() >= 0.95 then
                            iAliveExperimentals = iAliveExperimentals + 1
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iAliveExperimentals='..iAliveExperimentals) end
            if iAliveExperimentals == 0 then--]]

            local iHighestCompleteExperimentalInZone = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tExperimentalsUnderConstruction = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tExperimentalsUnderConstruction) == false then
                    for iUnit, oUnit in tExperimentalsUnderConstruction do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            iHighestCompleteExperimentalInZone = math.max(iHighestCompleteExperimentalInZone, oUnit:GetFractionComplete())
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iHighestCompleteExperimentalInZone='..iHighestCompleteExperimentalInZone) end
            iBPWanted = 240
            if bHaveLowPower then iBPWanted = 60 end
            if iHighestCompleteExperimentalInZone > 0 and (iHighestCompleteExperimentalInZone + 0.2 >= iEnemyHighestPercentComplete or iHighestCompleteExperimentalInZone >= 0.6) then
                --Assist the experimental
                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 1, iBPWanted)
                --HaveActionToAssign(refActionBuildExperimental, 1, iBPWanted)
            else
                --Assist air factory if we have air control or enemy experimental is already complete (since unlikely to have time to build our own to counter it)
                if (iEnemyHighestPercentComplete == 1 and iClosestExperimental <= 650) or AiBotConditions.TeamHasAirControl(iTeam) then

                    if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.6 then iBPWanted = 120
                    elseif not(bHaveLowPower) and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                        iBPWanted = 400
                    end
                    local tAirFacsToAssist = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory * AiBotUnitInfo.ConvertTechLevelToCategory(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]), tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    local oAirFactoryToAssist
                    if AiBotUtilities.IsTableEmpty(   tAirFacsToAssist) then
                        tAirFacsToAssist = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of air facs to assist empty='..tostring(AiBotUtilities.IsTableEmpty(tAirFacsToAssist))..'; iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iBPWanted='..iBPWanted) end
                    if AiBotUtilities.IsTableEmpty(tAirFacsToAssist) == false then

                        local iHighestAirFac = 0
                        local iCurTechLevel
                        for iFactory, oFactory in tAirFacsToAssist do
                            if not(oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                                iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oFactory)
                                if iCurTechLevel > iHighestAirFac then
                                    iHighestAirFac = iCurTechLevel
                                    oAirFactoryToAssist = oFactory
                                end
                            end
                        end
                        if oAirFactoryToAssist then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will assist air factory '..oAirFactoryToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirFactoryToAssist)) end
                            HaveActionToAssign(refActionAssistAirFactory, 1, iBPWanted, oAirFactoryToAssist)
                        end
                    end
                else
                    local iTechLevelWanted = 3
                    if iHighestCompleteExperimentalInZone > 0 and iHighestCompleteExperimentalInZone < 1 then iTechLevelWanted = 1 end
                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, iTechLevelWanted, iBPWanted)
                    --HaveActionToAssign(refActionBuildExperimental, iTechLevelWanted, iBPWanted)

                end
            end
            --end
        end
    end


    --Quantum gateway in a high AIx scenario
    iCurPriority = iCurPriority + 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] >= 2.0 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(10, tLZData[AiBotMap.subrefLZOrWZMexCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ArmyBrains[AiBotMap.reftiClosestFriendlyAiBotBrainIndex][AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 900 then
        --Get quantum gateway if we dont already have one
        local tCompletedGateway = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local iCompletedGateway = 0
        if AiBotUtilities.IsTableEmpty(tCompletedGateway) == false then
            for iGateway, oGateway in tCompletedGateway do
                if oGateway:GetFractionComplete() == 1 then iCompletedGateway = iCompletedGateway + 1 end
            end
        end
        iBPWanted = 30
        if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 60 end
        if iCompletedGateway < 2 and (iCompletedGateway == 0 or (not(bHaveLowMass) and not(bHaveLowPower))) then
            HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
        end
    end

    --At least 5 T3 engineers assigned to gameender template if one is active
    iCurPriority = iCurPriority + 1
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData) then
        AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionManageGameEnderTemplate, 3, 150)
        if bDebugMessages == true then LOG(sFunctionRef..': We have an active gameender template so will assign engis to this (unless we want to assist nearby teammate exp)') end
    end

    --V high priority TMD (we have another TMD builder a bit lower)
    iCurPriority = iCurPriority + 1

    if bDebugMessages == true then LOG(sFunctionRef..': Very high priority TMD builder, is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))..'; Enemy air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; Enemy combat total='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and (table.getn(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) >= 4 or (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 and table.getn(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) >= 2) or (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] == 2 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryTMD) < 3)) then
        local oUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone)
        if bDebugMessages == true then LOG(sFunctionRef..': Is oUnitWantingTMD valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnitWantingTMD))) end
        if oUnitWantingTMD then
            iBPWanted = 10
            if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 30 end
            if bSaveMassForMML then
                iBPWanted = iBPWanted * 0.5
            end
            --GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iOptionalLandZone, bReturnTMLCountAsWell, iOptionalCategoryWanted, bGetClosestUnitToOurBase)
            local oSecondUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone,     false,                  nil,                    false,              oUnitWantingTMD)
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build TMD, iBPWanted='..iBPWanted..'; Unit wanting TMD='..oUnitWantingTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitWantingTMD)..'; oSecondUnitWantingTMD='..(oSecondUnitWantingTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSecondUnitWantingTMD) or 'nil')) end
            iCurPriority = iCurPriority + 1
            if oUnitWantingTMD and not(oSecondUnitWantingTMD == oUnitWantingTMD) then
                if bDebugMessages == true then LOG(sFunctionRef..': We will try and build a second TMD as well') end
                HaveActionToAssign(refActionBuildSecondTMD, 2, math.min(10, iBPWanted), oSecondUnitWantingTMD)
            end
        else
            iCurPriority = iCurPriority + 1
        end
    else
        iCurPriority = iCurPriority + 1
    end

    --first ever experimental to build - rush if have t3 mex
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': First experimental - consider rushing if have t3 mex, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Active brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; T3 mexes='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 1 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 or (not(bWantT3LandForRavagers) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 14 + 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        local bHaveExperimentalForThisLandZone, iOtherLandZonesWithExperimental, iMassToComplete = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, true, nil, AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryAirToGround * categories.EXPERIMENTAL, nil, nil, aiBrain.AiBotAirSubteam)
        if bHaveExperimentalForThisLandZone or (iOtherLandZonesWithExperimental == 0 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel) < 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(tLZData[AiBotMap.subrefLZOrWZMexCount], 1) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3 + AiBotUnitInfo.refCategoryEngineer * categories.TECH3) >= 10) then

            iBPWanted = 90
            if not(bHaveLowPower) then
                iBPWanted = 150
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                    if not(bHaveLowMass) then
                        iBPWanted = 400
                    else
                        iBPWanted = 250
                    end
                end
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] then
                iBPWanted = 60
            elseif not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                iBPWanted = 120
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and rush our first experimental, iBPWanted='..iBPWanted) end
            --AssignBuildExperimentalOrT3NavyAction(fnHaveActionToAssign, iPlateau, iLandOrWaterZone, iTeam, tLZOrWZData, bIsWaterZone, iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam,               tLZData, tLZTeamData, false, refActionBuildExperimental, 3, iBPWanted)
            --HaveActionToAssign(refActionBuildExperimental, 3, iBPWanted)
        end
    end


    --Shielding in a high mass scenario
    iCurPriority = iCurPriority + 1
    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 250 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
        local iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
        if iBPWanted > 0 then
            iBPWanted = math.min(iBPWanted, 40)
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end

            HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
            if bDebugMessages == true then LOG(sFunctionRef..': High priority shield builder, iBPWanted='..iBPWanted) end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to assign any BP to high priority shield builder') end
        end
    end

    --T1 spam game - get more land facs if have mass
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam) and bWantMoreFactories and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 0 and (iFactoriesInLZ == 0 or not(bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
        local iFactoryAction = refActionBuildLandFactory
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then iFactoryActino = refActionBuildAirFactory end
        HaveActionToAssign(iFactoryAction, 1, 15)
    end


    --Start of game - if low power and dont ahve 12 gross energy yet, then ahve 1 engi on tree reclaim duty
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Early game tree reclaim: bHaveLowPower='..tostring(bHaveLowPower)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Want to relcaim energy nt mass='..tostring(AiBotConditions.WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone))) end
    if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 12 and AiBotConditions.WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone) then
        HaveActionToAssign(refActionReclaimArea, 1, 5, {true, nil})
    end

    --Send engineers to adjacent zones wnating engineers hwich already have some engineers in them (unless we need more power due to upcoming overflow)
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tiAdjacentLandZonesWantingEngineersThatAlreadyHaveSome) == false and iHighestTechEngiAvailable > 0 and (bHaveLowMass or not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.3 or GetGameTimeSeconds() <= 180) then
        for iPathingRef, iAdjLZ in tiAdjacentLandZonesWantingEngineersThatAlreadyHaveSome do
            tLZWantingBPConsidered[iAdjLZ] = true
            --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
            local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, true, false, true, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering for adjacent zone of lower priority iAdjLZ='..iAdjLZ..'; tiBPByTechWanted='..repru(tiBPByTechWanted)) end
            if tiBPByTechWanted then
                for iTech = 1, iHighestTechEngiAvailable, 1 do
                    if tiBPByTechWanted[iTech] > 0 then
                        iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                        iBPWanted = iNearbyZonesWantingEngineers * 5 + tiBPByTechWanted[iTech]
                        HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, iAdjLZ, true)
                        if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                            iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                        end

                        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                        if bDebugMessages == true then LOG(sFunctionRef..': Want iBPWanted='..iBPWanted..' to go to lower priority adjacent iAdjLZ='..iAdjLZ..'; iNearbyZonesWantingEngineers='..iNearbyZonesWantingEngineers..'; iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
                        if iHighestTechEngiAvailable == 0 then break end
                    end
                end
            end
            if iHighestTechEngiAvailable == 0 then break end
        end
    end

    --Campaign priority defences
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to build campaign priority defences, iCurPriority='..iCurPriority..'; is reftObjectiveLocation empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftObjectiveLocation]))) end
    if tLZTeamData[AiBotMap.reftObjectiveLocation] and (tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjTechLevelWanted] or 1) <= 2 and tLZTeamData[AiBotMap.subrefLZFortify] and AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation]) then
        local iTechLevelWanted = (tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjTechLevelWanted] or 1)
        iBPWanted = tiBPByTech[iTechLevelWanted]
        if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = iBPWanted * 2 end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to assign iBPWanted='..iBPWanted..' with iTechLevelWanted='..iTechLevelWanted..' to the campaign special objective category') end
        HaveActionToAssign(refActionBuildSpecialObjective, iTechLevelWanted, iBPWanted, tLZTeamData[AiBotMap.reftObjectiveLocation])
    end


    iCurPriority = iCurPriority + 1
    local iCoreWZWantingSupportAsLowerPriority
    --If have adjacent waterzone that has unbuilt mexes or is a core WZ of a high value pond, wants engineers and has no combat threat then assign engi
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have adjacent WZ that wants engineer for unbuilt mexes or core WZ, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
    if iHighestTechEngiAvailable > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iCurWZ, iCurPond
        local iBPAlreadyAssigned = 0
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
            iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
            local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
            --Use similar logic to minor land zone to avoid unintended consequences
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurWZ='..iCurWZ..'; Core base='..tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation]='..tostring(tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation])..'; Does it have an empty table of unbuilt mex locations='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; refiPriorityPondValues='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][iCurPond] or 'nil')) end
            local bConsiderWaterZone = false
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                bConsiderWaterZone = true
            elseif tWZTeamData[AiBotMap.subrefWZbCoreBase] and tWZTeamData[AiBotMap.subrefTbWantBP] and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][iCurPond] or 0) >= 14 and ((aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 or GetGameTimeSeconds() >= 900) or not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]))) then
                --Do we already have a completed naval factory here and at least 1 engineer? if so not as high priority
                bConsiderWaterZone = true
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tFactoriesAndEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tFactoriesAndEngineers) == false then
                        local iEngiCount = 0
                        local iCompletedFactoryCount = 0
                        for iUnit, oUnit in tFactoriesAndEngineers do
                            if oUnit:GetFractionComplete() == 1 then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId) then
                                    iCompletedFactoryCount = iCompletedFactoryCount + 1
                                else
                                    iEngiCount = iEngiCount + 1
                                end
                            end
                        end
                        if iCompletedFactoryCount > 0 and iCompletedFactoryCount + iEngiCount >= 3 then
                            bConsiderWaterZone = false
                        end
                    end
                end
                if not(bConsiderWaterZone) then iCoreWZWantingSupportAsLowerPriority = iCurWZ end
            end
            if bConsiderWaterZone then

                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to send engineers to an adjaent water zone, iCurWZ='..iCurWZ..'; tWZTeamData[AiBotMap.subrefTbWantBP]='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP] or false)) end
                if tWZTeamData[AiBotMap.subrefTbWantBP] and tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 10 then
                    iBPWanted = 5
                    if tWZTeamData[AiBotMap.subrefTbWantBP] then
                        iBPWanted = math.min(40, math.max(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], tWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1]))
                    end

                    HaveActionToAssign(refActionMoveToWaterZone, 1, iBPWanted + iBPAlreadyAssigned, iCurWZ, true)
                    iBPAlreadyAssigned = iBPAlreadyAssigned + iBPWanted
                    if bDebugMessages == true then LOG(sFunctionRef..': Tried to send engineers to iCurWZ '..iCurWZ..'; iBPWanted='..iBPWanted..'; iBPAlreadyAssigned='..iBPAlreadyAssigned) end
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    if iHighestTechEngiAvailable == 0 or iBPAlreadyAssigned >= tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 3 then break end
                end
            end

        end
    end

    --High priority reclaim if are low on mass or energy
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we will want to reclaim mass in LZ, bHaveLowMass='..tostring(bHaveLowMass)..'; tLZData[AiBotMap.subrefTotalMassReclaim]='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; tLZData[AiBotMap.subrefTotalSignificantMassReclaim]='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]) end
    if bHaveLowMass and tLZData[AiBotMap.subrefTotalMassReclaim] >= 50 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] > 0 then
        iBPWanted = math.min(40, math.max(5, tLZData[AiBotMap.subrefTotalMassReclaim] / 50))
        if bDebugMessages == true then LOG(sFunctionRef..': High priority reclaim, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; iBPWanted='..iBPWanted) end
        HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
    elseif AiBotConditions.WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will send engi to get tree reclaim') end
        HaveActionToAssign(refActionReclaimArea, 1, 5, {true, nil})
    end

    --TMD (including vs mobile ACUs with TML upgrade)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Considering if we want to get TMD; Priority of this action='..iCurPriority..'; is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))..'; Time since TMD intercepted missile='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] or -10000)) end
    if (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false or (tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] <= 60)) then
        --GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iOptionalLandZone, bReturnTMLCountAsWell, iOptionalCategoryWanted, bGetClosestUnitToOurBase, oOptionalUnitToAvoid)
        local oUnitWantingTMD, iEnemyTMLCount = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone,       true,               nil,                        false)
        if bDebugMessages == true then LOG(sFunctionRef..': Is oUnitWantingTMD valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnitWantingTMD))) end
        if oUnitWantingTMD then
            iBPWanted = 40
            if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 70
            elseif iEnemyTMLCount and iEnemyTMLCount >= 3 then iBPWanted = 60
            end
            if bSaveMassForMML and (iEnemyTMLCount or 0) <= 2 then
                iBPWanted = iBPWanted * 0.5
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build TMD, iBPWanted='..iBPWanted..'; Unit wanting TMD='..oUnitWantingTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitWantingTMD)..'; iEnemyTMLCount='..(iEnemyTMLCount or 'nil')) end
            HaveActionToAssign(refActionBuildTMD, 2, iBPWanted, oUnitWantingTMD)
            --Consider second TMD builder if enemy has lots of TML
            if (iEnemyTMLCount or 0) >= 3 then
                local oSecondUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone, false, categories.TECH3 + categories.EXPERIMENTAL, true)
                if bDebugMessages == true then LOG(sFunctionRef..': oSecondUnitWantingTMD='..(oSecondUnitWantingTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSecondUnitWantingTMD) or 'nil')) end
                if oSecondUnitWantingTMD then
                    HaveActionToAssign(refActionBuildSecondTMD, 2, iBPWanted, oSecondUnitWantingTMD)
                end
            end
        end
    end

    --Approaching enemy guncom - prioritise upgrades if dont have T2, if do have T2 then get T2 PD
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if emergency PD is needed, iApproachingACUThreat='..iApproachingACUThreat) end
    if iApproachingACUThreat > 0 and not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 120 or (not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))
            --Safe zone - ignore ACU if relatively early on and we dont ahve 3+ T2 mexes yet, since presumably we have a friendly base that can defend
            and (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 or GetGameTimeSeconds() >= 480) then

        --Do we have T2 (or a teammate has t3)?
        local bHaveSufficientTech = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then bHaveSufficientTech = true
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then
            local tT2PlusFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tT2PlusFactories) == false then
                for iUnit, oUnit in tT2PlusFactories do
                    if oUnit:GetFractionComplete() >= 1 and oUnit:GetAIBrain().AiBotAI then
                        bHaveSufficientTech = true
                        break
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveSufficientTech='..tostring(bHaveSufficientTech)) end
        if not(bHaveSufficientTech) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4) then
            --Do we have an active factory upgrade?
            local oActiveHQUpgradeToAssist
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                local iHighestCompletion = -1
                for iUpgrade, oUpgrade in tLZTeamData[AiBotMap.subreftoActiveUpgrades] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering active upgrade, oUpgrade='..oUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrade)..'; Fraction complete='..oUpgrade:GetFractionComplete()..'; Unit last subrefsOrderBlueprint='..(oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; oUpgrade.Dead='..tostring(oUpgrade.Dead or false)..'; Is this a factory='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUpgrade.UnitId) or false)) end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUpgrade.UnitId) and not(oUpgrade.Dead) then
                        if oUpgrade:GetWorkProgress() > iHighestCompletion and (iHighestCompletion <= 0 or (oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint]) and EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUpgrade[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefsOrderBlueprint].UnitId)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Updating factory to assist to be oUpgrade='..oUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrade)) end
                            oActiveHQUpgradeToAssist = oUpgrade
                            iHighestCompletion = oUpgrade:GetFractionComplete()
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oActiveHQUpgradeToAssist='..(oActiveHQUpgradeToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oActiveHQUpgradeToAssist) or 'nil')..'; Is subreftoActiveUpgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))) end
            if oActiveHQUpgradeToAssist then
                iBPWanted = 20
                if not(bHaveLowPower) and not(bHaveLowMass) then iBPWanted = 40 end
                HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, oActiveHQUpgradeToAssist)
                if bDebugMessages == true then LOG(sFunctionRef..': We have an active HQ upgrade so will assist this') end
            else
                --We need a priority upgrade, unless it is early game and the ACU is unupgraded and isnt trying to upgrade
                if GetGameTimeSeconds() >= 330/AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryEngineer) >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (oNearestEnemyACU and (oNearestEnemyACU:IsUnitState('Upgrading') or (oNearestEnemyACU[AiBotACU.refiUpgradeCount] or 0) > 0)) then
                    local tExistingT1LandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory * categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tExistingT1LandFactories) == false then
                        --Get factory with lowest fraction complete
                        local oFactoryToUpgrade
                        local iLowestWorkProgress = 1
                        local iLowestLandWorkProgress = 1
                        local oBackupFactory
                        for iFactory, oFactory in tExistingT1LandFactories do
                            if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory:GetFractionComplete() then
                                if (oFactory:GetWorkProgress() or 0) < iLowestLandWorkProgress then
                                    if oFactory:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then
                                        oFactoryToUpgrade = oFactory
                                        iLowestLandWorkProgress = (oFactory:GetWorkProgress() or 0)
                                    elseif oFactory:GetWorkProgress() < iLowestWorkProgress then
                                        oBackupFactory = oFactory
                                        iLowestWorkProgress = (oFactory:GetWorkProgress() or 0)
                                    end
                                end
                            end
                        end
                        if not(oFactoryToUpgrade) then oFactoryToUpgrade = oBackupFactory end
                        if bDebugMessages == true then LOG(sFunctionRef..': Have searched for t1 land factories to upgrade, is oFactoryToUpgrade valid='..tostring(AiBotUnitInfo.IsUnitValid(oFactoryToUpgrade))) end
                        if oFactoryToUpgrade then
                            if bDebugMessages == true then LOG(sFunctionRef..': Doign priority upgrade for oFactoryToUpgrade='..oFactoryToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactoryToUpgrade)..' due to appraoching enemy ACU') end
                            AiBotEconomy.UpgradeUnit(oFactoryToUpgrade, true)
                        end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Wont do priority land fac upgrade just yet as havent built lots of engineers and enemy ACU isnt upgraded') end
                end
            end
        else
            --We have T2 tech (or only need T1 due to enemy not having gun), so want to build PD
            local iRangeThreshold = 30 --typical guncom range
            if oNearestEnemyACU then iRangeThreshold = (oNearestEnemyACU[AiBotUnitInfo.refiDFRange] or 0) end
            if not(bHaveSufficientTech) then iRangeThreshold = 1 end
            --Increase PD threat if enemy is in another zone that has PD in it
            if not(iCurPDThreat) then
                iCurPDThreat = GetPDThreatAboveRangeThresholdAlongPath(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, iRangeThreshold, tNearestEnemyACU)
                local iACUPlateauOrZero, iACULandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tNearestEnemyACU)
                if iACULandZone > 0 and iACUPlateauOrZero == iPlateau and not(iACULandZone == iLandZone) then
                    --ACU is in a different land zone
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iACULandZone]][AiBotMap.subrefLZPath]) == false then
                        for iEntry, iAdjLZ in  tLZData[AiBotMap.subrefLZPathingToOtherLandZones][tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iACULandZone]][AiBotMap.subrefLZPath] do
                            if not(iAdjLZ == iLandZone) then
                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                                    for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                                        if iRange >= iRangeThreshold then
                                            iCurPDThreat = iCurPDThreat + iThreat
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': We have T2 or better or want T1 PD for nongun ACU, iCurPDThreat='..iCurPDThreat..'; iAppraochingACUThreat='..iApproachingACUThreat..'; bHaveSufficientTech='..tostring(bHaveSufficientTech)) end
            if (bHaveSufficientTech or iCurPDThreat == 0) and (iCurPDThreat <= math.max(1200, iApproachingACUThreat * 1.5) or ((aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy]) and iCurPDThreat <= math.max(3200, iApproachingACUThreat * 2.3)) or (iCurPDThreat <= 2400 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 200 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0) and (iApproachingACUThreat >= 1400 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] and iApproachingACUThreat >= 1000)))) then
                --Do we have friendly mobile units iwth decent range in this zone or an adjacent zone? if so then reduce the threat needed
                local iNearbyMobileThreat = 0
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                    for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                        if iRange >= iRangeThreshold then
                            iNearbyMobileThreat = iNearbyMobileThreat + iThreat
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                        if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                            for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                                if iRange >= iRangeThreshold then
                                    iNearbyMobileThreat = iNearbyMobileThreat + iThreat * 0.5
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyMobileThreat='..iNearbyMobileThreat..'; iCurPDThreat='..iCurPDThreat..'; iApproachingACUThreat='..iApproachingACUThreat..'; Dist between ACU and this LZ midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemyACU, tLZData[AiBotMap.subrefMidpoint])) end
                if iNearbyMobileThreat < 200 or iCurPDThreat < iApproachingACUThreat or iCurPDThreat + iNearbyMobileThreat < iApproachingACUThreat * 1.75 or ((aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy]) and iCurPDThreat < iApproachingACUThreat * 2.5) then
                    local iACUThreatFactorWanted = 1.75
                    --below check - ACU doesnt have gun yet and presumably not much veterancy, and we have near-full health T1 and T2 PD
                    if iApproachingACUThreat <= 1150 and iCurPDThreat >= 900 then
                        if (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                            iACUThreatFactorWanted = 0.85 --i.e. if we have some nearby mobile threat (even if not much) will be enough
                        else
                            iACUThreatFactorWanted = 1.2
                        end
                    elseif iCurPDThreat >= 2400 and AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemyACU, tLZData[AiBotMap.subrefMidpoint]) >= 80 then
                        iACUThreatFactorWanted = 1.4
                    end
                    if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then iACUThreatFactorWanted = iACUThreatFactorWanted * 1.5 end
                    if bSaveMassForMML then iACUThreatFactorWanted = iACUThreatFactorWanted * 0.75 end
                    if bDebugMessages == true then LOG(sFunctionRef..': iACUThreatFactorWanted='..iACUThreatFactorWanted..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Lowest mass percent='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; bSaveMassForMML='..tostring(bSaveMassForMML)) end
                    if iCurPDThreat + iNearbyMobileThreat < iApproachingACUThreat * iACUThreatFactorWanted then
                        if not(bSaveMassForMML) or iCurPDThreat == 0 or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then
                            iBPWanted = 40
                            if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 80 end
                            local tTargetBuildLocation
                            local iPDTechLevelWanted = 2
                            if not(bHaveSufficientTech) then iPDTechLevelWanted = 1 end
                            if tNearestEnemyACU then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will get PD position, tNearestEnemyACU='..repru(tNearestEnemyACU)..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                                tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(tNearestEnemyACU, tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, iPDTechLevelWanted)
                            end
                            --Reduce BP wanted if enemy has t2 arti nearby
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then iBPWanted = iBPWanted * 0.5 end
                            HaveActionToAssign(refActionBuildEmergencyPD, iPDTechLevelWanted, iBPWanted, tTargetBuildLocation)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will build emergency PD, iPDTechLevelWanted='..iPDTechLevelWanted) end
                        end
                    end
                end
            end
        end
    end


    --Nearby enemy ground threat and we dont already have at least 2 T2 PD (more in later game scenarios)
    iCurPriority = iCurPriority + 1
    local iEnemyThreat, iEnemyBestRange, oClosestUnit
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if want emergency PD for normal ground threat, tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; iCurPriority='..iCurPriority..'; Norush active='..tostring(AiBotOverseer.bNoRushActive)..'; Time until norush nolonger active='..(GetGameTimeSeconds() - (AiBotOverseer.iNoRushTimer or 0))..'; Have low mass='..tostring(bHaveLowMass)..'; Have low power='..tostring(bHaveLowPower)..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
    if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) and ((tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false) or tLZTeamData[AiBotMap.subrefLZFortify] or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][1] >= 3)) or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and not(bHaveLowPower) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 3000 and not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and (not(bHaveLowMass) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 50 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))))) and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 120 or (not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0)) then
        --Get existing T2 PD threat
        if not(iCurPDThreat) then
            iCurPDThreat = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                    iCurPDThreat = iCurPDThreat + iThreat
                end
            end
        end
        local iMaxPDThreat = 1700
        if iCurPDThreat <= 30000 and not(bSaveMassForMML) then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                iMaxPDThreat = 2800
            end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + 2 * tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount] * 0.75) then
                iMaxPDThreat = iMaxPDThreat * 2
                if tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                    iMaxPDThreat = math.max(10000,iMaxPDThreat)
                end
            end
            if tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then iMaxPDThreat=iMaxPDThreat * 1.5 end
            if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then
                iMaxPDThreat = iMaxPDThreat * 1.5
                if aiBrain[AiBotOverseer.refbPrioritiseDefence] then iMaxPDThreat = iMaxPDThreat * 1.5 end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iCurPDThreat in just this zone='..iCurPDThreat..'; iMaxPDThreat='..iMaxPDThreat..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
            if iCurPDThreat <= iMaxPDThreat and (iCurPDThreat == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] > 1) then
                --Get nearby enemy threat, but only for adjacent LZs
                if not(iEnemyThreat) then
                    iEnemyThreat, iEnemyBestRange = AiBotConditions.GetEnemyMobileCombatThreatAndRangeInCurrentAndAdjacentZones(tLZData, tLZTeamData, iPlateau, iTeam, aiBrain)
                end

                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyThreat='..iEnemyThreat..'; iENemyBestRange='..iEnemyBestRange) end
                if (iEnemyThreat >= 200 or tLZTeamData[AiBotMap.subrefbLZWantsDFSupport] or (not(bHaveLowMass) and not(bHaveLowPower)) or (iEnemyThreat >= 100 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 600) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0)) and (iCurPDThreat < iEnemyThreat * 4 or iCurPDThreat == 0 or (tLZTeamData[AiBotMap.subrefLZFortify] and iCurPDThreat <= 6000) or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iCurPDThreat < math.max(iEnemyThreat * 8, math.min(3000, 800 * tLZTeamData[AiBotMap.subrefMexCountByTech][3])))) then
                    --Are the enemies in an adjacent zone with none in this zone? if so factor in PD in that zone as well
                    local iClosestDist = 100000
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) then
                        local iCurDist
                        oClosestUnit = nil --redundancy
                        for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oClosestUnit = oUnit
                                end
                            end
                        end
                        if oClosestUnit and iClosestDist >= 50 then
                            iCurPDThreat = GetPDThreatAboveRangeThresholdAlongPath(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, 1, oClosestUnit:GetPosition())
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurPDThreat for slightly lower priority='..iCurPDThreat..'; iEnemyThreat='..iEnemyThreat..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])) end
                    if (iCurPDThreat < iEnemyThreat * 5 and ((iEnemyBestRange <= 50 and tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and (iEnemyBestRange <= 50 or iCurPDThreat < iEnemyThreat * 2.5)) or (not(aiBrain[AiBotOverseer.refbPrioritiseDefence]) and iCurPDThreat < iEnemyThreat * 4 and (iEnemyBestRange <= 50 or iCurPDThreat < iEnemyThreat * 2))))
                            or iCurPDThreat == 0 or (tLZTeamData[AiBotMap.subrefLZFortify] and iCurPDThreat <= 1800) or (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and iEnemyThreat >= 1500 and iCurPDThreat < iEnemyThreat * 4 and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] <= 50 and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] <= 50) then
                        --Is this early-game, with a relatively low enemy threat, and do we have nearby combat units that can deal with the enemy?
                        local bWantToGetPD = true

                        if iEnemyThreat <= 600 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 and GetGameTimeSeconds() <= 720 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                            local iNearbyFriendlyMobileThreat = tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    iNearbyFriendlyMobileThreat = iNearbyFriendlyMobileThreat + (tAltLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)
                                end
                            end
                            if iNearbyFriendlyMobileThreat > iEnemyThreat * 1.2 or (bHaveLowMass and iCurPDThreat + iNearbyFriendlyMobileThreat > iEnemyThreat * 2.5) then
                                if not(aiBrain[AiBotOverseer.refbPrioritiseDefence]) or iCurPDThreat + iNearbyFriendlyMobileThreat > iEnemyThreat * 3.5 then
                                    bWantToGetPD = false
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iNearbyFriendlyMobileThreat='..iNearbyFriendlyMobileThreat) end
                        end
                        if bWantToGetPD and bSaveMassForMML and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and iEnemyThreat < math.min(2000, iCurPDThreat * 4) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) and AiBotConditions.GetLifetimeBuildCount(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]], AiBotUnitInfo.refCategoryMML) < 15 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to save mass for MMLs instead of trying to get PD') end
                            bWantToGetPD = false
                        end
                        --Already have significant PD threat (e.g. approx 5 T2 PD) and our PD threat exceeds nearby enemey, and we have some mobile threat, and have low mass - reduce PD to get
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if want to not get after all, iClosestDist='..iClosestDist..'; bHaveLowMass='..tostring(bHaveLowMass)..'; subrefLZThreatAllyMobileDFTotal='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; subrefTThreatEnemyCombatTotal='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; GetHighestOtherTeamT3MexCount='..AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)..'; Our team t3 count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3]) end
                        if bWantToGetPD and iCurPDThreat >= 5000 and iClosestDist > 60 and bHaveLowMass and iCurPDThreat > iEnemyThreat and not(aiBrain[AiBotOverseer.refbPrioritiseDefence]) and iCurPDThreat + tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] > iEnemyThreat * 1.5 and iCurPDThreat > tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 4 then
                            --If are ahead on eco, or we have twice the enemy threat in PD, then dont build more pd
                            if iCurPDThreat >= 2 * iEnemyThreat or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and iCurPDThreat >= 1.5 * iEnemyThreat)
                                    or AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] then
                                if bDebugMessages == true then LOG(sFunctionRef..': We probably have enough T2 PD and have low mass so will hold off getting more PD') end
                                bWantToGetPD = false
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bWantToGetPD='..tostring(bWantToGetPD)..'; iEnemyThreat='..iEnemyThreat..'; Highest tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
                        if bWantToGetPD then
                            iBPWanted = 40
                            if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 80 end
                            local tEnemiesToConsider = {}
                            local oNearestEnemy
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                                        table.insert(tEnemiesToConsider, oUnit)
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tEnemiesToConsider) == false then
                                if not(oNearestEnemy) then oNearestEnemy = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.reftoNearestDFEnemies], tLZData[AiBotMap.subrefMidpoint], true, AiBotMap.refPathingTypeLand) end
                                if oNearestEnemy then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nearest enemy='..oNearestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy)..'; Position='..repru(oNearestEnemy:GetPosition())) end
                                    local iMinTechWanted = 1
                                    if iCurPDThreat > 0 then iMinTechWanted = 2 end
                                    local tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(oNearestEnemy:GetPosition(), tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, iMinTechWanted)
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then iBPWanted = iBPWanted * 0.5 end
                                    HaveActionToAssign(refActionBuildEmergencyPD, iMinTechWanted, iBPWanted, tTargetBuildLocation)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will build emergency PD to stop enemy ground threat, iMinTechWanted='..iMinTechWanted) end
                                end
                            elseif iCurPDThreat == 0 or tLZTeamData[AiBotMap.subrefLZFortify] then
                                local iMinTechWanted = 1
                                if iCurPDThreat > 0 then iMinTechWanted = 2 end
                                local tTargetBuildLocation

                                function GetLocationToTryBuilding(tUnitsToBuildNear, bNeedToBeConstructed, iOptionalMinimumShield)
                                    local iClosestDistToEnemy = 100000
                                    local iCurDist
                                    local oClosestUnit
                                    for iUnit, oUnit in tUnitsToBuildNear do
                                        if (not(bNeedToBeConstructed) or oUnit:GetFractionComplete() == 1) and (not(iOptionalMinimumShield) or (oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() >= 500)) then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                            if iCurDist < iClosestDistToEnemy then
                                                iClosestDistToEnemy = iCurDist
                                                oClosestUnit = oUnit
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Searched for units to b uild near, oClosestUnit='..(oClosestUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit) or 'nil')) end
                                    if oClosestUnit then
                                        local iAngleToEnemyBase = AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                        local tPotentialMoveLocation
                                        local iMaxMoveDist
                                        if iOptionalMinimumShield then iMaxMoveDist = math.min(16, (oClosestUnit:GetBlueprint().Defense.Shield.ShieldSize or 30) * 0.5 - 6)
                                        else iMaxMoveDist = 10
                                        end
                                        if iCurPDThreat > 0 then iMaxMoveDist = iMaxMoveDist - 2 end
                                        if iMaxMoveDist < 4 then iMaxMoveDist = 4 end
                                        for iDistToMove = iMaxMoveDist, 4, -2 do
                                            tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oClosestUnit:GetPosition(), iAngleToEnemyBase, iDistToMove, true, false, AiBotMap.bIsCampaignMap)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will build towards enemy base from potential location, iDistToMove='..iDistToMove..'; iAngleToEnemyBase='..iAngleToEnemyBase..'; Is tPotentialMoveLocation empty='..tostring( AiBotUtilities.IsTableEmpty(tPotentialMoveLocation))) end
                                            if AiBotUtilities.IsTableEmpty(tPotentialMoveLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tPotentialMoveLocation) == tLZData[AiBotMap.subrefLZIslandRef] then
                                                return tPotentialMoveLocation
                                            end
                                        end
                                    end
                                end

                                --First T2 PD - get under fixed shield if have one, or by units to repair if have them for campaign map
                                if iCurPDThreat <= 1700 and tLZTeamData[AiBotMap.subrefLZSValue] >= 200 then
                                    local tFriendlyFixedShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(tFriendlyFixedShields) == false then
                                        --Get the shield nearest the enemy base
                                        tTargetBuildLocation = GetLocationToTryBuilding(tFriendlyFixedShields, true, 500)
                                    end
                                end
                                if not(tTargetBuildLocation) then
                                    if iCurPDThreat <= 2700 and AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]) == false then
                                        tTargetBuildLocation = GetLocationToTryBuilding(tLZData[AiBotMap.subreftoUnitsToRepair])
                                    end
                                    if not(tTargetBuildLocation) then tTargetBuildLocation = tLZData[AiBotMap.subrefMidpoint] end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Getting emergency PD, iMinTechWanted='..iMinTechWanted..'; iBPWanted='..iBPWanted) end
                                HaveActionToAssign(refActionBuildEmergencyPD, iMinTechWanted, iBPWanted, tTargetBuildLocation)
                            end
                        end
                    end
                end
            end
        end
    end

    --High priority T1 radar if we have T2 arti but poor radar coverage
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; AiBotUnitInfo.iT3RadarSize='..AiBotUnitInfo.iT3RadarSize) end
    if (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount]) and (tLZTeamData[AiBotMap.refiRadarCoverage] <= 100 or (AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoBestRadar]) and tLZTeamData[AiBotMap.refoBestRadar]:GetFractionComplete() < 1)) then
        --Do we have T2 arti in this zone, or T2 PD with poor radar, or lots of mexes
        if bDebugMessages == true then LOG(sFunctionRef..': T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Is table of T2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
        if tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false or (tLZTeamData[AiBotMap.refiRadarCoverage] <= 50 and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2PlusPD, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false) then
            local bWantT1DueToRadarUnderConstruction = false
            if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoBestRadar]) and tLZTeamData[AiBotMap.refoBestRadar]:GetFractionComplete() < 1 then
                local tRadarInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                bWantT1DueToRadarUnderConstruction = true
                if AiBotUtilities.IsTableEmpty(tRadarInZone) == false then
                    for iUnit, oUnit in tRadarInZone do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and (oUnit:GetFractionComplete() == 1 or EntityCategoryContains(categories.TECH1, oUnit.UnitId)) then
                            bWantT1DueToRadarUnderConstruction = false
                            break
                        end
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
            --T1 radar
            local bWantT1RadarFirst = false
            if (bWantT1DueToRadarUnderConstruction or tLZTeamData[AiBotMap.refiRadarCoverage] <= 50) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] then
                --Check we dont already have t1 radar in the land zone
                if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT1Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                    iBPWanted = 5
                    if not(bHaveLowMass) then iBPWanted = 15 end
                    bWantT1RadarFirst = true
                    HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted)
                    if bDebugMessages == true then LOG(sFunctionRef..': High priority T1 radar builder, iBPWanted='..iBPWanted) end
                end
            end

            --T2 radar
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want T2 radar, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; bWantT1RadarFirst='..tostring(bWantT1RadarFirst)) end
            if not(bSaveMassForMML) and not(bWantT1RadarFirst) and tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 40 + 60 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 3 + 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                if not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                    --Check we dont already have t2 radar in the land zone
                    if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                        iBPWanted = 20
                        if not(bHaveLowMass) then iBPWanted = 60 end
                        if bDebugMessages == true then LOG(sFunctionRef..': High priority t2 radar builder') end
                        HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                    end
                end
            end
        end
    end

    --More land factories to produce MML to try and beat a firebase
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering more land facs for MML for firebase, bSaveMassForMML='..tostring(bSaveMassForMML)..'; Masss %='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; CurPrioriyt='..iCurPriority) end
    if bSaveMassForMML and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 300 and (ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech] == 2 or (bWantT3LandForRavagers and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech] >= 3)) then
        if bWantMoreFactories and not(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)) then
            iBPWanted = 40
            if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = 10 end
            if bWantT3LandForRavagers then
                HaveActionToAssign(refActionBuildLandFactory, 3, iBPWanted)
            else
                HaveActionToAssign(refActionBuildLandFactory, 2, iBPWanted)
            end
        else
            --Find the closest highest tech land factory
            local oClosestFactory
            local iHighestTech = 2 --no point assisting if we dont ahve a T2 land fac
            if bWantT3LandForRavagers then iHighestTech = 3 end
            local iClosestDistOfHighestTech = 10000
            local tLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                local iCurDist, iCurTech
                for iUnit, oUnit in tLandFactories do
                    if not(oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oUnit[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                        iCurTech = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                        if iCurTech >= iHighestTech then
                            if iCurTech > iHighestTech then
                                iHighestTech = iCurTech
                                iClosestDistOfHighestTech = 100000
                            end
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                            if iCurDist < iClosestDistOfHighestTech then
                                iClosestDistOfHighestTech = iCurDist
                                oClosestFactory = oUnit
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will assist land fac as we want MMLs, oClosestFactory='..(oClosestFactory.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestFactory) or 'nil')) end
            if oClosestFactory then
                iBPWanted = 100
                if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = 20
                elseif bWantT3LandForRavagers and not(bHaveLowMass) then iBPWanted = 300
                end
                HaveActionToAssign(refActionAssistLandFactory, 1, iBPWanted, oClosestFactory)
            elseif not(aiBrain[AiBotOverseer.refbPrioritiseAir]) and not(aiBrain[AiBotOverseer.refbPrioritiseHighTech]) and not(aiBrain[AiBotOverseer.refbPrioritiseDefence]) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and (not(bHaveLowMass) or (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadNothingToBuildForLandFactory] or -100)) >= 10) then
                iBPWanted = 40
                if bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = 10 end
                if bWantT3LandForRavagers then
                    HaveActionToAssign(refActionBuildLandFactory, 3, iBPWanted)
                else
                    HaveActionToAssign(refActionBuildLandFactory, 2, iBPWanted)
                end
            end
        end
    end

    --Precautionary AA if enemy has T3 air and we dont (unless are safe base rushing T3 air ourselves and enemy lacks significant air to ground)
    iCurPriority = iCurPriority + 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 then
        if tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 1000 and (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 500 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 1500 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbRushT3AirInAirSlot])))))  then
            iBPWanted = 20
            if (not(bHaveLowMass) and not(bHaveLowPower)) or (not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 200) then iBPWanted = 60 end
            HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted)
        end
    end

    --Get nearby enemy threat and PD so can assess if want to build PD in priority to T2 arti (in case the T2 arti would try and assist a land fac)
    if (not(iEnemyThreat) or not(iCurPDThreat)) and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 2000 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4) then
        if not(iCurPDThreat) then
            iCurPDThreat = 0
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                    iCurPDThreat = iCurPDThreat + iThreat
                end
            end
        end
        if not(iEnemyThreat) then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                iEnemyThreat, iEnemyBestRange = AiBotConditions.GetEnemyMobileCombatThreatAndRangeInCurrentAndAdjacentZones(tLZData, tLZTeamData, iPlateau, iTeam, aiBrain)
            else
                iEnemyThreat = 0
            end
        end
    end

    --Further T2 PD if we went far enough as to calculate both PD threat and enemy threat in above condition (i.e. this is expansion of above, but we want it to be lower priority than t2 arti)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Lower priority T2 PD builder, iCurPriority='..iCurPriority..'; iCurPDThreat='..(iCurPDThreat or 'nil')..'; iEnemyThreat='..(iEnemyThreat or 'nil')..'; Prioritise defence='..tostring(aiBrain[AiBotOverseer.refbPrioritiseDefence] or false)..'; Is table of nearest DF enemmies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Is table of structure DF by range empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]))..'; refiEnemyMobileDFThreatNearOurSide='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 'nil')..'; refiAllyMobileDFThreatNearOurSide='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] or 'nil')) end
    if iCurPDThreat and iEnemyThreat and (iCurPDThreat < iEnemyThreat or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iCurPDThreat < iEnemyThreat * 1.5)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4) then
        if iCurPDThreat >= 4000 then
            if bDebugMessages == true then LOG(sFunctionRef..': Will first consider getting t2 arti as we have at least 4k in PD threat') end
            --T2 arti if enemy has sniper bots or fatboy, or a firebase that threatens this zone
            GiveOrderForEmergencyT2Arti(HaveActionToAssign, bHaveLowMass, bHaveLowPower, iPlateau, iLandZone, tLZData, tLZTeamData, iTeam)
            iCurPriority = iCurPriority + 1
        end
        if not(oClosestUnit) then
            local iClosestDist = 100000
            local iCurDist
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oClosestUnit = oUnit
                        end
                    end
                end
            end
            if not(oClosestUnit) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                        for iUnit, oUnit in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                if iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oClosestUnit = oUnit
                                end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oClosestUnit='..(oClosestUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit) or 'nil')) end
        if oClosestUnit then
            --If we just consider enemies we have same or better range, do we have enough threat?
            local iOurBestPDRange = 1
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                    if iOurBestPDRange < iRange and iThreat > 0 then iOurBestPDRange = iRange end
                end
            end
            if iOurBestPDRange < 50 then
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                if iHighestTechEngiAvailable >= 2 then iOurBestPDRange = 50
                else iOurBestPDRange = 26 --T1 PD
                end
            end
            local iEnemyThreatThatDoesntOutrangeUs = 0
            local iEnemyThreatThatDoesOutrangeUs = 0
            local iCurZoneThreatThatOutrangesUs
            local iCurZoneThreatThatWeOutrange
            local iCurZoneThreatCap
            function UpdateEnemyThreatsByRange(tCurLZTeamData)
                iCurZoneThreatCap = (tCurLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) + (tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)
                if iCurZoneThreatCap > 0 then
                    iCurZoneThreatThatOutrangesUs = 0
                    iCurZoneThreatThatWeOutrange = 0
                    if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange]) == false then
                        for iRange, iThreat in tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] do
                            if iRange > iOurBestPDRange then
                                iCurZoneThreatThatOutrangesUs = iCurZoneThreatThatOutrangesUs + iThreat
                            else
                                iCurZoneThreatThatWeOutrange = iCurZoneThreatThatWeOutrange + iThreat
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                        for iRange, iThreat in tCurLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                            if iRange > iOurBestPDRange then
                                iCurZoneThreatThatOutrangesUs = iCurZoneThreatThatOutrangesUs + iThreat
                            else
                                iCurZoneThreatThatWeOutrange = iCurZoneThreatThatWeOutrange + iThreat
                            end
                        end
                    end
                    if iCurZoneThreatThatOutrangesUs > iCurZoneThreatCap then
                        if bDebugMessages == true then LOG(sFunctionRef..': Capping total threat for this zone, before cap iCurZoneThreatThatOutrangesUs='..iCurZoneThreatThatOutrangesUs..'; iCurZoneThreatCap='..iCurZoneThreatCap) end
                        iCurZoneThreatThatOutrangesUs = iCurZoneThreatCap
                    end
                    if iCurZoneThreatThatWeOutrange > iCurZoneThreatCap then
                        if bDebugMessages == true then LOG(sFunctionRef..': Capping total threat for this zone, before cap iCurZoneThreatThatWeOutrange='..iCurZoneThreatThatWeOutrange..'; iCurZoneThreatCap='..iCurZoneThreatCap) end
                        iCurZoneThreatThatWeOutrange = iCurZoneThreatCap
                    end
                    iEnemyThreatThatDoesntOutrangeUs = iEnemyThreatThatDoesntOutrangeUs + iCurZoneThreatThatWeOutrange
                    iEnemyThreatThatDoesOutrangeUs = iEnemyThreatThatDoesOutrangeUs + iCurZoneThreatThatOutrangesUs
                end
            end
            UpdateEnemyThreatsByRange(tLZTeamData)
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy threat in iAdjLZ='..iAdjLZ..'; subrefLZThreatEnemyMobileDFByRange='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; subrefLZThreatEnemyMobileIndirectByRange='..repru(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZThreatEnemyMobileIndirectByRange])..'; subrefTThreatEnemyCombatTotal='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]..'; subrefLZThreatAllyMobileDFTotal='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                    UpdateEnemyThreatsByRange(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyThreatThatDoesOutrangeUs='..(iEnemyThreatThatDoesOutrangeUs or 'nil')..'; iEnemyThreatThatDoesntOutrangeUs='..iEnemyThreatThatDoesntOutrangeUs..'; iCurPDThreat='..iCurPDThreat) end
            if (iEnemyThreatThatDoesntOutrangeUs >= 200 or tLZTeamData[AiBotMap.subrefbLZWantsDFSupport] or (not(bHaveLowMass) and not(bHaveLowPower)) or (iEnemyThreatThatDoesntOutrangeUs >= 100 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 600) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))
                    and (iEnemyThreatThatDoesOutrangeUs == 0 or (iEnemyThreatThatDoesOutrangeUs < 8000 and iCurPDThreat < iEnemyThreatThatDoesntOutrangeUs * 2 and (aiBrain[AiBotOverseer.refbPrioritiseDefence] or iCurPDThreat < iEnemyThreatThatDoesntOutrangeUs * 1.5))) then
                iBPWanted = 60
                if not(bHaveLowPower) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then iBPWanted = 100 end
                local tTargetBuildLocation = GetStartSearchPositionForEmergencyPD(oClosestUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint], iPlateau, iLandZone, tLZData, tLZTeamData, 2)
                HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted * 0.5, tTargetBuildLocation)
                if iEnemyThreatThatDoesOutrangeUs <= 1000 then
                    local tSecondBuildLocation = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], oClosestUnit:GetPosition()), 15, true)
                    if not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tSecondBuildLocation) == tLZData[AiBotMap.subrefLZIslandRef]) then tSecondBuildLocation = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]} end
                    HaveActionToAssign(refActionBuildSecondPD, 2, iBPWanted * 0.5, tSecondBuildLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and build some more PD, including second bd builder') end
                elseif bDebugMessages == true then LOG(sFunctionRef..': Will try and build some more emergency PD, but not a second PD at the same time')
                end
            end
        end
    else
        --T2 arti if enemy has sniper bots or fatboy, or a firebase that threatens this zone
        GiveOrderForEmergencyT2Arti(HaveActionToAssign, bHaveLowMass, bHaveLowPower, iPlateau, iLandZone, tLZData, tLZTeamData, iTeam)
    end

    --Preemptive PD on larger maps if we have T3 mex and enemy has large threat, and has enemies in a zone adjacent to an adjacent zone
    iCurPriority = iCurPriority + 1
    --iCurPDThreat - if nil then means not enough of a concern to have calculated it above

    if bDebugMessages == true then LOG(sFunctionRef..': Preemptive PD builder, iCurPDThreat='..(iCurPDThreat or 'nil')..'; Map size='..AiBotMap.iMapSize..'; Enemy mobile DF threat near our side='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Our team total T3 mex count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3]..'; Enemy T3 mex count='..AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)..'; Cond 1 part 1='..tostring(iCurPDThreat and AiBotMap.iMapSize >= 700 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= math.max(4000, iCurPDThreat * 2))..'; Cond 1 part 2='..tostring(not(bHaveLowPower) and (not(bHaveLowMass) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10)..'; Cond 2='..tostring((iCurPDThreat < 4000 or (iCurPDThreat < 3000 + 1000 * tLZTeamData[AiBotMap.subrefMexCountByTech][3] and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] > 2 + AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam))))) end
    --Cond 1 part 1
    if iCurPDThreat and (AiBotMap.iMapSize >= 700 or (AiBotMap.iMapSize >= 500 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 8000)) and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= math.max(4000, iCurPDThreat * 2)
            --Cond 1 part 2
            and not(bHaveLowPower) and (not(bHaveLowMass) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10
            --Cond 2
            and (iCurPDThreat < 4000 or (iCurPDThreat < 3000 + 1000 * tLZTeamData[AiBotMap.subrefMexCountByTech][3] and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] > 2 + AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)))
    then
        local bEnemiesAdjToAdjZone = not(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))
        if not(bEnemiesAdjToAdjZone) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                    bEnemiesAdjToAdjZone = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bEnemiesAdjToAdjZone='..tostring(bEnemiesAdjToAdjZone)) end
        if bEnemiesAdjToAdjZone then
            local tTargetBuildLocation = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), 35, true)
            if not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTargetBuildLocation) == tLZData[AiBotMap.subrefLZIslandRef]) then tTargetBuildLocation = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]} end
            iBPWanted = 20
            if not(bHaveLowMass) then iBPWanted = 40 end
            if bDebugMessages == true then LOG(sFunctionRef..': Will get preemptive PD') end
            HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted, tTargetBuildLocation)
        end
    end

    --High priority mass fab or quantum gateway for maps with few mexes
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Higher priority fab and gateway builder, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; bLowMexMap='..tostring(AiBotMap.bIsLowMexMap)..'; AiBotOverseer.iMassFabRatio='..(AiBotOverseer.iMassFabRatio or 'nil')..'; bWantMorePower='..tostring(bWantMorePower)) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and (AiBotMap.bIsLowMexMap or AiBotOverseer.IsTeamBoomMode(iTeam)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and not(bHaveLowPower) then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 320 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 500 or not(bWantMorePower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbEnemyGettingFabsOrRAS] or (AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryMassFab + AiBotUnitInfo.refCategoryQuantumGateway) <= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetCurrentUnits(AiBotUnitInfo.refCategoryQuantumGateway) == 0)) then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider building mass fab or gateway') end
                ConsiderBuildingMassFabOrGateway(iTeam, iLandZone, tLZTeamData, HaveActionToAssign, bWantMorePower)
            end
        end
    end

    --Assist land factory if we want to focus on getting sniperbots
    iCurPriority = iCurPriority + 1
    if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiOurHighestLandFactoryTech] >= 2 and AiBotConditions.PrioritiseSniperBots(tLZData, iTeam, tLZTeamData, iPlateau, iLandZone) then
        iBPWanted = 90
        if not(bHaveLowMass) then iBPWanted = 180 end
        local oClosestFactory
        local tAeonAndSeraFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory * categories.AEON + AiBotUnitInfo.refCategoryLandFactory * categories.SERAPHIM, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tAeonAndSeraFactories) == false then
            local oClosestFactory = AiBotUtilities.GetNearestUnit(tAeonAndSeraFactories, tLZData[AiBotMap.subrefMidpoint])
            if oClosestFactory then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to assist land factory so we can get more sniperbots') end
                HaveActionToAssign(refActionAssistLandFactory, 1, iBPWanted, oClosestFactory)
            end
        end
    end

    --Extra (second) shielding in a high mass scenario (where dont have experimental level shields) - will only try to shield t3 arti/game ender
    iCurPriority = iCurPriority + 1
    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] or (not(bHaveLowMass) and not(bPrioritiseProduction))) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 500 then

        local iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, true, iLandZone, iPlateau)
        if iBPWanted > 0 then
            iBPWanted = math.min(iBPWanted, 40)
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 1 then iBPWanted = iBPWanted * 0.5 end
            if aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] then
                iBPWanted = iBPWanted * 2
                HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
                if bDebugMessages == true then LOG(sFunctionRef..': Exp shields available so will just build first shield not multiple at once, iBPWanted='..iBPWanted..'; iLandZone='..iLandZone) end
            else
                HaveActionToAssign(refActionBuildSecondShield, iTechLevelWanted, iBPWanted, oUnitToShield)
                if bDebugMessages == true then LOG(sFunctionRef..': Second shield builder, iBPWanted='..iBPWanted..'; iLandZone='..iLandZone) end
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to assign any BP to second shield builder, LZ='..iLandZone) end
        end
    end

    --T2 arti to combat enemy navy if have t3 mexes
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        local iAirSubteam = aiBrain.AiBotAirSubteam
        if bDebugMessages == true then LOG(sFunctionRef..': Considering for P'..iPlateau..'L'..iLandZone..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] or false)..'; Is table of defence water zones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]))..'; Highest factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then
            local iTotalNearbyWaterThreat = 0
            for iEntry, iWaterZone in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones] do
                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) then
                    --How far away is the WZ to us?
                    if AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tLZData[AiBotMap.subrefMidpoint]) <= 170 then
                        iTotalNearbyWaterThreat = iTotalNearbyWaterThreat + math.max(0, (tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) - (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0))
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Checking threat in iWaterZone='..iWaterZone..'; is table of enemy units mpety='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; does this WZ have only hover enemies='..tostring(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies])..'; iTotalNearbyWaterThreat='..iTotalNearbyWaterThreat) end
            end
            if iTotalNearbyWaterThreat >= 1000 then
                local iT2ArtiWanted = math.max(1, math.min(5, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.3 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount], iTotalNearbyWaterThreat / 2000))
                local iT2ArtiCount = 0
                local tCurT2Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tCurT2Arti) == false then
                    for iUnit, oUnit in tCurT2Arti do
                        if oUnit:GetFractionComplete() == 1 then
                            iT2ArtiCount = iT2ArtiCount + 1
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iT2ArtiCount='..iT2ArtiCount..'; iT2ArtiWanted='..iT2ArtiWanted) end
                if iT2ArtiCount < iT2ArtiWanted then
                    iBPWanted = 50
                    if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 120 end

                    local tLocationToBuild
                    if iT2ArtiCount >= 3 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                        tLocationToBuild = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), 20, true, false)
                        if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLocationToBuild) == iPlateau) then
                            tLocationToBuild = {tLZData[AiBotMap.subrefMidpoint][1]. tLZData[AiBotMap.subrefMidpoint][2]. tLZData[AiBotMap.subrefMidpoint][3]}
                        end
                    else
                        tLocationToBuild = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Getting T2 arti to deal with enemy navy') end
                    HaveActionToAssign(refActionBuildEmergencyArti, 2, iBPWanted, tLocationToBuild)
                end
            end
        end
    end

    --Assign engineers to experimental eg in case original constructing engineers died
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        local oExperimentalToAssist = GetPartCompleteBuildingInZone(iTeam, iPlateau, iLandZone, AiBotUnitInfo.refCategoryExperimentalLevel - categories.NAVAL, false)
        if oExperimentalToAssist then
            iBPWanted = 30
            if oExperimentalToAssist:GetFractionComplete() >= 0.6 then
                iBPWanted = 120
                if not(bHaveLowPower) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then iBPWanted = math.max(iBPWanted, math.min(240, math.max(iBPWanted, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 12))) end
            elseif not(bHaveLowPower) then
                iBPWanted = 60
                if not(bHaveLowMass) then iBPWanted = 120 end
            end
            HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oExperimentalToAssist)
        end
    end

    --Second power builder to help scale power late game if high on mass, or earlier on if getting lots of mass and low power and already have a number of pgens of current tech
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Second power builder check, bWantMorePower='..tostring(bWantMorePower)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bSaveMassForMML='..tostring(bSaveMassForMML)..'; bPrioritiseProduction='..tostring(bPrioritiseProduction)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 'nil')..'; refiHighestBrainBuildMultiplier='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]) end
    if bWantMorePower and (not(bHaveLowMass) or (bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) and not(bSaveMassForMML) and (not(bPrioritiseProduction) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.15)) and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 0) >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 1) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 0.5 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 1) * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] > 32 * math.max(aiBrain[AiBotEconomy.refiBrainResourceMultiplier], aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]))) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 40 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 1) * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) * 1.25 or bHaveLowPower) then
        iBPWanted = tiBPByTech[(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 1)] * 10
        --reduce BP wanted if dont have massive amount of mass
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 5000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 25 then iBPWanted = iBPWanted * 0.6 end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 500 then
            iBPWanted = iBPWanted * 0.5 --i.e. want to have construction started so primary power builder can build sooner but not as worried about building this really fast
        end
        --If havent built 2 Pgen of this tech level yet then wait
        local bNotBuiltEnoughPowerYet = false
        local oPowerToAssistInstead
        local iClosestToCompletion = 0
        local iTechToUse = (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 1)
        --Be more likely to start 2nd pgen if only recently got to T2 and have high mass and low power
        if iTechToUse == 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[2]) then
            --Do we have T2 engi completed in this zone?
            local iConstructedT2EngiOrPgen = AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)
            if iConstructedT2EngiOrPgen == 0 then
                local tT2PgenInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower * categories.TECH2, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tT2PgenInZone) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Although we have T2 tech on our team, we have no t2 engis in this zone, and no t2 pgen (part complete or completed) in this zone, so will act as though we have t1 when deciding what to build') end
                    iTechToUse = 1
                end
            end
        end
        if iTechToUse == 1 then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] then
                bNotBuiltEnoughPowerYet = true
                local tFriendlyPowerOfTechWanted = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFriendlyPowerOfTechWanted) == false and table.getn(tFriendlyPowerOfTechWanted) >= 9 then
                    --T1 pgens - want to ignore if dont have lots already, and dont want to bother about assisting an existing onea s they should compelte relatively quickly with normal pgen builders
                    bNotBuiltEnoughPowerYet = false
                end
            end
        elseif iTechToUse >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 350 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
            local tFriendlyPowerOfTechWanted = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower * AiBotUnitInfo.ConvertTechLevelToCategory(math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], 3)), tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            bNotBuiltEnoughPowerYet = true
            if AiBotUtilities.IsTableEmpty(tFriendlyPowerOfTechWanted) == false then
                local iConstructedPower = 0
                for iUnit, oUnit in tFriendlyPowerOfTechWanted do
                    if oUnit:GetFractionComplete() == 1 then
                        iConstructedPower = iConstructedPower + 1
                        if iConstructedPower >= 2 then
                            bNotBuiltEnoughPowerYet = false
                            oPowerToAssistInstead = nil
                            break
                        end
                    elseif oUnit:GetFractionComplete() > iClosestToCompletion then
                        oPowerToAssistInstead = oUnit
                        iClosestToCompletion = oUnit:GetFractionComplete()
                    end
                end
            end
        end

        if bNotBuiltEnoughPowerYet then
            if bDebugMessages == true then LOG(sFunctionRef..': Normally would want to start second power builder but we havent built first yet so will focus on completing that, iClosestToCompletion='..iClosestToCompletion..'; oPowerToAssistInstead='..(oPowerToAssistInstead.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPowerToAssistInstead) or 'nil')) end
            if oPowerToAssistInstead then
                HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oPowerToAssistInstead)
            end
        else
            HaveActionToAssign(refActionBuildSecondPower, iTechToUse, iBPWanted)
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build second power due to lots of mass and having recently needed more energy for air production') end
        end
    end

    --Assist mex and air fac upgrades if in a safe zone or high resource modifier or have good amount of mass and number of units of that tech built; also assist mex more generally if have already have at least 1 mex of the same tech level and no enemies in an adjacent zone
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Priority mex or air fac assist, iCurPriority='..iCurPriority..'; is table of active upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; Is base in safe position='..tostring(tLZTeamData[AiBotMap.refbBaseInSafePosition])..'; Enemies in adj zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Mex count: T1='..tLZTeamData[AiBotMap.subrefMexCountByTech][1]..'; T2='..tLZTeamData[AiBotMap.subrefMexCountByTech][2]..'; T3='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and (tLZTeamData[AiBotMap.refbBaseInSafePosition] or tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0) then
        -- or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 and (tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0)  and not(AiBotOverseer.bUnitRestrictionsArePresent)
        --Decide if we want to assist an air factory, or instead assist a mex upgrade
        local oFactoryOrMexToAssist
        local tUpgradingHQs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAllHQFactories, tLZTeamData[AiBotMap.subreftoActiveUpgrades])
        if AiBotUtilities.IsTableEmpty(tUpgradingHQs) == false and not(aiBrain[AiBotOverseer.refbPrioritiseLowTech]) then
            local oHighestHQToConsiderAssisting
            local iHighestHQTechLevel = 0
            local iBestCompletionOfCurrentTechLevel
            local iCurTechLevel
            for iFactory, oFactory in tUpgradingHQs do
                iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oFactory)
                if iCurTechLevel > iHighestHQTechLevel then
                    iHighestHQTechLevel = iCurTechLevel
                    iBestCompletionOfCurrentTechLevel = oFactory:GetWorkProgress()
                    oHighestHQToConsiderAssisting = oFactory
                elseif iCurTechLevel == iHighestHQTechLevel then
                    if oFactory:GetWorkProgress() > iBestCompletionOfCurrentTechLevel then
                        iBestCompletionOfCurrentTechLevel = oFactory:GetWorkProgress()
                        oHighestHQToConsiderAssisting = oFactory
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oHighestHQToConsiderAssisting='..(oHighestHQToConsiderAssisting.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oHighestHQToConsiderAssisting) or 'nil')..'; iBestCompletionOfCurrentTechLevel='..iBestCompletionOfCurrentTechLevel..'; iHighestHQTechLevel='..iHighestHQTechLevel) end
            if oHighestHQToConsiderAssisting then
                --Do we want to assist this rather than a mex?
                if not(bHaveLowMass) then
                    oFactoryOrMexToAssist = oHighestHQToConsiderAssisting
                elseif bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oHighestHQToConsiderAssisting.UnitId) and iBestCompletionOfCurrentTechLevel < 0.6 then
                    --Dont assist anything
                else
                    --Tech 1 requirement to assist to get t2 sooner - want 35 mass income per sec before considering assisting
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oHighestHQToConsiderAssisting.UnitId) then
                        if AiBotConditions.HaveEnoughGrossEcoToSupportLandHQUpgrade(aiBrain) then
                            oFactoryOrMexToAssist = oHighestHQToConsiderAssisting
                        end
                    elseif EntityCategoryContains(categories.TECH1, oHighestHQToConsiderAssisting.UnitId) then
                        if AiBotConditions.HaveEnoughGrossEcoToSupportLandHQUpgrade(aiBrain, 1) then
                            oFactoryOrMexToAssist = oHighestHQToConsiderAssisting
                        end
                    else --T2 air
                        local iGrossMassAdjust = 0
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iGrossMassAdjust = 1 end
                        if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] /  aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 6 + iGrossMassAdjust then
                            oFactoryOrMexToAssist = oHighestHQToConsiderAssisting
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oFactoryOrMexToAssist after checking for upgrading HQs that we have enough gross income to support='..(oFactoryOrMexToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryOrMexToAssist) or 'nil')) end
        if not(oFactoryOrMexToAssist) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 or not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 1.3) then
            local tUpgradingMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subreftoActiveUpgrades])
            if bDebugMessages == true then LOG(sFunctionRef..': is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tUpgradingMexes))) end
            if AiBotUtilities.IsTableEmpty(tUpgradingMexes) == false then
                local iCurValue = 0
                local iCurTech
                local iBestValue = 0
                for iUpgradingUnit, oUpgradingUnit in tUpgradingMexes do
                    iCurTech = AiBotUnitInfo.GetUnitTechLevel(oUpgradingUnit)
                    if iCurTech == 1 then iCurValue = 1 + oUpgradingUnit:GetFractionComplete()
                    else iCurValue = oUpgradingUnit:GetFractionComplete()
                    end
                    if iCurValue > iBestValue then
                        oFactoryOrMexToAssist = oUpgradingUnit
                        iBestValue = iCurValue
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': oMex that want to assist='..(oFactoryOrMexToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryOrMexToAssist) or 'nil')) end
            end
        end
        --safe zones - consider assisting an air HQ upgrade
        if not(oFactoryOrMexToAssist) and tLZTeamData[AiBotMap.refbBaseInSafePosition] then
            local tUpgradingAirFac = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoActiveUpgrades])
            if AiBotUtilities.IsTableEmpty(tUpgradingAirFac) == false then
                for iUpgradingUnit, oUpgradingUnit in tUpgradingAirFac do
                    if AiBotUnitInfo.GetUnitTechLevel(oUpgradingUnit) >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] then
                        oFactoryOrMexToAssist = oUpgradingUnit
                        if bDebugMessages == true then LOG(sFunctionRef..': will assist upgrading air fac='..oFactoryOrMexToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactoryOrMexToAssist)) end
                        break
                    end
                end
            end
        end
        if oFactoryOrMexToAssist then
            if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oFactoryOrMexToAssist.UnitId) then
                local iCountAdjust = 0
                if tLZTeamData[AiBotMap.refbBaseInSafePosition] then iCountAdjust = 1 end
                iBPWanted = math.max(5, 5 * math.max(0, tLZTeamData[AiBotMap.subrefMexCountByTech][2] + iCountAdjust) + 10 * math.max(0, tLZTeamData[AiBotMap.subrefMexCountByTech][3] + iCountAdjust))
                if aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 1.3 then iBPWanted = iBPWanted + math.max(5, iBPWanted * 0.1, math.min(4, iBPWanted * 0.7, (aiBrain[AiBotEconomy.refiBrainResourceMultiplier] - 1.2)*10) * 5) * aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] end
                if bHaveLowPower then iBPWanted = iBPWanted * 0.5 end
            else
                iBPWanted = 20 * AiBotUnitInfo.GetUnitTechLevel(oFactoryOrMexToAssist)
                local bStallingResources = false
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then
                    iBPWanted = iBPWanted * 0.5
                    bStallingResources = true
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                    iBPWanted = iBPWanted * 0.5
                    bStallingResources = true
                end
                if not(bStallingResources) then
                    if not(bHaveLowMass) then iBPWanted = iBPWanted * 2 end
                    if not(bHaveLowPower) then iBPWanted = iBPWanted * 2 end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Priority mex or fac upgrade assistance, iBPWanted='..iBPWanted) end
            HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, oFactoryOrMexToAssist)
        end
    end

    --More factories if have some mass stored and enemy is still at T1
    iCurPriority = iCurPriority + 1
    if bWantMoreFactories and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 300) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] == 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] <= math.min(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] <= 1 and (iFactoriesInLZ == 0 or not(bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
        iBPWanted = 20
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
            HaveActionToAssign(refActionBuildAirFactory, 1, iBPWanted)
        else
            HaveActionToAssign(refActionBuildLandFactory, 1, iBPWanted)
        end
    end


    --Preemptive fixed AA if we have T2+ air fac and no fixed T2+ ground AA and dont have much MAA threat here either
    --Also includes T3 SAM preemptive builder in greater numbers if we lack air control and have at least 10 mass per tick and not low mass
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want fixed AA due to haveing T2+ air, iCurPriority='..iCurPriority..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Assassination or similar='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar])) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 24000 and (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 3000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 600)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 800 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] - 1)) then
        --Does enemy have air to ground threat that exceeds our AA threat in this zone, and/or do we have at least 2 T3 mexes in this zone and not have low mass?
        local iThreatRatioWanted = 1
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] then iThreatRatioWanted = iThreatRatioWanted + 0.5
        end
        if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] then
            iThreatRatioWanted = iThreatRatioWanted * 0.4
        elseif AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] then
            iThreatRatioWanted = iThreatRatioWanted + 0.5
        end
        if bHaveLowMass then
            iThreatRatioWanted = iThreatRatioWanted - 0.1
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iThreatRatioWanted = iThreatRatioWanted * 0.5 end
        end
        if bHaveLowPower then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iThreatRatioWanted = iThreatRatioWanted * 0.5
            else iThreatRatioWanted = iThreatRatioWanted * 0.8
            end
        end
        if iNearbyEnemyAirToGroundThreat >= 2500 then iThreatRatioWanted = iThreatRatioWanted + 0.2 end
        local iCurrentThreatRatio
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 0) > 0 then
            iCurrentThreatRatio = tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]
        else
            iCurrentThreatRatio = 1000
        end
        if bDebugMessages == true then LOG(sFunctionRef..': enemy air to ground threat='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 0)..'; Ally groundAA in this zone='..(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Mex count by tech='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; iThreatRatioWanted='..iThreatRatioWanted) end

        if iCurrentThreatRatio < iThreatRatioWanted or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 800 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] - 1) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) or (not(bHaveLowMass) and not(bHaveLowPower) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(3, tLZData[AiBotMap.subrefLZOrWZMexCount] * 0.5) or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= math.max(700, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] or 0) * 1.2)))))) then
            --Do we already have fixed AA in this LZ?
            local iAACategory = AiBotUnitInfo.refCategoryStructureAA - categories.TECH1
            if AiBotTeam.subrefiHighestFriendlyFactoryTech >= 3 then iAACategory = iAACategory * categories.TECH3 end
            local tExistingFixedAA = EntityCategoryFilterDown(iAACategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local bHaveFixedAA = false
            if AiBotUtilities.IsTableEmpty(tExistingFixedAA) == false then
                for iUnit, oUnit in tExistingFixedAA do
                    if oUnit:GetFractionComplete() then bHaveFixedAA = true break end
                end
            end
            iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
            if iCurrentThreatRatio < iThreatRatioWanted then iBPWanted = iBPWanted * (0.5 + 3 * (iThreatRatioWanted - iCurrentThreatRatio) / iThreatRatioWanted) end
            if not(bHaveFixedAA) then iBPWanted = iBPWanted * 1.5 end
            if not(bHaveLowPower) then
                if not(bHaveLowMass) then iBPWanted = iBPWanted * 3
                else iBPWanted = iBPWanted * 1.5
                end
            end
            local iApproachingAirThreat = AiBotConditions.GetNearbyEnemyAirToGroundThreat(tLZData, tLZTeamData, iTeam, 200)
            if bDebugMessages == true then LOG(sFunctionRef..': bHaveFixedAA='..tostring(bHaveFixedAA)..'; iBPWanted='..iBPWanted..'; iCurrentThreatRatio='..iCurrentThreatRatio..'; iThreatRatioWanted='..iThreatRatioWanted..'; iApproachingAirThreat='..iApproachingAirThreat) end

            if not(bHaveFixedAA)
                    or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) == 0
                    or (iApproachingAirThreat > 0 and (iApproachingAirThreat > 2500 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 300 or iApproachingAirThreat * 4 > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]))
                    or iCurrentThreatRatio * 2 < iThreatRatioWanted
                    or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))
                    or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and iCurrentThreatRatio * 1.5 < iThreatRatioWanted) then
                HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': preemptive AA builder, iBPWanted='..iBPWanted) end
            end
        end
    end

    --Similar to above but for third power with slightly greater mass threshold, and only for very high mass and energy incomes, and only if have stalled for power in last 60s
    iCurPriority = iCurPriority + 1
    if bWantMorePower and not(bHaveLowMass) and not(bSaveMassForMML) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 8000 and (not(bPrioritiseProduction) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 60 and (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0) <= 60 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) * 1.1) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 0) >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) * 1.25 then
        iBPWanted = 325 --10 T3 engis
        --reduce BP wanted if dont have massive amount of mass
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] <= 15000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 80 then iBPWanted = 150 end
        HaveActionToAssign(refActionBuildThirdPower, 3, iBPWanted)
        if bDebugMessages == true then LOG(sFunctionRef..': Want to build second power due to lots of mass and having recently needed more energy for air production') end
    end

    --High priority factories
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build a factory, bWantMoreFactories='..tostring(bWantMoreFactories)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Mass % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Highest tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; subrefbTeamIsStallingMass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl])..'; refbBaseInSafePosition='..tostring(tLZTeamData[AiBotMap.refbBaseInSafePosition])) end
    if bWantMoreFactories and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 11 and
            (not(bHaveLowMass) or (tLZTeamData[AiBotMap.refbBaseInSafePosition] and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 and not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and GetGameTimeSeconds() <= 600 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05) or (AiBotMap.iMapSize <= 256 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 150 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0)))) and (iFactoriesInLZ == 0 or not(bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) then
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 0) > 0 then
            if bHaveLowMass then iBPWanted =  tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2
            else iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 4
            end
        else
            iBPWanted = 5
        end

        local bWantAirNotLand = AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)
        local iFactoryAction
        if bWantAirNotLand then iFactoryAction = refActionBuildAirFactory
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build land factory not air factory2') end
            iFactoryAction = refActionBuildLandFactory
        end

        local tFactoriesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFactoriesInZone) == false then
            for iUnit, oUnit in tFactoriesInZone do
                if oUnit:GetFractionComplete() < 1 and not(oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded')) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a factory under construction in this zone already, unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnit.UnitId) then iFactoryAction = refActionBuildAirFactory
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then iFactoryAction = refActionBuildLandFactory
                    end
                end
            end
        end

        if bHaveLowPower and bWantAirNotLand then iBPWanted = iBPWanted * 0.5 end
        if bDebugMessages == true then LOG(sFunctionRef..': Wnat to build a factory, iBPWanted='..iBPWanted..'; iFactoryAction='..iFactoryAction..'; bWantAirNotLand='..tostring(bWantAirNotLand)) end
        HaveActionToAssign(iFactoryAction, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted, nil)
    end


    --High priority islands (early-game expansion)
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS)
    iCurPriority = iCurPriority + 1
    local iBPAlreadyTraveling = 0
    GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': Core LZ considering engis for islands, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Time='..GetGameTimeSeconds()) end
    if iHighestTechEngiAvailable > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of pathing to other islands empty='..tostring(tLZData[AiBotMap.subrefLZPathingToOtherIslands])) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
            local iDistanceThreshold = math.max(125, AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 0.502)
            if bDebugMessages == true then LOG(sFunctionRef..': iDistanceThreshold='..iDistanceThreshold) end

            for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; Travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; tPathingData[AiBotMap.subrefIslandClosestLZRef]='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; Are there enemies in this or adjacnet LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                if tPathingData[AiBotMap.subrefIslandTravelDist] > iDistanceThreshold then break
                else
                    --Are there enemies in the target LZ?
                    local tIslandLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]]
                    if tPathingData[AiBotMap.subrefIslandClosestLZRef] and AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 then
                        local iEnemyThreatNearby = 0
                        if tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                            if AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tIslandLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    iEnemyThreatNearby = iEnemyThreatNearby + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..'; iEnemyThreatNearby='..iEnemyThreatNearby) end
                        if iEnemyThreatNearby <= 10 then
                            --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                            local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false, true, false, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                            if tiBPByTechWanted then
                                --Is it either a minor zone, or a core zone that either wants lots of BP or doesnt have any engineers traveling to it?
                                for iTech = 1, iHighestTechEngiAvailable, 1 do
                                    if tiBPByTechWanted[iTech] > 0 then
                                        iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                        iBPWanted = iBPAlreadyTraveling + 5
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and assign an engineer to go to tPathingData[AiBotMap.subrefIslandClosestLZRef]='..tPathingData[AiBotMap.subrefIslandClosestLZRef]..'; BP wanted='..iBPWanted..'; iTech='..iTech..'; iPrevEngisAvailable='..iPrevEngisAvailable) end
                                        HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, tPathingData[AiBotMap.subrefIslandClosestLZRef], true)
                                        if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                            iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                            iBPAlreadyTraveling = iBPAlreadyTraveling + tiBPByTech[iTech]
                                        end

                                        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                        if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable after this='..iHighestTechEngiAvailable) end
                                        if iHighestTechEngiAvailable == 0 then break end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --TML if enemy has vulnerable units
    iCurPriority = iCurPriority + 1
    if iHighestTechEngiAvailable >= 2 and not(bHaveLowPower) then
        iBPWanted = GetBPToAssignToBuildingTML(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, bHaveLowMass)
        if iBPWanted > 0 then
            HaveActionToAssign(refActionBuildTML, 2, iBPWanted)
        end
    end

    --High priority T2 radar if we have sniperbots or fatboy
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': SNiperbot t2 radar builder, tLZTeamData[AiBotMap.refiRadarCoverage] ='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; T2+T3 mexes='..tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Gross E='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) end
    if tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] or 0) >= 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(2, tLZData[AiBotMap.subrefLZOrWZMexCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]  and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
        local bHaveAnySnipersOrFatboy = false
        local iCurSniperBots = 0
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFatboy) > 0 then
                bHaveAnySnipersOrFatboy = true
                break
            else
                iCurSniperBots = iCurSniperBots + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySniperBot)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; Cur sniperbots cumulative='..iCurSniperBots..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]) end
                if iCurSniperBots >= 3 then
                    bHaveAnySnipersOrFatboy = true
                    break
                elseif iCurSniperBots > 0 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 500 then
                    bHaveAnySnipersOrFatboy = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveAnySnipersOrFatboy='..tostring(bHaveAnySnipersOrFatboy)) end
        if bHaveAnySnipersOrFatboy then
            if bDebugMessages == true then LOG(sFunctionRef..': Do we have T2 radar in zone already? Is table empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                iBPWanted = 15
                if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 40 end
                HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and build t2 radar') end
            end
        end
    end

    --High priority omni if we have fatboy or sniperbots, or priority nukes to scout
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef..': Priority T3 radar for fatboy and sniperbots,  tLZTeamData[AiBotMap.refiRadarCoverage]='.. tLZTeamData[AiBotMap.refiRadarCoverage]..'; Exp cosntructed count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Team has omni vision='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision])..'; Team is stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Team gross E='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit]='..tostring(aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit] or false)..'; Brain gross E='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Team grossE='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Brain nickname='..aiBrain.Nickname..'; Is tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])))
        if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoBestRadar]) then LOG(sFunctionRef..': tLZTeamData[AiBotMap.refoBestRadar] is owned by '..tLZTeamData[AiBotMap.refoBestRadar]:GetAIBrain().Nickname..' with % complete='..tLZTeamData[AiBotMap.refoBestRadar]:GetFractionComplete())
        else LOG(sFunctionRef..': tLZTeamData[AiBotMap.refoBestRadar] is not valid')
        end
    end
    if (tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT2RadarSize and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) and
            (((AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 900)) and
                    ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(2, tLZData[AiBotMap.subrefLZOrWZMexCount]) and (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 10)) or
                            (aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit] and (AiBotMap.iMapSize >= 500 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 700)) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 300 and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 900 or not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1500))))

                    or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 600 and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategorySML,AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout])) == false)) then

        --We have built at least 1 exp, and lack omni coverage, and have enough powe that we could probably support an omni
        local bHaveFatboyOrSnipers = false
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            if oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFatboy) > 0 then
                bHaveFatboyOrSnipers = true
                break
            elseif oBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySniperBot) >= 3 then
                bHaveFatboyOrSnipers = true
                break
            elseif aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit] then
                local toExistingLandExp = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandExperimental, false, true)
                if AiBotUtilities.IsTableEmpty(toExistingLandExp) == false then
                    for iExp, oExp in toExistingLandExp do
                        if (oExp[AiBotUnitInfo.refiDFRange] or 0) >= 80 then
                            bHaveFatboyOrSnipers = true
                            break
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveFatboyOrSnipers='..tostring(bHaveFatboyOrSnipers)) end
        if bHaveFatboyOrSnipers or (AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategorySML,AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout])) == false) then
            --T2 radar
            local bBuildingT2 = false
            iCurPriority = iCurPriority + 1
            if bDebugMessages == true then LOG(sFunctionRef..': High priority Considering if want T2 radar, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
            if tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize then
                --Check we dont already have t2 radar in the land zone
                if not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                    if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                        iBPWanted = 20
                        if not(bHaveLowMass) then iBPWanted = 60 end
                        HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                        bBuildingT2 = true
                    end
                end
            end

            --T3 radar
            iCurPriority = iCurPriority + 1
            if bDebugMessages == true then LOG(sFunctionRef..': High priority Considering whether to build T3 radar, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Closest enemy base dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit]='..tostring(aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit])..'; Omni under construction elsewhere='..AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZTeamData, iTeam, AiBotUnitInfo.refCategoryT3Radar)) end
            if not(bSaveMassForMML) and tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT2RadarSize then
                --Require T3 mexes before building T3 radar unless we have a fatboy and no T3 radar under construction elsewhere
                if tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0) or (aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit] and AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZTeamData, iTeam, AiBotUnitInfo.refCategoryT3Radar) == 0) then
                    if AiBotUnitInfo.iT3RadarSize - AiBotUnitInfo.iT2RadarSize >= 100 or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryT3Radar) == 0 then
                        iBPWanted = 30
                        if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 100 end
                        if bBuildingT2 then iBPWanted = 5 end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will build T3 radar, iBPWanted='..iBPWanted..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
                        HaveActionToAssign(refActionBuildT3Radar, 3, iBPWanted)
                    end
                end
            end
        end
    end
    if AiBotUnitInfo.IsUnitValid(tLZTeamData[AiBotMap.refoBestRadar]) and tLZTeamData[AiBotMap.refoBestRadar]:GetFractionComplete() < 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
        iBPWanted = tiBPByTech[AiBotUnitInfo.GetUnitTechLevel(tLZTeamData[AiBotMap.refoBestRadar])]
        if not(bHaveLowPower) then
            iBPWanted = iBPWanted * 2
        else
            iBPWanted = 30
        end
        if bHaveLowMass and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.5 end
        if not(aiBrain[AiBotOverseer.refbBuiltLongRangeLandUnit]) then iBPWanted = iBPWanted * 0.5 end
        HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, tLZTeamData[AiBotMap.refoBestRadar])
    end

    --Focus on building our own experimental if we have one already under construction and enemy has any non fatboy experimentals, and we have at least 1 T3 mex
    iCurPriority = iCurPriority + 1
    if (not(bHaveLowPower) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])) == false and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 7000) then
        local iHighestCompleteExperimentalInZone = 0
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tExperimentalsUnderConstruction = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tExperimentalsUnderConstruction) == false then
                for iCurEntry = table.getn(tExperimentalsUnderConstruction), 1, -1 do
                    local oUnit = tExperimentalsUnderConstruction[iCurEntry]
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering exp under construction='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' with fraction complete='..oUnit:GetFractionComplete()) end
                        if oUnit:GetFractionComplete() == 1 then
                            table.remove(tExperimentalsUnderConstruction, iCurEntry)
                        else
                            iHighestCompleteExperimentalInZone = math.max(iHighestCompleteExperimentalInZone, oUnit:GetFractionComplete())
                        end
                    else
                        table.remove(tExperimentalsUnderConstruction, iCurEntry)
                    end
                end
            end

        end
        if bDebugMessages == true then LOG(sFunctionRef..': iHighestCompleteExperimentalInZone='..iHighestCompleteExperimentalInZone..' in zone '..iLandZone) end
        if iHighestCompleteExperimentalInZone > 0 then
            --As a very rough guide, every 1 build power on a GC will use roughly 0.5 mass per sec; so if want 50% of entire team eco on this experimental, then want to assign
            if bHaveLowMass and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] < 1000 then
                iBPWanted = math.min(500, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 8 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 25)
            else
                iBPWanted = math.min(500, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 14 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] / 25)
            end
            if bHaveLowPower then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] then
                    iBPWanted = math.min(90, iBPWanted * 0.4)
                else
                    iBPWanted = math.min(120, iBPWanted * 0.5)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': BP want to assist under construction experimental='..iBPWanted) end
            --Assist the experimental
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 1, iBPWanted)
            --HaveActionToAssign(refActionBuildExperimental, 1, iBPWanted)
        end
    end

    --Assist air fac if at T2+ and want more factories
    iCurPriority = iCurPriority + 1
    if not(bWantMorePower) and (not(bHaveLowMass) or bWantMoreFactories) and not(bSaveMassForMML) then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAllAir - categories.TECH1) <= 5) then
            --Check we have more power than when we last were unable to build air units
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] > (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnergyWhenAirFactoryLastUnableToBuildAir] or 0) * 1.25 then
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tT2PlusAirFacsInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory * AiBotUnitInfo.ConvertTechLevelToCategory(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]), tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(   tT2PlusAirFacsInLZ) == false and (not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                        if bHaveLowMass then iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 1.5
                        else
                            iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 4
                            if not(bWantMorePower) then iBPWanted = iBPWanted * 2 end
                        end
                        local oAirFactoryToAssist
                        local iHighestAirFac = 0
                        local iCurTechLevel
                        for iFactory, oFactory in tT2PlusAirFacsInLZ do
                            if not(oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                                iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oFactory)
                                if iCurTechLevel > iHighestAirFac then
                                    iHighestAirFac = iCurTechLevel
                                    oAirFactoryToAssist = oFactory
                                end
                            end
                        end
                        if oAirFactoryToAssist then
                            HaveActionToAssign(refActionAssistAirFactory, 1, iBPWanted, oAirFactoryToAssist)
                        end
                    end
                end
            end
        end
    end

    --Energy storage once have eco to support it
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Considering building energy storage, Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; Have low power='..tostring(bHaveLowPower)..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]..'; Enemy unit with highest health='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyHighestMobileLandHealth]) end
    if (not(bHaveLowPower) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 300)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] <= 7 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] * 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] * 20 and (((AiBotMap.bIsCampaignMap or (GetGameTimeSeconds() >= 600 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] == 0)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1 + 0.25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + 0.25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount]))
            and (GetGameTimeSeconds() >= 360 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3 or (not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2) or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10) then
        --Do we have enough storage to 1-shot any enemy unit? and/or if we have constructed 2+ experimentals then want at least 3 energy storage (e.g. helps if we have t3 arti)
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] < math.max(1, math.ceil((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyHighestMobileLandHealth] / 0.9 - 1000) / (0.25 * AiBotBuilding.iEnergyStorageExpectedCapacity))) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2) then
            --Is the number of storage in this LZ <= lowest storage count?
            local toStorageInThisLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local iStorageInThisLZ
            if AiBotUtilities.IsTableEmpty(toStorageInThisLZ) == false then
                iStorageInThisLZ = table.getn(toStorageInThisLZ)
            else
                iStorageInThisLZ = 0
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iStorageInThisLZ='..iStorageInThisLZ) end
            if iStorageInThisLZ <= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestEnergyStorageCount] and ((not(bSaveMassForMML) and not(bPrioritiseProduction)) or iStorageInThisLZ == 0) then
                if (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and AiBotBuilding.iLowestEnergyStorageTechAvailable <= 2) or (iStorageInThisLZ == 0 and not(AiBotEconomy.bT3MexCanBeUpgraded) and not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to get storage, Is tEngineers[1] valid='..tostring(AiBotUnitInfo.IsUnitValid(tEngineers[1]))) end
                    iBPWanted = 5
                    if not(bHaveLowMass) then iBPWanted = 20 end
                    HaveActionToAssign(refActionBuildEnergyStorage, AiBotBuilding.iLowestEnergyStorageTechAvailable, iBPWanted)
                end
            end
        end
    end

    --1 T3 mass fab if not defending against T3 arti and have lots of t3 mexes; or quantum gateway if enemy having them
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Mass fab builder: Highest friendly fac tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Defending against arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] or (AiBotOverseer.bNoRushActive and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and AiBotConditions.NoRushPreventingHydroOrMex(tLZData, true)) or AiBotMap.bIsLowMexMap or AiBotOverseer.IsTeamBoomMode(iTeam)) and not(bHaveLowPower) and not(bSaveMassForMML) and not(bPrioritiseProduction) then
        if bDebugMessages == true then LOG(sFunctionRef..': Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; bLowMexMap='..tostring(AiBotMap.bIsLowMexMap)..'; AiBotOverseer.iMassFabRatio='..(AiBotOverseer.iMassFabRatio or 'nil')) end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 350 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZData[AiBotMap.subrefLZOrWZMexCount] <= 1) or ((AiBotMap.bIsLowMexMap or AiBotOverseer.bNoRushActive) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 260 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (AiBotOverseer.iMassFabRatio >= 1.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 150 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (AiBotOverseer.IsTeamBoomMode(iTeam) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
            --Do we either have a constructed experimental in this zone, or have unit restrictions?
            if AiBotOverseer.bUnitRestrictionsArePresent or (tLZTeamData[AiBotMap.refiZoneConstructedExperimentalCount] or 0) > 0 or AiBotOverseer.bNoRushActive or AiBotMap.bIsLowMexMap or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbEnemyGettingFabsOrRAS] and tLZData[AiBotMap.subrefLZOrWZMexCount] <= 2) or (tLZData[AiBotMap.subrefLZOrWZMexCount] == 0 and not(bHaveLowPower)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider getting lower priority mass fab or gateway builder') end
                ConsiderBuildingMassFabOrGateway(iTeam, iLandZone, tLZTeamData, HaveActionToAssign, bWantMorePower)
            end
        end
    end

    --Shielding
    iCurPriority = iCurPriority + 1
    local iTechLevelWanted, oUnitToShield
    iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
    if iBPWanted > 0 then
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to build a shield, iBPWanted='..iBPWanted..'; bHaveLowMass='..tostring(bHaveLowMass)..'; bWantMorePower='..tostring(bWantMorePower)..'; oUnitToShield='..oUnitToShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToShield)..'; iTechLevelWanted='..iTechLevelWanted) end
        HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
    end

    --AA including SAMs
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Do we want more airaa? iNearbyEnemyAirToGroundThreat='..iNearbyEnemyAirToGroundThreat..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
    if iNearbyEnemyAirToGroundThreat > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= math.max(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA], 800) then
        if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] >= 200 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] == 0 then
            local iGroundAAThreatWanted
            if AiBotTeam.tAirSubteamData[ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].AiBotAirSubteam][AiBotTeam.refbHaveAirControl] then
                iGroundAAThreatWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.4 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.15
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFarBehindOnAir] then
                iGroundAAThreatWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.8 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.3
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 2000 then iGroundAAThreatWanted = iGroundAAThreatWanted + math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.15, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]) end
            else
                iGroundAAThreatWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.6 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.225
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 2000 then iGroundAAThreatWanted = iGroundAAThreatWanted + math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.1, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat]) end
            end
            if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) or iNearbyEnemyAirToGroundThreat >= 800 then
                iGroundAAThreatWanted = math.max(iNearbyEnemyAirToGroundThreat * 2, iNearbyEnemyAirToGroundThreat + iGroundAAThreatWanted)
            end
            --Cap Ground AA at equiv of 3 T2 flak if no enemy air to ground threat in this zone, and we arent at T3
            if iGroundAAThreatWanted >= 2400 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
                    iGroundAAThreatWanted = 2400
                else
                    --At T3 - reduce the amount of fixed AA wanted slightly for very high threat values (i.e. >= 10 SAM equivalent)
                    if iGroundAAThreatWanted >= 16000 then
                        if iGroundAAThreatWanted >= 30000 then
                            iGroundAAThreatWanted = 16000 + 14000 * 0.75 + (iGroundAAThreatWanted - 30000) * 0.5
                        else
                            iGroundAAThreatWanted = 16000 + (iGroundAAThreatWanted - 16000) * 0.75
                        end
                    end

                    --Campaign maps - further reduce amount earlier into the game
                    if AiBotMap.bIsCampaignMap and iGroundAAThreatWanted >= 8000 and (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4) and (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= math.max(20000, 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) or GetGameTimeSeconds() <= 900) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= math.max(20, tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] / 1000)) then
                        iGroundAAThreatWanted = math.min((iGroundAAThreatWanted - 8000) * 0.25 + 8000, 12000)
                    end
                    --No nearby air threats, and significant groundAA already, and low mass - reduce AA wanted by half unless we have all T3 mexes
                    if (bHaveLowMass or bHaveLowPower) and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 3000 and iNearbyEnemyAirToGroundThreat == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] <= math.min(5, tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                        if AiBotMap.iMapSize >= 1000 and (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 7000 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] < 3) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing groundAA threat wanted significantly to 35% of normal value as we already have some AA and are low on resources') end
                            iGroundAAThreatWanted = iGroundAAThreatWanted * 0.35
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing groundAA threat wanted to 50% of normal value as we already have some AA and are low on resources') end
                            iGroundAAThreatWanted = iGroundAAThreatWanted * 0.5
                        end
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': GroundAA='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; iGroundAAThreatWanted='..iGroundAAThreatWanted..'; Friendly factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
            --= AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]
            --Rushing T3 air from safe base - defer getting groundAA
            if tLZTeamData[AiBotMap.refbBaseInSafePosition] and iNearbyEnemyAirToGroundThreat == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] < 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbRushT3AirInAirSlot] and aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 and AiBotConditions.GetNearbyEnemyAirToGroundThreat(tLZData, tLZTeamData, iTeam, 150, 200) < 200 then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to rush t3 air so will delay') end


            elseif tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < iGroundAAThreatWanted or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 1600 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 1200 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2) or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 120)) then
                --Do we already have fixed AA in this LZ?
                local iAACategory = AiBotUnitInfo.refCategoryStructureAA
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then iAACategory = iAACategory * categories.TECH3 end
                local tExistingFixedAA = EntityCategoryFilterDown(iAACategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of fixed AA empty='..tostring(AiBotUtilities.IsTableEmpty(tExistingFixedAA))..'; Ally groundAA threat='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Highest enemy air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Enemy air to ground threat='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Enemy AirAA threat='..tLZTeamData[AiBotMap.refiEnemyAirAAThreat]..'; iGroundAAThreatWanted='..iGroundAAThreatWanted..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
                if AiBotUtilities.IsTableEmpty(tExistingFixedAA) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < math.max(1500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 3 + tLZTeamData[AiBotMap.refiEnemyAirAAThreat], iGroundAAThreatWanted)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < math.max(425 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 3 + tLZTeamData[AiBotMap.refiEnemyAirAAThreat] * 0.5, iGroundAAThreatWanted)) then
                    --Cap amount of SAMs if we dont have all T3 mexes in the zone and have low mass
                    if bDebugMessages == true then LOG(sFunctionRef..': bHaveLowMass='..tostring(bHaveLowMass)..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))..'; Ally groundAA threat='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Active brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) end
                    if not(bHaveLowMass and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 6000 and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1]) > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 15 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                        iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                        if iNearbyEnemyAirToGroundThreat > 0 then iBPWanted = iBPWanted * 2 end
                        if not(bHaveLowPower) then
                            if not(bHaveLowMass) then iBPWanted = iBPWanted * 4
                            else iBPWanted = iBPWanted * 2
                            end
                        end
                        HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted)
                        if bDebugMessages == true then LOG(sFunctionRef..': WIll build more AA, iBPWanted='..iBPWanted) end
                    end
                end
            end
        end
    end

    --Reclaim specific units
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if have units to reclaim, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]))) end
    if tLZTeamData[AiBotMap.subreftoUnitsToReclaim] and AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]) then
        local bObjectiveToReclaim = false
        if AiBotMap.bIsCampaignMap then
            for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if oUnit[AiBotUnitInfo.refbIsReclaimTarget] then bObjectiveToReclaim = true break end
            end
        end

        --Dont reclaim power if we have <100% stored or low power
        local bDontReclaimYet = false
        if not(bObjectiveToReclaim) and ((bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.98) then
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower, tLZTeamData[AiBotMap.subreftoUnitsToReclaim])) == false then
                bDontReclaimYet = true
            end
        end
        if not(AiBotOrders.bDontConsiderCombinedArmy) and not(bDontReclaimYet) then
            bDontReclaimYet = true
            for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if oUnit.AiBotActive or not(oUnit:GetAIBrain().AiBotTeam == iTeam) then
                    bDontReclaimYet = false
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to reclaim a unit but still stop if have low power and we have pgens in the list of units to reclaim, bHaveLowPower='..tostring(bHaveLowPower)..'; Average% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) end
        if not(bDontReclaimYet) then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to try and reclaim, bObjectiveToReclaim='..tostring(bObjectiveToReclaim)) end
            HaveActionToAssign(refActionReclaimFriendlyUnit, 1, math.min(2 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]], math.max(10, 10 * table.getn(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]))), nil, not(bObjectiveToReclaim))
        end
    end

    --Rushing T3 air from safe base - assist air fac
    iCurPriority = iCurPriority + 1
    if aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 and tLZTeamData[AiBotMap.refbBaseInSafePosition] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbRushT3AirInAirSlot] and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
        local oAirFacToUpgrade
        local iAirFacTechLevelWanted = aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]
        for iUpgrading, oUpgrading in tLZTeamData[AiBotMap.subreftoActiveUpgrades] do
            if EntityCategoryContains(AiBotUnitInfo.refCategoryAirHQ, oUpgrading.UnitId) and AiBotUnitInfo.GetUnitTechLevel(oUpgrading) >= iAirFacTechLevelWanted then
                oAirFacToUpgrade = oUpgrading
                break
            end
        end
        if oAirFacToUpgrade then
            iBPWanted = 30 * aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] * aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]
            if bHaveLowPower then iBPWanted = iBPWanted * 0.5 if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = iBPWanted * 0.5 end end
            HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, oAirFacToUpgrade)
            if bDebugMessages == true then LOG(sFunctionRef..': Trying to rush t3 air so prioritising air HQ upgrade, iBPWanted='..iBPWanted) end
        end
    end

    --Multiple mex upgrades (core zone), or a single upgrade but are behind enemy on eco - want to assist as a higher priority
    iCurPriority = iCurPriority + 1
    if (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) > 0 and ((tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= 2 or AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= math.max(1, 0.25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.15)) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) then
        iBPWanted = 10
        if not(bHaveLowPower) then
            iBPWanted = (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) * 15
        end
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 or (not(bHaveLowMass) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= math.max(1, 0.25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass])))) and bWantMoreFactories then
            iBPWanted = iBPWanted * 2
            if bHaveLowPower and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -10) <= 5 then
                if bDebugMessages == true then LOG(sFunctionRef..': Have low power and recently stalled E so will get more power instead of building air or land fac or assisting upgrade, iBPWanted='..iBPWanted) end
                HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, iBPWanted)
            else
                if bHaveLowPower and iFactoriesInLZ > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = iBPWanted * 0.25 end
                if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
                    HaveActionToAssign(refActionBuildAirFactory, 1, iBPWanted)
                else
                    HaveActionToAssign(refActionBuildLandFactory, 1, iBPWanted)
                end
            end
        else
            HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted)
        end
    end


    --More power
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': More power builder, bHaveLowMass='..tostring(bHaveLowMass)..'; bWantMorePower='..tostring(bWantMorePower)..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Highest friendly factory tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')) end
    if not(bHaveLowMass) and bWantMorePower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 11 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 0) > 0 and not(bSaveMassForMML) and not(bPrioritiseProduction) then
        iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 5
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 0 then
                iBPWanted = iBPWanted * 0.5
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > -3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamEnergyStored] >= 2000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                iBPWanted = iBPWanted * (1 - 0.5 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] + 3) / 3)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Want more power, iCurPriority='..iCurPriority..'; iBPWanted='..iBPWanted..'; refbFocusOnT1Spam='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])) end
        HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, iBPWanted)
    end

    --Assist ACU going for teleporter
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of upgrading ACUs on team empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs]) == false then
        local oACUUpgradingForTeleportInThisZone
        local AiBotACU = import('/lua/AiBot/AI/AiBotACU.lua') --done here incase having it above causes issues (havent actually tested, but aibotacu refers to parts of aibotengineer)
        if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs], false) then
            for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering upgrading ACU oACU='..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by brain '..oACU:GetAIBrain().Nickname..'; Unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Planning to get teleport='..tostring(oACU[AiBotACU.refbPlanningToGetTeleport])) end
                if oACU[AiBotACU.refbPlanningToGetTeleport] and oACU:IsUnitState('Upgrading') then
                    --Is ACU in this zone or nearby?

                    local iACUPlateauOrZero, iACULandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Have ACU wanting to get teleport whose unit state is upgrading, ACU brain='..oACU:GetAIBrain().Nickname..'; iACUPlateauOrZero='..(iACUPlateauOrZero or 'nil')..'; iACULandOrWaterZone='..(iACULandOrWaterZone or 'nil')..'; This plateau='..iPlateau..'; This LZ='..iLandZone..'; Dist from ACU to this zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oACU:GetPosition())) end
                    if iACUPlateauOrZero == iPlateau and iACULandOrWaterZone == iLandZone then --or AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oACU:GetPosition()) <= 100) then
                        oACUUpgradingForTeleportInThisZone = oACU
                        break
                    end
                end
            end
        end

        if oACUUpgradingForTeleportInThisZone then
            if bHaveLowPower then iBPWanted = 25
            else
                iBPWanted = 60
            end
            if not(bWantMorePower) then iBPWanted = 100 end
            if bDebugMessages == true then LOG(sFunctionRef..': Have ACU trying to get teleporter upgrade, iBPWanted='..iBPWanted) end
            HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, oACUUpgradingForTeleportInThisZone)
        end
    end

    --Shield assistance
    iCurPriority = iCurPriority + 1
    iBPWanted = GetBPForShieldAssistance(tLZTeamData, iTeam)
    if iBPWanted > 0 then
        HaveActionToAssign(refActionAssistShield, 1, iBPWanted)
    end

    --Higher priority mass storage if we have any T2+ mex in the LZ and available storage locations
    iCurPriority = iCurPriority + 1
    if AiBotBuilding.iLowestMassStorageTechAvailable <= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 11 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        iBPWanted = GetBPToAssignToMassStorage(iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, true, bHaveLowMass, bWantMorePower)
        if bSaveMassForMML then iBPWanted = iBPWanted * 0.5 end
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        if iBPWanted > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Higher priority mass storage if we have T3 mex in the LZ without storage, iBPWanted='..iBPWanted..'; iCurPriority='..iCurPriority) end
            HaveActionToAssign(refActionBuildMassStorage, AiBotBuilding.iLowestMassStorageTechAvailable, iBPWanted)
        end
    end

    --Factory builder ahead of assisting upgrades for if we have low mass stored but lots of mexes upgrading in this LZ, and are at T3
    iCurPriority = iCurPriority + 1
    if iActiveMexUpgrades >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.01 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 and table.getn(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) >= 3 then
        if bHaveLowPower then iBPWanted = tiBPByTech[3] * 3
        else iBPWanted = tiBPByTech[3] * 5
        end
        if iFactoriesInLZ > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then iBPWanted = iBPWanted * 0.25 end
        local bWantAirNotLand = AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)
        local iFactoryAction
        if bWantAirNotLand then iFactoryAction = refActionBuildAirFactory
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build land factory not air factory3') end
            iFactoryAction = refActionBuildLandFactory
        end
        if bHaveLowPower and bWantAirNotLand then iBPWanted = iBPWanted * 0.5 end

        HaveActionToAssign(iFactoryAction, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted, nil)
    end

    --Preemptive SMD
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; About to consider if want SMD, is table of enemy nukes empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]))..'; tLZTeamData[AiBotMap.subrefLZSValue]='..tLZTeamData[AiBotMap.subrefLZSValue]..'; Lifetime T3 nonstructure count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, categories.TECH3 - categories.STRUCTURE)..'; Team mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; T3 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; Total LZ mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; Have low mass='..tostring(bHaveLowMass)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Condition 1 is met='..tostring((tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and (not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 + 20 * (1-AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])))..'; Condition 2 is met='..tostring((tLZData[AiBotMap.subrefLZOrWZMexCount] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount]) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 5)))..'; Condition 3 is met='..tostring((tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 30))) end
    if tLZTeamData[AiBotMap.subrefLZSValue] >= 20000 and not(bHaveLowPower) and (tLZTeamData[AiBotMap.subrefLZSValue] >= 30000 or not(bHaveLowMass)) and (not(bPrioritiseProduction) or (GetGameTimeSeconds() >= 2400 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 or GetGameTimeSeconds() >= 3000))) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and not(bSaveMassForMML) then
        --Only build SMD if we have built a lot of T3 units or have built experimentals or have very high eco
        local iCurSMDInTeam = AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategorySMD, iTeam)
        if tLZTeamData[AiBotMap.subrefLZSValue] >= 45000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount]))) or ((not(AiBotUtilities.bLoudModActive) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, categories.TECH3) >= 15 + 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (AiBotUtilities.bLoudModActive and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, categories.TECH3 - categories.STRUCTURE) >= 20 + 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
            --Also require several T3 mexes unless we have very high mass
            if (tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and (not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 25 + 15 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] - 1))
                    or (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(3, tLZData[AiBotMap.subrefLZOrWZMexCount]))
                    or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 30 or (iCurSMDInTeam == 0 and AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) * 1.2 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]))) then
                local iExperimentalLifetimeCount = AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel)
                if bDebugMessages == true then LOG(sFunctionRef..': we have high enough mass to consider getting a preemptive SMD, iExperimentalLifetimeCount='..iExperimentalLifetimeCount) end
                if (iCurSMDInTeam == 0 and iExperimentalLifetimeCount >= 1) or iExperimentalLifetimeCount > math.min(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 or (not(bHaveLowMass) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20)) or AiBotMap.bIsCampaignMap then
                    local iSMDUnderConstructionInThisZone = AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, AiBotUnitInfo.refCategorySMD, true)
                    local bStillGetSMD = true
                    if iSMDUnderConstructionInThisZone == 0 then
                        local iSMDUnderConstructionInOtherZones = AiBotConditions.GetNumberOfUnderConstructionUnitsOfCategoryInOtherCoreZones(tLZTeamData, iTeam, AiBotUnitInfo.refCategorySMD)
                        if iSMDUnderConstructionInOtherZones > 0 then bStillGetSMD = false end
                    end
                    if bStillGetSMD then
                        local bAssistSMD = false
                        local oSMDToShield, oShieldToAssist
                        iBPWanted, bAssistSMD, oSMDToShield, oShieldToAssist = GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, false, bHaveLowMass, bWantMorePower)
                        if iBPWanted > 0 and not(bAssistSMD) then --Since htis is precautionary not worried about rushing the SMD or shielding as a high priority
                            if bDebugMessages == true then LOG(sFunctionRef..': Will assign BP to build an SMD preemptively, iBPWanted='..iBPWanted) end
                            HaveActionToAssign(refActionBuildSMD, 3, iBPWanted)
                        elseif oShieldToAssist then
                            HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oShieldToAssist)
                        end
                    end
                end
            end
        end
    end

    --Build multiple land factories if have lots of mass stored (higher priority)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want high priority second factory builder, bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; bWantMoreFactories='..tostring(bWantMoreFactories)..'; iActiveMexUpgrades='..iActiveMexUpgrades..'; Mass % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Friendly highest land fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; Team net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
    if not(bHaveLowMass) and not(bHaveLowPower) and bWantMoreFactories and not(bSaveMassForMML) and iFactoriesInLZ >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 11 and (iActiveMexUpgrades >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.25) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 or iActiveMexUpgrades >= 4) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 1 or iActiveMexUpgrades >= 4) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.45 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= math.min(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.25, 8))
            and (aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 2 or not(aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseDefence])) then

        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.55 then iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]] * 4
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 then iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]] * 2
        else iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]]
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Have lots of mass so want to build more than one factory at once as high priority, iBPWanted='..iBPWanted) end
        if not(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)) then
            HaveActionToAssign(refActionBuildSecondLandFactory, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech], iBPWanted)
        end
    end

    --T2 radar to support skirmishers (including t2 skirmishers) if enemy close to our side of the map
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want T2 radar for core base, radar coverage='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')..'; AiBotUnitInfo.iT1RadarSize='..AiBotUnitInfo.iT1RadarSize..'; Mobile DF threat near our side='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]..'; Brain energy='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; bHaveLowPower='..tostring(bHaveLowPower)) end
    if tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize and not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 250 or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 800) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] or 0) >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 160 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]  and not(bHaveLowPower) and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
        if bDebugMessages == true then LOG(sFunctionRef..'; Cur T2 skirmisher count='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySkirmisher - categories.TECH1)) end
        if aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 250 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySkirmisher - categories.TECH1) >= 2 then
            if bDebugMessages == true then LOG(sFunctionRef..': is table of radar empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                iBPWanted = 15
                if not(bHaveLowMass) and not(bHaveLowPower) then iBPWanted = 40 end
                if bDebugMessages == true then LOG(sFunctionRef..'; will try getting t2 radar') end
                HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
            end
        end
    end

    --Second mass storage if we have T2+ mex in this LZ and 5+ mass storage locations
    iCurPriority = iCurPriority + 1
    if not(bSaveMassForMML) and not(bPrioritiseProduction) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
        iBPWanted = GetBPToAssignToMassStorage(iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, true, bHaveLowMass, bWantMorePower)
        if iBPWanted > 0 then
            if table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) >= 5 then
                HaveActionToAssign(refActionBuildSecondMassStorage, 1, iBPWanted)
            end
        end
    end


    --Assist upgrades:
    iCurPriority = iCurPriority + 1
    iBPWanted = GetBPToAssignToAssistUpgrade(tLZTeamData, iTeam, true, bHaveLowMass, bHaveLowPower, bWantMorePower)
    if iBPWanted > 0 then
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted)
    end

    --Build mass storage if we have T2+ mexes
    iCurPriority = iCurPriority + 1
    iBPWanted = GetBPToAssignToMassStorage(iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, true, bHaveLowMass, bWantMorePower)
    if iBPWanted > 0 then
        if bSaveMassForMML then iBPWanted = iBPWanted * 0.5 end
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        HaveActionToAssign(refActionBuildMassStorage, AiBotBuilding.iLowestMassStorageTechAvailable, iBPWanted)
    end

    --Lower priority core WZ wanting engineers:
    iCurPriority = iCurPriority + 1
    if iCoreWZWantingSupportAsLowerPriority then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            HaveActionToAssign(refActionMoveToWaterZone, 1, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], iCoreWZWantingSupportAsLowerPriority, true)
        end
    end


    --Lower priority mass reclaim
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to get more reclaim, mass%='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] or 0)..'; Total mass reclaim='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; Signif mass reclaim='..(tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0)) end
    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 and tLZData[AiBotMap.subrefTotalMassReclaim] >= 5) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.5 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 150) then
        if bDebugMessages == true then LOG(sFunctionRef..': Lower priority reclaim, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]) end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 then
            iBPWanted = math.min(100, math.max(5, tLZData[AiBotMap.subrefTotalMassReclaim] / 10))
            if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3000 then iBPWanted = math.min(200, math.max(iBPWanted, tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 30)) end
        else
            iBPWanted = math.min(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2, tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 20)
        end
        HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
    end

    --Mass fab for LOUD or 40km+ maps (higher priority) when are spending all our mass and dont have low power, provided we have already built an experimental
    iCurPriority = iCurPriority + 1
    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or AiBotMap.iMapSize > 1000 or AiBotMap.bIsLowMexMap) and bHaveLowMass and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbPrioritiseProduction]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 80 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon]) and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 150 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > 0 then
        ConsiderBuildingMassFabOrGateway(iTeam, iLandZone, tLZTeamData, HaveActionToAssign, bWantMorePower, 2, true)
        --iBPWanted = 60
        --if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = 40 end
        --HaveActionToAssign(refActionBuildT3MassFab, 3, iBPWanted) --NOTE: Have a separate function more generally for mass fabs and quantum gateways
    end

    --Radar (not high priority)
    iCurPriority = iCurPriority + 1
    if not(bHaveLowPower) and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
        --T1 radar
        if tLZTeamData[AiBotMap.refiRadarCoverage] <= 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 25 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] and (GetGameTimeSeconds() >= 360 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3 or not(tLZTeamData[AiBotMap.refbBaseInSafePosition])))) then
            --Check we dont already have t1 radar in the land zone
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT1Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                iBPWanted = 5
                if not(bHaveLowMass) then iBPWanted = 15 end
                HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted)
            end
        end

        --T2 radar
        iCurPriority = iCurPriority + 1
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want T2 radar, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
        if tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 40 + 60 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 3 + 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
            if not(bSaveMassForMML) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 then
                --Check we dont already have t2 radar in the land zone
                if not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                    if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Radar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) then
                        iBPWanted = 20
                        if not(bHaveLowMass) then iBPWanted = 60 end
                        HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                    end
                end
            end
        end

        --T3 radar
        iCurPriority = iCurPriority + 1
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to build T3 radar, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Closest enemy base dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
        if not(bSaveMassForMML) and (not(bPrioritiseProduction) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2) and tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT2RadarSize and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 200) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 350 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 100 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryMobileLand * categories.TECH3 - AiBotUnitInfo.refCategoryEngineer) >= 40) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 and (AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) > tLZTeamData[AiBotMap.refiRadarCoverage] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20) then
            --Require T3 mexes before building T3 radar
            if tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0) then
                if AiBotUnitInfo.iT3RadarSize - AiBotUnitInfo.iT2RadarSize >= 100 or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryT3Radar) == 0 then
                    iBPWanted = 30
                    if not(bHaveLowMass) then iBPWanted = 100 end
                    if bDebugMessages == true then LOG(sFunctionRef..': Will build T3 radar, iBPWanted='..iBPWanted..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
                    HaveActionToAssign(refActionBuildT3Radar, 3, iBPWanted)
                end
            end
        end
    end

    --Air fac and second air fac ahead of land experimental if enemy has significant air to ground threat, for larger maps
    iCurPriority = iCurPriority + 1
    if AiBotMap.iMapSize > 512 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) < 8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeAir] or 0) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone) then
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
            iBPWanted = 40
            if not(bHaveLowMass) then iBPWanted = 80 end
            HaveActionToAssign(refActionBuildAirFactory, 3, iBPWanted)
            if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 10000 and not(AiBotConditions.TeamHasAirControl(iTeam))
                    and (not(aiBrain[AiBotOverseer.refbPrioritiseHighTech]) or aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3) and not(aiBrain[AiBotOverseer.refbPrioritiseNavy]) and (not(aiBrain[AiBotOverseer.refbPrioritiseDefence]) or aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3) then
                HaveActionToAssign(refActionBuildSecondAirFactory, 3, iBPWanted)
            end
        end
    end

    --Land experimental if lots of mass or have built lots of T3 units, or enemy has experimental and we dont, or we have good mass income
    iCurPriority = iCurPriority + 1
    local bExperimentalsBuiltInThisLZ, iExperimentalsBuiltInOtherLZ = GetExperimentalsBeingBuiltInThisAndOtherLandZones(iTeam, iPlateau, iLandZone, nil, nil, nil, nil, nil, aiBrain.AiBotAirSubteam)

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; iCurPriority='..iCurPriority..'; bExperimentalsBuiltInThisLZ='..tostring(bExperimentalsBuiltInThisLZ)..'; iExperimentalsBuiltInOtherLZ='..iExperimentalsBuiltInOtherLZ..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltLotsOfT3Combat]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltLotsOfT3Combat] or false)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and (
            (bExperimentalsBuiltInThisLZ or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 7 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 or (not(bWantT3LandForRavagers) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.2)))) and
                    --Are we already building an experimental here (in which case finish), or ave we built lots of T3 units, or does enemy have a land experimental and we arent building one anywhere? Or we havent built many experimentals and have high mass income?
                    ((bExperimentalsBuiltInThisLZ or (iExperimentalsBuiltInOtherLZ == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltLotsOfT3Combat] or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false)))
                            --Alternatively do we have lots of mass stored?
                            or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] > 8000 + 8000 * iExperimentalsBuiltInOtherLZ and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 11000 + 11000 * iExperimentalsBuiltInOtherLZ)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 20 + iExperimentalsBuiltInOtherLZ * 40 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= math.min(0.6, 0.1 + 0.1 * iExperimentalsBuiltInOtherLZ))
                            --Alternatively have we not built an experimental before but our team has high mass income and at least 1 T3 mex in this zone?
                            or (iExperimentalsBuiltInOtherLZ == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= (14 + 2 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(1 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount], tLZData[AiBotMap.subrefLZOrWZMexCount]))
                    )
                    or (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or -1000) <= 60 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4)
                    or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 400) then
        if bExperimentalsBuiltInThisLZ or iExperimentalsBuiltInOtherLZ == 0 or not(bHaveLowMass) then
            iBPWanted = 100 --No point trying to build an experimental with less build power
            if not(bHaveLowPower) then
                iBPWanted = iBPWanted * 1.5
                --BP wanted: e.g. monkeylord will cost 0.07 mass per tick for 1 BP; so if want to spend approx 50% of mass on the experimental, then for every 1 mass per tick generated, would want roughly 7 build power
                if not(bHaveLowMass) then iBPWanted = math.max(iBPWanted * 1.5, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] - iExperimentalsBuiltInOtherLZ * 25 - 10) * 5) end
                if bDebugMessages == true then LOG(sFunctionRef..': iExperimentalsBuiltInOtherLZ='..iExperimentalsBuiltInOtherLZ..'; Is table of enemy land exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))..'; Lifetime exp level build count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel)) end
                if iExperimentalsBuiltInOtherLZ == 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryExperimentalLevel) < math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 0.75) then
                    local iCapOnIncrease = 500
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iCapOnIncrease = 250 end
                    iBPWanted = math.max(iBPWanted, math.min(iCapOnIncrease, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 6))
                    if bDebugMessages == true then LOG(sFunctionRef..': IBPWanted after increasing if first experimental being built and enemy team has one='..iBPWanted) end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will get experimental if have enough T3 mexes in this zone, tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
            if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (not(bHaveLowMass) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 25000))) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2) or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false)) then
                --Want to only build experimental if have mostly T3 mexes in this zone
                if not(bSaveMassForMML) or (aiBrain.GetFactionIndex and not(aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(2, tLZData[AiBotMap.subrefLZOrWZMexCount])) then
                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 3, iBPWanted)
                    --HaveActionToAssign(refActionBuildExperimental, 3, iBPWanted)

                    --Also want more BP than what we have regardless if have lots of mass stored and experimental is being built
                    if bDebugMessages == true then LOG(sFunctionRef..': Have just had action to build experimental with iBPWanted='..iBPWanted..'; If lots of mass stored will increase BP assigned to experimental, bExperimentalsBuiltInThisLZ='..tostring(bExperimentalsBuiltInThisLZ)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; bHaveLowPower='..tostring(bHaveLowPower)) end
                    if bExperimentalsBuiltInThisLZ and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.6 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 20000) and not(bHaveLowPower) then
                        --Want 60 extra BP vs what we have already assigned
                        iBPWanted = 60
                        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.8 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored])) or not(bWantMorePower) then iBPWanted = 120 end
                        AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, iTechLevelWanted, iBPWanted, nil, false, true)
                        --HaveActionToAssign(refActionBuildExperimental, 3, iBPWanted, nil, false, true)
                    end
                end
            end
        end

    end

    --Build multiple land factories if have lots of mass stored (lower priority)
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and not(bHaveLowPower) and bWantMoreFactories and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then
        if bDebugMessages == true then LOG(sFunctionRef..': Have lots of mass so want to build more than one factory at once (lower priority)') end

        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 then iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 7
        else iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 5
        end
        if not(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)) then --factors in things like if we are on the same plateau
            HaveActionToAssign(refActionBuildSecondLandFactory, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech], tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 5)
        end
    end

    --Ensure we have engineers reclaiming current zone if it has lots of mass (looser conditions) before sending them to other lower priority zones
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Lower priority reclaim before sending engis to other zones, iCurPriority='..iCurPriority..'; subrefTotalMassReclaim='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; subrefiTeamAverageMassPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; subrefTotalSignificantMassReclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]) end
    if tLZData[AiBotMap.subrefTotalMassReclaim] >= 500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.8 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] > 50 then

        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 then
            iBPWanted = math.min(80, math.max(5, tLZData[AiBotMap.subrefTotalMassReclaim] / 10))
            if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3000 then iBPWanted = math.min(160, math.max(iBPWanted, tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 40)) end
        else
            iBPWanted = math.min(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 2, tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 20)
        end
        if iBPWanted < tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 10 and iBPWanted < 40 then iBPWanted = math.min(40, tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 10) end
        if bDebugMessages == true then LOG(sFunctionRef..': Even lower priority reclaim, subrefTotalMassReclaim='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; iBPWanted='..iBPWanted) end
        HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
    end

    --Lower priority land zones wanting engineers:
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS) Other non adjacent LZ on this plateau that wants engineers (low priority) - prioritise those nearest this zone
    iCurPriority = iCurPriority + 1
    iBPAlreadyTraveling = 0
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then
        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
            for iEngi, oEngi in toAssignedEngineers do
                if oEngi[refiAssignedAction] == refActionMoveToLandZone then
                    iBPAlreadyTraveling = iBPAlreadyTraveling + oEngi:GetBlueprint().Economy.BuildRate
                end
            end
        end

        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
            for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                if iBPAlreadyTraveling > 0 or not(tLZWantingBPConsidered[iAdjLZ]) then
                    tLZWantingBPConsidered[iAdjLZ] = true
                    --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                    --Dont check for recently run engineers since this is a core base so may take a while for engi to get there anyway
                    local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, false, false, false, false)
                    if tiBPByTechWanted then
                        --Is it either a minor zone, or a core zone that either wants lots of BP or doesnt have any engineers traveling to it?
                        for iTech = 1, iHighestTechEngiAvailable, 1 do
                            if tiBPByTechWanted[iTech] > 0 then
                                iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                iBPWanted = iBPAlreadyTraveling + 5
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and assign an engineer to go to iAdjLZ='..iAdjLZ..'; BP wanted='..iBPWanted..'; iTech='..iTech..'; iPrevEngisAvailable='..iPrevEngisAvailable) end
                                HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, iAdjLZ, true)
                                if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                    iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                    iBPAlreadyTraveling = iBPAlreadyTraveling + tiBPByTech[iTech]
                                end

                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable after this='..iHighestTechEngiAvailable) end
                                if iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                    end
                end
                if iHighestTechEngiAvailable == 0 then break end
            end
        end
    end

    --Islands wanting engineers (provided there are no enemy naval units in an adjacent naval zone)
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Core LZ considering engis for islands, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Time='..GetGameTimeSeconds()) end
    if iHighestTechEngiAvailable > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of pathing to other islands empty='..tostring(tLZData[AiBotMap.subrefLZPathingToOtherIslands])) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
            local iDistanceThreshold = math.max(125, AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 0.6)
            if bDebugMessages == true then LOG(sFunctionRef..': iDistanceThreshold='..iDistanceThreshold) end

            for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; Travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; tPathingData[AiBotMap.subrefIslandClosestLZRef]='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; Are there enemies in this or adjacnet LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                if tPathingData[AiBotMap.subrefIslandTravelDist] > iDistanceThreshold then break
                else
                    --Are there enemies in the target LZ?
                    if tPathingData[AiBotMap.subrefIslandClosestLZRef] then
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]]
                        if bDebugMessages == true then LOG(sFunctionRef..': Are there enemies in the land zone or adjacent='..tostring(tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Is the midpoint in the playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]))) end
                        if not(tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                            --Can we reach the island?
                            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]) then
                                --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                                local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false, true, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                                if tiBPByTechWanted then
                                    --Is it either a minor zone, or a core zone that either wants lots of BP or doesnt have any engineers traveling to it?
                                    for iTech = 1, iHighestTechEngiAvailable, 1 do
                                        if tiBPByTechWanted[iTech] > 0 then
                                            iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                            iBPWanted = iBPAlreadyTraveling + 5
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and assign an engineer to go to tPathingData[AiBotMap.subrefIslandClosestLZRef]='..tPathingData[AiBotMap.subrefIslandClosestLZRef]..'; BP wanted='..iBPWanted..'; iTech='..iTech..'; iPrevEngisAvailable='..iPrevEngisAvailable) end
                                            HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, tPathingData[AiBotMap.subrefIslandClosestLZRef], true)
                                            if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                                iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                                iBPAlreadyTraveling = iBPAlreadyTraveling + tiBPByTech[iTech]
                                            end

                                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                            if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable after this='..iHighestTechEngiAvailable) end
                                            if iHighestTechEngiAvailable == 0 then break end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --Quantum gateway for high AIx modifier and campaign, once we are at T3 mexes for the LZ
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to build quantum gateway, MexCountByTech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; bHaveLowPower='..tostring(bHaveLowPower)..'; mass storage locations empty?='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]))..'; mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]) end
    if not(bHaveLowPower) and not(bSaveMassForMML) and not(bPrioritiseProduction) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 11) or (AiBotMap.bIsCampaignMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 13))
            and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 6 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0))
            and (AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 or (AiBotMap.bIsCampaignMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 14))
            and (AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30) then
        --Are we in campaign (where ecoing more important) or AIx 1.2+?
        local iHighestCheatModifier = 1
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                if oBrain.CheatEnabled then
                    iHighestCheatModifier = oBrain[AiBotEconomy.refiBrainResourceMultiplier] or tonumber(ScenarioInfo.Options.CheatMult or 1.5)
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap)..'; iHighestCheatModifier='..iHighestCheatModifier) end
        if AiBotMap.bIsCampaignMap or iHighestCheatModifier >= 1.2 or (AiBotMap.iMapSize >= 1000 and not(bHaveLowMass) and ((tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount] or (AiBotOverseer.bNoRushActive and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and AiBotConditions.NoRushPreventingHydroOrMex(tLZData, true))))) then
            if AiBotOverseer.bUnitRestrictionsArePresent or (tLZTeamData[AiBotMap.refiZoneConstructedExperimentalCount] or 0) > 0 or AiBotOverseer.bNoRushActive then
                --Dont get gateway if low on mass and have t2 mexes in this zone we could upgrade
                if (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.05) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2 then
                    iBPWanted = 20
                    if not(bHaveLowMass) then iBPWanted = 80 end
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and build a quantum gateway') end
                    --Do we already have a quantum gateway in this land zone?
                    local iCurQuantumGateways = 0
                    local tQuantumGateways = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty( tQuantumGateways) == false then
                        for iUnit, oUnit in tQuantumGateways do
                            if oUnit:GetFractionComplete() >= 1 then
                                iCurQuantumGateways = iCurQuantumGateways + 1
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurQuantumGateways='..iCurQuantumGateways) end
                    --Get 1 quantumn gateway (or 2+ if we have 1.5+ AIx modifier)
                    if iCurQuantumGateways == 0 or (iCurQuantumGateways < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] >= 1.4 and iCurQuantumGateways < 0.4 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]) then
                        HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and assign '..iBPWanted..' to building a quantum gateway') end
                    end
                end
            end
        end
    end

    --Quantum optics if we need help with scouting
    iCurPriority = iCurPriority + 1
    if not(bHaveLowPower) and not(bSaveMassForMML) and not(bPrioritiseProduction) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 15000) and tLZTeamData[AiBotMap.refiRadarCoverage] > AiBotUnitInfo.iT2RadarSize and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 500 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
        --Are we likely to have aeon here?
        if ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]:GetFactionIndex() == AiBotUnitInfo.refFactionAeon then
            --Do we already have a quantum optics?
            if not(AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAlliedQuantumOptics])) then
                iBPWanted = 45
                if not(bHaveLowMass) then iBPWanted = 90 end
                HaveActionToAssign(refActionBuildQuantumOptics, 3, iBPWanted)
            end
        end
    end

    --Second experimental builder (for very high mass scenarios) assuming we have lots of T3 mexes
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and not(bHaveLowPower) and not(bSaveMassForMML) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 5000 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 or not(bWantT3LandForRavagers)) then
        if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2) or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
            --Want 30 extra BP vs what we have already assigned to both normal and second experimental builders
            iBPWanted = 30
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.8 or not(bWantMorePower) then iBPWanted = iBPWanted * 2 end
            --HaveActionToAssign(iActionToAssign,           iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting)
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 3,                       iBPWanted,      nil,                false, true)
            --HaveActionToAssign(refActionBuildExperimental,   3,                       iBPWanted,      nil,                false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Will flag that we want a second experimental to be built, additional iBPWanted='..iBPWanted) end
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildSecondExperimental, 3,                     iBPWanted,      nil,                false,                      true)
            --HaveActionToAssign(refActionBuildSecondExperimental, 3,                     iBPWanted,      nil,                false,                      true)
        end
    end

    --Assist upgrade even if resources aren't great
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.95 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 20 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 0 then
        iBPWanted = 10
        if bPrioritiseProduction then iBPWanted = 5 end --want at least some progress to be made on upgrades
        HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted, false, false)
    end


    --Units to capture
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then
        --Refresh the list
        local iCaptureCount = table.getn(tLZData[AiBotMap.subreftoUnitsToCapture])
        for iCurCount = iCaptureCount, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(tLZData[AiBotMap.subreftoUnitsToCapture][iCurCount])) then
                table.remove(tLZData[AiBotMap.subreftoUnitsToCapture], iCurCount)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Have units to capture for zone '..iLandZone..'; after freshing them is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]))) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then
            --Dont capture if are a hostile AI due to the risk we capture a campaign objective and progress the map
            if not(ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].HostileCampaignAI) then
                local oUnitToCapture
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                    local tPotentialCapture = EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryT3Power, tLZData[AiBotMap.subreftoUnitsToCapture])
                    if AiBotUtilities.IsTableEmpty(tPotentialCapture) == false then
                        oUnitToCapture = AiBotUtilities.GetNearestUnit(tPotentialCapture, tLZData[AiBotMap.subrefMidpoint])
                    end
                else
                    oUnitToCapture = AiBotUtilities.GetNearestUnit(tLZData[AiBotMap.subreftoUnitsToCapture], tLZData[AiBotMap.subrefMidpoint])
                end
                if oUnitToCapture then
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit to cpature='..oUnitToCapture.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToCapture)) end
                    iBPWanted = GetCaptureBPWanted(oUnitToCapture, bHaveLowPower, iTeam, tLZTeamData[AiBotMap.subrefLZbCoreBase])
                    HaveActionToAssign(refActionCaptureUnit, 1, iBPWanted, oUnitToCapture)
                end
            end
        end
    end

    --Units to repair
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Have units to repair for zone '..iLandZone..' is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]))) end

        if AiBotConditions.IsTableOfUnitsStillValid(tLZData[AiBotMap.subreftoUnitsToRepair], true) then
            local oUnitToTarget = AiBotUtilities.GetNearestUnit(tLZData[AiBotMap.subreftoUnitsToRepair], tLZData[AiBotMap.subrefMidpoint])
            if oUnitToTarget[refbDontIncludeAsPartCompleteBuildingForConstruction] then
                --Remove unit from UnitsToRepair
                for iUnit, oUnit in tLZData[AiBotMap.subreftoUnitsToRepair] do
                    if oUnit == oUnitToTarget then
                        table.remove(tLZData[AiBotMap.subreftoUnitsToRepair], iUnit)
                        break
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Unit to repair='..oUnitToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToTarget)) end
                HaveActionToAssign(refActionRepairUnit, 1, 5, oUnitToTarget)
            end
        end

    end

    --Game ender builder (in addition to normal experimental builders) - intended for extreme scenarios where overflowing lots of mass, or where are in campaign, at unit cap and have decent eco
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to build gameender, bHaveLowPower='..tostring(bHaveLowPower)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 'nil')..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Gameender count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) end
    if not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 3 and not(bSaveMassForMML) and not(bPrioritiseProduction) and (
            (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 95 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.55 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 10000)
                    or (AiBotMap.bIsCampaignMap and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 2 or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 60 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
        local bAlreadyHaveGameEnderUnderConstruction = false
        --local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]] --AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if bDebugMessages == true then LOG(sFunctionRef..': About to check for nearby gameenders for team '..(iTeam or 'nil')..'; First active AiBotbrain aibrain='..(aiBrain.Nickanme or 'nil')..'; LZ midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])) end
        local tNearbyGameEnders = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGameEnder, tLZData[AiBotMap.subrefMidpoint], 1000, 'Ally')
        local iCompletedGameEnders = 0
        if AiBotUtilities.IsTableEmpty(tNearbyGameEnders) == false then
            for iExperimental, oExperimental in tNearbyGameEnders do
                if oExperimental:GetFractionComplete() < 1 then
                    --Is this gameender in a different zone?
                    local iGameEnderPlateau, iGameEnderZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oExperimental:GetPosition())
                    if not(iGameEnderZone == iLandZone and iGameEnderPlateau == iPlateau) then
                        bAlreadyHaveGameEnderUnderConstruction = true
                    end
                else
                    iCompletedGameEnders = iCompletedGameEnders + 1
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bAlreadyHaveGameEnderUnderConstruction='..tostring(bAlreadyHaveGameEnderUnderConstruction or false)) end
        if not(bAlreadyHaveGameEnderUnderConstruction) then
            iBPWanted = 45
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 125 then iBPWanted = 90 end
            if iCompletedGameEnders < 1 then

                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildGameEnder, 3,                     iBPWanted,      nil,                false,                      true)
                --HaveActionToAssign(refActionBuildGameEnder, 3,                     iBPWanted,      nil,                false,                      true)
                if bDebugMessages == true then LOG(sFunctionRef..': iBPWanted for gameender='..iBPWanted) end
            else
                --Consider getting land experimental instead unless we have large number already
                local iCompletedLandExperimentals = 0
                local tNearbyLandExperimentals = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandExperimental, tLZData[AiBotMap.subrefMidpoint], 1000, 'Ally')
                if AiBotUtilities.IsTableEmpty(tNearbyLandExperimentals) == false then
                    for iUnit, oUnit in tNearbyLandExperimentals do
                        if oUnit:GetFractionComplete() >= 1 then
                            iCompletedLandExperimentals = iCompletedLandExperimentals + 1
                        end
                    end
                end
                local iLandExpeimentalsWantedPerGameEnder = 1
                if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestEnemyBase]) == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZData[AiBotMap.subrefMidpoint]) then iLandExpeimentalsWantedPerGameEnder = 5 end
                if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want gameender or land experimental, iCompletedLandExperimentals='..iCompletedLandExperimentals..'; iCompletedGameEnders='..iCompletedGameEnders..'; iLandExpeimentalsWantedPerGameEnder='..iLandExpeimentalsWantedPerGameEnder) end
                if iCompletedLandExperimentals < iCompletedGameEnders * iLandExpeimentalsWantedPerGameEnder then
                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildLandExperimental, 3,                     iBPWanted,      nil,                false,                      true)
                else
                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildGameEnder, 3,                     iBPWanted,      nil,                false,                      true)
                end
            end
        end
    end

    --Low priority island support - will consider further away distances tahn before, up to a distance of 400, and only if the island wants T1 engineer BP

    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Low priority core zone island engi support logic, iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
    if iHighestTechEngiAvailable > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': is pathing to other islands empty='..tostring( AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]))) end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; tLZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])) end

                for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..tPathingData[AiBotMap.subrefIslandNumber]..' for lower priority travel; travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; Closest LZ ref='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; are enemies in this or adjacent LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                    if tPathingData[AiBotMap.subrefIslandTravelDist] > 400 then break
                    else
                        --Are there enemies in the target LZ?

                        if tPathingData[AiBotMap.subrefIslandClosestLZRef] then
                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]]
                            if not(tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                                --Can we reach the island?
                                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]) then
                                    --Are there enemies in an adjacent LZ
                                    local iAdjacentEnemyThreat = 0
                                    if tAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                        if AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                            for _, iAdjToAdjLZ in tAdjLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                local tAdjToAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjToAdjLZ]
                                                iAdjacentEnemyThreat = iAdjacentEnemyThreat + tAdjToAdjLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iAdjacentEnemyThreat='..iAdjacentEnemyThreat) end
                                    if iAdjacentEnemyThreat < 10 then
                                        --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                                        local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false, true, false, false)
                                        if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                                        if (tiBPByTechWanted[1] or 0) > 0 then
                                            HaveActionToAssign(refActionMoveToLandZone, 1, 5, tPathingData[AiBotMap.subrefIslandClosestLZRef], true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to give order for engi to move to the island LZ '..tPathingData[AiBotMap.subrefIslandClosestLZRef]) end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --Build more air factories if close to overflowing mass and dont have low power (e.g. to help in campaign and unit restriction scenarios where land factories arent an option)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether want a low priority air factory if overflowing mass, bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Lowest mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Land facotyr lifetime count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandFactory)..'; Want more factories='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone))..'; want air instead of land fac='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) end
    if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone) then
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) or ((AiBotMap.bIsCampaignMap or AiBotOverseer.bUnitRestrictionsArePresent) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandFactory) <= 1) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build another air factory as low priority action due to mass overflow') end
            iBPWanted = 3 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
            HaveActionToAssign(refActionBuildAirFactory, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted, nil)
        end
    end

    --Build second air factories if really close to overflowing mass and dont have low power (e.g. to help in campaign and unit restriction scenarios where land factories arent an option)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether want a low priority air factory if overflowing mass, bHaveLowMass='..tostring(bHaveLowMass)..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Lowest mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Land facotyr lifetime count='..AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandFactory)..'; Want more factories='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone))..'; want air instead of land fac='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData))) end
    if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 1 then
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) or ((AiBotMap.bIsCampaignMap or AiBotOverseer.bUnitRestrictionsArePresent) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandFactory) <= 1) then
            if GetGameTimeSeconds() >= 300 / aiBrain[AiBotEconomy.refiBrainResourceMultiplier] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 then
                iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]]
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and build another air factory as low priority action due to mass overflow, iBPWanted='..iBPWanted..'; Highest air fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]) end
                HaveActionToAssign(refActionBuildSecondAirFactory, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted, nil)
            end
        end
    end

    --Check for any part constructed buildings in this zone if we have available engineers
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then
        local iCatToSearch
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
            iCatToSearch = AiBotUnitInfo.refCategoryPower
            if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti end
            if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryStructureAA end
        else
            iCatToSearch = AiBotUnitInfo.refCategoryStructure
        end
        local tBuildings = EntityCategoryFilterDown(iCatToSearch, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tBuildings) == false then
            for iUnit, oUnit in tBuildings do
                --Dont assist a part built shield being built for special shielding logic
                if oUnit:GetFractionComplete() < 1 and not(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                    HaveActionToAssign(refActionRepairUnit, 1, 5, oUnit)
                    break
                end
            end
        end
    end

    --Objective buildings
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.reftObjectiveLocation] and AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation]) then
        iTechLevelWanted = (tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjTechLevelWanted] or 1)
        iBPWanted = tiBPByTech[iTechLevelWanted]
        HaveActionToAssign(refActionBuildSpecialObjective, iTechLevelWanted, iBPWanted, tLZTeamData[AiBotMap.reftObjectiveLocation])
    end


    --SPARE ENGINEER ACTIONS----->
    UpdateSpareEngineerNumber(tLZTeamData, toAvailableEngineersByTech)


    --All spare engi actions
    if iHighestTechEngiAvailable > 0 then
        --Build any unbuilt mexes (with more build power than would normally assign)
        iCurPriority = iCurPriority + 1
        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations]) == false then
            iBPWanted = 5 + tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]] * table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefMexUnbuiltLocations])
            if iBPWanted > 10 and bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.1 and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80 then
                iBPWanted = 10
            end
            HaveActionToAssign(refActionBuildMex, 1, iBPWanted)
        end

        --Spare engi - assist any upgrading unit
        iCurPriority = iCurPriority + 1
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false and not(bHaveLowMass) and not(bHaveLowPower) then
            HaveActionToAssign(refActionAssistUpgrade, 1, 1000, nil, true, nil, nil, nil, true)
            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        end

        --Spare engi - reclaim area
        iCurPriority = iCurPriority + 1 --do this after each action
        if iHighestTechEngiAvailable > 0 then
            if tLZData[AiBotMap.subrefTotalMassReclaim] >= 20 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 then
                local bWantEnergy = false
                HaveActionToAssign(refActionReclaimArea, 1, 500, {bWantEnergy, nil}, true, nil, nil, nil, true)
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
            end
        end

        --Spare engi - assist under construction building if we dont have low mass or energy
        iCurPriority = iCurPriority + 1
        if bDebugMessages == true then LOG(sFunctionRef..': Spare engineer action, iHighestTechEngiAvaialble='..iHighestTechEngiAvailable..'; Have low mass='..tostring(bHaveLowMass)..'; Mass stored on team='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Have low power='..tostring(bHaveLowPower)) end
        if iHighestTechEngiAvailable > 0 and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 5000) and not(bHaveLowPower) then
            --Dont assist part complete shields due to risk we are using for active shielding
            local oBuildingToAssist = GetPartCompleteBuildingInZone(iTeam, iPlateau, iLandZone, AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryExperimentalLevel - AiBotUnitInfo.refCategoryFixedShield -categories.NAVAL, false)
            if bDebugMessages == true then LOG(sFunctionRef..': oBuildingToAssist='..(oBuildingToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBuildingToAssist) or 'nil')) end
            if oBuildingToAssist then
                if bDebugMessages == true then LOG(sFunctionRef..': Will assign all remaining engineers to repair building') end
                --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                HaveActionToAssign(refActionRepairUnit, 1,                  300,                oBuildingToAssist, true,                    true, nil, nil, true) --max 300 BP to allow for a very slight spreading of engineers where have lots
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
            end
        end

        --Ctrl-K engineers if have lots and at unit cap and idle
        if iHighestTechEngiAvailable > 0 and aiBrain[AiBotOverseer.refbCloseToUnitCap] == true and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer) >= 150 then
            local bHaveTriedToKillEngineer = false
            local iIdleEngineers = 0
            for iCurEngiTechLevel = 1, 3 do
                iIdleEngineers = table.getn(toAvailableEngineersByTech[iCurEngiTechLevel])
            end
            if iIdleEngineers >= 8 then
                local iKilled
                for iCurEngiTechLevel = 1, 3 do
                    if toAvailableEngineersByTech[iCurEngiTechLevel][1] then
                        iKilled = ConsiderDestroyingLowTechEngineers(toAvailableEngineersByTech[iCurEngiTechLevel][1], 1, toAvailableEngineersByTech[iCurEngiTechLevel])
                        if iKilled > 0 then break end
                    end
                end
            end
        end

        --Spare engi action - go to any nearby land or water zone that wants BP
        iCurPriority = iCurPriority + 1

        if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; If have available engis then will look for other zones wanting them, time='..GetGameTimeSeconds()..'; Is table of other land and water zones by distance empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
        if iHighestTechEngiAvailable > 0 then
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through all other land and water zones, reprs='..reprs(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance])) end
                for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to travel to zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Distance='..tSubtable[AiBotMap.subrefiDistance]) end
                    if tSubtable[AiBotMap.subrefiDistance] <= 500 then
                        local tAdjLZOrWZData, tAdjLZOrWZTeamData
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            tAdjLZOrWZData =AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tAdjLZOrWZTeamData = tAdjLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        else
                            tAdjLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tAdjLZOrWZTeamData = tAdjLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Wnats BP='..tostring(tAdjLZOrWZTeamData[AiBotMap.subrefTbWantBP])..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAdjLZOrWZData[AiBotMap.subrefMidpoint]))..'; Zone plateau='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAdjLZOrWZData[AiBotMap.subrefMidpoint]) or 'nil')..'; iPlateau='..iPlateau) end
                        if tAdjLZOrWZTeamData[AiBotMap.subrefTbWantBP] and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAdjLZOrWZData[AiBotMap.subrefMidpoint]) == iPlateau and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZOrWZData[AiBotMap.subrefMidpoint])) then
                            local iCurBPWanted = 0
                            local iMinTechWanted = 3
                            for iTech, iBP in tAdjLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] do
                                iMinTechWanted = math.min(iMinTechWanted, iTech)
                                iCurBPWanted = iCurBPWanted + iBP
                            end
                            if iCurBPWanted > 0 and iMinTechWanted <= iHighestTechEngiAvailable then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have BP wanted, iCurBPWanted='..iCurBPWanted..'; PlateauorPond='..(tSubtable[AiBotMap.subrefiPlateauOrPond] or 'nil')..'; Land or water zone ref='..(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] or 'nil')..'; Is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone] or false)) end
                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                    --HaveActionToAssign(iActionToAssign,   iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable,                      bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                    HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, iCurBPWanted,      tSubtable[AiBotMap.subrefiLandOrWaterZoneRef],true, true,nil,nil, false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                else
                                    HaveActionToAssign(refActionMoveToLandZone, iMinTechWanted, iCurBPWanted, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], true, true,nil,nil,false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                end
                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                    end
                end
            else
                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
            end
        end

        iCurPriority = iCurPriority + 1
        --Spare engi action - assist air factory if it isnt idle and we dont have low mass
        if iHighestTechEngiAvailable > 0 and not(bHaveLowPower) and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] > 0 and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeAirFacHadNothingToBuild] or -100) <= 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35 then
            local tAirFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tAirFactories) == false then
                --Get the factory  closest to the midpoint
                local iClosestDistOfHighestTech = 100000
                local iHighestTech = 0
                local oClosestFactory
                local iCurDist, iCurTech
                for iUnit, oUnit in tAirFactories do
                    iCurTech = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                    if iCurTech >= iHighestTech then
                        if iCurTech > iHighestTech then
                            iHighestTech = iCurTech
                            iClosestDistOfHighestTech = 100000
                        end
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        if iCurDist < iClosestDistOfHighestTech then
                            iClosestDistOfHighestTech = iCurDist
                            oClosestFactory = oUnit
                        end
                    end
                end
                if oClosestFactory then
                    --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                    HaveActionToAssign(refActionAssistAirFactory, 1,                  10000,                oClosestFactory, true,                    true,                       nil,                         nil,                                true)
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                end
            end
        end
    end

    -- Keep a small, bounded assist crew on the timed air HQ upgrade. The
    -- power deadline below is evaluated afterwards and therefore remains the
    -- stronger job once a T2/T3 engineer becomes available.
    if bDualGapAirHomeOnly
            and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tAirFactories = EntityCategoryFilterDown(
                AiBotUnitInfo.refCategoryAirFactory,
                tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tAirFactories) == false then
            for _, oAirFactory in tAirFactories do
                local bAssistFirstStrat = AiBotUnitInfo.GetUnitTechLevel(oAirFactory) == 3
                        and oAirFactory:IsUnitState('Building')
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH3) > 0
                        and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.TECH3) == 0
                if oAirFactory:IsUnitState('Upgrading') or bAssistFirstStrat then
                    iCurPriority = iCurPriority + 1
                    HaveActionToAssign(refActionAssistAirFactory, 1, bAssistFirstStrat and 80 or 60, oAirFactory)
                    break
                end
            end
        end
    end

    -- Deadline power for dedicated DualGap air slots must be considered after
    -- all generic core-base jobs. Earlier versions inserted this at priority
    -- zero, so practically every normal engineer task replaced it.
    if bDualGapAirHomeOnly then
        iCurPriority = iCurPriority + 1
        local oT3PowerToAssist
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tT3Power = EntityCategoryFilterDown(
                    AiBotUnitInfo.refCategoryPower * categories.TECH3,
                    tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tT3Power) == false then
                for _, oPower in tT3Power do
                    if oPower:GetFractionComplete() < 1 then
                        oT3PowerToAssist = oPower
                        break
                    end
                end
            end
        end
        if oT3PowerToAssist then
            HaveActionToAssign(refActionAssistDualGapT3Power, 1, 100, oT3PowerToAssist)
        elseif GetGameTimeSeconds() >= (aiBrain.AiBotDualGapT3PowerRushTime or 510)
                and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH3) == 0 then
            HaveActionToAssign(refActionBuildPower, 3, 100)
        elseif GetGameTimeSeconds() >= (aiBrain.AiBotDualGapT2PowerRushTime or 300)
                and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH2) == 0 then
            HaveActionToAssign(refActionBuildPower, 2, 20)
        end
    end


    --Localised mex upgrade logic (this is in addition to centralised logic) - intended for games on larger maps - but only if no enemies in adjacent zone
    if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer based mex upgrade logic for zone '..iLandZone..', bHaveLowPower='..tostring(bHaveLowPower)..'; mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Map size='..AiBotMap.iMapSize..'; Enemies in adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Is Active upgrades in this LZ table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; Team gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Is table of mexes on team empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]))..'; Team factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
    if not(bPrioritiseProduction) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 100 or not(bHaveLowPower)) and iActiveMexUpgrades == 0 and (tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0) and AiBotMap.iMapSize >= 256 and (not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or (not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5) and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 or not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 0)) then
        --Do we have T3 factory (or T2 if we have t1 mexes) and either we aren't mass stalling, or we have no mex upgrades at a team level?
        if bDebugMessages == true then LOG(sFunctionRef..': Passed initial checks, checking further') end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 or (not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) and ((tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2)) and (not(bHaveLowMass) or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingMexes]) or tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20)))then
            --Find a mex to upgrade - first try T1 mexes
            local tPotentialMexes
            if tLZTeamData[AiBotMap.subrefMexCountByTech][1] then
                tPotentialMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT1Mex, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            else
                tPotentialMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT2Mex + AiBotUnitInfo.refCategoryT1Mex, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of potential mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialMexes))) end
            if AiBotUtilities.IsTableEmpty(tPotentialMexes) == false then
                for iMex, oMex in tPotentialMexes do
                    if oMex:GetFractionComplete() >= 1 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade mex '..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)) end
                        AiBotEconomy.UpgradeUnit(oMex, true)
                        break
                    end
                end
            end

        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] before general adjustments='..repru(tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])..'; tLZTeamData[AiBotMap.subrefSpareBPByTech]='..repru(tLZTeamData[AiBotMap.subrefSpareBPByTech])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end
function ConsiderMinorLandZoneEngineerAssignment(tLZTeamData, iTeam, iPlateau, iLandZone, tEngineers)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderMinorLandZoneEngineerAssignment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bDontCheckPlayableArea = false
    if AiBotMap.bIsCampaignMap then
        bDontCheckPlayableArea = true
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] then bDontCheckPlayableArea = false end
    end

    --if bDebugMessages == true then AiBotMap.DrawSpecificLandZone(iPlateau, iLandZone, 1) end
    local iBPWanted
    local bHaveLowMass = AiBotConditions.TeamHasLowMass(iTeam)
    local bHaveLowPower = AiBotConditions.HaveLowPower(iTeam)
    local bWantMorePower = AiBotConditions.WantMorePower(iTeam)
    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]

    local bAdjacentToCoreZone
    local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
    local bPrioritiseProduction = AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refbPrioritiseProduction]
    local bDualGapAirHomeOnly = aiBrain.AiBotDualGapRole == 'top_air'
            or aiBrain.AiBotDualGapRole == 'bottom_air'
            or aiBrain.AiBotDualGapRole == 'eco'

    local iNearbyEnemyAirToGroundThreat = tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
    --For now only do land zone not water zone given water zone includes torp bombers
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
            iNearbyEnemyAirToGroundThreat = iNearbyEnemyAirToGroundThreat + tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
            if tAdjLZTeamData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then bAdjacentToCoreZone = true end
        end
    end


    local toAvailableEngineersByTech, toAssignedEngineers = FilterToAvailableEngineersByTech(tEngineers, false, tLZData, tLZTeamData, iTeam, iPlateau, iLandZone)
    tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] = {[1]=0,[2]=0,[3]=0}

    if bDualGapAirHomeOnly and not AiBotDualGap.IsAirHomeMexZone(aiBrain, tLZData[AiBotMap.subrefLZOrWZMexLocations]) then
        return
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Non core LZ - Have just reset BPByTech to 0 for Plateau'..iPlateau..'; LZ='..iLandZone..'; repru='..repru(tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])..'; subrefLZCoreExpansion='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; subrefbCoreBaseOverride='..tostring(tLZTeamData[AiBotMap.subrefbCoreBaseOverride] or false)..'; LZTeamData Allied nonAiBot mex count='..(tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] or 'nil')..'; Allied NonAiBot factory count='..(tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateau][iLandZone]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateau][iLandZone] or 'nil')) end
    local bTeammateHasBuiltHere = false
    if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 then
        if bDebugMessages == true then LOG(sFunctionRef..': Teammate mex count='..tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount]..'; iTeam='..iTeam..'; Factory count='..tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount]..'; LZ mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]) end
        if (tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] or 0) >= tLZData[AiBotMap.subrefLZOrWZMexCount]
                or ((tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) > 0 and (tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] or 0) >= (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) * 0.5) then
            bTeammateHasBuiltHere = true
            if bDebugMessages == true then LOG(sFunctionRef..': Since teammate has all the mexes or half plus factories will treat them as owning this zone and wont try and build much here') end
        elseif not(AiBotUnitInfo.bDontConsiderCombinedArmy) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbContainsPureAiBotAndSharedAiBot] and tLZTeamData[AiBotMap.subrefLZSValue] > 30 then
            local tMexesInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tMexesInZone) == false then
                local iHumanMexCount = 0
                for iMex, oMex in tMexesInZone do
                    if not(oMex.AiBotActive) then iHumanMexCount = iHumanMexCount + 1 end
                end
                if iHumanMexCount >= tLZData[AiBotMap.subrefLZOrWZMexCount] -1 and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or iHumanMexCount == tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                    bTeammateHasBuiltHere = true
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering shared army whether teammate has built here, iHumanMexCount='..iHumanMexCount..'; bTeammateHasBuiltHere='..tostring(bTeammateHasBuiltHere)) end
            end
        end


    elseif tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] > 0 then
        bTeammateHasBuiltHere = true
    end

    local bEngineersRecentlyRunFromEnemy = false
    if tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] <= 20 then bEngineersRecentlyRunFromEnemy = true end
    if bDebugMessages == true then LOG(sFunctionRef..': bTeammateHasBuiltHere='..tostring(bTeammateHasBuiltHere)..'; P'..iPlateau..'Z'..iLandZone) end
    -- (tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] >= tLZData[AiBotMap.subrefLZOrWZMexCount] tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] > 0 and (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] >= 3 or
    --local iCurCondition = 0
    local iCurPriority = 0



    function HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
        --Done as subfunction for convenience so can just note the key values for the action in question and add on the others that wont change
        ConsiderActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iCurPriority, tLZData, tLZTeamData, iTeam, iPlateau, iLandZone, toAvailableEngineersByTech, toAssignedEngineers, false, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    end

    if bDualGapAirHomeOnly and GetGameTimeSeconds() >= (aiBrain.AiBotDualGapT2PowerRushTime or 330)
            and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower * categories.TECH2) == 0 then
        HaveActionToAssign(refActionBuildPower, 2, 10)
    end

    --Active gameender template - want to always have 1 engi on duty as highest priority to avoid having orders cancelled
    iCurPriority = iCurPriority + 1
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (not(bPrioritiseProduction) or (not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4)) and AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZTeamData) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        HaveActionToAssign(refActionManageGameEnderTemplate, 3, 25)
    end


    --Land fac if this is an island with no core LZs - also set this as the primary if no such LZ
    iCurPriority = iCurPriority + 1
    local iHighestTechEngiAvailable
    local bExpansionOnSameIslandAsBase = false

    if bDebugMessages == true then LOG(sFunctionRef..': do we want this zone as an expansion point? iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Time='..GetGameTimeSeconds()..'; tLZTeamData[AiBotMap.subrefLZCoreExpansion]='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; tLZTeamData[AiBotMap.subrefLZCoreExpansion] is nil='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] == nil)..'; tLZTeamData[AiBotMap.subrefLZExpansionOverride]='..tostring(tLZTeamData[AiBotMap.subrefLZExpansionOverride] or false)..'; tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][1]='..(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][1] or 'nil')) end
    if tLZTeamData[AiBotMap.subrefLZCoreExpansion] == nil or (tLZTeamData[AiBotMap.subrefLZExpansionOverride] and not(tLZTeamData[AiBotMap.subrefLZCoreExpansion])) then
        if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
            local iEnemyBaseStraightLineDist = 200
            local iTravelLimit = 600 --If takes more than this to travel to the nearest friendly base, and we are more than iEnemyBaseStraightLineDist from the nearest enemy base on a straight line basis, then will consider a land expansion point

            bExpansionOnSameIslandAsBase = false
            if tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) then
                bExpansionOnSameIslandAsBase = true
                if not(bDontCheckPlayableArea) then
                    bExpansionOnSameIslandAsBase = false
                    --Check we can actually travel here by land
                    local iNearestBasePlateau, iNearestBaseLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                    if (iNearestBaseLandZone or 0) > 0 then
                        local iEntryNumber = tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iNearestBaseLandZone]
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': iEntryNumber='..(iEntryNumber or 'nil')..'; iNearestBasePlateau='..(iNearestBasePlateau or 'nil')..'; LZ Ref based on this entry number='..(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZNumber] or 'nil')..'; iNearestBaseLandZone='..iNearestBaseLandZone)
                            if not(iEntryNumber) then LOG(sFunctionRef..': Dont have a ref for iNearestBaseLandZone='..iNearestBaseLandZone..'; All refs='..repru(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef])) end
                        end
                        if iEntryNumber then
                            local tTravelPath = tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZPath]
                            if bDebugMessages == true then LOG(sFunctionRef..': tTravelPath='..repru(tTravelPath)) end
                            if AiBotUtilities.IsTableEmpty(tTravelPath) == false then
                                bExpansionOnSameIslandAsBase = true
                                for iPath, iPathLZ in tTravelPath do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iPathLZ='..iPathLZ..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefMidpoint]))) end
                                    if not(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefMidpoint])) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': iPathLZ is not in the playable area so dont want to make this an expansion') end
                                        bExpansionOnSameIslandAsBase = false
                                        break
                                    end
                                end
                                if bExpansionOnSameIslandAsBase then
                                    --Still consider as expansion point if far away
                                    if bDebugMessages == true then LOG(sFunctionRef..': Expansion is on same island as base, checking if it is still really far away such that we want to considera n expansion point, travel dist='..tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZTravelDist]..'; Dist to enemy base (straight line)='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])) end
                                    if tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZTravelDist] >= iTravelLimit and AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) >= iEnemyBaseStraightLineDist then
                                        bExpansionOnSameIslandAsBase = false
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': tLZData[AiBotMap.subrefLZOrWZMexCount]='..(tLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')..'; Island mex count='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] or 'nil')..'; bExpansionOnSameIslandAsBase='..tostring(bExpansionOnSameIslandAsBase or false)..'; tLZData[AiBotMap.subrefLZIslandRef]='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Closest firendly base island ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) or 'nil')) end
            if (tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 or (AiBotMap.bIsCampaignMap and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] >= 4)) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] >= 3 and not(bExpansionOnSameIslandAsBase) then
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
                if iHighestTechEngiAvailable > 0 then
                    local bHaveCoreLZ = false
                    for iEntry, iIslandLZ in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][tLZData[AiBotMap.subrefLZIslandRef]] do
                        if AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIslandLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] or AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIslandLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZCoreExpansion] then
                            if bDebugMessages == true then LOG(sFunctionRef..': iIslandlZ'..iIslandLZ..' in the island '..tLZData[AiBotMap.subrefLZIslandRef]..' is either a core base or expansion, Is core base='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIslandLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] or false)..'; Is core expansion='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iIslandLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZCoreExpansion] or false)..'; bDontCheckPlayableArea='..tostring(bDontCheckPlayableArea)) end
                            if bDontCheckPlayableArea then
                                bHaveCoreLZ = true
                                break
                            else
                                --Check we can actually travel here by land and it isn't too far away
                                local iEntryNumber = tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iIslandLZ]
                                if bDebugMessages == true then LOG(sFunctionRef..': iEntryNumber='..(iEntryNumber or 'nil')..'; LZ Ref based on this entry number='..(tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZNumber] or 'nil')..'; iIslandLZ='..iIslandLZ) end
                                if iEntryNumber then
                                    local tTravelPath = tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZPath]
                                    if bDebugMessages == true then LOG(sFunctionRef..': tTravelPath='..repru(tTravelPath)) end
                                    if AiBotUtilities.IsTableEmpty(tTravelPath) == false then
                                        bHaveCoreLZ = true
                                        for iPath, iPathLZ in tTravelPath do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iPathLZ='..iPathLZ..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefMidpoint]))) end
                                            if not(AiBotConditions.IsLocationInPlayableArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iPathLZ][AiBotMap.subrefMidpoint])) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': iPathLZ is not in the playable area so dont think we have a core LZ after all') end
                                                bHaveCoreLZ = false
                                                break
                                            end
                                        end
                                        if bHaveCoreLZ then
                                            --Ignore if this location is far away
                                            if tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZTravelDist] >= iTravelLimit then
                                                bHaveCoreLZ = false
                                            end
                                            if bHaveCoreLZ then
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Updating core expansion flag, bHaveCoreLZ='..tostring(bHaveCoreLZ)..'; Have override='..tostring(tLZTeamData[AiBotMap.subrefLZExpansionOverride] or false)) end
                    if not(bHaveCoreLZ) or tLZTeamData[AiBotMap.subrefLZExpansionOverride] then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will set this location as the core expansion location') end
                        --Build a land factory
                        tLZTeamData[AiBotMap.subrefLZCoreExpansion] = true
                    else
                        tLZTeamData[AiBotMap.subrefLZCoreExpansion] = false
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will update core expansion flag, tLZTeamData[AiBotMap.subrefLZExpansionOverride]='..tostring(tLZTeamData[AiBotMap.subrefLZExpansionOverride] or false)) end
                if tLZTeamData[AiBotMap.subrefLZExpansionOverride] then
                    tLZTeamData[AiBotMap.subrefLZCoreExpansion] = true
                else
                    tLZTeamData[AiBotMap.subrefLZCoreExpansion] = false
                end
            end
        end
    elseif tLZTeamData[AiBotMap.subrefLZCoreExpansion] and not(bExpansionOnSameIslandAsBase) then
        --Need to calculate if are on same island
        local iBaseIslandRef = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase])
        if iBaseIslandRef == tLZData[AiBotMap.subrefLZIslandRef] then
            bExpansionOnSameIslandAsBase = true
        end
    end

    local iFactoriesWanted = 0
    local iExistingFactory
    function GetExistingFactoryNumber()
        if not(iExistingFactory) then
            iExistingFactory = 0
            local tExistingFactory = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tExistingFactory) == false then
                for iUnit, oUnit in tExistingFactory do
                    if oUnit:GetFractionComplete() == 1 then
                        bExistingFactoryIsComplete = true
                        iExistingFactory = iExistingFactory + 1
                        if AiBotUnitInfo.GetUnitTechLevel(oUnit) >= 2 then
                            iExistingFactory = iExistingFactory + 1
                        end
                    end
                end
            end
            return iExistingFactory
        else
            return iExistingFactory
        end
    end
    local bExistingFactoryIsComplete = false
    if bDebugMessages == true then LOG(sFunctionRef..': About to determine factories wanted, tLZTeamData[AiBotMap.subrefLZCoreExpansion]='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; bAdjacentToCoreZone='..tostring(bAdjacentToCoreZone or false)..'; bHaveLowMass='..tostring(bHaveLowMass or false)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
    if tLZTeamData[AiBotMap.subrefLZCoreExpansion] or tLZTeamData[AiBotMap.subrefLZFortify] then
        if not(bTeammateHasBuiltHere) and (tLZTeamData[AiBotMap.subrefLZCoreExpansion] or (not(bHaveLowMass) and (bAdjacentToCoreZone and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 750) or (AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam) and ((bAdjacentToCoreZone and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.75 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or tLZData[AiBotMap.subrefLZOrWZMexCount] >= 4) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3))) then
            iFactoriesWanted = math.min(4, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] - 2)
            local iIslandZoneCount = table.getn(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][tLZData[AiBotMap.subrefLZIslandRef]])
            if bExpansionOnSameIslandAsBase then
                iFactoriesWanted = math.max(1, math.min(4, iFactoriesWanted, tLZData[AiBotMap.subrefLZOrWZMexCount] - 2))
                if not(bHaveLowMass) and AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam) then iFactoriesWanted = iFactoriesWanted + 1 end
                --Consider getting more factories if enemy has nearby factories, i.e. factor in adjacent zones
                if (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.2 and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] >= 8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 100 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= math.min(5, tLZData[AiBotMap.subrefLZOrWZMexCount]))) and not(bAdjacentToCoreZone) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 2 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber - categories.TECH1) <= 15)) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 50 then
                    local iMexesIncludingAdjacentZones = tLZData[AiBotMap.subrefLZOrWZMexCount]
                    local bEnemyHasCombatOrFactory = tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]
                    local iEnemyNetCombatThreat = (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                        iMexesIncludingAdjacentZones = iMexesIncludingAdjacentZones + tAdjLZData[AiBotMap.subrefLZOrWZMexCount]
                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                        iEnemyNetCombatThreat = iEnemyNetCombatThreat + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                        if not(bEnemyHasCombatOrFactory) then
                            if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 20 then
                                bEnemyHasCombatOrFactory = true
                            elseif AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])) == false then
                                bEnemyHasCombatOrFactory = true
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': P'..iPlateau..'Z'..iLandZone..': bEnemyHasCombatOrFactory='..tostring(bEnemyHasCombatOrFactory or false)..'; iMexesIncludingAdjacentZones='..iMexesIncludingAdjacentZones..'; iEnemyNetCombatThreat='..iEnemyNetCombatThreat) end
                    if bEnemyHasCombatOrFactory and iMexesIncludingAdjacentZones >= 6 and iEnemyNetCombatThreat <= 1000 then
                        --Dont get more factories if enemy ACU is relatively close since will likely be wasted mass
                        local iClosestEnemyACU = 100000
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                            for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                                if not(oEnemyACU.Dead) then
                                    iClosestEnemyACU = math.min(iClosestEnemyACU, AiBotUtilities.GetDistanceBetweenPositions(oEnemyACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]))
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemyACU='..iClosestEnemyACU) end
                        if iClosestEnemyACU > 200 then
                            iFactoriesWanted = math.max(iFactoriesWanted, 3, math.min(5, iMexesIncludingAdjacentZones * 0.5))
                        end
                    end
                end

            else
                if iIslandZoneCount < 4 then iFactoriesWanted = math.max(1, math.min(iFactoriesWanted, iIslandZoneCount * 0.5)) end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iIslandZoneCount='..iIslandZoneCount..'; iFactoriesWanted pre adj='..iFactoriesWanted) end
            if (iIslandZoneCount > 2 or tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bWantMorePower) and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 then
                if bDebugMessages == true then LOG(sFunctionRef..': Likely want an extra factory, bExpansionOnSameIslandAsBase='..tostring(bExpansionOnSameIslandAsBase)..'; Map size='..AiBotMap.iMapSize..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Dist to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Mass%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Enemies in this or adj LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Can path to enemy with land='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])) end
                if not(bExpansionOnSameIslandAsBase) or (AiBotMap.iMapSize >= 750 and (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.5 or AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 200 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 or (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]))) then
                    iFactoriesWanted = iFactoriesWanted + 1
                    if bDebugMessages == true then LOG(sFunctionRef..': Increasing factories wanted by 1') end
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 then
                    if not(bExpansionOnSameIslandAsBase) or AiBotMap.iMapSize >= 750 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 then
                        iFactoriesWanted = iFactoriesWanted + math.max(1, iFactoriesWanted / 3)
                        if bDebugMessages == true then LOG(sFunctionRef..': Increasing factories wanted by higher of 1 and 1/3') end
                    end
                end
            end
            if iFactoriesWanted >= 1 and ((bExpansionOnSameIslandAsBase and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap]) and not(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone)) then
                if bDebugMessages == true then LOG(sFunctionRef..': We dont actually want more factories in this zone, so limiting factories wanted to just 1 (or 2 if lots of mexes and we wanted 4+') end
                if tLZData[AiBotMap.subrefLZOrWZMexCount] >= 4 and (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 or iFactoriesWanted >= 4) then
                    iFactoriesWanted = math.min(3, math.max(1, iFactoriesWanted * 0.6))
                else
                    iFactoriesWanted = 1
                end
            end
            if iFactoriesWanted < 4 and tLZTeamData[AiBotMap.subrefLZFortify] then
                if not(bHaveLowMass) then iFactoriesWanted = 4
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8 then
                    iFactoriesWanted = 3
                else
                    iFactoriesWanted = 2
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Increasing factories wanted due to fortification desire') end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iFactoriesWanted='..iFactoriesWanted..'; bWantMorePower='..tostring(bWantMorePower)..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Map size='..AiBotMap.iMapSize..'; bExpansionOnSameIslandAsBase='..tostring(bExpansionOnSameIslandAsBase)..'; Island mex count='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]]..'; LZ mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]) end
            if iFactoriesWanted > 2 then
                --Does enemy have any units/threats on this island within a certain range?
                local bEnemyHasDangerousUnitsOnIsland = tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]
                if not(bEnemyHasDangerousUnitsOnIsland) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                    local iAdjLZ
                    for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                        iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Travel dist='..tPathingDetails[AiBotMap.subrefLZTravelDist]..'; Does it want DF support='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport])) end
                        if tPathingDetails[AiBotMap.subrefLZTravelDist] < 275 then
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])) end
                            if tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                                bEnemyHasDangerousUnitsOnIsland = true
                                break
                            end
                        end
                    end
                end
                if not(bEnemyHasDangerousUnitsOnIsland) then
                    if iFactoriesWanted > 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 then
                        iFactoriesWanted = 3
                    else
                        iFactoriesWanted = 2 --only here if we have >=2 factories wanted
                    end
                end
            end
            if bHaveLowMass then iFactoriesWanted = math.max(1, math.floor(iFactoriesWanted * 0.5)) end
            if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then iFactoriesWanted = math.max(1, math.floor(iFactoriesWanted * 0.5)) end
            if bDebugMessages == true then LOG(sFunctionRef..': iFactoriesWanted after adjusting for enemy units='..iFactoriesWanted..'; iExistingFactory='..(iExistingFactory or 'nil')) end
        elseif tLZTeamData[AiBotMap.subrefLZFortify] then
            if not(bHaveLowMass) then iFactoriesWanted = 4
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8 then
                iFactoriesWanted = 3
            else
                iFactoriesWanted = 2
            end
            if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy] then iFactoriesWanted = math.max(1, math.floor(iFactoriesWanted * 0.5)) end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Factories wanted after considering='..iFactoriesWanted) end
    elseif tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and not(bAdjacentToCoreZone) then
        if bDebugMessages == true then LOG(sFunctionRef..': Zone has lots of mexes even though it isnt an expansino zone, consider if we want land fac for it, mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]) end
        if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 4 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.2) then
            --Can we path to enemy base with land and lack T3 air, or is our mod dist relatively high?
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 and (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) == tLZData[AiBotMap.subrefLZIslandRef] or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25) then
                if bDebugMessages == true then LOG(sFunctionRef..': Do we want more factories='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone, false))) end
                if AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone, false) then
                    iFactoriesWanted = 1
                    if not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and not(aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy]) then iFactoriesWanted = 2 end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Factories wanted for non core expansion='..iFactoriesWanted) end
    end
    if iFactoriesWanted > 1 and bHaveLowPower and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
        if bDebugMessages == true then LOG(sFunctionRef..': Stalling energy so reducing factories wanted to 1') end
        iFactoriesWanted = 1
    end
    if bEngineersRecentlyRunFromEnemy and iFactoriesWanted > 1 then iFactoriesWanted = 1 end
    --TMD if we have recently lost a building to enemy TML - have 1 engineer assigned as top priority (will assign more later on)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': highest priority TMD builder, is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))..'; Enemy air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; subrefLZOrWZThreatAllyGroundAA='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; Enemy combat total='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; subrefLZThreatAllyMobileDFTotal='..tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]..'; Time since subrefiTimeOfLastBuildingDeathToTML='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] or 0)) end
    if tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeOfLastBuildingDeathToTML] <= 90 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] <= tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] * 0.5 then
        local oUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone)
        if bDebugMessages == true then LOG(sFunctionRef..': Is oUnitWantingTMD valid unit='..tostring(AiBotUnitInfo.IsUnitValid(oUnitWantingTMD))) end
        if oUnitWantingTMD then
            iBPWanted = tiBPByTech[2]
            local bSaveMassForMML, bWantT3LandForRavagers = AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tLZData, tLZTeamData, iPlateau, iTeam, bHaveLowMass)
            if bSaveMassForMML then
                iBPWanted = iBPWanted * 0.5
            end
            if bEngineersRecentlyRunFromEnemy then
                iBPWanted = iBPWanted * 0.5
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Want to build TMD as top priority, iBPWanted='..iBPWanted..'; Unit wanting TMD='..oUnitWantingTMD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitWantingTMD)) end
            HaveActionToAssign(refActionBuildTMD, 2, iBPWanted, oUnitWantingTMD)
        end
    end


    --Do we want emergency PD?
    if bDebugMessages == true then LOG(sFunctionRef..': Considering emergency PD for zone '..iLandZone..', iExistingFactory='..(iExistingFactory or 'nil')..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Enemies in this or adj LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Ally AA threat='..(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)..'; SValue='..(tLZTeamData[AiBotMap.subrefLZSValue] or 0)) end
    if not(bTeammateHasBuiltHere) and ((tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and (GetExistingFactoryNumber() >= 1 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 2 + tLZTeamData[AiBotMap.subrefMexCountByTech][1] * 0.35) >= 2) and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) <= math.min(350, 0.5*(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0))) and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 120 or (not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))) then
        --Does enemy have any units that can outrange a PD? If so then dont bother building
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then
            local iHighestNearbyEnemyRange = math.max((tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0), tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0)
            local bConsiderT2PD = false
            local bConsiderT3PD = false
            if bDebugMessages == true then LOG(sFunctionRef..': iHighestNearbyEnemyRange='..iHighestNearbyEnemyRange..'; Highest friendly land fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Active brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; Mex count by tehc='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; LZ s value='..tLZTeamData[AiBotMap.subrefLZSValue]..'; Mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]) end
            if iHighestNearbyEnemyRange <= AiBotBuilding.tiWorstPDRangeByTech[2] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 1 or (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 4 and tLZTeamData[AiBotMap.subrefLZSValue] >= 500)) and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1) then bConsiderT2PD = true end
            --T3 PD - ravagers have 70 range, so want to consider if enemy range this or worse
            if iHighestNearbyEnemyRange <= AiBotBuilding.tiWorstPDRangeByTech[3] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.max(1, math.min(2, tLZData[AiBotMap.subrefLZOrWZMexCount])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 then bConsiderT3PD = true end
            if iHighestNearbyEnemyRange <= AiBotBuilding.tiWorstPDRangeByTech[1] or bConsiderT2PD then
                local iEnemyCombatThreat = (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                        iHighestNearbyEnemyRange = math.max(iHighestNearbyEnemyRange, (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0), tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0)
                        iEnemyCombatThreat = iEnemyCombatThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)
                    end
                end
                if iEnemyCombatThreat >= 25 then
                    if bConsiderT2PD then
                        if iHighestNearbyEnemyRange > AiBotBuilding.tiWorstPDRangeByTech[2] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 2 then bConsiderT2PD = false
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 then
                            --Do we have T2 factories or engineers of any kind in this zone?
                            local tT2Units = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            local bHaveT2FactoriesOrEngineers = false
                            if AiBotUtilities.IsTableEmpty(tT2Units) == false then
                                for iUnit, oUnit in tT2Units do
                                    if oUnit:GetFractionComplete() == 1 then
                                        bHaveT2FactoriesOrEngineers = true
                                        break
                                    end
                                end
                            end
                            if not(bHaveT2FactoriesOrEngineers) then bConsiderT2PD = false end
                        end
                    end
                    if bConsiderT3PD then
                        --Do we have T3 factories or engineers of any kind in this zone?
                        local tT3Units = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory - categories.TECH1 + categories.TECH2, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        local bHaveT3FactoriesOrEngineers = false
                        if AiBotUtilities.IsTableEmpty(tT3Units) == false then
                            for iUnit, oUnit in tT3Units do
                                if oUnit:GetFractionComplete() == 1 then
                                    if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or EntityCategoryContains(categories.UEF, oUnit.UnitId) then
                                        bHaveT3FactoriesOrEngineers = true
                                        break
                                    end
                                end
                            end
                        end
                        if not(bHaveT3FactoriesOrEngineers) then bConsiderT3PD = false end
                    end
                    if iHighestNearbyEnemyRange <= AiBotBuilding.tiWorstPDRangeByTech[1] or bConsiderT2PD or bConsiderT3PD then
                        local iExistingStructureThreat = 0
                        local bHaveLRPDThreat = false
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                                iExistingStructureThreat = iExistingStructureThreat + iThreat
                                if iThreat > 0 and iRange >= 50 then bHaveLRPDThreat = true end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iExistingStructureThreat of existing PD='..iExistingStructureThreat..'; will get emergency PD if below threshold, iEnemyCombatThreat='..iEnemyCombatThreat..'; bConsiderT2PD='..tostring(bConsiderT2PD or false)) end
                        local iMinTechLevelWanted = 1
                        iBPWanted = 40
                        if bConsiderT2PD and iExistingStructureThreat >= 400 then
                            iMinTechLevelWanted = 2
                            iBPWanted = 60
                        elseif bConsiderT3PD and iExistingStructureThreat >= 1200 then
                            iMinTechLevelWanted = 3
                            iBPWanted = 80
                        end

                        if iExistingStructureThreat < 400 or (bConsiderT2PD and iExistingStructureThreat < math.max(800, math.max(iEnemyCombatThreat, math.min(iEnemyCombatThreat * 2, 2880)))) or (not(bConsiderT2PD) and iExistingStructureThreat < math.min(800, iEnemyCombatThreat * 3))
                                or (bConsiderT3PD and iExistingStructureThreat < math.max(1250, math.max(iEnemyCombatThreat, math.min(iEnemyCombatThreat * 2, 2880))))
                        then
                            --Get T1 radar in priority to T2 PD if we already have T2 PD but no radar
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to get t1 radar instead of t2 pd, bHaveLRPDThreat='..tostring(bHaveLRPDThreat)..'; Stalling energy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Want land scout='..tostring(tLZTeamData[AiBotMap.refbWantLandScout])..'; iExistingStructureThreat='..iExistingStructureThreat..'; Enemy combat='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)) end
                            local bTryingToBuildT1Radar = false
                            if bHaveLRPDThreat and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and tLZTeamData[AiBotMap.refiRadarCoverage] <= math.min(50, math.max(40, AiBotUnitInfo.iT1RadarSize - 50)) and (tLZTeamData[AiBotMap.refbWantLandScout] or ((tLZTeamData[AiBotMap.refiRadarCoverage] == 0 or iExistingStructureThreat >= 2000) and iExistingStructureThreat >= 1000 and iExistingStructureThreat >= (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0))) and iExistingStructureThreat * 1.5 >= (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) then
                                if bDebugMessages == true then LOG(sFunctionRef..': will get t1 radar (or T2 if close to unit cap and can build t2), iBPWanted='..iBPWanted) end
                                HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted)
                                bTryingToBuildT1Radar = true
                            end
                            --If close to unit cap we might not build the radar
                            if not(bTryingToBuildT1Radar) or aiBrain[AiBotOverseer.refbCloseToUnitCap] then
                                local tPDStartPoint
                                if iExistingStructureThreat <= 800 then tPDStartPoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                                else
                                    tPDStartPoint = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), 25, true, false, AiBotMap.bIsCampaignMap)
                                    if not(tPDStartPoint) or not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tPDStartPoint) == tLZData[AiBotMap.subrefLZIslandRef]) then  tPDStartPoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]} end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build emergency PD, iMinTechLevelWanted='..iMinTechLevelWanted..'; bConsiderT2PD='..tostring(bConsiderT2PD or false)..'; iExistingStructureThreat='..(iExistingStructureThreat or 'nil')..'; tPDStartPoint='..repru(tPDStartPoint)) end
                                HaveActionToAssign(refActionBuildEmergencyPD, iMinTechLevelWanted, iBPWanted, tPDStartPoint)
                            end
                        end
                    end
                end
            end
        end
    end

    --Anti-teleport PD builder
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) == false then
        --Are any teleport targets within 70 of this zone midpoint? If so then build emergency PD, and base the PD location on the teleport location (but move a bit towards this zone's midpoint from the actual teleport location)
        local iClosestTeleportDist = 70
        local iCurTeleportDist
        local tClosestTeleport
        for iEntry, tTeleportData in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails] do
            iCurTeleportDist = AiBotUtilities.GetDistanceBetweenPositions(tTeleportData[AiBotTeam.subreftTeleportTarget], tLZData[AiBotMap.subrefMidpoint])
            if iCurTeleportDist < iClosestTeleportDist then
                iClosestTeleportDist = iCurTeleportDist
                tClosestTeleport = {tTeleportData[AiBotTeam.subreftTeleportTarget][1], tTeleportData[AiBotTeam.subreftTeleportTarget][2], tTeleportData[AiBotTeam.subreftTeleportTarget][3]}
            end
        end
        if tClosestTeleport then
            iBPWanted = 60
            HaveActionToAssign(refActionBuildEmergencyPD, 1, iBPWanted, AiBotUtilities.MoveInDirection(tClosestTeleport, AiBotUtilities.GetAngleFromAToB(tClosestTeleport, tLZData[AiBotMap.subrefMidpoint]), 10, true))
        end
    end

    --Priority repair for campaign objective if it is low health
    if AiBotMap.bIsCampaignMap then
        iCurPriority = iCurPriority + 1
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]) == false then
            local oUnitToTarget
            for iUnit, oUnit in tLZData[AiBotMap.subreftoUnitsToRepair] do
                if not(oUnit.Dead) and AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.1 then
                    if oUnitToTarget[refbDontIncludeAsPartCompleteBuildingForConstruction] then
                        --Remove unit from UnitsToRepair
                        for iUnit, oUnit in tLZData[AiBotMap.subreftoUnitsToRepair] do
                            if oUnit == oUnitToTarget then
                                table.remove(tLZData[AiBotMap.subreftoUnitsToRepair], iUnit)
                                break
                            end
                        end
                    else
                        oUnitToTarget = oUnit
                        break
                    end
                end
            end
            if oUnitToTarget then
                if bDebugMessages == true then LOG(sFunctionRef..': Unit to repair as priority='..oUnitToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToTarget)..'; health='..oUnitToTarget:GetHealth()..'; health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnitToTarget)..'; will flag we want some BP for this') end
                HaveActionToAssign(refActionRepairUnit, 1, 5, oUnitToTarget)
            end
        end
    end

    --Consider making a zone with lots of mexes a core expansion in some cases in the early game
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': LZ mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Air fac tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]..'; Team mass stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored]..'; Active brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; P='..iPlateau..'Z='..iLandZone..'; subrefTotalSignificantMassReclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]) end
    if not(bEngineersRecentlyRunFromEnemy) and not(tLZTeamData[AiBotMap.subrefLZCoreExpansion]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        local bLotsOfReclaim = false
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 4000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] then bLotsOfReclaim = true end
        if ((tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2) or (AiBotMap.bIsCampaignMap and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 and tLZTeamData[AiBotMap.subrefLZSValue] > 0 and GetGameTimeSeconds() >= 1800) or ((bLotsOfReclaim or (tLZData[AiBotMap.subrefLZOrWZMexCount] < 3 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 4000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] - tLZData[AiBotMap.subrefLZOrWZMexCount] * 1000)) and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]))) and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 150 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > 0 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.5 + 2.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))) then
            if not(bTeammateHasBuiltHere) or tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] < 2 or tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] <= math.max(5, tLZData[AiBotMap.subrefLZOrWZMexCount] * 0.75) then
                if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.1 or tLZData[AiBotMap.subrefLZOrWZMexCount] >= 5 then
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; bLotsOfReclaim='..tostring(bLotsOfReclaim)) end
                    if iHighestTechEngiAvailable > 0 then
                        --Check we can path to closest enemy base or there's enough reclaim to justify a factory anyway
                        if bDebugMessages == true then LOG(sFunctionRef..': Island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Nearest enemy base island ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or 'nil')) end
                        if tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or bLotsOfReclaim then
                            --Check we are closer to enemy base than closest friendly base (or have enough reclaim here to justify the factory)
                            local iOurDistToEnemy = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])
                            if bDebugMessages == true then LOG(sFunctionRef..': iOurDistToEnemy='..iOurDistToEnemy..'; Map size='..AiBotMap.iMapSize..'; Dist from closest friendly base to enemy='..AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Factories in adj zone='..AiBotConditions.GetNumberOfUnitsOfCategoryInAdjacentLandZones(tLZData, iPlateau, iTeam, AiBotUnitInfo.refCategoryFactory, true, true)..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)) end
                            if bLotsOfReclaim or iOurDistToEnemy < math.min(650, AiBotMap.iMapSize * 1.1) or (AiBotMap.bIsCampaignMap and iOurDistToEnemy <= 800 and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                                local iClosestFriendlyBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                if bLotsOfReclaim or iClosestFriendlyBaseDist > iOurDistToEnemy or (AiBotMap.bIsCampaignMap and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                                    --If no mexes and campaign map then also require no land facs in an adjacent zone
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will proceed if have mexes, arent campaign map, or no factories in adj zone') end
                                    if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 or not(AiBotMap.bIsCampaignMap) or AiBotConditions.GetNumberOfUnitsOfCategoryInAdjacentLandZones(tLZData, iPlateau, iTeam, AiBotUnitInfo.refCategoryFactory, true, true) == 0 then
                                        tLZTeamData[AiBotMap.subrefLZExpansionOverride] = true
                                        tLZTeamData[AiBotMap.subrefLZCoreExpansion] = true
                                        iFactoriesWanted = math.max(iFactoriesWanted, 1)
                                        if bDebugMessages == true then LOG(sFunctionRef..': setting this zone as being a core expansion with iFactoriesWanted='..iFactoriesWanted) end
                                    end
                                end
                            end
                        end
                    end
                end
                if (iFactoriesWanted or 0) == 0 and bLotsOfReclaim then
                    iFactoriesWanted = 1
                    if bDebugMessages == true then LOG(sFunctionRef..': Want 1 land fac to help get reclaim') end
                end
            end
        end
        --Islands we have dropped on that have 4+ mexes and no start position
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have dropped here recently and it is an island with lots of mexes, island mex count='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] or 'nil')..'; Time last dropped='..(GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeLastDroppedEngi] or 0))) end
        if not(tLZTeamData[AiBotMap.subrefLZExpansionOverride]) and ((tLZTeamData[AiBotMap.refiTimeLastDroppedEngi] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeLastDroppedEngi] <= 180 and tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] >= 4) or (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] >= 5 and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 and not(tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase])))) then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to get land fac unless have nearby enemy base, tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Island ref='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; Nearest enemy base island ref='..NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase])) end
            if tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 or not(tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase])) then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to build at least 1 factory here') end
                tLZTeamData[AiBotMap.subrefLZExpansionOverride] = true
                tLZTeamData[AiBotMap.subrefLZCoreExpansion] = true
                iFactoriesWanted = math.max(1, (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] - 1) / 3)
            end
        end
    end
    --Paragon - always want at least 1 factory in every minor LZ
    if aiBrain[AiBotEconomy.refbBuiltParagon] and not(bTeammateHasBuiltHere) and iFactoriesWanted <= 0 and tLZData[AiBotMap.subrefLZTotalSegmentCount] >= 20 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 1 then iFactoriesWanted = math.max(iFactoriesWanted, 1) end
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': iExistingFactory='..GetExistingFactoryNumber()..'; iFactoriesWanted='..iFactoriesWanted..'; P'..iPlateau..'Z'..iLandZone..'; Mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Signif mass reclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; iCurPriority='..iCurPriority..';  Time='..GetGameTimeSeconds()) end
    --If we have dropped here recently, and mod dist is high, then prioritise getting reclaim over land fac as enemy will likely kill us soon
    if GetExistingFactoryNumber() < iFactoriesWanted and (tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.75 or tLZData[AiBotMap.subrefTotalSignificantMassReclaim] < 250 or aiBrain:GetEconomyStoredRatio('MASS') >= 0.75 or (tLZTeamData[AiBotMap.subrefLZFortify] and GetExistingFactoryNumber() == 0)) then
        iBPWanted = 10
        if bExistingFactoryIsComplete and bHaveLowMass then iBPWanted = 5 end
        --If we have dropped engineerz in this zone then prioritise the first land fac more
        if not(bExistingFactoryIsComplete) and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 100 or (iExistingFactory == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 5 and tLZTeamData[AiBotMap.subrefLZCoreExpansion])) and AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateau][iLandZone] then
            iBPWanted = 15
            if not(bHaveLowMass) and iExistingFactory == 0 then iBPWanted = 20 end
        end
        local iMaxTechLevelIfAny
        local iMinFacTechLevelWanted = 1
        if iExistingFactory == 0 then
            iMaxTechLevelIfAny = 1
        else
            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
            if iHighestTechEngiAvailable > 1 then
                if iExistingFactory == 1 then iMinFacTechLevelWanted = 2
                else
                    iMinFacTechLevelWanted = iHighestTechEngiAvailable
                end
            end
        end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = 5 end

        if bDebugMessages == true then LOG(sFunctionRef..': Want a land facotry, iExistingFactory='..iExistingFactory..'; iFactoriesWanted='..iFactoriesWanted..'; gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; bExistingFactoryIsComplete='..tostring(bExistingFactoryIsComplete or false)) end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 750 or aiBrain[AiBotOverseer.refbPrioritiseAir]) and AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
            HaveActionToAssign(refActionBuildAirFactory, iMinFacTechLevelWanted, iBPWanted, iMaxTechLevelIfAny)
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build land fac, iMinFacTechLevelWanted='..(iMinFacTechLevelWanted or 'nil')..'; iBPWanted='..(iBPWanted or 'nil')..'; iMaxTechLevelIfAny='..(iMaxTechLevelIfAny or 'nil')) end
            HaveActionToAssign(refActionBuildLandFactory, iMinFacTechLevelWanted, iBPWanted, iMaxTechLevelIfAny)
        end
    end


    --High reclaim zone when ahve low mass - want to be reclaiming ahead of building mexes; also if high reclaim and on enemy side of map (as less likely to hold onto any mexes)
    iCurPriority = iCurPriority + 1
    if (bHaveLowMass and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 250) or (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 250 and tLZTeamData[AiBotMap.refiModDistancePercent] > 0.75 and aiBrain:GetEconomyStoredRatio('MASS') < 0.75) or (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.15) then
        if bDebugMessages == true then LOG(sFunctionRef..': High priority reclaim in minor LZ, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; Signif mass='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; bEngineersRecentlyRunFromEnemy='..tostring(bEngineersRecentlyRunFromEnemy)) end

        --Have 1 engi search for high value wrecks
        iBPWanted = 5
        if tLZData[AiBotMap.subrefHighestIndividualReclaim] >= 50 then
            if bDebugMessages == true then LOG(sFunctionRef..': Have very high value reclaim so want 1 engi to go for these wrecks') end
            HaveActionToAssign(refActionReclaimArea, 1, 5, { false, 50 })
            iBPWanted = iBPWanted + 5
        end
        --Then have 1-2 engis search for reclaim generally if we dont have unclaimed mexes and havent run from enemy recently
        iCurPriority = iCurPriority + 1
        --possible reclai mvalues have cahnged as if we ran above reclaimarea then we may have refreshed values, so recheck we have at least some significant mass reeclaim
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 100 and ((not(bEngineersRecentlyRunFromEnemy) or tLZData[AiBotMap.subrefHighestIndividualReclaim] < 50) and tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount]) then
            if bDebugMessages == true then LOG(sFunctionRef..': We have no unclaimed mexes so will consider having high priority reclaimers, bEngineersRecentlyRunFromEnemy='..tostring(bEngineersRecentlyRunFromEnemy)) end
            if bEngineersRecentlyRunFromEnemy then iBPWanted = 5
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.03 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1000 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                iBPWanted = iBPWanted + 5
                if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                    iBPWanted = math.max(iBPWanted + 5, 15, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]])
                end
                if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3000 then
                    iBPWanted = iBPWanted * 1.5
                    if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.075 then
                        iBPWanted = iBPWanted * 1.5
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will assign '..iBPWanted..' to high priorty reclaimer') end
            HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, AiBotMap.iSignificantMassThreshold})
        end
    else
        iCurPriority = iCurPriority + 1
    end

    --Low power - if at T1, and have lots of mass income but poor E, and lots of mexes in zone (6+), then build t1 pgen as very high priority instead of more t1 mexes
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Priority t1 power builder for minor LZ check, subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; subrefLZOrWZMexCount='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; subrefiTeamAverageMassPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; subrefMexCountByTech][1]='..tLZTeamData[AiBotMap.subrefMexCountByTech][1]..'; subrefiTeamGrossMass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; subrefiTeamGrossEnergy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
    if not(bEngineersRecentlyRunFromEnemy) and bHaveLowPower and tLZData[AiBotMap.subrefLZOrWZMexCount] > 5 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 200 and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryPower - categories.TECH1, iTeam) == 0)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 and (tLZTeamData[AiBotMap.subrefMexCountByTech][1] >= 4 or (tLZTeamData[AiBotMap.subrefMexCountByTech][1] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 30 > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.95 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.7)) and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 then
        if not(AiBotUtilities.bFAFActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 15 > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] then
            if bDebugMessages == true then LOG(sFunctionRef..': High mex zone will build pgen as we have low power and lots of mass') end
            HaveActionToAssign(refActionBuildPower, 1, 10)
        end
    end


    if bDebugMessages == true then LOG(sFunctionRef..': About to consider what actions we want to give engineers for iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iTeam='..iTeam..'; Is table of unbuilt mex locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Is table of part complete mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]))) end
    iCurPriority = iCurPriority + 1
    --Unclaimed mex high priority
    if not(bTeammateHasBuiltHere) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and not(AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tLZData, true)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 then
        if bDebugMessages == true then LOG(sFunctionRef..': We have unbuilt mex locations for this land zone, locations='..repru(tLZData[AiBotMap.subrefMexUnbuiltLocations])..'; will assign a mex to build') end
        HaveActionToAssign(refActionBuildMex, 1, 5)
        if not(bEngineersRecentlyRunFromEnemy) and (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionBuildMex] or 0) > 0 then
            tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true
            --Update flat for adjacent zones
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                        tAdjLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true --in v274 experimented with not enabling this if lots of engis already traveling but slowed down early expansion too much
                    end
                end
            end
        end
    end

    --Reclaim enemy building if have available engineers, and enemy has buildings but no combat threat
    iCurPriority = iCurPriority + 1
    if not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            local oNearestEnemyUnitToMidpoint = AiBotUtilities.GetNearestUnit(tLZTeamData[AiBotMap.subrefTEnemyUnits], tLZData[AiBotMap.subrefMidpoint])
            if AiBotUnitInfo.IsUnitValid(oNearestEnemyUnitToMidpoint) then
                HaveActionToAssign(refActionReclaimEnemyUnit, 1, 5, oNearestEnemyUnitToMidpoint)

            end
        end
    end



    --AA if enemy has air to ground threat
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': High priority AA builder: iCurPriority='..iCurPriority..'; iNearbyEnemyAirToGroundThreat='..iNearbyEnemyAirToGroundThreat..'; enemy air to ground threat='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Enemy AirAA threat='..tLZTeamData[AiBotMap.refiEnemyAirAAThreat]) end
    if (iNearbyEnemyAirToGroundThreat > 0 or tLZTeamData[AiBotMap.refiEnemyAirAAThreat] >= 500) and (not(bTeammateHasBuiltHere) or iNearbyEnemyAirToGroundThreat >= 1000) then
        --Do we already have fixed AA in this LZ?
        if not(AiBotConditions.ZoneWantsT1Spam(tLZTeamData, iTeam)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] >= 200 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] == 0 then
            local iAACategory = AiBotUnitInfo.refCategoryStructureAA
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then

                if iNearbyEnemyAirToGroundThreat * 6 < tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] then
                    if iNearbyEnemyAirToGroundThreat * 10 < tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] then
                        --Dont change tech level
                    else
                        iAACategory = iAACategory - categories.TECH1
                    end
                else
                    iAACategory = iAACategory - categories.TECH1 - categories.TECH2
                end
            end
            local tExistingFixedAA = EntityCategoryFilterDown(iAACategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local bHaveFixedAA = false
            if AiBotUtilities.IsTableEmpty(tExistingFixedAA) == false then
                for iUnit, oUnit in tExistingFixedAA do
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have fixed AA, considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                    if oUnit:GetFractionComplete() then bHaveFixedAA = true break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bHaveFixedAA='..tostring(bHaveFixedAA)..'; Enemy air to ground threat='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Ally groundAA threat='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
            if not(bHaveFixedAA) or iNearbyEnemyAirToGroundThreat > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and math.min(iNearbyEnemyAirToGroundThreat * 4, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) then
                iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                if iNearbyEnemyAirToGroundThreat > 0 then
                    iBPWanted = iBPWanted * 2
                    if bDebugMessages == true then LOG(sFunctionRef..': Doubling base BP wanted as enemy has nearby air threat') end
                end

                if not(bHaveLowPower) then
                    if not(bHaveLowMass) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have low power or mass so quadrupling BP wanted') end
                        iBPWanted = iBPWanted * 4
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have low power but have low mass so only doubling bp wanted') end
                        iBPWanted = iBPWanted * 2
                    end
                end
                --Minimum of 30 build power if we have t2+ mexes
                if iBPWanted < 30 and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have T2 mexes so want at least 30 BP, or at least 20 if only 1 t2 mex') end
                    if tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 then iBPWanted = math.max(iBPWanted, 20)
                    else iBPWanted = 30
                    end
                end

                if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
                local iTechLevelWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]
                --If we have no engis of that tech level in this or adjacent zone then lower requirement if there is nearby enemy air threat
                if bDebugMessages == true then LOG(sFunctionRef..': Checking tech level if not adjacent to core zone, subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; bAdjacentToCoreZone='..tostring(bAdjacentToCoreZone)) end
                if iNearbyEnemyAirToGroundThreat > 0 and iTechLevelWanted > 1 then
                    if AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[iTechLevelWanted]) and (not(bAdjacentToCoreZone) or aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < iTechLevelWanted or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
                        local iHighestTechActuallyAvailable = 1
                        if iTechLevelWanted == 3 and AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[2]) == false then iHighestTechActuallyAvailable = 2 end
                        local iCurEngiTech
                        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
                            for iEngi, oEngi in toAssignedEngineers do
                                iCurEngiTech = AiBotUnitInfo.GetUnitTechLevel(oEngi)
                                if iCurEngiTech > iHighestTechActuallyAvailable then
                                    iHighestTechActuallyAvailable = iCurEngiTech
                                    if iHighestTechActuallyAvailable >= 3 then break end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechActuallyAvailable='..iHighestTechActuallyAvailable) end
                        iTechLevelWanted = iHighestTechActuallyAvailable
                    end
                end
                --If we are only building because we lack a SAM, but we dont have engineers avialable for it, then dont keep building T1-T2 fixed AA
                if iTechLevelWanted < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < iTechLevelWanted * iTechLevelWanted * 1000 and iNearbyEnemyAirToGroundThreat * 2 < tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] then
                    if bDebugMessages == true then LOG(sFunctionRef..': We lack t3 engis for sam so wont build any more AA') end
                else
                    --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted,                                          iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting)
                    HaveActionToAssign(refActionBuildAA, iTechLevelWanted, iBPWanted     , nil,              true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Minor Zone AA builder if no fixed AA: iBPWanted='..iBPWanted..'; iNearbyEnemyAirToGroundThreat='..iNearbyEnemyAirToGroundThreat..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; subrefiAlliedGroundAAThreat='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; iTechLevelWanted='..iTechLevelWanted) end
                end
            end
        end
    end

    --Protect game-ender or similar high avlue target (very high priority on assumption if we have built such a unit we shouldnt have to worry about lack of resources for this
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection]) == false then
        local bContinue = true
        for iUnit, oUnit in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
            if oUnit[AiBotBuilding.reftArtiTemplateRefs] then
                table.remove(tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection], iUnit)
                bContinue = false
                break
            end
        end
        if bContinue then
            --if not(aiBrain.AiBotEasy) then --have instead disabled the 'ctrlk existing shield to build new shield' logic if AiBotEasy is enabled
            if bDebugMessages == true then LOG(sFunctionRef..': Want to assign units to active shield protection, will list out each unit for this zone that wants active protection')
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoUnitsForSpecialShieldProtection] do
                    LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Mass cost='..oUnit[AiBotUnitInfo.refiUnitMassCost])
                end
            end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                iBPWanted = math.max(100, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] * 300 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] * 75)
            else
                iBPWanted = 100
            end
            if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.2 end


            if bDebugMessages == true then LOG(sFunctionRef..': Special shield defence action iBPWanted='..iBPWanted) end

            --Only use T3 engineers (even if we already have t3 engineers assigned) as want to make sure we can quickly get good concentrated build power
            --function HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist)
            HaveActionToAssign(refActionSpecialShieldDefence, 3, iBPWanted,         nil,                nil,                    nil,                        nil,                            true)
            --end
        end
    end

    --Rebuilding power e.g. if core base has lost main power; or if have low mass to energy ratio
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': rebuild power in minor zone check, subrefbTeamIsStallingEnergy='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; subrefbTeamIsStallingMass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; subrefbEnemiesInThisOrAdjacentLZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; subrefiTeamAverageEnergyPercentStored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]..'; subrefiTeamGrossMass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; subrefiTeamGrossEnergy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; subrefLZSValue='..tLZTeamData[AiBotMap.subrefLZSValue]..'; iLandZone='..iLandZone) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.9 and tLZTeamData[AiBotMap.subrefLZSValue] >= 200 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 8 > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]
            and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 6 > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] or tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.05) then --normally would expect 10-20 times energy to mass; meanwhile t3 mexes use 3x the mass cost in energy; so if have below 5 then want more power

        local iMinTechWanted = 1

        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 70 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 and AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[2]) and AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3])) then
            iBPWanted = 15
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 10 then iBPWanted = 5
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 20 then iBPWanted = 10
            end
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 250 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3])) then
            iMinTechWanted = 2
            iBPWanted = 60
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 100 then iBPWanted = 20
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 175 then iBPWanted = 40
            end
        else
            iMinTechWanted = 3
            iBPWanted = 60
        end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] >= 0.8 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.1 then iBPWanted = iBPWanted * 0.5 end
        if bDebugMessages == true then LOG(sFunctionRef..': We have far more mass income than energy income, and are stalling E, consider building power in minor LZs, iMinTechWanted='..iMinTechWanted..'; iBPWanted='..iBPWanted) end
        HaveActionToAssign(refActionBuildPower, iMinTechWanted, iBPWanted)
    end

    --Fortify zone (if flagged to fortify)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to fortify LZ or if we are turtle AI with mexes, iCurPriority='..iCurPriority..'; subrefLZFortify='..tostring((tLZTeamData[AiBotMap.subrefLZFortify] or false))..'; refbPrioritiseDefence='..tostring(aiBrain[AiBotOverseer.refbPrioritiseDefence] or false)..'; subrefMexCountByTech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
    if (tLZTeamData[AiBotMap.subrefLZFortify] or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][1] >= 3))) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 then
        local bHaveSufficientTech = false
        local tT2PlusFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tT2PlusFactories) == false then
            for iUnit, oUnit in tT2PlusFactories do
                if oUnit:GetFractionComplete() >= 1 and oUnit:GetAIBrain().AiBotAI then
                    bHaveSufficientTech = true
                    break
                end
            end
        end
        if bHaveSufficientTech then
            --If have capture targets then try and protect these, otherwise base destination on midpoint of the zone
            local tPointForPDConstruction
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoUnitsToCapture]) == false then
                for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoUnitsToCapture] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        tPointForPDConstruction = oUnit:GetPosition()
                        break
                    end
                end
            end
            if not(tPointForPDConstruction) then
                local iMoveDist = 40
                if AiBotMap.bIsCampaignMap then
                    if tLZTeamData[AiBotMap.reftObjectiveLocation] or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoLZUnitWantingFixedShield]) == false then iMoveDist = 15
                    else iMoveDist = 30
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will get PD position based on moving iMoveDist='..iMoveDist..' from the midpoint, Midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])) end
                tPointForPDConstruction = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), iMoveDist, true, false, AiBotMap.bIsCampaignMap)
            end
            local iCurPDThreat = GetPDThreatAboveRangeThresholdAlongPath(iPlateau, iLandZone, tLZData, tLZTeamData, iTeam, 40, tPointForPDConstruction)
            if bDebugMessages == true then LOG(sFunctionRef..': Want PD for a zone that we want to fortify, iCurPDThreat='..(iCurPDThreat or 'nil')..'; Have sufficient tech='..tostring(bHaveSufficientTech)..'; tPointForPDConstruction='..repru(tPointForPDConstruction)..'; Midpoint of zone='..repru(tLZData[AiBotMap.subrefMidpoint])..'; subrefLZFortify='..tostring(tLZTeamData[AiBotMap.subrefLZFortify])) end
            if (iCurPDThreat <= 2100 and tLZTeamData[AiBotMap.subrefLZFortify]) or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and iCurPDThreat <= 3000 and (iCurPDThreat <= 400 * aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] or iCurPDThreat <= 400 * (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + (tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 2))))
                    or (tLZTeamData[AiBotMap.subrefLZFortify] and iCurPDThreat <= 4000 and GetExistingFactoryNumber() >= 1 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false or tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZData[AiBotMap.subrefLZOrWZMexCount]))
            then
                iBPWanted = 40
                if not(bHaveLowMass) and not(AiBotConditions.HaveLowPower(iTeam)) then iBPWanted = 80 end

                --Get T1 radar in priority to T2 PD if we already have T2 PD but no radar
                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and tLZTeamData[AiBotMap.refiRadarCoverage] <= 40 and tLZTeamData[AiBotMap.refbWantLandScout] and iCurPDThreat * 1.5 >= (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) then
                    HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have t2 pd but no t1 radar so will get t1 radar') end
                    --Get groundAA for a fortify zone if already have good PD threat
                else
                    local iPDTechLevelWanted = 2
                    --Also get AA
                    if iCurPDThreat > 2100 and tLZTeamData[AiBotMap.subrefLZFortify] and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 800 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want some fixed AA to fortify zone') end
                        HaveActionToAssign(refActionBuildAA, iPDTechLevelWanted, iBPWanted)
                    end
                    HaveActionToAssign(refActionBuildEmergencyPD, iPDTechLevelWanted, iBPWanted, tPointForPDConstruction)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will build PD to fortify zone, iPDTechLevelWanted='..iPDTechLevelWanted..'; iBPWanted='..iBPWanted) end
                end
            end
        end
    end


    --TMD to defend against enemy missiles (including mobile ACUs with TML upgrade)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Minor LZ TMD builder, iCurPriority='..iCurPriority..'; is table of units wanting TMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))..'; bTeammateHasBuiltHere='..tostring(bTeammateHasBuiltHere or false)..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Time since TMD hit misisle='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] or -10000)) end
    if (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false or (tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] <= 60)) and (not(bTeammateHasBuiltHere) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
        iBPWanted = 30
        if not(bHaveLowMass) then iBPWanted = 50 end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (tLZTeamData[AiBotMap.subrefiTimeFriendlyTMDHitEnemyMissile] or 0) == 0 then
            if tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] == 0 then
                iBPWanted = 0
            else
                iBPWanted = iBPWanted * 0.5
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iBPWanted after adjusting due to having unbuilt mexes in zone='..iBPWanted) end
        end
        if bEngineersRecentlyRunFromEnemy and iBPWanted > 0 then iBPWanted = math.min(20, iBPWanted * 0.5) end
        if bDebugMessages == true then LOG(sFunctionRef..': We have untis wanting TMD in LZ '..iLandZone..'; will list out each unit if table not empty, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD])))
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
                for iUnit, oUnit in tLZTeamData[AiBotMap.reftUnitsWantingTMD] do
                    LOG(sFunctionRef..': Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Unit position='..repru(oUnit:GetPosition()))
                end
            end
        end
        if iBPWanted > 0 then
            --Get the unit closest to the nearest enemy base to protect first
            local oUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone)
            if bDebugMessages == true then LOG(sFunctionRef..': Is oUnitWantingTMD valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnitWantingTMD))..'; iBPWanted='..iBPWanted..'; oUnitWantingTMD='..(oUnitWantingTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitWantingTMD) or 'nil')) end
            if oUnitWantingTMD then
                HaveActionToAssign(refActionBuildTMD, 2, iBPWanted,  oUnitWantingTMD)
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and build TMD') end

                --Consider another TMD if we have multiple T2+ mexes and have a mex that wants TMD - get the unit closest to our base
                if table.getn(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) >= 2 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2) then
                    --GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iOptionalLandZone, bReturnTMLCountAsWell, iOptionalCategoryWanted, bGetClosestUnitToOurBase)
                    local oSecondUnitWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone,     false,                      AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPD, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': oSecondUnitWantingTMD='..(oSecondUnitWantingTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSecondUnitWantingTMD) or 'nil')) end
                    if oSecondUnitWantingTMD then
                        iCurPriority = iCurPriority + 1
                        HaveActionToAssign(refActionBuildSecondTMD, 2, tiBPByTech[2],  oSecondUnitWantingTMD)
                    end
                end
            end
        end
    end

    --Get T2 arti if we have lots of mexes in this zone
    iCurPriority = iCurPriority + 1
    if not(bTeammateHasBuiltHere) and not(bEngineersRecentlyRunFromEnemy) then GiveOrderForEmergencyT2Arti(HaveActionToAssign, bHaveLowMass, bHaveLowPower, iPlateau, iLandZone, tLZData, tLZTeamData, iTeam) end

    --Assign more BP to factories
    iCurPriority = iCurPriority + 1
    if GetExistingFactoryNumber() < iFactoriesWanted and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        --Dont want to build air factories at a core expansion point, instead only want land
        iBPWanted = 10
        if bEngineersRecentlyRunFromEnemy then iBPWanted = 5
        elseif not(bHaveLowMass) then iBPWanted = math.min(30, 3 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]) end
        if bDebugMessages == true then LOG(sFunctionRef..': Want more BP for land factories, iBPWanted='..iBPWanted..' iExistingFactory='..iExistingFactory..'; iFactoriesWanted='..iFactoriesWanted) end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 750 or aiBrain[AiBotOverseer.refbPrioritiseAir]) and AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
            HaveActionToAssign(refActionBuildAirFactory, 1, iBPWanted, nil)
        else
            HaveActionToAssign(refActionBuildLandFactory, 1, iBPWanted, nil)
        end
    end

    --Unclaimed mex in the zone
    iCurPriority = iCurPriority + 1
    if (not(bTeammateHasBuiltHere) or (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) == 0) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and not(AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tLZData, true)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 then
        iBPWanted = math.max(5, table.getn(tLZData[AiBotMap.subrefMexUnbuiltLocations]) * 2.5)
        if bDebugMessages == true then LOG(sFunctionRef..': We have unbuilt mex locations for this land zone, iBPWanted='..iBPWanted..', locations='..repru(tLZData[AiBotMap.subrefMexUnbuiltLocations])) end
        if bEngineersRecentlyRunFromEnemy then iBPWanted =5
        elseif bHaveLowPower and not(bHaveLowMass) and iBPWanted > 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
            iBPWanted = 5
        elseif bHaveLowPower and iBPWanted > 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80  then
            iBPWanted = 10
        end
        if bTeammateHasBuiltHere then iBPWanted = 5 end
        HaveActionToAssign(refActionBuildMex, 1, iBPWanted)
        if not(bTeammateHasBuiltHere) and not(bEngineersRecentlyRunFromEnemy) and (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionBuildMex] or 0) > 0 and not(tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex]) then
            tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    tAdjLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true --in v274 experimented with not enabling this if lots of engis already traveling but slowed down early expansion too much
                end
            end
        end
    elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
        --Do we have no engineers assigned to building a mex?
        local bHaveEngisBuilding = false
        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
            for iEngi, oEngi in toAssignedEngineers do
                if oEngi[refiAssignedAction] == refActionBuildMex then
                    bHaveEngisBuilding = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of assigned engineers empty='..tostring(AiBotUtilities.IsTableEmpty(toAssignedEngineers))..'; bHaveEngisBuilding='..tostring(bHaveEngisBuilding)) end
        if not(bHaveEngisBuilding) then
            --Refresh list of mexes
            RefreshPartBuiltMexList(tLZTeamData)
            if bDebugMessages == true then LOG(sFunctionRef..': Refreshed part built mex list, is table of part built mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]))) end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
                HaveActionToAssign(refActionCompletePartBuiltMex, 1, 5)
                if bDebugMessages == true then LOG(sFunctionRef..': Will get engi to complete part built mex') end
            end
        end
    end

    --Zones wanting specific faction engineers (e.g. for shielding game ender)
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftFactoriesWantedForEngineers]) == false then
        local iZoneWantingEngineersOfFaction, iFactionWanted = GetZoneAndFactionForPriorityEngineerTravel(tLZTeamData, iTeam, iLandZone, iPlateau)
        if iZoneWantingEngineersOfFaction and iFactionWanted then
            HaveActionToAssign(refActionMoveToLandZone, 3, 90, iZoneWantingEngineersOfFaction, true, false, iFactionWanted)
        end
    end

    --radar to support longer ranged units (prioritised more if in LOUD)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Radar builder check if we have LR units wanting support, tLZTeamData[AiBotMap.refiRadarCoverage]='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; AiBotUnitInfo.iT1RadarSize='..AiBotUnitInfo.iT1RadarSize..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange]='..tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Gross E='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Table of enemy firebases is empty?='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]))..'; Enemies in adj zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Cur T2+ skirmisher count='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySkirmisher - categories.TECH1)..'; brain gross E='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]) end
    if tLZTeamData[AiBotMap.refiRadarCoverage] < math.min(50, AiBotUnitInfo.iT1RadarSize - 5) and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 250 and (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 2000 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2) and (tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] >= 60 or tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] >= 34 and tLZTeamData[AiBotMap.refiRadarCoverage] < AiBotUnitInfo.iT1RadarSize -50) and (not(bHaveLowPower) or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false and tLZTeamData[AiBotMap.subrefLZSValue] >= 1000)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 150))) and not(bTeammateHasBuiltHere) and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 8 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        if bDebugMessages == true then LOG(sFunctionRef..': 2nd level of check') end
        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] +  tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 4000 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] +  tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 150 and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategorySkirmisher - categories.TECH1) >= 2))) then
            if bDebugMessages == true then LOG(sFunctionRef..': 3rd level, will decide whether to get t1/t2 and how much BP') end
            if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] >= 70) then
                iBPWanted = 5
                if bDebugMessages == true then LOG(sFunctionRef..': Want to get either t1 or t2 radar, tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange]='..(tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or 'nil')) end
                if tLZTeamData[AiBotMap.subrefLZAllyBestCombatRange] >= 80 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] then
                    if not(bHaveLowMass) or (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 5000 and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then iBPWanted = 40 end
                    HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                else
                    if not(bHaveLowMass) or (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 5000 and tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then iBPWanted = 10 end
                    HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted)
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will get t1 radar but just with 1 engi') end
                HaveActionToAssign(refActionBuildT1Radar, 1, 5)
            end
        end
    end

    --nearby zones with unclaimed mexes (or undefended enemy mexes) and no engineers traveling there
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have available engineers to send to another LZ. GetHighestTechEngiAvailable='..GetHighestTechEngiAvailable(toAvailableEngineersByTech)) end
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    local iNearbyZonesWantingEngineers = 0
    local iPrevEngisAvailable
    local tLZWantingBPConsidered = {}
    local iAdjLZ
    if iHighestTechEngiAvailable > 0 then
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
            for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                if tPathingDetails[AiBotMap.subrefLZTravelDist] <= tLZData[AiBotMap.subrefLZFurthestAdjacentLandZoneTravelDist] then
                    iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]) then
                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to send engineers from iLandZone='..iLandZone..' to iAdjLZ='..iAdjLZ..'; does the adjLZ want BP='..tostring(tAdjLZTeamData[AiBotMap.subrefTbWantBP])..'; tAdjLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1]='..tAdjLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1]..'; T2 wanted='..(tAdjLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][2] or 'nil')..'; Is table of unbuild mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; subrefTEngineersTravelingHere is empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]))) end
                        if tAdjLZTeamData[AiBotMap.subrefTbWantBP] and tAdjLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1] > 0 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) and
                                (AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(tAdjLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or GetGameTimeSeconds() - (tAdjLZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] or 0) >= 40) and not(tAdjLZTeamData[AiBotMap.subrefLZCoreExpansion]) and not(tAdjLZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))
                                --Enemy has mexes but nothing to protect them
                                or (not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] > 0 and tAdjLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] < 240 and (AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))))
                        then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will send engineer(s) to the iAdjLZ='..iAdjLZ) end
                            HaveActionToAssign(refActionMoveToLandZone, 1, iNearbyZonesWantingEngineers * 5 + 5, iAdjLZ, true)
                            iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                            if (tLZTeamData[AiBotMap.subreftiBPWantedByAction][refActionMoveToLandZone] or 0) > 0 then tLZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = true end
                            if iHighestTechEngiAvailable == 0 then break end
                        end
                    end
                else
                    break --Table shoudl be sorted closest first so if we are too far away now the later entries should be ignored
                end
            end
        end
    end

    --High priority reclaim if are low on mass or energy or is a very high value wreck in the zone
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef..': Considering if we want high priority reclaim, bHaveLowMass='..tostring(bHaveLowMass)..'; tLZData[AiBotMap.subrefTotalMassReclaim]='..(tLZData[AiBotMap.subrefTotalMassReclaim] or 'nil')..'; Significant mass reclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim])
        AiBotLand.DrawReclaimSegmentsInLandZone(iPlateau, iLandZone, true)
    end
    if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 25 and (bHaveLowMass or (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.4 and tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 3 * tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])) then
        local iReclaimFactor = 60
        if GetGameTimeSeconds() <= 540 then iReclaimFactor = 90 end
        iBPWanted = math.min(40, math.max(5, tLZData[AiBotMap.subrefTotalMassReclaim] / iReclaimFactor))
        if iBPWanted > 15 and GetGameTimeSeconds() <= 540 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
            iBPWanted = math.min(iBPWanted, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * 15)
        end
        if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iBPWanted = math.max(5, iBPWanted * 0.6) end
        if tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 10000 then iBPWanted = iBPWanted * 2 end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = math.min(10, iBPWanted * 0.5) end
        if bDebugMessages == true then LOG(sFunctionRef..': Higher priority reclaim, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]) end
        HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
        if bDebugMessages == true then LOG(sFunctionRef..': Have just tried assigning action to reclaim area') end
    elseif AiBotConditions.WantToReclaimEnergyNotMass(iTeam, iPlateau, iLandZone) then
        HaveActionToAssign(refActionReclaimArea, 1, 5, {true, nil})
    end


    --Reclaim specific units
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if have units to reclaim, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]))..'; Is table of units still valid='..tostring(AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]))..'; bEngineersRecentlyRunFromEnemy='..tostring(bEngineersRecentlyRunFromEnemy)) end
    if tLZTeamData[AiBotMap.subreftoUnitsToReclaim] and AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]) == true and not(bEngineersRecentlyRunFromEnemy) then
        local bObjectiveToReclaim = false
        if AiBotMap.bIsCampaignMap then
            for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit to reclaim, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                if oUnit[AiBotUnitInfo.refbIsReclaimTarget] then bObjectiveToReclaim = true break end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to reclaim friendly unit, bObjectiveToReclaim='..tostring(bObjectiveToReclaim)) end
        --Dont reclaim power if we have <100% stored or low power
        local bDontReclaimYet = false
        if not(bObjectiveToReclaim) and ((bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.98) then
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower, tLZTeamData[AiBotMap.subreftoUnitsToReclaim])) == false then
                bDontReclaimYet = true
            end
        end
        if not(AiBotOrders.bDontConsiderCombinedArmy) and not(bDontReclaimYet) then
            bDontReclaimYet = true
            for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if bDebugMessages == true then LOG(sFunctionRef..': Checking we wont reclaim a teammate unit, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Brain team='..(oUnit:GetAIBrain().AiBotTeam or 'nil')..'; BrainType='..(oUnit:GetAIBrain().BrainType or 'nil')) end
                if oUnit.AiBotActive or not(oUnit:GetAIBrain().AiBotTeam == iTeam) or oUnit:GetAIBrain().BrainType == 'AI' then
                    bDontReclaimYet = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a nonhuman unit to reclaim') end
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to reclaim a unit but still stop if have low power and we have pgens in the list of units to reclaim, bHaveLowPower='..tostring(bHaveLowPower)..'; Average% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) end
        if not(bDontReclaimYet) then

            if bObjectiveToReclaim or (bHaveLowMass and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) then
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, math.min(1.5 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]], math.max(5, 5 * table.getn(tLZTeamData[AiBotMap.subreftoUnitsToReclaim]))), nil, false)
            else
                --if have engi in the zone then reclaim it, but dont request an engi
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, 5, nil, true)
            end
        end
    end

    --Unclaimed hydro in the zone (and we have less than 4k power in our team)
    if not(bTeammateHasBuiltHere) and not(bEngineersRecentlyRunFromEnemy) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 400 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroUnbuiltLocations]) == false and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        if bDebugMessages == true then LOG(sFunctionRef..': We have unbuilt hydro locations for this land zone, locations='..repru(tLZData[AiBotMap.subrefHydroUnbuiltLocations])) end
        iBPWanted = 10
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] or (not(bHaveLowMass) and bHaveLowPower) then iBPWanted = 20 end
        HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
    end

    --SMD if very high value and enemy has nukes
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefLZSValue]='..tLZTeamData[AiBotMap.subrefLZSValue]..'; T3 mexes='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]) end
    if not(bEngineersRecentlyRunFromEnemy) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (tLZTeamData[AiBotMap.subrefLZSValue] >= 60000 or (not(bTeammateHasBuiltHere) and tLZTeamData[AiBotMap.subrefLZSValue] >= 17000 and (tLZTeamData[AiBotMap.subrefLZSValue] >= 20000 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyNukeLaunchers]) == false) or (tLZTeamData[AiBotMap.reftObjectiveLocation] and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategorySMD, tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjCategoryToBuild]) and (AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation]) or GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, false, bHaveLowMass, bWantMorePower) > 0)) or (tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] <= 360)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        --Make sure we have at least 2 T3 mex in this zone (or no T2 and T1 mexes)
        if (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10)) or (((tLZTeamData[AiBotMap.reftObjectiveLocation] and AiBotUtilities.DoesCategoryContainCategory(AiBotUnitInfo.refCategorySMD, tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjCategoryToBuild]) and (AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation] or GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, false, bHaveLowMass, bWantMorePower) > 0))) or (tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfLastSMDPrioritisationRequest] <= 360)) and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])) then

            local bAssistSMD = false
            local oSMDToShield, oUnderConstructionShield

            iBPWanted, bAssistSMD, oSMDToShield, oUnderConstructionShield = GetBPToAssignToSMD(iPlateau, iLandZone, iTeam, tLZTeamData, false, bHaveLowMass, bWantMorePower, not(AiBotUtilities.IsTableEmpty(toAvailableEngineersByTech[3])))
            if bDebugMessages == true then LOG(sFunctionRef..': iBPWanted for SMD in minor zone='..(iBPWanted or 'nil')..'; bAssistSMD='..tostring(bAssistSMD or false)..'; oSMDToShield='..(oSMDToShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSMDToShield) or 'nil')) end
            if iBPWanted > 0 then
                if oUnderConstructionShield then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have under construction shield we want to complete to cover SMD') end
                    if bAssistSMD then
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                            HaveActionToAssign(refActionRepairUnit, 1, iBPWanted * 0.5, oUnderConstructionShield)
                            HaveActionToAssign(refActionAssistSMD, 1, iBPWanted * 0.5)
                        else
                            HaveActionToAssign(refActionRepairUnit, 1, iBPWanted * 0.3, oUnderConstructionShield)
                            HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                        end
                    else
                        HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oUnderConstructionShield)
                    end
                    iCurPriority = iCurPriority + 3
                elseif oSMDToShield then
                    iCurPriority = iCurPriority + 1
                    if bDebugMessages == true then LOG(sFunctionRef..': Need to shield the SMD first') end
                    local iTechLevelWanted = 2
                    if (oSMDToShield[refiFailedShieldConstructionCount] or 0) > 0 or (tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 0) >= 5 then iTechLevelWanted = 3 end
                    if bAssistSMD then
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                            HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted * 0.5, oSMDToShield)
                            HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                        else
                            HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted * 0.1, oSMDToShield)
                            HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                        end
                    else
                        HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oSMDToShield)
                    end
                    iCurPriority = iCurPriority + 2
                elseif bAssistSMD then
                    iCurPriority = iCurPriority + 2
                    if bDebugMessages == true then LOG(sFunctionRef..': Will assist existing SMD') end
                    HaveActionToAssign(refActionAssistSMD, 1, iBPWanted)
                    iCurPriority = iCurPriority + 1
                else
                    iCurPriority = iCurPriority + 3
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to build SMD, iCurPrioriyt='..iCurPriority) end
                    HaveActionToAssign(refActionBuildSMD, 3, iBPWanted)
                end
            else
                iCurPriority = iCurPriority + 3
            end
        else
            iCurPriority = iCurPriority + 3
        end
    else
        iCurPriority = iCurPriority + 3
    end

    --Shielding due to enemy novax
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 15 and not(bHaveLowPower) and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
        local iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, false, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
        if iBPWanted > 0 then
            iBPWanted = math.min(iBPWanted, 40)
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
            if bEngineersRecentlyRunFromEnemy then iBPWanted = math.min(20, iBPWanted * 0.5) end

            HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
            if bDebugMessages == true then LOG(sFunctionRef..': Anti novax priority shield builder, iBPWanted='..iBPWanted) end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to assign any BP to antinovax priority shield builder') end
        end
    end

    --TML (will only trigger atm for core expansions)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Core expansion='..tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; Table of enemy firebases in range is empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]))..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Enemies in this or adj zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tLZData[AiBotMap.subrefLZOrWZMexCount]='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; T2 mex count='..(tLZTeamData[AiBotMap.subrefMexCountByTech][2] or 'nil')..'; Is table of storage empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]))..'; Closest enemy base plateau='..NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; iPlateau='..iPlateau) end
    if not(bEngineersRecentlyRunFromEnemy) and (tLZTeamData[AiBotMap.subrefLZCoreExpansion] or (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.1 and tLZData[AiBotMap.subrefLZOrWZMexCount] >= 1 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] == tLZData[AiBotMap.subrefLZOrWZMexCount] and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and (tLZData[AiBotMap.subrefLZOrWZMexCount] >= 2 or (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) and not(iPlateau == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tLZTeamData[AiBotMap.reftClosestEnemyBase]))))))) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then --Redundancy - getbptoassign function also includes this condition; however might be faster by having ith ere as an excluding factor?
        iBPWanted = GetBPToAssignToBuildingTML(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, bHaveLowMass)
        if iBPWanted > 0 then
            HaveActionToAssign(refActionBuildTML, 2, iBPWanted)
        end
    end

    --Teammate asked for engi (minor zone)
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefoBrainWantingEngi] then
        UpdateSpareEngineerNumber(tLZTeamData, toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            HaveActionToAssign(refActionGiveEngineerToTeammate, 1, 5)
        end
    end

    --Multiple mex upgrades (minor zone) - want to assist as a higher priority
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and (tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        iBPWanted = 10
        if not(bHaveLowPower) then
            iBPWanted = tLZTeamData[AiBotMap.subrefiActiveMexUpgrades] * 10
        end
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted)
    end

    --Shielding
    iCurPriority = iCurPriority + 1
    local iTechLevelWanted, oUnitToShield
    iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, false, bHaveLowMass, bWantMorePower, false, iLandZone, iPlateau)
    if bDebugMessages == true then LOG(sFunctionRef..': Minor zone results of BP for shielding='..(iBPWanted or 'nil')..'; iTechLevelWanted='..(iTechLevelWanted or 'nil')..'; iCurPriority='..iCurPriority) end
    if iBPWanted > 0 then
        if bEngineersRecentlyRunFromEnemy then
            iBPWanted = iBPWanted * 0.25
        end
        if bTeammateHasBuiltHere then
            if bHaveLowMass then iBPWanted = 5
            else
                iBPWanted = iBPWanted * 0.5
            end
        end
        if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
        HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
        if bDebugMessages == true then LOG(sFunctionRef..': Have just tried to assign an action to shield unit '..oUnitToShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToShield)) end
    end

    --Units to capture
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to capture empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]))..'; iCurPriority='..iCurPriority) end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then
        --Refresh the list
        local iCaptureCount = table.getn(tLZData[AiBotMap.subreftoUnitsToCapture])
        for iCurCount = iCaptureCount, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(tLZData[AiBotMap.subreftoUnitsToCapture][iCurCount])) or (tLZData[AiBotMap.subreftoUnitsToCapture][iCaptureCount].IsCapturable and not(tLZData[AiBotMap.subreftoUnitsToCapture][iCaptureCount]:IsCapturable())) then
                table.remove(tLZData[AiBotMap.subreftoUnitsToCapture], iCurCount)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Have units to capture for zone '..iLandZone..', after freshing them is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]))) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then
            --Dont capture if are a hostile AI due to the risk we capture a campaign objective and progress the map
            if not(aiBrain.HostileCampaignAI) then
                local oUnitToCapture
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                    local tPotentialCapture = EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryT3Power, tLZData[AiBotMap.subreftoUnitsToCapture])
                    if AiBotUtilities.IsTableEmpty(tPotentialCapture) == false then
                        oUnitToCapture = AiBotUtilities.GetNearestUnit(tPotentialCapture, tLZData[AiBotMap.subrefMidpoint])
                    end
                else
                    oUnitToCapture = AiBotUtilities.GetNearestUnit(tLZData[AiBotMap.subreftoUnitsToCapture], tLZData[AiBotMap.subrefMidpoint])
                end
                if oUnitToCapture then
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit to cpature='..oUnitToCapture.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToCapture)) end
                    iBPWanted = GetCaptureBPWanted(oUnitToCapture, bHaveLowPower, iTeam, tLZTeamData[AiBotMap.subrefLZbCoreBase])
                    HaveActionToAssign(refActionCaptureUnit, 1, iBPWanted, oUnitToCapture)
                end
            end

        end
    end

    --Units to repair
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to repair empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]))..'; iTeam='..iTeam) end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Have units to repair for zone '..iLandZone..' is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]))) end
        if AiBotConditions.IsTableOfUnitsStillValid(tLZData[AiBotMap.subreftoUnitsToRepair], true) then
            local oUnitToTarget = AiBotUtilities.GetNearestUnit(tLZData[AiBotMap.subreftoUnitsToRepair], tLZData[AiBotMap.subrefMidpoint])
            if oUnitToTarget[refbDontIncludeAsPartCompleteBuildingForConstruction] then
                --Remove unit from UnitsToRepair
                for iUnit, oUnit in tLZData[AiBotMap.subreftoUnitsToRepair] do
                    if oUnit == oUnitToTarget then
                        table.remove(tLZData[AiBotMap.subreftoUnitsToRepair], iUnit)
                        break
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Unit to repair='..oUnitToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToTarget)..'; will flag we want some BP for this') end
                HaveActionToAssign(refActionRepairUnit, 1, 5, oUnitToTarget)
            end
        end
    end

    --Early game power (for maps where want to scale up power really fast) where also lots of reclaim in the zone, and we have low power, and dont ahve low mass
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 2 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 and bHaveLowPower and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and not(bHaveLowMass) then
        --Build T1 power even if have t2 tech in some cases
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 125 then
            HaveActionToAssign(refActionBuildPower, 1, 15)
            --Build t2 pgens in rarer scenarios
        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3000 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 160 then
            HaveActionToAssign(refActionBuildPower, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], 30)
        end
    end

    --late game power (in case running out of space in core zone)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want power in minor zone, bHaveLowPower='..tostring(bHaveLowPower)..'; tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Mass % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; bHaveLowMass='..tostring(bHaveLowMass)..'; MexT3 count='..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; tLZTeamData[AiBotMap.subrefLZSValue]='..tLZTeamData[AiBotMap.subrefLZSValue]..'; iExistingFactory='..iExistingFactory) end
    if not(bTeammateHasBuiltHere) and not(bEngineersRecentlyRunFromEnemy) and (bHaveLowPower or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and AiBotConditions.WantMorePower(iTeam))) and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bHaveLowMass) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 or tLZTeamData[AiBotMap.subrefLZSValue] >= 10000 or (bAdjacentToCoreZone and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        --Either adjacent to core zone, or have a land fac in this zone, or relatively close to our base
        if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Gross energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]) end
        if bAdjacentToCoreZone or iExistingFactory > 0 or tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.15 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.95 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 3000) then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 350 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.35 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 30 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 900 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
                iBPWanted = 90
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.85 then iBPWanted = 180 end
                HaveActionToAssign(refActionBuildPower, 3, iBPWanted)
            end
        end
    end

    --Shield assistance
    iCurPriority = iCurPriority + 1
    if not(bTeammateHasBuiltHere) then
        iBPWanted = GetBPForShieldAssistance(tLZTeamData, iTeam)
        if iBPWanted > 0 then
            HaveActionToAssign(refActionAssistShield, 1, iBPWanted)
        end
    end

    iCurPriority = iCurPriority + 1
    --(ANY CHANGES TO BELOW - CONSIDER REPLICATING FOR BOTH CORE AND NONCORE BUILDERS) Adjacent LZ that wants engineers and has unbuilt mexes (only chekc if we have available engineers)
    --(as of v24 decided to go with differences for the minior LZ (which uses a simplified appraoch) vs core base highest priority for adj LZs
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have available engineers to send to another LZ. GetHighestTechEngiAvailable='..GetHighestTechEngiAvailable(toAvailableEngineersByTech)) end
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
            for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                if tPathingDetails[AiBotMap.subrefLZTravelDist] <= tLZData[AiBotMap.subrefLZFurthestAdjacentLandZoneTravelDist] then
                    iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]

                    --tLZWantingBPConsidered[iAdjLZ] = true --Are now adding in the condition that the zone has unbuilt mexes
                    --Require unbuilt mexes:
                    --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                    local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, true, false, true, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                    if tiBPByTechWanted then
                        for iTech = 1, iHighestTechEngiAvailable, 1 do
                            if tiBPByTechWanted[iTech] > 0 then
                                iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                HaveActionToAssign(refActionMoveToLandZone, iTech, iNearbyZonesWantingEngineers * 5 + tiBPByTechWanted[iTech], iAdjLZ, true)
                                if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                    iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                end

                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                    end
                    if iHighestTechEngiAvailable == 0 then break end
                else
                    break --Table shoudl be sorted closest first so if we are too far away now the later entries should be ignored
                end
            end
        end
    end

    iCurPriority = iCurPriority + 1
    --If have adjacent waterzone that has unbuilt mexes, wants engineers and has no combat threat then assign engi unelss it already has engis and we dont have many in this zone
    if bDebugMessages == true then LOG(sFunctionRef..': iCurPriority='..iCurPriority..'; Checking if adjacent water zones that want engis to build mexes, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
    local iCoreWZWantingSupportAsLowerPriority
    if iHighestTechEngiAvailable > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iCurWZ, iCurPond
        local iBPAlreadyAssigned = 0
        local bConsiderWaterZone
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            --Use similar logic to core land zone to avoid unintended consequences
            iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
            iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
            local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent water zone iCurWZ='..iCurWZ..'; iCurPond='..iCurPond..'; Is table of unbuilt mex locations empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]))) end
            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
            bConsiderWaterZone = false
            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then
                if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                    bConsiderWaterZone = true
                elseif tWZTeamData[AiBotMap.subrefWZbCoreBase] and tWZTeamData[AiBotMap.subrefTbWantBP] then
                    --Do we already have a completed naval factory here and at least 1 engineer? if so not as high priority
                    bConsiderWaterZone = true
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tFactoriesAndEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tFactoriesAndEngineers) == false then
                            local iEngiCount = 0
                            local iCompletedFactoryCount = 0
                            for iUnit, oUnit in tFactoriesAndEngineers do
                                if oUnit:GetFractionComplete() == 1 then
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId) then
                                        iCompletedFactoryCount = iCompletedFactoryCount + 1
                                    else
                                        iEngiCount = iEngiCount + 1
                                    end
                                end
                            end
                            if iCompletedFactoryCount > 0 and iCompletedFactoryCount + iEngiCount >= 3 then
                                bConsiderWaterZone = false
                            end
                        end
                    end
                    if not(bConsiderWaterZone)  and tWZTeamData[AiBotMap.subrefTbWantBP] then iCoreWZWantingSupportAsLowerPriority = iCurWZ end
                end
            end
            if bConsiderWaterZone then

                --or (tWZTeamData[AiBotMap.subrefWZbCoreBase] and (AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap. then

                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to send engineers to an adjaent water zone, iCurWZ='..iCurWZ..'; tWZTeamData[AiBotMap.subrefTbWantBP]='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP] or false)) end
                if tWZTeamData[AiBotMap.subrefTbWantBP] and tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 10 and (not(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) or not(tWZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand]) or GetGameTimeSeconds() - tWZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] > 30) then
                    iBPWanted = 5
                    if tWZTeamData[AiBotMap.subrefTbWantBP] then
                        iBPWanted = math.min(50, math.max(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], tWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1]))
                    end
                    HaveActionToAssign(refActionMoveToWaterZone, 1, iBPWanted + iBPAlreadyAssigned, iCurWZ, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': BP wanted+BP assigned='..iBPWanted + iBPAlreadyAssigned) end
                    iBPAlreadyAssigned = iBPAlreadyAssigned + iBPWanted
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    if iHighestTechEngiAvailable == 0 or iBPAlreadyAssigned >= tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 3 then break end
                end
            end
        end
    end

    --High priority islands (early-game expansion)
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS)
    iCurPriority = iCurPriority + 1
    local iBPAlreadyTraveling = 0
    GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': Core LZ considering engis for islands, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Time='..GetGameTimeSeconds()) end
    if iHighestTechEngiAvailable > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of pathing to other islands empty='..tostring(tLZData[AiBotMap.subrefLZPathingToOtherIslands])) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
            local iDistanceThreshold = math.max(125, AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 0.502)
            if bDebugMessages == true then LOG(sFunctionRef..': iDistanceThreshold='..iDistanceThreshold) end

            for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; Travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; tPathingData[AiBotMap.subrefIslandClosestLZRef]='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; Are there enemies in this or adjacnet LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                if tPathingData[AiBotMap.subrefIslandTravelDist] > iDistanceThreshold then break
                else
                    --Are there enemies in the target LZ?
                    local tIslandLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]]
                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tIslandLZData[AiBotMap.subrefMidpoint]) then
                        if tPathingData[AiBotMap.subrefIslandClosestLZRef] and AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and not(tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                            --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ,                                    iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                            local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false, true, false, false)
                            if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                            if tiBPByTechWanted then
                                --Is it either a minor zone, or a core zone that either wants lots of BP or doesnt have any engineers traveling to it?
                                for iTech = 1, iHighestTechEngiAvailable, 1 do
                                    if tiBPByTechWanted[iTech] > 0 then
                                        iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                        iBPWanted = iBPAlreadyTraveling + 5
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and assign an engineer to go to tPathingData[AiBotMap.subrefIslandClosestLZRef]='..tPathingData[AiBotMap.subrefIslandClosestLZRef]..'; BP wanted='..iBPWanted..'; iTech='..iTech..'; iPrevEngisAvailable='..iPrevEngisAvailable) end
                                        HaveActionToAssign(refActionMoveToLandZone, iTech, iBPWanted, tPathingData[AiBotMap.subrefIslandClosestLZRef], true)
                                        if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                            iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                            iBPAlreadyTraveling = iBPAlreadyTraveling + tiBPByTech[iTech]
                                        end

                                        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                        if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable after this='..iHighestTechEngiAvailable) end
                                        if iHighestTechEngiAvailable == 0 then break end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --AA if approaching enemy air threat and have significant mexes here
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= math.max(400, tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] * 2) and (AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.5) then
        local iGroundAAWanted = 150 * (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 4)
        if bHaveLowMass then iGroundAAWanted = iGroundAAWanted * 0.5 end
        local iApproachingEnemyAirToGroundThreat = tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
        for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if tSubtable[AiBotMap.subrefiDistance] >= 200 then break end
            local tAltLZOrWZTeamData
            if not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                tAltLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefLZTeamData][iTeam]
            else
                tAltLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefWZTeamData][iTeam]
            end
            iApproachingEnemyAirToGroundThreat = iApproachingEnemyAirToGroundThreat + (tAltLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)
        end
        iNearbyEnemyAirToGroundThreat = math.max(iNearbyEnemyAirToGroundThreat, iApproachingEnemyAirToGroundThreat)
        if bHaveLowMass then iGroundAAWanted = math.max(iGroundAAWanted,  iNearbyEnemyAirToGroundThreat * 0.4)
        else iGroundAAWanted = math.max(iGroundAAWanted, iNearbyEnemyAirToGroundThreat * 0.8)
        end
        iGroundAAWanted = math.min(iGroundAAWanted, 2000)
        if bDebugMessages == true then LOG(sFunctionRef..': Approaching air threat, tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] ='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; iGroundAAWanted='..iGroundAAWanted..'; Team air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) end
        if tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < iGroundAAWanted then
            iBPWanted = tiBPByTech[math.max(iHighestTechEngiAvailable, 1)]
            if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
            if (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) >= 600 then
                if (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) >= 1500 then
                    HaveActionToAssign(refActionBuildAA, math.max(2, iHighestTechEngiAvailable, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyLandFactoryTech]), iBPWanted)
                else
                    HaveActionToAssign(refActionBuildAA, math.max(2, iHighestTechEngiAvailable), iBPWanted)
                end
            else
                HaveActionToAssign(refActionBuildAA, math.max(1, iHighestTechEngiAvailable), iBPWanted)
            end
        end
    end


    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) then
        iBPWanted = GetBPToAssignToAssistUpgrade(tLZTeamData, iTeam, false, bHaveLowMass, bHaveLowPower, bWantMorePower)
        if iBPWanted > 0 then
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
            HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted)
        end
    end

    --Build mass storage if we have T2+ mexes
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) then
        iBPWanted = GetBPToAssignToMassStorage(iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, true, bHaveLowMass, bWantMorePower)
        if iBPWanted > 0 then
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
            HaveActionToAssign(refActionBuildMassStorage, AiBotBuilding.iLowestMassStorageTechAvailable, iBPWanted)
        end
    end

    --Lower priority mass reclaim
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Lower priority reclaim if want mass, Total mass reclaim in zone='..(tLZData[AiBotMap.subrefTotalMassReclaim] or 'nil')..'; bHaveLowMass='..tostring(bHaveLowMass)..'; Lowest mass % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Signif mass reclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]) end
    if not(bEngineersRecentlyRunFromEnemy) and (bHaveLowMass or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.5 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 125)) and tLZData[AiBotMap.subrefTotalMassReclaim] >= 5 then
        local iReclaimFactor = 25
        if GetGameTimeSeconds() <= 540 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 2 then
            iReclaimFactor = 100
            if bHaveLowMass and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.1 and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 400 then iReclaimFactor = 75 end
        end
        iBPWanted = math.min(40, math.max(5, tLZData[AiBotMap.subrefTotalMassReclaim] / iReclaimFactor))
        if iBPWanted > 15 and GetGameTimeSeconds() <= 540 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
            iBPWanted = math.min(iBPWanted, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * 10)
        end
        if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iBPWanted = math.max(5, iBPWanted * 0.6) end
        if bDebugMessages == true then LOG(sFunctionRef..': Lower priority reclaim, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; iBPWanted='..iBPWanted) end
        HaveActionToAssign(refActionReclaimArea, 1, iBPWanted, {false, nil})
    end

    --SAMs for minor zones
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and tLZTeamData[AiBotMap.subrefLZSValue] >= 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 1000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3) and (not(bTeammateHasBuiltHere) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) then
        local iGroundAAWanted = math.max(1600, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.2)
        if (not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 8) or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] >= 2000)) and tLZTeamData[AiBotMap.subrefLZSValue] >= 1500 then
            iGroundAAWanted = math.max(3200, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.25 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.05)
        end
        if iGroundAAWanted > math.max(7000, tLZTeamData[AiBotMap.subrefLZSValue] * 0.5) then
            iGroundAAWanted = math.max(7000, math.min(iGroundAAWanted, tLZTeamData[AiBotMap.subrefLZSValue] * 0.5, 4000 * tLZTeamData[AiBotMap.subrefMexCountByTech][3]  + 1000 * tLZTeamData[AiBotMap.subrefMexCountByTech][2]))
        end
        --Cap amount of AA wanted

        if iGroundAAWanted > 8000 then
            if iGroundAAWanted > 20000 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] < 4 then iGroundAAWanted = 20000 end
            local iAboveThresholdFactor = 1
            if bHaveLowMass then iAboveThresholdFactor = 0.75 end
            if bHaveLowPower then iAboveThresholdFactor = iAboveThresholdFactor * 0.75 end
            if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] then iAboveThresholdFactor = iAboveThresholdFactor * 0.75 end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] < 12000 then iAboveThresholdFactor = iAboveThresholdFactor * 0.75 end
            if tLZTeamData[AiBotMap.subrefMexCountByTech][3] < 2 then iAboveThresholdFactor = iAboveThresholdFactor * 0.75 end
            iGroundAAWanted = 8000 + (iGroundAAWanted - 8000) * iAboveThresholdFactor
            if bDebugMessages == true then LOG(sFunctionRef..': We did want more than 8k groundAA threat, reduced to '..iGroundAAWanted..'; iAboveThresholdFactor=;..iAboveThresholdFactor') end
        end

        if tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < iGroundAAWanted then
            --Do we already have fixed AA in this LZ?
            local iAACategory = AiBotUnitInfo.refCategoryStructureAA
            if AiBotTeam.subrefiHighestFriendlyFactoryTech >= 3 then
                iAACategory = iAACategory * categories.TECH3
            end
            local tExistingFixedAA = EntityCategoryFilterDown(iAACategory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            --Max of 1 sam per 1 T3 mex (approx), more if we have large gunship threat and lack air control
            if AiBotUtilities.IsTableEmpty(tExistingFixedAA) or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < math.max(iNearbyEnemyAirToGroundThreat * 2, iGroundAAWanted) then
                --Further cap on number of SAMs
                if bDebugMessages == true then LOG(sFunctionRef .. ': tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]=' .. tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] .. '; iNearbyEnemyAirToGroundThreat=' .. iNearbyEnemyAirToGroundThreat .. '; iGroundAAWanted=' .. iGroundAAWanted) end
                if not (bHaveLowMass and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) and tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 6000 and (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][1]) > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 15 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                    iBPWanted = tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]]
                    if iNearbyEnemyAirToGroundThreat > 0 then
                        iBPWanted = iBPWanted * 2
                    end
                    if not (bHaveLowPower) then
                        if not (bHaveLowMass) then
                            iBPWanted = iBPWanted * 4
                        else
                            iBPWanted = iBPWanted * 2
                        end
                    end
                    HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], iBPWanted)
                    if bDebugMessages == true then LOG(sFunctionRef .. ': Wnat more AA for minor zone, iBPWanted=' .. iBPWanted) end
                end
            end
        end
    end

    --Power spread out to help vs enemy t3 arti
    iCurPriority = iCurPriority + 1
    if bWantMorePower and not(bEngineersRecentlyRunFromEnemy) and not(bHaveLowMass) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] >= 2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 500 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 9000 and (tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 or AiBotMap.iMapSize <= 512) then
        --Do we have any T3 pgens in this zone already?
        local iExistingT3Pgen = 0
        local tExistingT3Pgen = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryT3Power, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tExistingT3Pgen) == false then
            for iPGen, oPGen in tExistingT3Pgen do
                if oPGen:GetFractionComplete() == 1 then
                    iExistingT3Pgen = iExistingT3Pgen + 1
                end
            end
        end
        if iExistingT3Pgen < 2 and (bHaveLowPower or iExistingT3Pgen == 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4) then
            iBPWanted = 60
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 then iBPWanted = 120 end
            HaveActionToAssign(refActionBuildPower, 3, iBPWanted)
        end
    end

    --Higher priority T2 radar creep where we have large mass income or lots of experimentals, or priority units wanting land scouts in some cases
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': T2 radar creep - bHaveLowMass='..tostring(bHaveLowMass)..'; bWantMorePower='..tostring(bWantMorePower)..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Map size='..AiBotMap.iMapSize..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
    if not(bHaveLowPower) and not(bTeammateHasBuiltHere) and not(bEngineersRecentlyRunFromEnemy) and tLZTeamData[AiBotMap.refiRadarCoverage] < math.max(AiBotUnitInfo.iT2RadarSize - 50, math.min(AiBotUnitInfo.iT2RadarSize - 20, AiBotUnitInfo.iT1RadarSize)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) and (
            (tLZTeamData[AiBotMap.subrefLZSValue] >= 3000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 300 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and (tLZTeamData[AiBotMap.refiRadarCoverage] <= AiBotUnitInfo.iT1RadarSize or not(bHaveLowMass)) and AiBotMap.iMapSize > AiBotUnitInfo.iT3RadarSize and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 60 and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 150) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL) >= 4)
                    or (tLZTeamData[AiBotMap.refiRadarCoverage] < 50 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZTeamData[AiBotMap.subrefLZSValue] > 0 or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] > tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 2 or not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) and AiBotUtilities.IsTableEmpty(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.reftoPriorityUnitsWantingLandScout]) == false)) then
        --Check we dont have any radar here already (redundancy for radar coverage)
        local tExistingRadar = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local bHaveRadar = false
        if AiBotUtilities.IsTableEmpty(tExistingRadar) == false then
            for iUnit, oUnit in tExistingRadar do
                if oUnit:GetFractionComplete() >= 1 then
                    bHaveRadar = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveRadar='..tostring(bHaveRadar)) end
        if not(bHaveRadar) then
            --Are we able to build radar? assume we can if we have access to T3 factories for simplicity
            if not(AiBotMap.bIsCampaignMap) or not(AiBotOverseer.bUnitRestrictionsArePresent) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                HaveActionToAssign(refActionBuildT2Radar, 2, 10)
            end
        end
    end

    --Lower priority LZs wanting engineers:
    iCurPriority = iCurPriority + 1
    if iCoreWZWantingSupportAsLowerPriority and iHighestTechEngiAvailable > 0 then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            HaveActionToAssign(refActionMoveToWaterZone, 1, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]], iCoreWZWantingSupportAsLowerPriority, true)
        end
    end
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS) Other non adjacent LZ on this plateau that wants engineers (low priority) - prioritise those nearest this zone
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': About to check for further away zones wanting BP, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; iCurPriority='..iCurPriority) end
    if iHighestTechEngiAvailable > 0 then
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
            for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                if bDebugMessages == true then LOG(sFunctionRef..': Lower priority logic to send engineers to another LZ, iAdjLZ='..iAdjLZ..'; Have we alreayd considered='..tostring(tLZWantingBPConsidered[iAdjLZ] or false)) end
                if not(tLZWantingBPConsidered[iAdjLZ]) then
                    tLZWantingBPConsidered[iAdjLZ] = true
                    --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                    local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ, iPathingRef, iHighestTechEngiAvailable, false            , false, false, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                    if tiBPByTechWanted then
                        for iTech = 1, iHighestTechEngiAvailable, 1 do
                            if tiBPByTechWanted[iTech] > 0 then
                                iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                HaveActionToAssign(refActionMoveToLandZone, iTech, (iNearbyZonesWantingEngineers + 1) * 5, iAdjLZ, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Sending engineers to nearby zone, BPWanted='..(iNearbyZonesWantingEngineers + 1) * 5) end
                                if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                    iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                end

                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                    end
                end
                if iHighestTechEngiAvailable == 0 then break end
            end
        end
    end

    --Islands wanting engineers (provided we dont have adjacent naval threats)
    --(ANY CHANGES TO BELOW - REPLICATE FOR BOTH CORE AND NONCORE BUILDERS)
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': About to check if minor LZ wants to send engis to an island, iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
    local iIslandDistanceThreshold
    if iHighestTechEngiAvailable > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
        if bDebugMessages == true then LOG(sFunctionRef..': is pathing to other islands empty='..tostring( AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]))) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
            if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; tLZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])) end
            iIslandDistanceThreshold = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], tLZData[AiBotMap.subrefMidpoint]) * 0.6
            if AiBotMap.bIsCampaignMap then iIslandDistanceThreshold = iIslandDistanceThreshold * 1.5 end
            if bDebugMessages == true then LOG(sFunctionRef..': Will search for islands, iIslandDistanceThreshold='..iIslandDistanceThreshold) end

            for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..tPathingData[AiBotMap.subrefIslandNumber]..'; travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; Closest LZ ref='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; are enemies in this or adjacent LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                if tPathingData[AiBotMap.subrefIslandTravelDist] > iIslandDistanceThreshold then break
                else
                    --Are there enemies in the target LZ?
                    if tPathingData[AiBotMap.subrefIslandClosestLZRef] and not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                        --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ,                                    iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                        local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false,             true,       false,              false)
                        if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                        if tiBPByTechWanted then
                            --Is it either a minor zone, or a core zone that either wants lots of BP or doesnt have any engineers traveling to it?
                            for iTech = 1, iHighestTechEngiAvailable, 1 do
                                if tiBPByTechWanted[iTech] > 0 then
                                    iPrevEngisAvailable = table.getn(toAvailableEngineersByTech[iTech])
                                    HaveActionToAssign(refActionMoveToLandZone, iTech, math.max((iNearbyZonesWantingEngineers + 1) * 5, tiBPByTechWanted[iTech]), tPathingData[AiBotMap.subrefIslandClosestLZRef], true)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to give order for engi to move to the island LZ, table.getn(toAvailableEngineersByTech[iTech])='..table.getn(toAvailableEngineersByTech[iTech])..'; iPrevEngisAvailable='..iPrevEngisAvailable) end
                                    if table.getn(toAvailableEngineersByTech[iTech]) < iPrevEngisAvailable then
                                        iNearbyZonesWantingEngineers = iNearbyZonesWantingEngineers + 1
                                    end

                                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                    if iHighestTechEngiAvailable == 0 then break end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --Objective buildings
    iCurPriority = iCurPriority + 1
    if tLZTeamData[AiBotMap.reftObjectiveLocation] then
        --Check if we already have enough of the category
        if AiBotConditions.DoWeWantToBuildObjectiveCategory(tLZTeamData[AiBotMap.reftObjectiveLocation]) then
            iTechLevelWanted = (tLZTeamData[AiBotMap.reftObjectiveLocation][AiBotMap.subrefiObjTechLevelWanted] or 1)
            iBPWanted = tiBPByTech[iTechLevelWanted]
            HaveActionToAssign(refActionBuildSpecialObjective, iTechLevelWanted, iBPWanted, tLZTeamData[AiBotMap.reftObjectiveLocation])
        end
    end

    --Ecoing or exp, If have are overflowing mass and have high income, energy, and are at T3, and this zone has mexes and no enemy units then get land factories if <=2, or an experimental or T3 power otherwise
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and not(bTeammateHasBuiltHere) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 3 and not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6)) then
        --We need at least 1 T3 mex in the zone and no enemy units
        if tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
            local iExistingFactories = 0
            local tExistingLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tExistingLandFactories) == false then
                iExistingFactories = table.getn(tExistingLandFactories)
            end
            local bBuiltParagon = aiBrain[AiBotEconomy.refbBuiltParagon]
            if (iExistingFactories < 2 or (bBuiltParagon and iExistingFactories < 3)) and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone) then
                --Build air fac if in very higih mass scenario such as having a paragon
                if aiBrain[AiBotEconomy.refbBuiltParagon] or (aiBrain[AiBotOverseer.refbPrioritiseAir] and AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': want air fac as we have paragon') end
                    HaveActionToAssign(refActionBuildAirFactory, 1, 40)
                elseif AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 1 then
                    --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting)
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to build land factory as only have 1 factory') end
                    HaveActionToAssign(refActionBuildQuantumGateway, 3, 100)
                end
            else
                --Build land experimental if enemy base is pathable by land from here and we have high gross mass, and we have a high % stored or low mod dist
                if not(bHaveLowPower) then
                    --Get quantum gateway if dont have one and are in LOUD or QUIET
                    local bGetGatewayInstead = false
                    if AiBotUtilities.bQuietModActive or AiBotUtilities.bLoudModActive then
                        local tCompletedGateway = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        local iCompletedGateway = 0
                        if AiBotUtilities.IsTableEmpty(tCompletedGateway) == false then
                            for iGateway, oGateway in tCompletedGateway do
                                if oGateway:GetFractionComplete() == 1 then iCompletedGateway = iCompletedGateway + 1 end
                            end
                        end
                        iBPWanted = 200
                        if iCompletedGateway == 0 then
                            bGetGatewayInstead = true
                        end
                    end
                    if bGetGatewayInstead then
                        HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will get quantum gateway for minor zone to spend our mass') end
                    elseif bBuiltParagon or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 60 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 6 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 or tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.1)) then
                        --If we have stalled power recently then build power, otherwise get experimental
                        if bWantMorePower and (bHaveLowPower or GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -100 <= 30) then
                            HaveActionToAssign(refActionBuildPower, 3, 60, nil, false, true)
                        else
                            if bBuiltParagon or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9) then
                                if ((NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or 0) == (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint]) or -1) and (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.35 or AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) <= 350))
                                        and (not(aiBrain[AiBotEconomy.refbBuiltParagon]) or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 6 + 6 * AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti))
                                then

                                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildLandExperimental,3, 60, nil, false, true)
                                else
                                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 3, 60, nil, false, true)
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --Part build hydro builder where we started but got interrupted
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and not(bTeammateHasBuiltHere) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 400 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroLocations]) == false and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefHydroUnbuiltLocations]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        if iHighestTechEngiAvailable > 0 or GetGameTimeSeconds() <= 900 then --Wont bother refreshing highest engi tech - this is only a rough measure intended to minimise performace implications of the above later in the game
            local tFriendlyHydro = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local oHydroToAssist
            if AiBotUtilities.IsTableEmpty(tFriendlyHydro) == false then
                for iExistingHydro, oExistingHydro in tFriendlyHydro do
                    if oExistingHydro:GetFractionComplete() < 1 then
                        oHydroToAssist = oExistingHydro
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': We have a hydro location in this zone that is showing as unavailable, will check if we have any part-built hydro buildings in here, is tFriendlyHydro empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyHydro))..'; oHydroToAssist='..(oHydroToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oHydroToAssist) or 'nil')) end
            if oHydroToAssist then
                if bDebugMessages == true then LOG(sFunctionRef..': Will assist part-complete hydro for P'..iPlateau..'Z'..iLandZone) end
                iBPWanted = 5
                HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oHydroToAssist)
            end
        end
    end

    --If still have an engineer available and have an adjacent LZ that wants BP and doesnt have any enemies in that LZ specifically (even if there might be in an adjacent one) then send engineer
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then

        if bDebugMessages == true then LOG(sFunctionRef..': Table of adjacnet LZs='..repru(tLZData[AiBotMap.subrefLZAdjacentLandZones])) end
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            local iBPAlreadyTraveling = 0
            if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
                for iEngi, oEngi in toAssignedEngineers do
                    if oEngi[refiAssignedAction] == refActionMoveToLandZone then
                        iBPAlreadyTraveling = iBPAlreadyTraveling + oEngi:GetBlueprint().Economy.BuildRate
                    end
                end
            end

            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Does it want BP='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP])..'; Combat threat='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]) end
                if not(tLZWantingBPConsidered[iAdjLZ]) and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTbWantBP] and (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTBuildPowerByTechWanted][1] or 0) > 0 and AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal] == 0 then
                    HaveActionToAssign(refActionMoveToLandZone, 1, iBPAlreadyTraveling + 5, iAdjLZ, true)
                    iBPAlreadyTraveling = iBPAlreadyTraveling + 5
                    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    if iHighestTechEngiAvailable == 0 then break end
                end
            end
        end
    end


    --Adjacent water zones that want an engineer
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have adjacent WZ that wants engineer, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
    if iHighestTechEngiAvailable > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iCurWZ
        local iCurPond
        local bWantBPOfOurTech
        local iMinTechWanted = 1
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iCurWZ = tSubtable[AiBotMap.subrefAWZRef]
            iCurPond = AiBotMap.tiPondByWaterZone[iCurWZ]
            local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iCurWZ]
            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to send engineers to an adjaent water zone, iCurWZ='..iCurWZ..'; tWZTeamData[AiBotMap.subrefTbWantBP]='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP] or false)) end
                if tWZTeamData[AiBotMap.subrefTbWantBP] then
                    bWantBPOfOurTech = false
                    for iTech = iHighestTechEngiAvailable, 1, -1 do
                        if tWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                            bWantBPOfOurTech = true
                            iMinTechWanted = iTech
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bWantBPOfOurTech='..tostring(bWantBPOfOurTech)) end
                    if bWantBPOfOurTech then
                        HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, math.min(tiBPByTech[iMinTechWanted] * 2, 50), iCurWZ, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': have tried to send BP of '..(tiBPByTech[iMinTechWanted] * 2)..' to iCurWZ '..iCurWZ) end
                        break
                    end
                end
                if bWantBPOfOurTech then break end
            end
        end
    end

    --Extra (second) shielding in a high mass scenario - will only try to shield t3 arti/game ender
    iCurPriority = iCurPriority + 1
    if (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and not(bEngineersRecentlyRunFromEnemy) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 500 and not(bTeammateHasBuiltHere) then
        local iBPWanted, iTechLevelWanted, oUnitToShield = GetBPMinTechAndUnitForFixedShields(tLZData, tLZTeamData, iTeam, true, bHaveLowMass, bWantMorePower, true, iLandZone, iPlateau)
        if iBPWanted > 0 then
            iBPWanted = math.min(iBPWanted, 40)
            if bPrioritiseProduction then iBPWanted = iBPWanted * 0.25 end
            if aiBrain[AiBotOverseer.refbCanBuildExperimentalShields] then
                iBPWanted = iBPWanted * 2
                HaveActionToAssign(refActionBuildShield, iTechLevelWanted, iBPWanted, oUnitToShield)
                if bDebugMessages == true then LOG(sFunctionRef..': Exp shields available so minor zone will just build first shield not multiple at once, iBPWanted='..iBPWanted..'; iLandZone='..iLandZone) end
            else
                HaveActionToAssign(refActionBuildSecondShield, iTechLevelWanted, iBPWanted, oUnitToShield)
                if bDebugMessages == true then LOG(sFunctionRef..': High priority shield builder, iBPWanted='..iBPWanted) end
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to assign any BP to high priority shield builder') end
        end
    end

    --Pre-emptive AA turret
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and (not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2) and not(bHaveLowPower) then
        --Are we likely on a small island/plateau (due to having at least 50% of the island's mexes)? Or we have significant value here?
        if tLZData[AiBotMap.subrefLZOrWZMexCount] >= 0.5 * AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 300 then
                local iAAWanted = math.min(150 * (tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 4), AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] * 0.25 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] or 0) * 0.05)
                if not(bHaveLowMass) and not(bHaveLowPower) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 then iAAWanted = math.max(iAAWanted, 1500) end
                if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] then iAAWanted = iAAWanted * 0.25 end
                if bDebugMessages == true then LOG(sFunctionRef..': iAAWanted='..iAAWanted..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) end
                if iAAWanted > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] then
                    if tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 700 then
                        HaveActionToAssign(refActionBuildAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech], 5)
                    else
                        HaveActionToAssign(refActionBuildAA, 1, 5)
                    end
                end
            end
        end
    end


    --Low priority power builder if we have lots of mass and dont have much power
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and not(bTeammateHasBuiltHere) and (not(bPrioritiseProduction) or (not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 75 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < math.max(250, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] * 0.5) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 20) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        local iMinTechLevelForPower = 1
        --[[if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 then
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 22 then iMinTechLevelForPower = 1
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 110 then iMinTechLevelForPower = 2
    end
end--]]
        HaveActionToAssign(refActionBuildPower, iMinTechLevelForPower, tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]] * 6)
    end

    --Low priority air staging, if we have T3 mex, decent intel coverage, no nearby enemies, low mod distance, and need air staging
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': About to check if we need air staging for core zone, Time='..GetGameTimeSeconds()..'; Time of last shortage='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] or 'nil')..'; bPrioritiseProduction='..tostring(bPrioritiseProduction or false)..'; subrefbEnemiesInThisOrAdjacentLZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; T2 mex count='..tLZTeamData[AiBotMap.subrefMexCountByTech][2]..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]) end
    if not(bEngineersRecentlyRunFromEnemy) and (not(bTeammateHasBuiltHere) and not(bPrioritiseProduction) and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] or 0) <= 1.1 and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3) and tLZTeamData[AiBotMap.refiRadarCoverage] >= math.min(AiBotUnitInfo.iT1RadarSize - 15, 100) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 80*AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        local tExistingAirStaging = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirStaging, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local iExistingAirStaging = 0
        if AiBotUtilities.IsTableEmpty(tExistingAirStaging) == false then
            for iStaging, oStaging in tExistingAirStaging do
                if oStaging:GetFractionComplete() == 1 and oStaging:GetAIBrain().AiBotAI then
                    iExistingAirStaging = iExistingAirStaging + 1
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iExistingAirStaging='..iExistingAirStaging..'; bHaveLowMass='..tostring(bHaveLowMass)) end
        if iExistingAirStaging < 1 then
            iBPWanted = 5
            if not(bHaveLowMass) then iBPWanted = iBPWanted * 2 end
            HaveActionToAssign(refActionBuildAirStaging, AiBotBuilding.iLowestAirStagingTechAvailable, iBPWanted, nil, false)
            if bDebugMessages == true then LOG(sFunctionRef..': Have flagged we want air staging for minor zone with iBPWanted='..iBPWanted) end
        end
    end

    --Low priority T2 radar creep
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': T2 radar creep - bHaveLowMass='..tostring(bHaveLowMass)..'; bWantMorePower='..tostring(bWantMorePower)..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]..'; Map size='..AiBotMap.iMapSize..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
    if not(bEngineersRecentlyRunFromEnemy) and (not(bHaveLowMass) and not(bWantMorePower) and tLZTeamData[AiBotMap.refiRadarCoverage] < math.min(100, math.max(AiBotUnitInfo.iT1RadarSize + 1, AiBotUnitInfo.iT2RadarSize - 80)) and not(bTeammateHasBuiltHere) and AiBotMap.iMapSize > 512 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 300 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 18 or AiBotMap.bIsCampaignMap) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 or tLZTeamData[AiBotMap.subrefLZSValue] >= 1750)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        --Check we dont have any radar here already (redundancy for radar coverage)
        local tExistingRadar = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRadar, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        local bHaveRadar = false
        if AiBotUtilities.IsTableEmpty(tExistingRadar) == false then
            for iUnit, oUnit in tExistingRadar do
                if oUnit:GetFractionComplete() >= 1 then
                    bHaveRadar = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bHaveRadar='..tostring(bHaveRadar)) end
        if not(bHaveRadar) then
            --Are we able to build radar? assume we can if we have access to T3 factories for simplicity
            if not(AiBotMap.bIsCampaignMap) or not(AiBotOverseer.bUnitRestrictionsArePresent) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 then
                HaveActionToAssign(refActionBuildT2Radar, 2, 10)
            end
        end
    end

    --Low priority air staging builder (max of 1) for expansion bases
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and (tLZTeamData[AiBotMap.subrefLZCoreExpansion] and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and not(bTeammateHasBuiltHere) and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] or -100) <= 2 and tLZTeamData[AiBotMap.subrefLZSValue] >= 400 and not(bHaveLowMass) and not(bHaveLowPower)) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        local bHaveAirStaging = false
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tAirStaging = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirStaging, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tAirStaging) == false then
                for iUnit, oUnit in tAirStaging do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then bHaveAirStaging = true break end
                end
            end
        end
        if not(bHaveAirStaging) then
            HaveActionToAssign(refActionBuildAirStaging, AiBotBuilding.iLowestAirStagingTechAvailable, 10)
            if bDebugMessages == true then LOG(sFunctionRef..': Low priority air staging builder') end
        end
    end


    --If still have an engineer available and there is reclaim in the LZ of any kind, and we arent overflowing, then reclaim
    iCurPriority = iCurPriority + 1
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.8 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] > 0.95 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.9) then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if bDebugMessages == true then LOG(sFunctionRef..': Very low priority reclaimer if have available engineers; iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
        if iHighestTechEngiAvailable > 0 then
            if tLZData[AiBotMap.subrefTotalMassReclaim] >= 5 then
                if bDebugMessages == true then LOG(sFunctionRef..': Lower priority reclaim, Total mass in Plateau '..iPlateau..' LZ '..iLandZone..'='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; will request at least 100 BP, but wont request more than we already have') end
                HaveActionToAssign(refActionReclaimArea, 1, 100, {false, nil}, true)
            end
        end
    end

    --Check for any part constructed buildings in this zone if we either have available engineers, or no engineers at all
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if AiBotUtilities.IsTableEmpty(tEngineers) or iHighestTechEngiAvailable > 0 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and table.getn(tEngineers) < 3) then
        local iCatToSearch
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
            iCatToSearch = AiBotUnitInfo.refCategoryPower
            if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti end
            if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryStructureAA end
        else
            iCatToSearch = AiBotUnitInfo.refCategoryStructure + categories.EXPERIMENTAL * categories.BUILTBYTIER3ENGINEER
        end
        local tBuildings = EntityCategoryFilterDown(iCatToSearch, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tBuildings) == false then
            for iUnit, oUnit in tBuildings do
                --Dont assist part complete shields as may be for special shielding logic
                if oUnit:GetFractionComplete() < 1 and not(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                    iBPWanted = 5
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) and oUnit:GetFractionComplete() >= 0.4 then
                        if not(bEngineersRecentlyRunFromEnemy) or oUnit:GetFractionComplete() >= 0.8 then
                            if oUnit:GetFractionComplete() >= 0.6 then iBPWanted = 120 else iBPWanted = 60 end
                        end
                    end
                    HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oUnit)
                    break
                end
            end
        end
    end

    --Build air factory if overflowing mass, ahve all T3 mexes in the zone, no adjacent enemies, and dont have low power
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Low priority factory builder: mass% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Enemies in this or adjacent zone='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; bTeammateHasBuiltHere='..tostring(bTeammateHasBuiltHere)..'; tLZTeamData[AiBotMap.subrefMexCountByTech][2]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech][2])) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and not(bEngineersRecentlyRunFromEnemy) and not(bHaveLowPower) and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and (tLZTeamData[AiBotMap.subrefMexCountByTech][math.min(3,AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech])] >= math.max(1, tLZData[AiBotMap.subrefLZOrWZMexCount]) or (not(bTeammateHasBuiltHere) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.99)) and AiBotConditions.WantMoreFactories(iTeam, iPlateau, iLandZone) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) then
        if not(bTeammateHasBuiltHere) or tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 then
            local iActionWanted
            local iTechWanted = 1
            if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData) then
                iActionWanted = refActionBuildAirFactory
                iTechWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]
            else
                iActionWanted = refActionBuildLandFactory
                iTechWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]
            end
            HaveActionToAssign(iActionWanted, iTechWanted, tiBPByTech[iTechWanted] * 3)
            if bDebugMessages == true then LOG(sFunctionRef..': Low priority minor zone factory builder, iActionWanted='..iActionWanted..'; iTechWanted='..iTechWanted) end
        end
    end

    --Get PD and SAM if have built an omni here
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build pd to protect omni in minor zone, tLZTeamData[AiBotMap.subrefLZSValue]='..tLZTeamData[AiBotMap.subrefLZSValue]..'; tLZTeamData[AiBotMap.refoBestRadar]='..(tLZTeamData[AiBotMap.refoBestRadar].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLZTeamData[AiBotMap.refoBestRadar]) or 'nil')..' assigned to P'..(tLZTeamData[AiBotMap.refoBestRadar][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(tLZTeamData[AiBotMap.refoBestRadar][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')..'; tLZTeamData[AiBotMap.refiRadarCoverage]='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')..'; T2 radar normal coverage='..(AiBotUnitInfo.iT2RadarSize or 'nil')..'; bHaveLowPower='..tostring(bHaveLowPower)..'; Stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or false)) end
    if tLZTeamData[AiBotMap.subrefLZSValue] >= 3000 and tLZTeamData[AiBotMap.refoBestRadar][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone and tLZTeamData[AiBotMap.refoBestRadar][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau and tLZTeamData[AiBotMap.refiRadarCoverage] > AiBotUnitInfo.iT2RadarSize and not(bHaveLowPower) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and (tLZTeamData[AiBotMap.refoBestRadar]:GetFractionComplete() >= 0.6 or not(bHaveLowMass)) then
        iBPWanted = 20
        if not(bHaveLowMass) then iBPWanted = 40 end
        local iExistingStructureThreat = 0
        local bHaveLRPDThreat = false
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                iExistingStructureThreat = iExistingStructureThreat + iThreat
                if iThreat > 0 and iRange >= 50 then bHaveLRPDThreat = true end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if want PD or AA to support omni in minor zone, iExistingStructureThreat='..iExistingStructureThreat..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
        if not(bHaveLRPDThreat) or iExistingStructureThreat <= 900 then
            local tBuildLocation = AiBotUtilities.MoveInDirection(tLZTeamData[AiBotMap.refoBestRadar]:GetPosition(), AiBotUtilities.GetAngleFromAToB(tLZTeamData[AiBotMap.refoBestRadar]:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]), 5, true)
            if not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tBuildLocation) == tLZData[AiBotMap.subrefLZIslandRef]) then tBuildLocation = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]} end
            HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted, tBuildLocation)
        elseif tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 0 then
            HaveActionToAssign(refActionBuildAA, 2, iBPWanted)
        end
    end

    --Paragon on team - consider building exp
    iCurPriority = iCurPriority + 1
    if not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbBuiltParagon] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] > 0.01 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will look to start work on an experimental given paragon on our team') end
        iBPWanted = 60
        if aiBrain:GetEconomyStoredRatio('MASS') < 0.1 and not(aiBrain[AiBotEconomy.refbBuiltParagon]) then iBPWanted = 30 end
        if ((NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestEnemyBase]) or 0) == (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZData[AiBotMap.subrefMidpoint]) or -1) and (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.35 or AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]) <= 350))
                and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] <= 6 + 6 * AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti))
        then

            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildLandExperimental,3, iBPWanted, nil, false, true)
        else
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, iPlateau, iLandZone, iTeam, tLZData, tLZTeamData, false, refActionBuildExperimental, 3, iBPWanted, nil, false, true)
        end
    end

    UpdateSpareEngineerNumber(tLZTeamData, toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': About to consider spare engi actions at time='..GetGameTimeSeconds()..', iHighestTechEngiAvailable='..iHighestTechEngiAvailable) end
    --Spare engi - assist any upgrading unit
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then
        if not(bHaveLowPower) and not(bPrioritiseProduction) then
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of active upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; have spare engis so will send any spare to assist any active upgrades') end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                HaveActionToAssign(refActionAssistUpgrade, 1, 1000, false, true, nil, nil, nil, true)
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
            end
        end

        --Spare engi - assist part complete buildings
        iCurPriority = iCurPriority + 1
        if iHighestTechEngiAvailable > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Have a spare engi, will look to see to see if htere are any part complete buildings in the area; if are stalling power then will only repair powergenerators') end
            local iCatToSearch
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy] then
                iCatToSearch = AiBotUnitInfo.refCategoryPower
                if tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryFixedT2Arti end
                if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then iCatToSearch = iCatToSearch + AiBotUnitInfo.refCategoryStructureAA end
            else
                iCatToSearch = AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryExperimentalLevel
            end
            local tFriendlyBuildings = EntityCategoryFilterDown(iCatToSearch, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tFriendlyBuildings) == false then
                local oUnitToAssist
                local iClosestToCompletion = 0
                for iUnit, oUnit in tFriendlyBuildings do
                    if oUnit:GetFractionComplete() < 1 and oUnit:GetFractionComplete() > iClosestToCompletion and not(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                        iClosestToCompletion = oUnit:GetFractionComplete()
                        oUnitToAssist = oUnit
                    end
                end
                if oUnitToAssist then
                    HaveActionToAssign(refActionRepairUnit, 1, 1000, oUnitToAssist, true, nil, nil, nil, true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try assisting unit '..oUnitToAssist.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist)) end
                end
            end


            --Low priority island support (for any spare engineers) - will consider further away distances tahn before, up to a distance of 400, and only if the island wants T1 engineer BP
            if iHighestTechEngiAvailable > 0 and (iIslandDistanceThreshold or 0) > 0 and iIslandDistanceThreshold <= 400 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) then
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                if iHighestTechEngiAvailable > 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': is pathing to other islands empty='..tostring( AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]))) end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; tLZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])) end

                        if bDebugMessages == true then LOG(sFunctionRef..': Will search for islands, iIslandDistanceThreshold='..iIslandDistanceThreshold) end

                        for iEntry, tPathingData in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..tPathingData[AiBotMap.subrefIslandNumber]..' for lower priority travel; travel dist='..tPathingData[AiBotMap.subrefIslandTravelDist]..'; Closest LZ ref='..(tPathingData[AiBotMap.subrefIslandClosestLZRef] or 'nil')..'; are enemies in this or adjacent LZ='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end
                            if tPathingData[AiBotMap.subrefIslandTravelDist] > iIslandDistanceThreshold then --Have already considered islands with a shorter travel distance above
                                if tPathingData[AiBotMap.subrefIslandTravelDist] > 400 then break --Too far to try and travel by engineer
                                else
                                    --Are there enemies in the target LZ?
                                    if tPathingData[AiBotMap.subrefIslandClosestLZRef] and not(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tPathingData[AiBotMap.subrefIslandClosestLZRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) then
                                        --function GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, iAdjLZ,                                iPathingRef, iHighestTechEngiAvailable, bNearbyZone, bIslandPathing, bRequireUnbuiltMexes, bCheckIfEngisRecentlyRun)
                                        local tiBPByTechWanted = GetBPByTechWantedForAlternativeLandZone(iPlateau, iTeam, tLZData, tPathingData[AiBotMap.subrefIslandClosestLZRef], iEntry, iHighestTechEngiAvailable, false,         true            , false,            false)
                                        if bDebugMessages == true then LOG(sFunctionRef..': tiBPByTechWanted='..repru(tiBPByTechWanted)) end
                                        if (tiBPByTechWanted[1] or 0) > 0 then
                                            HaveActionToAssign(refActionMoveToLandZone, 1, 5, tPathingData[AiBotMap.subrefIslandClosestLZRef], true) --wont flag as 'spare' since only assigning a small amount of BP
                                            if bDebugMessages == true then LOG(sFunctionRef..': Finished trying to give order for engi to move to the island LZ '..tPathingData[AiBotMap.subrefIslandClosestLZRef]) end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end

            --Spare engi action - go to any nearby land or water zone that wants BP
            iCurPriority = iCurPriority + 1

            if bDebugMessages == true then LOG(sFunctionRef..': iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; If have available engis then will look for other zones wanting them, time='..GetGameTimeSeconds()..'; Is table of other land and water zones by distance empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
            if iHighestTechEngiAvailable > 0 then
                local iZoneWithAnyReclaimOrCoreBase, iPlateauOrZeroOfZoneWithReclaimOrCoreBase, bZoneHasOnlyEnergyReclaim
                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through all other land and water zones, reprs='..reprs(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance])) end
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to travel to zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Distance='..tSubtable[AiBotMap.subrefiDistance]) end
                        if tSubtable[AiBotMap.subrefiDistance] <= 500 then
                            local tAdjLZOrWZData, tAdjLZOrWZTeamData
                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                tAdjLZOrWZData =AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                tAdjLZOrWZTeamData = tAdjLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            else
                                tAdjLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                tAdjLZOrWZTeamData = tAdjLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] or 'nil')..'; Wnats BP='..tostring(tAdjLZOrWZTeamData[AiBotMap.subrefTbWantBP] or false)..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAdjLZOrWZData[AiBotMap.subrefMidpoint]))..'; On same plateau='..tostring(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAdjLZOrWZData[AiBotMap.subrefMidpoint]) == iPlateau)..'; Mass reclaim='..(tAdjLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 'nil')..'; Energy reclaim='..(tAdjLZOrWZData[AiBotMap.subrefLZTotalEnergyReclaim] or 'nil')..'; tAdjLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tAdjLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or false)..'; tAdjLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..(tAdjLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; Mod dist%='..(tAdjLZOrWZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; Enemy S value='..(tAdjLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; tAdjLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..(tAdjLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')) end
                            if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAdjLZOrWZData[AiBotMap.subrefMidpoint]) == iPlateau and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZOrWZData[AiBotMap.subrefMidpoint])) then
                                local bDangerousZone
                                if tAdjLZOrWZTeamData[AiBotMap.subrefTbWantBP] then
                                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                        bDangerousZone = ((tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > (tAdjLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0))
                                    else
                                        bDangerousZone = (tAdjLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and (tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > (tAdjLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0))
                                        if not(bDangerousZone) then
                                            if tAdjLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.8 and tAdjLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] >= 200 and tAdjLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] < 10 then
                                                --Dont send spare engineers towards an enemy if DF units in an adjacent zone, or we lack intel and it's in the first 20m to stop over-engineer expansion into enemy base
                                                if AiBotUtilities.IsTableEmpty(tAdjLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false or (GetGameTimeSeconds() <= 1200 and (tAdjLZOrWZTeamData[AiBotMap.refiRadarCoverage] or 0) <= 10) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will treat zone as dangerous afterall as near enemy base, and nearby DF units') end
                                                    bDangerousZone = true
                                                end
                                            end
                                        elseif bDangerousZone and tAdjLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and (tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 0.5 * (tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) then bDangerousZone = false
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bDangerousZone='..tostring(bDangerousZone)) end
                                    if not(bDangerousZone) then
                                        local iCurBPWanted = 0
                                        local iMinTechWanted = 3
                                        for iTech, iBP in tAdjLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] do
                                            iMinTechWanted = math.min(iMinTechWanted, iTech)
                                            iCurBPWanted = iCurBPWanted + iBP
                                        end
                                        if iCurBPWanted > 0 and iHighestTechEngiAvailable >= iMinTechWanted then
                                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                --HaveActionToAssign(iActionToAssign,   iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable,                      bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                                                HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, iCurBPWanted,      tSubtable[AiBotMap.subrefiLandOrWaterZoneRef],true, true,nil,nil, false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                            else
                                                HaveActionToAssign(refActionMoveToLandZone, iMinTechWanted, iCurBPWanted, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], true, true,                    nil,                            nil,            false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                            end
                                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                            if iHighestTechEngiAvailable == 0 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': No longer have available engis so exiting loop') end
                                                break
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to record this zone as a potential destination for any further spare engineers, bDangerousZone='..tostring(bDangerousZone or false)..'; bDangerousZone is nil='..tostring(bDangerousZone == nil)..'; tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; tAdjLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]='..(tAdjLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 'nil')..'; iZoneWithAnyReclaimOrCoreBase='..(iZoneWithAnyReclaimOrCoreBase or 'nil')) end
                                if (not(iZoneWithAnyReclaimOrCoreBase) or bZoneHasOnlyEnergyReclaim) and ((tAdjLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 0) > 0 or (tAdjLZOrWZData[AiBotMap.subrefLZTotalEnergyReclaim] or 0) > 0 or (tAdjLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and tAdjLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 100)) and ((bDangerousZone == nil and (tAdjLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < (tAdjLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)) or (not(bDangerousZone == nil) and not(bDangerousZone))) then
                                    --if (tSubtable[AiBotMap.subrefiPlateauOrPond] == iPlateau and not(tSubtable[AiBotMap.subrefbIsWaterZone])) or (tSubtable[AiBotMap.subrefbIsWaterZone] and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAdjLZOrWZData[AiBotMap.subrefMidpoint]) == iPlateau) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Recording first plateau or pond and zone with reclaim in in case we want for spare engi action, or core base, total mass reclaim='..(tAdjLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 0)..'; Is core base='..tostring(tAdjLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; Zone='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Energy reclaim in this zone='..(tAdjLZOrWZData[AiBotMap.subrefLZTotalEnergyReclaim] or 0)) end
                                    iZoneWithAnyReclaimOrCoreBase = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                                    if  tSubtable[AiBotMap.subrefbIsWaterZone] then iPlateauOrZeroOfZoneWithReclaimOrCoreBase = 0
                                    else iPlateauOrZeroOfZoneWithReclaimOrCoreBase = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                    end
                                    if (tAdjLZOrWZData[AiBotMap.subrefTotalMassReclaim] or 0) == 0 and not(tAdjLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) then
                                        bZoneHasOnlyEnergyReclaim = true
                                    end
                                end
                            end
                        end
                    end
                else
                    AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
                end

                --Reclaim area if is any reclaim
                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                if bDebugMessages == true then LOG(sFunctionRef..': Spare engi action - reclaim area if any mass or energy in it, iHighestTechEngiAvailable='..iHighestTechEngiAvailable..'; Mass='..(tLZData[AiBotMap.subrefTotalMassReclaim] or 0)..'; Energy='..(tLZData[AiBotMap.subrefLZTotalEnergyReclaim] or 0)..'; iZoneWithAnyReclaimOrCoreBase='..(iZoneWithAnyReclaimOrCoreBase or 'nil')..'; tLZData[AiBotMap.subrefLZTotalEnergyReclaim]='..tLZData[AiBotMap.subrefLZTotalEnergyReclaim]..'; Team energy % stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) end
                if iHighestTechEngiAvailable > 0 then
                    if (tLZData[AiBotMap.subrefTotalMassReclaim] or 0) > 0 or (tLZData[AiBotMap.subrefLZTotalEnergyReclaim] or 0) > 0 then --treat energy reclaim as likely having some mass in it as well but of such a low value the normal mass check wont have picked it up
                        if bDebugMessages == true then LOG(sFunctionRef..': Will tyr and get remaining reclaim in area') end
                        HaveActionToAssign(refActionReclaimArea, 1, 90, {(tLZData[AiBotMap.subrefTotalMassReclaim] or 0) == 0, nil}, true, true, nil, nil, false)
                        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                    end

                    --Adjacent core zones if we have spare engis in this zone
                    if iHighestTechEngiAvailable > 0 then
                        local iTotalAvailableEngineerBP = 0
                        for iTech, tEngineers in toAvailableEngineersByTech do
                            if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                                iTotalAvailableEngineerBP = iTotalAvailableEngineerBP + tiBPByTech[iTech] * table.getn(tEngineers)
                            end
                        end
                        if iTotalAvailableEngineerBP >= 80 then
                            local iBPToSend = iTotalAvailableEngineerBP - 80
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]) then
                                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                        if tAdjLZTeamData[AiBotMap.subrefLZbCoreBase] or (tAdjLZTeamData[AiBotMap.subrefTbWantBP] and (not(tAdjLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or GetGameTimeSeconds() - (tAdjLZTeamData[AiBotMap.bEngineersRecentlyRunFromEnemy] or 0) >= 20)) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Minor zone spare engi overflow - will send to adjacent zone '..iAdjLZ..'; iPlateau='..iPlateau..'; iBPToSend='..iBPToSend) end
                                            HaveActionToAssign(refActionMoveToLandZone, 1, iBPToSend, iAdjLZ, true, nil, nil, nil, true)
                                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        --Other zones with reclaim or further away core bases
                        if iHighestTechEngiAvailable > 0 and iZoneWithAnyReclaimOrCoreBase then
                            local iBPToSend = math.max(iTotalAvailableEngineerBP - 40, math.min(iTotalAvailableEngineerBP - 5, 60), 5)
                            if iHighestTechEngiAvailable > 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will move (or attack move for land zone) to closest zone with reclaim or core base, current P='..iPlateau..'Z'..iLandZone..'; iZoneWithAnyReclaimOrCoreBase='..(iZoneWithAnyReclaimOrCoreBase or 'nil')..'; iPlateauOrZeroOfZoneWithReclaimOrCoreBase='..iPlateauOrZeroOfZoneWithReclaimOrCoreBase) end
                                if iPlateauOrZeroOfZoneWithReclaimOrCoreBase == 0 then
                                    HaveActionToAssign(refActionMoveToWaterZone, 1, iBPToSend,      iZoneWithAnyReclaimOrCoreBase,true, true,nil,nil, false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                else
                                    HaveActionToAssign(refActionAttackMoveToLandZone, 1, iBPToSend, iZoneWithAnyReclaimOrCoreBase, true, true,                    nil,                            nil,            false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                end
                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                            end
                        end
                        if iHighestTechEngiAvailable > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            --send 1 engi to attack move to each adjacent land zone
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if bDebugMessages == true then LOG(sFunctionRef..': Will tell an engi to attack move to an adjacent zone, iAdjLZ='..iAdjLZ..'; P='..iPlateau) end
                                HaveActionToAssign(refActionAttackMoveToLandZone, 1, 5, iAdjLZ, true, true,                    nil,                            nil,            false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                        --Ctrl-K if close to unit cap
                        if iHighestTechEngiAvailable > 0 and aiBrain[AiBotOverseer.refbCloseToUnitCap] == true and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer) >= 150 then
                            local bHaveTriedToKillEngineer = false
                            local iIdleEngineers = 0
                            for iCurEngiTechLevel = 1, 3 do
                                iIdleEngineers = table.getn(toAvailableEngineersByTech[iCurEngiTechLevel])
                            end
                            if iIdleEngineers >= 4 then
                                local iKilled
                                for iCurEngiTechLevel = 1, 3 do
                                    iKilled = ConsiderDestroyingLowTechEngineers(toAvailableEngineersByTech[iCurEngiTechLevel][1], 1, toAvailableEngineersByTech[iCurEngiTechLevel])
                                    if iKilled > 0 then break end
                                end
                            end
                        end
                    end
                end

            end
        end
    end


    --Do we have stuff to reclaim in this LZ and arent about to overflow mass? Decided to leave this out as looks like it can do more harm than good
    --[[iCurPriority = iCurPriority + 1
iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
if iHighestTechEngiAvailable > 0 and tLZData[AiBotMap.subrefTotalMassReclaim] >= 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.6 then
HaveActionToAssign(refActionReclaimArea, 1, math.min(100, math.max(10, tLZData[AiBotMap.subrefTotalMassReclaim] / 10)), false, true)
end--]]




    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function ConsiderWaterZoneEngineerAssignment(tWZTeamData, iTeam, iPond, iWaterZone, tEngineers)
    --Called from ConsiderLandOrWaterZoneEngineerAssignment
    local bDebugMessages = false
    if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderWaterZoneEngineerAssignment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iBPWanted
    local bHaveLowMass = AiBotConditions.TeamHasLowMass(iTeam)
    local bHaveLowPower = AiBotConditions.HaveLowPower(iTeam)
    local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
    local aiBrain = ArmyBrains[tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
    local iHighestTechEngiAvailable
    local iExistingWaterFactory = 0
    local oFirstWaterFactory
    local bHaveFactoryHQ = false
    local bDontCheckPlayableArea = false
    if AiBotMap.bIsCampaignMap then
        bDontCheckPlayableArea = true
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.rebTeamOnlyHasCampaignAI] then bDontCheckPlayableArea = false end
    end

    local bEngineersRecentlyRunFromEnemy = false
    if tWZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] and GetGameTimeSeconds() - tWZTeamData[AiBotMap.refiTimeLastRunFromEnemyLand] <= 30 then bEngineersRecentlyRunFromEnemy = true end

    if tWZTeamData[AiBotMap.subrefWZbCoreBase] then
        local tExistingWaterFactory = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tExistingWaterFactory) == false then
            for iFactory, oFactory in tExistingWaterFactory do
                if not(oFirstWaterFactory) or (AiBotUnitInfo.GetUnitLifetimeCount(oFactory) < AiBotUnitInfo.GetUnitLifetimeCount(oFirstWaterFactory) and AiBotUnitInfo.GetUnitTechLevel(oFactory) >= AiBotUnitInfo.GetUnitTechLevel(oFirstWaterFactory)) then
                    oFirstWaterFactory = oFactory
                end
                if oFactory:GetFractionComplete() == 1 then
                    iExistingWaterFactory = iExistingWaterFactory + 1
                    if not(bHaveFactoryHQ) and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oFactory.UnitId) then
                        bHaveFactoryHQ = true
                    end
                elseif not(bHaveFactoryHQ) and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oFactory.UnitId) then
                    bHaveFactoryHQ = true
                end
            end
            --If is a small pond then include adjacent zone naval factories
            if AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] * AiBotMap.iLandZoneSegmentSize <= 5000 or AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWZCount] <= 3 then
                for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                    local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                    if AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tAdjWZFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAdjWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tAdjWZFactories) == false then
                            for iFactory, oFactory in tExistingWaterFactory do
                                if oFactory:GetFractionComplete() == 1 then
                                    iExistingWaterFactory = iExistingWaterFactory + 1
                                    if not(bHaveFactoryHQ) and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oFactory.UnitId) then
                                        bHaveFactoryHQ = true
                                    end
                                elseif not(bHaveFactoryHQ) and EntityCategoryContains(AiBotUnitInfo.refCategoryNavalHQ, oFactory.UnitId) then
                                    bHaveFactoryHQ = true
                                end
                            end
                        end
                    end

                end
            end

            --Want to set flag to rebuild naval fac if we only have support facs (this won't work 100% if e.g. a teammate has a factory of a different faction in the zone or elsewhere, but should cover majority fo cases; also have the logic to xfer support facs to a teammate of same faction which shoudl help)
            --Note that need to keep it general as otherwise would likely run into issues of infinitely building naval facs (e.g. if we have UEF and Aeon support facs in zone, and UEF has an HQ elsewhere but Aeon doesnt, if we try and build naval fac as a result, we might be building UEF naval facs on repeat)
            if iExistingWaterFactory > 0 and not(bHaveFactoryHQ) then
                --Are we lacking an appropriate HQ for the support factory?
                local bHaveHQElsewhere = false
                for iFactory, oFactory in tExistingWaterFactory do
                    if oFactory:GetAIBrain()[AiBotEconomy.refiOurHighestNavalFactoryTech] > 0 then
                        bHaveHQElsewhere = true
                        break
                    end
                end
                if bHaveHQElsewhere then bHaveFactoryHQ = true end
            end
        end
    end



    local toAvailableEngineersByTech, toAssignedEngineers = FilterToAvailableEngineersByTech(tEngineers, false, tWZData, tWZTeamData, iTeam, iPond, iWaterZone, true)

    tWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] = { [1] = 0, [2] = 0, [3] = 0 }
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Time=' .. GetGameTimeSeconds() .. '; iPond=' .. iPond .. '; iWaterZone=' .. iWaterZone .. '; tWZTeamData[AiBotMap.subrefWZbCoreBase]=' .. tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase] or false) .. '; iExistingWaterFactory=' .. (iExistingWaterFactory or 'nil') .. '; Have just reset BPByTech to 0 for Pond' .. iPond .. '; WZ=' .. iWaterZone .. '; repru=' .. repru(tWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]) .. '; bHaveLowMass=' .. tostring(bHaveLowMass or false) .. '; bHaveLowPower=' .. tostring(bHaveLowPower or false))
    end
    --local iCurCondition = 0
    local iCurPriority = 0
    local iMinTechWanted = 1

    function HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
        --Done as subfunction for convenience so can just note the key values for the action in question and add on the others that wont change
        if iActionToAssign == refActionBuildNavalFactory and not(AiBotDualGap.CanBuildNavalFactory(aiBrain)) then
            return
        end
        ConsiderActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iCurPriority, tWZData, tWZTeamData, iTeam, iPond, iWaterZone, toAvailableEngineersByTech, toAssignedEngineers, true, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
    end

    --Emergency torp launcher if enemy has threat in this zone/nearby and we have a naval factory; also get on campaign maps after a while
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we need torpedo launcher, iExistingWaterFactory='..iExistingWaterFactory..'; Enemies in adj WZ='..tostring(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])..'; Is table of LR units empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftEnemyLongRangeUnits]))) end
    if not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) and iExistingWaterFactory > 0 and (tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] == 1 and AiBotMap.bIsCampaignMap and tWZTeamData[AiBotMap.subrefWZbCoreBase] and GetGameTimeSeconds() >= 600)) and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftEnemyLongRangeUnits]) then
        --If enemy best DF or IF range is <50 and they dont have hover units, then build torp launcher
        local iOurCombatThreat = 0
        local bEnemyHasLongRangeOrHover = AiBotConditions.DoesWaterZoneHaveUnitsThatCounterTorpDefence(tWZTeamData, iOurCombatThreat)
        if bDebugMessages == true then LOG(sFunctionRef..': tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]='..tostring(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies])..'; tWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange]='..(tWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] or 0)..'; tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange]='..(tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 0)..'; bEnemyHasLongRangeOrHover for this zone='..tostring(bEnemyHasLongRangeOrHover)) end
        if not(bEnemyHasLongRangeOrHover) then
            local iEnemyCombatThreat = (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat='..iEnemyCombatThreat..'; bEnemyHasLongRangeOrHover='..tostring(bEnemyHasLongRangeOrHover)) end
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                    local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                    bEnemyHasLongRangeOrHover = AiBotConditions.DoesWaterZoneHaveUnitsThatCounterTorpDefence(tAdjWZTeamData, iOurCombatThreat)
                    iEnemyCombatThreat = iEnemyCombatThreat + (tAdjWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; subrefbWZOnlyHoverEnemies='..tostring(tAdjWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies] or false)..'; subrefWZBestEnemyAntiNavyRange='..(tAdjWZTeamData[AiBotMap.subrefWZBestEnemyAntiNavyRange] or 'nil')..'; subrefWZBestEnemyDFRange='..(tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] or 'nil')..'; bEnemyHasLongRangeOrHover='..tostring(bEnemyHasLongRangeOrHover)) end
                    if bEnemyHasLongRangeOrHover then break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to build torp launchers, bEnemyHasLongRangeOrHover='..tostring(bEnemyHasLongRangeOrHover)..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; iOurCombatThreat='..iOurCombatThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat) end
            if not(bEnemyHasLongRangeOrHover) and (iEnemyCombatThreat >= 100 or AiBotMap.bIsCampaignMap) and (tWZTeamData[AiBotMap.subrefWZTThreatAllyLauncherDefenceTotal] < 7500 or (tWZTeamData[AiBotMap.subrefWZThreatAlliedAntiNavy] or 0) < (tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0)) then
                --Do we not have significantly more threat than enemy?
                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyCombatThreat='..iEnemyCombatThreat..'; iOurCombatThreat='..iOurCombatThreat..'; tWZTeamData[AiBotMap.subrefWZThreatAlliedAntiNavy]='..(tWZTeamData[AiBotMap.subrefWZThreatAlliedAntiNavy] or 'nil')..'; tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible]='..(tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 'nil')) end
                if iEnemyCombatThreat * 3 > iOurCombatThreat or (tWZTeamData[AiBotMap.subrefWZThreatAlliedAntiNavy] or 0) < 3 * (tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0) or AiBotMap.bIsCampaignMap then
                    iBPWanted = 20
                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                        iBPWanted = math.max(40, math.min(100, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 10))
                    end
                    iMinTechWanted = 1
                    local tExistingTorpLauncher = EntityCategoryFilterDown(tiActionCategory[refActionBuildTorpLauncher], tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    local iExistingTorpThreat = 0
                    if AiBotUtilities.IsTableEmpty(tExistingTorpLauncher) == false then
                        iExistingTorpThreat = AiBotUnitInfo.GetCombatThreatRating(tExistingTorpLauncher, false, false, false, true)
                        if iExistingTorpThreat >= 2500 or table.getn(tExistingTorpLauncher) >= 5 then
                            iMinTechWanted = 2
                        end
                        --Ignore part-complete buildings to make sure we keep building them
                        if iExistingTorpThreat > 0 then
                            for iTorp, oTorp in tExistingTorpLauncher do
                                if oTorp:GetFractionComplete() < 1 then
                                    iExistingTorpThreat = iExistingTorpThreat - AiBotUnitInfo.GetCombatThreatRating({ oTorp }, false, false, false, true)
                                end
                            end
                        end
                        if iExistingTorpThreat < 50 then iExistingTorpThreat = 0 end --redundancy for above
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iExistingTorpThreat='..iExistingTorpThreat..'; iEnemyCombatThreat='..iEnemyCombatThreat) end
                    if iExistingTorpThreat <= math.min(7500, math.max(3500,  iEnemyCombatThreat * 1.5)) and (iExistingTorpThreat == 0 or iEnemyCombatThreat + (tWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0) > 0.2 * iExistingTorpThreat) then
                        --If we have a naval factory, aim to build the torp launcher near to here
                        local tTargetTorpLauncherPosition = GetStartSearchPositionForTorpLauncherOrNilForDefault(tWZTeamData, tWZData, iWaterZone, iPond)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will build torp launcher, iMinTechWanted='..iMinTechWanted) end
                        if iMinTechWanted >= 2 then
                            HaveActionToAssign(refActionBuildTorpLauncher, iMinTechWanted, iBPWanted, tTargetTorpLauncherPosition)
                        else
                            HaveActionToAssign(refActionBuildT1TorpLauncher, iMinTechWanted, iBPWanted, tTargetTorpLauncherPosition)
                        end
                    end
                end
            end
        end
    end

    --High priority hydro if we have low energy and water zone start
    iCurPriority = iCurPriority + 1
    if tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] and AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
        iBPWanted = 5
        if bHaveLowPower or not (bHaveLowMass) then
            iBPWanted = 10
            if table.getn(tWZData[AiBotMap.subrefHydroUnbuiltLocations]) >= 2 then
                iBPWanted = 15
            end
        end
        HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
    end

    --High priority AA if we have a naval factory
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': High priority AA builder, iExistingWaterFactory='..iExistingWaterFactory..'; Enemy air to ground threat='..(tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Allied AA threat='..(tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil')) end
    if iExistingWaterFactory > 0 then
        local iAdjacentEnemyAirToGroundThreat = (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)
        local iAdjacentAlliedCombatThreat = (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tWZData)
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                if tSubtable[AiBotMap.subrefiDistance] >= 190 then
                    break
                end
                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                    if not(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] == iWaterZone) then
                        local tAdjWZTeamData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefWZTeamData][iTeam]
                        iAdjacentEnemyAirToGroundThreat = iAdjacentEnemyAirToGroundThreat + (tAdjWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)
                        iAdjacentAlliedCombatThreat = iAdjacentAlliedCombatThreat + (tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; subrefWZTThreatAllyCombatTotal='..(tAdjWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)) end
                    end
                else
                    iAdjacentEnemyAirToGroundThreat = iAdjacentEnemyAirToGroundThreat + (AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiEnemyAirToGroundThreat] or 0)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iAdjacentEnemyAirToGroundThreat='..iAdjacentEnemyAirToGroundThreat..'; iAdjacentAlliedCombatThreat='..iAdjacentAlliedCombatThreat..'; subrefbDangerousEnemiesInAdjacentWZ='..tostring(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])..'; subrefLZOrWZThreatAllyGroundAA='..tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]..'; subrefWZTThreatAllyCombatTotal='..tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]..'; refiEnemyAirToGroundThreat='..tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; Last fac assisted build count='..(tWZTeamData[AiBotMap.refoLastNavalFacAssisted][AiBotFactory.refiTotalBuildCount] or 'nil')) end
        if (not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 4000) and iAdjacentEnemyAirToGroundThreat * 1.5 > (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) or (iAdjacentEnemyAirToGroundThreat * 3 > (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) and tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] >= 200) then
            --If we havent got much of a naval force, enemies are nearby, then dont build enough SAMs to handle enemy air as it will just die to enemy navy
            if tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] and (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) >= 2500 and tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] > tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] and tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] > iAdjacentAlliedCombatThreat * 0.8 and tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] > (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) and (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 6000 or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= iAdjacentEnemyAirToGroundThreat * 0.4 or not(tWZTeamData[AiBotMap.refoLastNavalFacAssisted]) or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] > (tWZTeamData[AiBotMap.refoLastNavalFacAssisted][AiBotFactory.refiTotalBuildCount] or 0) * 1000) then
                if bDebugMessages == true then LOG(sFunctionRef..': Wont build AA afterall as worried it will die to enemy navy') end
                --If we have blueprint override for naval fac, and already have AA, then assist naval fac instead (for campaign missions where enemy can s tart with large air to ground threat like cybran mission 5)
            elseif oFirstWaterFactory and oFirstWaterFactory[AiBotFactory.refsFactoryNextBlueprintOverride] and (AiBotMap.bIsCampaignMap or EntityCategoryContains(categories.TECH1, oFirstWaterFactory.UnitId)) and tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= math.max(150, tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 2) then
                iBPWanted = 20
                HaveActionToAssign(refActionAssistNavalFactory, 1, iBPWanted, oFirstWaterFactory)
                if bDebugMessages == true then LOG(sFunctionRef..': Will assist naval factory as top priority as it has blueprint overrides') end
                iBPWanted = 5
                local iTechLevelWanted = math.max(1, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) - 1)
                HaveActionToAssign(refActionBuildAA, iTechLevelWanted, iBPWanted)
            else
                iBPWanted = 25
                if (not (bHaveLowMass) and not (bHaveLowPower)) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) >= 2) then
                    iBPWanted = 50
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and build AA for water zone') end
                local iTechLevelWanted = math.max(1, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) - 1)
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 2 and (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) - (tWZTeamData[AiBotMap.subrefWZThreatAlliedMAA] or 0) >= 2000 then iTechLevelWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] end
                HaveActionToAssign(refActionBuildAA, iTechLevelWanted, iBPWanted)
            end
        end
    end

    --Higih priority mex if we have water zone start
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] and not(AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tWZData, true)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 then
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': We want to build a mex asap as we have unbuilt locations and have started in water')
        end
        iBPWanted = math.max(5, table.getn(tWZData[AiBotMap.subrefMexUnbuiltLocations]) * 2.5)
        if bHaveLowPower and not(bHaveLowMass) and iBPWanted > 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
            iBPWanted = 5
        elseif bHaveLowPower and iBPWanted > 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80  then
            iBPWanted = 10
        end
        HaveActionToAssign(refActionBuildMex, 1, iBPWanted)
    end

    --High priority reclaim with 1 engi if low mass and have reclaim
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering high priority reclaim, tWZData[AiBotMap.subrefTotalSignificantMassReclaim]='..(tWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')..'; bHaveLowMass='..tostring(bHaveLowMass)) end
    if bHaveLowMass and (tWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 50 then
        HaveActionToAssign(refActionReclaimArea, 1, 5, { false, math.min((tWZData[AiBotMap.subrefHighestIndividualReclaim] or 10), 40) })
    end

    --Naval fac if this is a core WZ and we dont have any (or lack an HQ), with eco condition
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef .. ': First naval fac builder, about to see if we want to build a naval factory, subrefWZbCoreBase=' .. tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase] or false) .. '; tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation]='..tostring(tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation] or false)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]=' .. (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] or 'nil')..'; First AiBot lifetime factory highest build count='..(AiBotTeam.GetFirstActiveAiBotBrain(iTeam)[AiBotFactory.refiHighestFactoryBuildCount] or 'nil')..'; WZ brain build count='..(aiBrain[AiBotFactory.refiHighestFactoryBuildCount] or 'nil')..'; DelayNavyWhereLessImportant='..tostring(AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam) or false)..'; iTeam='..iTeam..'; subrefiTimeNavalFacHadNothingToBuild='..GetGameTimeSeconds() - (tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] or -10000)) end
    local iFactoriesWanted
    if tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] and GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] <= 60 and (GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] <= 20 or AiBotUnitInfo.IsUnitRestricted('ues0103', tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex])) then
        if tWZTeamData[AiBotMap.subrefWZbCoreBase] and not(AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam)) then iFactoriesWanted = 1 else iFactoriesWanted = 0 end
    elseif (not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) or iExistingWaterFactory == 0) and ((tWZTeamData[AiBotMap.subrefWZbCoreBase] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 3.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotMap.bIsCampaignMap or ((not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2.5) or aiBrain[AiBotFactory.refiHighestFactoryBuildCount] >= 30)))
            or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]
            or (not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1 and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.5 or aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0) and (iExistingWaterFactory > 0 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] < 3 and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryNavalFactory, iTeam) < math.min(9, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 0.6))))) then
        --Is this a priority pond for our team to expand to?
        if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 'nil')..'; DelayNavyWhereLessImportant='..tostring(AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam) or false)) end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 7 or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 4 and AiBotMap.iMapSize > 512) or (iExistingWaterFactory > 0 and tWZTeamData[AiBotMap.subrefWZbCoreBase]) or (aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 2) or (tWZTeamData[AiBotMap.subrefWZbCoreBase] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies]) or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2))) then
            if (tWZTeamData[AiBotMap.subrefWZbCoreBase] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] > 2 and tWZTeamData[AiBotMap.subrefWZFactoryDestroyedCount] < 4)) or (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 2 + 3 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 and not(bHaveLowPower) and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 3) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeNaval] < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 3) and (aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 or not(aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence])) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 1)) then
                if AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam) then
                    iFactoriesWanted = 0
                else
                    iFactoriesWanted = 1
                    local bPrioritiseNonNavy = aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseLand]
                    --if bHaveLowMass then iFactoriesWanted = math.max(1, iFactoriesWanted * 0.5) end
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': iFactoriesWanted=' .. iFactoriesWanted .. '; iExistingWaterFactory=' .. iExistingWaterFactory)
                    end
                    --Increase factories wanted based on how important the pond is; whether we can path to the enemy with navy; our gross mass income; whether it is a core base; and whehter we have reached T2 navy in this pond yet
                    --however, dont increase factories if we are stalling mass (unles are at t1 with high value water zone)
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] >= 14 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 and ((tWZTeamData[AiBotMap.subrefWZbCoreBase] and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] == 1)) or not(bHaveLowMass))
                            --AI subtypes - dont get as many naval facs if low on mass
                            and (not(bHaveLowMass) or (not(bPrioritiseNonNavy) and aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] < 3))
                            and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 1
                    then
                        local iExtraFactoriesValue = 1
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] >= 21 then iExtraFactoriesValue = iExtraFactoriesValue + 1 end
                            if not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) then iExtraFactoriesValue = iExtraFactoriesValue + 1 end
                            if tWZTeamData[AiBotMap.subrefWZbCoreBase] then iExtraFactoriesValue = iExtraFactoriesValue + 1 else iExtraFactoriesValue = math.min(2, iExtraFactoriesValue * 0.5) end
                            --Decrease factories wanted if have T2/T3 navy
                            if aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 3 then
                                iExtraFactoriesValue = math.max(1, iExtraFactoriesValue - 2)
                            elseif aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 2 and iExtraFactoriesValue >= 3 then
                                iExtraFactoriesValue = math.max(1, iExtraFactoriesValue - 1)
                            end
                        end
                        --Subject to gross mass threshold
                        iExtraFactoriesValue = math.min((aiBrain[AiBotEconomy.refiGrossMassBaseIncome] - 4) * 0.5, iExtraFactoriesValue)
                        if bHaveLowMass then
                            iExtraFactoriesValue = iExtraFactoriesValue * 0.5
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iExtraFactoriesValue = math.min(1, iExtraFactoriesValue * 0.5) end
                            --Take into account adjacent zone factories
                            local iAdjacentZoneFacs = 0
                            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                    local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                    if tAdjWZTeamData[AiBotMap.refiTimeLastBuiltAtFactory] then
                                        local tAdjFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAdjWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                        if AiBotUtilities.IsTableEmpty(tAdjFactories) == false then
                                            iAdjacentZoneFacs = iAdjacentZoneFacs + table.getn(tAdjFactories)
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iAdjacentZoneFacs='..iAdjacentZoneFacs..'; iExtraFactoriesValue before adj for this='..iExtraFactoriesValue) end
                            if iAdjacentZoneFacs > 0 then
                                iExtraFactoriesValue = math.max(iExtraFactoriesValue * 0.1, iExtraFactoriesValue - iAdjacentZoneFacs * 0.5)
                            end
                        end
                        if bPrioritiseNonNavy then iExtraFactoriesValue = iExtraFactoriesValue * 0.5 end
                        iFactoriesWanted = math.min(5, iFactoriesWanted + iExtraFactoriesValue)
                        if bDebugMessages == true then LOG(sFunctionRef..': iExtraFactoriesValue='..iExtraFactoriesValue..'; iFactoriesWanted='..iFactoriesWanted..'; Team is stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; bHaveLowMass='..tostring(bHaveLowMass)..'; gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                    end
                    --(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 16 or not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]))
                    if tWZTeamData[AiBotMap.subrefWZbCoreBase] and aiBrain[AiBotOverseer.refbPrioritiseNavy] and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then iFactoriesWanted = iFactoriesWanted + 1 end
                    if iExistingWaterFactory < iFactoriesWanted or not(bHaveFactoryHQ) then
                        iBPWanted = 40
                        if bHaveLowMass then
                            if iExistingWaterFactory > 0 then iBPWanted = 25 else iBPWanted = 35 end
                        end
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.65 end
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': We want to build a naval factory, or assist if oFirstWaterFactory has low build count, oFirstWaterFactory='..(oFirstWaterFactory.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFirstWaterFactory) or 'nil')..'; oFirstWaterFactory[AiBotFactory.refiTotalBuildCount]='..(oFirstWaterFactory[AiBotFactory.refiTotalBuildCount] or 'nil'))
                        end
                        if oFirstWaterFactory and iExistingWaterFactory >= 1 and (iExistingWaterFactory >= 2 or oFirstWaterFactory:GetFractionComplete() == 1) and oFirstWaterFactory[AiBotFactory.refiTotalBuildCount] < 3 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will assist oFirstWaterFactory') end
                            HaveActionToAssign(refActionAssistNavalFactory, 1, iBPWanted, oFirstWaterFactory)
                            HaveActionToAssign(refActionBuildNavalFactory, 1, 5, nil)
                        else
                            HaveActionToAssign(refActionBuildNavalFactory, 1, iBPWanted, nil)
                        end
                    end
                end
            end
        end
    end

    --Other scenarios where we want factories
    if not(iFactoriesWanted) and not(bEngineersRecentlyRunFromEnemy) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 1 then --i.e. we havent triggered the high priority builder - still work out if we want facs in this zone
        if AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam) then
            iFactoriesWanted = 0
        elseif tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy] then
            if bDebugMessages == true then LOG(sFunctionRef..': Time since we last ctrlkd naval fac due to stuck navy='..GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]..'; Core base='..tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase])) end
            if tWZTeamData[AiBotMap.subrefWZbCoreBase] and GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy] >= 60 then
                iFactoriesWanted = 1
                if GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy] >= 600 and not(bHaveLowMass) and not(bHaveLowPower) then iFactoriesWanted = 2 end
                if bDebugMessages == true then LOG(sFunctionRef..': Been a while since we last destroyed for stuck navy, iFactoriesWanted='..iFactoriesWanted) end
            else
                iFactoriesWanted = 0
            end
        elseif (not (bHaveLowMass) or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or (iExistingWaterFactory > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]))) and (not (bHaveLowPower) or (tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] > 1 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or -100) >= 10)) and ((tWZTeamData[AiBotMap.subrefWZbCoreBase] and (tWZTeamData[AiBotMap.subrefTbWantBP] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= 10000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) or (tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (tWZTeamData[AiBotMap.subrefTbWantBP] or not (bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 12 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]))) then
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if have valuable pond or underwater start, pond value='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] or false)..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Time since bombardment mode last='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond] or -10)..'; subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 7 or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 4 and AiBotMap.iMapSize > 512) or (iExistingWaterFactory > 0 and tWZTeamData[AiBotMap.subrefWZbCoreBase]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2))) then
                --Dont build another naval fac if are in bombardment mode unless close to overflowing
                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond] or -10) >= 4.1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
                    iFactoriesWanted = 1
                    if (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iExistingWaterFactory <= 1 and tWZTeamData[AiBotMap.subrefWZbCoreBase]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 0) >= 60 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] or 0) >= 30) then
                        --Subtypes that dont want to prioritise navy - avoid getting more than 1 naval fac unless have lots of mass
                        if aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseLand] then
                            if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and (tWZTeamData[AiBotMap.subrefWZbCoreBase] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.45) then iFactoriesWanted = 2 end
                        else
                            if (not (bHaveLowMass) or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) then
                                iFactoriesWanted = 2
                            end
                            if tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] then
                                iFactoriesWanted = math.min(8, math.max(2, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / 2))
                            end
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 100 then
                                iFactoriesWanted = 3
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iFactoriesWanted after initail consideration='..iFactoriesWanted) end

                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 6 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                                --Consider getting 3 factories if enemy has a naval factory in this pond and doesn't have T2+
                                local bEnemyHasT1OnlyNavalFacs = false --true if they both have T1 naval facs and dont ahve T2+
                                local bEnemyHasT2PlusFacs = false
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] == 1 and AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]) == false then
                                    for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                                        if tSubtable[AiBotMap.subrefWZAWZDistance] >= 375 then break end
                                        local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefWZAWZRef]][AiBotMap.subrefWZTeamData][iTeam]
                                        if AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                            local tEnemyNavalFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                                            if AiBotUtilities.IsTableEmpty(tEnemyNavalFactories) == false then
                                                for iFactory, oFactory in tEnemyNavalFactories do
                                                    if EntityCategoryContains(categories.TECH1, oFactory.UnitId) then
                                                        bEnemyHasT1OnlyNavalFacs = true
                                                    else
                                                        bEnemyHasT1OnlyNavalFacs = false
                                                        bEnemyHasT2PlusFacs = true
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if bEnemyHasT2PlusFacs then break end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bEnemyHasT1OnlyNavalFacs='..tostring(bEnemyHasT1OnlyNavalFacs)..'; bEnemyHasT2PlusFacs='..tostring(bEnemyHasT2PlusFacs)) end
                                    if bEnemyHasT1OnlyNavalFacs and not(bEnemyHasT2PlusFacs) then
                                        iFactoriesWanted = math.max(iFactoriesWanted + 1, 3)
                                    end
                                end
                            end
                        end
                    end

                    if aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 or not(aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence]) or tWZTeamData[AiBotMap.subrefWZbCoreBase] then iFactoriesWanted = 0 end
                end
            end
        end
        if not(iFactoriesWanted) then
            iFactoriesWanted = 0
            if tWZTeamData[AiBotMap.subrefWZbCoreBase] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 4 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 7 or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 4 and AiBotMap.iMapSize > 512) or (iExistingWaterFactory > 0 and tWZTeamData[AiBotMap.subrefWZbCoreBase]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2))) then
                    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond] or -10) >= 4.1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] then
                        iFactoriesWanted = 1
                        if not(bHaveLowMass) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 then
                            if aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseLand] then
                                if not(bHaveLowMass) and not(bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.45 and (tWZTeamData[AiBotMap.subrefWZbCoreBase] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.55) then iFactoriesWanted = 2 end
                            else
                                iFactoriesWanted = 2
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 and not(bHaveLowPower) then iFactoriesWanted = 3 end
                                if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] then iFactoriesWanted = math.max(1, iFactoriesWanted * 0.5) end
                            end
                        end

                        if tWZTeamData[AiBotMap.subrefWZbCoreBase] and aiBrain[AiBotOverseer.refbPrioritiseNavy] and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then iFactoriesWanted = iFactoriesWanted + 1 end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Further naval fac check for high mass, iFactoriesWanted before this='..(iFactoriesWanted or 'nil')..'; Mass%='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; bHaveLowPower='..tostring(bHaveLowPower or false)..'; Pond value='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 'nil')) end
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) >= 4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and not(bHaveLowPower) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 or GetGameTimeSeconds() >= 300) and GetGameTimeSeconds() - (tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] or -100) >= 30 then
            if iFactoriesWanted == 0 and AiBotConditions.DelayNavyWhereLessImportant(aiBrain, tWZData, tWZTeamData, iTeam) then
                --Do nothing
            else
                iFactoriesWanted = 4
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.99 then
                    iFactoriesWanted = math.min(4, AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] * AiBotMap.iLandZoneSegmentSize / 2000) --e.g. tabula ross pond is a size of 2379, but really would only want 2 naval facs in it, have done /1k to be safe though
                end
                if aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseLand] then
                    iFactoriesWanted = math.min(iFactoriesWanted, 2)
                end
                if iFactoriesWanted >= 2 and not(tWZTeamData[AiBotMap.subrefWZbCoreBase]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 0) < 10 then
                    iFactoriesWanted = math.max(1, iFactoriesWanted * 0.5)
                end
            end
        end
    end
    if not(iFactoriesWanted) then iFactoriesWanted = 0 end

    if bEngineersRecentlyRunFromEnemy and iFactoriesWanted and iFactoriesWanted > 1 then iFactoriesWanted = 1 end

    if bDebugMessages == true then
        LOG(sFunctionRef .. ': About to consider what actions we want to give engineers for iPond=' .. iPond .. '; iWaterZone=' .. iWaterZone .. '; iTeam=' .. iTeam .. '; iFactoriesWanted='..iFactoriesWanted..'; Is table of unbuilt mex locations empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations])) .. '; Is table of part complete mexes empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoPartBuiltMexes])))
    end

    --Emergency AA (slightly lower priority than above)
    iCurPriority = iCurPriority + 1
    if (not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] <= 4000) and (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 0.25 and (tWZTeamData[AiBotMap.subrefWZbCoreBase] or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) and
        (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 0.6 or not(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < 800 * aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] * aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]) then
        iBPWanted = 25
        if not (bHaveLowMass) and not (bHaveLowPower) then
            iBPWanted = 50
        end
        local iTechLevelWanted = math.max(1, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) - 1)
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 2 and (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) - (tWZTeamData[AiBotMap.subrefWZThreatAlliedMAA] or 0) >= 2000 then iTechLevelWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
        HaveActionToAssign(refActionBuildAA, iTechLevelWanted, iBPWanted)
    end

    --Unclaimed mex in the zone
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Considering if unbuilt or part build mexes in t his WZ ' .. iWaterZone .. ', is subrefMexUnbuiltLocations empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations])) .. '; Is subreftoPartBuiltMexes empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoPartBuiltMexes])) .. '; Is table of mex locations empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefLZOrWZMexLocations])) .. '; Enemy combat threat=' .. tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
            LOG(sFunctionRef .. ': Size of unbuilt locations table=' .. table.getn(tWZData[AiBotMap.subrefMexUnbuiltLocations]))
        end
    end
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and not(AiBotOverseer.bNoRushActive and AiBotConditions.NoRushPreventingHydroOrMex(tWZData, true)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 then
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': We want to build a mex as we have unbuilt locations')
        end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = 5
        else
            iBPWanted = math.max(5, table.getn(tWZData[AiBotMap.subrefMexUnbuiltLocations]) * 2.5)
            if bHaveLowPower and not(bHaveLowMass) and iBPWanted > 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 then
                iBPWanted = 5
            elseif bHaveLowPower and iBPWanted > 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 80  then
                iBPWanted = 10
            end
        end
        HaveActionToAssign(refActionBuildMex, 1, iBPWanted)
    elseif AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
        --Do we have no engineers assigned to building a mex?
        local bHaveEngisBuilding = false
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Have part built mexes, is toAssignedEngineers empty=' .. tostring(AiBotUtilities.IsTableEmpty(toAssignedEngineers)))
        end
        if AiBotUtilities.IsTableEmpty(toAssignedEngineers) == false then
            for iEngi, oEngi in toAssignedEngineers do
                if oEngi[refiAssignedAction] == refActionBuildMex then
                    bHaveEngisBuilding = true
                    break
                end
            end
        end
        if not (bHaveEngisBuilding) then
            --Refresh list of mexes
            RefreshPartBuiltMexList(tWZTeamData)
            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
                HaveActionToAssign(refActionCompletePartBuiltMex, 1, 5)
            end
        end
    elseif AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then
        --Does the enemy have mexes in this WZ but doesnt have combat threat? If so then try and reclaim
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Checking if enemy has any mexes in this WZ, Is table of enemey units empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits])) .. '; Enemy combat threat=' .. tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal])
        end
        if tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 15 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            local tEnemyMexes = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tWZTeamData[AiBotMap.subrefTEnemyUnits])
            if bDebugMessages == true then
                LOG(sFunctionRef .. 'Is table of enemy mexes empty=' .. tostring(AiBotUtilities.IsTableEmpty(tEnemyMexes)))
            end
            if AiBotUtilities.IsTableEmpty(tEnemyMexes) == false then
                HaveActionToAssign(refActionReclaimEnemyUnit, 1, 5, tEnemyMexes)
            end
        end
    end


    --Lower priority mass reclaim where will request engineers to reclaim
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want minor reclaim for zone, team % mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Total mass reclaim='..(tWZData[AiBotMap.subrefTotalMassReclaim] or 'nil')) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.35 and (tWZData[AiBotMap.subrefTotalMassReclaim] or 0) >= 5 then
        local iReclaimFactor
        if GetGameTimeSeconds() <= 540 then
            iReclaimFactor = 125
        else
            if bHaveLowMass then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.01 then
                    iReclaimFactor = 50
                else
                    iReclaimFactor = 60
                end
            else
                iReclaimFactor = 70
            end
        end
        iBPWanted = math.max(5, tWZData[AiBotMap.subrefTotalMassReclaim] / iReclaimFactor)
        if not(bHaveLowMass) then
            if iBPWanted > 40 then iBPWanted = math.max(40, iBPWanted * 0.5) end
        elseif iBPWanted > 60 then iBPWanted = 60 + (iBPWanted - 60) * 0.5
        end
        if iBPWanted > 15 and GetGameTimeSeconds() <= 540 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
            iBPWanted = math.min(iBPWanted, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * 10)
        end
        if tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] then
            iBPWanted = math.max(5, iBPWanted * 0.6)
        end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = math.min(15, iBPWanted * 0.25) end

        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Lower priority reclaim, Total mass in Pond ' .. iPond .. ' WZ ' .. iWaterZone .. '=' .. tWZData[AiBotMap.subrefTotalMassReclaim]..'; BP to assign='..math.min(100, math.max(5, iBPWanted)))
        end
        HaveActionToAssign(refActionReclaimArea, 1, math.min(100, math.max(5, iBPWanted)), {false, nil}, false)
    end

    --Unclaimed hydro
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefHydroUnbuiltLocations]) == false and not(bEngineersRecentlyRunFromEnemy) then
        iBPWanted = 10
        if table.getn(tWZData[AiBotMap.subrefHydroUnbuiltLocations]) >= 2 then
            iBPWanted = 20
        end
        HaveActionToAssign(refActionBuildHydro, 1, iBPWanted)
    end

    --Mexes or significant reclaim in an adjacent zone, with no enemies in this or adjacent zone, and we have low mass
    --Send engineer to a water zone near this that wants support, or alternatively a land zone adjacent to that water zone that wants support
    iCurPriority = iCurPriority + 1
    local iLZSentTo = 0
    if bDebugMessages == true then LOG(sFunctionRef..': Considering high priority reclaim for adjacent water zones, bHaveLowMass='..tostring(bHaveLowMass)..'; subrefbDangerousEnemiesInAdjacentWZ='..tostring(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or false)..'; Is table of other WZ empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]))) end
    if bHaveLowMass and not(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]) == false then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': About to check if have adjacent water zones wanting engineers for mex or reclaim, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable)
        end
        if iHighestTechEngiAvailable > 0 then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                local iAdjWZ = tSubtable[AiBotMap.subrefWZAWZRef]
                local tAltWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAltWZData[AiBotMap.subrefMidpoint]) then
                    local tAltWZTeamData = tAltWZData[AiBotMap.subrefWZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef .. ': Considering iAdjWZ=' .. iAdjWZ .. '; tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]=' .. tostring(tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or false) .. '; tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTbWantBP]=' .. tostring(tAltWZTeamData[AiBotMap.subrefTbWantBP]) .. '; WZ table of unclaimed mexes is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefMexUnbuiltLocations])) .. '; WZ table of unbuilt hydro is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefHydroUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of engis traveling here empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEngineersTravelingHere]))..'; Is table of friendly units in this alt zone empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                    if tAltWZTeamData[AiBotMap.subrefTbWantBP] and (tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 or (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] >= math.min(6000, math.max(100, tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.75))) and tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][1] > 0
                            --Do we have mexes or significant reclaim here?
                            and ((tAltWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) > 150 or (tAltWZData[AiBotMap.subrefLZOrWZMexCount] > 0 and AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefMexUnbuiltLocations]) == false)) then
                        if AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) and (AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory, tAltWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) then
                            iLZSentTo = iLZSentTo + 1
                            iBPWanted = 5 * iLZSentTo
                            HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, iBPWanted, iAdjWZ, true)
                            if iLZSentTo >= 2 then break end
                        end
                    end
                end
            end
        end
    end

    --Multiple mex upgrades (water zone) - want to assist as a higher priority
    iCurPriority = iCurPriority + 1
    if (tWZTeamData[AiBotMap.subrefiActiveMexUpgrades] or 0) >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and not(bEngineersRecentlyRunFromEnemy) then
        iBPWanted = 10
        if not(bHaveLowPower) then
            iBPWanted = tWZTeamData[AiBotMap.subrefiActiveMexUpgrades] * 15
        end
        HaveActionToAssign(refActionAssistUpgrade, 1, iBPWanted)
    end

    --Assist naval fac if have recently assisted one that hasnt built much
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Do we have a last naval fac assisted? iCurPriority='..iCurPriority..'; refoLastNavalFacAssisted='..(tWZTeamData[AiBotMap.refoLastNavalFacAssisted].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tWZTeamData[AiBotMap.refoLastNavalFacAssisted]) or 'nil')..'; Pond value='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] or 'nil')..'; Fac build count='..(tWZTeamData[AiBotMap.refoLastNavalFacAssisted][AiBotFactory.refiTotalBuildCount] or 'nil')) end
    if tWZTeamData[AiBotMap.refoLastNavalFacAssisted] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiPriorityPondValues][AiBotMap.tiPondByWaterZone[iWaterZone]] >= 14 and ((tWZTeamData[AiBotMap.refoLastNavalFacAssisted][AiBotFactory.refiTotalBuildCount] or 0) < 5 or not(bHaveLowMass))
            and AiBotUnitInfo.IsUnitValid(tWZTeamData[AiBotMap.refoLastNavalFacAssisted]) and (not(tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild]) or GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] > 60 or (tWZTeamData[AiBotMap.refoLastNavalFacAssisted]:GetWorkProgress()>0 and (not(AiBotUnitInfo.IsUnitRestricted('ues0103', tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex])) or GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] > 20))) then
        local iFacTechLevel = AiBotUnitInfo.GetUnitTechLevel(tWZTeamData[AiBotMap.refoLastNavalFacAssisted])
        if (tWZTeamData[AiBotMap.refoLastNavalFacAssisted][AiBotFactory.refiTotalBuildCount] or 0) < 3 or iFacTechLevel <= 2 or not(bHaveLowMass) then
            local iBPWanted = math.min(8 * tiBPByTech[iFacTechLevel], (tWZTeamData[AiBotMap.refiHighestNavalFacAssistBP] or 50))
            if bHaveLowMass then
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then
                    iBPWanted = iBPWanted * 0.5
                else
                    iBPWanted = iBPWanted * 0.75
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Will assist naval fac as tWZTeamData[AiBotMap.refoLastNavalFacAssisted] is valid, iBPWanted='..iBPWanted) end
            --AssignBuildExperimentalOrT3NavyAction(fnHaveActionToAssign, iPlateau,                                                             iLandOrWaterZone, iTeam, tLZOrWZData, tLZOrWZTeamData, bIsWaterZone, iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData,        true,      refActionAssistNavalFactory, 1,         iBPWanted,          false,                  false)
        end
    end

    --Extra naval facs if need build power and dont have low mass and have positive net energy income
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': About to see if we want to build a naval factory, is this a core WZ base=' .. tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase]) .. '; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] .. '; bHaveLowMass=' .. tostring(bHaveLowMass) .. '; bWantBP=' .. tostring(tWZTeamData[AiBotMap.subrefTbWantBP])..'; Time since pond last in bombardment mode='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond] or -10)..'; iFactoriesWanted='..(iFactoriesWanted or 'nil'))
    end
    if iExistingWaterFactory < iFactoriesWanted and (not (bHaveLowMass) or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or tWZTeamData[AiBotMap.subrefWZbCoreBase] or iExistingWaterFactory == 0) then
        --if bHaveLowMass then iFactoriesWanted = math.max(1, iFactoriesWanted * 0.5) end
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Lower priority builder for naval fac, iFactoriesWanted=' .. iFactoriesWanted .. '; iExistingWaterFactory=' .. iExistingWaterFactory..'; Pond segment size='..AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount])
        end
        if not(bHaveLowMass) then iBPWanted = 60 else
            iBPWanted = 30
            if not(tWZTeamData[AiBotMap.subrefWZbCoreBase]) then iBPWanted = 15 end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.35 end
        end
        if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
        HaveActionToAssign(refActionBuildNavalFactory, 1, iBPWanted, nil)
    end

    --Build sonar if no nearby enemies and lack decent coverage and have decent eco
    iCurPriority = iCurPriority + 1
    --Coverage set at 100, as can have large water zones, with sonar built on edge, meaning T2 sonar doesnt even give 100 coverage of its own midpoint
    if not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) and tWZTeamData[AiBotMap.refiSonarCoverage] <= 100 and not(bEngineersRecentlyRunFromEnemy) and not (bHaveLowMass) and not (bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2 and tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and not (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamHasOmniVision]) then
        local iGrossMassWanted = 6
        local iGrossEnergyWanted = 125
        iBPWanted = 15
        if not (tWZTeamData[AiBotMap.subrefWZbCoreBase]) then
            iGrossMassWanted = iGrossMassWanted * 2
            iGrossEnergyWanted = iGrossEnergyWanted * 2
        else
            iBPWanted = 40
        end
        if tWZTeamData[AiBotMap.refiSonarCoverage] == 0 then
            iGrossMassWanted = iGrossMassWanted * 0.8
            iGrossEnergyWanted = iGrossEnergyWanted * 0.8
            if AiBotMap.bIsCampaignMap and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
                iGrossMassWanted = iGrossMassWanted * 0.7
                iGrossEnergyWanted = iGrossEnergyWanted * 0.7
            end
        end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= iGrossMassWanted and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= iGrossEnergyWanted and AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] >= 10 then
            local iPondSize = math.min((AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondMaxX] - AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondMinX]), (AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondMaxZ] - AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondMinZ]))

            if iPondSize >= 50 and (iPondSize >= 90 or tWZTeamData[AiBotMap.subrefWZbCoreBase]) then
                --Check we dont have any T2+ sonar in this WZ as sometimes water zones are so big that they dont get great coverage from sonar
                local tFriendlySonar
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    tFriendlySonar = EntityCategoryFilterDown(AiBotUnitInfo.refCategorySonar, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                end
                if AiBotUtilities.IsTableEmpty(tFriendlySonar) then
                    --Build t1 sonar if enemy has enemies in adjacent WZ or we have reached 400 gross mass income, T2 if no enemies in this or adjacent
                    if (iPondSize >= 200 or (iPondSize >= 150 and tWZTeamData[AiBotMap.subrefWZbCoreBase])) and not (tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750) then
                        HaveActionToAssign(refActionBuildT2Sonar, 2, iBPWanted, false, false)
                    elseif tWZTeamData[AiBotMap.refiSonarCoverage] <= 10 then
                        HaveActionToAssign(refActionBuildT1Sonar, 1, 5, false, false)
                    end
                end
            end
        end
    end

    --Build mass storage if we have T2+ mexes
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) then
        iBPWanted = GetBPToAssignToMassStorage(0, iWaterZone, iTeam, tWZData, tWZTeamData, false, bHaveLowMass, bHaveLowPower)
        if iBPWanted > 0 then
            HaveActionToAssign(refActionBuildMassStorage, AiBotBuilding.iLowestMassStorageTechAvailable, iBPWanted)
        end
    end

    --Units to capture
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of units to capture for WZ empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToCapture]))) end
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToCapture]) == false then
        --Refresh the list
        local iCaptureCount = table.getn(tWZData[AiBotMap.subreftoUnitsToCapture])
        for iCurCount = iCaptureCount, 1, -1 do
            if not (AiBotUnitInfo.IsUnitValid(tWZData[AiBotMap.subreftoUnitsToCapture][iCurCount])) then
                table.remove(tWZData[AiBotMap.subreftoUnitsToCapture], iCurCount)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finishedupdating if have WZ units to capture for zone, after freshing them is table empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToCapture]))) end
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToCapture]) == false then
            --Dont capture if are a hostile AI due to the risk we capture a campaign objective and progress the map
            if not(ArmyBrains[tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]].HostileCampaignAI) then
                local oUnitToCapture
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                    local tPotentialCapture = EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryT3Power, tWZData[AiBotMap.subreftoUnitsToCapture])
                    if AiBotUtilities.IsTableEmpty(tPotentialCapture) == false then
                        oUnitToCapture = AiBotUtilities.GetNearestUnit(tPotentialCapture, tWZData[AiBotMap.subrefMidpoint])
                    end
                else
                    oUnitToCapture = AiBotUtilities.GetNearestUnit(tWZData[AiBotMap.subreftoUnitsToCapture], tWZData[AiBotMap.subrefMidpoint])
                end
                if bDebugMessages == true then LOG(sFunctionRef..': WZ Unit to cpature='..(oUnitToCapture.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToCapture) or 'nil')) end
                if oUnitToCapture then
                    iBPWanted = GetCaptureBPWanted(oUnitToCapture, bHaveLowPower, iTeam, tWZTeamData[AiBotMap.subrefLZbCoreBase])
                    HaveActionToAssign(refActionCaptureUnit, 1, iBPWanted, oUnitToCapture)
                end
            end
        end
    end

    --Experimental naval unit for very high mass levels (higher priority than naval fac assist so engis stop assisting naval fac and start building this)
    --If have navy prioritising brain that is closest, then will be much more likely to build a naval experimental

    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Experimental navy builder - core base=' .. tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase]) .. '; bHaveLowMass=' .. tostring(bHaveLowMass) .. '; Low power=' .. tostring(bHaveLowPower) .. '; Mass%=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] .. '; Gross mass=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] .. '; Net mass=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] .. '; Naval tehc=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] .. '; Enemies in adjacent QZ=' .. tostring(tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) .. '; Ally combat total=' .. tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal])
    end
    if tWZTeamData[AiBotMap.subrefWZbCoreBase] and (not (bHaveLowMass) or (aiBrain[AiBotOverseer.refbPrioritiseNavy] and aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] >= 3 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 30 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond][iPond]) or GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastHadBombardmentModeByPond] >= 60 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAllNavy * categories.EXPERIMENTAL) == 0))) and not (bHaveLowPower)
            and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 35 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 5 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] > -1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 80)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 3 and (not (tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) or (tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] >= 8000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7))))
            or (aiBrain[AiBotOverseer.refbPrioritiseNavy] and (aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF or aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon) and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 16 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAllNavy * categories.TECH3) >= 5)))
    then
        --Likely have the eco to get an experimental naval unit, check if we have a lifetime build count of at least 2 T3 naval units
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Think we have enough eco for experimental navy builder, lifetime battleship count=' .. AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryBattleship))
        end
        if AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryBattleship) >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 100) then
            --Cap experimentals to 2 if there are no enemy naval targets (increase cap if about to overflow mass)
            local iCurNavalExperimentalsOrSubstitutes = 0
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    iCurNavalExperimentalsOrSubstitutes = iCurNavalExperimentalsOrSubstitutes + oBrain:GetCurrentUnits(tiActionCategory[refActionBuildExperimentalNavy])
                end
            end
            local iExperimentalsWanted = 4
            if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNoSurfaceCombatTargetByPond][iPond] or -100) <= 30 then
                iExperimentalsWanted = 2
            end
            if AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] * AiBotMap.iLandZoneSegmentSize <= 8000 then iExperimentalsWanted = iExperimentalsWanted * 0.5 end
            if iCurNavalExperimentalsOrSubstitutes >= iExperimentalsWanted then
                local iCurLandExperimentals = 0
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        iCurLandExperimentals = iCurLandExperimentals + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental)
                    end
                end
                iExperimentalsWanted = math.max(iExperimentalsWanted, iCurLandExperimentals)
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': iCurLandExperimentals=' .. iCurLandExperimentals)
                end
            end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.99 and not(bHaveLowPower)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40) then
                iExperimentalsWanted = iExperimentalsWanted * 1.5
            end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiStuckMassByPondByTech][iPond][3] > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': Have stuck naval mass, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiStuckMassByPondByTech][iPond]='..reprs(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiStuckMassByPondByTech][iPond])..'; refbCanPathToEnemyBaseWithLand='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])) end
                if aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiStuckMassByPondByTech][iPond][3] > 10000 and (iCurNavalExperimentalsOrSubstitutes > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 2 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandExperimental) < math.max(2, iCurNavalExperimentalsOrSubstitutes)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiStuckMassByPondByTech][iPond][3] >= 30000 or iCurNavalExperimentalsOrSubstitutes > 1 or AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] * AiBotMap.iLandZoneSegmentSize <= 60000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 2)) then
                    iExperimentalsWanted = 0
                    if bDebugMessages == true then LOG(sFunctionRef..': Have stuck naval units so dont want to get naval exp') end
                else
                    iExperimentalsWanted = 1
                end
            end
            if bEngineersRecentlyRunFromEnemy and iExperimentalsWanted > 1 then iExperimentalsWanted = 1 end
            if bDebugMessages == true then LOG(sFunctionRef..': iExperimentalsWanted='..iExperimentalsWanted..'; iCurNavalExperimentalsOrSubstitutes='..iCurNavalExperimentalsOrSubstitutes) end

            if iCurNavalExperimentalsOrSubstitutes < iExperimentalsWanted then
                iBPWanted = 45
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 10) then
                    iBPWanted = 90
                end
                if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.3 end
                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionBuildExperimentalNavy, 3, iBPWanted, false, false, true)

                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Want experimental naval unit, iBPWanted=' .. iBPWanted)
                end
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.6 and not(bHaveLowPower) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.95 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 60) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 then
                --Get land or air experimental
                iBPWanted = 60
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.75 then iBPWanted = 120 end
                if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.3 end
                --Are we a smallish pond on the same plateau as a core zone? then get a land experimental
                local iPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint])
                if bDebugMessages == true then LOG(sFunctionRef..': Will get land exp if small pond, otherwise air exp, iPond='..iPond..'; SegmentCount='..(AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] or 'nil')..'; iLandZoneSegmentSize='..AiBotMap.iLandZoneSegmentSize..'; refbCanPathToEnemyBaseWithAmphibious='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious])) end
                if iPlateau and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateau]) == false and AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount] * AiBotMap.iLandZoneSegmentSize <= 20000 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try getting land exp') end
                    AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionBuildLandExperimental,3, iBPWanted)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try getting air exp') end
                    HaveActionToAssign(refActionBuildAirExperimental, 3, iBPWanted)
                end

            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1000 then
                iBPWanted = 90
                if bEngineersRecentlyRunFromEnemy then iBPWanted = 30 end
                if bDebugMessages == true then LOG(sFunctionRef..': Gross mass is high enough will get land exp') end
                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionBuildLandExperimental, 3, iBPWanted)
            end
        end
    end

    --Send engineer to a land zone adjacent to this that wants support and lacks factories
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef .. ': About to see if have adjacent land zones wanting engineers, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable..'; Is table of adjacent LZs empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]))) end
    if iHighestTechEngiAvailable > 0 then
        --Do we haev adjacent land zone wanting engineer?
        local bWantBPOfOurTech
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                local iPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                local iLandZone = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAdjLZData[AiBotMap.subrefMidpoint]) then
                    local tLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent LZ '..(iLandZone or 'nil')..' on plateau '..(iPlateau or 'nil')..'; Does this LZ want BP='..tostring(tLZTeamData[AiBotMap.subrefTbWantBP])..'; Dangerous enemies in this LZ='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Allied untis in this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                    if tLZTeamData[AiBotMap.subrefTbWantBP] and not (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) then
                        bWantBPOfOurTech = false
                        for iTech = iHighestTechEngiAvailable, 1, -1 do
                            if tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                bWantBPOfOurTech = true
                                iMinTechWanted = iTech
                            end
                        end
                        if bWantBPOfOurTech then
                            --For now to keep things simple will ignore minimum engineer tech requirements
                            iLZSentTo = iLZSentTo + 1
                            if bDebugMessages == true then LOG(sFunctionRef..': About to try and send engineers to iLandZOne '..(iLandZone or 'nil')..'; iPlateau='..(iPlateau or 'nil')) end
                            --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted,            vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted)
                            HaveActionToAssign(refActionMoveToLandZone, iMinTechWanted, 10 * 2 * iLZSentTo, {iPlateau, iLandZone}, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Have flagged we want to send BP of '..10 * 2 * iLZSentTo..' to land zone '..iLandZone) end
                        end
                    end
                end
            end
        end
    end


    --Send engineer to a water zone near this that wants support, or alternatively a land zone adjacent to that water zone that wants support
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': About to check if have adjacent water zones wanting engineers, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable)
    end
    if iHighestTechEngiAvailable > 0 then
        local bWantBPOfOurTech
        local iMinTechWanted       = 1
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]) == false then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                local iAdjWZ = tSubtable[AiBotMap.subrefWZAWZRef]
                local tAltWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAltWZData[AiBotMap.subrefMidpoint]) then
                    local tAltWZTeamData = tAltWZData[AiBotMap.subrefWZTeamData][iTeam]
                    local bWZOrAdjacentLZWantsEngineers
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': Considering iAdjWZ=' .. iAdjWZ .. '; tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]=' .. tostring(tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or false) .. '; tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTbWantBP]=' .. tostring(tAltWZTeamData[AiBotMap.subrefTbWantBP]) .. '; WZ table of unclaimed mexes is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefMexUnbuiltLocations])) .. '; WZ table of unbuilt hydro is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefHydroUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEnemyUnits])))
                    end
                    if (not (tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) or (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] >= math.min(6000, math.max(100, tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.75)) or (tAltWZTeamData[AiBotMap.subrefWZbCoreBase] and AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEnemyUnits]) and AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.reftLZEnemyAirUnits]) and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20)))) then
                        --WZ is safe to go to, does the WZ want engineers and/or does it have an adjacent LZ that wants engineers?
                        bWZOrAdjacentLZWantsEngineers = tAltWZTeamData[AiBotMap.subrefTbWantBP]
                        bWantBPOfOurTech = false
                        if bWZOrAdjacentLZWantsEngineers then
                            for iTech = iHighestTechEngiAvailable, 1, -1 do
                                if tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                    bWantBPOfOurTech = true
                                    iMinTechWanted = iTech
                                end
                            end
                        end

                        if not (bWantBPOfOurTech) and AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefAdjacentLandZones]) == false then

                            for iEntry, tSubtable in tAltWZData[AiBotMap.subrefAdjacentLandZones] do
                                local iPlateau = tSubtable[1]
                                local iLandZone = tSubtable[2]
                                local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                                if tLZTeamData[AiBotMap.subrefTbWantBP] and not (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) then
                                    bWantBPOfOurTech = false
                                    for iTech = iHighestTechEngiAvailable, 1, -1 do
                                        if tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                            bWantBPOfOurTech = true
                                            iMinTechWanted = iTech
                                        end
                                    end
                                    if bWantBPOfOurTech then
                                        bWZOrAdjacentLZWantsEngineers = true
                                        break
                                    end
                                end
                            end
                        end
                        if bWZOrAdjacentLZWantsEngineers then
                            iLZSentTo = iLZSentTo + 1
                            iBPWanted = 10 * 2 * iLZSentTo
                            if iExistingWaterFactory > 0 then iBPWanted = iBPWanted *0.25 end
                            HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, iBPWanted, iAdjWZ, true)
                            if iLZSentTo >= 4 then break end
                        end
                    end
                end
            end
        end
    end

    --Naval fac if this is a core WZ and we dont have any, but have engineers available, or we have lots of mass stored
    iCurPriority = iCurPriority + 1
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if bDebugMessages == true then LOG(sFunctionRef..': More naval fac if available engineers, iHighestTechEngiAvailable='..(iHighestTechEngiAvailable or 'nil')..'; iExistingWaterFactory='..(iExistingWaterFactory or 0)..'; iFactoriesWanted='..(iFactoriesWanted or 0)) end
    if iHighestTechEngiAvailable > 0 and iExistingWaterFactory < iFactoriesWanted and tWZTeamData[AiBotMap.subrefWZbCoreBase] then
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Later naval fac builder We want to build a naval factory')
        end
        iBPWanted = 35
        if bHaveLowMass then
            iBPWanted = 25
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.35 end
        end

        HaveActionToAssign(refActionBuildNavalFactory, 1, iBPWanted, nil)
    end

    --Assist naval factory based on average mass income of team; assist more if enemy has naval facs
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to assist naval fac, core base='..tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase])..'; iExistingWaterFactory='..iExistingWaterFactory..'; Is table of naval factories empty='..tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))) end
    if tWZTeamData[AiBotMap.subrefWZbCoreBase] and iExistingWaterFactory > 0 and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false
            and (not(tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild]) or GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] > 60 or (GetGameTimeSeconds() - tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] <= 20 and not(AiBotUnitInfo.IsUnitRestricted('ues0103', tWZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex])))) then
        --e.g. 1 BP building a frigate uses 0.2 mass per second, or 0.02 mass per tick; if want 40% of team mass income spent on navy, then want to assign 20 BP per 1 mass per tick (i.e. 20 BP per 10 mass per sec)
        iBPWanted = math.min(1000, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) * 20)
        --Adjust BP for number of naval facs (as might be spread out over a number of zones)
        local iTeamNavalFacs = (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTotalFactoryCountByType][AiBotFactory.refiFactoryTypeNaval] or 0)
        if iTeamNavalFacs >= 3 and iTeamNavalFacs > iExistingWaterFactory then
            local iNavalFacAdj = math.max(1, iExistingWaterFactory) / iTeamNavalFacs
            if iNavalFacAdj < 1 then
                iBPWanted = iBPWanted * iNavalFacAdj
            end
        end

        if not (bHaveLowMass) and not (bHaveLowPower) then
            iBPWanted = iBPWanted * 1.5
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.4 then iBPWanted = iBPWanted * 1.5 end
        elseif bHaveLowMass then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then
                iBPWanted = iBPWanted * 0.4
            elseif GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastMassStall] or 0) <= 30 then
                iBPWanted = iBPWanted * 0.75
            end
        end
        if bHaveLowPower then iBPWanted = iBPWanted * 0.5 end
        iBPWanted = math.max(5, iBPWanted)
        if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
        if iBPWanted < 200 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) then
            --Do we need more BP to keep up with enemy?
            local iEnemyBP = 0
            for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                if tSubtable[AiBotMap.subrefWZAWZDistance] >= 375 then break end
                local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefWZAWZRef]][AiBotMap.subrefWZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    local tEnemyNavalFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tEnemyNavalFactories) == false then
                        for iFactory, oFactory in tEnemyNavalFactories do
                            if AiBotUnitInfo.IsUnitValid(oFactory) then
                                iEnemyBP = iEnemyBP + (oFactory:GetBlueprint().Economy.BuildRate or 0)
                            end
                        end
                    end
                    local tEnemyEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false then
                        for iEnemyEnngineer, oEnemyEngineer in tEnemyEngineers do
                            if AiBotUnitInfo.IsUnitValid(oEnemyEngineer) then
                                iEnemyBP = iEnemyBP + tiBPByTech[AiBotUnitInfo.GetUnitTechLevel(oEnemyEngineer)]
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to increase engi assistance for naval fac due to enemy BP, iEnemyBP='..iEnemyBP..'; iExistingWaterFactory='..iExistingWaterFactory..'; iBPWanted before any adjust='..iBPWanted) end
            iBPWanted = math.max(iBPWanted, math.min(iEnemyBP * 1.25 - iExistingWaterFactory * 20), 25 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech]], (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] / (1 + (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] - 1) * 0.5) * 40))
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to assist naval fac, iBPWanted='..iBPWanted) end
        NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint])
        AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionAssistNavalFactory, 1, iBPWanted, false, false)
    end

    --If already have 1 naval fac build another if high mass
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': More naval fac if already have some and have lots of mass stored, iCurPrioriyt='..iCurPriority..'; iExistingWaterFactory='..iExistingWaterFactory..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; Time since last had nothing to build='..GetGameTimeSeconds() - (tWZTeamData[AiBotMap.subrefiTimeNavalFacHadNothingToBuild] or -100)..'; Have low power='..tostring(bHaveLowPower)) end

    if iExistingWaterFactory < iFactoriesWanted and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.5 and not(bHaveLowPower) then
        iBPWanted = 15 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech]
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 then iBPWanted = iBPWanted * 1.5 end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to assign BP to build a naval fac, iBPWanted='..iBPWanted..'; Pond segment size='..AiBotMap.tPondDetails[iPond][AiBotMap.subrefiSegmentCount]) end
        if not(tWZTeamData[AiBotMap.subrefWZbCoreBase]) then iBPWanted = iBPWanted * 0.75 end
        HaveActionToAssign(refActionBuildNavalFactory, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech], iBPWanted, nil)
    end

    --Preemptive AA builder if we are at T3 and have decent mass income, and have friendly units in the WZ or intel coverage, and no enemy units
    iCurPriority = iCurPriority + 1
    if not(tWZTeamData[AiBotMap.subrefWZTimeLastDestroyedForStuckNavy]) and not (bHaveLowMass) and not (bHaveLowPower) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 then
        --Build AA if we have <1.5k AA threat
        local iAAThreatWanted = 1500
        if tWZTeamData[AiBotMap.subrefWZbCoreBase] or tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] then
            iAAThreatWanted = 3000
        end
        if tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < iAAThreatWanted then
            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) and ((tWZTeamData[AiBotMap.refiSonarCoverage] or 0) > 20 or AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false) then
                iBPWanted = 50
                if tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] then
                    iBPWanted = 25
                end
                if bEngineersRecentlyRunFromEnemy then iBPWanted = iBPWanted * 0.5 end
                local iTechLevelWanted = math.max(2, (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) - 1)
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] >= 3 and (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) - (tWZTeamData[AiBotMap.subrefWZThreatAlliedMAA] or 0) >= 800 then iTechLevelWanted = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] end
                HaveActionToAssign(refActionBuildAA, iTechLevelWanted, iBPWanted)
            end
        end
    end

    --Build land experimentals in water if v.high mass
    iCurPriority = iCurPriority + 1
    if not(bEngineersRecentlyRunFromEnemy) and not (bHaveLowMass) and not (bHaveLowPower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] or 1) >= 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 40 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.9 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20)) then
        local iT3AndExperimentalNavy = 0
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                iT3AndExperimentalNavy = iT3AndExperimentalNavy + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAllNavy * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryAllNavy * categories.TECH3)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iT3AndExperimentalNavy='..iT3AndExperimentalNavy) end
        if iT3AndExperimentalNavy >= 4 then
            --If we have flagged we want more torp bombers or we have multiple land exp and no significant enemy land threat still get naval exp (if we arent searaphim)
            iBPWanted = 45
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should build naval exp or land exp, refbTooMuchGroundNavalAAForTorpBombers='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbTooMuchGroundNavalAAForTorpBombers])..'; refbNoAvailableTorpsForEnemies='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies])..'; refiAllyMobileDFThreatNearOurSide='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] or 'nil')..'; refiEnemyMobileDFThreatNearOurSide='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 'nil')..'; refiConstructedExperimentalCount='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) end
            if not(aiBrain[AiBotUnitInfo.refFactionSeraphim]) and iT3AndExperimentalNavy <= 10 + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] * 0.75 and (AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbTooMuchGroundNavalAAForTorpBombers] or AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] or (AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] > math.max(15000 * iT3AndExperimentalNavy, AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] * 4))) then
                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionBuildExperimentalNavy, 3, iBPWanted, false, false, true)
            else
                AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionBuildLandExperimental,3, iBPWanted, false, false, true)
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Want experimental land unit, iBPWanted=' .. iBPWanted)
                end
            end
        end
    end

    --Units to reclaim
    iCurPriority = iCurPriority + 1
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if have units to reclaim in WZ, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoUnitsToReclaim]))) end
    if tWZTeamData[AiBotMap.subreftoUnitsToReclaim] and AiBotConditions.IsTableOfUnitsStillValid(tWZTeamData[AiBotMap.subreftoUnitsToReclaim]) == true then
        local bObjectiveToReclaim = false
        if AiBotMap.bIsCampaignMap then
            for iUnit, oUnit in tWZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering WZ unit to reclaim, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                if oUnit[AiBotUnitInfo.refbIsReclaimTarget] then bObjectiveToReclaim = true break end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to reclaim friendly WZ unit, bObjectiveToReclaim='..tostring(bObjectiveToReclaim)) end
        --Dont reclaim power if we have <100% stored or low power
        local bDontReclaimYet = false
        if not(bObjectiveToReclaim) and ((bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] <= 0.98) then
            if AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower, tWZTeamData[AiBotMap.subreftoUnitsToReclaim])) == false then
                bDontReclaimYet = true
            end
        end
        if not(AiBotOrders.bDontConsiderCombinedArmy) and not(bDontReclaimYet) then
            bDontReclaimYet = true
            for iUnit, oUnit in tWZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                if oUnit.AiBotActive or not(oUnit:GetAIBrain().AiBotTeam == iTeam) then
                    bDontReclaimYet = false
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': About to reclaim a unit but still stop if have low power and we have pgens in the list of units to reclaim, bHaveLowPower='..tostring(bHaveLowPower)..'; Average% stored='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored]) end
        if not(bDontReclaimYet) then

            if bObjectiveToReclaim or (bHaveLowMass and not(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])) then
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, math.min(1.5 * tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]], math.max(5, 5 * table.getn(tWZTeamData[AiBotMap.subreftoUnitsToReclaim]))), nil, false)
            elseif bHaveLowMass and tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] > 200 and tWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] == 0 and tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] == 0 then
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, math.min(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]], math.max(5, math.min(30, 5 * table.getn(tWZTeamData[AiBotMap.subreftoUnitsToReclaim])))), nil, false)
            elseif not(tWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.5 then
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, math.min(tiBPByTech[AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]], math.max(5, math.min(30, 5 * table.getn(tWZTeamData[AiBotMap.subreftoUnitsToReclaim])))), nil, false)
            else
                --if have engi in the zone then reclaim it, but dont request an engi
                HaveActionToAssign(refActionReclaimFriendlyUnit, 1, 5, nil, true)
            end
        end
    end

    --Units to repair
    iCurPriority = iCurPriority + 1
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToRepair]) == false then
        --Refresh the list
        local iUnitCount = table.getn(tWZData[AiBotMap.subreftoUnitsToRepair])
        for iCurCount = iUnitCount, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(tWZData[AiBotMap.subreftoUnitsToRepair][iCurCount])) then
                table.remove(tWZData[AiBotMap.subreftoUnitsToRepair], iCurCount)
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Have units to repair for water zone '..iWaterZone..' after freshing them is table empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subreftoUnitsToRepair]))) end
        if AiBotConditions.IsTableOfUnitsStillValid(tWZData[AiBotMap.subreftoUnitsToRepair], true) then
            local oUnitToTarget = AiBotUtilities.GetNearestUnit(tWZData[AiBotMap.subreftoUnitsToRepair], tWZData[AiBotMap.subrefMidpoint])
            if oUnitToTarget[refbDontIncludeAsPartCompleteBuildingForConstruction] then
                --Remove unit from UnitsToRepair
                for iUnit, oUnit in tWZData[AiBotMap.subreftoUnitsToRepair] do
                    if oUnit == oUnitToTarget then
                        table.remove(tWZData[AiBotMap.subreftoUnitsToRepair], iUnit)
                        break
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Unit to repair='..oUnitToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToTarget)) end
                HaveActionToAssign(refActionRepairUnit, 1, 5, oUnitToTarget)
            end
        end
    end

    --Under construction unit
    iCurPriority = iCurPriority + 1
    if iHighestTechEngiAvailable > 0 and not(bEngineersRecentlyRunFromEnemy) then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if iHighestTechEngiAvailable > 0 then
            local tBuildingsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tBuildingsInZone) == false then
                for iUnit, oUnit in tBuildingsInZone do
                    if oUnit:GetFractionComplete() < 1 and not(oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                        HaveActionToAssign(refActionRepairUnit, 1, 5, oUnit)
                        break
                    end
                end
            end
        end
    end

    --Lower priority sending engineeres to other land and water zones
    --Send engineer to a land zone adjacent to this that wants support and lacks factories
    iCurPriority = iCurPriority + 1
    if iHighestTechEngiAvailable > 0 then
        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if bDebugMessages == true then LOG(sFunctionRef .. ': Lower priority About to see if have adjacent land zones wanting engineers, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable..'; Is table of adjacent LZs empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]))) end
        if iHighestTechEngiAvailable > 0 then
            --Do we haev adjacent land zone wanting engineer?
            local bWantBPOfOurTech
            local iMinTechWanted = 1

            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                    local iPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                    local iLandZone = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent LZ '..(iLandZone or 'nil')..' on plateau '..(iPlateau or 'nil')..'; Does this LZ want BP='..tostring(tLZTeamData[AiBotMap.subrefTbWantBP])..'; Dangerous enemies in this LZ='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; Allied untis in this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                        if tLZTeamData[AiBotMap.subrefTbWantBP] and not (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                            bWantBPOfOurTech = false
                            for iTech = iHighestTechEngiAvailable, 1, -1 do
                                if tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                    bWantBPOfOurTech = true
                                    iMinTechWanted = iTech
                                end
                            end
                            if bWantBPOfOurTech then
                                --For now to keep things simple will ignore minimum engineer tech requirements
                                iLZSentTo = iLZSentTo + 1
                                if bDebugMessages == true then LOG(sFunctionRef..': About to try and send engineers to iLandZOne '..(iLandZone or 'nil')..'; iPlateau='..(iPlateau or 'nil')) end
                                --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted,            vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted)
                                HaveActionToAssign(refActionMoveToLandZone, iMinTechWanted, 10 * 2 * iLZSentTo, {iPlateau, iLandZone}, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Have flagged we want to send BP of '..10 * 2 * iLZSentTo..' to land zone '..iLandZone) end
                            end
                        end
                    end
                end
            end
        end
    end


    --Send engineer to a water zone near this that wants support, or alternatively a land zone adjacent to that water zone that wants support
    iCurPriority = iCurPriority + 1
    if iHighestTechEngiAvailable > 0 then

        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Lower priority About to check if have adjacent water zones wanting engineers, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable)
        end
        if iHighestTechEngiAvailable > 0 then
            local bWantBPOfOurTech
            local iMinTechWanted = 1
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]) == false then
                for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                    local iAdjWZ = tSubtable[AiBotMap.subrefWZAWZRef]
                    local tAltWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAltWZData[AiBotMap.subrefMidpoint]) then
                        local tAltWZTeamData = tAltWZData[AiBotMap.subrefWZTeamData][iTeam]
                        local bWZOrAdjacentLZWantsEngineers
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': Considering iAdjWZ=' .. iAdjWZ .. '; tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]=' .. tostring(tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] or false) .. '; tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]=' .. (tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) .. '; tAltWZTeamData[AiBotMap.subrefTbWantBP]=' .. tostring(tAltWZTeamData[AiBotMap.subrefTbWantBP]) .. '; WZ table of unclaimed mexes is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefMexUnbuiltLocations])) .. '; WZ table of unbuilt hydro is empty=' .. tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefHydroUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEnemyUnits])))
                        end
                        if (not (tAltWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) or (tAltWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] >= math.min(6000, math.max(100, tAltWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] * 0.75)) or (tAltWZTeamData[AiBotMap.subrefWZbCoreBase] and AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.subrefTEnemyUnits]) and AiBotUtilities.IsTableEmpty(tAltWZTeamData[AiBotMap.reftLZEnemyAirUnits]) and (not(bHaveLowMass) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20)))) then
                            --WZ is safe to go to, does the WZ want engineers and/or does it have an adjacent LZ that wants engineers?
                            bWZOrAdjacentLZWantsEngineers = tAltWZTeamData[AiBotMap.subrefTbWantBP]
                            bWantBPOfOurTech = false
                            if bWZOrAdjacentLZWantsEngineers then

                                for iTech = iHighestTechEngiAvailable, 1, -1 do
                                    if tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                        bWantBPOfOurTech = true
                                        iMinTechWanted = iTech
                                    end
                                end
                            end
                            if not (bWantBPOfOurTech) and AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefAdjacentLandZones]) == false then

                                for iEntry, tSubtable in tAltWZData[AiBotMap.subrefAdjacentLandZones] do
                                    local iPlateau = tSubtable[1]
                                    local iLandZone = tSubtable[2]
                                    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                                    if tLZTeamData[AiBotMap.subrefTbWantBP] and not (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                                        bWantBPOfOurTech = false
                                        for iTech = iHighestTechEngiAvailable, 1, -1 do
                                            if tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                                bWantBPOfOurTech = true
                                                iMinTechWanted = iTech
                                            end
                                        end
                                        if bWantBPOfOurTech then
                                            bWZOrAdjacentLZWantsEngineers = true
                                            break
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of adj land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefAdjacentLandZones]))..'; bWantBPOfOurTech='..tostring(bWantBPOfOurTech)..'; bWZOrAdjacentLZWantsEngineers='..tostring(bWZOrAdjacentLZWantsEngineers)) end
                            if bWZOrAdjacentLZWantsEngineers and bWantBPOfOurTech then
                                iLZSentTo = iLZSentTo + 1
                                HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, 10 * 2 * iLZSentTo, iAdjWZ, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Assigned engineers to move to water zone, Total of iLZSentTo='..iLZSentTo..'; iAdjWZ='..iAdjLZ) end
                                iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                                if iLZSentTo >= 4 or iHighestTechEngiAvailable == 0 then break end
                            end
                        end
                    end
                end
            end
        end
    end


    UpdateSpareEngineerNumber(tWZTeamData, toAvailableEngineersByTech)

    --spare engis - If still have an engineer available and there is reclaim in the WZ of any kind, and we arent overflowing, then reclaim (but dont request engineers for this)
    iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
    if iHighestTechEngiAvailable > 0 then
        iCurPriority = iCurPriority + 1
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.8 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageEnergyPercentStored] < 0.9 then
            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': iCurPriority=' .. iCurPriority .. '; considering if want to reclaim in the WZ, iHighestTechEngiAvailable=' .. iHighestTechEngiAvailable .. '; tWZData[AiBotMap.subrefTotalMassReclaim]=' .. (tWZData[AiBotMap.subrefTotalMassReclaim] or 0))
            end
            if iHighestTechEngiAvailable > 0 then
                if tWZData[AiBotMap.subrefTotalMassReclaim] >= 5 then
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': Will tell engineer to get lower priority reclaim, Total mass in pond ' .. iPond .. ' WZ ' .. iWaterZone .. '=' .. tWZData[AiBotMap.subrefTotalMassReclaim])
                    end
                    HaveActionToAssign(refActionReclaimArea, 1, 100, {false, nil}, true, nil, nil, nil, true)
                end
            end
        end
        --Spare engis - if have adjacent land zone wanting engineers, then send them here
        iCurPriority = iCurPriority + 1
        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                local iBPWanted = 0
                local iMinTechWanted = 3
                local iPlateau = tSubtable[1]
                local iLandZone = tSubtable[2]
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if tLZTeamData[AiBotMap.subrefTbWantBP] then
                        for iTech, iZoneBPWanted in tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] do
                            iBPWanted = iBPWanted + iZoneBPWanted
                            iMinTechWanted = math.min(iZoneBPWanted, iTech)
                        end
                    end
                    if iBPWanted > 0 then
                        --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                        HaveActionToAssign(refActionMoveToLandZone, iMinTechWanted, iBPWanted,      {iPlateau, iLandZone}, true,                    true,                       nil,                            nil,                                false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                        iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                        if iHighestTechEngiAvailable == 0 then break end
                    end
                end
            end
        end

        --Spare engis - if still have engi available, then send engineer to the closest land or water zone wanting more BP
        iCurPriority = iCurPriority + 1
        if iHighestTechEngiAvailable > 0 and AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZOtherWaterZones]) == false then
            for iEntry, tSubtable in tWZData[AiBotMap.subrefWZOtherWaterZones] do
                local iAdjWZ = tSubtable[AiBotMap.subrefWZAWZRef]
                local tAltWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tAltWZData[AiBotMap.subrefMidpoint]) then
                    local tAltWZTeamData = tAltWZData[AiBotMap.subrefWZTeamData][iTeam]
                    local iBPWanted = 0
                    local iMinTechWanted = 3
                    if tAltWZTeamData[AiBotMap.subrefTbWantBP] then
                        for iTech, iZoneBPWanted in tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] do
                            iBPWanted = iBPWanted + iZoneBPWanted
                            iMinTechWanted = math.min(iZoneBPWanted, iTech)
                        end
                        if iBPWanted > 0 then
                            --HaveActionToAssign(iActionToAssign, iMinTechLevelWanted, iBuildPowerWanted, vOptionalVariable, bDontIncreaseLZBPWanted, bBPIsInAdditionToExisting, iOptionalSpecificFactionWanted, bDontUseLowerTechEngineersToAssist, bMarkAsSpare)
                            HaveActionToAssign(refActionMoveToWaterZone, iMinTechWanted, iBPWanted,             iAdjWZ,         true,                   true,                       nil,                            nil,                                false) --Dont treat it as spare action, or else it gets orders overwritten and can end up in a loop where it moves to another zone and that zone sends it back home
                            iHighestTechEngiAvailable = GetHighestTechEngiAvailable(toAvailableEngineersByTech)
                            if iHighestTechEngiAvailable == 0 then break end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tAltWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                        for iEntry, tSubtable in tAltWZData[AiBotMap.subrefAdjacentLandZones] do
                            local iPlateau = tSubtable[1]
                            local iLandZone = tSubtable[2]
                            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if tLZTeamData[AiBotMap.subrefTbWantBP] then
                                    for iTech, iZoneBPWanted in tAltWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted] do
                                        iBPWanted = iBPWanted + iZoneBPWanted
                                        iMinTechWanted = math.min(iZoneBPWanted, iTech)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        --Spare engis - assist naval factory if dont ahve low mass
        iCurPriority = iCurPriority + 1
        if not (bHaveLowMass) and iExistingWaterFactory > 0 then
            --+5 BP a time assigned to naval factory
            AssignBuildExperimentalOrT3NavyAction(HaveActionToAssign, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tWZData[AiBotMap.subrefMidpoint]), iWaterZone, iTeam, tWZData, tWZTeamData, true, refActionAssistNavalFactory, 1, 5, false, true, true, nil, nil, true)
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function ConsiderLandOrWaterZoneEngineerAssignment(tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrPond, iLandOrWaterZone, tEngineers, bIsWaterZone)
    --tEngineers might be empty if e.g. we just want to record how much build power the land zone wants
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderLandOrWaterZoneEngineerAssignment'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Start of code, iTeam=' .. iTeam .. '; iPlateauOrPond=' .. iPlateauOrPond .. '; iLandOrWaterZone=' .. iLandOrWaterZone .. '; is tEngineers empty=' .. tostring(AiBotUtilities.IsTableEmpty(tEngineers)) .. '; Is this a core base LZ=' .. tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false) .. '; bIsWaterZone=' .. tostring(bIsWaterZone or false)..'; tLZOrWZTeamData[AiBotMap.subrefTbWantBP] before reset='..tostring(tLZOrWZTeamData[AiBotMap.subrefTbWantBP] or false)..'; iTeam='..iTeam)
    end

    --First clear any faction requests (will set to true again if we want to build something and dont have an engineer of the right faction for it)
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted]) == false then
        for iFaction, bWantEngineers in tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted] do
            if bWantEngineers then
                if bDebugMessages == true then LOG(sFunctionRef..': We want engineers for iFaction='..iFaction..' for zone '..iLandOrWaterZone..'; if this is UEF or seraphim and we have an active gameender logic, then wont reset this flag to false, do we have active gameender logic='..tostring(AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZOrWZTeamData, true))..'; Is this not UEF or seraphim='..tostring(not(iFaction == AiBotUnitInfo.refFactionUEF) and not(iFaction == AiBotUnitInfo.refFactionSeraphim))) end
                if not(AiBotConditions.HaveActiveGameEnderTemplateLogic(tLZOrWZTeamData, true)) or (not(iFaction == AiBotUnitInfo.refFactionUEF) and not(iFaction == AiBotUnitInfo.refFactionSeraphim)) then
                    tLZOrWZTeamData[AiBotMap.subreftbBPByFactionWanted][iFaction] = false
                end
            end
        end
    end
    --Clear tracking of engineers wanted by action
    tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction] = {}
    tLZOrWZTeamData[AiBotMap.refbAdjZonesWantEngiForUnbuiltMex] = false

    if bIsWaterZone then
        ConsiderWaterZoneEngineerAssignment(tLZOrWZTeamData, iTeam, iPlateauOrPond, iLandOrWaterZone, tEngineers, bIsWaterZone)
    elseif tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
        ConsiderCoreBaseLandZoneEngineerAssignment(tLZOrWZTeamData, iTeam, iPlateauOrPond, iLandOrWaterZone, tEngineers)
    else
        --Not dealing with a core base
        ConsiderMinorLandZoneEngineerAssignment(tLZOrWZTeamData, iTeam, iPlateauOrPond, iLandOrWaterZone, tEngineers)
    end

    tLZOrWZTeamData[AiBotMap.subrefTbWantBP] = false --set to true later if any BP wanted
    --Reduce BP wanted by any engineers assigned to this LZ from another LZ
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Checking if engineers already assigned here, Is table of traveling engis empty=' .. tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere])) .. '; BP wanted pre update for traveling engis=' .. repru(tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]))
    end
    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
        --Make sure the list of units traveling here is still accurate
        function KeepCurEntry(tArray, iEntry)
            if AiBotUnitInfo.IsUnitValid(tArray[iEntry]) then
                if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, tArray[iEntry].UnitId) then
                    if (tArray[iEntry][refiAssignedAction] == refActionRunToLandZone or tArray[iEntry][refiAssignedAction] == refActionMoveToLandZone) and tArray[iEntry][AiBotLand.reftiPlateauAndLZToMoveTo][2] == iLandOrWaterZone then
                        return true
                    elseif (tArray[iEntry][refiAssignedAction] == refActionMoveToWaterZone or tArray[iEntry][refiAssignedAction] == refActionRunToWaterZone) and tArray[iEntry][AiBotNavy.refiWZToMoveTo] == iLandOrWaterZone then
                        return true
                    else
                        return false

                    end
                else
                    --Not an engineer so dont remove from the table of traveling units as only concerned with removing engineers no longer assigned to do this
                    return true
                end
            else
                return false
            end
        end

        AiBotUtilities.RemoveEntriesFromArrayBasedOnCondition(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere], KeepCurEntry)
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
            local tTravelingEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere])
            local iCurEngiTechLevel
            if AiBotUtilities.IsTableEmpty(tTravelingEngineers) == false then
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                    --Refresh list of traveling engineers in case it is invalid

                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        --Is the engi still actually travelling here?
                        iCurEngiTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                        for iTech = iCurEngiTechLevel, 1, -1 do
                            if tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
                                --Dont ignore traveling engineers for fortify zone (so UEF M2 we still try doing a drop)
                                if iTech > 1 or not(AiBotMap.bIsCampaignMap) or not(tLZOrWZTeamData[AiBotMap.subrefLZFortify]) then
                                    tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] = tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] - oUnit:GetBlueprint().Economy.BuildRate
                                    break
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': BP wanted after updating for traveling engineers=' .. repru(tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]))
            end
        end
    end

    --Cap BP wanted for non-core LZs and all WZs if enemies in the zone or adjacent
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Considering capping engis wnated for noncore zones; tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]=' .. (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil') .. '; tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]=' .. tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false))
    end
    if not (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not (tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) then
        local iBPCap
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to gap BP wanted due to enemy threat, bIsWaterZone='..tostring(bIsWaterZone)..'; iLandOrWaterZone='..iLandOrWaterZone..'; tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]='..(tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')..'; Our highest fac tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')..'; .subrefLZTThreatAllyCombatTotal='..(tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')..'; subrefWZTThreatAllyCombatTotal='..(tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 'nil')) end
        if (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 10 then
            iBPCap = 0
            --Exception - cap of 5 for campaign with objective to repair (i.e. M2 UEF)
            if AiBotMap.bIsCampaignMap and tLZOrWZTeamData[AiBotMap.subrefLZFortify] and (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < 1000 and AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subreftoUnitsToRepair][1] and AiBotUnitInfo.GetUnitHealthPercent(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subreftoUnitsToRepair][1]) < 0.15 then
                iBPCap = 5
                --Other exception - high reclaim zone where our combat units have more threat tahn the enemy
            elseif (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * 250 then
                if bDebugMessages == true then LOG(sFunctionRef..': Alot of reclaim so want to consider having engineers reclaim even though dangerous if we have enough friendly combat threat') end
                if tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] > (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3 then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have more threat than enemy so will increase BP wanted based on how much reclaim there is') end
                    if (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] then
                        if (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 1000 then
                            iBPCap = math.min(30, tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] / 250) --i.e. more than 0
                        else
                            --BP cap remains at 0
                        end
                    else
                        iBPCap = 5
                        --If lots of reclaim increase cap further
                        if (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 1000 then
                            iBPCap = math.min(60, tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] / 80)
                        end
                    end
                end
            end
            --Clear any engineers already traveling here
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': Setting BP cap to 0 (or 5 if unit to repair) and clearing engineers traveling here, iBPCap='..iBPCap..'; AiBotMap.bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap)..'; Fortify='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZFortify] or false)..'; Fortify based on plateau and zone='..tostring(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZFortify] or false)..'; Enemy combat='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..';1st unit to repair if there is one='..(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subreftoUnitsToRepair][1].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subreftoUnitsToRepair][1]) or 'nil')..'; flag for iTeam '..iTeam)
            end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                local tTravelingEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                if AiBotUtilities.IsTableEmpty(tTravelingEngineers) == false then
                    for iEngi, oEngi in tTravelingEngineers do
                        if iBPCap > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will hold off clearing engineer '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..' and will set BP cap to 0 based on engi BP') end
                            if iBPCap > 5 then
                                iBPCap = math.max(0, iBPCap - tiBPByTech[AiBotUnitInfo.GetUnitTechLevel(oEngi)])
                            else
                                iBPCap = 0
                            end
                        else
                            AiBotOrders.IssueTrackedClearCommands(oEngi)
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iBPCap after clearing traveling engineers='..iBPCap) end
        elseif tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] then
            iBPCap = 5
            if tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 400 and (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 250 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] then
                iBPCap = math.max(5, math.min(60, tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] / 75))
            end
        end
        if not(iBPCap) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false and bIsWaterZone then
            iBPCap = 5
            if (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 1000 then
                iBPCap = math.min(30, tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] / 200)
            end
        end
        if iBPCap then
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': have iBPCap of ' .. iBPCap .. '; so will limit BP wanted for this LZ')
            end
            for iTech = 3, 1, -1 do
                if tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > iBPCap then
                    tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] = iBPCap
                    if iTech > 1 then
                        for iAltTech = iTech, 1, -1 do
                            tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iAltTech] = 0
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if zone wants BP for any tech level 1-3, tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]='..repru(tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])) end
    for iTech = 1, 3 do
        if tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] > 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Zone wants BP so setting flag to true') end
            tLZOrWZTeamData[AiBotMap.subrefTbWantBP] = true
            break
        end
    end
    --Clear the BP wanted flag if this is a pacifist zone
    if AiBotOverseer.bPacifistModeActive and tLZOrWZTeamData[AiBotMap.subrefTbWantBP] then
        local tLZOrWZData
        if bIsWaterZone then
            tLZOrWZData = AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        end
        if tLZOrWZData[AiBotMap.subrefbPacifistArea] then
            tLZOrWZTeamData[AiBotMap.subrefTbWantBP] = false
            for iTech = 1, 3 do
                tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] = 0
            end
        end
    end

    --Clear any BP wanted if norush active and dealing with a non-core LZ outside any AiBot norush raidius
    if AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() > 30 and tLZOrWZTeamData[AiBotMap.subrefTbWantBP] and not (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not (tLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) then
        local tLZOrWZData
        if bIsWaterZone then
            tLZOrWZData = AiBotMap.tPondDetails[iPlateauOrPond][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        else
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrPond][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        end
        if AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], tLZOrWZData[AiBotMap.subrefMidpoint]) > AiBotOverseer.iNoRushRange then
            for iTech = 1, 3 do
                tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted][iTech] = 0
            end
            tLZOrWZTeamData[AiBotMap.subrefTbWantBP] = false
            if bDebugMessages == true then LOG(sFunctionRef..': No rush override - clearing any BP wanted') end
        end
    end
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Finished updating the BP wanted for this land or water zone '..iLandOrWaterZone..'; iPlateauOrPond='..iPlateauOrPond..'; tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]=' .. repru(tLZOrWZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]) .. '; tLZOrWZTeamData[AiBotMap.subrefTbWantBP]=' .. tostring(tLZOrWZTeamData[AiBotMap.subrefTbWantBP]))
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckDestroyedBuildingLocations()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckDestroyedBuildingLocations'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iLastEntryToRemove
    local aiBrain
    for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
        aiBrain = oBrain
        if not(oBrain.AiBotIsDefeated) then
            break
        end
    end

    for iEntry, tSubtable in tRecentlyDestroyedBuildings do
        --As a rough test, in sandbox it looked like an Aeon T2 shield took about 3.5s to complete, so will go with 3.9s to be safe
        if GetGameTimeSeconds() - tSubtable[subrefDestroyedBuildingTime] >= 3.9 then
            iLastEntryToRemove = iEntry
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..' in recently destroyed buildings, tSubtable='..reprs(tSubtable)..'; Map playable area='..repru(AiBotMap.rMapPlayableArea)..'; subrefDestroyedBuildingLocation='..reprs(tSubtable[subrefDestroyedBuildingLocation])) end
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tSubtable[subrefDestroyedBuildingLocation])
            local tLZOrWZData
            local tZoneBySegmentRef
            local tBlueprintSizeTableRef
            if iPlateauOrZero > 0 then
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                tZoneBySegmentRef = AiBotMap.tLandZoneBySegment
                tBlueprintSizeTableRef = tsBlueprintsBySize
            elseif iPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                tZoneBySegmentRef = AiBotMap.tWaterZoneBySegment
                tBlueprintSizeTableRef = tsWZBlueprintsBySize
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iENtry='..iEntry..'; repru='..repru(tSubtable)) end
            if iLandOrWaterZone > 0 then
                if not(tSubtable[subrefDestroyedBuildingBlueprint]) then AiBotUtilities.ErrorHandler('No destroyed building blueprint')
                else
                    local iBuildingSize = AiBotUnitInfo.GetBuildingSize(tSubtable[subrefDestroyedBuildingBlueprint])
                    local iBaseSegmentX, iBaseSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tSubtable[subrefDestroyedBuildingLocation])
                    --local iAffectedDistanceRadius = math.min(math.max(iBuildingSize, 8), iBuildingSize * 0.5 + iMaxBuildingSize * 0.5)

                    if aiBrain then
                        SearchForBuildableLocationsNearTarget(aiBrain, tLZOrWZData, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, iBaseSegmentX, iBaseSegmentZ, iBuildingSize * 0.5)

                        --Record any mass storage locations
                        if iPlateauOrZero > 0 then
                            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then
                                local bHaveNearbyMex = false
                                local iPotentialStorageDistance = iBuildingSize * 0.5 + 3
                                for iMex, tMex in tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations] do
                                    if AiBotUtilities.GetRoughDistanceBetweenPositions(tMex, tSubtable[subrefDestroyedBuildingLocation]) <= iPotentialStorageDistance then
                                        bHaveNearbyMex = true
                                        break
                                    end
                                end
                                if bHaveNearbyMex then
                                    AiBotMap.RecordAvailableMassStorageLocationsForLandZone(iPlateauOrZero, iLandOrWaterZone)
                                end
                            end
                        end
                    else
                        AiBotUtilities.ErrorHandler('No longer have AiBot brain')
                        if bDebugMessages == true then
                            for iBrain, oBrain in ArmyBrains do
                                LOG(sFunctionRef..': Considering iBrain='..iBrain..'; oBrain='..(oBrain.Nickname or 'nil')..'; oBrain.AiBotIsDefeated='..tostring(oBrain.AiBotIsDefeated or false)..'; .AiBotAI='..tostring(oBrain.AiBotAI or false)..'; Team='..(oBrain.AiBotTeam or 'nil'))
                            end
                            for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                                LOG(sFunctionRef..': Cycling all active AiBot Brains, iBrain='..iBrain..'; oBrain='..(oBrain.Nickname or 'nil')..'; oBrain.AiBotIsDefeated='..tostring(oBrain.AiBotIsDefeated or false))
                            end
                        end
                    end
                end
            end
        else
            iLastEntryToRemove = iEntry - 1
            break
        end
    end
    if iLastEntryToRemove > 0 then
        for iEntry = iLastEntryToRemove, 1, -1 do
            table.remove(tRecentlyDestroyedBuildings, iEntry)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DestroyedBuildingLocationMonitor()
    if not(bActiveDestroyedBuildingLoop) then
        while AiBotUtilities.bAiBotAIInGame do
            WaitTicks(1)
            if AiBotUtilities.IsTableEmpty(tRecentlyDestroyedBuildings) == false then
                ForkThread(CheckDestroyedBuildingLocations)
            end
        end
    end
end

function EngineerInitialisation(aiBrain)
    --Variable declaration
    aiBrain[refiEngineerCurUniqueReference] = 0
    aiBrain[AiBotFactory.refiHighestFactoryBuildCount] = 0

    if not (bBuildLocationLoopActive) then
        ForkThread(SlowlyRefreshBuildableLandZoneLocations, aiBrain)
        ForkThread(DestroyedBuildingLocationMonitor)
    end
    if not (bWZBuildLocationLoopActive) then
        ForkThread(RecordBuildableCoreWaterZoneLocationsNearStartOfGame)
    end
end

function GetBPToAssignToBuildingTML(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, bHaveLowMass)
    local bDebugMessages = false
    if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetBPToAssignToBuildingTML'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iBPWanted = 0
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': TIme=' .. GetGameTimeSeconds() .. ' iPlateau=' .. iPlateau .. '; bHaveLowMass=' .. tostring(bHaveLowMass) .. '; Is core base=' .. tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase]) .. '; is core expansion=' .. tostring(tLZTeamData[AiBotMap.subrefLZCoreExpansion]) .. '; iLandZone=' .. iLandZone)
    end
    if tLZTeamData[AiBotMap.subrefLZbCoreBase] or ((tLZTeamData[AiBotMap.subrefLZCoreExpansion] or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 3 or (tLZTeamData[AiBotMap.subrefMexCountByTech][2] == tLZData[AiBotMap.subrefLZOrWZMexCount] and tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 and not(bHaveLowMass) and not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]))) and (not (bHaveLowMass) or (not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and ((tLZTeamData[AiBotMap.subrefiTMLLifetimeBuildCount] or 0) == 0 or (tLZTeamData[AiBotMap.subrefiTMLLifetimeBuildCount] == 1 and AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZTeamData, AiBotUnitInfo.refCategoryTML, true) > 0)) and ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiGrossMassBaseIncome] >= 3.5 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) and (ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]][AiBotEconomy.refiGrossMassBaseIncome]>= 10 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))))  then
        --Make sure we have recorded pathing in a straight line for this zone (will only run if table is empty)
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)

        if bDebugMessages == true then
            LOG(sFunctionRef .. ': AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]=' .. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] .. '; Is table of pathing to other LZ and WZ empty=' .. tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance])))
        end
        --Decided to remove the check about max enemy tech, as they may have T2 mexes but T1 units, and performance isn't as big a concern early-game anyway
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
            --Do we have any TML in this LZ already?
            local iMaxTMLWanted = 1
            if tLZTeamData[AiBotMap.refbGetTMLBattery] then iMaxTMLWanted = 9 end
            if bDebugMessages == true then LOG(sFunctionRef .. ': Do we already have TML in this LZ? Is table of TML empty=' .. tostring(AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTML, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))..'; iMaxTMLWanted='..iMaxTMLWanted) end
            local tTMLInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTML, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if (iMaxTMLWanted == 1 and (AiBotUtilities.IsTableEmpty(tTMLInZone) or ((tLZTeamData[AiBotMap.subrefiTMLLifetimeBuildCount] or 0) <= 1 and AiBotConditions.DoesTableContainUnderConstructionUnits(tTMLInZone)))) or (iMaxTMLWanted > 1 and table.getn(tTMLInZone) < iMaxTMLWanted) then
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': About to cycle through every land zone and consider targets, unless we want TML to defend against LR threat, iMaxTMLWanted='..iMaxTMLWanted)
                end
                if iMaxTMLWanted > 1 then
                    iBPWanted = 50
                    if not (bHaveLowMass) then
                        iBPWanted = 100
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Want BP for TML defense') end
                else
                    for iEntry, tSubtable in tLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': Zone ' .. tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] .. ' with Plateau/Pond '..tSubtable[AiBotMap.subrefiPlateauOrPond]..' is distance ' .. tSubtable[AiBotMap.subrefiDistance] .. ' away')
                        end
                        if tSubtable[AiBotMap.subrefiDistance] <= AiBotBuilding.iTMLMissileRange + 10 then --Increase from TML range, as zones can be large so likely some units in the zone we can still reach
                            if not (tSubtable[AiBotMap.subrefbIsWaterZone]) then
                                local tAltLZTeamData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then
                                    LOG(sFunctionRef .. ': Considering enemy zone ' .. tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] .. ', PlateauOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Is tAltLZTeamData nil='..tostring(tAltLZTeamData == nil)..'; Is table of enemy TMD empty=' .. tostring(AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoEnemyTMD])) .. '; is talbe of enemy potential targets empty=' .. tostring(AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoEnemyTMD])))
                                end
                                if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoEnemyTMD]) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Target zone has TMD, Targets based on more detailed check='..AiBotBuilding.GetTargetsWithoutTMDCoverageBasedOnZoneMidpoint(tLZTeamData, tAltLZTeamData, tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], tLZData[AiBotMap.subrefMidpoint])) end
                                    --GetTargetsWithoutTMDCoverageBasedOnZoneMidpoint(tTMLLZTeamData, tTargetLZTeamData, iTargetPlateauOrZero, iTargetZone, tPlannedTMLLocation, iOptionalTMDRequiredToBlock)
                                    if AiBotBuilding.GetTargetsWithoutTMDCoverageBasedOnZoneMidpoint(tLZTeamData, tAltLZTeamData, tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], tLZData[AiBotMap.subrefMidpoint]) == 0 then
                                        break
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets]) == false then
                                    --Refresh the list of potential targets
                                    local iLastEntry = table.getn(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets])
                                    for iCurEntry = iLastEntry, 1, -1 do
                                        if not (AiBotUnitInfo.IsUnitValid(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets][iCurEntry])) then
                                            table.remove(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets], iCurEntry)
                                        end
                                    end
                                    if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets]) == false then
                                        --Do we have >=50% complete T2+ mex, or 100% of a high value alt unit?
                                        local iDecentTargetCount = 0
                                        local bDontDoDistanceCheck = false
                                        if table.getn(tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets]) >= 5 then bDontDoDistanceCheck = true end
                                        for iUnit, oUnit in tAltLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets] do
                                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Distance to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
                                            if oUnit:GetFractionComplete() >= 0.75 then
                                                if bDontDoDistanceCheck or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= AiBotBuilding.iTMLMissileRange - 10 then
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex - categories.TECH1, oUnit.UnitId) then
                                                        iDecentTargetCount = iDecentTargetCount + 1
                                                    else iDecentTargetCount = iDecentTargetCount + oUnit:GetFractionComplete() *  (oUnit:GetBlueprint().BuildCostMass or 0) / 1200
                                                    end
                                                    if iDecentTargetCount >= 1 then break end
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iDecentTargetCount='..iDecentTargetCount) end
                                        if iDecentTargetCount >= 1 then
                                            iBPWanted = 40
                                            if not (bHaveLowMass) then
                                                iBPWanted = 80
                                            end
                                            break
                                        end
                                    end
                                end
                            end
                        else
                            if bDebugMessages == true then
                                LOG(sFunctionRef .. ': Remaining zones out of range so will abort')
                            else
                                break --so we can see distances for other zones that we arent including
                            end

                        end
                    end
                end
            end
        else
            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZData)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, iBPWanted='..iBPWanted) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iBPWanted
end

function GetStartSearchPositionForEmergencyPD(tNearestEnemy, tLZMidpoint, iPlateau, iLandZone, tLZData, tLZTeamData, iExpectedPDTechLevel)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetStartSearchPositionForEmergencyPD'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; tNearestEnemy='..repru(tNearestEnemy)..'; Time='..GetGameTimeSeconds()) end
    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, tLZMidpoint)
    local iDistToPointToMove = iDistToTarget
    local iBaseLZAverageSize = 0.5*((tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX])*AiBotMap.iLandZoneSegmentSize + (tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ])*AiBotMap.iLandZoneSegmentSize)
    local iDistToMoveFromEnemyToLZ --We set this later on

    local iAngleFromTargetToMidpoint
    local bUseLandTravelPath
    local tFullPath, iPathSize, iDistance
    local tPointToMoveFrom
    local tTargetLocation
    local iDistanceToIgnorePathingAndBuildAwayFromEnemy
    if iExpectedPDTechLevel >= 2 then iDistanceToIgnorePathingAndBuildAwayFromEnemy = 70
    else iDistanceToIgnorePathingAndBuildAwayFromEnemy = 45
    end

    if iDistToTarget >= iDistanceToIgnorePathingAndBuildAwayFromEnemy and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tNearestEnemy) == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZMidpoint) then bUseLandTravelPath = true
        --Generate the land travel path from the enemy to our base
        tFullPath, iPathSize, iDistance = NavUtils.PathTo(AiBotMap.refPathingTypeLand, tLZMidpoint, tNearestEnemy)
        if not(tFullPath) then bUseLandTravelPath = false
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to calculate detailed land path to determine PD placement, or if enemy is so close we should just build away from them, bUseLandTravelPath='..tostring(bUseLandTravelPath or false)..'; iDistToTarget='..iDistToTarget..'; iDistanceToIgnorePathingAndBuildAwayFromEnemy='..iDistanceToIgnorePathingAndBuildAwayFromEnemy) end
    if bUseLandTravelPath then

        iDistToMoveFromEnemyToLZ = math.max(math.min(30, iDistance), math.min(iDistance * 0.6, iDistToTarget))
        --Make it less likely we build outside the zone (unless a core base where we might be ok to build on outskirts)
        if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.1 or tLZTeamData[AiBotMap.subrefLZFortify] then
            iDistToMoveFromEnemyToLZ = math.max(iDistToMoveFromEnemyToLZ, iDistToTarget - iBaseLZAverageSize)
        end
        --If dist to target is far away from dist to move then increase slightly
        if iDistToMoveFromEnemyToLZ < 100 and iDistToTarget >= 225 then
            iDistToMoveFromEnemyToLZ = math.max(iDistToMoveFromEnemyToLZ, math.min(iBaseLZAverageSize * 2, 150, iDistToTarget * 0.3))
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iDistance='..iDistance..'; iDistToMoveFromEnemyToLZ after adjustment='..iDistToMoveFromEnemyToLZ..'; iDistToTarget='..iDistToTarget..'; iBaseLZAverageSize='..iBaseLZAverageSize) end

        local iCurPathDistance = 0
        local iCumulativePathDistance = 0
        --If nearest enemy is close to the pathing point then just replace the first entry with nearest enemy
        if tFullPath[1] and AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, tFullPath[1]) <= 5 then
            tFullPath[1] = {tNearestEnemy[1], tNearestEnemy[2], tNearestEnemy[3]}
        else
            table.insert(tFullPath, 1, tNearestEnemy)
        end
        table.insert(tFullPath, tLZMidpoint)
        if bDebugMessages == true then
            if bDebugMessages == true then LOG(sFunctionRef..': iDistance='..iDistance..'; iDistToTarget (straightline)='..iDistToTarget..'; tFullPath='..repru(tFullPath)..'; Will draw full path, iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ) end
            for iEntry, tViaPoint in tFullPath do
                if iEntry > 1 then
                    ForkThread(AiBotUtilities.ForkedDrawLine, tFullPath[iEntry - 1], tViaPoint, 2, 100)
                end
            end
        end
        local iCurSegmentX, iCurSegmentZ, iDetailedCurSegmentX, iDetailedCurSegmentZ

        for iCurEntry, tViaPoint in tFullPath do
            if iCurEntry > 1 then
                iCurPathDistance = AiBotUtilities.GetDistanceBetweenPositions(tFullPath[iCurEntry - 1], tViaPoint)
                iCumulativePathDistance = iCumulativePathDistance + iCurPathDistance
                if bDebugMessages == true then LOG(sFunctionRef..': Are using land travel path to get PD position, iCurEntry='..iCurEntry..'; tViaPoint='..repru(tViaPoint)..'; iCurPathDistance='..iCurPathDistance..'; iCumulativePathDistance before this='..iCumulativePathDistance..'; iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ) end
                if iCumulativePathDistance >= iDistToMoveFromEnemyToLZ then
                    iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tViaPoint)
                    if AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] == iLandZone then
                        --Get the detailed path between these two points
                        local iCumulativeDetailedPathDistance = iCumulativePathDistance - iCurPathDistance
                        local iCurDetailedPathDistance
                        local tDetailedPath, iDetailedPathEntries, iDetailedPathLength = NavUtils.DetailedPathTo(AiBotMap.refPathingTypeLand, tFullPath[iCurEntry - 1], tViaPoint)
                        if tDetailedPath then
                            table.insert(tDetailedPath, 1, tFullPath[iCurEntry - 1])
                            table.insert(tFullPath, tViaPoint)
                        end
                        if AiBotUtilities.IsTableEmpty(tDetailedPath) == false and iDetailedPathEntries >= 1 then
                            for iDetailedEntry, tDetailedViaPoint in tDetailedPath do
                                if iDetailedEntry > 1 then
                                    iCurDetailedPathDistance = AiBotUtilities.GetDistanceBetweenPositions(tDetailedViaPoint, tDetailedPath[iDetailedEntry - 1])
                                    iCumulativeDetailedPathDistance = iCumulativeDetailedPathDistance + iCurDetailedPathDistance
                                    iDetailedCurSegmentX, iDetailedCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tDetailedViaPoint)
                                    if AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] == iLandZone then
                                        if iCurDetailedPathDistance >= iDistToMoveFromEnemyToLZ then
                                            tPointToMoveFrom = AiBotUtilities.MoveInDirection(tDetailedPath[iDetailedEntry - 1], AiBotUtilities.GetAngleFromAToB(tDetailedPath[iDetailedEntry - 1], tDetailedViaPoint), math.max(0, iDistToMoveFromEnemyToLZ - iCumulativeDetailedPathDistance + iCurPathDistance), true, false, true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Setting PD placement using detailed path, tPointToMoveFrom='..repru(tPointToMoveFrom)..'; iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ..'; iCumulativeDetailedPathDistance='..iCumulativeDetailedPathDistance..'; iCurPathDistance='..iCurPathDistance..'; Dist that will actually have moved='..math.max(0, iDistToMoveFromEnemyToLZ - iCumulativeDetailedPathDistance + iCurPathDistance)) end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if not(tPointToMoveFrom) then
                            --Redundancy
                            tPointToMoveFrom = AiBotUtilities.MoveInDirection(tFullPath[iCurEntry - 1], AiBotUtilities.GetAngleFromAToB(tFullPath[iCurEntry - 1], tViaPoint), math.max(iDistToMoveFromEnemyToLZ - iCumulativePathDistance + iCurPathDistance, 0), true, false, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting PD placement using simplified path as redundancy, iCurEntry='..iCurEntry..'; Previous path position='..repru(tFullPath[iCurEntry - 1])..'; tViaPoint='..repru(tViaPoint)..'; Angle to via point='..AiBotUtilities.GetAngleFromAToB(tFullPath[iCurEntry - 1], tViaPoint)..'; tPointToMoveFrom='..repru(tPointToMoveFrom)..'; Dist from pointtovmovefrom and nearestenemy='..AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, tPointToMoveFrom)..'; iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ..'; iCumulativeDetailedPathDistance='..iCumulativeDetailedPathDistance..'; iCurPathDistance='..iCurPathDistance) end
                        end
                        break
                    else
                        --Keep looking
                    end
                else
                    --Keep looking
                end
            end
        end
        if not(tPointToMoveFrom) then
            bUseLandTravelPath = false --revert to default logic (redundancy)
        else
            iAngleFromTargetToMidpoint = AiBotUtilities.GetAngleFromAToB(tPointToMoveFrom, tLZMidpoint)
            tTargetLocation = { tPointToMoveFrom[1], tPointToMoveFrom[2], tPointToMoveFrom[3] }

            local iDistToEnemyFromHere = AiBotUtilities.GetDistanceBetweenPositions(tPointToMoveFrom, tNearestEnemy)
            iDistToMoveFromEnemyToLZ = math.max(iDistToEnemyFromHere * 0.7, iDistToMoveFromEnemyToLZ * 0.5)
            iDistToPointToMove = AiBotUtilities.GetDistanceBetweenPositions(tPointToMoveFrom, tLZMidpoint)
            --NOTE: In v268 adjusted this, previously iDistToMoveFromEnemyToLZ = 0, but was causing errors where were adjusting for cliff height; however this new approach might also cause unexpected issues
            if bDebugMessages == true then LOG(sFunctionRef..': We have a point to move from based on the detailed travel path, which should already be sufficient distance from the nearest enemy, dist to midpoint (iDistToPointToMove)='..iDistToPointToMove..'; Dist from tNearestEnemy to tPointToMoveFrom='..AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, tPointToMoveFrom)..'; iDistToMoveFromEnemyToLZ after adjust='..iDistToMoveFromEnemyToLZ) end
        end
    else
        iDistToMoveFromEnemyToLZ = math.max(32, iDistToTarget * 0.6)
        iDistToMoveFromEnemyToLZ = math.min(iDistToMoveFromEnemyToLZ, iBaseLZAverageSize)
        if iDistToTarget - iDistToMoveFromEnemyToLZ >= 60 then
            iDistToMoveFromEnemyToLZ = math.min(iDistToTarget - 60, 100) --will adjust below e.g. if are using land travel logic
        end
    end
    if not(bUseLandTravelPath) then
        tPointToMoveFrom = {tNearestEnemy[1], tNearestEnemy[2], tNearestEnemy[3]}
        iAngleFromTargetToMidpoint = AiBotUtilities.GetAngleFromAToB(tNearestEnemy, tLZMidpoint)
        tTargetLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ, true, false, true)
    end

    --Adjust if T2 arti nearby
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
        --Get closest T2 arti
        local oClosestT2Arti
        local iClosestT2ArtiDist = 100000
        local iCurDist
        for iUnit, oUnit in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
            if not(oUnit.Dead) then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tTargetLocation)
                if iCurDist < iClosestT2ArtiDist then
                    iClosestT2ArtiDist = iCurDist
                    oClosestT2Arti = oUnit
                end
            end
        end

        if oClosestT2Arti and iClosestT2ArtiDist <= (oClosestT2Arti[AiBotUnitInfo.refiIndirectRange] or 120) + 4 then
            iAngleFromTargetToMidpoint = AiBotUtilities.GetAngleFromAToB(oClosestT2Arti:GetPosition(), tLZMidpoint)
            iDistToMoveFromEnemyToLZ = (oClosestT2Arti[AiBotUnitInfo.refiIndirectRange] or 120) + 10 - iClosestT2ArtiDist
            tTargetLocation = AiBotUtilities.MoveInDirection(tPointToMoveFrom, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ, true, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Adjusted for T2 arti location, iClosestT2ArtiDist='..iClosestT2ArtiDist) end
        end
    end

    --Adjust if enemy has long range DF units nearby
    local bMovedDueToLRThreat = false
    if tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] > 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
        local iCurDistUntilInRange
        local iClosestDist = 15 --If we would be building this close to enemy unit then want to move further back
        local oClosestLRUnit
        for iLRUnit, oLRUnit in tLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
            if not(oLRUnit.Dead) and (oLRUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 then
                iCurDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(oLRUnit:GetPosition(), tTargetLocation) - oLRUnit[AiBotUnitInfo.refiDFRange]
                if iCurDistUntilInRange <= iClosestDist then
                    oClosestLRUnit = oLRUnit
                    iClosestDist = iCurDistUntilInRange
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if build location is close to enemy LR threats, oClosestLRUnit that is almost in range of it='..(oClosestLRUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestLRUnit) or 'nil')..'; iClosestDist (factoring in range)='..iClosestDist..'; tTargetLocation='..repru(tTargetLocation)) end
        if oClosestLRUnit then
            local iAngleFromLRUnit = AiBotUtilities.GetAngleFromAToB(oClosestLRUnit:GetPosition(), tTargetLocation)
            local iRangeFallback = 25
            if AiBotUtilities.GetDistanceBetweenPositions(oClosestLRUnit:GetPosition(), tLZMidpoint) - oClosestLRUnit[AiBotUnitInfo.refiDFRange] >= 30 then iRangeFallback = 35 end
            if AiBotUtilities.GetAngleDifference(iAngleFromLRUnit, iAngleFromTargetToMidpoint) > 90 then
                tPointToMoveFrom = oClosestLRUnit:GetPosition()
                iDistToMoveFromEnemyToLZ = -iCurDistUntilInRange + iRangeFallback - 5
                iAngleFromTargetToMidpoint = AiBotUtilities.GetAngleFromAToB(oClosestLRUnit:GetPosition(), tLZMidpoint)
                if bDebugMessages == true then LOG(sFunctionRef..': Big angle dif so will revise so we are moving away from the nearest LR threat') end
            else
                iDistToMoveFromEnemyToLZ = iDistToMoveFromEnemyToLZ -iCurDistUntilInRange + iRangeFallback
            end
            local tPotentialNewLocation = AiBotUtilities.MoveInDirection(tPointToMoveFrom, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ, true, false, AiBotMap.bIsCampaignMap)
            if tPotentialNewLocation and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPotentialNewLocation) == iPlateau then
                if bDebugMessages == true then LOG(sFunctionRef..': Moving build location due to enemy LR threat, for P'..iPlateau..'Z'..iLandZone..'; Dist moved away='..(-iCurDistUntilInRange + 20)..'; iCurDistUntilInRange='..iCurDistUntilInRange..'; iAngleFromLRUnit='..iAngleFromLRUnit..'; tPotentialNewLocation='..repru(tPotentialNewLocation)..'; Dist from tPotentialNewLocation to tNearestEnemy='..AiBotUtilities.GetDistanceBetweenPositions(tPotentialNewLocation, tNearestEnemy)..'; iDistToMoveFromEnemyToLZ after adjust='..iDistToMoveFromEnemyToLZ) end
                tTargetLocation = {tPotentialNewLocation[1], tPotentialNewLocation[2], tPotentialNewLocation[3]}
                bMovedDueToLRThreat = true
            end
        end
    end

    --Adjust if we end up out of the zone
    local iTargetPlateau, iTargetLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Time ' .. GetGameTimeSeconds() .. '; First position with iDistToMoveFromEnemyToLZ=' .. iDistToMoveFromEnemyToLZ .. '=' .. repru(tTargetLocation) .. '; tLZMidpoint=' .. repru(tLZMidpoint) .. '; tPointToMoveFrom=' .. repru(tPointToMoveFrom) .. '; Dist to midpoint=' .. AiBotUtilities.GetDistanceBetweenPositions(tPointToMoveFrom, tLZMidpoint) .. '; Dist to original target=' .. AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, tTargetLocation) .. '; iTargetPlateau=' .. (iTargetPlateau or 'nil') .. '; iTargetLandZone=' .. (iTargetLandZone or 'nil')..'; iLandZone='..iLandZone)
    end
    if (iDistToPointToMove or 100000) < 500 then --To prevent infinite loop
        local iMaxDistToMove = math.max(iDistToPointToMove, AiBotUtilities.GetDistanceBetweenPositions(tLZMidpoint, tNearestEnemy))
        while not (iLandZone == iTargetLandZone) do
            --LOG('Emergency PD log, iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ..'; iDistToPointToMove='..(iDistToPointToMove or 'nil'))
            iDistToMoveFromEnemyToLZ = iDistToMoveFromEnemyToLZ + 5
            if iDistToMoveFromEnemyToLZ > iMaxDistToMove then
                if bDebugMessages == true then LOG(sFunctionRef..': Will set target location to be the LZMidpoint as iDistToMoveFromEnemyToLZ is now greater than iMaxDistToMove='..iMaxDistToMove) end
                tTargetLocation = {tLZMidpoint[1], tLZMidpoint[2], tLZMidpoint[3]}
                break
            else
                tTargetLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ, true, false, true)
                if iDistToMoveFromEnemyToLZ >=2000 then AiBotUtilities.ErrorHandler('Likely infinite loop, will abort') break end
            end

            iTargetPlateau, iTargetLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
            if bDebugMessages == true then LOG(sFunctionRef..': Trying to find location in same zone, adjusted the target location by increasing the distance to move, New location='..repru(tTargetLocation)..'; land zone='..(iTargetLandZone or 'nil')..'; iLandZone='..iLandZone) end
        end
    end


    --Adjust if likely to be on elevated ground and unable to hit the enemy as a result (move closer so are on edge of cliff); if the reverse (we are on lower ground) then move away
    if bDebugMessages == true then LOG(sFunctionRef..': Y height of target location='..tTargetLocation[2]..'; Y height of nearest enemy='..tNearestEnemy[2]..'; iDistToMoveFromEnemyToLZ='..iDistToMoveFromEnemyToLZ..'; bMovedDueToLRThreat='..tostring(bMovedDueToLRThreat)..'; tTargetLocation before cliff adjust='..repru(tTargetLocation)) end
    local bMoveBackFromBlockingCliff = false
    if not(bMovedDueToLRThreat) and tTargetLocation[2] > tNearestEnemy[2] + 1 and iDistToMoveFromEnemyToLZ >= 35 then
        local iDistToCliff
        local iMaxHeightBeforeConsideringMovingBack = tTargetLocation[2] + 1 --if changing here also change below for iHeightThreshold
        for iCurCliffAdjust = 1, 20 do
            local tAltLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ - iCurCliffAdjust, true, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurCliffAdjust='..iCurCliffAdjust..'; tAltLocation plateau='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) or 'nil')..'; Height='..tAltLocation[2]..'; iMaxHeightBeforeConsideringMovingBack='..iMaxHeightBeforeConsideringMovingBack) end
            if tAltLocation[2] >= iMaxHeightBeforeConsideringMovingBack then
                if bDebugMessages == true then LOG(sFunctionRef..': Might have a blocking cliff that is taller, despite us being taller than enemy, so actually want to move back') end
                bMoveBackFromBlockingCliff = true break
            end
            if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) == iPlateau) then
                if bDebugMessages == true then LOG(sFunctionRef..': Have reahced location with dif hover pathing label suggesting a cliff, iCurCliffAdjust='..iCurCliffAdjust) end
                iDistToCliff = iCurCliffAdjust - 1
                break
            end
        end
        if iDistToCliff and not(bMoveBackFromBlockingCliff) then
            for iCurCliffAdjust = iDistToCliff + 2, iDistToCliff + 22, 2 do
                local tAltLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ - iCurCliffAdjust, true, false, true)
                if tAltLocation[2] >= iMaxHeightBeforeConsideringMovingBack then
                    if bDebugMessages == true then LOG(sFunctionRef..': 2nd check, may have a blocking cliff that is taller, despite us being taller than enemy, so actually want to move back') end
                    bMoveBackFromBlockingCliff = true break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished checking cliff adj, bMoveBackFromBlockingCliff='..tostring(bMoveBackFromBlockingCliff or false)..'; iDistToCliff='..(iDistToCliff or 'nil')..'; tTargetLocation='..repru(tTargetLocation)) end
        if not(bMoveBackFromBlockingCliff) and iDistToCliff then
            tTargetLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ - iDistToCliff, true, false, true)
        end
    elseif tTargetLocation[2] < tNearestEnemy[2] - 1 then
        local iDistFromMidpoint = AiBotUtilities.GetDistanceBetweenPositions(tLZMidpoint, tNearestEnemy)
        if iDistFromMidpoint >= 35 then
            local iIslandWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZMidpoint)
            if iIslandWanted then
                local iDistFromCliff
                for iCurCliffAdjust = 15, 40, 5 do
                    local tAltLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ + iCurCliffAdjust, true, false, true)
                    if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) == iPlateau and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tAltLocation) == iIslandWanted then
                        local tPositionTowardsEnemy = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ + iCurCliffAdjust - 50, true, false, true)
                        iDistFromCliff = iCurCliffAdjust
                        if tAltLocation[2] > tPositionTowardsEnemy[2] - 1 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Build location would be much lower than enemy so want to build further back from enemy, at this point we think there is no longer such a height difference iCufCliffAdjust='..iCurCliffAdjust) end
                            break
                        elseif bDebugMessages == true then LOG(sFunctionRef..': At iCurCliffAdjust='..iCurCliffAdjust..' the height dif is still too great, tAltLocation[2]='..tAltLocation[2]..'; tPositionTowardsEnemy[2]='..tPositionTowardsEnemy[2])
                        end
                    end
                end
                if iDistFromCliff then
                    tTargetLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ + iDistFromCliff, true, false, true)
                end
            end
        end
    else
        bMoveBackFromBlockingCliff = true
    end
    if bMoveBackFromBlockingCliff then
        --Consider if there is a cliff inbetween us and the enemy that is a higher height (even if the enemy itself is on the same or lower height)
        local iMaxSearchRange
        if iDistToMoveFromEnemyToLZ > 30 then iMaxSearchRange = 30 else iMaxSearchRange = math.floor(iDistToMoveFromEnemyToLZ / 5)*5 - 5 end
        if iMaxSearchRange >= 5 then
            local iAngleFromBuildLocation = iAngleFromTargetToMidpoint + 180
            if iAngleFromBuildLocation > 360 then iAngleFromBuildLocation = iAngleFromBuildLocation - 360 end
            local iHeightThreshold = tTargetLocation[2] + 1 --if changing here also change above for iMaxHeightBeforeConsideringMovingBack
            local iBlockingCliffDist
            for iCurSearchDist = 5, iMaxSearchRange, 5 do
                local tCliffCheckLocation = AiBotUtilities.MoveInDirection(tTargetLocation, iAngleFromBuildLocation, iCurSearchDist, false)
                if tCliffCheckLocation[2] >= iHeightThreshold then
                    iBlockingCliffDist = iCurSearchDist
                    break
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking whether we have a blocking cliff so will try and move the PD back if we do, iBlockingCliffDist='..(iBlockingCliffDist or 'nil')) end
            if iBlockingCliffDist then
                --Move the PD back if possible
                local iDistToMoveFromEnemyToLZBack = math.min(30, 50 - iBlockingCliffDist)
                local iIslandWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLZMidpoint)
                if iIslandWanted then
                    for iDistAdjust = iDistToMoveFromEnemyToLZBack, 5, -5 do
                        local tAltLocation = AiBotUtilities.MoveInDirection(tNearestEnemy, iAngleFromTargetToMidpoint, iDistToMoveFromEnemyToLZ + iDistAdjust, true, false, true)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if alt location for iDistAdjust='..iDistAdjust..' is valid and not too far below the enemy, height dif to enemy='..(tAltLocation[2] or 0) - tNearestEnemy[2]..'; Island='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tAltLocation) or 'nil')..'; iIslandWanted='..iIslandWanted) end
                        if AiBotUtilities.IsTableEmpty(tAltLocation) == false and tAltLocation[2] - tNearestEnemy[2] >= -0.8 and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) == iPlateau and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tAltLocation) == iIslandWanted then
                            if bDebugMessages == true then LOG(sFunctionRef..': will set new target location to tAltLocation, tTargetLocation dist to tAltLocation='..AiBotUtilities.GetDistanceBetweenPositions(tTargetLocation, tAltLocation)..'; iDistAdjust='..iDistAdjust) end
                            tTargetLocation = {tAltLocation[1], tAltLocation[2], tAltLocation[3]}
                            break
                        end
                    end
                end
            end
        end
    elseif GetTerrainHeight(tNearestEnemy[1], tNearestEnemy[3]) < AiBotMap.iMapWaterHeight then
        --Dont build on the edge but instead move back if enemy is in the water
        if bDebugMessages == true then LOG(sFunctionRef..': Enemy is approaching from the water so want to move back so they are just in our range when they make landfall') end
        local iMinDistFromWaterWanted = 20 --Often water will be shallow so no harm on being able to hit slightly at the water
        if iExpectedPDTechLevel > 1 then iMinDistFromWaterWanted = 35 end
        --If we move from target location towards enemy are we in water?
        local iAngleFromMidpointToNearestEnemy = AiBotUtilities.GetAngleFromAToB(tLZMidpoint, tNearestEnemy)
        for iCurMoveBackDist = 0, iMinDistFromWaterWanted, 5 do
            local tPotentialWaterLocation = AiBotUtilities.MoveInDirection(tTargetLocation, iAngleFromMidpointToNearestEnemy, iMinDistFromWaterWanted - iCurMoveBackDist, true, true, true)
            if bDebugMessages == true then LOG(sFunctionRef..': iCurMoveBackDist='..iCurMoveBackDist..'; tPotentialWaterLocation='..repru(tPotentialWaterLocation)..'; Terrain height='..GetTerrainHeight(tPotentialWaterLocation[1], tPotentialWaterLocation[3])..'; iMapWaterHeight='..AiBotMap.iMapWaterHeight) end
            if GetTerrainHeight(tPotentialWaterLocation[1], tPotentialWaterLocation[3]) >= AiBotMap.iMapWaterHeight then
                --Have land; so consider switching to here
                if iCurMoveBackDist > 0 then
                    local tAltLocation = AiBotUtilities.MoveInDirection(tTargetLocation, iAngleFromMidpointToNearestEnemy + 180, iCurMoveBackDist, true, true, true)
                    --Check we arent building on a cliff
                    if bDebugMessages == true then LOG(sFunctionRef..': tAltLocation='..repru(tAltLocation)..'; Land pathing ref of this='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tAltLocation) or 'nil')..'; subrefLZIslandRef='..(tLZData[AiBotMap.subrefLZIslandRef] or 'nil')) end
                    if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tAltLocation) == tLZData[AiBotMap.subrefLZIslandRef] then
                        --Check we arent blocked by a cliff
                        local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
                        local tShotStart = {tAltLocation[1], tAltLocation[2] + iExpectedPDTechLevel * 0.5, tAltLocation[3]}
                        local tShotEndPosition = {tPotentialWaterLocation[1], tPotentialWaterLocation[2] + 1, tPotentialWaterLocation[3]}
                        if bDebugMessages == true then LOG(sFunctionRef..': Is line blocked between shot start and shot end='..tostring(import('/lua/AiBot/AI/AiBotLogic.lua').IsLineBlocked(aiBrain, tShotStart, tShotEndPosition, 0, false, false))) end
                        if not(import('/lua/AiBot/AI/AiBotLogic.lua').IsLineBlocked(aiBrain, tShotStart, tShotEndPosition, 0, false, false)) then
                            --Change the start position
                            tTargetLocation = {tAltLocation[1], tAltLocation[2], tAltLocation[3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Changing PD placement so we move back from water by '..iCurMoveBackDist) end
                        end

                    end
                end
                break --First potential location is invalid, wont look further for performance reasons
            end
        end
    end


    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Time=' .. GetGameTimeSeconds() .. '; tNearestEnemy=' .. repru(tNearestEnemy) .. '; tLZMidpoint=' .. repru(tLZMidpoint) .. '; iAngleFromTargetToMidpoint=' .. iAngleFromTargetToMidpoint .. '; iDistToTarget=' .. iDistToTarget .. '; iDistToMoveFromEnemyToLZ=' .. iDistToMoveFromEnemyToLZ .. '; tTargetLocation=' .. repru(tTargetLocation)..'; Dist between tNearestEnemy and tTargetLocation='..AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemy, (tTargetLocation or {0,0,0}))..'; will draw original target location in blue and the midpoint in red, and the revised target in gold')
        AiBotUtilities.DrawLocation(tNearestEnemy, 1)
        AiBotUtilities.DrawLocation(tLZMidpoint, 2)
        AiBotUtilities.DrawLocation(tTargetLocation, 4)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return tTargetLocation
end

function GetMaxShieldSearchRangeForEngineer(oFirstEngineer, iCategoryWanted)
    --Sets max search range to ensure we dont go outside the max shield radius available to oFirstEngineer
    local bDebugMessages = false
    if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetMaxShieldSearchRangeForEngineer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                            --GetBlueprintThatCanBuildOfCategory(aiBrain,               iCategoryCondition, oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
    local tsAvailableBlueprints = AiBotFactory.GetBlueprintThatCanBuildOfCategory(oFirstEngineer:GetAIBrain(), iCategoryWanted, oFirstEngineer)
    local iMaxSearchRange = 10 --Default in case something goes wrong
    if AiBotUtilities.IsTableEmpty(tsAvailableBlueprints) == false then
        for iShield, sShield in tsAvailableBlueprints do
            iMaxSearchRange = math.max(iMaxSearchRange, (__blueprints[sShield].ShieldSize or 0) * 0.5)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iMaxSearchRange
end

function ClearEngineersBuildingUnit(oEngineer, oJustBuilt, bClearEngineersBuildingAtSameLocation)
    --Note - oJustBuilt can also be a unit under construction (e.g. if we want to cancel construction and reclaim it)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ClearEngineersBuildingUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Ignore logic if this was built as part of the gameendertemplate logic
    if not(oEngineer[AiBotBuilding.reftArtiTemplateRefs] or oJustBuilt[AiBotBuilding.reftArtiTemplateRefs]) and not(oEngineer[refiAssignedAction] == refActionSpecialShieldDefence) and not(oEngineer[refiAssignedAction] == refActionManageGameEnderTemplate) then

        local iAction = oEngineer[refiAssignedAction]

        function ClearEngineerIfActionObseleteNow(oCurEngineer, bCalledViaRepairTracking)
            local bClearEngineer = false
            if AiBotUnitInfo.IsUnitValid(oCurEngineer) and not (oCurEngineer:IsUnitState('Reclaiming')) and not(oCurEngineer[AiBotUnitInfo.refbCampaignNeverPause]) then
                --Does it have the same action, or alternatitvely is it trying to build something at this location that will now be blocked?
                local tLastOrder = oCurEngineer[AiBotOrders.reftiLastOrders][oCurEngineer[AiBotOrders.refiOrderCount]]
                local iOrderDistToJustBuilt
                --Ignore if last order was to load onto transport
                if not(tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderLoadOntoTransport) and not(oEngineer[refiAssignedAction] == refActionLoadOntoTransport) then --redundancy
                    if AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false then iOrderDistToJustBuilt = AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oJustBuilt:GetPosition()) end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if should clear engineer, oJustBuilt='..(oJustBuilt.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt) or 'nil')..'; oCurEngineer='..(oCurEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oCurEngineer) or 'nil')..'; iOrderDistToJustBuilt='..(iOrderDistToJustBuilt or 'nil')..'; tLastOrder[AiBotOrders.subrefoOrderUnitTarget]='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; iAction='..(iAction or 'nil')..'; Cur engineer action='..(oCurEngineer[refiAssignedAction] or 'nil')) end

                    if (iOrderDistToJustBuilt and iOrderDistToJustBuilt <= 1) or tLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oJustBuilt then
                        if bDebugMessages == true then LOG(sFunctionRef..': Engi last target was the unit that has just been built so is obsolete') end
                        bClearEngineer = true
                    elseif bCalledViaRepairTracking and oCurEngineer:GetFocusUnit() == oJustBuilt then
                        if bDebugMessages == true then LOG(sFunctionRef..': this was called via repair tracking and engineer focus unit is the one just built so is obsolete') end
                        bClearEngineer = true
                        --Are we building something near here that is now blocked?
                    elseif iOrderDistToJustBuilt and iOrderDistToJustBuilt <= 10 and tLastOrder[AiBotOrders.subrefsOrderBlueprint] then
                        local oBlueprint = __blueprints[tLastOrder[AiBotOrders.subrefsOrderBlueprint]]
                        local iBuildingRadius = math.min(oBlueprint.Physics.SkirtSizeX, oBlueprint.Physics.SkirtSizeZ) * 0.5
                        if iOrderDistToJustBuilt < iBuildingRadius * 1.45 then --1.4142 should be enough, 1.45 used for prudence
                            --do more precise check
                            if math.abs(tLastOrder[AiBotOrders.subreftOrderPosition][1] - oJustBuilt:GetPosition()[1]) < iBuildingRadius and math.abs(tLastOrder[AiBotOrders.subreftOrderPosition][3] - oJustBuilt:GetPosition()[3]) < iBuildingRadius then
                                if bDebugMessages == true then LOG(sFunctionRef..': Last order was to build something close to just built unit so is obsolete') end
                                bClearEngineer = true
                            end
                        end

                    end
                end
                if bClearEngineer then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will clear engineer') end
                    AiBotOrders.IssueTrackedClearCommands(oCurEngineer)
                end
            end
        end

        if (tiActionOrder[iAction] == AiBotOrders.refiOrderIssueBuild and not (tbIgnoreEngineerAssistance[iAction])) or (oJustBuilt:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oJustBuilt.UnitId)) then
            --FIrst clear any engineers tracked as repariing this building
            if AiBotUtilities.IsTableEmpty(oJustBuilt[AiBotOrders.toUnitsOrderedToRepairThis]) == false then
                for iCurEngineer = table.getn(oJustBuilt[AiBotOrders.toUnitsOrderedToRepairThis]), 1, -1 do
                    ClearEngineerIfActionObseleteNow(oJustBuilt[AiBotOrders.toUnitsOrderedToRepairThis][iCurEngineer], true)
                end
            end
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oEngineer:GetPosition())
            if (iLandOrWaterZone or 0) > 0 then
                local tLZOrWZTeamData
                local aiBrain = oEngineer:GetAIBrain()
                local iTeam = aiBrain.AiBotTeam
                if iPlateauOrZero == 0 then
                    tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                else
                    tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                end
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tAllEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tAllEngineers) == false then
                        for iUnit, oUnit in tAllEngineers do
                            ClearEngineerIfActionObseleteNow(oUnit, false)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ClearEngineersWhoseTargetIsNowBlockedByUnitConstructionStarted(oEngineer, oConstruction)
    --Idea is to prevent scenarios where two units get queued orders for the same location - once construction is started for one, it wont be possible for the other
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ClearEngineersWhoseTargetIsNowBlockedByUnitConstructionStarted'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iAction = oEngineer[refiAssignedAction]
    if tiActionOrder[iAction] == AiBotOrders.refiOrderIssueBuild then
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oConstruction:GetPosition())
        if (iLandOrWaterZone or 0) > 0 then
            local tLZOrWZTeamData
            local aiBrain = oEngineer:GetAIBrain()
            local iTeam = aiBrain.AiBotTeam
            if iPlateauOrZero == 0 then
                tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            else
                tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
            end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tAllEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tAllEngineers) == false then
                    local iBuildingSizeRadius = AiBotUnitInfo.GetBuildingSize(oConstruction.UnitId) * 0.5
                    local iQueuedBuildingSizeRadius
                    for iUnit, oUnit in tAllEngineers do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit[refiAssignedAction] and not (oUnit[refiAssignedAction] == iAction) and not (oUnit:IsUnitState('Reclaiming')) and tiActionOrder[oUnit[refiAssignedAction]] == AiBotOrders.refiOrderIssueBuild then
                            local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                            if tLastOrder[AiBotOrders.subrefsOrderBlueprint] then
                                if AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false then
                                    iQueuedBuildingSizeRadius = AiBotUnitInfo.GetBuildingSize(tLastOrder[AiBotOrders.subrefsOrderBlueprint]) * 0.5
                                    if AiBotUtilities.GetRoughDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oConstruction:GetPosition()) < iBuildingSizeRadius + iQueuedBuildingSizeRadius then
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef .. ': Clearing engineer ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. ' as it has a queued order ' .. reprs(tLastOrder) .. ' that is blocked by oConstruction=' .. oConstruction.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oConstruction.UnitId))
                                        end
                                        AiBotOrders.IssueTrackedClearCommands(oUnit)
                                    end
                                end
                            end
                        end
                    end
                end
            end

        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function ConsiderDestroyingLowTechEngineers(oJustBuilt, iOptionalMaxNumberToKill, toOptionalEngineersToConsderKilling, bDontReturnNumberKilled)
    --Intended late game where lots of low tech engis in a core base; will kill engineers and returns the number of engineers killed
    local bDebugMessages = false
    if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderDestroyingLowTechEngineers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if not(oJustBuilt.Dead) and oJustBuilt.GetAIBrain then
        local aiBrain = oJustBuilt:GetAIBrain()
        local iCurEngineers = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEngineer)
        local iEngineersKilled = 0
        if iCurEngineers >= 100 then
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
            if (iLandOrWaterZone or 0) > 0 then
                local tLZOrWZTeamData
                local iTeam = aiBrain.AiBotTeam
                if iPlateauOrZero == 0 then
                    tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                else
                    tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                end
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tT1AndT2EngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer * categories.TECH1 + AiBotUnitInfo.refCategoryEngineer * categories.TECH2, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tT1AndT2EngineersInZone) == false then
                        local iT1AndT2EngineersInZone = table.getn(tT1AndT2EngineersInZone)
                        if iT1AndT2EngineersInZone >= 10 or (iCurEngineers >= 150 and iT1AndT2EngineersInZone >= 4) then
                            local tT3EngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer * categories.TECH3, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            local iT3EngineersInZone
                            if AiBotUtilities.IsTableEmpty(tT3EngineersInZone) == false then iT3EngineersInZone = table.getn(tT3EngineersInZone) end
                            if (iCurEngineers >= 200 and tT1AndT2EngineersInZone >= 60 and aiBrain[AiBotOverseer.refbCloseToUnitCap]) or iT3EngineersInZone >= 40 then
                                local iMaxToKill = (iOptionalMaxNumberToKill or 3)
                                --Ctrl-K up to 3 engineers
                                local tT1Engineers = EntityCategoryFilterDown(categories.TECH1, tT1AndT2EngineersInZone)
                                function KillEngineerIfSufficientlyIdle(oEngi)
                                    if (not(oEngi[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) then
                                        if not (oEngi[refbPrimaryBuilder]) and not (oEngi:IsUnitState('Building')) and not (oEngi:IsUnitState('Reclaiming')) and not (oEngi:IsUnitState('Capturing')) and not (oEngi:IsUnitState('Repairing')) then
                                            if bDebugMessages == true then LOG(sFunctionRef .. ': Just given order to kill unit ' .. oEngi.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oEngi) .. ' as have oto many engis in this zone') end
                                            AiBotOrders.IssueTrackedKillUnit(oEngi)
                                            iEngineersKilled = iEngineersKilled + 1
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(toOptionalEngineersToConsderKilling) == false then
                                    for iUnit, oUnit in toOptionalEngineersToConsderKilling do
                                        KillEngineerIfSufficientlyIdle(oUnit)
                                        if iEngineersKilled >= iMaxToKill then
                                            break
                                        end
                                    end
                                elseif AiBotUtilities.IsTableEmpty(tT1Engineers) == false then
                                    for iUnit, oUnit in tT1Engineers do
                                        KillEngineerIfSufficientlyIdle(oUnit)
                                        if iEngineersKilled >= iMaxToKill then
                                            break
                                        end
                                    end
                                end
                                if iEngineersKilled < iMaxToKill then
                                    local tT2Engineers = EntityCategoryFilterDown(categories.TECH2, tT1AndT2EngineersInZone)
                                    if AiBotUtilities.IsTableEmpty(tT2Engineers) == false then
                                        for iUnit, oUnit in tT2Engineers do
                                            KillEngineerIfSufficientlyIdle(oUnit)
                                            if iEngineersKilled >= iMaxToKill then
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if not(bDontReturnNumberKilled) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return iEngineersKilled
        end
    else
        if not(bDontReturnNumberKilled) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return 0
        end
    end
end

function RecordUnitAsCaptureTarget(oUnit, bOptionalOnlyRecordIfSameUnitIdInCaptureList)
    --bOptionalOnlyRecordIfSameUnitIdInCaptureList - true if we only want to record oUnit if a unit with the same .UnitId is in the zone as a capture target - i.e. intended where a unit is captured that can be captured back
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordUnitAsCaptureTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotMap.bIsCampaignMap and not(EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) then
        while not(AiBotMap.bWaterZoneInitialCreation) do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if GetGameTimeSeconds() >= 10 then break end
        end

        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        local tLZOrWZData
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..';  oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; Unit position='..repru(oUnit:GetPosition())..'; Unit owner='..oUnit:GetAIBrain().Nickname) end
        if iLandOrWaterZone > 0 then
            if iPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            end
            --If this was called via onunitcaptured then want to check if the same unitid was recorded in a table of capture targets:
            local bWantToCaptureUnit = not(bOptionalOnlyRecordIfSameUnitIdInCaptureList)
            if bOptionalOnlyRecordIfSameUnitIdInCaptureList then
                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false then
                    for iCaptureTarget, oCaptureTarget in tLZOrWZData[AiBotMap.subreftoUnitsToCapture] do
                        if oCaptureTarget.UnitId == oUnit.UnitId then
                            bWantToCaptureUnit = true
                            break
                        end
                    end
                end
            end

            --Check we havent already recorded this unit
            if bWantToCaptureUnit and oUnit[AiBotUnitInfo.refbIsCaptureTarget] and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false then
                for iRecordedUnit, oRecordedUnit in tLZOrWZData[AiBotMap.subreftoUnitsToCapture] do
                    if oRecordedUnit == oUnit then
                        bWantToCaptureUnit = false
                        break
                    end
                end
            end

            --Record unit against zone as a capture target and flag so we dont try and reclaim it
            if bDebugMessages == true then LOG(sFunctionRef..': bWantToCaptureUnit='..tostring(bWantToCaptureUnit)..'; oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
            if bWantToCaptureUnit then
                AiBotOverseer.RecordUnitAsCaptureTarget(oUnit, iPlateauOrZero, iLandOrWaterZone)
                if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of units to capture') end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForSpecialCampaignCaptureTargets()
    --Called whenever we get a new objective or the map size changes, as a basic way of checking for extra objectives that dont use the normal objective function
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForSpecialCampaignCaptureTargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --FA M6 - check for control centre building
    if bDebugMessages == true then LOG(sFunctionRef..': is ControlCentreBldg nil='..tostring(ScenarioInfo.ControlCenterBldg == nil)) end
    if ScenarioInfo.ControlCenterBldg then
        local oControlCentre = ScenarioInfo.ControlCenterBldg
        if bDebugMessages == true then LOG(sFunctionRef..': oControlCentre='..(oControlCentre.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oControlCentre) or 'nil')..'; Is capturable='..tostring(oControlCentre:IsCapturable())..'; refbIsCaptureTarget='..tostring(oControlCentre[AiBotUnitInfo.refbIsCaptureTarget] or false)) end
        if AiBotUnitInfo.IsUnitValid(oControlCentre) and oControlCentre:IsCapturable() then
            --Have we already recorded as a capturable target?
            if not(oControlCentre[AiBotUnitInfo.refbIsCaptureTarget]) then
                --Get first AiBot brain in game
                local oFirstAiBotBrain
                if AiBotUtilities.IsTableEmpty(AiBotOverseer.tAllActiveAiBotBrains) == false then
                    for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                        if oBrain.AiBotAI then
                            oFirstAiBotBrain = oBrain
                            if not(oBrain.CampaignAI) then
                                break
                            end
                        end
                    end
                end
                if oFirstAiBotBrain and not(IsAlly(oFirstAiBotBrain:GetArmyIndex(), oControlCentre:GetAIBrain():GetArmyIndex())) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will call logic to record control centre as a capture target') end
                    RecordUnitAsCaptureTarget(oControlCentre)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function GetLocationToBuildWall(oEngineer, oJustBuilt, sWallBP)
    --Builds wall around nearby T1 PD (if there is any), subject to blacklist
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetLocationToBuildWall'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oPDToSurround
    if EntityCategoryContains(AiBotUnitInfo.refCategoryPD * categories.TECH1, oJustBuilt.UnitId) then
        if oJustBuilt:GetBlueprint().Physics.SkirtSizeX <= 1 then
            oPDToSurround = oJustBuilt
        end
    else
        --Search nearby for T1 PD
        local tNearbyUnits = GetUnitsInRect(AiBotUtilities.GetRectAroundLocation(oJustBuilt:GetPosition(), 1.9))
        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
            local tNearbyPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD * categories.TECH1, tNearbyUnits)
            if AiBotUtilities.IsTableEmpty(tNearbyPD) == false then
                local tSuitablePDSize = {}
                for iUnit, oUnit in tNearbyPD do
                    if oUnit:GetBlueprint().Physics.SkirtSizeX <= 1 then
                        table.insert(tSuitablePDSize, oUnit)
                    end
                end
                if AiBotUtilities.IsTableEmpty(tSuitablePDSize) == false then
                    local iCurDist
                    local iClosestDist = 10000
                    if table.getn(tSuitablePDSize) > 1 then
                        for iPD, oPD in tSuitablePDSize do
                            iCurDist = AiBotUtilities.GetRoughDistanceBetweenPositions(oPD:GetPosition(), oJustBuilt:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oPDToSurround = oPD
                            end
                        end
                    else
                        oPDToSurround = tSuitablePDSize[1]
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near start, oPDToSurround='..(oPDToSurround.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPDToSurround) or 'nil')..'; Gametime='..GetGameTimeSeconds()..'; oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)) end
    if oPDToSurround then
        local tPDToSurround = oPDToSurround:GetPosition()
        --Get first location around the PD that is available for building, if any
        local aiBrain = oEngineer:GetAIBrain()
        local tiDistToEnemyBaseByXAndZ --used to decide which 3 wall segments not to build
        local tbDontBuildByXAndZ --true if we dont want to build these segments due to being in opposite direction to enemy
        for iXAdjust = -1, 1, 1 do
            for iZAdjust = -1, 1, 1 do
                if not(iXAdjust == 0 and iZAdjust == 0) then
                    local tTargetLocation = {tPDToSurround[1] + iXAdjust, tPDToSurround[2], tPDToSurround[3] + iZAdjust}
                    tTargetLocation[2] = GetSurfaceHeight(tTargetLocation[1], tTargetLocation[3])
                    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tTargetLocation)
                    if bDebugMessages == true then LOG(sFunctionRef..': Can engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..' that has just built unit '..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..' at position '..repru(oJustBuilt:GetPosition())..' build at tTargetLocation '..repru(tTargetLocation)..'='..tostring(CanBuildAtLocation(aiBrain, sWallBP, tTargetLocation, nil, nil, nil, false, true, false, true))..'; Simple can build check='..tostring(aiBrain:CanBuildStructureAt(sWallBP, tTargetLocation))..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')) end
                    if (iPlateau or 0) > 0 and (iLandZone or 0) > 0 then
                        --CanBuildAtLocation(aiBrain, sBlueprintToBuild, tTargetLocation, iOptionalPlateauGroupOrZero, iOptionalLandOrWaterZone, iEngiActionToIgnore, bClearActionsIfNotStartedBuilding, bCheckForQueuedBuildings, bCheckForOverlappingBuildings, bCheckBlacklistIfNoGameEnder, bConsideringResourceLocation)
                        if CanBuildAtLocation(aiBrain, sWallBP,         tTargetLocation,     iPlateau,                  iLandZone, nil, false, true, false, true, false) then
                            --Do we want to drop 3 of the wall segments to save mass?
                            if not(tiDistToEnemyBaseByXAndZ) then
                                local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oEngineer:GetAIBrain().AiBotTeam]
                                local oClosestDFEnemy
                                local iClosestDFEnemy = 1000
                                local iCurDist
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                    for iEnemy, oEnemy in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                        if not(oEnemy.Dead) then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tPDToSurround)
                                            if iCurDist < iClosestDFEnemy then
                                                iClosestDFEnemy = iCurDist
                                                oClosestDFEnemy = oEnemy
                                            end
                                        end
                                    end
                                end
                                local iAngleToEnemyBase = AiBotUtilities.GetAngleFromAToB(tPDToSurround, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                if not(oClosestDFEnemy) or AiBotUtilities.GetAngleDifference(iAngleToEnemyBase, AiBotUtilities.GetAngleFromAToB(tPDToSurround, oClosestDFEnemy:GetPosition())) <= 55 then
                                    --Get the 3 points furthest from the enemy base (in an ideal would work figure out the maths to calculate this , but easier to use this method since wont get t1 pd that often)
                                    tiDistToEnemyBaseByXAndZ = {}
                                    local iFurthest1 = 0
                                    local iFurthest2 = 0
                                    local iFurthest3 = 0
                                    tbDontBuildByXAndZ = {}
                                    for i2XAdjust = -1, 1, 1 do
                                        tiDistToEnemyBaseByXAndZ[i2XAdjust] = {}
                                        for i2ZAdjust = -1, 1, 1 do
                                            local tLocation = {tPDToSurround[1] + i2XAdjust, tPDToSurround[2], tPDToSurround[3] + i2ZAdjust}
                                            tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust] = AiBotUtilities.GetDistanceBetweenPositions(tLocation, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                            if tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust] > iFurthest3 then
                                                if tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust] > iFurthest2 then
                                                    if tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust] > iFurthest1 then
                                                        iFurthest3 = iFurthest2
                                                        iFurthest2 = iFurthest1
                                                        iFurthest1 = tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust]
                                                    else
                                                        iFurthest3 = iFurthest2
                                                        iFurthest2 = tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust]
                                                    end
                                                else
                                                    iFurthest3 = tiDistToEnemyBaseByXAndZ[i2XAdjust][i2ZAdjust]
                                                end
                                            end
                                        end
                                    end
                                    --Now we have worked out the 3 furthest distances, ignore any positions that are too far
                                    tbDontBuildByXAndZ = {}
                                    for i2XAdjust, tSubtable in tiDistToEnemyBaseByXAndZ do
                                        tbDontBuildByXAndZ[i2XAdjust] = {}
                                        for i2ZAdjust, iDist in tSubtable do
                                            if iDist >= iFurthest3 then
                                                tbDontBuildByXAndZ[i2XAdjust][i2ZAdjust] = true
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': oPDToSurround is at position='..repru(oPDToSurround:GetPosition())..'; iFurthest3='..iFurthest3..'; tbDontBuildByXAndZ='..repru(tbDontBuildByXAndZ)..'; tiDistToEnemyBaseByXAndZ='..repru(tiDistToEnemyBaseByXAndZ)) end
                                end
                            end
                            if not(tbDontBuildByXAndZ[iXAdjust][iZAdjust]) then
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return tTargetLocation
                            end
                        end
                    --sometimes an area might appear to be on a cliff but could still fit a wall piece
                    elseif aiBrain:CanBuildStructureAt(sWallBP, tTargetLocation) then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return tTargetLocation
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderClearingEngineersForUnitJustDamagedOrDestroyed(oUnit, iOptionalEngineerActionLimitation)
    --E.g. intended for building emergency PD where we built too close to the frontline and it got destroyed so we dont send more engineeres to their death but try and build further back
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderClearingEngineersForUnitJustDamagedOrDestroyed'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; Time='..GetGameTimeSeconds())
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            LOG(sFunctionRef..': Unit cur health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete())
        end
    end
    oUnit[refbDontIncludeAsPartCompleteBuildingForConstruction] = true
    oUnit[refiLastClearedForReclaim] = GetGameTimeSeconds()
    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
    if (iLandZone or 0) > 0 and iPlateau then
        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][oUnit:GetAIBrain().AiBotTeam]
        local tEngineersInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false then
            local tEngineersToClear = {}
            local bIgnoreBuildDistanceCheck = not(AiBotUnitInfo.IsUnitValid(oUnit))
            for iEngineer, oEngineer in tEngineersInZone do
                if AiBotUnitInfo.IsUnitValid(oEngineer) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer in zone, oENgineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Engineer assigned action='..(oEngineer[refiAssignedAction] or 'nil')) end
                    if not(iOptionalEngineerActionLimitation) or oEngineer[refiAssignedAction] == iOptionalEngineerActionLimitation then
                        local tLastOrder = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]]
                        if bDebugMessages == true then LOG(sFunctionRef..': Engineer order blueprint='..(tLastOrder[AiBotOrders.subrefsOrderBlueprint] or 'nil')..'; Orer position='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])..'; Dist to unit position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), (tLastOrder[AiBotOrders.subreftOrderPosition] or {0,0,0}))..'; Order count='..(oEngineer[AiBotOrders.refiOrderCount] or 'nil')) end
                        if tLastOrder[AiBotOrders.subrefsOrderBlueprint] == oUnit.UnitId and tLastOrder[AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= 1 and (bIgnoreBuildDistanceCheck or AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oUnit:GetPosition()) >= 2 + (oEngineer:GetBlueprint().Economy.MaxBuildDistance or 5)) then
                            --Clear engineer
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add engiener to list of engineers whose orders are to be cleared') end
                            table.insert(tEngineersToClear, oEngineer)
                        end
                    end
                end
                end
            if AiBotUtilities.IsTableEmpty(tEngineersToClear) == false then
                for iUnit, oEngineer in tEngineersToClear do
                    AiBotOrders.IssueTrackedClearCommands(oEngineer)
                end
            end
        end
    end
end

function GiveOrderForEmergencyT2Arti(HaveActionToAssign, bHaveLowMass, bHaveLowPower, iPlateau, iLandZone, tLZData, tLZTeamData, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GiveOrderForEmergencyT2Arti'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Only want to get for core base or minor zones iwth lots of mexes that have a positive mod distance
    if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; Mex count by tech='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])..'; Is team stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Is team stalling power='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; bHaveLowMass='..tostring(bHaveLowMass)..'; refbBaseInSafePosition='..tostring(tLZTeamData[AiBotMap.refbBaseInSafePosition] or false)..'; Time='..GetGameTimeSeconds()..'; Time of last T2 arti shot='..(tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 'nil')) end
    if tLZTeamData[AiBotMap.subrefLZbCoreBase] or
            ((tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4 or (tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] * 2 + tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4))) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and tLZTeamData[AiBotMap.refiModDistancePercent] > 0.05) then

        local iBPWanted = 0
        local iEnemyIndirectThreatInNearbyPlateau = 0
        local iBestEnemyRange = 0
        if tLZTeamData[AiBotMap.refbEnemiesInNearbyPlateau] then
            iEnemyIndirectThreatInNearbyPlateau, iBestEnemyRange = AiBotLand.GetNearestEnemyInOtherPlateau(iPlateau, tLZData, iTeam, true)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want emergency T2 arti, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; Friendly tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Is table of pathing to other zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]))..'; Is tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]))..'; subrefbDangerousEnemiesInAdjacentWZ='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or false)) end
        if ((tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoLongRangeEnemyDFUnits]) == false or (tLZTeamData[AiBotMap.subrefLZbCoreBase] and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.subrefiTimeOfMMLFiringNearTMDOrShield] or -100) <= 5) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5) or (tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 1 or tLZTeamData[AiBotMap.subrefMexCountByTech][2] >= 4) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (not(AiBotOverseer.bNoRushActive) or AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() <= 180 or ((not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 10 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (not(bHaveLowPower) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 250 + 75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and ((tLZTeamData[AiBotMap.subrefMexCountByTech][1] == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 12 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0))) then
            local aiBrain = ArmyBrains[tLZTeamData[AiBotMap.reftiClosestFriendlyAiBotBrainIndex]]
            local iRangeThreshold = 65
            local iEnemyLongRangeThreat = 0
            local iSearchRange = 300
            local iCurDFThreat, iCurIFThreat

            local iLowerThreatFactorDist = 180
            local iLowerThreatFactor = 0.5
            local iCurThreatFactor
            if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] < 5 then
                if tLZTeamData[AiBotMap.subrefMexCountByTech][3] <= 3 then
                    iLowerThreatFactorDist = 160
                    iSearchRange = 250
                else
                    iSearchRange = 275
                end
            end
            local iHighestIndividiualLongRangeThreat = math.min(25000, (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0))
            local iNearbyEnemyFixedShieldThreat = (tLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)


            if tLZTeamData[AiBotMap.refbBaseInSafePosition] then
                if tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= math.min(6, tLZData[AiBotMap.subrefLZOrWZMexCount]) then
                    iSearchRange = 200
                    iHighestIndividiualLongRangeThreat = iHighestIndividiualLongRangeThreat * 0.5
                else
                    iSearchRange = math.min(200, 110 + (tLZData[AiBotMap.subrefLZMaxSegX] - tLZData[AiBotMap.subrefLZMinSegX] + tLZData[AiBotMap.subrefLZMaxSegZ] - tLZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize * 0.25)
                    iHighestIndividiualLongRangeThreat = iHighestIndividiualLongRangeThreat * 0.5
                end
            end
            if aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] then
                if tLZTeamData[AiBotMap.refbBaseInSafePosition] then
                    iSearchRange = iSearchRange + 15
                    if aiBrain[AiBotOverseer.refbPrioritiseDefence] then iSearchRange = math.max(iSearchRange, 200) end
                elseif aiBrain[AiBotOverseer.refbPrioritiseDefence] then iSearchRange = iSearchRange * 1.5
                else iSearchRange = iSearchRange * 1.25
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of firebases in range empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]))..'; iSearchRange='..iSearchRange) end
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange]) == false then
                local iEnemyFirebaseThreat = 0
                for iFirebase, tPlateauAndZone in tLZTeamData[AiBotMap.subreftEnemyFirebasesInRange] do
                    iEnemyFirebaseThreat = iEnemyFirebaseThreat + math.max(1500, (AiBotMap.tAllPlateaus[tPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZone[2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefThreatEnemyStructureTotalMass] or 0))
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyFirebaseThreat after considering for firebase in tPlateauAndZone '..repru(tPlateauAndZone)..'='..iEnemyFirebaseThreat) end
                end
                if GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 0) >= 30 then
                    if aiBrain[AiBotOverseer.refbPrioritiseDefence] then
                        iEnemyLongRangeThreat = iEnemyLongRangeThreat + math.min(9000, iEnemyFirebaseThreat * 0.75)
                    else
                        iEnemyLongRangeThreat = iEnemyLongRangeThreat + math.min(6000, iEnemyFirebaseThreat * 0.5)
                    end
                else
                    iEnemyLongRangeThreat = iEnemyLongRangeThreat + iEnemyFirebaseThreat
                end
                if bDebugMessages == true then LOG(sFunctionRef..': refiTimeOurT2ArtiLastFired='..GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 0)..'; iEnemyLongRangeThreat after update for firebase='..iEnemyLongRangeThreat) end
            end

            --Only consider enemy long range threat in adjacent zones - if already in this zone then presumably too close for arti to help that much
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                local bHaveMobileLRThreatNearby = false
                for iEntry, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                    if tSubtable[AiBotMap.subrefLZTravelDist] > iSearchRange then break
                    else
                        iCurThreatFactor = 1
                        if tSubtable[AiBotMap.subrefLZTravelDist] > iLowerThreatFactorDist then iCurThreatFactor = iLowerThreatFactor end
                        local iAltLZ = tSubtable[AiBotMap.subrefLZNumber]
                        local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefLZTeamData][iTeam]
                        iCurDFThreat = 0
                        iCurIFThreat = 0
                        if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                            for iRange, iThreat in tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                                if iRange >= iRangeThreshold then
                                    iCurDFThreat = iCurDFThreat + iThreat * iCurThreatFactor
                                    iBestEnemyRange = math.max(iBestEnemyRange, iRange)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange]) == false then
                            for iRange, iThreat in tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange] do
                                if iRange >= iRangeThreshold then
                                    iCurIFThreat = iCurIFThreat + iThreat * iCurThreatFactor
                                    iBestEnemyRange = math.max(iBestEnemyRange, iRange)
                                end
                            end
                        end
                        iEnemyLongRangeThreat = iEnemyLongRangeThreat + math.max(iCurIFThreat, iCurDFThreat)
                        if not(tLZTeamData[AiBotMap.refbBaseInSafePosition]) then
                            if (tAltLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > iHighestIndividiualLongRangeThreat then
                                if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                                    bHaveMobileLRThreatNearby = false
                                    for iUnit, oUnit in tAltLZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                                        if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                            iHighestIndividiualLongRangeThreat = math.max(iHighestIndividiualLongRangeThreat, AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true))
                                        end
                                    end
                                end
                            end

                        end
                        if (tAltLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then
                            if iNearbyEnemyFixedShieldThreat > 0 or (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                                iNearbyEnemyFixedShieldThreat = iNearbyEnemyFixedShieldThreat + (tAltLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)
                            else
                                --We dont have any fixed shield threat recorded, so get the fixed mobile shields, and check just how close they are to us
                                local tEnemyFixedShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tAltLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tEnemyFixedShields) == false then
                                    for iShield, oShield in tEnemyFixedShields do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; dist='..AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; iLowerThreatFactorDist='..iLowerThreatFactorDist) end
                                        if AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) < iLowerThreatFactorDist then
                                            iNearbyEnemyFixedShieldThreat = iNearbyEnemyFixedShieldThreat + AiBotUnitInfo.GetMassCostOfUnits({ oShield }, true)
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering iAltLZ='..iAltLZ..'; iCurIFThreat='..iCurIFThreat..'; iCurDFThreat='..iCurDFThreat..'; iEnemyLongRnageThreat='..iEnemyLongRangeThreat..'; tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]='..repru(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange])..'; tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange]='..repru(tAltLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectByRange])..'; iNearbyEnemyFixedShieldThreat='..iNearbyEnemyFixedShieldThreat..'; Zone dist='..tSubtable[AiBotMap.subrefLZTravelDist]) end
                    end
                end
            end
            --Consider nearby naval threat
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                local iAdjWZ, iPond
                for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                    iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                    iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                    local tAdjWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                    if tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > 40 then
                        iEnemyLongRangeThreat = iEnemyLongRangeThreat + math.max(0, (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) - (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0))
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; subrefWZBestEnemyDFRange='..tAdjWZTeamData[AiBotMap.subrefWZBestEnemyDFRange]..'; subrefWZThreatEnemyVsSurface='..(tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0)..'; subrefWZThreatEnemySubmersible='..(tAdjWZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] or 0)..'; iEnemyLongRangeThreat after increasing for this zone if relevant='..iEnemyLongRangeThreat) end
                end
            end
            local iLongRangeFurtherAwayThreat = AiBotLand.GetFarAwayLandThreatOfLongRangeUnits(tLZData[AiBotMap.subrefMidpoint], iTeam, (not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or tLZTeamData[AiBotMap.refbBaseInSafePosition]), true) --Will just consider mobile long range units; threat is reduced if we have TML
            if iLongRangeFurtherAwayThreat > 0 then
                iBestEnemyRange = math.max(90, iBestEnemyRange) --assume enemy long range threat will be at least 90, e.g. fatboy
                --If this is a safe base and the LR threat is sub-8k (or 12k if we have decent mobile force vs enemy) and we have low mass then ignore (we already reduce the threat for fractinocomplete in the above function)
                if bDebugMessages == true then LOG(sFunctionRef..': Brain='..aiBrain.Nickname..'; iTeam='..iTeam..'; iLandSubteam='..(aiBrain.AiBotLandSubteam or 'nil')..'; iTeam='..iTeam..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] or 'nil')..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 'nil')..'; iLongRangeFurtherAwayThreat before adjustment='..iLongRangeFurtherAwayThreat) end
                if bHaveLowMass and tLZTeamData[AiBotMap.refbBaseInSafePosition] and (iLongRangeFurtherAwayThreat <= 8000 or (iLongRangeFurtherAwayThreat <= 13000 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] > 1.5 * AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide])) then iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat * 0.1
                elseif bHaveLowMass and tLZTeamData[AiBotMap.subrefLZbCoreBase] and iLongRangeFurtherAwayThreat <= 20000 and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] > 1.75 * AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] then
                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat * 0.5
                elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide] >= 2.5 * AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] then
                    iLongRangeFurtherAwayThreat = iLongRangeFurtherAwayThreat * 0.6
                end
                --Further reduction if already have 4 T2 arti, and they haven't fired in last minute, and enemy has no nearby LR threat
                if iLongRangeFurtherAwayThreat > 10000 and (not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or tLZTeamData[AiBotMap.refbBaseInSafePosition]) and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 0) >= 60 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) < 1000 and (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] or 0) < 1000 then
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] < 0.4 and AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) * 1.5 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] then
                        iLongRangeFurtherAwayThreat = math.max(10000, iLongRangeFurtherAwayThreat * math.min(0.9, 0.43 + 0.06 * tLZTeamData[AiBotMap.subrefMexCountByTech][3] + 0.02 * tLZTeamData[AiBotMap.subrefMexCountByTech][2]))
                    else
                        iLongRangeFurtherAwayThreat = math.max(10000, iLongRangeFurtherAwayThreat * math.min(0.95, (0.5 + 0.09 * tLZTeamData[AiBotMap.subrefMexCountByTech][3] + 0.03 * tLZTeamData[AiBotMap.subrefMexCountByTech][2])))
                    end
                end
            end

            iEnemyLongRangeThreat = iEnemyLongRangeThreat + iEnemyIndirectThreatInNearbyPlateau
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyLongRangeThreat after checking all zones within dist threshold='..iEnemyLongRangeThreat..'; iHighestIndividiualLongRangeThreat='..iHighestIndividiualLongRangeThreat..'; Is table of enemy T2 arti empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]))..'; iLongRangeFurtherAwayThreat='..iLongRangeFurtherAwayThreat..'; iNearbyEnemyFixedShieldThreat='..iNearbyEnemyFixedShieldThreat..'; iEnemyIndirectThreatInNearbyPlateau which is included in LR threat='..iEnemyIndirectThreatInNearbyPlateau..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiAllyMobileDFThreatNearOurSide]..'; Enemy threat='..AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]) end
            if iEnemyLongRangeThreat >= 750 or iLongRangeFurtherAwayThreat >= 750 or iHighestIndividiualLongRangeThreat > 0 or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false or iNearbyEnemyFixedShieldThreat > 0 or iEnemyIndirectThreatInNearbyPlateau > 0 or (iEnemyLongRangeThreat > 0 and aiBrain[AiBotOverseer.refbPrioritiseDefence]) then
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then

                    --Increase long range threat based on enemy T2 arti within 175 of our midpoint
                    for iT2Arti, oT2Arti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                        if AiBotUnitInfo.IsUnitValid(oT2Arti) then
                            if AiBotUtilities.GetDistanceBetweenPositions(oT2Arti:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= (oT2Arti[AiBotUnitInfo.refiIndirectRange] or 'nil') + 50 then
                                iBestEnemyRange = math.max(iBestEnemyRange, (oT2Arti[AiBotUnitInfo.refiIndirectRange] or 'nil'))
                                iEnemyLongRangeThreat = iEnemyLongRangeThreat + oT2Arti[AiBotUnitInfo.refiUnitMassCost]
                            end
                        end
                    end
                elseif iHighestIndividiualLongRangeThreat then iBestEnemyRange = math.max(iBestEnemyRange, 80)
                end



                --What is our long range threat that equals their range?
                iCurDFThreat = 0
                iCurIFThreat = 0
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange]) == false then
                    for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFByRange] do
                        if iRange >= iBestEnemyRange then iCurDFThreat = iCurDFThreat + iThreat end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange]) == false then
                    for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyMobileIndirectByRange] do
                        if iRange >= iBestEnemyRange then iCurIFThreat = iCurIFThreat + iThreat end
                    end
                end
                local iThreatWanted = math.max(iEnemyLongRangeThreat * 1.5, iHighestIndividiualLongRangeThreat * 0.75, iLongRangeFurtherAwayThreat) + math.max(iNearbyEnemyFixedShieldThreat * 2, math.min(14000, iNearbyEnemyFixedShieldThreat * 5)) - iCurDFThreat * 0.75 - iCurIFThreat
                if iNearbyEnemyFixedShieldThreat > 0 and iEnemyLongRangeThreat > 0 and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 12 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                    if iThreatWanted >= 4000 or (not(bHaveLowMass) and not(bHaveLowPower) and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] or 0) >= math.min(4, tLZData[AiBotMap.subrefLZOrWZMexCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 20 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) then
                        iThreatWanted = math.max(10000, iThreatWanted)
                    elseif iNearbyEnemyFixedShieldThreat >= 1000 or iEnemyLongRangeThreat >= 1000 then
                        iThreatWanted = math.max(4000, iThreatWanted)
                    end
                end


                if iEnemyLongRangeThreat >= 1600 then iThreatWanted = math.max(iThreatWanted, 500) end --Want 1 T2 arti if enemy has significant long rnage threat, even if we have friendly units
                if iThreatWanted > 1000 and iEnemyLongRangeThreat >= 1000 and (not(tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired]) or GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] >= 60) and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                    --If we cant path to our main base by land then reduce t2 arti to build if it hasnt fired recently
                    if bDebugMessages == true then LOG(sFunctionRef..': This island ref='..tLZData[AiBotMap.subrefLZIslandRef]..'; Island refo f closest friendly base='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase]) or 'nil')) end
                    if not(tLZData[AiBotMap.subrefLZIslandRef] == NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZTeamData[AiBotMap.reftClosestFriendlyBase])) then
                        if tLZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 then
                            iThreatWanted = math.min(iThreatWanted, 3000 + 0.3 * (iThreatWanted - 3000))
                        else
                            iThreatWanted = math.min(iThreatWanted, 1000 + 0.25*(iThreatWanted - 1000))
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Our T2 arti havent fired much and are on a dif island to main base, so significantly reducing threat wanted to '..iThreatWanted) end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                    iThreatWanted = math.max(iThreatWanted, 2 * AiBotUnitInfo.GetMassCostOfUnits(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], true))
                end
                if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then iThreatWanted = iThreatWanted * 0.75 end
                if aiBrain[AiBotOverseer.refbPrioritiseDefence] then
                    iThreatWanted = iThreatWanted * 1.5
                end

                if iThreatWanted >= 25000 then
                    if iThreatWanted >= 50000 then
                        iThreatWanted = math.min(70000, 25000 + 12500 + (iThreatWanted - 50000) * 0.2)
                    else
                        iThreatWanted = 25000 + (iThreatWanted - 25000) * 0.5
                    end
                    if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then iThreatWanted = 25000 end
                end


                if bDebugMessages == true then LOG(sFunctionRef..': iCurDFThreat='..iCurDFThreat..'; iCurIFThreat='..iCurIFThreat..'; iThreatWanted='..iThreatWanted..'; iLongRangeFurtherAwayThreat='..iLongRangeFurtherAwayThreat..'; iBestEnemyRange='..iBestEnemyRange) end
                if iThreatWanted >= 500 or (iThreatWanted > 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 18 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (aiBrain[AiBotOverseer.refbPrioritiseDefence] and not(bHaveLowMass)))) then
                    --Get friendly T2 arti threat
                    local iT2ArtiThreat = 0
                    local iT2ArtiCount = 0
                    local toT2ArtiWantingShields = {}
                    local toT2ArtiWithDownedShields = {}
                    local toPartCompleteShields = {}
                    local tT2Arti
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        tT2Arti = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedT2Arti, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tT2Arti) == false then
                            iT2ArtiThreat = AiBotUnitInfo.GetMassCostOfUnits(tT2Arti, true) --for reference, combat threat will be 60% of mass cost per getcombatthreatrating; we also exclude part-complete t2 arti from this value below
                            --If enemy has T2 arti near here, then reduce D2 arti threat by 50% of any Arti that are more than 130 away from the enemy T2 arti
                            local tNearestEnemyArtiPosition
                            if tLZTeamData[AiBotMap.subrefLZbCoreBase] and (not(bHaveLowMass) or tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false and table.getn(tT2Arti) < math.min(10, math.max(4, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 2.5)) then
                                local iClosestArtiDist = 200 --No point considering t2 arti further away than this
                                local iCurArtiDist
                                for iEnemyArti, oEnemyArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                                    if AiBotUnitInfo.IsUnitValid(oEnemyArti) then
                                        iCurArtiDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyArti:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                        if iCurArtiDist < iClosestArtiDist then
                                            iClosestArtiDist = iCurArtiDist
                                            tNearestEnemyArtiPosition = oEnemyArti:GetPosition()
                                        end
                                    end
                                end
                            end
                            for iArti, oArti in tT2Arti do
                                if oArti:GetFractionComplete() == 1 then iT2ArtiCount = iT2ArtiCount + 1
                                else iT2ArtiThreat = iT2ArtiThreat - (oArti[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oArti))
                                end
                                if oArti[AiBotBuilding.refbUnitWantsShielding] and AiBotUtilities.IsTableEmpty(oArti[AiBotBuilding.reftoShieldsProvidingCoverage]) and (oArti[refiFailedShieldConstructionCount] or 0) <= 1 then
                                    table.insert(toT2ArtiWantingShields, oArti)
                                elseif AiBotUtilities.IsTableEmpty(oArti[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                                    for iShield, oShield in oArti[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef..': Considering if oArti is shielded, oArti='..oArti.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oArti)..'; oShield='..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Shield fraciton complete='..oShield:GetFractionComplete())
                                            if oShield:GetFractionComplete() == 1 then LOG(sFunctionRef..': Shield health='..oShield.MyShield:GetHealth()) end
                                        end
                                        if not(oShield.Dead) then
                                            if oShield:GetFractionComplete() < 1 then
                                                table.insert(toPartCompleteShields, oShield)
                                            elseif oShield.MyShield:GetHealth() <= 3000 and table.getn(oArti[AiBotBuilding.reftoShieldsProvidingCoverage]) < 3 then
                                                table.insert(toT2ArtiWithDownedShields, oArti)
                                            end
                                        end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(toT2ArtiWithDownedShields) == false and AiBotUtilities.IsTableEmpty(toT2ArtiWantingShields) then toT2ArtiWantingShields = toT2ArtiWithDownedShields end
                                if tNearestEnemyArtiPosition then
                                    --Reduce threat by 50% if arti is far away from closest enemy arti
                                    if AiBotUtilities.GetDistanceBetweenPositions(oArti:GetPosition(), tNearestEnemyArtiPosition) > math.max(125, (oArti[AiBotUnitInfo.refiIndirectRange] or 0) + math.max((oArti[AiBotUnitInfo.refiIndirectAOE] or 0), 5)) then
                                        iT2ArtiThreat = iT2ArtiThreat - (oArti[AiBotUnitInfo.refiUnitMassCost] or 0) * 0.6
                                    end
                                end
                            end
                        end
                    end

                    local iTimeSinceLastFired = GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] or 0)

                    if iT2ArtiThreat >= math.max(11000, math.min(iLongRangeFurtherAwayThreat * 1.25, 30000)) then iThreatWanted = iThreatWanted * 0.8 end
                    if iT2ArtiThreat >= 2800 and tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] and GetGameTimeSeconds() - tLZTeamData[AiBotMap.refiTimeOurT2ArtiLastFired] <= 20 and tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] >= 3000 then
                        iThreatWanted = iThreatWanted + math.min(iThreatWanted, 4000)
                        if bDebugMessages == true then LOG(sFunctionRef..': Increasing t2 arti threat wanted due to firing t2 arti recently and enemy having LR arti threat, iLandZone='..iLandZone..'; iT2ArtiThreat='..iT2ArtiThreat..'; subrefiNearbyEnemyLongRangeDFThreat='..tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat]) end
                    end
                    if tLZTeamData[AiBotMap.refbBaseInSafePosition] then iThreatWanted = iThreatWanted * 0.75 end
                    if iT2ArtiThreat >= 4000 and iThreatWanted >= 4000 and iTimeSinceLastFired >= 40 then
                        iThreatWanted = 4000 + (iThreatWanted - 4000)*0.5
                        if bDebugMessages == true then LOG(sFunctionRef..': Not fired t2 arti recently so reducing threat further') end
                    end
                    local iNetThreatWanted = iThreatWanted - iT2ArtiThreat
                    iBPWanted = 240 --default
                    local bAreBuildingShieldOrTML = false
                    local iTMLBPWanted = 0
                    if tLZTeamData[AiBotMap.refbGetTMLBattery] and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbTMLBatteryMissedLots]) or iT2ArtiCount >= 6 or (iT2ArtiCount >= 3 and (AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) or table.getn(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) <= iT2ArtiCount))) then iTMLBPWanted = GetBPToAssignToBuildingTML(tLZData, tLZTeamData, iPlateau, iLandZone, iTeam, bHaveLowMass) end
                    if bDebugMessages == true then LOG(sFunctionRef..': iT2ArtiThreat='..iT2ArtiThreat..'; iThreatWanted='..iThreatWanted..'; iNetThreatWanted='..iNetThreatWanted..'; iLongRangeFurtherAwayThreat='..iLongRangeFurtherAwayThreat..'; Threat rating of all nearby enemy T2 arti='..AiBotUnitInfo.GetMassCostOfUnits(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], true)..'; iLongRangeFurtherAwayThreat='..iLongRangeFurtherAwayThreat..'; iTMLBPWanted='..(iTMLBPWanted or 'nil')) end
                    if iT2ArtiThreat > 0 and tLZTeamData[AiBotMap.refiRadarCoverage] <= math.min(60, AiBotUnitInfo.iT1RadarSize - 20) then
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                            HaveActionToAssign(refActionBuildT2Radar, 2, iBPWanted)
                        else
                            HaveActionToAssign(refActionBuildT1Radar, 1, iBPWanted * 0.65)
                        end
                    elseif AiBotUtilities.IsTableEmpty(toPartCompleteShields) == false then
                        iBPWanted = 120
                        if iT2ArtiCount >= 4 then iBPWanted = 240 end
                        local oNearestCompletionShield
                        local iNearestCompletionShield = -1
                        for iShield, oShield in toPartCompleteShields do
                            if oShield:GetFractionComplete() > iNearestCompletionShield then
                                iNearestCompletionShield = oShield:GetFractionComplete()
                                oNearestCompletionShield = oShield
                            end
                        end
                        local bInRangeOfEnemyArti = false
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) == false then
                            for iEnemyArti, oEnemyArti in tLZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] do
                                if AiBotUtilities.GetDistanceBetweenPositions(oEnemyArti:GetPosition(), oNearestCompletionShield:GetPosition()) <= oEnemyArti[AiBotUnitInfo.refiCombatRange] + 5 then
                                    bInRangeOfEnemyArti = true
                                    break
                                end
                            end
                        end
                        if not(bInRangeOfEnemyArti) and bHaveLowMass or bHaveLowPower then
                            --Only reduce buildpower if not in range of enemy t2 arti
                            iBPWanted = iBPWanted * 0.5
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will assist part complete shield='..oNearestCompletionShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestCompletionShield)..' with fraction complete='..oNearestCompletionShield:GetFractionComplete()..'; iBPWanted='..iBPWanted) end
                        HaveActionToAssign(refActionRepairUnit, 1, iBPWanted, oNearestCompletionShield)
                        if bInRangeOfEnemyArti then iBPWanted = 0 end --dont build t2 arti if we want to get shielding
                    elseif AiBotUtilities.IsTableEmpty(toT2ArtiWantingShields) == false and iT2ArtiCount >= 2 then
                        if table.getn(toT2ArtiWantingShields) >= 4 or iT2ArtiCount >= 6 then iBPWanted = 240
                        else iBPWanted = 120
                        end
                        if bHaveLowMass or bHaveLowPower then iBPWanted = iBPWanted * 0.5 end
                        local oArtiToShield = AiBotUtilities.GetNearestUnit(toT2ArtiWantingShields, tLZData[AiBotMap.subrefMidpoint])
                        if not(oArtiToShield) and iNetThreatWanted > 0 then
                            --Redundancy
                            AiBotUtilities.ErrorHandler('Have arti for P'..iPlateau..'Z'..iLandZone..' that want shielding but werent able to get one to shield - shoudlnt be possible')
                            --HaveActionToAssign(refActionBuildEmergencyArti, 2, iBPWanted, tLZData[AiBotMap.subrefMidpoint])
                        else
                            bAreBuildingShieldOrTML = true
                            local iShieldTechLevelWanted = 2
                            if (tLZTeamData[AiBotMap.refiFixedShieldT2EngiFailureCount] or 0) >= 8 then iShieldTechLevelWanted = 3 end --normal limit elsewhere is 5
                            HaveActionToAssign(refActionBuildShield, iShieldTechLevelWanted, iBPWanted, oArtiToShield)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will build shield to cover arti isntead of more arti; however will still try more arti as slightly lower priority. iShieldTechLevelWanted='..iShieldTechLevelWanted) end
                        end
                        iBPWanted = 0
                    elseif iTMLBPWanted > 0 then
                        bAreBuildingShieldOrTML = true
                        HaveActionToAssign(refActionBuildTML, 2, math.max(iBPWanted, iTMLBPWanted))
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and build TML') end
                        --Also get shielding if we have lots of TML
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTMLBatteryUnits]) == false then
                            local toTMLToShield = {}
                            for iTML, oTML in tLZTeamData[AiBotMap.reftoTMLBatteryUnits] do
                                if oTML[AiBotBuilding.refbUnitWantsShielding] and AiBotUtilities.IsTableEmpty(oTML[AiBotBuilding.reftoShieldsProvidingCoverage]) and (oTML[refiFailedShieldConstructionCount] or 0) <= 1 and AiBotUnitInfo.IsUnitValid(oTML) then
                                    table.insert(toTMLToShield, oTML)
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(toTMLToShield) == false then
                                local oTMLForShielding = AiBotUtilities.GetNearestUnit(toTMLToShield, tLZData[AiBotMap.subrefMidpoint])
                                if table.getn(toTMLToShield) >= 3 then iBPWanted = iBPWanted * 0.5 else iBPWanted = iBPWanted * 0.25 end
                                HaveActionToAssign(refActionBuildShield, 2, iBPWanted, oTMLForShielding)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will shield TML, oTMLForShielding='..oTMLForShielding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTMLForShielding)) end
                            end
                        end
                        if iT2ArtiCount > 0 then iBPWanted = 0 end
                        --Minor LZs with T2 arti - get at least 1 t2 pd or else vulnerable to enemy t1 spam; dont worry if core base though as should have other units to protect
                    elseif iT2ArtiCount >= 2 and (not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) or iT2ArtiCount >= 4) and (iT2ArtiCount >= 3 or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                        local iCurT2PDThreat = 0
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                                if iRange >= 40 then iCurT2PDThreat = iCurT2PDThreat + iThreat end
                            end
                        end
                        local iPDThreatPerArtiWanted = 200
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                            if not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) then
                                iPDThreatPerArtiWanted = 100
                            elseif tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                local iCumulativeShorterRangeThreat = 0
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] > 0 then
                                        for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                                            if iRange > 50 then break end
                                            iCumulativeShorterRangeThreat = iCumulativeShorterRangeThreat + iThreat
                                        end
                                    end
                                end
                                if iCumulativeShorterRangeThreat < iCurT2PDThreat * 0.25 then
                                    iPDThreatPerArtiWanted = 100
                                elseif iCumulativeShorterRangeThreat < iCurT2PDThreat * 0.5 then
                                    iPDThreatPerArtiWanted = 150
                                elseif iCumulativeShorterRangeThreat > iCurT2PDThreat then
                                    iPDThreatPerArtiWanted = 250
                                else
                                    --Default of 200
                                end
                            end
                        end
                        if iCurT2PDThreat < iPDThreatPerArtiWanted * iT2ArtiCount then
                            if bHaveLowMass or bHaveLowPower then iBPWanted = iBPWanted * 0.5 end
                            HaveActionToAssign(refActionBuildEmergencyPD, 2, iBPWanted, tLZData[AiBotMap.subrefMidpoint])
                            iBPWanted = 0
                        end
                    end
                    --TMD secnd builder
                    if iBPWanted > 0 then
                        --Consider TMD if enemy has significant cruiser threat nearby
                        if bDebugMessages == true then LOG(sFunctionRef..': Is reftUnitsWantingTMD empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]))) end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftUnitsWantingTMD]) == false then
                            local oArtiWantingTMD = AiBotBuilding.GetUnitWantingTMD(tLZData, tLZTeamData, iTeam, iLandZone, false, AiBotUnitInfo.refCategoryFixedT2Arti, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want TMD for T2 arti, in which case prioritise over building more t2 arti, oArtiWantingTMD='..(oArtiWantingTMD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oArtiWantingTMD) or 'nil')) end
                            if oArtiWantingTMD then
                                HaveActionToAssign(refActionBuildThirdTMD, 2, iBPWanted, oArtiWantingTMD)
                                iBPWanted = 0
                                if bDebugMessages == true then LOG(sFunctionRef..': Will get third TMD, so can get tmd for our T2 arti') end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we already ahve enough T2 arti threat, iThreatWanted='..iThreatWanted..'; iT2ArtiThreat='..iT2ArtiThreat..'; iNetThreatWanted='..iNetThreatWanted..'; HaveLowMass='..tostring(bHaveLowMass)..'; iBPWanted='..iBPWanted) end
                    if iBPWanted > 0 and (iNetThreatWanted > 0 or (iT2ArtiThreat <= 3000 and not(bHaveLowMass) and tLZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 and (iT2ArtiThreat <= 1500 or iNetThreatWanted >= 800))) and (iNetThreatWanted >= 500 or (iNetThreatWanted > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 18 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) then
                        if iNetThreatWanted <= 4000 and iT2ArtiThreat >= 1000 then
                            iBPWanted = math.min(120, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 10 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])
                            if bHaveLowMass or bHaveLowPower then iBPWanted = iBPWanted * 0.5 end
                        else
                            --Presumably up against a fatboy or are outranged and have no T2 arti so need T2 arti asap
                            iBPWanted = math.min(240, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] * 10)
                            if bHaveLowMass or bHaveLowPower then iBPWanted = iBPWanted * 0.75 end
                        end
                        if bAreBuildingShieldOrTML then iBPWanted = iBPWanted * 0.25 end

                        local oFactoryToAssistInstead
                        local bEnemyHasFatboyOrMegalith = false
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                            local tFatboyOrMegalith = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryMegalith, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])
                            if AiBotUtilities.IsTableEmpty(tFatboyOrMegalith) == false then
                                for iFatboy, oFatboy in tFatboyOrMegalith do
                                    if AiBotUnitInfo.IsUnitValid(oFatboy) and oFatboy:GetFractionComplete() >= 0.75 then
                                        bEnemyHasFatboyOrMegalith = true
                                        break
                                    end
                                end
                            end
                            if not(bEnemyHasFatboyOrMegalith) and ((tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] == 2) then
                                --At high mass levels want to build t2 arti anyway instead of assisting a factory
                                if bHaveLowMass or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 12 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 16 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (tLZTeamData[AiBotMap.subrefMexCountByTech][3] or 0) == 0)) then
                                    local tLandHQs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandHQ - categories.TECH1, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    if AiBotUtilities.IsTableEmpty(tLandHQs) == false then
                                        for iFactory, oFactory in tLandHQs do
                                            if not(oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                                                if oFactory[AiBotFactory.refiTotalBuildCount] <= 10 or (oFactory[AiBotFactory.refiTotalBuildCount] <= 20 and AiBotConditions.GetLifetimeBuildCount(oFactory:GetAIBrain(), AiBotUnitInfo.refCategoryMML) <= 15) then
                                                    oFactoryToAssistInstead = oFactory
                                                    break
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if not(oFactoryToAssistInstead) and not(bEnemyHasFatboyOrMegalith) and iBestEnemyRange <= 80 then
                            --If we have t3 factory nearby then assist that
                            local tLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if AiBotUtilities.IsTableEmpty(tLandFactories) == false then
                                for iFactory, oFactory in tLandFactories do
                                    if not(oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder]) or GetGameTimeSeconds() - oFactory[AiBotFactory.refiTimeSinceLastFailedToGetOrder] >= 10 then
                                        if oFactory[AiBotFactory.refiTotalBuildCount] <= 20 then
                                            oFactoryToAssistInstead = oFactory
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to assist land factory for MML, or get T2 arti, bEnemyHasFatboyOrMegalith='..tostring(bEnemyHasFatboyOrMegalith)..'; oFactoryToAssistInstead='..(oFactoryToAssistInstead.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryToAssistInstead) or 'nil')) end
                        if oFactoryToAssistInstead then
                            HaveActionToAssign(refActionAssistLandFactory, 1, iBPWanted, oFactoryToAssistInstead)
                        else
                            --adjust location to build if we already have 3 t2 arti so we build towards enemy
                            local tLocationToBuild
                            if iT2ArtiCount >= 3 and not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                                for iDistanceToTry = 20, 40, 10 do
                                    tLocationToBuild = AiBotUtilities.MoveInDirection(tLZData[AiBotMap.subrefMidpoint], AiBotUtilities.GetAngleFromAToB(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase]), iDistanceToTry, true, false)
                                    if not(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLocationToBuild) == iPlateau) and GetSurfaceHeight(tLocationToBuild[1], tLocationToBuild[3]) <= GetTerrainHeight(  tLocationToBuild[1], tLocationToBuild[3]) then
                                        tLocationToBuild = {tLZData[AiBotMap.subrefMidpoint][1]. tLZData[AiBotMap.subrefMidpoint][2]. tLZData[AiBotMap.subrefMidpoint][3]}
                                        break
                                    end
                                end
                                if not(tLocationToBuild) then tLocationToBuild = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]} end
                            else
                                tLocationToBuild = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                            end
                            HaveActionToAssign(refActionBuildEmergencyArti, 2, iBPWanted, tLocationToBuild)
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to build emergency arti, iBPWanted='..iBPWanted) end
                        end

                    end
                end

            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderBuildingMassFabOrGateway(iTeam, iZone, tLZTeamData, HaveActionToAssign, bWantMorePower, iOptionalMassFabMod, bDontConsiderGateway)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderBuildingMassFabOrGateway'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --iOptionalMassFabMod - e.g. set to 2 to build double the normal number of mass fabs wanted

    local bBuiltSomething = false
    --Dont try and build anything if we have 2+ t2 mexes in this zone we could be upgrading
    if tLZTeamData[AiBotMap.subrefMexCountByTech][2] < 2 then
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) > 0 then
            local iExistingT3MassFabs = 0
            local iUnderConstructionT3MassFabs = 0
            local tExistingMassFabs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMassFab * categories.TECH3, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty( tExistingMassFabs) == false then
                for iUnit, oUnit in tExistingMassFabs do
                    if oUnit:GetFractionComplete() < 1 then iUnderConstructionT3MassFabs = iUnderConstructionT3MassFabs + 1
                    else iExistingT3MassFabs = iExistingT3MassFabs + 1
                    end
                end
            end
            local iMaxMassFabsWanted = 1
            local iModFactor = AiBotOverseer.iMassFabRatio * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering for zone '..iZone..' at time='..GetGameTimeSeconds()) end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] <= 8 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or AiBotMap.bIsLowMexMap or AiBotOverseer.IsTeamBoomMode(iTeam) or iModFactor >= math.max(1.2, 1 + 0.1 * iExistingT3MassFabs) then
                iMaxMassFabsWanted = 4
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then
                    --If enemy has multiple T3 arti or novax or gameender then reduce to 1
                    local iEnemyCount = 0
                    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) then
                        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                            if oUnit:GetFractionComplete() >= 0.35 then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oUnit.UnitId) then
                                    iEnemyCount = iEnemyCount + 3
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId) then
                                    iEnemyCount = iEnemyCount + 1
                                else
                                    iEnemyCount = iEnemyCount + 0.5
                                end
                            end
                        end
                    end
                    iMaxMassFabsWanted = math.max(0, iMaxMassFabsWanted - iEnemyCount)
                    if bDebugMessages == true then LOG(sFunctionRef..': Are defending against arti, imaxMassFabsWanted='..iMaxMassFabsWanted..'; iEnemyCount='..iEnemyCount) end
                end
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] then iMaxMassFabsWanted = 0
            end
            if iModFactor >= 1.5 or AiBotMap.bIsLowMexMap or AiBotOverseer.IsTeamBoomMode(iTeam) then
                iMaxMassFabsWanted = math.max(2,iMaxMassFabsWanted * ((iModFactor - 1)*0.5 + 1))
                if AiBotOverseer.IsTeamBoomMode(iTeam) then iMaxMassFabsWanted = iMaxMassFabsWanted + 1 end
            end
            if iOptionalMassFabMod then iMaxMassFabsWanted = iMaxMassFabsWanted * iOptionalMassFabMod end
            --If recently stalled E and relatively early game then reduce
            if GetGameTimeSeconds() <= 2700 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] <= 500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.3 * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) then
                if bWantMorePower or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] and (GetGameTimeSeconds() -  AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastEnergyStall] <= 90 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] < 600 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiGrossEnergyWhenStalled])) then
                    iMaxMassFabsWanted = math.max(0, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] - 1)
                else
                    iMaxMassFabsWanted = iMaxMassFabsWanted - 1
                end
            end
            if iMaxMassFabsWanted > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 16 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.8 * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) then
                iMaxMassFabsWanted = math.min(iMaxMassFabsWanted, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] + 1)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iExistingT3MassFabs='..iExistingT3MassFabs..'; iMaxMassFabsWanted='..iMaxMassFabsWanted..'; iUnderConstructionT3MassFabs='..iUnderConstructionT3MassFabs) end
            local iBPWanted = 0
            if iExistingT3MassFabs < iMaxMassFabsWanted or iUnderConstructionT3MassFabs > 0 then
                iBPWanted = 90
                if bWantMorePower then iBPWanted = 45 end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.75 end
                HaveActionToAssign(refActionBuildT3MassFab, 3, iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': iBpWanted for mass fabs='..iBPWanted) end
                bBuiltSomething = true
            elseif not(bDontConsiderGateway) and (AiBotMap.bIsLowMexMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbEnemyGettingFabsOrRAS] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= math.max(3, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] + 1) or (AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() >= 60)) then
                local tQuantumGateways = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local iExistingGateways = 0
                if AiBotUtilities.IsTableEmpty( tQuantumGateways) == false then
                    for iUnit, oUnit in tQuantumGateways do
                        if oUnit:GetFractionComplete() == 1 then
                            iExistingGateways = iExistingT3MassFabs + 1
                        end
                    end
                end
                if iExistingGateways == 0 then
                    iBPWanted = 70
                    if bWantMorePower then iBPWanted = 35 end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.7 end
                    HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have enough mass fabs but want quantum gateway, iBPWanted='..iBPWanted) end
                    bBuiltSomething = true
                end
                --LOUD - still try and build mass fab so income grows over time either way as harder to close out the game
            end
            if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and not(bBuiltSomething) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= 0.3 then
                iBPWanted = 30
                if not(bWantMorePower) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then iBPWanted = 60 end
                HaveActionToAssign(refActionBuildT3MassFab, 3, iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': In LOUD/QUIET so will build more mass fabs given not defending against t3 arti') end
            end
        elseif not(bDontConsiderGateway) then
            --Unit cap - only get gateway if we dont have one (or are overflowing mass and is LOUD or QUIET), and dont get more mass fabs
            local iBPWanted
            local tQuantumGateways = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryQuantumGateway, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            local iExistingGateways = 0
            if AiBotUtilities.IsTableEmpty( tQuantumGateways) == false then
                for iUnit, oUnit in tQuantumGateways do
                    if oUnit:GetFractionComplete() == 1 then
                        iExistingGateways = iExistingGateways + 1
                    end
                end
            end
            if iExistingGateways == 0 or ((((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= -1 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) >= 0 or iExistingGateways == 1)) or (AiBotUtilities.bLoudModActive and iExistingGateways < 2)) and (tLZTeamData[AiBotMap.subrefiTimeLastWantSACUForExp] and iExistingGateways <= 5 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.8 and (iExistingGateways < 4 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.95 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryFactory) >= 12)))) then
                iBPWanted = 70
                if bWantMorePower then iBPWanted = 35 end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass] then iBPWanted = iBPWanted * 0.7 end
                HaveActionToAssign(refActionBuildQuantumGateway, 3, iBPWanted)
                if bDebugMessages == true then LOG(sFunctionRef..': Unit cap where want quantum gateway, iBPWanted='..iBPWanted) end
                bBuiltSomething = true --(for completeness in case we add more code later, currently wont matter if got to here)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckAndClearEngineersConstructingTargetUnit(oUnitBeingReclaimed, tLZTeamData, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckAndClearEngineersConstructingTargetUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Intended for if we have given engineers an order to reclaim a unit, although in theory could use for other things
    if bDebugMessages == true then LOG(sFunctionRef..': Considering if there are any engineers building unit '..oUnitBeingReclaimed.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitBeingReclaimed)..'; oUnitBeingReclaimed[refbDontIncludeAsPartCompleteBuildingForConstruction]='..tostring(oUnitBeingReclaimed[refbDontIncludeAsPartCompleteBuildingForConstruction] or false)..'; oUnitBeingReclaimed[refiLastClearedForReclaim]='..(oUnitBeingReclaimed[refiLastClearedForReclaim] or 'nil')) end
    if not(oUnitBeingReclaimed[refbDontIncludeAsPartCompleteBuildingForConstruction]) or GetGameTimeSeconds() - (oUnitBeingReclaimed[refiLastClearedForReclaim] or 0) >= 10 then
        oUnitBeingReclaimed[refbDontIncludeAsPartCompleteBuildingForConstruction] = true
        oUnitBeingReclaimed[refiLastClearedForReclaim] = GetGameTimeSeconds()
        local tEngisInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if bDebugMessages == true then LOG(sFunctionRef..': Will cycle through every engineer in zone and clear if it is building or repariing the unit we want to reclaim, is table of engis in zone empty='..tostring(AiBotUtilities.IsTableEmpty(tEngisInZone))) end
        if AiBotUtilities.IsTableEmpty(tEngisInZone) == false then
            for iEngi, oEngi in tEngisInZone do
                if AiBotUnitInfo.IsUnitValid(oEngi) then
                    if ((oEngi:IsUnitState('Repairing') or oEngi:IsUnitState('Building')) and oEngi:GetFocusUnit() == oUnitBeingReclaimed) or (oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] == oUnitBeingReclaimed and (oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueRepair or oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGuard)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Cleearing engineer from building a unit since we are trying to reclaim that same unit, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)) end
                        AiBotOrders.IssueTrackedClearCommands(oEngi)
                    end
                end
            end
        end
        --Check if the unit is in the same zone; if its in a dif zone then  check engineers in that zone too
        local iUnitPlateau, iUnitLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnitBeingReclaimed:GetPosition())
        if bDebugMessages == true then LOG(sFunctionRef..': iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitLandZone='..(iUnitLandZone or 'nil')) end
        if not(iUnitPlateau == iPlateau and iUnitLandZone == iLandZone) and (iUnitPlateau or 0) > 0 and (iUnitLandZone or 0) > 0 then
            local iTeam = oUnitBeingReclaimed:GetAIBrain().AiBotTeam
            local tUnitLZTeamData = AiBotMap.tAllPlateaus[iUnitPlateau][AiBotMap.subrefPlateauLandZones][iUnitLandZone][AiBotMap.subrefLZTeamData][iTeam]
            local tEngisInUnitZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tUnitLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of units in unit zone empty='..tostring(AiBotUtilities.IsTableEmpty(tEngisInUnitZone))) end
            if AiBotUtilities.IsTableEmpty(tEngisInUnitZone) == false then
                for iEngi, oEngi in tEngisInUnitZone do
                    if AiBotUnitInfo.IsUnitValid(oEngi) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy engineer '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Unit state='..AiBotUnitInfo.GetUnitState(oEngi)..'; Last order='..reprs(oEngi[AiBotOrders.reftiLastOrders][1])) end
                        if ((oEngi:IsUnitState('Repairing') or oEngi:IsUnitState('Building')) and oEngi:GetFocusUnit() == oUnitBeingReclaimed) or (oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] == oUnitBeingReclaimed and (oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueRepair or oEngi[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGuard)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Cleearing engineer from building a unit in unit zone since we are trying to reclaim that same unit, oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)) end
                            AiBotOrders.IssueTrackedClearCommands(oEngi)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TrackEngineerWithHighReclaimOrder(oEngineer, oWreck, iMassAbortThreshold)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TrackEngineerWithHighReclaimOrder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Flag that special micro is active so we dont get given other orders
    AiBotMicro.TrackTemporaryUnitMicro(oEngineer, 0)
    local iTeam = oEngineer:GetAIBrain().AiBotTeam
    local bRunFromEnemy = false
    local iEngiBuildRange = oEngineer:GetBlueprint().Economy.MaxBuildDistance or 5
    if bDebugMessages == true then LOG(sFunctionRef..': Just before start of loop for oEngineer='..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; oWreck.MaxMassReclaim='..(oWreck.MaxMassReclaim or 'nil')) end
    while AiBotUnitInfo.IsUnitValid(oEngineer) and oWreck.MaxMassReclaim >= iMassAbortThreshold and not(oWreck:BeenDestroyed()) do
        --If reclaiming then ignore everything
        if not(oEngineer:IsUnitState('Reclaiming')) then
            bRunFromEnemy = false
            --Check for enemies that mean we want to abort
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oEngineer:GetPosition())
            if iPlateauOrZero and iLandOrWaterZone then
                local tLZOrWZData
                local tLZOrWZTeamData
                local tEnemiesToSearch
                if iPlateauOrZero > 0 then
                    tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                    tLZOrWZTeamData  = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    tEnemiesToSearch = tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]
                else
                    --Water zone
                    tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                    tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    tEnemiesToSearch = tLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies]
                end
                if AiBotUtilities.IsTableEmpty(tEnemiesToSearch) == false then
                    bRunFromEnemy = AiBotConditions.CloseToEnemyUnit(oEngineer:GetPosition(), tEnemiesToSearch, 3, iTeam, true, nil, nil, oEngineer)
                    if bDebugMessages == true then LOG(sFunctionRef..': bRunFromEnemy='..tostring(bRunFromEnemy))
                        if bRunFromEnemy then LOG(sFunctionRef..': Dist to closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oEngineer[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition())..'; Engi build rnage='..iEngiBuildRange) end
                    end

                end
                if bRunFromEnemy then
                    if oEngineer[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck] and AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oEngineer[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck]:GetPosition()) <= iEngiBuildRange then
                        AiBotOrders.IssueTrackedReclaim(oEngineer, oEngineer[AiBotUnitInfo.refoClosestEnemyFromLastCloseToEnemyUnitCheck], false, 'SpReclEn', true)
                    else
                        AiBotOrders.IssueTrackedMove(oEngineer, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, 'SpReclRTB', true)
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Proceeding with reclaim order') end
                    AiBotOrders.IssueTrackedReclaim(oEngineer, oWreck, false, 'SpReclR', true)
                end
            else
                AiBotOrders.UpdateRecordedOrders(oEngineer)
                if oEngineer[AiBotOrders.refiOrderCount] == 0 then
                    AiBotOrders.IssueTrackedReclaim(oEngineer, oWreck, false, 'SpReclBR', true)
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(AiBotLand.iTicksPerLandCycle)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': About to recheck, Is engineer valid='..tostring(AiBotUnitInfo.IsUnitValid(oEngineer))..'; Reclaim='..(oWreck.MaxMassReclaim or 'nil')..'; oWreck.IsDestroyed==nil='..tostring(oWreck.IsDestroyed==nil)..'; Time='..GetGameTimeSeconds()) end
    end
    --Clear engi incase it is far away from the reclaim target
    if AiBotUnitInfo.IsUnitValid(oEngineer) then
        if not(oEngineer:IsUnitState('Reclaiming')) then AiBotOrders.IssueTrackedClearCommands(oEngineer) end
        if oEngineer[AiBotUnitInfo.refbSpecialMicroActive] then
            oEngineer[AiBotUnitInfo.refbSpecialMicroActive] = false
            ForkThread(AiBotMicro.ForkedResetMicroFlag, oEngineer, 0.01) --redundancy
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished clearing commands and micro status from engineer, time='..GetGameTimeSeconds()) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HighValueReclaimOrder(iTeam, oWreck, tPosition)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HighValueReclaimOrder'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPosition)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iTeam='..iTeam..'; tPosition='..repru(tPosition)..'; Wreck mass value='..(oWreck.MaxMassReclaim or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if iPlateauOrZero and iLandOrWaterZone then
        local tLZOrWZData
        local tLZOrWZTeamData
        if iPlateauOrZero > 0 then
            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
            tLZOrWZTeamData  = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        else
            --Water zone
            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
        end
        --Ignore if mod dist means it is close to enemy base
        if bDebugMessages == true then LOG(sFunctionRef..': Mod dist%='..(tLZOrWZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; Plateau of nearest friendly base='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) or 'nil')..'; Enemy combat='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Dist to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tPosition, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
        if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 or (AiBotMap.iMapSize <= 512 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.8) then
            --Ignore if dif plateau to our closest base, or closest base is too far away
            if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) == iPlateauOrZero and tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 100000 and AiBotUtilities.GetDistanceBetweenPositions(tPosition, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 500 then
                --Check enemy doesnt still have a large army here (taking into account that the threat values may not have updated yet)
                local iEnemyDFValue = 0
                if iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                    iEnemyDFValue = AiBotUnitInfo.GetMassCostOfUnits(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], true)
                elseif iPlateauOrZero == 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                    iEnemyDFValue = AiBotUnitInfo.GetMassCostOfUnits(tLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies], true)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyDFValue='..iEnemyDFValue..'; Ally LZ combat='..(tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)..'; Ally WZ combat='..(tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0)) end
                if iEnemyDFValue < 20000 or (tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) >= 10000 or (tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or 0) >= 10000 then
                    --Get an engineer from the nearest base
                    local tNearestBaseLZData, tNearestBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], true, iTeam)
                    if tNearestBaseLZTeamData and AiBotUtilities.IsTableEmpty(tNearestBaseLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local oEngineerToTryAndReclaim
                        local tFriendlyEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tNearestBaseLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyEngineers))) end
                        if AiBotUtilities.IsTableEmpty(tFriendlyEngineers) == false then
                            local iHighestPriority = 0
                            local iHighestTech = 0
                            local iCurTech
                            for iEngi, oEngi in tFriendlyEngineers do
                                if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oEngi) then LOG(sFunctionRef..': Considering oEngi='..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..'; Primary builder='..tostring(oEngi[refbPrimaryBuilder] or false)..'; % complete='..oEngi:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oEngi)..'; Special micro active='..tostring(oEngi[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Priority='..(oEngi[refiAssignedActionPriority] or 'nil')..'; Tech level='..AiBotUnitInfo.GetUnitTechLevel(oEngi)) end

                                if AiBotUnitInfo.IsUnitValid(oEngi) and not(oEngi[refbPrimaryBuilder]) and oEngi:GetFractionComplete() == 1 and not(oEngi:IsUnitState('Attached')) and not(oEngi[AiBotUnitInfo.refbSpecialMicroActive]) then
                                    --Get the highest tech engi, and then the highest number for priority
                                    iCurTech = AiBotUnitInfo.GetUnitTechLevel(oEngi)
                                    if iCurTech > iHighestTech then iHighestTech = iCurTech iHighestPriority = 0 end
                                    if (oEngi[refiAssignedActionPriority] or 1000) > iHighestPriority then
                                        iHighestPriority = (oEngi[refiAssignedActionPriority] or 1000)
                                        oEngineerToTryAndReclaim = oEngi
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have a new highest priority engi to give the order to') end
                                    end
                                end
                            end
                        end
                        if oEngineerToTryAndReclaim then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            TrackEngineerWithHighReclaimOrder(oEngineerToTryAndReclaim, oWreck, 1000)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetStartSearchPositionForTorpLauncherOrNilForDefault(tWZTeamData, tWZData, iWaterZone, iPond)
    --Returns nil if want to go with default logic
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetStartSearchPositionForTorpLauncherOrNilForDefault'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    local tPreferredLocation
    if bDebugMessages == true then LOG(sFunctionRef..': Near start for iWaterZone='..iWaterZone..'; in iPond='..iPond..'; Is subreftoLZOrWZAlliedUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; at time='..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tFriendlyFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFriendlyFactories) == false then
            local oFactoryToBuildNear
            local iBestFactoryHealth = -1
            local iCurHealthPercent
            for iFactory, oFactory in tFriendlyFactories do
                if oFactory:GetFractionComplete() == 1 then
                    iCurHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oFactory)
                    if iCurHealthPercent > iBestFactoryHealth or (iCurHealthPercent == iBestFactoryHealth and not(oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond]) and (oFactory[AiBotFactory.refbPrimaryFactoryForIslandOrPond] or (AiBotUtilities.GetDistanceBetweenPositions(oFactory:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase]) < AiBotUtilities.GetDistanceBetweenPositions(oFactoryToBuildNear:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase]))))  then
                        iBestFactoryHealth = iCurHealthPercent
                        oFactoryToBuildNear = oFactory
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oFactoryToBuildNear='..(oFactoryToBuildNear.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryToBuildNear) or 'nil')..'; subrefWZTThreatAllyCombatTotal='..tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal]) end
            if oFactoryToBuildNear then
                tPreferredLocation = oFactoryToBuildNear:GetPosition()
                --If lack significant threat in this WZ then build behind naval fac
                if tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] <= 1600 then
                    --Move away from nearest enemy base, provided still in same zone
                    local iAngleFromEnemyBase = AiBotUtilities.GetAngleFromAToB(tWZTeamData[AiBotMap.reftClosestEnemyBase], oFactoryToBuildNear:GetPosition())
                    local bCampaignMap = AiBotMap.bIsCampaignMap
                    for iAngleAdjust = 0, 90, 30 do
                        for iAngleMod = -1, 1, 2 do
                            if iAngleAdjust == 0 and iAngleMod == 1 then break end
                            local tPotentialAltPosition = AiBotUtilities.MoveInDirection(oFactoryToBuildNear:GetPosition(), iAngleFromEnemyBase + iAngleAdjust * iAngleMod, 8, true, false, bCampaignMap)
                            if tPotentialAltPosition and NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, tPotentialAltPosition) == iPond then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build away from enemy base so a bit behind our naval factory') end
                                tPreferredLocation = {tPotentialAltPosition[1], tPotentialAltPosition[2], tPotentialAltPosition[3]}
                                break
                            end
                        end
                    end
                end
                --If this would be in firing range of an enemy then abort and go with default logic (that builds torp launcher by the engineers)
                if tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 30 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                    local iCurEnemyRange
                    for iEnemy, oEnemy in tWZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                        iCurEnemyRange = math.max(oEnemy[AiBotUnitInfo.refiCombatRange], (oEnemy[AiBotUnitInfo.refiAntiNavyRange] or 0))
                        if iCurEnemyRange > 0 and not(oEnemy.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), tPreferredLocation) <= iCurEnemyRange + 2 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Building here puts us in range of oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' so will clear preferred location') end
                            tPreferredLocation = nil
                            break
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tPreferredLocation if any='..repru(tPreferredLocation)) end
    return tPreferredLocation
end
